-- ========================== FUNCTIONS ===========================
IF OBJECT_ID(N'[proj].[fn_GetJobBudgetState]') IS NOT NULL DROP FUNCTION [proj].[fn_GetJobBudgetState];
GO
-- Returns one of 'NONE' / 'DRAFT' / 'APPROVED' based on the current revision
-- (the one with IsCurrent=1). Falls back to MAX(RvNo) for safety if the
-- IsCurrent flag has drifted. NEVER throws — used in hot transactional paths.
CREATE   FUNCTION proj.fn_GetJobBudgetState (@JobId NVARCHAR(50))
RETURNS NVARCHAR(20)
AS
BEGIN
    IF NOT EXISTS (SELECT 1 FROM proj.TBL_JOB_BUDGET WHERE JobId = @JobId)
        RETURN N'NONE';

    DECLARE @CurrentRv INT = (
        SELECT TOP 1 RvNo FROM proj.TBL_JOB_BUDGET
        WHERE JobId = @JobId AND ISNULL(IsCurrent, 0) = 1
        ORDER BY RvNo DESC
    );
    IF @CurrentRv IS NULL
        SET @CurrentRv = (SELECT MAX(RvNo) FROM proj.TBL_JOB_BUDGET WHERE JobId = @JobId);

    IF EXISTS (SELECT 1 FROM proj.TBL_JOB_BUDGET
               WHERE JobId = @JobId AND RvNo = @CurrentRv AND IsApproved = 1)
        RETURN N'APPROVED';

    RETURN N'DRAFT';
END;
GO

IF OBJECT_ID(N'[proj].[fn_IsJobLocked]') IS NOT NULL DROP FUNCTION [proj].[fn_IsJobLocked];
GO
-- Align lock semantics with TBL_JOB_STATUS.IsClosed so Freezed (3) blocks too.
-- Earlier we agreed "no further transactions on a Freezed job until revised";
-- the existing sp_CheckJobOpenForTransactions already encodes that.
CREATE   FUNCTION proj.fn_IsJobLocked (@JobId NVARCHAR(50))
RETURNS BIT
AS
BEGIN
    DECLARE @Locked BIT = 0;
    SELECT @Locked = ISNULL(js.IsClosed, 0)
    FROM   proj.TBL_JOB j
    JOIN   proj.TBL_JOB_STATUS js ON js.JobStatusId = j.JobStatusId
    WHERE  j.JobId = @JobId;
    RETURN @Locked;
END;
GO

IF OBJECT_ID(N'[proj].[fn_ToBase]') IS NOT NULL DROP FUNCTION [proj].[fn_ToBase];
GO

CREATE   FUNCTION proj.fn_ToBase
(
    @Amount DECIMAL(18,4),
    @Rate   DECIMAL(18,6)
)
RETURNS DECIMAL(18,2)
AS
BEGIN
    -- Canonical conversion: base(AED) = original amount * stored exchange rate.
    -- Stored rate means "1 unit of the transaction currency = @Rate base units".
    -- Base currency (AED) has rate 1, so this is a no-op for base-currency rows.
    -- A NULL or zero rate is treated as 1 (defensive; posting paths validate rate>0).
    RETURN ISNULL(@Amount, 0) * ISNULL(NULLIF(@Rate, 0), 1);
END
GO

-- ============================ VIEWS =============================
IF OBJECT_ID(N'[proj].[vw_AlertJobBudget]') IS NOT NULL DROP VIEW [proj].[vw_AlertJobBudget];
GO

CREATE VIEW proj.vw_AlertJobBudget AS
SELECT
    j.JobId,
    j.ProjectName,
    c.CustomerName,
    ROUND(ISNULL(jf.OrderValue, 0) * ISNULL(j.JobExcRate, 1), 2)        AS OrderValue,
    ISNULL(budget.TotalBudget, 0)                                         AS TotalBudget,
    ISNULL(jf.TotalExpenses, 0)                                           AS ActualCost,
    ISNULL(committed.CommittedCost, 0)                                    AS CommittedCost,
    ISNULL(committed.CommittedCost, 0) - ISNULL(budget.TotalBudget, 0)   AS CommittedVariance,
    ISNULL(jf.TotalExpenses, 0) - ISNULL(budget.TotalBudget, 0)          AS BudgetVariance,
    CASE
        WHEN ISNULL(budget.TotalBudget, 0) > 0
        THEN CAST(
            ((ISNULL(committed.CommittedCost, 0) - ISNULL(budget.TotalBudget, 0))
             / NULLIF(budget.TotalBudget, 0)) * 100
            AS DECIMAL(10,2))
        ELSE 0
    END                                                                   AS CommittedVariancePct,
    ROUND(ISNULL(jf.OrderValue, 0) * ISNULL(j.JobExcRate, 1), 2)
        - ISNULL(jf.TotalExpenses, 0)                                     AS GrossMargin,
    CASE
        WHEN ROUND(ISNULL(jf.OrderValue, 0) * ISNULL(j.JobExcRate, 1), 2) > 0
        THEN CAST(
            ((ROUND(ISNULL(jf.OrderValue, 0) * ISNULL(j.JobExcRate, 1), 2) - ISNULL(jf.TotalExpenses, 0))
             / NULLIF(ROUND(ISNULL(jf.OrderValue, 0) * ISNULL(j.JobExcRate, 1), 2), 0)) * 100
            AS DECIMAL(10, 2))
        ELSE 0
    END                                                                   AS MarginPct,
    CAST(j.JobDate AS DATE)                                               AS JobDate
FROM proj.TBL_JOB j
LEFT JOIN proj.TBL_CUSTOMER c ON c.CustomerId = j.CustomerId
LEFT JOIN proj.TBL_JOB_FINANCE jf ON jf.JobId = j.JobId
LEFT JOIN (
    SELECT JobId,
           SUM(ISNULL(AmountInBaseCurrency,
               proj.fn_ToBase(ISNULL(BudgetedAmount,0), ISNULL(ExchangeRate,1)))) AS TotalBudget
    FROM proj.TBL_JOB_BUDGET
    WHERE IsCurrent = 1
    GROUP BY JobId
) budget ON budget.JobId = j.JobId
LEFT JOIN (
    SELECT
        po.JobId,
        SUM(pol.OrderedQty * pol.UnitPrice * po.ExchangeRate) AS CommittedCost
    FROM proj.TBL_PURCHASE_ORDER po
    JOIN proj.TBL_PURCHASE_ORDER_LINE pol ON pol.PoId = po.PoId AND pol.IsActive = 1
    WHERE po.IsActive = 1
      AND po.Status NOT IN ('Cancelled', 'Draft')
      AND po.JobId IS NOT NULL
    GROUP BY po.JobId
) committed ON committed.JobId = j.JobId
WHERE j.CompletedDate IS NULL
  AND j.CancelledDate IS NULL
  AND (
      ISNULL(committed.CommittedCost, 0) > ISNULL(budget.TotalBudget, 0)
      OR ISNULL(jf.TotalExpenses, 0) > ISNULL(budget.TotalBudget, 0)
      OR ROUND(ISNULL(jf.OrderValue, 0) * ISNULL(j.JobExcRate, 1), 2) - ISNULL(jf.TotalExpenses, 0) < 0
  );
GO

