IF OBJECT_ID(N'[proj].[vw_AlertOverdueInvoices]') IS NOT NULL DROP VIEW [proj].[vw_AlertOverdueInvoices];
GO
CREATE   VIEW proj.vw_AlertOverdueInvoices AS
SELECT
    c.CustomerId, c.CustomerCode, c.CustomerName,
    i.InvoiceId, i.InvoiceNo,
    CAST(i.InvoiceDate AS DATE) AS InvoiceDate,
    CAST(i.DueDate     AS DATE) AS DueDate,
    i.TotalAmount AS InvoiceAmount,
    i.TotalAmount - ROUND((COALESCE(rv.RvPaid,0) + COALESCE(cn.CnPaid,0)) / NULLIF(i.ExchangeRate,0), 2) AS OutstandingAmount,
    DATEDIFF(DAY, i.DueDate, GETDATE()) AS DaysOverdue,
    CASE
        WHEN DATEDIFF(DAY, i.DueDate, GETDATE()) <= 30 THEN '1-30'
        WHEN DATEDIFF(DAY, i.DueDate, GETDATE()) <= 60 THEN '31-60'
        WHEN DATEDIFF(DAY, i.DueDate, GETDATE()) <= 90 THEN '61-90'
        ELSE '90+'
    END AS AgingBucket
FROM proj.TBL_INVOICE i
JOIN proj.TBL_CUSTOMER c ON c.CustomerId = i.CustomerId
LEFT JOIN (
    SELECT a.InvoiceId, SUM(CASE WHEN a.IsActive=1 THEN a.AllocatedAmount ELSE 0 END) AS RvPaid
    FROM proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
    JOIN proj.TBL_RECEIPT_VOUCHER rv ON a.RvId = rv.RvId
    WHERE rv.Status = 'Approved' AND rv.IsActive = 1 GROUP BY a.InvoiceId
) rv ON rv.InvoiceId = i.InvoiceId
LEFT JOIN (
    SELECT a.InvoiceId, SUM(CASE WHEN a.IsActive=1 THEN a.AllocatedAmount ELSE 0 END) AS CnPaid
    FROM proj.TBL_CREDIT_NOTE_ALLOCATION a
    JOIN proj.TBL_CREDIT_NOTE cn ON a.CnId = cn.CnId
    WHERE cn.Status = 'Approved' AND cn.IsActive = 1 GROUP BY a.InvoiceId
) cn ON cn.InvoiceId = i.InvoiceId
WHERE i.IsActive = 1
  AND i.Status NOT IN ('Draft','Cancelled')
  AND i.DueDate IS NOT NULL
  AND i.DueDate < CAST(GETDATE() AS DATE)
  AND i.TotalAmount * i.ExchangeRate > COALESCE(rv.RvPaid,0) + COALESCE(cn.CnPaid,0);
GO

IF OBJECT_ID(N'[proj].[vw_AlertOverStock]') IS NOT NULL DROP VIEW [proj].[vw_AlertOverStock];
GO
CREATE   VIEW proj.vw_AlertOverStock AS
SELECT i.ItemId, i.ItemCode, i.ItemName,
       u.UomCode AS UOM,
       id.MinStockLevel, id.ReorderLevel, id.MaxStockLevel,
       ISNULL(sb.QtyOnHand,0) AS QtyOnHand,
       ISNULL(sb.QtyOnHand,0) - id.MaxStockLevel AS ExcessQty,
       ISNULL(sb.AvgUnitCost,0) AS AvgUnitCost,
       ROUND((ISNULL(sb.QtyOnHand,0) - id.MaxStockLevel) * ISNULL(sb.AvgUnitCost,0), 2) AS ExcessValue
FROM proj.TBL_ITEM i
JOIN proj.TBL_ITEM_DETAIL id ON id.ItemId = i.ItemId AND id.IsDefault = 1 AND id.IsActive = 1
LEFT JOIN proj.TBL_ITEM_UOM u ON u.UomId = i.BaseUomId
JOIN proj.TBL_STOCK_BALANCE sb ON sb.ItemId = i.ItemId
WHERE i.IsActive = 1 AND i.IsStockable = 1
  AND id.MaxStockLevel > 0
  AND ISNULL(sb.QtyOnHand,0) > id.MaxStockLevel;
GO

IF OBJECT_ID(N'[proj].[vw_AlertPaymentFollowupDue]') IS NOT NULL DROP VIEW [proj].[vw_AlertPaymentFollowupDue];
GO

CREATE VIEW proj.vw_AlertPaymentFollowupDue
AS
    WITH InvoiceOutstanding AS (
        SELECT i.CustomerId,
            i.TotalAmount * i.ExchangeRate
                - COALESCE(rv_paid.RvPaid, 0)
                - COALESCE(cn_paid.CnPaid, 0) AS OutstandingBase,
            CASE WHEN i.DueDate IS NULL OR i.DueDate >= CAST(GETDATE() AS DATE) THEN 0
                 ELSE DATEDIFF(DAY, i.DueDate, GETDATE()) END AS DaysOverdue
        FROM proj.TBL_INVOICE i
        LEFT JOIN (
            SELECT a.InvoiceId, SUM(CASE WHEN a.IsActive = 1 THEN a.AllocatedAmount ELSE 0 END) AS RvPaid
            FROM proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
            INNER JOIN proj.TBL_RECEIPT_VOUCHER rv ON a.RvId = rv.RvId
            WHERE rv.Status = 'Approved' AND rv.IsActive = 1 GROUP BY a.InvoiceId
        ) rv_paid ON i.InvoiceId = rv_paid.InvoiceId
        LEFT JOIN (
            SELECT a.InvoiceId, SUM(CASE WHEN a.IsActive = 1 THEN a.AllocatedAmount ELSE 0 END) AS CnPaid
            FROM proj.TBL_CREDIT_NOTE_ALLOCATION a
            INNER JOIN proj.TBL_CREDIT_NOTE cn ON a.CnId = cn.CnId
            WHERE cn.Status = 'Approved' AND cn.IsActive = 1 GROUP BY a.InvoiceId
        ) cn_paid ON i.InvoiceId = cn_paid.InvoiceId
        WHERE i.IsActive = 1 AND i.Status NOT IN ('Draft','Cancelled')
          AND (i.TotalAmount * i.ExchangeRate
               - COALESCE(rv_paid.RvPaid, 0)
               - COALESCE(cn_paid.CnPaid, 0)) > 0.005
    ),
    CustomerOutstanding AS (
        SELECT CustomerId, SUM(OutstandingBase) AS TotalPendingBase,
               SUM(CASE WHEN DaysOverdue > 0 THEN OutstandingBase ELSE 0 END) AS OverdueAmountBase,
               MAX(DaysOverdue) AS MaxDaysOverdue
        FROM InvoiceOutstanding GROUP BY CustomerId HAVING SUM(OutstandingBase) > 0
    ),
    LatestFollowup AS (
        SELECT * FROM (
            SELECT f.CustomerId, f.Outcome, f.PromiseAmount, f.PromiseDate, f.NextFollowupDate, f.PromiseStatus,
                   ROW_NUMBER() OVER (PARTITION BY f.CustomerId ORDER BY f.ContactDate DESC, f.FollowupId DESC) rn
            FROM PROJ.TBL_PAYMENT_FOLLOWUP f WHERE f.IsActive = 1
        ) x WHERE rn = 1
    )
    SELECT c.CustomerName, c.CustomerCode, c.Phone, c.Mobile,
        co.TotalPendingBase AS Outstanding, co.OverdueAmountBase AS Overdue, co.MaxDaysOverdue AS DaysOverdue,
        lf.PromiseAmount, lf.PromiseDate, lf.NextFollowupDate, lf.Outcome AS LastOutcome,
        CASE
            WHEN lf.PromiseStatus = 'Open' AND lf.PromiseDate < CAST(GETDATE() AS DATE) THEN 'Promise overdue'
            WHEN lf.PromiseStatus = 'Open' AND lf.PromiseDate = CAST(GETDATE() AS DATE) THEN 'Promise due today'
            WHEN lf.NextFollowupDate = CAST(GETDATE() AS DATE) THEN 'Follow-up due today'
            ELSE 'Action required'
        END AS Reason
    FROM CustomerOutstanding co
    INNER JOIN proj.TBL_CUSTOMER c ON co.CustomerId = c.CustomerId
    LEFT JOIN LatestFollowup lf ON co.CustomerId = lf.CustomerId
    WHERE (lf.PromiseStatus = 'Open' AND lf.PromiseDate <= CAST(GETDATE() AS DATE))
       OR (lf.NextFollowupDate IS NOT NULL AND lf.NextFollowupDate <= CAST(GETDATE() AS DATE));
GO

IF OBJECT_ID(N'[proj].[vw_AlertPendingApprovals]') IS NOT NULL DROP VIEW [proj].[vw_AlertPendingApprovals];
