CREATE VIEW proj.vw_AlertPendingApprovals AS SELECT at2.TransactionId,am.ModuleName,at2.DocumentNo,at2.DocumentAmount,at2.SubmittedBy,CAST(at2.SubmittedDate AS DATE) AS SubmittedDate,DATEDIFF(DAY,at2.SubmittedDate,GETDATE()) AS DaysPending,at2.CurrentLevelNo,al.LevelName AS PendingLevel,u.FullName AS ApproverName,u.Email AS ApproverEmail FROM proj.TBL_APPROVAL_TRANSACTION at2 JOIN proj.TBL_APPROVAL_MODULE am ON am.ModuleId=at2.ModuleId LEFT JOIN proj.TBL_APPROVAL_LEVEL al ON al.PolicyId=at2.PolicyId AND al.LevelNo=at2.CurrentLevelNo AND al.IsActive=1 LEFT JOIN proj.TBL_USERS u ON u.UserId=al.ApproverId WHERE at2.CurrentStatus='Pending'
GO

IF OBJECT_ID(N'[proj].[vw_AlertReceivables]') IS NOT NULL DROP VIEW [proj].[vw_AlertReceivables];
GO

CREATE VIEW proj.vw_AlertReceivables AS
SELECT
    c.CustomerId,
    c.CustomerCode,
    c.CustomerName,
    i.InvoiceId,
    i.InvoiceNo,
    CAST(i.InvoiceDate AS DATE) AS InvoiceDate,
    CAST(i.DueDate     AS DATE) AS DueDate,
    i.TotalAmount               AS InvoiceAmount,
    -- Paid in invoice currency = (approved RV + approved CN base) / invoice rate
    ROUND((COALESCE(rv.RvPaid,0) + COALESCE(cn.CnPaid,0)) / NULLIF(i.ExchangeRate, 0), 2) AS PaidAmount,
    i.TotalAmount - ROUND((COALESCE(rv.RvPaid,0) + COALESCE(cn.CnPaid,0)) / NULLIF(i.ExchangeRate, 0), 2) AS OutstandingAmount,
    CASE WHEN i.DueDate < CAST(GETDATE() AS DATE)
         THEN DATEDIFF(DAY, i.DueDate, GETDATE()) ELSE 0 END AS DaysOverdue
FROM proj.TBL_INVOICE i
JOIN proj.TBL_CUSTOMER c ON c.CustomerId = i.CustomerId
LEFT JOIN (
    SELECT a.InvoiceId, SUM(CASE WHEN a.IsActive=1 THEN a.AllocatedAmount ELSE 0 END) AS RvPaid
    FROM proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
    INNER JOIN proj.TBL_RECEIPT_VOUCHER rv ON a.RvId = rv.RvId
    WHERE rv.Status = 'Approved' AND rv.IsActive = 1
    GROUP BY a.InvoiceId
) rv ON rv.InvoiceId = i.InvoiceId
LEFT JOIN (
    SELECT a.InvoiceId, SUM(CASE WHEN a.IsActive=1 THEN a.AllocatedAmount ELSE 0 END) AS CnPaid
    FROM proj.TBL_CREDIT_NOTE_ALLOCATION a
    INNER JOIN proj.TBL_CREDIT_NOTE cn ON a.CnId = cn.CnId
    WHERE cn.Status = 'Approved' AND cn.IsActive = 1
    GROUP BY a.InvoiceId
) cn ON cn.InvoiceId = i.InvoiceId
WHERE i.IsActive = 1
  AND i.Status NOT IN ('Draft','Cancelled')
  AND i.TotalAmount * i.ExchangeRate > COALESCE(rv.RvPaid,0) + COALESCE(cn.CnPaid,0);
GO

IF OBJECT_ID(N'[proj].[vw_AlertSupplierInvoiceDue]') IS NOT NULL DROP VIEW [proj].[vw_AlertSupplierInvoiceDue];
GO
CREATE   VIEW proj.vw_AlertSupplierInvoiceDue AS
SELECT
    s.SupplierId, s.SupplierCode, s.SupplierName,
    si.SupplierInvoiceId, si.InvoiceNo,
    CAST(si.InvoiceDate AS DATE) AS InvoiceDate,
    CAST(si.DueDate     AS DATE) AS DueDate,
    si.TotalAmount AS InvoiceAmount,
    si.TotalAmount - ROUND(COALESCE(pv.PvPaid,0) / NULLIF(si.ExchangeRate,0), 2) AS OutstandingAmount,
    DATEDIFF(DAY, GETDATE(), si.DueDate) AS DaysToDue,   -- negative = overdue
    CASE
        WHEN si.DueDate < CAST(GETDATE() AS DATE) THEN 'Overdue'
        ELSE 'Due within 7 days'
    END AS DueStatus
FROM proj.TBL_SUPPLIER_INVOICE si
JOIN proj.TBL_SUPPLIER s ON s.SupplierId = si.SupplierId
LEFT JOIN (
    SELECT a.SupplierInvoiceId, SUM(CASE WHEN a.IsActive=1 THEN a.AllocatedAmount ELSE 0 END) AS PvPaid
    FROM proj.TBL_PAYMENT_VOUCHER_ALLOCATION a
    JOIN proj.TBL_PAYMENT_VOUCHER pv ON pv.PvId = a.PvId
    WHERE pv.Status = 'Approved' AND pv.IsActive = 1 AND a.SupplierInvoiceId IS NOT NULL
    GROUP BY a.SupplierInvoiceId
) pv ON pv.SupplierInvoiceId = si.SupplierInvoiceId
WHERE si.IsActive = 1
  AND si.Status NOT IN ('Draft','Cancelled','Rejected')
  AND si.DueDate IS NOT NULL
  AND si.DueDate <= DATEADD(DAY, 7, CAST(GETDATE() AS DATE))   -- overdue or due within 7 days
  AND si.TotalAmount * si.ExchangeRate > COALESCE(pv.PvPaid,0);
GO

IF OBJECT_ID(N'[proj].[VW_CUSTOMER]') IS NOT NULL DROP VIEW [proj].[VW_CUSTOMER];
GO
CREATE   VIEW [PROJ].[VW_CUSTOMER]
AS
SELECT
    C.CustomerId,
    C.CustomerCode,
    C.CustomerName,
    C.CustomerShortName,
    C.CustomerRef,

    C.CustomerCategoryId,
    CC.CategoryName                                         AS CustomerCategoryName,
    C.CustomerType,
    C.SalesPerson,

    C.Phone,
    C.Mobile,
    C.Email,
    C.Web,

    C.CurrencyId,
    CUR.CurrencyName,
    CUR.ShortName                                           AS CurrencyShortName,
    CUR.Symbol                                              AS CurrencySymbol,
    C.PaymentTermsId,
    PT.TermName                                             AS PaymentTermName,
    PT.TermDays                                             AS PaymentTermDays,
    C.CreditLimit,
    C.CreditDays,

    C.VatNumber,
    C.TaxNumber,

    -- ── Credit Hold (unchanged) ───────────────────────────────────
    C.CreditHold,
    C.CreditHoldBy,
    C.CreditHoldNote,

    -- ── Credit Flag (manual rating: GREEN / YELLOW / RED) ─────────
    ISNULL(C.CreditFlag, 'GREEN')                          AS CreditFlag,
    CASE ISNULL(C.CreditFlag, 'GREEN')
        WHEN 'GREEN'  THEN 'Good Standing'
        WHEN 'YELLOW' THEN 'Warning'
        WHEN 'RED'    THEN 'Overdue'
        ELSE 'Good Standing'
    END                                                     AS CreditFlagLabel,
    C.CreditFlagNote,
    C.CreditFlagBy,
    C.CreditFlagDate,

    C.IsActive,
    CASE WHEN C.IsActive = 1 THEN 'Active' ELSE 'Inactive' END AS StatusLabel,

    C.Remarks,

    C.CreatedBy,
    C.ModifiedBy

FROM TBL_CUSTOMER                  C
LEFT JOIN TBL_CUSTOMER_CATEGORY   CC  ON C.CustomerCategoryId = CC.CustomerCategoryId
LEFT JOIN TBL_CURRENCY            CUR ON C.CurrencyId         = CUR.CurrencyId
LEFT JOIN TBL_PAYMENT_TERMS       PT  ON C.PaymentTermsId     = PT.PaymentTermsId;
GO

IF OBJECT_ID(N'[proj].[VW_JOB_COST_ACTUAL]') IS NOT NULL DROP VIEW [proj].[VW_JOB_COST_ACTUAL];
GO

CREATE VIEW proj.VW_JOB_COST_ACTUAL AS
WITH Costs AS (

    -- Manhours → Mechanical (3) / Electrical (4)
    SELECT m.JobId,
           CASE WHEN m.MType = 'E' THEN 4 ELSE 3 END AS CostCategoryId,
           (m.Hours * ISNULL(m.NHRate, 0))
         + (ISNULL(m.OvertimeHours, 0) * ISNULL(m.OTRate, 0)) AS Amount
    FROM proj.TBL_MANHOUR m
    WHERE m.Status = 'Approved' AND m.IsActive = 1 AND m.JobId IS NOT NULL

    UNION ALL

    -- PO commitments → the category chosen on the PO (po.ExpenseCategoryId).
    -- In-house / non-costed jobs (IsCostingRequired = 0) are EXCLUDED — their
    -- purchases are inventory, not job cost; cost lands on the fab job at issue.
    SELECT po.JobId, po.ExpenseCategoryId AS CostCategoryId,
           proj.fn_ToBase(pol.OrderedQty * pol.UnitPrice, po.ExchangeRate) AS Amount
    FROM proj.TBL_PURCHASE_ORDER      po
    JOIN proj.TBL_PURCHASE_ORDER_LINE pol ON pol.PoId = po.PoId AND pol.IsActive = 1
    JOIN proj.TBL_JOB                 j   ON j.JobId  = po.JobId
    JOIN proj.TBL_JOBTYPE             jt  ON jt.JobTypeId = j.JobTypeId
    WHERE po.Status NOT IN ('Draft','Cancelled') AND po.IsActive = 1
      AND po.JobId IS NOT NULL AND po.ExpenseCategoryId IS NOT NULL
      AND ISNULL(jt.IsCostingRequired, 1) = 1

    UNION ALL

    -- Approved job expenses → their chosen category
    SELECT je.JobId, je.ExpenseCategoryId,
           ISNULL(je.AmountInBaseCurrency, proj.fn_ToBase(je.ExpenseAmount, je.ExchangeRate)) AS Amount
    FROM proj.TBL_JOB_EXPENSE je
    WHERE je.IsApproved = 1 AND je.JobId IS NOT NULL

)
SELECT JobId, CostCategoryId, SUM(ISNULL(Amount, 0)) AS ActualAmount
FROM Costs
GROUP BY JobId, CostCategoryId;
GO

IF OBJECT_ID(N'[proj].[VW_SUPPLIER]') IS NOT NULL DROP VIEW [proj].[VW_SUPPLIER];
GO

CREATE VIEW proj.VW_SUPPLIER AS
SELECT
    S.SupplierId, S.SupplierCode, S.SupplierName, S.SupplierShortName, S.SupplierRef,
    S.SupplierCategoryId,
    SC.CategoryName     AS SupplierCategoryName,
    S.SupplierType, S.AccountManager,
    S.Phone, S.Mobile, S.Email, S.Web,
    S.CurrencyId,
    CUR.CurrencyName, CUR.ShortName AS CurrencyShortName, CUR.Symbol AS CurrencySymbol,
    S.PaymentTermsId,
    PT.TermName         AS PaymentTermName,
    PT.TermDays         AS PaymentTermDays,
    S.CreditLimit, S.CreditDays,
    S.VatNumber, S.TaxNumber,
    S.IsApprovedVendor, S.IsOnHold,
    S.LeadTimeDays, S.PaymentMode,
    S.TradeLicenseNo, S.TradeLicenseExpiry,
    S.CountryId,
    C.CountryName,
    S.Rating,
    S.IsActive,
    CASE WHEN S.IsActive = 1 THEN 'Active' ELSE 'Inactive' END AS StatusLabel,
    S.Remarks,
    S.CreatedBy, S.ModifiedBy
FROM proj.TBL_SUPPLIER S
LEFT JOIN proj.TBL_SUPPLIER_CATEGORY SC  ON S.SupplierCategoryId = SC.SupplierCategoryId
LEFT JOIN proj.TBL_CURRENCY          CUR ON S.CurrencyId          = CUR.CurrencyId
LEFT JOIN proj.TBL_PAYMENT_TERMS     PT  ON S.PaymentTermsId      = PT.PaymentTermsId
LEFT JOIN proj.TBL_COUNTRY           C   ON S.CountryId           = C.CountryId;
GO

IF OBJECT_ID(N'[proj].[VW_JOB]') IS NOT NULL DROP VIEW [proj].[VW_JOB];
GO
CREATE VIEW [PROJ].[VW_JOB] AS
SELECT
    j.JobNumId, j.JobId, j.ApprovalStatus, j.ParentJobId, j.JobTypeId,
    jt.JobTypeName, jt.PreFix AS JobTypePrefix, jt.RequiresParentJob,
    jt.IsBudgetHeaderLinked, jt.IsCostingRequired,
    j.JobStageId, js.JobStageName,
    j.CustomerId, c.CustomerName, c.CustomerCode,
    j.JobCurrencyId, cur.ShortName AS CurrencyName, cur.Symbol AS CurrencySymbol,
    j.JobExcRate, j.JobDescription, j.JobDate, j.ProjectName, j.LpoDate, j.ContractRef, j.LpoRef,
    j.JobStatusId, jst.StatusName AS JobStatusName, jst.IsClosed AS IsClosedStatus,
    j.ExternalRef, j.EndUserId,
    j.BudgetCategoryId, ec.CategoryName AS BudgetCategoryName, ec.CategoryCode AS BudgetCategoryCode,
    j.JobCreatedBy, j.JobCreatedDate, j.JobLastModifiedBy, j.JobLastUpdatedDate,
    j.BomId, j.PlannedQty, j.PlannedUomId,
    CASE WHEN bh.JobId IS NOT NULL THEN 1 ELSE 0 END AS HasBom,
    ISNULL(bh.BomVersion, 0)  AS BomVersion,
    ISNULL(bh.BomStatus,  0)  AS BomHeaderStatus,
    ISNULL(bh.TotalBomValue, 0) AS TotalBomValue,
    (SELECT COUNT(*) FROM proj.TBL_BOM_DETAILS bd WHERE bd.JobId = j.JobId AND bd.IsActive = 1) AS BomLineCount,
    ISNULL(f.OrderValue, 0) AS OrderValue,
    ISNULL((SELECT SUM(ActualAmount) FROM proj.VW_JOB_COST_ACTUAL vca WHERE vca.JobId = j.JobId), 0) AS TotalActual,
    ISNULL(f.TotalExpenses, 0) AS TotalExpenses,
    ISNULL(f.TotalInvoicing, 0) AS TotalInvoicing,
    ISNULL(f.TotalPayments, 0) AS TotalPayments,
    ISNULL(f.TotalCredit, 0) AS TotalCredit,
    ISNULL(f.JobAdvanceAmount, 0) AS JobAdvanceAmount,
    ISNULL(f.BalanceAmount, 0) AS BalanceAmount,
    ISNULL(f.IsLDApplicable, 0) AS IsLDApplicable,
    ISNULL(f.LDAmount, 0) AS LDAmount,
    f.LDPercent,
    d.JobPlannedStartDate, d.JobExpectedCompleteDate, d.JobActualCompleteDate,
    d.JobExpectedDeliveryDate, d.JobActualDeliveryDate
FROM proj.TBL_JOB j
LEFT JOIN proj.TBL_JOBTYPE      jt  ON j.JobTypeId     = jt.JobTypeId
LEFT JOIN proj.TBL_JOB_STAGE    js  ON j.JobStageId    = js.JobStageId
LEFT JOIN proj.TBL_JOB_STATUS   jst ON j.JobStatusId   = jst.JobStatusId
LEFT JOIN proj.TBL_CUSTOMER     c   ON j.CustomerId    = c.CustomerId
LEFT JOIN proj.TBL_CURRENCY     cur ON j.JobCurrencyId = cur.CurrencyId
LEFT JOIN proj.TBL_JOB_EXPENSE_CATEGORY ec ON j.BudgetCategoryId = ec.ExpenseCategoryId
OUTER APPLY (
    SELECT TOP 1 b.JobId, b.BomVersion, b.BomStatus, b.TotalBomValue
    FROM proj.TBL_BOM_HEADER b
    WHERE b.JobId = j.JobId AND b.IsActive = 1
    ORDER BY b.BomVersion DESC, b.BomHeaderId DESC
) bh
LEFT JOIN proj.TBL_JOB_FINANCE  f   ON j.JobId = f.JobId
LEFT JOIN proj.TBL_JOB_DATES    d   ON j.JobId = d.JobId
LEFT JOIN proj.TBL_JOB_META     m   ON j.JobId = m.JobId;
GO

