IF OBJECT_ID(N'[proj].[sp_AdminDeleteManhourLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_AdminDeleteManhourLine];
GO
CREATE   PROCEDURE proj.sp_AdminDeleteManhourLine
    @ManhourId  INT,
    @DeletedBy  NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM proj.TBL_MANHOUR WHERE ManhourId = @ManhourId AND IsActive = 1)
    BEGIN
        RAISERROR('Line not found or already deleted.', 16, 1);
        RETURN;
    END

    UPDATE proj.TBL_MANHOUR
    SET    IsActive     = 0,
           ModifiedBy   = @DeletedBy,
           ModifiedDate = GETDATE()
    WHERE  ManhourId = @ManhourId;
END
GO

