IF OBJECT_ID(N'[proj].[sp_AdminSearchManhourLines]') IS NOT NULL DROP PROCEDURE [proj].[sp_AdminSearchManhourLines];
GO
CREATE   PROCEDURE proj.sp_AdminSearchManhourLines
    @SearchText   NVARCHAR(200) = NULL,
    @JobId        NVARCHAR(50)  = NULL,
    @DocumentNo   NVARCHAR(50)  = NULL,
    @EmployeeId   INT           = NULL,
    @EmpType      NVARCHAR(20)  = NULL,   -- 'COMPANY' | 'OUTSOURCED'
    @Status       NVARCHAR(50)  = NULL,
    @DateFrom     DATE          = NULL,
    @DateTo       DATE          = NULL,
    @PageNumber   INT           = 1,
    @PageSize     INT           = 50,
    @SortColumn   NVARCHAR(100) = N'DocumentDate',
    @SortDirection NVARCHAR(4)  = N'DESC'
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH Lines AS (
        SELECT
            m.ManhourId,
            m.BatchId,
            m.DocumentNo,
            m.DocumentDate,
            m.JobId,
            j.JobDescription,
            m.EmployeeId,
            e.EmpCode,
            e.EmployeeName,
            e.EmpType,
            m.Hours,
            m.OvertimeHours,
            m.Site,
            m.MType,
            m.Status,
            m.NHRate,
            m.OTRate,
            m.Remarks,
            m.CreatedBy,
            m.CreatedDate,
            m.ModifiedBy,
            m.ModifiedDate
        FROM proj.TBL_MANHOUR m
        LEFT JOIN proj.TBL_JOB      j ON j.JobId      = m.JobId
        LEFT JOIN proj.TBL_EMPLOYEE e ON e.EmployeeId  = m.EmployeeId
        WHERE m.IsActive = 1
          AND (@JobId      IS NULL OR m.JobId       = @JobId)
          AND (@EmployeeId IS NULL OR m.EmployeeId  = @EmployeeId)
          AND (@EmpType    IS NULL OR e.EmpType     = @EmpType)
          AND (@DocumentNo IS NULL OR m.DocumentNo  LIKE N'%' + @DocumentNo + N'%')
          AND (@Status     IS NULL OR m.Status      = @Status)
          AND (@DateFrom   IS NULL OR m.DocumentDate >= @DateFrom)
          AND (@DateTo     IS NULL OR m.DocumentDate <= @DateTo)
          AND (@SearchText IS NULL
               OR m.DocumentNo     LIKE N'%' + @SearchText + N'%'
               OR m.JobId          LIKE N'%' + @SearchText + N'%'
               OR e.EmpCode        LIKE N'%' + @SearchText + N'%'
               OR e.EmployeeName   LIKE N'%' + @SearchText + N'%'
               OR j.JobDescription LIKE N'%' + @SearchText + N'%')
    ),
    Ranked AS (
        SELECT *, COUNT(*) OVER () AS TotalRows,
               ROW_NUMBER() OVER (
                   ORDER BY
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='DocumentDate' THEN DocumentDate END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='DocumentDate' THEN DocumentDate END DESC,
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='DocumentNo'  THEN DocumentNo   END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='DocumentNo'  THEN DocumentNo   END DESC,
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='JobId'       THEN JobId        END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='JobId'       THEN JobId        END DESC,
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='EmpCode'     THEN EmpCode      END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='EmpCode'     THEN EmpCode      END DESC,
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='Status'      THEN Status       END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='Status'      THEN Status       END DESC,
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='Hours'       THEN Hours        END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='Hours'       THEN Hours        END DESC,
                       DocumentDate DESC, ManhourId DESC
               ) AS RowNum
        FROM Lines
    )
    SELECT
        ManhourId, BatchId, DocumentNo, DocumentDate,
        JobId, JobDescription, EmployeeId, EmpCode, EmployeeName, EmpType,
        Hours, OvertimeHours, Site, MType, Status,
        NHRate, OTRate, Remarks, CreatedBy, CreatedDate, ModifiedBy, ModifiedDate,
        TotalRows
    FROM Ranked
    WHERE RowNum BETWEEN (@PageNumber - 1) * @PageSize + 1
                     AND  @PageNumber      * @PageSize
    ORDER BY RowNum;
END
GO

IF OBJECT_ID(N'[proj].[sp_AdminUpdateManhourLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_AdminUpdateManhourLine];
GO
CREATE   PROCEDURE proj.sp_AdminUpdateManhourLine
    @ManhourId    INT,
    @JobId        NVARCHAR(50),
    @EmployeeId   INT,
    @Hours        DECIMAL(6,2),
    @OvertimeHours DECIMAL(6,2),
    @Site         NVARCHAR(100) = NULL,
    @MType        NVARCHAR(50)  = NULL,
    @Remarks      NVARCHAR(500) = NULL,
    @ModifiedBy   NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM proj.TBL_MANHOUR WHERE ManhourId = @ManhourId AND IsActive = 1)
    BEGIN
        RAISERROR('Line not found.', 16, 1);
        RETURN;
    END

    -- Basic value checks
    IF @Hours <= 0
    BEGIN RAISERROR('Hours must be greater than 0.', 16, 1); RETURN; END
    IF @Hours > 24
    BEGIN RAISERROR('Hours cannot exceed 24.', 16, 1); RETURN; END
    IF @OvertimeHours < 0
    BEGIN RAISERROR('OT hours cannot be negative.', 16, 1); RETURN; END
    IF @Hours + @OvertimeHours > 24
    BEGIN RAISERROR('Total hours (NH + OT) cannot exceed 24.', 16, 1); RETURN; END

    UPDATE proj.TBL_MANHOUR
    SET    JobId         = @JobId,
           EmployeeId    = @EmployeeId,
           Hours         = @Hours,
           OvertimeHours = @OvertimeHours,
           Site          = NULLIF(@Site, ''),
           MType         = NULLIF(@MType,''),
           Remarks       = NULLIF(@Remarks,''),
           ModifiedBy    = @ModifiedBy,
           ModifiedDate  = GETDATE()
    WHERE  ManhourId = @ManhourId;

    SELECT 1 AS Result;
END
GO

