IF OBJECT_ID(N'[proj].[sp_AmendPOLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_AmendPOLine];
GO

CREATE PROCEDURE proj.sp_AmendPOLine
    @PoLineId     INT,
    @NewQty       DECIMAL(18,4),
    @NewPrice     DECIMAL(18,4),
    @Reason       NVARCHAR(500),
    @PasswordHash NVARCHAR(500),
    @ModifiedBy   NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM proj.TBL_USERS WHERE UserName=@ModifiedBy AND PasswordHash=@PasswordHash AND IsActive=1)
        RAISERROR('Incorrect password.', 16, 1);

    IF LTRIM(RTRIM(ISNULL(@Reason,''))) = ''
        RAISERROR('A reason is required for amendment.', 16, 1);

    DECLARE @CurrentOrdered  DECIMAL(18,4);
    DECLARE @CurrentReceived DECIMAL(18,4);
    DECLARE @CurrentPrice    DECIMAL(18,4);
    DECLARE @PoStatus        NVARCHAR(50);
    DECLARE @PrLineId        INT;
    DECLARE @BomDetailId     INT;
    DECLARE @PoIdVal         INT;
    DECLARE @LineNumVal      INT;
    DECLARE @ItemCode        NVARCHAR(100);
    DECLARE @ItemDesc        NVARCHAR(500);

    SELECT @CurrentOrdered  = pol.OrderedQty,
           @CurrentReceived = ISNULL(pol.ReceivedQty, 0),
           @CurrentPrice    = pol.UnitPrice,
           @PoStatus        = po.Status,
           @PrLineId        = pol.PrLineId,
           @PoIdVal         = pol.PoId,
           @LineNumVal      = pol.LineNum,
           @ItemCode        = pol.ItemCode,
           @ItemDesc        = pol.ItemDesc
    FROM   proj.TBL_PURCHASE_ORDER_LINE pol
    JOIN   proj.TBL_PURCHASE_ORDER      po ON po.PoId = pol.PoId
    WHERE  pol.PoLineId = @PoLineId AND pol.IsActive = 1;

    IF @CurrentOrdered IS NULL RAISERROR('PO line not found.', 16, 1);

    IF @PoStatus NOT IN ('Approved','Partial','Received')
        RAISERROR('Amendment is only allowed on Approved, Partial or Received POs.', 16, 1);
    IF @NewQty <= 0
        RAISERROR('New quantity must be greater than zero.', 16, 1);
    IF @NewQty > @CurrentOrdered
        RAISERROR('Amendment can only reduce the ordered quantity, not increase it.', 16, 1);

    -- Guard against Draft + confirmed GRN lines combined (pol.ReceivedQty only
    -- reflects confirmed GRNs; Draft GRNs may already carry a received qty)
    DECLARE @TotalGrnQty DECIMAL(18,4);
    SELECT @TotalGrnQty = ISNULL(SUM(d.ReceivedQty), 0)
    FROM   proj.TBL_GRN_DETAIL d
    JOIN   proj.TBL_GRN_HEADER h ON h.GrnId = d.GrnId AND h.IsActive = 1
    WHERE  d.PoLineId = @PoLineId
      AND  d.IsActive = 1
      AND  h.Status  <> 'Cancelled';

    IF @NewQty < @TotalGrnQty
    BEGIN
        DECLARE @GrnMsg NVARCHAR(300) =
            'New quantity (' + CAST(@NewQty AS NVARCHAR(50)) +
            ') cannot be less than the total quantity already recorded in GRNs (' +
            CAST(@TotalGrnQty AS NVARCHAR(50)) + '), including drafts.';
        RAISERROR(@GrnMsg, 16, 1);
    END

    IF @NewPrice < 0
        RAISERROR('Unit price cannot be negative.', 16, 1);

    -- 1. Update PO line
    UPDATE proj.TBL_PURCHASE_ORDER_LINE
    SET    OrderedQty=@NewQty, UnitPrice=@NewPrice,
           ModifiedBy=@ModifiedBy, ModifiedDate=GETDATE()
    WHERE  PoLineId=@PoLineId;

    -- 2. Sync GRN detail OrderedQty
    UPDATE proj.TBL_GRN_DETAIL
    SET    OrderedQty=@NewQty, ModifiedBy=@ModifiedBy, ModifiedDate=GETDATE()
    WHERE  PoLineId=@PoLineId AND IsActive=1;

    -- 2b. Recompute this PO line's status + PO header status
    EXEC proj.sp_RecalcPoLineStatus @PoLineId, @ModifiedBy;

    -- 3. Recalculate PR line PoCreatedQty + BOM PoCreatedQty
    IF @PrLineId IS NOT NULL
    BEGIN
        SELECT @BomDetailId = BomDetailId
        FROM   proj.TBL_PURCHASE_REQUEST_LINE
        WHERE  PrLineId=@PrLineId AND IsActive=1;

        UPDATE proj.TBL_PURCHASE_REQUEST_LINE
        SET    PoCreatedQty = (
                   SELECT ISNULL(SUM(pol2.OrderedQty),0)
                   FROM proj.TBL_PURCHASE_ORDER_LINE pol2
                   WHERE pol2.PrLineId=@PrLineId AND pol2.IsActive=1
               ),
               ModifiedBy=@ModifiedBy, ModifiedDate=GETDATE()
        WHERE  PrLineId=@PrLineId;

        EXEC proj.sp_RecalcPrStatus @PrLineId, @ModifiedBy;

        IF @BomDetailId IS NOT NULL
        BEGIN
            UPDATE proj.TBL_BOM_DETAILS
            SET    PoCreatedQty = (
                       SELECT ISNULL(SUM(pol3.OrderedQty),0)
                       FROM proj.TBL_PURCHASE_ORDER_LINE pol3
                       JOIN proj.TBL_PURCHASE_REQUEST_LINE prl3
                           ON prl3.PrLineId=pol3.PrLineId AND prl3.IsActive=1
                       WHERE prl3.BomDetailId=@BomDetailId AND pol3.IsActive=1
                   )
            WHERE  BomId=@BomDetailId;

            UPDATE proj.TBL_BOM_DETAILS
            SET    BomStatus = CASE
                       WHEN BomReceivedQty >= BomRequestedQty THEN 'FullyReceived'
                       WHEN BomReceivedQty  > 0               THEN 'PartialReceived'
                       WHEN PoCreatedQty   >= BomRequestedQty THEN 'PORaised'
                       WHEN PoCreatedQty    > 0               THEN 'POPartial'
                       WHEN PrCreatedQty   >= BomRequestedQty THEN 'PRRaised'
                       WHEN PrCreatedQty    > 0               THEN 'PRPartial'
                       ELSE 'Pending'
                   END,
                   ModifiedBy=@ModifiedBy, ModifiedDate=GETDATE()
            WHERE  BomId=@BomDetailId;
        END
    END

    -- 4. Write amendment log
    INSERT INTO proj.TBL_PO_AMENDMENT_LOG
        (PoLineId,PoId,LineNum,ItemCode,ItemDesc,OldQty,NewQty,OldPrice,NewPrice,Reason,AmendedBy,AmendedDate)
    VALUES
        (@PoLineId,@PoIdVal,@LineNumVal,@ItemCode,@ItemDesc,@CurrentOrdered,@NewQty,@CurrentPrice,@NewPrice,@Reason,@ModifiedBy,GETDATE());

    SELECT @PoLineId AS PoLineId;
END
GO

IF OBJECT_ID(N'[proj].[sp_AmendPOLineQty]') IS NOT NULL DROP PROCEDURE [proj].[sp_AmendPOLineQty];
GO

CREATE PROCEDURE proj.sp_AmendPOLineQty
    @PoLineId   INT,
    @NewQty     DECIMAL(18,4),
    @ModifiedBy NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CurrentOrdered  DECIMAL(18,4);
    DECLARE @CurrentReceived DECIMAL(18,4);
    DECLARE @PoStatus        NVARCHAR(50);
    DECLARE @PrLineId        INT;
    DECLARE @BomDetailId     INT;

    SELECT @CurrentOrdered  = pol.OrderedQty,
           @CurrentReceived = ISNULL(pol.ReceivedQty, 0),
           @PoStatus        = po.Status,
           @PrLineId        = pol.PrLineId
    FROM   proj.TBL_PURCHASE_ORDER_LINE pol
    JOIN   proj.TBL_PURCHASE_ORDER      po ON po.PoId = pol.PoId
    WHERE  pol.PoLineId = @PoLineId
      AND  pol.IsActive = 1;

    IF @CurrentOrdered IS NULL
        RAISERROR('PO line not found.', 16, 1);

    IF @PoStatus NOT IN ('Approved', 'Partial')
        RAISERROR('Quantity amendment is only allowed on Approved or Partial POs.', 16, 1);

    IF @NewQty <= 0
        RAISERROR('New quantity must be greater than zero.', 16, 1);

    IF @NewQty > @CurrentOrdered
        RAISERROR('Amendment can only reduce the ordered quantity, not increase it.', 16, 1);

    -- Guard against Draft + confirmed GRN lines combined (pol.ReceivedQty only
    -- reflects confirmed GRNs; Draft GRNs may already carry a received qty)
    DECLARE @TotalGrnQty DECIMAL(18,4);
    SELECT @TotalGrnQty = ISNULL(SUM(d.ReceivedQty), 0)
    FROM   proj.TBL_GRN_DETAIL d
    JOIN   proj.TBL_GRN_HEADER h ON h.GrnId = d.GrnId AND h.IsActive = 1
    WHERE  d.PoLineId = @PoLineId
      AND  d.IsActive = 1
      AND  h.Status  <> 'Cancelled';

    IF @NewQty < @TotalGrnQty
    BEGIN
        DECLARE @GrnMsg NVARCHAR(300) =
            'New quantity (' + CAST(@NewQty AS NVARCHAR(50)) +
            ') cannot be less than the total quantity already recorded in GRNs (' +
            CAST(@TotalGrnQty AS NVARCHAR(50)) + '), including drafts.';
        RAISERROR(@GrnMsg, 16, 1);
    END

    -- 1. Update the PO line
    UPDATE proj.TBL_PURCHASE_ORDER_LINE
    SET    OrderedQty   = @NewQty,
           ModifiedBy   = @ModifiedBy,
           ModifiedDate = GETDATE()
    WHERE  PoLineId = @PoLineId;

    -- 2. Sync GRN detail OrderedQty for all active GRN lines linked to this PO line
    UPDATE proj.TBL_GRN_DETAIL
    SET    OrderedQty   = @NewQty,
           ModifiedBy   = @ModifiedBy,
           ModifiedDate = GETDATE()
    WHERE  PoLineId = @PoLineId
      AND  IsActive = 1;

    -- 2b. Recompute this PO line's status + PO header status
    EXEC proj.sp_RecalcPoLineStatus @PoLineId, @ModifiedBy;

    -- 3. Recalculate PR line PoCreatedQty from sum of all active PO lines
    IF @PrLineId IS NOT NULL
    BEGIN
        SELECT @BomDetailId = BomDetailId
        FROM   proj.TBL_PURCHASE_REQUEST_LINE
        WHERE  PrLineId = @PrLineId AND IsActive = 1;

        UPDATE proj.TBL_PURCHASE_REQUEST_LINE
        SET    PoCreatedQty = (
                   SELECT ISNULL(SUM(pol2.OrderedQty), 0)
                   FROM   proj.TBL_PURCHASE_ORDER_LINE pol2
                   WHERE  pol2.PrLineId = @PrLineId
                     AND  pol2.IsActive = 1
               ),
               ModifiedBy   = @ModifiedBy,
               ModifiedDate = GETDATE()
        WHERE  PrLineId = @PrLineId;

        EXEC proj.sp_RecalcPrStatus @PrLineId, @ModifiedBy;

        IF @BomDetailId IS NOT NULL
        BEGIN
            UPDATE proj.TBL_BOM_DETAILS
            SET    PoCreatedQty = (
                       SELECT ISNULL(SUM(pol3.OrderedQty), 0)
                       FROM   proj.TBL_PURCHASE_ORDER_LINE pol3
                       JOIN   proj.TBL_PURCHASE_REQUEST_LINE prl3
                           ON prl3.PrLineId = pol3.PrLineId AND prl3.IsActive = 1
                       WHERE  prl3.BomDetailId = @BomDetailId
                         AND  pol3.IsActive    = 1
                   )
            WHERE  BomId = @BomDetailId;
        END
    END

    SELECT @PoLineId AS PoLineId;
END
GO

IF OBJECT_ID(N'[proj].[sp_ApproveBom]') IS NOT NULL DROP PROCEDURE [proj].[sp_ApproveBom];
GO

-- sp_ApproveBom: approve/unapprove a BOM
CREATE   PROCEDURE proj.sp_ApproveBom
    @BomHeaderId  INT,
    @Action       NVARCHAR(10),   -- 'APPROVE' or 'UNAPPROVE'
    @ApprovedBy   NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM proj.TBL_BOM_HEADER WHERE BomHeaderId = @BomHeaderId AND IsActive = 1)
    BEGIN
        RAISERROR('BOM not found.', 16, 1);
        RETURN;
    END

    IF @Action = 'APPROVE'
    BEGIN
        -- Must have at least one detail line
        IF NOT EXISTS (SELECT 1 FROM proj.TBL_BOM_DETAILS WHERE BomHeaderId = @BomHeaderId AND IsActive = 1)
        BEGIN
            RAISERROR('Cannot approve a BOM with no detail lines.', 16, 1);
            RETURN;
        END

        UPDATE proj.TBL_BOM_HEADER
        SET BomStatus       = 'Approved',
            BomApprovedBy   = @ApprovedBy,
            BomApprovedDate = GETDATE(),
            ModifiedBy      = @ApprovedBy,
            ModifiedDate    = GETDATE()
        WHERE BomHeaderId = @BomHeaderId;
    END
    ELSE IF @Action = 'UNAPPROVE'
    BEGIN
        UPDATE proj.TBL_BOM_HEADER
        SET BomStatus       = 'Draft',
            BomApprovedBy   = NULL,
            BomApprovedDate = NULL,
            ModifiedBy      = @ApprovedBy,
            ModifiedDate    = GETDATE()
        WHERE BomHeaderId = @BomHeaderId;
    END
    ELSE
    BEGIN
        RAISERROR('Invalid action. Use APPROVE or UNAPPROVE.', 16, 1);
        RETURN;
    END

    SELECT BomHeaderId, BomStatus, BomApprovedBy, BomApprovedDate
    FROM proj.TBL_BOM_HEADER
    WHERE BomHeaderId = @BomHeaderId;
END
GO

IF OBJECT_ID(N'[proj].[sp_ApproveJobBudget]') IS NOT NULL DROP PROCEDURE [proj].[sp_ApproveJobBudget];
GO

CREATE PROCEDURE proj.sp_ApproveJobBudget
    @JobId        NVARCHAR(50),
    @PasswordHash NVARCHAR(500),
    @ApprovedBy   NVARCHAR(100),
    @Reason       NVARCHAR(500) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @Reason IS NULL OR LTRIM(RTRIM(@Reason)) = N''
    BEGIN RAISERROR('Reason is required to approve the budget.', 16, 1); RETURN; END

    DECLARE @UserId INT = (SELECT TOP 1 UserId FROM proj.TBL_USERS WHERE UserName = @ApprovedBy);
    IF @UserId IS NULL
    BEGIN RAISERROR('Acting user not found.', 16, 1); RETURN; END

    DECLARE @JobsMenuId   INT = (SELECT MenuId   FROM proj.TBL_MENU         WHERE MenuUrl = '/jobs');
    DECLARE @ApproveActId INT = (SELECT ActionId FROM proj.TBL_MENU_ACTIONS WHERE MenuId = @JobsMenuId AND ActionCode = 'APPROVE');

    DECLARE @HasApprovePerm BIT = CASE WHEN EXISTS (
        SELECT 1 FROM proj.TBL_USER_ROLES ur
        JOIN proj.TBL_ROLE_MENU_ACTION rma ON rma.RoleId = ur.RoleId AND rma.MenuId = @JobsMenuId AND rma.ActionId = @ApproveActId AND rma.IsAllowed = 1
        WHERE ur.UserId = @UserId) THEN 1 ELSE 0 END;
    IF @HasApprovePerm = 0
    BEGIN RAISERROR('You do not have permission to approve budgets.', 16, 1); RETURN; END

    DECLARE @HasUserSecret BIT = CASE WHEN EXISTS (
        SELECT 1 FROM proj.TBL_USER_SECRET WHERE UserId = @UserId AND SecretKey = 'BUDGET_PASSWORD') THEN 1 ELSE 0 END;
    DECLARE @AuthSource NVARCHAR(20);
    IF @HasUserSecret = 1
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM proj.TBL_USER_SECRET WHERE UserId = @UserId AND SecretKey = 'BUDGET_PASSWORD' AND SecretValueHash = @PasswordHash)
        BEGIN RAISERROR('Incorrect budget password.', 16, 1); RETURN; END
        SET @AuthSource = N'user';
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM proj.TBL_USER_ROLES ur
            JOIN proj.TBL_ROLE_SECRET rs ON rs.RoleId = ur.RoleId AND rs.SecretKey = 'BUDGET_PASSWORD'
            WHERE ur.UserId = @UserId AND rs.SecretValueHash = @PasswordHash)
        BEGIN RAISERROR('Incorrect password, or you have no role-level budget password configured (and your personal budget password is not set).', 16, 1); RETURN; END
        SET @AuthSource = N'role';
    END

    DECLARE @LatestRv INT = ISNULL((SELECT MAX(RvNo) FROM proj.TBL_JOB_BUDGET WHERE JobId = @JobId), -1);
    IF @LatestRv = -1
    BEGIN RAISERROR('No budget lines exist for this job.', 16, 1); RETURN; END
    IF EXISTS (SELECT 1 FROM proj.TBL_JOB_BUDGET WHERE JobId = @JobId AND RvNo = @LatestRv AND IsApproved = 1)
    BEGIN RAISERROR('Budget revision %d is already approved.', 16, 1, @LatestRv); RETURN; END

    -- ── PR guard: a revised item qty cannot drop below what has already been PR'd ──
    DECLARE @vCode NVARCHAR(50), @vBudgetQty DECIMAL(18,4), @vPrQty DECIMAL(18,4);
    SELECT TOP 1
        @vCode = i.ItemCode, @vBudgetQty = ISNULL(b.BudgetQty,0), @vPrQty = pr.PrQty
    FROM (
        SELECT bd.ItemId, SUM(bd.PrCreatedQty) AS PrQty
        FROM proj.TBL_BOM_DETAILS bd
        JOIN proj.TBL_BOM_HEADER  bh ON bh.BomHeaderId = bd.BomHeaderId AND bh.IsActive = 1
        WHERE bh.JobId = @JobId AND bd.IsActive = 1
        GROUP BY bd.ItemId
        HAVING SUM(bd.PrCreatedQty) > 0
    ) pr
    JOIN proj.TBL_ITEM i ON i.ItemId = pr.ItemId
    OUTER APPLY (
        SELECT SUM(bi.Qty) AS BudgetQty FROM proj.TBL_JOB_BUDGET_ITEM bi
        WHERE bi.JobId=@JobId AND bi.RvNo=@LatestRv AND bi.ItemId=pr.ItemId AND bi.IsActive=1
    ) b
    WHERE ISNULL(b.BudgetQty,0) < pr.PrQty
    ORDER BY i.ItemCode;

    IF @vCode IS NOT NULL
    BEGIN
        DECLARE @vmsg NVARCHAR(400) =
            'Cannot reduce the budget quantity below the PR created quantity. Item ' + @vCode +
            ' — Budget Qty: ' + CONVERT(NVARCHAR(30), CAST(@vBudgetQty AS DECIMAL(18,2))) +
            ', PR Created Qty: ' + CONVERT(NVARCHAR(30), CAST(@vPrQty AS DECIMAL(18,2)));
        RAISERROR(@vmsg, 16, 1); RETURN;
    END

    UPDATE proj.TBL_JOB_BUDGET
    SET IsApproved = 1, ApprovedBy = @ApprovedBy, ApprovedDate = GETDATE(), ApprovalReason = @Reason
    WHERE JobId = @JobId AND RvNo = @LatestRv;

    -- Auto-advance job stage: budget approved → STAGE2
    UPDATE proj.TBL_JOB
    SET JobStageId = 'STAGE2'
    WHERE JobId = @JobId AND JobStageId = 'STAGE1';

    INSERT INTO proj.TBL_JOB_AUDIT (JobId, Action, Section, OldValue, NewValue, Remarks, CreatedBy, CreatedDate)
    VALUES (@JobId, N'BUDGET_APPROVED', N'Budget', NULL, CONCAT(N'Rev ', @LatestRv, N' approved'),
            CONCAT(@Reason, N' [auth=', @AuthSource, N']'), @ApprovedBy, GETDATE());

    -- Generate / sync the BOM from the approved budget (BomRequestedQty updated, PR progress kept).
    EXEC proj.sp_GenerateBomFromBudget @JobId = @JobId, @RvNo = @LatestRv, @By = @ApprovedBy;

    SELECT 1 AS LinesApproved, @LatestRv AS ApprovedRvNo, @AuthSource AS AuthSource;
END
GO

IF OBJECT_ID(N'[proj].[sp_ApproveJobExpense]') IS NOT NULL DROP PROCEDURE [proj].[sp_ApproveJobExpense];
GO

CREATE   PROCEDURE PROJ.sp_ApproveJobExpense
    @ExpenseId  INT,
    @JobId      NVARCHAR(50),
    @ApprovedBy NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE PROJ.TBL_JOB_EXPENSE
    SET IsApproved = 1, ApprovedBy = @ApprovedBy, ApprovedDate = GETDATE(),
        ModifiedBy = @ApprovedBy, ModifiedDate = GETDATE()
    WHERE ExpenseId = @ExpenseId AND JobId = @JobId;

    INSERT INTO PROJ.TBL_JOB_AUDIT (JobId, Action, Section, NewValue, CreatedBy, CreatedDate)
    VALUES (@JobId, 'EXPENSE_APPROVED', 'Expenses', CAST(@ExpenseId AS NVARCHAR), @ApprovedBy, GETDATE());

    SELECT @ExpenseId AS ExpenseId;
END
GO

IF OBJECT_ID(N'[proj].[sp_ApproveManhour]') IS NOT NULL DROP PROCEDURE [proj].[sp_ApproveManhour];
GO

CREATE PROCEDURE proj.sp_ApproveManhour
    @BatchId        INT,
    @ApprovedBy     NVARCHAR(100),
    @OverrideBudget BIT = 0
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        -- ── Step 1: Resolve rates (3-level fallback) ─────────────────────────
        UPDATE m SET
            m.NHRate       = ISNULL(r1.NHRate, ISNULL(r2.NHRate, ISNULL(r3.NHRate, 0))),
            m.OTRate       = ISNULL(r1.OTRate, ISNULL(r2.OTRate, ISNULL(r3.OTRate, 0))),
            m.Status       = 'Approved',
            m.ModifiedBy   = @ApprovedBy,
            m.ModifiedDate = GETDATE()
        FROM proj.TBL_MANHOUR m
        JOIN proj.TBL_JOB j ON j.JobId = m.JobId
        OUTER APPLY (
            SELECT TOP 1 NHRate, OTRate FROM proj.TBL_MANHOUR_RATE
            WHERE IsActive = 1 AND JobId = m.JobId
              AND m.DocumentDate BETWEEN EffectiveFrom AND EffectiveTo
        ) r1
        OUTER APPLY (
            SELECT TOP 1 NHRate, OTRate FROM proj.TBL_MANHOUR_RATE
            WHERE IsActive = 1 AND JobTypeId = j.JobTypeId AND JobId IS NULL
              AND m.DocumentDate BETWEEN EffectiveFrom AND EffectiveTo
        ) r2
        OUTER APPLY (
            SELECT TOP 1 NHRate, OTRate FROM proj.TBL_MANHOUR_RATE
            WHERE IsActive = 1 AND JobTypeId IS NULL AND JobId IS NULL
              AND m.DocumentDate BETWEEN EffectiveFrom AND EffectiveTo
        ) r3
        WHERE m.BatchId = @BatchId AND m.IsActive = 1;

        -- ── Step 2: Zero-rate check (ALWAYS a hard block — override never bypasses) ──
        DECLARE @ZeroRateJobs NVARCHAR(MAX);
        SELECT @ZeroRateJobs = STRING_AGG(JobId, ', ')
        FROM (
            SELECT DISTINCT m.JobId
            FROM proj.TBL_MANHOUR m
            WHERE m.BatchId = @BatchId AND m.IsActive = 1
              AND m.Hours > 0 AND m.NHRate = 0
        ) zr;

        IF @ZeroRateJobs IS NOT NULL
        BEGIN
            ROLLBACK TRANSACTION;
            RAISERROR(N'Approval blocked - no manhour rate found for job(s): %s. Configure a rate in Manhour Rates before approving.', 16, 1, @ZeroRateJobs);
            RETURN;
        END;

        -- ── Step 3: Budget ceiling check (bypassed when @OverrideBudget = 1) ──
        IF @OverrideBudget = 0
        BEGIN
            DECLARE @OverBudget NVARCHAR(MAX);
            SELECT @OverBudget = STRING_AGG(Entry, ' | ')
            FROM (
                SELECT
                    x.JobId + ' [' + x.CategoryCode
                    + ': cost '    + FORMAT(x.TotalCostBase, 'N2')
                    + ' / budget ' + FORMAT(x.BudgetBase,    'N2')
                    + ', over by ' + FORMAT(x.TotalCostBase - x.BudgetBase, 'N2') + ']' AS Entry
                FROM (
                    SELECT
                        m.JobId,
                        jec.CategoryCode,
                        ROUND(SUM(m.Hours * m.NHRate + m.OvertimeHours * m.OTRate), 2) AS TotalCostBase,
                        ISNULL(MAX(jb.AmountInBaseCurrency), 0)                        AS BudgetBase
                    FROM proj.TBL_MANHOUR m
                    JOIN proj.TBL_JOB_EXPENSE_CATEGORY jec
                        ON m.MType = jec.MhTypeCode
                    LEFT JOIN proj.TBL_JOB_BUDGET jb
                        ON  jb.JobId         = m.JobId
                        AND jb.CostCategoryId = jec.ExpenseCategoryId
                        AND jb.IsCurrent     = 1
                        AND jb.IsApproved    = 1
                    WHERE m.JobId IN (
                        SELECT DISTINCT JobId FROM proj.TBL_MANHOUR
                        WHERE BatchId = @BatchId AND IsActive = 1
                    )
                    AND m.IsActive = 1
                    AND m.Status   = 'Approved'
                    GROUP BY m.JobId, jec.CategoryCode
                    HAVING MAX(jb.AmountInBaseCurrency) > 0
                       AND ROUND(SUM(m.Hours * m.NHRate + m.OvertimeHours * m.OTRate), 2)
                           > MAX(jb.AmountInBaseCurrency)
                ) x
            ) msg;

            IF @OverBudget IS NOT NULL
            BEGIN
                ROLLBACK TRANSACTION;
                RAISERROR(N'Manhour approval blocked - cost exceeds budget (base currency): %s', 16, 1, @OverBudget);
                RETURN;
            END;
        END;

        COMMIT TRANSACTION;

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_ApproveManhourHook]') IS NOT NULL DROP PROCEDURE [proj].[sp_ApproveManhourHook];
GO
-- Hook wrapper: calls sp_ApproveManhour, discards its result set,
-- re-raises any budget/rate errors as exceptions so sp_SubmitForApproval's
-- CATCH block handles them cleanly.
CREATE   PROCEDURE proj.sp_ApproveManhourHook
    @DocId INT,
    @By    NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    -- Capture sp_ApproveManhour's result set into a table var so it is
    -- not emitted to the client (which would confuse sp_SubmitForApproval's caller)
    DECLARE @r TABLE (BatchId INT, ErrorMessage NVARCHAR(MAX));

    INSERT INTO @r (BatchId, ErrorMessage)
    EXEC proj.sp_ApproveManhour @BatchId = @DocId, @ApprovedBy = @By;

    -- If sp_ApproveManhour returned BatchId < 0 (blocked), raise the message
    DECLARE @batchId INT, @errMsg NVARCHAR(MAX);
    SELECT @batchId = BatchId, @errMsg = ErrorMessage FROM @r;

    IF ISNULL(@batchId, -1) < 0
    BEGIN
        DECLARE @msg NVARCHAR(2048) = ISNULL(@errMsg, 'Manhour approval failed.');
        RAISERROR(@msg, 16, 1);
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_AssertBudgetApproved]') IS NOT NULL DROP PROCEDURE [proj].[sp_AssertBudgetApproved];
GO

-- In-house / non-costed jobs are exempt from budget approval
CREATE PROCEDURE proj.sp_AssertBudgetApproved
    @JobId   NVARCHAR(50),
    @TxnType NVARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- Jobs whose type does not require costing (e.g. in-house stock jobs) never
    -- need an approved budget to transact — they are pure inventory vehicles.
    IF EXISTS (SELECT 1 FROM proj.TBL_JOB j
               JOIN proj.TBL_JOBTYPE jt ON jt.JobTypeId = j.JobTypeId
               WHERE j.JobId = @JobId AND ISNULL(jt.IsCostingRequired, 1) = 0)
        RETURN;

    DECLARE @State NVARCHAR(20) = proj.fn_GetJobBudgetState(@JobId);
    IF @State = N'APPROVED' RETURN;

    DECLARE @Why NVARCHAR(100) =
        CASE WHEN @State = N'NONE'  THEN N'has no budget'
             WHEN @State = N'DRAFT' THEN N'has a draft budget that is not yet approved'
             ELSE N'has an unapproved budget' END;

    DECLARE @Msg NVARCHAR(500) =
        N'Job ' + @JobId + N' ' + @Why + N'. ' +
        N'Approve the current budget revision before posting ' +
        ISNULL(@TxnType, N'transactional') +
        N' entries. (Purchase Requests, BOMs, and Delivery notes are exempt.)';

    THROW 50001, @Msg, 1;
END;
GO

IF OBJECT_ID(N'[proj].[sp_AssertJobOpen]') IS NOT NULL DROP PROCEDURE [proj].[sp_AssertJobOpen];
GO
-- Same fix for the job-open guard so a closed/freezed job also aborts the
-- parent INSERT, not just shows a message.
CREATE   PROCEDURE proj.sp_AssertJobOpen
    @JobId NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @StatusName NVARCHAR(50), @IsClosed BIT;
    SELECT  @StatusName = js.StatusName,
            @IsClosed   = js.IsClosed
    FROM    proj.TBL_JOB j
    JOIN    proj.TBL_JOB_STATUS js ON js.JobStatusId = j.JobStatusId
    WHERE   j.JobId = @JobId;

    IF @StatusName IS NULL
    BEGIN
        DECLARE @NotFound NVARCHAR(200) = N'Job ' + @JobId + N' not found.';
        THROW 50002, @NotFound, 1;
    END

    IF @IsClosed = 1
    BEGIN
        DECLARE @msg NVARCHAR(500) =
            N'Job ' + @JobId + N' is ' + @StatusName +
            N'. No new transactions (PR, PO, GRN, Issue, Invoice, Manhour, etc.) can be created. Revise the job to reopen it first.';
        THROW 50003, @msg, 1;
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_AutoCreditHoldCheck]') IS NOT NULL DROP PROCEDURE [proj].[sp_AutoCreditHoldCheck];
GO

CREATE PROCEDURE proj.sp_AutoCreditHoldCheck
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH Alloc AS (
        SELECT a.InvoiceId,
               SUM(CASE WHEN a.IsActive=1 THEN a.AllocatedAmount ELSE 0 END) AS RvPaid
        FROM proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
        JOIN proj.TBL_RECEIPT_VOUCHER rv ON a.RvId = rv.RvId
        WHERE rv.Status = 'Approved' AND rv.IsActive = 1 GROUP BY a.InvoiceId
    ),
    CnAlloc AS (
        SELECT a.InvoiceId,
               SUM(CASE WHEN a.IsActive=1 THEN a.AllocatedAmount ELSE 0 END) AS CnPaid
        FROM proj.TBL_CREDIT_NOTE_ALLOCATION a
        JOIN proj.TBL_CREDIT_NOTE cn ON a.CnId = cn.CnId
        WHERE cn.Status = 'Approved' AND cn.IsActive = 1 GROUP BY a.InvoiceId
    ),
    InvCalc AS (
        SELECT
            i.CustomerId,
            i.TotalAmount * ISNULL(i.ExchangeRate, 1)
                - ISNULL(al.RvPaid,0) - ISNULL(cn.CnPaid,0)  AS PendingAmtBase,
            CASE
                WHEN i.DueDate IS NOT NULL THEN i.DueDate
                WHEN c.CreditDays > 0      THEN DATEADD(DAY, ISNULL(c.CreditDays,0), CAST(i.InvoiceDate AS DATE))
                ELSE NULL
            END AS EffectiveDueDate
        FROM proj.TBL_INVOICE i
        JOIN proj.TBL_CUSTOMER c ON c.CustomerId = i.CustomerId
        LEFT JOIN Alloc   al ON al.InvoiceId = i.InvoiceId
        LEFT JOIN CnAlloc cn ON cn.InvoiceId = i.InvoiceId
        WHERE i.IsActive = 1 AND i.Status NOT IN ('Draft','Cancelled')
    ),
    CustBalance AS (
        SELECT
            CustomerId,
            ISNULL(SUM(PendingAmtBase), 0)  AS OutstandingBalance,
            ISNULL(MAX(CASE
                WHEN EffectiveDueDate IS NOT NULL
                 AND EffectiveDueDate < CAST(GETDATE() AS DATE)
                 AND PendingAmtBase > 0
                THEN DATEDIFF(DAY, EffectiveDueDate, GETDATE())
                ELSE 0 END), 0)              AS MaxOverdueDays
        FROM InvCalc
        GROUP BY CustomerId
    ),
    CustCheck AS (
        SELECT
            c.CustomerId,
            c.CreditHold,
            c.AutoHold,
            ISNULL(c.CreditLimit, 0)        AS CreditLimit,
            ISNULL(c.CreditDays,  0)        AS CreditDays,
            ISNULL(b.OutstandingBalance, 0) AS OutstandingBalance,
            ISNULL(b.MaxOverdueDays, 0)     AS MaxOverdueDays,
            CAST(CASE
                WHEN ISNULL(c.CreditLimit,0) > 0
                 AND ISNULL(b.OutstandingBalance,0) > c.CreditLimit   THEN 1
                WHEN ISNULL(c.CreditDays,0) > 0
                 AND ISNULL(b.MaxOverdueDays,0) > c.CreditDays        THEN 1
                ELSE 0 END AS BIT) AS ShouldHold
        FROM proj.TBL_CUSTOMER c
        LEFT JOIN CustBalance b ON b.CustomerId = c.CustomerId
        WHERE c.IsActive = 1
    )

    UPDATE c SET
        CreditHold     = 1,
        AutoHold       = 1,
        CreditHoldBy   = 'SYSTEM',
        CreditHoldDate = GETDATE(),
        CreditHoldNote = CASE
            WHEN cc.CreditLimit > 0 AND cc.OutstandingBalance > cc.CreditLimit
                THEN 'Auto: Outstanding ' + FORMAT(cc.OutstandingBalance,'N2') +
                     ' exceeds credit limit ' + FORMAT(cc.CreditLimit,'N2')
            ELSE 'Auto: Invoice overdue by ' + CAST(cc.MaxOverdueDays AS NVARCHAR) + ' days'
        END,
        ModifiedBy   = 'SYSTEM',
        ModifiedDate = GETDATE()
    FROM proj.TBL_CUSTOMER c
    JOIN CustCheck cc ON cc.CustomerId = c.CustomerId
    WHERE cc.ShouldHold = 1 AND c.CreditHold = 0;

    UPDATE c SET
        CreditHold     = 0,
        AutoHold       = 0,
        CreditHoldBy   = NULL,
        CreditHoldDate = NULL,
        CreditHoldNote = NULL,
        ModifiedBy     = 'SYSTEM',
        ModifiedDate   = GETDATE()
    FROM proj.TBL_CUSTOMER c
    JOIN CustCheck cc ON cc.CustomerId = c.CustomerId
    WHERE cc.ShouldHold = 0 AND c.CreditHold = 1 AND c.AutoHold = 1;

    SELECT
        SUM(CASE WHEN cc.ShouldHold=1 AND c.CreditHold=0  THEN 1 ELSE 0 END) AS NewHolds,
        SUM(CASE WHEN cc.ShouldHold=0 AND c.CreditHold=1
                  AND c.AutoHold=1                         THEN 1 ELSE 0 END) AS Released
    FROM proj.TBL_CUSTOMER c
    JOIN CustCheck cc ON cc.CustomerId = c.CustomerId
    WHERE c.IsActive = 1;
END
GO

IF OBJECT_ID(N'[proj].[sp_BacklogBomToPr]') IS NOT NULL DROP PROCEDURE [proj].[sp_BacklogBomToPr];
GO

CREATE PROCEDURE proj.sp_BacklogBomToPr
    @JobId    NVARCHAR(50) = NULL,
    @Critical BIT          = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        bh.BomHeaderId, bd.JobId, j.ProjectName, bs.SectionName,
        i.ItemCode, i.ItemName, u.UomCode AS UomName,
        bd.BomRequestedQty, bd.PrCreatedQty,
        ROUND(bd.BomRequestedQty - bd.PrCreatedQty, 4)              AS PendingQty,
        bd.BomPrice,
        ROUND((bd.BomRequestedQty - bd.PrCreatedQty) * bd.BomPrice, 2) AS PendingValue,
        bd.BomStatus AS LineStatus, bd.IsCritical, bd.ItemReqDate, bd.ExpectedDelivery, bd.Remarks
    FROM  proj.TBL_BOM_DETAILS  bd
    JOIN  proj.TBL_BOM_HEADER   bh ON bh.BomHeaderId  = bd.BomHeaderId
    JOIN  proj.TBL_BOM_SECTION  bs ON bs.BomSectionId = bd.BomSectionId
    JOIN  proj.TBL_ITEM          i ON i.ItemId         = bd.ItemId
    LEFT JOIN proj.TBL_ITEM_UOM  u ON u.UomId          = bd.UomId
    LEFT JOIN proj.TBL_JOB       j ON j.JobId           = bd.JobId
    WHERE bd.IsActive = 1
      AND bh.IsActive = 1
      AND bh.BomStatus = 'Approved'
      AND bd.BomRequestedQty > bd.PrCreatedQty
      AND ISNULL(i.IsPurchasable, 1) = 1          -- service items (manhours/design) never procured
      AND (@JobId    IS NULL OR bd.JobId      = @JobId)
      AND (@Critical IS NULL OR bd.IsCritical = @Critical)
    ORDER BY bd.JobId, bs.SortOrder, bd.SortOrder;
END
GO

IF OBJECT_ID(N'[proj].[sp_BacklogPoToGrn]') IS NOT NULL DROP PROCEDURE [proj].[sp_BacklogPoToGrn];
GO

CREATE   PROCEDURE proj.sp_BacklogPoToGrn
    @JobId      NVARCHAR(50) = NULL,
    @SupplierId INT          = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        po.PoId,
        po.PoNumber,
        po.PoDate,
        po.SupplierId,
        s.SupplierName,
        po.JobId,
        j.ProjectName,
        po.Status          AS PoStatus,
        po.Priority,
        po.DeliveryDate,
        cur.ShortName      AS CurrencyShort,
        pol.PoLineId,
        pol.LineNum,
        pol.ItemCode,
        pol.ItemDesc,
        pol.UomName,
        pol.OrderedQty,
        pol.ReceivedQty,
        ROUND(pol.OrderedQty - pol.ReceivedQty, 4)                        AS PendingQty,
        pol.UnitPrice,
        ROUND((pol.OrderedQty - pol.ReceivedQty) * pol.UnitPrice, 2)      AS PendingValue
    FROM  proj.TBL_PURCHASE_ORDER_LINE pol
    JOIN  proj.TBL_PURCHASE_ORDER       po  ON po.PoId        = pol.PoId
    LEFT JOIN proj.TBL_SUPPLIER         s   ON s.SupplierId   = po.SupplierId
    LEFT JOIN proj.TBL_CURRENCY         cur ON cur.CurrencyId = po.CurrencyId
    LEFT JOIN proj.TBL_JOB              j   ON j.JobId         = po.JobId
    WHERE pol.IsActive = 1
      AND po.Status NOT IN ('Cancelled','Received')
      AND pol.OrderedQty > pol.ReceivedQty
      AND (@JobId      IS NULL OR po.JobId      = @JobId)
      AND (@SupplierId IS NULL OR po.SupplierId = @SupplierId)
    ORDER BY po.PoDate, po.PoNumber, pol.LineNum;
END
GO

IF OBJECT_ID(N'[proj].[sp_BacklogPrToPo]') IS NOT NULL DROP PROCEDURE [proj].[sp_BacklogPrToPo];
GO

CREATE   PROCEDURE proj.sp_BacklogPrToPo
    @JobId NVARCHAR(50) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        pr.PrId,
        pr.PrNumber,
        pr.PrDate,
        pr.JobId,
        j.ProjectName,
        pr.Priority,
        pr.Status          AS PrStatus,
        pl.PrLineId,
        pl.LineNum,
        pl.ItemCode,
        pl.ItemDesc,
        pl.UomName,
        pl.RequiredQty,
        pl.PoCreatedQty,
        ROUND(pl.RequiredQty - pl.PoCreatedQty, 4)                        AS PendingQty,
        pl.EstUnitPrice,
        ROUND((pl.RequiredQty - pl.PoCreatedQty) * pl.EstUnitPrice, 2)    AS PendingValue,
        pl.RequiredDate,
        pl.Remarks
    FROM  proj.TBL_PURCHASE_REQUEST_LINE pl
    JOIN  proj.TBL_PURCHASE_REQUEST      pr ON pr.PrId  = pl.PrId
    LEFT JOIN proj.TBL_JOB               j  ON j.JobId  = pr.JobId
    WHERE pl.IsActive = 1
      AND pr.Status NOT IN ('Cancelled','Rejected','Draft')
      AND pl.RequiredQty > pl.PoCreatedQty
      AND (@JobId IS NULL OR pr.JobId = @JobId)
    ORDER BY pr.PrDate, pr.PrNumber, pl.LineNum;
END
GO

IF OBJECT_ID(N'[proj].[sp_CancelCreditNote]') IS NOT NULL DROP PROCEDURE [proj].[sp_CancelCreditNote];
GO

CREATE   PROCEDURE proj.sp_CancelCreditNote
    @CnId         INT,
    @CancelledBy  NVARCHAR(100),
    @Reason       NVARCHAR(500) = NULL,
    @PasswordHash NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    BEGIN TRY
        DECLARE @Status NVARCHAR(20);
        SELECT @Status = Status FROM proj.TBL_CREDIT_NOTE WHERE CnId = @CnId AND IsActive = 1;

        IF @Status IS NULL       THROW 51000, 'Credit note not found.', 1;
        IF @Status <> 'Approved' THROW 51000, 'Only Approved credit notes can be cancelled.', 1;

        IF NULLIF(LTRIM(RTRIM(ISNULL(@Reason, ''))), '') IS NULL
            THROW 51000, 'A reason is required to cancel an approved credit note.', 1;
        IF NULLIF(@PasswordHash, '') IS NULL
            THROW 51000, 'Password is required.', 1;

        IF NOT EXISTS (
            SELECT 1
            FROM   proj.TBL_USER_ROLES  ur
            JOIN   proj.TBL_ROLE_SECRET rs ON rs.RoleId  = ur.RoleId
            JOIN   proj.TBL_USERS       u  ON u.UserId   = ur.UserId
            WHERE  u.Username         = @CancelledBy
              AND  rs.SecretKey       = 'RV_REVISE'
              AND  rs.SecretValueHash = @PasswordHash
        )
            THROW 51000, 'Incorrect password. You do not have permission to cancel this credit note.', 1;

        -- Capture jobs affected by this CN's active allocations BEFORE removing them
        DECLARE @Jobs TABLE (JobId NVARCHAR(50) PRIMARY KEY);
        INSERT INTO @Jobs (JobId)
        SELECT DISTINCT i.JobId
        FROM   proj.TBL_CREDIT_NOTE_ALLOCATION a
        JOIN   proj.TBL_INVOICE i ON i.InvoiceId = a.InvoiceId
        WHERE  a.CnId = @CnId AND a.IsActive = 1 AND NULLIF(i.JobId,'') IS NOT NULL;

        UPDATE proj.TBL_CREDIT_NOTE_ALLOCATION
        SET    IsActive     = 0,
               ModifiedBy   = @CancelledBy,
               ModifiedDate = GETDATE()
        WHERE  CnId = @CnId AND IsActive = 1;

        UPDATE proj.TBL_CREDIT_NOTE
        SET    Status          = 'Cancelled',
               AllocatedAmount = 0,
               CancelReason    = @Reason,
               CancelledBy     = @CancelledBy,
               CancelledDate   = GETDATE(),
               ModifiedBy      = @CancelledBy,
               ModifiedDate    = GETDATE()
        WHERE  CnId = @CnId;

        DECLARE @ModId INT;
        SELECT @ModId = ModuleId FROM proj.TBL_APPROVAL_MODULE WHERE ModuleCode = 'CN';

        UPDATE proj.TBL_APPROVAL_TRANSACTION
        SET    CurrentStatus = 'Cancelled',
               FinalAction   = 'Cancelled',
               FinalActionBy = @CancelledBy,
               FinalRemarks  = ISNULL(FinalRemarks + ' | ', '') + 'Cancelled — ' + @Reason,
               CompletedDate = GETDATE(),
               ModifiedBy    = @CancelledBy,
               ModifiedDate  = GETDATE()
        WHERE  ModuleId      = @ModId
          AND  DocumentId    = @CnId
          AND  CurrentStatus NOT IN ('Cancelled', 'Rejected');

        -- Recalc job credit totals for every affected job
        DECLARE @J NVARCHAR(50);
        DECLARE jc CURSOR LOCAL FAST_FORWARD FOR SELECT JobId FROM @Jobs;
        OPEN jc; FETCH NEXT FROM jc INTO @J;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            EXEC proj.sp_RecalcJobCredits @J, @CancelledBy;
            FETCH NEXT FROM jc INTO @J;
        END
        CLOSE jc; DEALLOCATE jc;

        COMMIT;
        SELECT @CnId AS CnId, 'Cancelled' AS Status;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        DECLARE @msg NVARCHAR(2048) = ERROR_MESSAGE();
        THROW 51000, @msg, 1;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_CancelDebitNote]') IS NOT NULL DROP PROCEDURE [proj].[sp_CancelDebitNote];
