        DECLARE @Status NVARCHAR(20);
        SELECT @Status = Status FROM proj.TBL_DEBIT_NOTE WHERE DnId = @DnId AND IsActive = 1;

        IF @Status IS NULL       THROW 51000, 'Debit note not found.', 1;
        IF @Status <> 'Approved' THROW 51000, 'Only Approved debit notes can be cancelled.', 1;

        IF NULLIF(LTRIM(RTRIM(ISNULL(@Reason, ''))), '') IS NULL
            THROW 51000, 'A reason is required to cancel an approved debit note.', 1;
        IF NULLIF(@PasswordHash, '') IS NULL
            THROW 51000, 'Password is required.', 1;

        IF NOT EXISTS (
            SELECT 1
            FROM   proj.TBL_USER_ROLES  ur
            JOIN   proj.TBL_ROLE_SECRET rs ON rs.RoleId  = ur.RoleId
            JOIN   proj.TBL_USERS       u  ON u.UserId   = ur.UserId
            WHERE  u.Username         = @CancelledBy
              AND  rs.SecretKey       = 'PV_REVISE'
              AND  rs.SecretValueHash = @PasswordHash
        )
            THROW 51000, 'Incorrect password. You do not have permission to cancel this debit note.', 1;

        UPDATE proj.TBL_DEBIT_NOTE_ALLOCATION
        SET    IsActive     = 0,
               ModifiedBy   = @CancelledBy,
               ModifiedDate = GETDATE()
        WHERE  DnId = @DnId AND IsActive = 1;

        UPDATE proj.TBL_DEBIT_NOTE
        SET    Status          = 'Cancelled',
               AllocatedAmount = 0,
               CancelReason    = @Reason,
               CancelledBy     = @CancelledBy,
               CancelledDate   = GETDATE(),
               ModifiedBy      = @CancelledBy,
               ModifiedDate    = GETDATE()
        WHERE  DnId = @DnId;

        DECLARE @ModId INT;
        SELECT @ModId = ModuleId FROM proj.TBL_APPROVAL_MODULE WHERE ModuleCode = 'DN';

        UPDATE proj.TBL_APPROVAL_TRANSACTION
        SET    CurrentStatus = 'Cancelled',
               FinalAction   = 'Cancelled',
               FinalActionBy = @CancelledBy,
               FinalRemarks  = ISNULL(FinalRemarks + ' | ', '') + 'Cancelled — ' + @Reason,
               CompletedDate = GETDATE(),
               ModifiedBy    = @CancelledBy,
               ModifiedDate  = GETDATE()
        WHERE  ModuleId      = @ModId
          AND  DocumentId    = @DnId
          AND  CurrentStatus NOT IN ('Cancelled', 'Rejected');

        COMMIT;
        SELECT @DnId AS DnId, 'Cancelled' AS Status;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        DECLARE @msg NVARCHAR(2048) = ERROR_MESSAGE();
        THROW 51000, @msg, 1;
    END CATCH
END
