IF OBJECT_ID(N'[proj].[sp_CancelGRN]') IS NOT NULL DROP PROCEDURE [proj].[sp_CancelGRN];
GO

CREATE PROCEDURE proj.sp_CancelGRN
    @GrnId        INT,
    @CancelledBy  NVARCHAR(100),
    @Reason       NVARCHAR(1000),
    @PasswordHash NVARCHAR(500)
AS
BEGIN
    SET NOCOUNT ON;

    IF LTRIM(RTRIM(ISNULL(@Reason, ''))) = ''
        RAISERROR('A cancellation reason is required.', 16, 1);

    IF NOT EXISTS (
        SELECT 1 FROM proj.TBL_USERS
        WHERE UserName = @CancelledBy AND PasswordHash = @PasswordHash AND IsActive = 1
    )
        RAISERROR('Incorrect password. Cancellation not authorised.', 16, 1);

    DECLARE @CurrentStatus NVARCHAR(30), @GrnNumber NVARCHAR(50),
            @GrnDate DATE, @ReceivedDate DATE, @JobId NVARCHAR(50),
            @PoId INT, @SupplierId INT;

    SELECT @CurrentStatus = g.Status,  @GrnNumber   = g.GrnNumber,
           @GrnDate       = g.GrnDate, @ReceivedDate = g.ReceivedDate,
           @JobId         = g.JobId,   @PoId         = g.PoId,
           @SupplierId    = g.SupplierId
    FROM   proj.TBL_GRN_HEADER g
    WHERE  g.GrnId = @GrnId AND g.IsActive = 1;

    IF @CurrentStatus IS NULL  RAISERROR('GRN not found.', 16, 1);
    IF @CurrentStatus = 'Cancelled' RAISERROR('This GRN is already cancelled.', 16, 1);
    IF @CurrentStatus NOT IN ('Draft', 'Received')
        RAISERROR('Only Draft or Received GRNs can be cancelled.', 16, 1);

    BEGIN TRANSACTION;
    BEGIN TRY

        IF @CurrentStatus = 'Received'
        BEGIN
            -- Reverse PO line ReceivedQty
            UPDATE pol
            SET    pol.ReceivedQty  = CASE
                       WHEN ISNULL(pol.ReceivedQty,0) - (d.ReceivedQty - ISNULL(d.RejectedQty,0)) < 0
                       THEN 0
                       ELSE ISNULL(pol.ReceivedQty,0) - (d.ReceivedQty - ISNULL(d.RejectedQty,0))
                   END,
                   pol.ModifiedBy   = @CancelledBy,
                   pol.ModifiedDate = GETDATE()
            FROM   proj.TBL_PURCHASE_ORDER_LINE pol
            JOIN   proj.TBL_GRN_DETAIL d ON d.PoLineId = pol.PoLineId
            WHERE  d.GrnId = @GrnId AND d.IsActive = 1 AND d.PoLineId IS NOT NULL;

            -- Revert PO line LineStatus
            UPDATE pol
            SET    pol.LineStatus = CASE
                       WHEN pol.ReceivedQty >= pol.OrderedQty THEN 'Received'
                       WHEN pol.ReceivedQty  > 0              THEN 'Partial'
                       ELSE 'Open'
                   END,
                   pol.ModifiedBy   = @CancelledBy,
                   pol.ModifiedDate = GETDATE()
            FROM   proj.TBL_PURCHASE_ORDER_LINE pol
            JOIN   proj.TBL_GRN_DETAIL d ON d.PoLineId = pol.PoLineId
            WHERE  d.GrnId = @GrnId AND d.IsActive = 1 AND d.PoLineId IS NOT NULL
              AND  pol.LineStatus NOT IN ('Closed', 'Cancelled');

            -- Revert PO header status
            IF NULLIF(@PoId, 0) IS NOT NULL
            BEGIN
                UPDATE po
                SET    po.Status = CASE
                           WHEN EXISTS (
                               SELECT 1 FROM proj.TBL_PURCHASE_ORDER_LINE
                               WHERE PoId = @PoId AND IsActive = 1 AND ReceivedQty > 0
                           ) THEN 'Partial'
                           ELSE 'Approved'
                       END,
                       po.ModifiedBy   = @CancelledBy,
                       po.ModifiedDate = GETDATE()
                FROM   proj.TBL_PURCHASE_ORDER po
                WHERE  po.PoId = @PoId AND po.Status NOT IN ('Cancelled', 'Closed', 'Draft');
            END

            -- Reverse BOM received qty + recalculate BomStatus
            UPDATE bom
            SET    bom.BomReceivedQty = v.NewQty,
                   bom.BomStatus = CASE
                       WHEN v.NewQty >= bom.BomRequestedQty                THEN 'FullyReceived'
                       WHEN v.NewQty  > 0                                  THEN 'PartialReceived'
                       WHEN bom.PoCreatedQty >= bom.BomRequestedQty        THEN 'PORaised'
                       WHEN bom.PoCreatedQty  > 0                          THEN 'POPartial'
                       WHEN bom.PrCreatedQty >= bom.BomRequestedQty        THEN 'PRRaised'
                       WHEN bom.PrCreatedQty  > 0                          THEN 'PRPartial'
                       ELSE 'Pending'
                   END,
                   bom.ModifiedBy   = @CancelledBy,
                   bom.ModifiedDate = GETDATE()
            FROM   proj.TBL_BOM_DETAILS bom
            JOIN   proj.TBL_PURCHASE_REQUEST_LINE prl ON prl.BomDetailId = bom.BomId
            JOIN   proj.TBL_GRN_DETAIL d ON d.PrLineId = prl.PrLineId
            CROSS APPLY (VALUES (
                CASE WHEN ISNULL(bom.BomReceivedQty,0) - (d.ReceivedQty - ISNULL(d.RejectedQty,0)) < 0
                     THEN CAST(0 AS DECIMAL(18,4))
                     ELSE ISNULL(bom.BomReceivedQty,0) - (d.ReceivedQty - ISNULL(d.RejectedQty,0))
                END
            )) v(NewQty)
            WHERE  d.GrnId = @GrnId AND d.IsActive = 1 AND d.PrLineId IS NOT NULL;

            -- Reverse stock balance & create reversal ledger entries
            DECLARE @RItemId INT, @RQtyIn DECIMAL(18,4), @RUnitCost DECIMAL(18,4),
                    @RIsJobStock BIT, @RJobId NVARCHAR(50);

            DECLARE cur CURSOR LOCAL FAST_FORWARD FOR
                SELECT ItemId, QtyIn, UnitCost, IsJobStock, JobId
                FROM   proj.TBL_STOCK_LEDGER
                WHERE  TransType = 'GRN' AND RefId = @GrnId AND QtyIn > 0;

            OPEN cur;
            FETCH NEXT FROM cur INTO @RItemId, @RQtyIn, @RUnitCost, @RIsJobStock, @RJobId;
            WHILE @@FETCH_STATUS = 0
            BEGIN
                UPDATE proj.TBL_STOCK_BALANCE
                SET    QtyOnHand   = CASE WHEN ISNULL(QtyOnHand,0) - @RQtyIn < 0 THEN 0 ELSE ISNULL(QtyOnHand,0) - @RQtyIn END,
                       QtyJobStock = CASE WHEN @RIsJobStock = 1
                                          THEN CASE WHEN ISNULL(QtyJobStock,0) - @RQtyIn < 0 THEN 0 ELSE ISNULL(QtyJobStock,0) - @RQtyIn END
                                          ELSE QtyJobStock END,
                       UpdatedDate = GETDATE()
                WHERE  ItemId = @RItemId;

                INSERT INTO proj.TBL_STOCK_LEDGER
                    (ItemId, TransDate, TransType, RefId, RefNo, QtyIn, QtyOut, UnitCost, IsJobStock, JobId, CreatedBy)
                VALUES
                    (@RItemId, GETDATE(), 'GRN-REV', @GrnId, @GrnNumber, 0, @RQtyIn, @RUnitCost, @RIsJobStock, @RJobId, @CancelledBy);

                FETCH NEXT FROM cur INTO @RItemId, @RQtyIn, @RUnitCost, @RIsJobStock, @RJobId;
            END
            CLOSE cur; DEALLOCATE cur;

            UPDATE proj.TBL_STOCK_RECEIPT
            SET    IsActive = 0, Status = 'Cancelled',
                   ModifiedBy = @CancelledBy, ModifiedDate = GETDATE()
            WHERE  GrnId = @GrnId AND IsActive = 1;

            UPDATE rl
            SET    rl.IsActive = 0, rl.ModifiedBy = @CancelledBy, rl.ModifiedDate = GETDATE()
            FROM   proj.TBL_STOCK_RECEIPT_LINE rl
            JOIN   proj.TBL_STOCK_RECEIPT r ON r.ReceiptId = rl.ReceiptId
            WHERE  r.GrnId = @GrnId;
        END

        UPDATE proj.TBL_GRN_HEADER
        SET    Status       = 'Cancelled',
               Remarks      = CASE
                                  WHEN NULLIF(LTRIM(RTRIM(Remarks)), '') IS NULL
                                  THEN 'Cancelled: ' + @Reason
                                  ELSE Remarks + ' | Cancelled: ' + @Reason
                              END,
               ModifiedBy   = @CancelledBy,
               ModifiedDate = GETDATE()
        WHERE  GrnId = @GrnId AND IsActive = 1;

        COMMIT;
        SELECT CAST(@GrnId AS NVARCHAR(20));
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        THROW;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_CancelInvoice]') IS NOT NULL DROP PROCEDURE [proj].[sp_CancelInvoice];
GO

CREATE   PROCEDURE PROJ.sp_CancelInvoice
    @InvoiceId  INT,
    @ModifiedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM PROJ.TBL_INVOICE WHERE InvoiceId = @InvoiceId AND Status = 'Draft' AND IsActive = 1)
        RAISERROR('Only Draft invoices can be cancelled.', 16, 1);

    UPDATE PROJ.TBL_INVOICE
    SET Status = 'Cancelled', ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE()
    WHERE InvoiceId = @InvoiceId;

    SELECT InvoiceNo, Status FROM PROJ.TBL_INVOICE WHERE InvoiceId = @InvoiceId;
END;
GO

IF OBJECT_ID(N'[proj].[sp_CancelPaymentVoucher]') IS NOT NULL DROP PROCEDURE [proj].[sp_CancelPaymentVoucher];
GO

-- ── sp_CancelPaymentVoucher ───────────────────────────────────────────────────
CREATE PROCEDURE proj.sp_CancelPaymentVoucher
    @PvId         INT,
    @CancelledBy  NVARCHAR(100),
    @Reason       NVARCHAR(500) = NULL,
    @PasswordHash NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    BEGIN TRY
        DECLARE @Status NVARCHAR(20);
        SELECT @Status = Status FROM proj.TBL_PAYMENT_VOUCHER WHERE PvId = @PvId AND IsActive = 1;
        IF @Status IS NULL       THROW 51000,'Payment voucher not found.',1;
        IF @Status <> 'Approved' THROW 51000,'Only Approved payment vouchers can be cancelled.',1;
        IF NULLIF(LTRIM(RTRIM(ISNULL(@Reason,''))),   '') IS NULL THROW 51000,'A reason is required.',1;
        IF NULLIF(@PasswordHash,'') IS NULL THROW 51000,'Password is required.',1;

        IF NOT EXISTS (
            SELECT 1 FROM proj.TBL_USER_ROLES ur
            JOIN proj.TBL_ROLE_SECRET rs ON rs.RoleId  = ur.RoleId
            JOIN proj.TBL_USERS       u  ON u.UserId   = ur.UserId
            WHERE u.Username = @CancelledBy AND rs.SecretKey = 'PV_REVISE' AND rs.SecretValueHash = @PasswordHash
        ) THROW 51000,'Incorrect password.',1;

        -- Reverse all allocations
        UPDATE proj.TBL_PAYMENT_VOUCHER_ALLOCATION
        SET    IsActive = 0, ModifiedBy = @CancelledBy, ModifiedDate = GETDATE()
        WHERE  PvId = @PvId AND IsActive = 1;

        DECLARE @ModId INT;
        SELECT @ModId = ModuleId FROM proj.TBL_APPROVAL_MODULE WHERE ModuleCode = 'PV';

        UPDATE proj.TBL_PAYMENT_VOUCHER
        SET    Status = 'Cancelled', AllocatedAmount = 0, CancelReason = @Reason,
               ModifiedBy = @CancelledBy, ModifiedDate = GETDATE()
        WHERE  PvId = @PvId;

        UPDATE proj.TBL_APPROVAL_TRANSACTION
        SET    CurrentStatus = 'Cancelled', FinalAction = 'Cancelled', FinalActionBy = @CancelledBy,
               FinalRemarks = ISNULL(FinalRemarks+' | ','')+'Cancelled — '+@Reason,
               CompletedDate = GETDATE(), ModifiedBy = @CancelledBy, ModifiedDate = GETDATE()
        WHERE  ModuleId = @ModId AND DocumentId = @PvId
          AND  CurrentStatus NOT IN ('Cancelled','Rejected');

        COMMIT;
        SELECT @PvId AS PvId, 'Cancelled' AS Status;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        DECLARE @msg NVARCHAR(2048) = ERROR_MESSAGE();
        THROW 51000, @msg, 1;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_CancelReceiptVoucher]') IS NOT NULL DROP PROCEDURE [proj].[sp_CancelReceiptVoucher];
GO

CREATE PROCEDURE proj.sp_CancelReceiptVoucher
    @RvId         INT,
    @CancelledBy  NVARCHAR(100),
    @Reason       NVARCHAR(500) = NULL,
    @PasswordHash NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    BEGIN TRY
        -- ── Guards ───────────────────────────────────────────────────────────
        DECLARE @Status NVARCHAR(20);
        SELECT @Status = Status
        FROM   proj.TBL_RECEIPT_VOUCHER
        WHERE  RvId = @RvId AND IsActive = 1;

        IF @Status IS NULL       THROW 51000, 'Receipt voucher not found.', 1;
        IF @Status <> 'Approved' THROW 51000, 'Only Approved receipt vouchers can be cancelled.', 1;

        IF NULLIF(LTRIM(RTRIM(ISNULL(@Reason, ''))), '') IS NULL
            THROW 51000, 'A reason is required to cancel an approved receipt voucher.', 1;

        IF NULLIF(@PasswordHash, '') IS NULL
            THROW 51000, 'Password is required.', 1;

        IF NOT EXISTS (
            SELECT 1
            FROM   proj.TBL_USER_ROLES  ur
            JOIN   proj.TBL_ROLE_SECRET rs ON rs.RoleId  = ur.RoleId
            JOIN   proj.TBL_USERS       u  ON u.UserId   = ur.UserId
            WHERE  u.Username         = @CancelledBy
              AND  rs.SecretKey       = 'RV_REVISE'
              AND  rs.SecretValueHash = @PasswordHash
        )
            THROW 51000, 'Incorrect password. You do not have permission to cancel this receipt voucher.', 1;

        -- ── 1. Soft-delete every active allocation ────────────────────────
        UPDATE proj.TBL_RECEIPT_VOUCHER_ALLOCATION
        SET    IsActive     = 0,
               ModifiedBy   = @CancelledBy,
               ModifiedDate = GETDATE()
        WHERE  RvId = @RvId AND IsActive = 1;

        -- ── 2. Mark header Cancelled ──────────────────────────────────────
        UPDATE proj.TBL_RECEIPT_VOUCHER
        SET    Status          = 'Cancelled',
               AllocatedAmount = 0,
               CancelReason    = @Reason,
               ModifiedBy      = @CancelledBy,
               ModifiedDate    = GETDATE()
        WHERE  RvId = @RvId;

        -- ── 3. Cancel open approval transaction ───────────────────────────
        DECLARE @ModId INT;
        SELECT @ModId = ModuleId FROM proj.TBL_APPROVAL_MODULE WHERE ModuleCode = 'RV';

        UPDATE proj.TBL_APPROVAL_TRANSACTION
        SET    CurrentStatus = 'Cancelled',
               FinalAction   = 'Cancelled',
               FinalActionBy = @CancelledBy,
               FinalRemarks  = ISNULL(FinalRemarks + ' | ', '') + 'Cancelled — ' + @Reason,
               CompletedDate = GETDATE(),
               ModifiedBy    = @CancelledBy,
               ModifiedDate  = GETDATE()
        WHERE  ModuleId      = @ModId
          AND  DocumentId    = @RvId
          AND  CurrentStatus NOT IN ('Cancelled', 'Rejected');

        -- ── 4. Recalculate job payments ───────────────────────────────────
        DECLARE @JobId NVARCHAR(50);
        DECLARE jc CURSOR LOCAL FAST_FORWARD FOR
            SELECT DISTINCT i.JobId
            FROM   proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
            JOIN   proj.TBL_INVOICE i ON i.InvoiceId = a.InvoiceId
            WHERE  a.RvId = @RvId AND NULLIF(i.JobId, '') IS NOT NULL;

        OPEN jc; FETCH NEXT FROM jc INTO @JobId;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            EXEC proj.sp_RecalcJobPayments @JobId, @CancelledBy;
            FETCH NEXT FROM jc INTO @JobId;
        END
        CLOSE jc; DEALLOCATE jc;

        COMMIT;
        SELECT @RvId AS RvId, 'Cancelled' AS Status;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        IF CURSOR_STATUS('local', 'jc') >= 0 BEGIN CLOSE jc; DEALLOCATE jc; END
        DECLARE @msg NVARCHAR(2048) = ERROR_MESSAGE();
        THROW 51000, @msg, 1;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_CancelStockIssue]') IS NOT NULL DROP PROCEDURE [proj].[sp_CancelStockIssue];
GO

CREATE   PROCEDURE proj.sp_CancelStockIssue
    @IssueId    INT,
    @ModifiedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        -- Only a Draft note can be cancelled. A Confirmed note has already moved
        -- stock and must be reversed via an Issue Return, not cancelled.
        IF NOT EXISTS (
            SELECT 1 FROM proj.TBL_STOCK_ISSUE
            WHERE IssueId = @IssueId AND IsActive = 1)
            THROW 50310, 'Issue Note not found.', 1;

        DECLARE @Status NVARCHAR(30);
        SELECT @Status = Status FROM proj.TBL_STOCK_ISSUE WHERE IssueId = @IssueId;

        IF @Status = 'Cancelled'
            THROW 50311, 'Issue Note is already cancelled.', 1;

        IF @Status <> 'Draft'
            THROW 50312, 'Only Draft Issue Notes can be cancelled. Use an Issue Return to reverse a confirmed note.', 1;

        UPDATE proj.TBL_STOCK_ISSUE
        SET Status = N'Cancelled', ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE()
        WHERE IssueId = @IssueId;

        DECLARE @IssueNo NVARCHAR(30);
        SELECT @IssueNo = IssueNo FROM proj.TBL_STOCK_ISSUE WHERE IssueId = @IssueId;
        SELECT @IssueNo AS IssueNo, N'Cancelled' AS Status;
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_CancelStockReceipt]') IS NOT NULL DROP PROCEDURE [proj].[sp_CancelStockReceipt];
GO
CREATE PROCEDURE proj.sp_CancelStockReceipt
    @ReceiptId    INT,
    @CancelledBy  NVARCHAR(100),
    @Reason       NVARCHAR(1000),
    @PasswordHash NVARCHAR(500) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF LTRIM(RTRIM(ISNULL(@Reason, ''))) = ''
        RAISERROR('A cancellation reason is required.', 16, 1);

    -- Authorisation: voiding un-posts stock, so require the user's password.
    IF NULLIF(@CancelledBy,'') IS NULL
        RAISERROR('User is required to cancel.', 16, 1);
    IF NOT EXISTS (SELECT 1 FROM proj.TBL_USERS
                   WHERE UserName = @CancelledBy AND PasswordHash = @PasswordHash AND IsActive = 1)
        RAISERROR('Incorrect password. Cancellation not authorised.', 16, 1);

    DECLARE @Status NVARCHAR(30), @ReceiptNo NVARCHAR(30), @GrnId INT;
    SELECT @Status = Status, @ReceiptNo = ReceiptNo, @GrnId = GrnId
    FROM   proj.TBL_STOCK_RECEIPT
    WHERE  ReceiptId = @ReceiptId AND IsActive = 1;

    IF @Status IS NULL
        RAISERROR('Stock receipt not found or already cancelled.', 16, 1);
    IF @Status = 'Cancelled'
        RAISERROR('This stock receipt is already cancelled.', 16, 1);
    IF @GrnId IS NOT NULL
        RAISERROR('This receipt belongs to a GRN. Cancel or unregister the GRN instead.', 16, 1);

    BEGIN TRANSACTION;
    BEGIN TRY

        IF @Status = 'Confirmed'
        BEGIN
            DECLARE @NegItems NVARCHAR(1000) = '';
            SELECT @NegItems = @NegItems +
                   ISNULL(it.ItemCode, 'Item#' + CAST(rev.ItemId AS NVARCHAR)) +
                   ' (balance=' + CAST(ISNULL(sb.QtyOnHand,0) AS NVARCHAR) +
                   ', reverse=' + CAST(rev.QtyIn AS NVARCHAR) + ') '
            FROM (
                    SELECT ItemId, SUM(QtyIn) AS QtyIn
                    FROM   proj.TBL_STOCK_LEDGER
                    WHERE  TransType = 'RECEIPT' AND RefId = @ReceiptId AND QtyIn > 0
                    GROUP  BY ItemId
                 ) rev
            LEFT JOIN proj.TBL_STOCK_BALANCE sb ON sb.ItemId = rev.ItemId
            LEFT JOIN proj.TBL_ITEM          it ON it.ItemId = rev.ItemId
            WHERE ISNULL(sb.QtyOnHand,0) - rev.QtyIn < 0;

            IF LEN(@NegItems) > 0
            BEGIN
                DECLARE @NegMsg NVARCHAR(2000) =
                    'Cancellation blocked: stock would go negative — items from this receipt have already been consumed. '
                    + 'Use a Stock Adjustment to record the correction. Affected: ' + @NegItems;
                RAISERROR(@NegMsg, 16, 1);
            END

            DECLARE @RItemId INT, @RQtyIn DECIMAL(18,4), @RUnitCost DECIMAL(18,4),
                    @RIsJobStock BIT, @RJobId NVARCHAR(50);

            DECLARE cur CURSOR LOCAL FAST_FORWARD FOR
                SELECT ItemId, QtyIn, UnitCost, IsJobStock, JobId
                FROM   proj.TBL_STOCK_LEDGER
                WHERE  TransType = 'RECEIPT' AND RefId = @ReceiptId AND QtyIn > 0;

            OPEN cur;
            FETCH NEXT FROM cur INTO @RItemId, @RQtyIn, @RUnitCost, @RIsJobStock, @RJobId;
            WHILE @@FETCH_STATUS = 0
            BEGIN
                UPDATE proj.TBL_STOCK_BALANCE
                SET    QtyOnHand   = CASE WHEN ISNULL(QtyOnHand,0) - @RQtyIn < 0 THEN 0 ELSE ISNULL(QtyOnHand,0) - @RQtyIn END,
                       QtyJobStock = CASE WHEN @RIsJobStock = 1
                                          THEN CASE WHEN ISNULL(QtyJobStock,0) - @RQtyIn < 0 THEN 0 ELSE ISNULL(QtyJobStock,0) - @RQtyIn END
                                          ELSE QtyJobStock END,
                       UpdatedDate = GETDATE()
                WHERE  ItemId = @RItemId;

                INSERT INTO proj.TBL_STOCK_LEDGER
                    (ItemId, TransDate, TransType, RefId, RefNo, QtyIn, QtyOut, UnitCost, IsJobStock, JobId, CreatedBy)
                VALUES
                    (@RItemId, GETDATE(), 'RECEIPT-REV', @ReceiptId, @ReceiptNo, 0, @RQtyIn, @RUnitCost, @RIsJobStock, @RJobId, @CancelledBy);

                FETCH NEXT FROM cur INTO @RItemId, @RQtyIn, @RUnitCost, @RIsJobStock, @RJobId;
            END
            CLOSE cur; DEALLOCATE cur;
        END

        UPDATE proj.TBL_STOCK_RECEIPT
        SET    Status   = 'Cancelled',
               IsActive = 0,
               Notes    = CASE WHEN NULLIF(LTRIM(RTRIM(Notes)),'') IS NULL
                               THEN 'Cancelled: ' + @Reason
                               ELSE Notes + ' | Cancelled: ' + @Reason END,
               ModifiedBy   = @CancelledBy,
               ModifiedDate = GETDATE()
        WHERE  ReceiptId = @ReceiptId;

        UPDATE proj.TBL_STOCK_RECEIPT_LINE
        SET    IsActive = 0, ModifiedBy = @CancelledBy, ModifiedDate = GETDATE()
        WHERE  ReceiptId = @ReceiptId;

        COMMIT;
        SELECT @ReceiptNo AS ReceiptNo, 'Cancelled' AS Status;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        IF CURSOR_STATUS('local','cur') >= 0 BEGIN CLOSE cur; DEALLOCATE cur; END;
        THROW;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_CancelStockTransfer]') IS NOT NULL DROP PROCEDURE [proj].[sp_CancelStockTransfer];
GO

CREATE   PROCEDURE proj.sp_CancelStockTransfer
    @TransferId INT, @ModifiedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM proj.TBL_STOCK_TRANSFER WHERE TransferId=@TransferId AND Status='Draft' AND IsActive=1)
        THROW 50630, 'Only a Draft transfer can be cancelled.', 1;
    UPDATE proj.TBL_STOCK_TRANSFER
    SET Status='Cancelled', ModifiedBy=@ModifiedBy, ModifiedDate=GETDATE()
    WHERE TransferId=@TransferId;
    SELECT @TransferId AS TransferId, 'Cancelled' AS Status;
END;
GO

IF OBJECT_ID(N'[proj].[sp_ChangeDeliveryStatus]') IS NOT NULL DROP PROCEDURE [proj].[sp_ChangeDeliveryStatus];
GO
CREATE   PROCEDURE proj.sp_ChangeDeliveryStatus
    @DeliveryId INT,
    @NewStatus  NVARCHAR(20),
    @ActionBy   NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @CurrentStatus NVARCHAR(20), @JobId NVARCHAR(100);
    SELECT @CurrentStatus = Status, @JobId = JobId
    FROM proj.TBL_DELIVERY WHERE DeliveryId = @DeliveryId AND IsActive = 1;
    IF @CurrentStatus IS NULL BEGIN SELECT 'Delivery not found.'; RETURN; END

    IF NOT (
        (@CurrentStatus = 'Draft'      AND @NewStatus = 'Approved')   OR
        (@CurrentStatus = 'Approved'   AND @NewStatus = 'Dispatched') OR
        (@CurrentStatus = 'Dispatched' AND @NewStatus = 'Delivered')  OR
        (@CurrentStatus = 'Approved'   AND @NewStatus = 'Draft')
    )
    BEGIN SELECT 'Invalid status transition from ' + @CurrentStatus + ' to ' + @NewStatus; RETURN; END

    IF @NewStatus = 'Approved' AND NOT EXISTS (
        SELECT 1 FROM proj.TBL_DELIVERY_LINE WHERE DeliveryId = @DeliveryId AND IsActive = 1
    )
    BEGIN SELECT 'Cannot approve a delivery with no lines.'; RETURN; END

    -- ── Delivered-units cap: validate BEFORE mutating anything ───────────
    IF @NewStatus = 'Dispatched' AND NULLIF(@JobId, '') IS NOT NULL
    BEGIN
        DECLARE @Qty DECIMAL(18,2) = (
            SELECT ISNULL(SUM(Qty), 0) FROM proj.TBL_DELIVERY_LINE
            WHERE DeliveryId = @DeliveryId AND IsActive = 1);

        DECLARE @Total DECIMAL(18,2), @Delivered DECIMAL(18,2), @HasMeta BIT = 0;
        SELECT @HasMeta = 1, @Total = TotalUnits, @Delivered = ISNULL(DeliveredUnit, 0)
        FROM   proj.TBL_JOB_META WHERE JobId = @JobId;

        IF @HasMeta = 1 AND @Total IS NOT NULL AND (@Delivered + @Qty) > @Total
        BEGIN
            SELECT 'Cannot dispatch: this would make delivered units ('
                 + CAST(@Delivered + @Qty AS NVARCHAR(20))
                 + ') exceed the job total units (' + CAST(@Total AS NVARCHAR(20))
                 + '). Increase Total Units on the job meta first.';
            RETURN;
        END
    END

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE proj.TBL_DELIVERY SET Status = @NewStatus, ModifiedBy = @ActionBy, ModifiedDate = GETDATE()
        WHERE DeliveryId = @DeliveryId;

        -- On dispatch, add this delivery's total line qty to the linked job's delivered units.
        IF @NewStatus = 'Dispatched' AND NULLIF(@JobId, '') IS NOT NULL
        BEGIN
            UPDATE proj.TBL_JOB_META
            SET    DeliveredUnit = ISNULL(DeliveredUnit, 0) +
                       (SELECT ISNULL(SUM(Qty), 0) FROM proj.TBL_DELIVERY_LINE
                        WHERE DeliveryId = @DeliveryId AND IsActive = 1),
                   ModifiedBy    = @ActionBy,
                   ModifiedDate  = GETDATE()
            WHERE  JobId = @JobId;
        END

        COMMIT TRANSACTION;
        SELECT 'OK';
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        SELECT ERROR_MESSAGE();
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_ChangeGRNStatus]') IS NOT NULL DROP PROCEDURE [proj].[sp_ChangeGRNStatus];
GO

CREATE PROCEDURE proj.sp_ChangeGRNStatus
    @GrnId     INT,
    @NewStatus NVARCHAR(30),
    @ChangedBy NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    BEGIN TRY

        DECLARE @CurrentStatus NVARCHAR(30), @GrnNumber NVARCHAR(50),
                @GrnDate DATE, @ReceivedDate DATE, @JobId NVARCHAR(50),
                @PoId INT, @SupplierId INT;

        SELECT @CurrentStatus = g.Status, @GrnNumber = g.GrnNumber,
               @GrnDate = g.GrnDate, @ReceivedDate = g.ReceivedDate,
               @JobId = g.JobId, @PoId = g.PoId, @SupplierId = g.SupplierId
        FROM   proj.TBL_GRN_HEADER g
        WHERE  g.GrnId = @GrnId AND g.IsActive = 1;

        IF @CurrentStatus IS NULL
        BEGIN
            ROLLBACK;
            RAISERROR('GRN not found.', 16, 1);
            RETURN;
        END

        DECLARE @IsInHouseJob BIT = 0;
        IF NULLIF(@JobId,'') IS NOT NULL
            SELECT @IsInHouseJob = ISNULL(jt.IsBudgetHeaderLinked, 0)
            FROM proj.TBL_JOB j
            JOIN proj.TBL_JOBTYPE jt ON jt.JobTypeId = j.JobTypeId
            WHERE j.JobId = @JobId;

        DECLARE @IsJobStock BIT = CASE
            WHEN NULLIF(@JobId,'') IS NOT NULL AND @IsInHouseJob = 0 THEN 1
            ELSE 0 END;

        IF @CurrentStatus = N'Draft' AND @NewStatus = N'Received'
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM proj.TBL_GRN_DETAIL WHERE GrnId=@GrnId AND IsActive=1)
            BEGIN ROLLBACK; RAISERROR('Cannot receive a GRN with no lines.', 16, 1); RETURN; END

            UPDATE pol
            SET    pol.ReceivedQty  = ISNULL(pol.ReceivedQty,0) + (d.ReceivedQty - ISNULL(d.RejectedQty,0)),
                   pol.ModifiedBy   = @ChangedBy, pol.ModifiedDate = GETDATE()
            FROM   proj.TBL_PURCHASE_ORDER_LINE pol
            JOIN   proj.TBL_GRN_DETAIL d ON d.PoLineId = pol.PoLineId
            WHERE  d.GrnId=@GrnId AND d.IsActive=1 AND d.PoLineId IS NOT NULL;

            UPDATE pol
            SET    pol.LineStatus = CASE
                       WHEN pol.ReceivedQty >= pol.OrderedQty THEN 'Received'
                       WHEN pol.ReceivedQty  > 0              THEN 'Partial'
                       ELSE 'Open' END,
                   pol.ModifiedBy = @ChangedBy, pol.ModifiedDate = GETDATE()
            FROM   proj.TBL_PURCHASE_ORDER_LINE pol
            JOIN   proj.TBL_GRN_DETAIL d ON d.PoLineId = pol.PoLineId
            WHERE  d.GrnId=@GrnId AND d.IsActive=1 AND d.PoLineId IS NOT NULL
              AND  pol.LineStatus NOT IN ('Closed','Cancelled');

            IF NULLIF(@PoId,0) IS NOT NULL
            BEGIN
                UPDATE po
                SET    po.Status = CASE
                           WHEN NOT EXISTS (SELECT 1 FROM proj.TBL_PURCHASE_ORDER_LINE
                               WHERE PoId=@PoId AND IsActive=1
                                 AND LineStatus NOT IN ('Received','Closed','Cancelled')) THEN 'Received'
                           WHEN EXISTS (SELECT 1 FROM proj.TBL_PURCHASE_ORDER_LINE
                               WHERE PoId=@PoId AND IsActive=1 AND ReceivedQty > 0) THEN 'Partial'
                           ELSE po.Status END,
                       po.ModifiedBy=@ChangedBy, po.ModifiedDate=GETDATE()
                FROM   proj.TBL_PURCHASE_ORDER po
                WHERE  po.PoId=@PoId AND po.Status NOT IN ('Cancelled','Closed');
            END

            UPDATE bom
            SET    bom.BomReceivedQty = ISNULL(bom.BomReceivedQty,0) + (d.ReceivedQty - ISNULL(d.RejectedQty,0)),
                   bom.BomStatus = CASE
                       WHEN (ISNULL(bom.BomReceivedQty,0)+(d.ReceivedQty-ISNULL(d.RejectedQty,0))) >= bom.BomRequestedQty THEN 'FullyReceived'
                       WHEN (ISNULL(bom.BomReceivedQty,0)+(d.ReceivedQty-ISNULL(d.RejectedQty,0)))  > 0 THEN 'PartialReceived'
                       ELSE bom.BomStatus END,
                   bom.ModifiedBy=@ChangedBy, bom.ModifiedDate=GETDATE()
            FROM   proj.TBL_BOM_DETAILS bom
            JOIN   proj.TBL_PURCHASE_REQUEST_LINE prl ON prl.BomDetailId=bom.BomId
            JOIN   proj.TBL_GRN_DETAIL d ON d.PrLineId=prl.PrLineId
            WHERE  d.GrnId=@GrnId AND d.IsActive=1 AND d.PrLineId IS NOT NULL;

            DECLARE @LineNum INT, @ItemId INT, @ItemDesc NVARCHAR(300),
                    @AcceptedQty DECIMAL(18,4), @UomId INT, @UnitPrice DECIMAL(18,4),
                    @BaseUomId INT, @ConvFactor DECIMAL(18,6),
                    @StockQty DECIMAL(18,4), @StockUnitCost DECIMAL(18,4),
                    @ConvErrMsg NVARCHAR(400);

            DECLARE cur CURSOR LOCAL FAST_FORWARD FOR
                SELECT LineNum,ItemId,ItemDesc,(ReceivedQty-ISNULL(RejectedQty,0)),UomId,UnitPrice
                FROM proj.TBL_GRN_DETAIL
                WHERE GrnId=@GrnId AND IsActive=1 AND ItemId IS NOT NULL
                  AND (ReceivedQty-ISNULL(RejectedQty,0)) > 0;

            OPEN cur;
            FETCH NEXT FROM cur INTO @LineNum,@ItemId,@ItemDesc,@AcceptedQty,@UomId,@UnitPrice;
            WHILE @@FETCH_STATUS=0
            BEGIN
                SELECT @BaseUomId = BaseUomId FROM proj.TBL_ITEM WHERE ItemId = @ItemId;
                SET @ConvFactor = NULL;
                IF @UomId IS NOT NULL AND @BaseUomId IS NOT NULL AND @UomId <> @BaseUomId
                BEGIN
                    SELECT @ConvFactor = ConversionFactor
                    FROM proj.TBL_ITEM_UOM_CONVERSION
                    WHERE ItemId=@ItemId AND FromUomId=@UomId AND ToUomId=@BaseUomId AND IsActive=1;
                    IF @ConvFactor IS NULL OR @ConvFactor = 0
                    BEGIN
                        SET @ConvErrMsg = 'No UOM conversion defined for "' +
                            ISNULL(@ItemDesc, CAST(@ItemId AS NVARCHAR(20))) +
                            '". Set it up in Item master > UOM Conversions tab.';
                        RAISERROR(@ConvErrMsg, 16, 1);
                    END
                    SET @StockQty      = @AcceptedQty * @ConvFactor;
                    SET @StockUnitCost = @UnitPrice   / @ConvFactor;
                END
                ELSE
                BEGIN
                    SET @StockQty      = @AcceptedQty;
                    SET @StockUnitCost = @UnitPrice;
                END

                IF EXISTS (SELECT 1 FROM proj.TBL_STOCK_BALANCE WHERE ItemId=@ItemId)
                BEGIN
                    DECLARE @CurrQty DECIMAL(18,4), @CurrAvgCost DECIMAL(18,4), @NewAvgCost DECIMAL(18,4);
                    SELECT @CurrQty=ISNULL(QtyOnHand,0), @CurrAvgCost=ISNULL(AvgUnitCost,0)
                    FROM proj.TBL_STOCK_BALANCE WHERE ItemId=@ItemId;
                    SET @NewAvgCost = CASE WHEN (@CurrQty+@StockQty)=0 THEN @StockUnitCost
                                          ELSE (@CurrQty*@CurrAvgCost+@StockQty*@StockUnitCost)/(@CurrQty+@StockQty) END;
                    UPDATE proj.TBL_STOCK_BALANCE
                    SET QtyOnHand    = ISNULL(QtyOnHand,0) + @StockQty,
                        QtyJobStock  = ISNULL(QtyJobStock,0) + CASE WHEN @IsJobStock=1 THEN @StockQty ELSE 0 END,
                        AvgUnitCost  = @NewAvgCost,
                        LastReceiptDate = GETDATE(), UpdatedDate = GETDATE()
                    WHERE ItemId=@ItemId;
                END
                ELSE
                    INSERT INTO proj.TBL_STOCK_BALANCE(ItemId,QtyOnHand,QtyJobStock,AvgUnitCost,LastReceiptDate,UpdatedDate)
                    VALUES(@ItemId,@StockQty,CASE WHEN @IsJobStock=1 THEN @StockQty ELSE 0 END,@StockUnitCost,GETDATE(),GETDATE());

                INSERT INTO proj.TBL_STOCK_LEDGER(ItemId,TransDate,TransType,RefId,RefNo,QtyIn,QtyOut,UnitCost,IsJobStock,JobId,CreatedBy)
                VALUES(@ItemId,GETDATE(),'GRN',@GrnId,@GrnNumber,@StockQty,0,@StockUnitCost,@IsJobStock,NULLIF(@JobId,''),@ChangedBy);

                FETCH NEXT FROM cur INTO @LineNum,@ItemId,@ItemDesc,@AcceptedQty,@UomId,@UnitPrice;
            END
            CLOSE cur; DEALLOCATE cur;

            DECLARE @ReceiptNo NVARCHAR(50), @PoNumber NVARCHAR(50),
                    @SupplierName NVARCHAR(200), @ReceiptId INT;
            DECLARE @srResult TABLE (DocNumber NVARCHAR(50), NewSeries INT);
            INSERT INTO @srResult EXEC proj.sp_GetNextDocNumber 'SR';
            SELECT @ReceiptNo=DocNumber FROM @srResult;
            SELECT @PoNumber=PoNumber FROM proj.TBL_PURCHASE_ORDER WHERE PoId=@PoId;
            SELECT @SupplierName=SupplierName FROM proj.TBL_SUPPLIER WHERE SupplierId=@SupplierId;

            INSERT INTO proj.TBL_STOCK_RECEIPT(ReceiptNo,ReceiptDate,ReceiptType,JobId,PoId,PoNumber,SupplierName,Notes,Status,GrnId,IsActive,CreatedBy)
            VALUES(@ReceiptNo,ISNULL(@ReceivedDate,@GrnDate),'GRN',NULLIF(@JobId,''),@PoId,@PoNumber,@SupplierName,'Auto-created from GRN '+@GrnNumber,'Posted',@GrnId,1,@ChangedBy);
            SET @ReceiptId=SCOPE_IDENTITY();

            INSERT INTO proj.TBL_STOCK_RECEIPT_LINE(ReceiptId,LineNum,ItemId,ItemDesc,Qty,UomId,UnitCost,IsJobStock,JobId,IsActive,CreatedBy)
            SELECT @ReceiptId,d.LineNum,d.ItemId,d.ItemDesc,(d.ReceivedQty-ISNULL(d.RejectedQty,0)),d.UomId,d.UnitPrice,
                   @IsJobStock,NULLIF(@JobId,''),1,@ChangedBy
            FROM proj.TBL_GRN_DETAIL d
            WHERE d.GrnId=@GrnId AND d.IsActive=1 AND d.ItemId IS NOT NULL
              AND (d.ReceivedQty-ISNULL(d.RejectedQty,0))>0;
        END

        ELSE IF @CurrentStatus=N'Received' AND @NewStatus=N'Cancelled'
        BEGIN
            UPDATE pol
            SET    pol.ReceivedQty = CASE
                       WHEN ISNULL(pol.ReceivedQty,0)-(d.ReceivedQty-ISNULL(d.RejectedQty,0))<0 THEN 0
                       ELSE ISNULL(pol.ReceivedQty,0)-(d.ReceivedQty-ISNULL(d.RejectedQty,0)) END,
                   pol.ModifiedBy=@ChangedBy, pol.ModifiedDate=GETDATE()
            FROM proj.TBL_PURCHASE_ORDER_LINE pol
            JOIN proj.TBL_GRN_DETAIL d ON d.PoLineId=pol.PoLineId
            WHERE d.GrnId=@GrnId AND d.IsActive=1 AND d.PoLineId IS NOT NULL;

            UPDATE pol
            SET    pol.LineStatus = CASE
                       WHEN pol.ReceivedQty >= pol.OrderedQty THEN 'Received'
                       WHEN pol.ReceivedQty  > 0              THEN 'Partial'
                       ELSE 'Open' END,
                   pol.ModifiedBy=@ChangedBy, pol.ModifiedDate=GETDATE()
            FROM   proj.TBL_PURCHASE_ORDER_LINE pol
            JOIN   proj.TBL_GRN_DETAIL d ON d.PoLineId=pol.PoLineId
            WHERE  d.GrnId=@GrnId AND d.IsActive=1 AND d.PoLineId IS NOT NULL
              AND  pol.LineStatus NOT IN ('Closed','Cancelled');

            IF NULLIF(@PoId,0) IS NOT NULL
            BEGIN
                UPDATE po
                SET    po.Status = CASE
                           WHEN EXISTS (SELECT 1 FROM proj.TBL_PURCHASE_ORDER_LINE
                               WHERE PoId=@PoId AND IsActive=1 AND ReceivedQty>0) THEN 'Partial'
                           ELSE 'Approved' END,
                       po.ModifiedBy=@ChangedBy, po.ModifiedDate=GETDATE()
                FROM proj.TBL_PURCHASE_ORDER po
                WHERE po.PoId=@PoId AND po.Status NOT IN ('Cancelled','Closed','Draft');
            END

            UPDATE bom
            SET    bom.BomReceivedQty = v.NewQty,
                   bom.BomStatus = CASE
                       WHEN v.NewQty >= bom.BomRequestedQty         THEN 'FullyReceived'
                       WHEN v.NewQty  > 0                           THEN 'PartialReceived'
                       WHEN bom.PoCreatedQty >= bom.BomRequestedQty THEN 'PORaised'
                       WHEN bom.PoCreatedQty  > 0                   THEN 'POPartial'
                       WHEN bom.PrCreatedQty >= bom.BomRequestedQty THEN 'PRRaised'
                       WHEN bom.PrCreatedQty  > 0                   THEN 'PRPartial'
                       ELSE 'Pending' END,
                   bom.ModifiedBy=@ChangedBy, bom.ModifiedDate=GETDATE()
            FROM   proj.TBL_BOM_DETAILS bom
            JOIN   proj.TBL_PURCHASE_REQUEST_LINE prl ON prl.BomDetailId=bom.BomId
            JOIN   proj.TBL_GRN_DETAIL d ON d.PrLineId=prl.PrLineId
            CROSS APPLY (VALUES (
                CASE WHEN ISNULL(bom.BomReceivedQty,0)-(d.ReceivedQty-ISNULL(d.RejectedQty,0))<0
                     THEN CAST(0 AS DECIMAL(18,4))
                     ELSE ISNULL(bom.BomReceivedQty,0)-(d.ReceivedQty-ISNULL(d.RejectedQty,0)) END
            )) v(NewQty)
            WHERE  d.GrnId=@GrnId AND d.IsActive=1 AND d.PrLineId IS NOT NULL;

            DECLARE @RItemId INT, @RQtyIn DECIMAL(18,4), @RUnitCost DECIMAL(18,4),
                    @RIsJobStock BIT, @RJobId NVARCHAR(50);
            DECLARE cur2 CURSOR LOCAL FAST_FORWARD FOR
                SELECT ItemId,QtyIn,UnitCost,IsJobStock,JobId FROM proj.TBL_STOCK_LEDGER
                WHERE TransType='GRN' AND RefId=@GrnId AND QtyIn>0;
            OPEN cur2;
            FETCH NEXT FROM cur2 INTO @RItemId,@RQtyIn,@RUnitCost,@RIsJobStock,@RJobId;
            WHILE @@FETCH_STATUS=0
            BEGIN
                UPDATE proj.TBL_STOCK_BALANCE
                SET QtyOnHand=CASE WHEN ISNULL(QtyOnHand,0)-@RQtyIn<0 THEN 0 ELSE ISNULL(QtyOnHand,0)-@RQtyIn END,
                    QtyJobStock=CASE WHEN @RIsJobStock=1 THEN CASE WHEN ISNULL(QtyJobStock,0)-@RQtyIn<0 THEN 0 ELSE ISNULL(QtyJobStock,0)-@RQtyIn END ELSE QtyJobStock END,
                    UpdatedDate=GETDATE()
                WHERE ItemId=@RItemId;

                INSERT INTO proj.TBL_STOCK_LEDGER(ItemId,TransDate,TransType,RefId,RefNo,QtyIn,QtyOut,UnitCost,IsJobStock,JobId,CreatedBy)
                VALUES(@RItemId,GETDATE(),'GRN-REV',@GrnId,@GrnNumber,0,@RQtyIn,@RUnitCost,@RIsJobStock,@RJobId,@ChangedBy);

                FETCH NEXT FROM cur2 INTO @RItemId,@RQtyIn,@RUnitCost,@RIsJobStock,@RJobId;
            END
            CLOSE cur2; DEALLOCATE cur2;

            UPDATE proj.TBL_STOCK_RECEIPT
            SET IsActive=0, Status='Cancelled', ModifiedBy=@ChangedBy, ModifiedDate=GETDATE()
            WHERE GrnId=@GrnId AND IsActive=1;

            UPDATE rl SET rl.IsActive=0, rl.ModifiedBy=@ChangedBy, rl.ModifiedDate=GETDATE()
            FROM proj.TBL_STOCK_RECEIPT_LINE rl
            JOIN proj.TBL_STOCK_RECEIPT r ON r.ReceiptId=rl.ReceiptId
            WHERE r.GrnId=@GrnId;
        END

        UPDATE proj.TBL_GRN_HEADER
        SET Status=@NewStatus, ModifiedBy=@ChangedBy, ModifiedDate=GETDATE()
        WHERE GrnId=@GrnId AND IsActive=1;

        COMMIT;
        SELECT CAST(@GrnId AS NVARCHAR(20));
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        IF CURSOR_STATUS('local','cur')  >= 0 BEGIN CLOSE cur;  DEALLOCATE cur;  END
        IF CURSOR_STATUS('local','cur2') >= 0 BEGIN CLOSE cur2; DEALLOCATE cur2; END
        DECLARE @Msg NVARCHAR(2048) = ERROR_MESSAGE();
        RAISERROR(@Msg, 16, 1); RETURN;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_ChangeJobStage]') IS NOT NULL DROP PROCEDURE [proj].[sp_ChangeJobStage];
GO
CREATE   PROCEDURE proj.sp_ChangeJobStage
    @JobId        NVARCHAR(50),
    @JobStageId   NVARCHAR(10),
    @OldStage     NVARCHAR(100),
    @NewStage     NVARCHAR(100),
    @ModifiedBy   NVARCHAR(50),
    @Reason       NVARCHAR(500) = NULL,
    @PasswordHash NVARCHAR(500) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @FreezeStageId NVARCHAR(10) = N'STAGE5';
    DECLARE @CurrentStatus INT, @CurrentStageId NVARCHAR(10);
    SELECT @CurrentStatus  = JobStatusId,
           @CurrentStageId = JobStageId
    FROM   proj.TBL_JOB WHERE JobId = @JobId;

    DECLARE @ShouldFreeze BIT = CASE
        WHEN @JobStageId = @FreezeStageId AND @CurrentStatus IN (1, 2) THEN 1 ELSE 0
    END;

    -- ════════════════════════════════════════════════════════════
    -- Freeze-path gating: same reason + password contract as Complete/Cancel.
    -- The SP is authoritative — the UI's modal is just nicer UX. Direct API
    -- callers (postman, integrations) get the same enforcement here.
    -- ════════════════════════════════════════════════════════════
    IF @ShouldFreeze = 1
    BEGIN
        IF @Reason IS NULL OR LTRIM(RTRIM(@Reason)) = N''
        BEGIN
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   N'Reason is required to move into stage ''' + @NewStage + N''' (this freezes the job).' AS Message;
            RETURN;
        END
        IF @PasswordHash IS NULL
        BEGIN
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   N'Password is required to move into stage ''' + @NewStage + N''' (this freezes the job).' AS Message;
            RETURN;
        END

        DECLARE @UserId INT = (SELECT TOP 1 UserId FROM proj.TBL_USERS WHERE UserName = @ModifiedBy);
        IF @UserId IS NULL
        BEGIN
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   N'Acting user not found.' AS Message;
            RETURN;
        END

        DECLARE @JobsMenuId   INT = (SELECT MenuId   FROM proj.TBL_MENU         WHERE MenuUrl = N'/jobs');
        DECLARE @ApproveActId INT = (SELECT ActionId FROM proj.TBL_MENU_ACTIONS WHERE MenuId  = @JobsMenuId AND ActionCode = N'APPROVE');

        IF NOT EXISTS (
            SELECT 1
            FROM   proj.TBL_USER_ROLES ur
            JOIN   proj.TBL_ROLE_SECRET rs
                   ON rs.RoleId = ur.RoleId AND rs.SecretKey = N'BUDGET_PASSWORD'
            JOIN   proj.TBL_ROLE_MENU_ACTION rma
                   ON rma.RoleId = ur.RoleId AND rma.MenuId = @JobsMenuId
                  AND rma.ActionId = @ApproveActId AND rma.IsAllowed = 1
            WHERE  ur.UserId = @UserId
              AND  rs.SecretValueHash = @PasswordHash )
        BEGIN
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   N'Incorrect password, or none of your roles is allowed to authorise this action.' AS Message;
            RETURN;
        END
    END

    -- Compose the remark that goes into the lifecycle audit + history.
    DECLARE @FreezeRemark NVARCHAR(500) =
        N'Auto-freezed because stage moved to ' + @NewStage +
        CASE WHEN @Reason IS NULL THEN N'' ELSE N' — ' + @Reason END;

    UPDATE proj.TBL_JOB
    SET    JobStageId         = @JobStageId,
           PreFreezeStageId   = CASE WHEN @ShouldFreeze = 1 AND PreFreezeStageId IS NULL
                                       THEN @CurrentStageId
                                     ELSE PreFreezeStageId END,
           JobStatusId        = CASE WHEN @ShouldFreeze = 1 THEN 3 ELSE JobStatusId END,
           JobLastModifiedBy  = @ModifiedBy,
           JobLastUpdatedDate = GETDATE()
    WHERE  JobId = @JobId;

    INSERT INTO proj.TBL_JOB_AUDIT (JobId, Action, Section, OldValue, NewValue, Remarks, CreatedBy, CreatedDate)
    VALUES (@JobId, N'STAGE_CHANGED', N'Job', @OldStage, @NewStage, @Reason, @ModifiedBy, GETDATE());

    IF @ShouldFreeze = 1
    BEGIN
        INSERT INTO proj.TBL_JOB_AUDIT (JobId, Action, Section, OldValue, NewValue, Remarks, CreatedBy, CreatedDate)
        VALUES (@JobId, N'JOB_FREEZED', N'Lifecycle',
                CASE @CurrentStatus WHEN 1 THEN N'Active' WHEN 2 THEN N'On Hold' END,
                N'Freezed',
                @FreezeRemark,
                @ModifiedBy, GETDATE());
    END

    -- Always return Success/JobId/Message so the controller can branch uniformly.
    SELECT 1 AS Success, @JobId AS JobId,
           CASE WHEN @ShouldFreeze = 1
                THEN N'Stage changed and job freezed.'
                ELSE N'Stage updated.' END AS Message,
           @ShouldFreeze AS Freezed;
END;
GO

IF OBJECT_ID(N'[proj].[sp_ChangeJobStatus]') IS NOT NULL DROP PROCEDURE [proj].[sp_ChangeJobStatus];
GO
CREATE PROCEDURE proj.sp_ChangeJobStatus
    @JobId        NVARCHAR(50),
    @JobStatusId  INT,
    @OldStatus    NVARCHAR(50),
    @NewStatus    NVARCHAR(50),
    @ModifiedBy   NVARCHAR(50),
    @Reason       NVARCHAR(500) = NULL,
    @PasswordHash NVARCHAR(500) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @IsInHouseJob BIT = 0;
    SELECT @IsInHouseJob = ISNULL(jt.IsBudgetHeaderLinked, 0)
    FROM proj.TBL_JOB j
    JOIN proj.TBL_JOBTYPE jt ON jt.JobTypeId = j.JobTypeId
    WHERE j.JobId = @JobId;

    DECLARE @StockItemCount INT        = 0;
    DECLARE @StockSummary   NVARCHAR(MAX) = N'';

    -- ── Shared guards (cancel AND complete) ───────────────────────────────
    IF @JobStatusId IN (4, 5)
    BEGIN
        SELECT @StockItemCount = COUNT(*)
        FROM (
            SELECT sl.ItemId FROM proj.TBL_STOCK_LEDGER sl
            WHERE sl.JobId = @JobId GROUP BY sl.ItemId HAVING SUM(sl.QtyIn - sl.QtyOut) > 0
        ) x;
        IF @StockItemCount > 0
        BEGIN
            SELECT @StockSummary = @StockSummary + i.ItemCode +
                ' (' + CAST(CAST(net.NetQty AS DECIMAL(18,2)) AS NVARCHAR(30)) + '), '
            FROM (
                SELECT sl.ItemId, SUM(sl.QtyIn - sl.QtyOut) AS NetQty
                FROM proj.TBL_STOCK_LEDGER sl WHERE sl.JobId = @JobId
                GROUP BY sl.ItemId HAVING SUM(sl.QtyIn - sl.QtyOut) > 0
            ) net JOIN proj.TBL_ITEM i ON i.ItemId = net.ItemId ORDER BY i.ItemCode;
            SET @StockSummary = NULLIF(LEFT(@StockSummary, LEN(@StockSummary) - 1), N'');
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   'Cannot ' + LOWER(@NewStatus) + ' — ' + CAST(@StockItemCount AS NVARCHAR(10)) +
                   ' item(s) still have stock in this job''s bucket: ' + ISNULL(@StockSummary, N'') +
                   '. Issue out or adjust all remaining stock before closing the job.' AS Message;
            RETURN;
        END

        DECLARE @DraftIssues INT = (
            SELECT COUNT(*) FROM proj.TBL_STOCK_ISSUE WHERE JobId = @JobId AND IsActive = 1 AND Status = 'Draft'
        );
        IF @DraftIssues > 0
        BEGIN
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   'Cannot ' + LOWER(@NewStatus) + ' — ' + CAST(@DraftIssues AS NVARCHAR(10)) +
                   ' draft issue note(s) must be confirmed or deleted first.' AS Message;
            RETURN;
        END

        -- Draft GRNs must be confirmed or deleted
        DECLARE @DraftGRNs INT = (
            SELECT COUNT(*) FROM proj.TBL_STOCK_RECEIPT WHERE JobId = @JobId AND IsActive = 1 AND Status = 'Draft'
        );
        IF @DraftGRNs > 0
        BEGIN
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   'Cannot ' + LOWER(@NewStatus) + ' — ' + CAST(@DraftGRNs AS NVARCHAR(10)) +
                   ' draft GRN(s) must be confirmed or deleted first.' AS Message;
            RETURN;
        END
    END

    -- ── Cancel-only guards ────────────────────────────────────────────────
    IF @JobStatusId = 5
    BEGIN
        DECLARE @OpenPos INT = (
            SELECT COUNT(*) FROM proj.TBL_PURCHASE_ORDER
            WHERE JobId = @JobId AND IsActive = 1 AND Status NOT IN (N'Cancelled', N'Closed', N'Received')
        );
        IF @OpenPos > 0
        BEGIN
            DECLARE @PoList NVARCHAR(MAX) = N'';
            SELECT @PoList = @PoList + PoNumber + N', ' FROM proj.TBL_PURCHASE_ORDER
            WHERE JobId = @JobId AND IsActive = 1 AND Status NOT IN (N'Cancelled', N'Closed', N'Received') ORDER BY PoNumber;
            SET @PoList = NULLIF(LEFT(@PoList, LEN(@PoList) - 1), N'');
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   'Cannot cancel — ' + CAST(@OpenPos AS NVARCHAR(10)) +
                   ' open purchase order(s) must be closed or cancelled first: ' + ISNULL(@PoList, N'') AS Message;
            RETURN;
        END

        DECLARE @OpenPRs INT = (
            SELECT COUNT(*) FROM proj.TBL_PURCHASE_REQUEST
            WHERE JobId = @JobId AND IsActive = 1 AND Status NOT IN (N'Cancelled', N'Closed')
        );
        IF @OpenPRs > 0
        BEGIN
            DECLARE @PrList NVARCHAR(MAX) = N'';
            SELECT @PrList = @PrList + PrNumber + N', ' FROM proj.TBL_PURCHASE_REQUEST
            WHERE JobId = @JobId AND IsActive = 1 AND Status NOT IN (N'Cancelled', N'Closed') ORDER BY PrNumber;
            SET @PrList = NULLIF(LEFT(@PrList, LEN(@PrList) - 1), N'');
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   'Cannot cancel — ' + CAST(@OpenPRs AS NVARCHAR(10)) +
                   ' open purchase request(s) must be cancelled or closed first: ' + ISNULL(@PrList, N'') AS Message;
            RETURN;
        END

        DECLARE @ActiveReceipts INT = (
            SELECT COUNT(DISTINCT rv.RvId) FROM proj.TBL_RECEIPT_VOUCHER rv
            JOIN proj.TBL_RECEIPT_VOUCHER_ALLOCATION a ON a.RvId = rv.RvId AND ISNULL(a.IsActive, 1) = 1
            JOIN proj.TBL_INVOICE i ON i.InvoiceId = a.InvoiceId
            WHERE (i.JobId = @JobId OR i.JobId IN (SELECT JobId FROM proj.TBL_JOB WHERE ParentJobId = @JobId))
              AND ISNULL(rv.IsActive, 1) = 1 AND ISNULL(rv.Status, N'') NOT IN (N'CANCELLED', N'VOID')
        );
        IF @ActiveReceipts > 0
        BEGIN
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   'Cannot cancel — ' + CAST(@ActiveReceipts AS NVARCHAR(10)) +
                   ' active receipt voucher(s) allocated to this job (or its additional jobs) must be cancelled first.' AS Message;
            RETURN;
        END

        DECLARE @ActiveInvoices INT = (
            SELECT COUNT(*) FROM proj.TBL_INVOICE i
            WHERE (i.JobId = @JobId OR i.JobId IN (SELECT JobId FROM proj.TBL_JOB WHERE ParentJobId = @JobId))
              AND ISNULL(i.Status, N'') NOT IN (N'CANCELLED', N'VOID')
        );
        IF @ActiveInvoices > 0
        BEGIN
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   'Cannot cancel — ' + CAST(@ActiveInvoices AS NVARCHAR(10)) +
                   ' active invoice(s) on this job (or its additional jobs) must be cancelled first.' AS Message;
            RETURN;
        END

        DECLARE @PendingVariations INT = (
            SELECT COUNT(*) FROM proj.TBL_JOB WHERE ParentJobId = @JobId AND ISNULL(JobStatusId, 0) <> 5
        );
        IF @PendingVariations > 0
        BEGIN
            DECLARE @V NVARCHAR(MAX) = N'';
            SELECT @V = @V + JobId + N', ' FROM proj.TBL_JOB WHERE ParentJobId = @JobId AND ISNULL(JobStatusId, 0) <> 5;
            SET @V = NULLIF(LEFT(@V, LEN(@V) - 1), N'');
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   'Cannot cancel — ' + CAST(@PendingVariations AS NVARCHAR(10)) +
                   ' additional job(s) must be cancelled first: ' + ISNULL(@V, N'') AS Message;
            RETURN;
        END
    END

    -- ── Complete-only guards ──────────────────────────────────────────────
    IF @JobStatusId = 4
    BEGIN
        DECLARE @OpenVariations INT = (
            SELECT COUNT(*) FROM proj.TBL_JOB WHERE ParentJobId = @JobId AND ISNULL(JobStatusId, 0) NOT IN (4, 5)
        );
        IF @OpenVariations > 0
        BEGIN
            DECLARE @V2 NVARCHAR(MAX) = N'';
            SELECT @V2 = @V2 + JobId + N', ' FROM proj.TBL_JOB WHERE ParentJobId = @JobId AND ISNULL(JobStatusId, 0) NOT IN (4, 5);
            SET @V2 = NULLIF(LEFT(@V2, LEN(@V2) - 1), N'');
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   'Cannot complete — ' + CAST(@OpenVariations AS NVARCHAR(10)) +
                   ' additional job(s) must be completed or cancelled first: ' + ISNULL(@V2, N'') AS Message;
            RETURN;
        END

        DECLARE @OpenPosComplete INT = (
            SELECT COUNT(*) FROM proj.TBL_PURCHASE_ORDER
            WHERE JobId = @JobId AND IsActive = 1 AND Status NOT IN (N'Cancelled', N'Closed', N'Received')
        );
        IF @OpenPosComplete > 0
        BEGIN
            DECLARE @PoListC NVARCHAR(MAX) = N'';
            SELECT @PoListC = @PoListC + PoNumber + N', ' FROM proj.TBL_PURCHASE_ORDER
            WHERE JobId = @JobId AND IsActive = 1 AND Status NOT IN (N'Cancelled', N'Closed', N'Received') ORDER BY PoNumber;
            SET @PoListC = NULLIF(LEFT(@PoListC, LEN(@PoListC) - 1), N'');
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   'Cannot complete — ' + CAST(@OpenPosComplete AS NVARCHAR(10)) +
                   ' open purchase order(s) must be received, closed, or cancelled first: ' + ISNULL(@PoListC, N'') AS Message;
            RETURN;
        END

        DECLARE @OpenPRsComplete INT = (
            SELECT COUNT(*) FROM proj.TBL_PURCHASE_REQUEST
            WHERE JobId = @JobId AND IsActive = 1 AND Status NOT IN (N'Cancelled', N'Closed')
        );
        IF @OpenPRsComplete > 0
        BEGIN
            DECLARE @PrListC NVARCHAR(MAX) = N'';
            SELECT @PrListC = @PrListC + PrNumber + N', ' FROM proj.TBL_PURCHASE_REQUEST
            WHERE JobId = @JobId AND IsActive = 1 AND Status NOT IN (N'Cancelled', N'Closed') ORDER BY PrNumber;
            SET @PrListC = NULLIF(LEFT(@PrListC, LEN(@PrListC) - 1), N'');
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   'Cannot complete — ' + CAST(@OpenPRsComplete AS NVARCHAR(10)) +
                   ' open purchase request(s) must be cancelled or closed first: ' + ISNULL(@PrListC, N'') AS Message;
            RETURN;
        END

        -- Draft invoices must be confirmed before completing
        DECLARE @DraftInvoices INT = (
            SELECT COUNT(*) FROM proj.TBL_INVOICE WHERE JobId = @JobId AND IsActive = 1 AND Status = 'Draft'
        );
        IF @DraftInvoices > 0
        BEGIN
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   'Cannot complete — ' + CAST(@DraftInvoices AS NVARCHAR(10)) +
                   ' invoice(s) are still in Draft status and must be confirmed or deleted first.' AS Message;
            RETURN;
        END

        DECLARE @OpenMOMTasks INT = (
            SELECT COUNT(*) FROM proj.TBL_MOM_TASK WHERE JobId = @JobId AND IsActive = 1 AND Status = 'Open'
        );
        IF @OpenMOMTasks > 0
        BEGIN
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   'Cannot complete — ' + CAST(@OpenMOMTasks AS NVARCHAR(10)) +
                   ' open MOM task(s) must be closed or cancelled first.' AS Message;
            RETURN;
        END
    END

    -- ── Password + reason + role check ───────────────────────────────────
    IF @JobStatusId IN (4, 5)
    BEGIN
        IF @Reason IS NULL OR LTRIM(RTRIM(@Reason)) = N''
        BEGIN
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   'Reason is required to ' + LOWER(@NewStatus) + ' a job.' AS Message; RETURN;
        END
        IF @PasswordHash IS NULL
        BEGIN
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   'Password is required to ' + LOWER(@NewStatus) + ' a job.' AS Message; RETURN;
        END

        DECLARE @UserId INT = (SELECT TOP 1 UserId FROM proj.TBL_USERS WHERE UserName = @ModifiedBy);
        IF @UserId IS NULL
        BEGIN
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId, 'Acting user not found.' AS Message; RETURN;
        END

        DECLARE @JobsMenuId   INT = (SELECT MenuId   FROM proj.TBL_MENU        WHERE MenuUrl = N'/jobs');
        DECLARE @ApproveActId INT = (SELECT ActionId FROM proj.TBL_MENU_ACTIONS WHERE MenuId  = @JobsMenuId AND ActionCode = N'APPROVE');

        IF NOT EXISTS (
            SELECT 1 FROM proj.TBL_USER_ROLES ur
            JOIN proj.TBL_ROLE_SECRET rs      ON rs.RoleId  = ur.RoleId AND rs.SecretKey = N'BUDGET_PASSWORD'
            JOIN proj.TBL_ROLE_MENU_ACTION rma ON rma.RoleId = ur.RoleId AND rma.MenuId = @JobsMenuId
                AND rma.ActionId = @ApproveActId AND rma.IsAllowed = 1
            WHERE ur.UserId = @UserId AND rs.SecretValueHash = @PasswordHash
        )
        BEGIN
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   'Incorrect password, or none of your roles is allowed to authorise this action.' AS Message; RETURN;
        END
    END

    IF @JobStatusId = 4 AND EXISTS (SELECT 1 FROM proj.TBL_JOB WHERE JobId = @JobId AND JobStatusId = 4)
    BEGIN SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId, 'This job is already completed.' AS Message; RETURN; END
    IF @JobStatusId = 5 AND EXISTS (SELECT 1 FROM proj.TBL_JOB WHERE JobId = @JobId AND JobStatusId = 5)
    BEGIN SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId, 'This job is already cancelled.' AS Message; RETURN; END

    -- Financial check — skipped for in-house jobs
    IF @JobStatusId = 4 AND @IsInHouseJob = 0
    BEGIN
        DECLARE @OrderValueBase DECIMAL(18,2), @TotalInvoiced DECIMAL(18,2), @TotalPaid DECIMAL(18,2);
        SELECT @OrderValueBase = jf.OrderValue * ISNULL(jf.ExchangeRate, 1),
               @TotalInvoiced  = ISNULL(jf.TotalInvoicing, 0),
               @TotalPaid      = ISNULL(jf.TotalPayments,  0)
        FROM proj.TBL_JOB_FINANCE jf WHERE jf.JobId = @JobId;
        SET @OrderValueBase = ISNULL(@OrderValueBase, 0);

        IF @TotalInvoiced < @OrderValueBase * 0.99
        BEGIN
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   'Cannot complete job: total invoiced (' + FORMAT(@TotalInvoiced, 'N2') +
                   ') is below 99% of order value (' + FORMAT(@OrderValueBase * 0.99, 'N2') + ').' AS Message; RETURN;
        END
        IF @TotalPaid < @TotalInvoiced * 0.99
        BEGIN
            SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
                   'Cannot complete job: total payment (' + FORMAT(@TotalPaid, 'N2') +
                   ') is below 99% of total invoiced (' + FORMAT(@TotalInvoiced * 0.99, 'N2') + ').' AS Message; RETURN;
        END
    END

    UPDATE proj.TBL_JOB
    SET    JobStatusId        = @JobStatusId,
           JobLastModifiedBy  = @ModifiedBy,
           JobLastUpdatedDate = GETDATE(),
           CompletedDate      = CASE WHEN @JobStatusId = 4 THEN GETDATE()   ELSE CompletedDate   END,
           CompletedReason    = CASE WHEN @JobStatusId = 4 THEN @Reason     ELSE CompletedReason END,
           CompletedBy        = CASE WHEN @JobStatusId = 4 THEN @ModifiedBy ELSE CompletedBy     END,
           CancelledDate      = CASE WHEN @JobStatusId = 5 THEN GETDATE()   ELSE CancelledDate   END,
           CancelledReason    = CASE WHEN @JobStatusId = 5 THEN @Reason     ELSE CancelledReason END,
           CancelledBy        = CASE WHEN @JobStatusId = 5 THEN @ModifiedBy ELSE CancelledBy     END
    WHERE  JobId = @JobId;

    DECLARE @AuditAction NVARCHAR(50) =
        CASE @JobStatusId WHEN 4 THEN N'JOB_COMPLETED' WHEN 5 THEN N'JOB_CANCELLED' ELSE N'STATUS_CHANGED' END;

    INSERT INTO proj.TBL_JOB_AUDIT (JobId, Action, Section, OldValue, NewValue, Remarks, CreatedBy, CreatedDate)
    VALUES (@JobId, @AuditAction, N'Lifecycle', @OldStatus, @NewStatus, @Reason, @ModifiedBy, GETDATE());

    SELECT 1 AS Success, @JobId AS JobId, CAST(NULL AS NVARCHAR(500)) AS Message;
END;
GO

IF OBJECT_ID(N'[proj].[sp_ChangePoLineStatus]') IS NOT NULL DROP PROCEDURE [proj].[sp_ChangePoLineStatus];
GO

CREATE PROCEDURE PROJ.sp_ChangePoLineStatus
    @PoLineId  INT,
    @NewStatus NVARCHAR(20),
    @ChangedBy NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    IF @NewStatus NOT IN ('Closed','Cancelled')
        RAISERROR('Only Closed or Cancelled are allowed via manual line status change.', 16, 1);

    DECLARE @PoId          INT;
    DECLARE @CurrentStatus NVARCHAR(20);
    DECLARE @ReceivedQty   DECIMAL(18,4);
    DECLARE @OrderedQty    DECIMAL(18,4);
    DECLARE @PoStatus      NVARCHAR(30);
    DECLARE @PrLineId      INT;

    SELECT @PoId          = pol.PoId,
           @CurrentStatus = pol.LineStatus,
           @ReceivedQty   = ISNULL(pol.ReceivedQty, 0),
           @OrderedQty    = pol.OrderedQty,
           @PoStatus      = po.Status,
           @PrLineId      = pol.PrLineId
    FROM   PROJ.TBL_PURCHASE_ORDER_LINE pol
    JOIN   PROJ.TBL_PURCHASE_ORDER po ON po.PoId = pol.PoId
    WHERE  pol.PoLineId = @PoLineId AND pol.IsActive = 1;

    IF @PoId IS NULL RAISERROR('PO line not found.', 16, 1);

    IF @CurrentStatus IN ('Closed','Cancelled')
    BEGIN
        DECLARE @AlreadyMsg NVARCHAR(100) = 'Line is already ' + @CurrentStatus + '.';
        RAISERROR(@AlreadyMsg, 16, 1);
    END

    IF @NewStatus = 'Cancelled' AND @ReceivedQty > 0
        RAISERROR('Cannot cancel a line that has received goods. Use Return to Vendor instead.', 16, 1);

    IF @PoStatus = 'Draft'
        RAISERROR('Cannot change line status while PO is in Draft. Submit for approval first.', 16, 1);

    -- Update the PO line status
    UPDATE PROJ.TBL_PURCHASE_ORDER_LINE
    SET    LineStatus    = @NewStatus,
           ModifiedBy    = @ChangedBy,
           ModifiedDate  = GETDATE()
    WHERE  PoLineId = @PoLineId;

    -- Quantity to release back up the chain = the un-received portion.
    -- Cancel: ReceivedQty is 0 (guarded) → releases full OrderedQty.
    -- Close : releases OrderedQty - ReceivedQty (keeps what was received).
    DECLARE @ReleaseQty DECIMAL(18,4) = @OrderedQty - @ReceivedQty;
    IF @ReleaseQty < 0 SET @ReleaseQty = 0;

    DECLARE @BomDetailId INT = NULL;

    IF @PrLineId IS NOT NULL AND @ReleaseQty > 0
    BEGIN
        -- 1. Reduce the PR line's PoCreatedQty (release the order back to the PR)
        UPDATE PROJ.TBL_PURCHASE_REQUEST_LINE
        SET    PoCreatedQty = CASE WHEN ISNULL(PoCreatedQty,0) - @ReleaseQty < 0 THEN 0
                                   ELSE ISNULL(PoCreatedQty,0) - @ReleaseQty END,
               ModifiedBy   = @ChangedBy,
               ModifiedDate = GETDATE()
        WHERE  PrLineId = @PrLineId;

        SELECT @BomDetailId = BomDetailId
        FROM   PROJ.TBL_PURCHASE_REQUEST_LINE WHERE PrLineId = @PrLineId;

        -- 2. Reduce the BOM's PoCreatedQty and re-derive BomStatus from the numbers
        IF @BomDetailId IS NOT NULL AND @BomDetailId > 0
            UPDATE bom
            SET bom.PoCreatedQty = v.NewPo,
                bom.BomStatus    = CASE
                    WHEN bom.BomReceivedQty >= bom.BomRequestedQty         THEN 'FullyReceived'
                    WHEN bom.BomReceivedQty  > 0                           THEN 'PartialReceived'
                    WHEN v.NewPo >= bom.BomRequestedQty                    THEN 'PORaised'
                    WHEN v.NewPo  > 0                                      THEN 'POPartial'
                    WHEN ISNULL(bom.PrCreatedQty,0) >= bom.BomRequestedQty THEN 'PRRaised'
                    WHEN ISNULL(bom.PrCreatedQty,0)  > 0                   THEN 'PRPartial'
                    ELSE 'Pending'
                END,
                bom.ModifiedBy   = @ChangedBy,
                bom.ModifiedDate = GETDATE()
            FROM PROJ.TBL_BOM_DETAILS bom
            CROSS APPLY (VALUES (
                CASE WHEN ISNULL(bom.PoCreatedQty,0) - @ReleaseQty < 0 THEN CAST(0 AS DECIMAL(18,4))
                     ELSE ISNULL(bom.PoCreatedQty,0) - @ReleaseQty END
            )) v(NewPo)
            WHERE bom.BomId = @BomDetailId;
    END

    -- 3. Recalc PR line + PR header status now that PoCreatedQty has changed
    IF @PrLineId IS NOT NULL
        EXEC proj.sp_RecalcPrStatus @PrLineId = @PrLineId, @ChangedBy = @ChangedBy;

    -- 4. Recalculate PO header status based on remaining lines.
    --    Guard: only become 'Received' if at least one line is actually Received
    --    (prevents an all-Cancelled PO from flipping to Received).
    UPDATE po
    SET    po.Status = CASE
               WHEN NOT EXISTS (
                   SELECT 1 FROM PROJ.TBL_PURCHASE_ORDER_LINE
                   WHERE PoId = @PoId AND IsActive = 1
                     AND LineStatus NOT IN ('Received','Closed','Cancelled')
               ) AND EXISTS (
                   SELECT 1 FROM PROJ.TBL_PURCHASE_ORDER_LINE
                   WHERE PoId = @PoId AND IsActive = 1 AND LineStatus = 'Received'
               ) THEN 'Received'
               WHEN EXISTS (
                   SELECT 1 FROM PROJ.TBL_PURCHASE_ORDER_LINE
                   WHERE PoId = @PoId AND IsActive = 1 AND ReceivedQty > 0
               ) THEN 'Partial'
               ELSE po.Status
           END,
           po.ModifiedBy   = @ChangedBy,
           po.ModifiedDate = GETDATE()
    FROM   PROJ.TBL_PURCHASE_ORDER po
    WHERE  po.PoId = @PoId
      AND  po.Status NOT IN ('Cancelled','Closed','Draft');

    SELECT CAST(@PoLineId AS NVARCHAR(20));
END
GO

IF OBJECT_ID(N'[proj].[sp_ChangePOStatus]') IS NOT NULL DROP PROCEDURE [proj].[sp_ChangePOStatus];
GO
CREATE PROCEDURE PROJ.sp_ChangePOStatus
    @PoId      INT,
    @NewStatus NVARCHAR(30),
    @ChangedBy NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    -- Approval-controlled status — block direct set
    IF @NewStatus = 'Approved'
    BEGIN
        RAISERROR('PO status cannot be set to Approved directly. Use the approval workflow.', 16, 1);
        RETURN;
    END

    -- Currency validation (rate/code sanity check only — no budget re-check here;
    -- budget enforcement runs at sp_SubmitForApproval and sp_ProcessApproval)
    IF @NewStatus NOT IN ('Draft', 'Cancelled', 'Received', 'Closed')
    BEGIN
        DECLARE @PoCurrency INT, @PoRate DECIMAL(18,6);
        SELECT @PoCurrency = CurrencyId, @PoRate = ExchangeRate
        FROM PROJ.TBL_PURCHASE_ORDER WHERE PoId = @PoId AND IsActive = 1;

        EXEC proj.sp_ValidateTxnCurrency @PoCurrency, @PoRate, N'Purchase order';
    END

    UPDATE PROJ.TBL_PURCHASE_ORDER
    SET Status       = @NewStatus,
        PoSentDate   = CASE
                           WHEN @NewStatus = 'Sent' THEN ISNULL(PoSentDate, GETDATE())
                           WHEN @NewStatus = 'Draft' THEN NULL
                           ELSE PoSentDate
                       END,
        ModifiedBy   = @ChangedBy,
        ModifiedDate = GETDATE()
    WHERE PoId = @PoId AND IsActive = 1;

    SELECT CAST(@PoId AS NVARCHAR(20));
END
GO

IF OBJECT_ID(N'[proj].[sp_ChangePrLineStatus]') IS NOT NULL DROP PROCEDURE [proj].[sp_ChangePrLineStatus];
GO

CREATE PROCEDURE PROJ.sp_ChangePrLineStatus
    @PrLineId  INT,
    @NewStatus NVARCHAR(20),
    @ChangedBy NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    IF @NewStatus NOT IN ('Closed','Cancelled')
        RAISERROR('Only Closed or Cancelled are allowed via manual PR line status change.', 16, 1);

    DECLARE @PrId          INT;
    DECLARE @CurrentStatus NVARCHAR(20);
    DECLARE @PoCreatedQty  DECIMAL(18,4);
    DECLARE @RequiredQty   DECIMAL(18,4);
    DECLARE @PrStatus      NVARCHAR(30);
    DECLARE @BomDetailId   INT;

    SELECT @PrId          = prl.PrId,
           @CurrentStatus = prl.LineStatus,
           @PoCreatedQty  = ISNULL(prl.PoCreatedQty, 0),
           @RequiredQty   = ISNULL(prl.RequiredQty, 0),
           @PrStatus      = pr.Status,
           @BomDetailId   = prl.BomDetailId
    FROM   PROJ.TBL_PURCHASE_REQUEST_LINE prl
    JOIN   PROJ.TBL_PURCHASE_REQUEST pr ON pr.PrId = prl.PrId
    WHERE  prl.PrLineId = @PrLineId AND prl.IsActive = 1;

    IF @PrId IS NULL RAISERROR('PR line not found.', 16, 1);

    IF @CurrentStatus IN ('Closed','Cancelled')
    BEGIN
        DECLARE @AlreadyMsg NVARCHAR(100) = 'Line is already ' + @CurrentStatus + '.';
        RAISERROR(@AlreadyMsg, 16, 1);
    END

    IF @NewStatus = 'Cancelled' AND @PoCreatedQty > 0
        RAISERROR('Cannot cancel a line that already has Purchase Orders raised against it.', 16, 1);

    IF @PrStatus = 'Draft'
        RAISERROR('Cannot change line status while PR is in Draft. Submit for approval first.', 16, 1);

    -- Update the PR line status
    UPDATE PROJ.TBL_PURCHASE_REQUEST_LINE
    SET    LineStatus    = @NewStatus,
           ModifiedBy    = @ChangedBy,
           ModifiedDate  = GETDATE()
    WHERE  PrLineId = @PrLineId;

    -- Release the un-ordered PR qty back to the BOM.
    -- Cancel: PoCreatedQty is 0 (guarded) → releases full RequiredQty.
    -- Close : releases RequiredQty - PoCreatedQty (keeps the qty already ordered).
    DECLARE @PrReleaseQty DECIMAL(18,4) = @RequiredQty - @PoCreatedQty;
    IF @PrReleaseQty < 0 SET @PrReleaseQty = 0;

    IF @BomDetailId IS NOT NULL AND @BomDetailId > 0
        UPDATE bom
        SET bom.PrCreatedQty = v.NewPr,
            bom.BomStatus     = CASE
                WHEN bom.BomReceivedQty >= bom.BomRequestedQty         THEN 'FullyReceived'
                WHEN bom.BomReceivedQty  > 0                           THEN 'PartialReceived'
                WHEN ISNULL(bom.PoCreatedQty,0) >= bom.BomRequestedQty THEN 'PORaised'
                WHEN ISNULL(bom.PoCreatedQty,0)  > 0                   THEN 'POPartial'
                WHEN v.NewPr >= bom.BomRequestedQty                    THEN 'PRRaised'
                WHEN v.NewPr  > 0                                      THEN 'PRPartial'
                ELSE 'Pending'
            END,
            bom.ModifiedBy   = @ChangedBy,
            bom.ModifiedDate = GETDATE()
        FROM PROJ.TBL_BOM_DETAILS bom
        CROSS APPLY (VALUES (
            CASE WHEN ISNULL(bom.PrCreatedQty,0) - @PrReleaseQty < 0 THEN CAST(0 AS DECIMAL(18,4))
                 ELSE ISNULL(bom.PrCreatedQty,0) - @PrReleaseQty END
        )) v(NewPr)
        WHERE bom.BomId = @BomDetailId;

    -- Recalculate PR header status.
    -- Guard: only become 'Ordered' if at least one line is actually Ordered
    -- (prevents an all-Cancelled PR from flipping to Ordered).
    UPDATE PROJ.TBL_PURCHASE_REQUEST
    SET    Status = CASE
               WHEN NOT EXISTS (
                   SELECT 1 FROM PROJ.TBL_PURCHASE_REQUEST_LINE
                   WHERE PrId=@PrId AND IsActive=1
                     AND LineStatus NOT IN ('Ordered','Closed','Cancelled')
               ) AND EXISTS (
                   SELECT 1 FROM PROJ.TBL_PURCHASE_REQUEST_LINE
                   WHERE PrId=@PrId AND IsActive=1 AND LineStatus = 'Ordered'
               ) THEN 'Ordered'
               WHEN EXISTS (
                   SELECT 1 FROM PROJ.TBL_PURCHASE_REQUEST_LINE
                   WHERE PrId=@PrId AND IsActive=1 AND PoCreatedQty > 0
               ) THEN 'Partial'
               ELSE Status
           END,
           ModifiedBy   = @ChangedBy,
           ModifiedDate = GETDATE()
    WHERE  PrId   = @PrId
      AND  Status NOT IN ('Draft','Cancelled','Closed','Rejected');

    SELECT CAST(@PrLineId AS NVARCHAR(20));
END
GO

IF OBJECT_ID(N'[proj].[sp_ChangePRStatus]') IS NOT NULL DROP PROCEDURE [proj].[sp_ChangePRStatus];
GO

CREATE PROCEDURE PROJ.sp_ChangePRStatus
    @PrId      INT,
    @NewStatus NVARCHAR(30),
    @ChangedBy NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    -- ── Guard: block direct approval bypass ───────────────────────────────
    IF @NewStatus = 'Approved'
    BEGIN
        RAISERROR('PR status cannot be set to Approved directly. Use the approval workflow.', 16, 1);
        RETURN;
    END

    -- ── Guard: document must exist and be active ──────────────────────────
    IF NOT EXISTS (SELECT 1 FROM PROJ.TBL_PURCHASE_REQUEST WHERE PrId = @PrId AND IsActive = 1)
    BEGIN
        RAISERROR('Purchase Request not found or is inactive.', 16, 1);
        RETURN;
    END

    -- ── Guard: only allow transitions from safe current states ────────────
    -- Cancelled PRs cannot be re-opened; Approved PRs cannot change except via workflow
    DECLARE @CurrentStatus NVARCHAR(30);
    SELECT @CurrentStatus = Status FROM PROJ.TBL_PURCHASE_REQUEST WHERE PrId = @PrId AND IsActive = 1;

    IF @CurrentStatus = 'Cancelled' AND @NewStatus <> 'Cancelled'
    BEGIN
        RAISERROR('A cancelled PR cannot be re-opened.', 16, 1);
        RETURN;
    END

    IF @CurrentStatus = 'Approved' AND @NewStatus NOT IN ('Draft', 'Cancelled', 'Partial', 'Closed')
    BEGIN
        RAISERROR('An approved PR can only be returned to Draft, Cancelled, set to Partial, or Closed.', 16, 1);
        RETURN;
    END

    -- ── Apply the status change ───────────────────────────────────────────
    UPDATE PROJ.TBL_PURCHASE_REQUEST
    SET    Status       = @NewStatus,
           ModifiedBy   = @ChangedBy,
           ModifiedDate = GETDATE()
    WHERE  PrId = @PrId AND IsActive = 1;

    -- When a PR is returned to Draft, cancel the existing approval transaction
    -- so the user can re-submit for approval.
    IF @NewStatus = 'Draft'
    BEGIN
        UPDATE PROJ.TBL_APPROVAL_TRANSACTION
        SET    CurrentStatus  = 'Cancelled',
               FinalAction    = 'Cancelled',
               FinalActionBy  = @ChangedBy,
               FinalRemarks   = 'Cancelled — PR returned to Draft',
               CompletedDate  = GETDATE(),
               ModifiedBy     = @ChangedBy,
               ModifiedDate   = GETDATE()
        WHERE  ModuleId      = 1   -- PR module
          AND  DocumentId    = @PrId
          AND  CurrentStatus NOT IN ('Cancelled', 'Rejected');
    END

    SELECT CAST(@PrId AS NVARCHAR(20));
END
GO

IF OBJECT_ID(N'[proj].[sp_ChangeServiceReceiptStatus]') IS NOT NULL DROP PROCEDURE [proj].[sp_ChangeServiceReceiptStatus];
GO
CREATE PROCEDURE proj.sp_ChangeServiceReceiptStatus
    @SrvId     INT,
    @NewStatus NVARCHAR(30),
    @ChangedBy NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    BEGIN TRY

        DECLARE @CurrentStatus NVARCHAR(30), @PoId INT;
        SELECT @CurrentStatus = Status, @PoId = PoId
        FROM   proj.TBL_SRV_HEADER
        WHERE  SrvId = @SrvId AND IsActive = 1;

        IF @CurrentStatus IS NULL
            THROW 50400, 'Service Receipt not found.', 1;

        IF @CurrentStatus = 'Draft' AND @NewStatus = 'Confirmed'
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM proj.TBL_SRV_LINE WHERE SrvId = @SrvId AND IsActive = 1)
                THROW 50401, 'Cannot confirm a Service Receipt with no lines.', 1;

            -- Subcontract Order for this PO must be Closed before confirming the SRV
            IF @PoId IS NOT NULL
            BEGIN
                IF EXISTS (
                    SELECT 1 FROM proj.TBL_SUBCONTRACT_ORDER
                    WHERE  PoId = @PoId AND IsActive = 1 AND Status <> 'Closed'
                )
                BEGIN
                    DECLARE @ScNo NVARCHAR(50);
                    SELECT @ScNo = SubcontractNo FROM proj.TBL_SUBCONTRACT_ORDER
                    WHERE  PoId = @PoId AND IsActive = 1 AND Status <> 'Closed';
                    DECLARE @ScErr NVARCHAR(300) = 'Cannot confirm: Subcontract Order ' + ISNULL(@ScNo,'') + ' must be Closed before this Service Receipt can be confirmed.';
                    THROW 50403, @ScErr, 1;
                END
            END

            UPDATE pol
            SET    pol.ReceivedQty  = ISNULL(pol.ReceivedQty, 0) + sl.CompletedQty,
                   pol.ModifiedBy   = @ChangedBy,
                   pol.ModifiedDate = GETDATE()
            FROM   proj.TBL_PURCHASE_ORDER_LINE pol
            JOIN   proj.TBL_SRV_LINE            sl ON sl.PoLineId = pol.PoLineId
            WHERE  sl.SrvId = @SrvId AND sl.IsActive = 1 AND sl.PoLineId IS NOT NULL;

            UPDATE pol
            SET    pol.LineStatus = CASE WHEN ISNULL(pol.ReceivedQty,0) <= 0 THEN 'Open'
                                         WHEN ISNULL(pol.ReceivedQty,0) >= pol.OrderedQty THEN 'Received'
                                         ELSE 'Partial' END
            FROM   proj.TBL_PURCHASE_ORDER_LINE pol
            JOIN   proj.TBL_SRV_LINE            sl ON sl.PoLineId = pol.PoLineId
            WHERE  sl.SrvId = @SrvId AND sl.IsActive = 1 AND sl.PoLineId IS NOT NULL
              AND  pol.LineStatus NOT IN ('Closed','Cancelled');

            IF @PoId IS NOT NULL
            BEGIN
                DECLARE @TotalLines INT, @FullyReceived INT;
                SELECT @TotalLines = COUNT(*), @FullyReceived = SUM(CASE WHEN ReceivedQty >= OrderedQty THEN 1 ELSE 0 END)
                FROM   proj.TBL_PURCHASE_ORDER_LINE
                WHERE  PoId = @PoId AND IsActive = 1;

                UPDATE proj.TBL_PURCHASE_ORDER SET
                    Status       = CASE WHEN @FullyReceived = @TotalLines THEN 'Received' ELSE 'Partial' END,
                    ModifiedBy   = @ChangedBy,
                    ModifiedDate = GETDATE()
                WHERE  PoId = @PoId AND Status IN ('Approved','Sent','Partial');
            END
        END

        ELSE IF @CurrentStatus = 'Confirmed' AND @NewStatus = 'Cancelled'
        BEGIN
            UPDATE pol
            SET    pol.ReceivedQty  = CASE WHEN ISNULL(pol.ReceivedQty,0) - sl.CompletedQty < 0
                                           THEN 0 ELSE ISNULL(pol.ReceivedQty,0) - sl.CompletedQty END,
                   pol.ModifiedBy   = @ChangedBy,
                   pol.ModifiedDate = GETDATE()
            FROM   proj.TBL_PURCHASE_ORDER_LINE pol
            JOIN   proj.TBL_SRV_LINE            sl ON sl.PoLineId = pol.PoLineId
            WHERE  sl.SrvId = @SrvId AND sl.IsActive = 1 AND sl.PoLineId IS NOT NULL;

            UPDATE pol
            SET    pol.LineStatus = CASE WHEN ISNULL(pol.ReceivedQty,0) <= 0 THEN 'Open'
                                         WHEN ISNULL(pol.ReceivedQty,0) >= pol.OrderedQty THEN 'Received'
                                         ELSE 'Partial' END
            FROM   proj.TBL_PURCHASE_ORDER_LINE pol
            JOIN   proj.TBL_SRV_LINE            sl ON sl.PoLineId = pol.PoLineId
            WHERE  sl.SrvId = @SrvId AND sl.IsActive = 1 AND sl.PoLineId IS NOT NULL
              AND  pol.LineStatus NOT IN ('Closed','Cancelled');

            IF @PoId IS NOT NULL
            BEGIN
                DECLARE @AnyReceived INT;
                SELECT @AnyReceived = SUM(CASE WHEN ReceivedQty > 0 THEN 1 ELSE 0 END)
                FROM   proj.TBL_PURCHASE_ORDER_LINE
                WHERE  PoId = @PoId AND IsActive = 1;

                UPDATE proj.TBL_PURCHASE_ORDER SET
                    Status       = CASE WHEN @AnyReceived > 0 THEN 'Partial' ELSE 'Sent' END,
                    ModifiedBy   = @ChangedBy,
                    ModifiedDate = GETDATE()
                WHERE  PoId = @PoId AND Status = 'Received';
            END
        END
        ELSE
            THROW 50402, 'Invalid status transition.', 1;

        UPDATE proj.TBL_SRV_HEADER SET
            Status = @NewStatus, ModifiedBy = @ChangedBy, ModifiedDate = GETDATE()
        WHERE SrvId = @SrvId;

        COMMIT;
        SELECT CAST(@SrvId AS NVARCHAR(20));

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        DECLARE @ErrMsg NVARCHAR(MAX) = ERROR_MESSAGE();
        EXEC proj.sp_WriteLog @Action='sp_ChangeServiceReceiptStatus', @Message=@ErrMsg, @UserId=@ChangedBy;
        THROW;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_ChangeSubcontractOrderStatus]') IS NOT NULL DROP PROCEDURE [proj].[sp_ChangeSubcontractOrderStatus];
GO
CREATE PROCEDURE proj.sp_ChangeSubcontractOrderStatus
    @SubcontractId  INT,
    @NewStatus      NVARCHAR(20),
    @ActionBy       NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        DECLARE @CurrentStatus NVARCHAR(20);
        DECLARE @SubcontractType NVARCHAR(20);

        SELECT @CurrentStatus = Status, @SubcontractType = SubcontractType
        FROM proj.TBL_SUBCONTRACT_ORDER
        WHERE SubcontractId = @SubcontractId AND IsActive = 1;

        IF @CurrentStatus IS NULL
            RAISERROR('Subcontract order not found.', 16, 1);

        -- Valid transitions
        IF NOT (
            (@CurrentStatus = 'Draft'      AND @NewStatus = 'Approved')   OR
            (@CurrentStatus = 'Approved'   AND @NewStatus = 'InProgress') OR
            (@CurrentStatus = 'InProgress' AND @NewStatus = 'Received')   OR
            (@CurrentStatus = 'Received'   AND @NewStatus = 'Closed')     OR
            (@CurrentStatus = 'Approved'   AND @NewStatus = 'Cancelled')  OR
            (@CurrentStatus = 'Draft'      AND @NewStatus = 'Cancelled')
        )
            RAISERROR('Invalid status transition from %s to %s.', 16, 1, @CurrentStatus, @NewStatus);

        -- When approving MATERIAL_OUT type, must have at least one component
        IF @NewStatus = 'Approved' AND @SubcontractType = 'MATERIAL_OUT'
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM proj.TBL_SUBCONTRACT_COMPONENT
                           WHERE SubcontractId = @SubcontractId AND IsActive = 1)
                RAISERROR('Cannot approve: no components defined. Add materials to be sent to vendor.', 16, 1);
        END

        -- Cannot close without at least one posted receipt
        IF @NewStatus = 'Closed'
        BEGIN
            IF NOT EXISTS (
                SELECT 1 FROM proj.TBL_SUBCONTRACT_RECEIPT
                WHERE SubcontractId = @SubcontractId AND Status = 'Posted' AND IsActive = 1
            )
                RAISERROR('Cannot close: no receipts have been posted against this order.', 16, 1);
        END

        UPDATE proj.TBL_SUBCONTRACT_ORDER SET
            Status       = @NewStatus,
            ModifiedBy   = @ActionBy,
            ModifiedDate = GETDATE()
        WHERE SubcontractId = @SubcontractId;

        SELECT @NewStatus AS Status;
    END TRY
    BEGIN CATCH
        DECLARE @ErrMsg NVARCHAR(MAX) = ERROR_MESSAGE();
        EXEC proj.sp_WriteLog @Action='sp_ChangeSubcontractOrderStatus', @Message=@ErrMsg, @UserId=@ActionBy;
        THROW;
    END CATCH
END;
GO

IF OBJECT_ID(N'[proj].[sp_ChangeSupplierInvoiceStatus]') IS NOT NULL DROP PROCEDURE [proj].[sp_ChangeSupplierInvoiceStatus];
GO
CREATE PROCEDURE proj.sp_ChangeSupplierInvoiceStatus
    @SupplierInvoiceId INT,
    @NewStatus         NVARCHAR(20),
    @ActionBy          NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CurrentStatus NVARCHAR(20);
    SELECT @CurrentStatus = Status FROM proj.TBL_SUPPLIER_INVOICE
    WHERE SupplierInvoiceId = @SupplierInvoiceId AND IsActive = 1;

    IF @CurrentStatus IS NULL
    BEGIN SELECT 'Invoice not found.'; RETURN; END

    IF NOT (
        (@CurrentStatus = 'Draft'     AND @NewStatus = 'Submitted') OR
        (@CurrentStatus = 'Submitted' AND @NewStatus = 'Approved')  OR
        (@CurrentStatus = 'Approved'  AND @NewStatus = 'Posted')    OR
        (@CurrentStatus = 'Submitted' AND @NewStatus = 'Draft')
    )
    BEGIN SELECT 'Invalid status transition from ' + @CurrentStatus + ' to ' + @NewStatus; RETURN; END

    IF @NewStatus = 'Submitted' AND NOT EXISTS (
        SELECT 1 FROM proj.TBL_SUPPLIER_INVOICE_LINE
        WHERE SupplierInvoiceId = @SupplierInvoiceId AND IsActive = 1
    )
    BEGIN SELECT 'Cannot submit an invoice with no lines.'; RETURN; END

    UPDATE proj.TBL_SUPPLIER_INVOICE
    SET    Status       = @NewStatus,
           ModifiedBy   = @ActionBy,
           ModifiedDate = GETDATE()
    WHERE  SupplierInvoiceId = @SupplierInvoiceId;

    IF @NewStatus = 'Posted'
    BEGIN
        -- Mark linked GRNs as Invoiced
        UPDATE gh
        SET    gh.Status       = 'Invoiced',
               gh.ModifiedBy   = @ActionBy,
               gh.ModifiedDate = GETDATE()
        FROM   proj.TBL_GRN_HEADER gh
        WHERE  gh.IsActive = 1
          AND  gh.Status   = 'Received'
          AND  gh.GrnId IN (
              SELECT DISTINCT sil.GrnId
              FROM proj.TBL_SUPPLIER_INVOICE_LINE sil
              WHERE sil.SupplierInvoiceId = @SupplierInvoiceId
                AND sil.IsActive = 1 AND sil.GrnId IS NOT NULL
          );

        -- Mark linked SRVs as Invoiced
        UPDATE sh
        SET    sh.Status       = 'Invoiced',
               sh.ModifiedBy   = @ActionBy,
               sh.ModifiedDate = GETDATE()
        FROM   proj.TBL_SRV_HEADER sh
        WHERE  sh.IsActive = 1
          AND  sh.Status   = 'Confirmed'
          AND  sh.SrvId IN (
              SELECT DISTINCT sil.SrvId
              FROM proj.TBL_SUPPLIER_INVOICE_LINE sil
              WHERE sil.SupplierInvoiceId = @SupplierInvoiceId
                AND sil.IsActive = 1 AND sil.SrvId IS NOT NULL
          );
    END

    SELECT 'OK';
END
GO

IF OBJECT_ID(N'[proj].[sp_ChangeUserPassword]') IS NOT NULL DROP PROCEDURE [proj].[sp_ChangeUserPassword];
GO

CREATE   PROCEDURE proj.sp_ChangeUserPassword
    @UserId          INT,
    @OldPasswordHash NVARCHAR(255),
    @NewPasswordHash NVARCHAR(255)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CurrentHash NVARCHAR(510), @IsActive BIT;
    SELECT @CurrentHash = PasswordHash, @IsActive = IsActive
    FROM   proj.TBL_USERS
    WHERE  UserId = @UserId;

    IF @CurrentHash IS NULL
    BEGIN
        SELECT 0 AS Success, N'User not found.' AS ErrorMessage; RETURN;
    END
    IF @IsActive = 0
    BEGIN
        SELECT 0 AS Success, N'This account is inactive.' AS ErrorMessage; RETURN;
    END
    IF @CurrentHash <> @OldPasswordHash
    BEGIN
        SELECT 0 AS Success, N'Your current password is incorrect.' AS ErrorMessage; RETURN;
    END
    IF @NewPasswordHash = @OldPasswordHash
    BEGIN
        SELECT 0 AS Success, N'The new password must be different from the current password.' AS ErrorMessage; RETURN;
    END

    UPDATE proj.TBL_USERS
    SET    PasswordHash       = @NewPasswordHash,
           LastPasswordChange = GETDATE(),
           ModifiedBy         = N'SelfService',
           ModifiedDate       = GETDATE()
    WHERE  UserId = @UserId;

    SELECT 1 AS Success, CAST(NULL AS NVARCHAR(200)) AS ErrorMessage;
END
GO

IF OBJECT_ID(N'[proj].[sp_CheckApprovalCustomerCredit]') IS NOT NULL DROP PROCEDURE [proj].[sp_CheckApprovalCustomerCredit];
GO
CREATE   PROCEDURE proj.sp_CheckApprovalCustomerCredit
    @TransactionId INT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @ModuleCode NVARCHAR(20), @DocumentId INT, @CustomerId INT;

    SELECT @ModuleCode = m.ModuleCode, @DocumentId = t.DocumentId
    FROM   proj.TBL_APPROVAL_TRANSACTION t
    JOIN   proj.TBL_APPROVAL_MODULE      m ON m.ModuleId = t.ModuleId
    WHERE  t.TransactionId = @TransactionId;

    -- Only invoices carry a credit-hold gate today
    IF @ModuleCode = 'INV'
        SELECT @CustomerId = CustomerId FROM proj.TBL_INVOICE WHERE InvoiceId = @DocumentId;

    -- No customer to check → allow
    IF @CustomerId IS NULL
    BEGIN
        SELECT 0 AS CustomerId, CAST(NULL AS NVARCHAR(200)) AS CustomerName,
               CAST(0 AS BIT) AS CreditHold, CAST(NULL AS NVARCHAR(500)) AS CreditHoldNote,
               CAST(NULL AS DECIMAL(18,2)) AS CreditLimit, 'GREEN' AS CreditFlag,
               1 AS CanTransact, 'OK' AS StatusMessage;
        RETURN;
    END

    EXEC proj.sp_CheckCustomerCreditStatus @CustomerId;
END
GO

IF OBJECT_ID(N'[proj].[sp_CheckCustomerCreditStatus]') IS NOT NULL DROP PROCEDURE [proj].[sp_CheckCustomerCreditStatus];
GO

CREATE PROCEDURE proj.sp_CheckCustomerCreditStatus
    @CustomerId INT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CreditLimit    DECIMAL(18,2),
            @CreditDays     INT,
            @CreditHold     BIT,
            @AutoHold       BIT,
            @CustomerName   NVARCHAR(200),
            @CreditFlag     NVARCHAR(20),
            @CreditHoldNote NVARCHAR(200);

    SELECT  @CreditLimit    = ISNULL(CreditLimit, 0),
            @CreditDays     = ISNULL(CreditDays,  0),
            @CreditHold     = ISNULL(CreditHold,  0),
            @AutoHold       = ISNULL(AutoHold,    0),
            @CustomerName   = CustomerName,
            @CreditFlag     = CreditFlag,
            @CreditHoldNote = CreditHoldNote
    FROM    proj.TBL_CUSTOMER
    WHERE   CustomerId = @CustomerId;

    ;WITH Alloc AS (
        SELECT a.InvoiceId,
               SUM(CASE WHEN a.IsActive=1 THEN a.AllocatedAmount ELSE 0 END) AS RvPaid
        FROM proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
        JOIN proj.TBL_RECEIPT_VOUCHER rv ON a.RvId = rv.RvId
        WHERE rv.Status = 'Approved' AND rv.IsActive = 1 GROUP BY a.InvoiceId
    ),
    CnAlloc AS (
        SELECT a.InvoiceId,
               SUM(CASE WHEN a.IsActive=1 THEN a.AllocatedAmount ELSE 0 END) AS CnPaid
        FROM proj.TBL_CREDIT_NOTE_ALLOCATION a
        JOIN proj.TBL_CREDIT_NOTE cn ON a.CnId = cn.CnId
        WHERE cn.Status = 'Approved' AND cn.IsActive = 1 GROUP BY a.InvoiceId
    ),
    InvCalc AS (
        SELECT
            i.InvoiceId,
            i.TotalAmount * ISNULL(i.ExchangeRate, 1)
                - ISNULL(al.RvPaid,0) - ISNULL(cn.CnPaid,0)  AS PendingAmtBase,
            CASE
                WHEN i.DueDate IS NOT NULL THEN i.DueDate
                WHEN @CreditDays > 0       THEN DATEADD(DAY, @CreditDays, CAST(i.InvoiceDate AS DATE))
                ELSE NULL
            END AS EffectiveDueDate
        FROM proj.TBL_INVOICE i
        LEFT JOIN Alloc   al ON al.InvoiceId = i.InvoiceId
        LEFT JOIN CnAlloc cn ON cn.InvoiceId = i.InvoiceId
        WHERE i.CustomerId = @CustomerId
          AND i.IsActive = 1
          AND i.Status NOT IN ('Draft','Cancelled')
    )
    SELECT
        @CustomerId                                                           AS CustomerId,
        @CustomerName                                                         AS CustomerName,
        @CreditHold                                                           AS CreditHold,
        @AutoHold                                                             AS IsAutoHold,
        @CreditHoldNote                                                       AS CreditHoldNote,
        @CreditLimit                                                          AS CreditLimit,
        @CreditDays                                                           AS CreditDays,
        @CreditFlag                                                           AS CreditFlag,
        ISNULL(SUM(PendingAmtBase), 0)                                        AS OutstandingBalance,
        ISNULL(MAX(CASE
            WHEN EffectiveDueDate IS NOT NULL
             AND EffectiveDueDate < CAST(GETDATE() AS DATE)
             AND PendingAmtBase > 0
            THEN DATEDIFF(DAY, EffectiveDueDate, GETDATE())
            ELSE 0 END), 0)                                                   AS MaxOverdueDays,
        CAST(CASE WHEN @CreditLimit > 0
                   AND ISNULL(SUM(PendingAmtBase),0) > @CreditLimit
                  THEN 1 ELSE 0 END AS BIT)                                   AS LimitBreached,
        CAST(CASE WHEN @CreditDays > 0
                   AND ISNULL(MAX(CASE
                        WHEN EffectiveDueDate IS NOT NULL
                         AND EffectiveDueDate < CAST(GETDATE() AS DATE)
                         AND PendingAmtBase > 0
                        THEN DATEDIFF(DAY, EffectiveDueDate, GETDATE())
                        ELSE 0 END), 0) > @CreditDays
                  THEN 1 ELSE 0 END AS BIT)                                   AS DaysBreached,
        CAST(CASE WHEN @CreditHold = 1 THEN 0 ELSE 1 END AS INT)              AS CanTransact,
        CASE
            WHEN @CreditHold = 1 AND @AutoHold = 1 THEN
                CASE WHEN @CreditLimit > 0 AND ISNULL(SUM(PendingAmtBase),0) > @CreditLimit
                     THEN 'Auto hold: outstanding balance exceeds credit limit.'
                     ELSE 'Auto hold: invoice overdue beyond credit days.'
                END
            WHEN @CreditHold = 1 THEN
                ISNULL('Credit hold: ' + @CreditHoldNote, 'Customer is on credit hold.')
            ELSE NULL
        END                                                                    AS StatusMessage
    FROM InvCalc;
END
GO

IF OBJECT_ID(N'[proj].[sp_CheckJobOpenForTransactions]') IS NOT NULL DROP PROCEDURE [proj].[sp_CheckJobOpenForTransactions];
GO

CREATE   PROCEDURE proj.sp_CheckJobOpenForTransactions
    @JobId NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        j.JobId,
        js.IsClosed,
        js.StatusName,
        CASE WHEN js.IsClosed = 1
             THEN 'Job ' + j.JobId + ' is ' + js.StatusName + '. Revise the job to create new transactions.'
             ELSE NULL
        END AS Message
    FROM proj.TBL_JOB j
    JOIN proj.TBL_JOB_STATUS js ON js.JobStatusId = j.JobStatusId
    WHERE j.JobId = @JobId;
END;
GO

IF OBJECT_ID(N'[proj].[sp_CheckUserPassword]') IS NOT NULL DROP PROCEDURE [proj].[sp_CheckUserPassword];
GO
CREATE   PROCEDURE proj.sp_CheckUserPassword
    @UserName     NVARCHAR(100),
    @PasswordHash NVARCHAR(500)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT CASE WHEN EXISTS (
        SELECT 1 FROM proj.TBL_USERS
        WHERE UserName = @UserName AND PasswordHash = @PasswordHash AND IsActive = 1
    ) THEN 1 ELSE 0 END AS IsValid;
END
GO

IF OBJECT_ID(N'[proj].[sp_ClearGRNInvoice]') IS NOT NULL DROP PROCEDURE [proj].[sp_ClearGRNInvoice];
GO
CREATE PROCEDURE proj.sp_ClearGRNInvoice
    @GrnId      INT,
    @ModifiedBy NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM proj.TBL_GRN_HEADER WHERE GrnId = @GrnId AND IsActive = 1)
        RAISERROR('GRN not found.', 16, 1);

    UPDATE proj.TBL_GRN_HEADER
    SET    InvoiceNo    = NULL,
           InvoiceDate  = NULL,
           -- Revert to Received only if currently Invoiced
           Status       = CASE WHEN Status = 'Invoiced' THEN 'Received' ELSE Status END,
           ModifiedBy   = @ModifiedBy,
           ModifiedDate = GETDATE()
    WHERE  GrnId = @GrnId AND IsActive = 1;

    SELECT CAST(@GrnId AS NVARCHAR(20));
END
GO

