CREATE   PROCEDURE PROJ.sp_CloseMOM
    @MomId      INT,
    @ModifiedBy NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE PROJ.TBL_MOM
    SET Status       = 'Closed',
        ModifiedBy   = @ModifiedBy,
        ModifiedDate = GETDATE()
    WHERE MomId = @MomId;
    SELECT CAST(@MomId AS NVARCHAR(20));
END
