IF OBJECT_ID(N'[proj].[sp_ClosePR]') IS NOT NULL DROP PROCEDURE [proj].[sp_ClosePR];
GO
CREATE PROCEDURE PROJ.sp_ClosePR
    @PrId     INT,
    @Reason   NVARCHAR(500),
    @ClosedBy NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    IF LTRIM(RTRIM(ISNULL(@Reason, ''))) = ''
        RAISERROR('A reason is required to close the PR.', 16, 1);

    DECLARE @CurrentStatus NVARCHAR(30);
    SELECT @CurrentStatus = Status
    FROM PROJ.TBL_PURCHASE_REQUEST WHERE PrId = @PrId AND IsActive = 1;

    IF @CurrentStatus IS NULL
        RAISERROR('Purchase Request not found or is inactive.', 16, 1);

    IF @CurrentStatus NOT IN ('Approved', 'Partial')
    BEGIN
        DECLARE @StatusMsg NVARCHAR(200) = 'Cannot close: PR must be Approved or Partial. Current status: '
            + ISNULL(@CurrentStatus, 'Unknown') + '.';
        RAISERROR(@StatusMsg, 16, 1);
    END

    -- Close all Open/Partial lines
    UPDATE PROJ.TBL_PURCHASE_REQUEST_LINE
    SET    LineStatus    = 'Closed',
           ModifiedBy    = @ClosedBy,
           ModifiedDate  = GETDATE()
    WHERE  PrId       = @PrId
      AND  IsActive   = 1
      AND  LineStatus IN ('Open', 'Partial');

    -- Update BOM status for all lines that have a BOM link
    UPDATE bd
    SET    bd.BomStatus     = CASE
               WHEN bd.BomReceivedQty >= bd.BomRequestedQty THEN 'FullyReceived'
               WHEN bd.BomReceivedQty  > 0                  THEN 'PartialReceived'
               WHEN bd.PoCreatedQty   >= bd.BomRequestedQty THEN 'PORaised'
               WHEN bd.PoCreatedQty    > 0                  THEN 'POPartial'
               ELSE                                              'PRClosed'
           END,
           bd.ModifiedBy   = @ClosedBy,
           bd.ModifiedDate = GETDATE()
    FROM   PROJ.TBL_BOM_DETAILS bd
    JOIN   PROJ.TBL_PURCHASE_REQUEST_LINE prl
               ON prl.BomDetailId = bd.BomId
              AND prl.PrId        = @PrId
              AND prl.IsActive    = 1
    WHERE  bd.BomStatus NOT IN ('FullyReceived','PartialReceived','PORaised');

    -- Close the PR header
    UPDATE PROJ.TBL_PURCHASE_REQUEST
    SET    Status       = 'Closed',
           ModifiedBy   = @ClosedBy,
           ModifiedDate = GETDATE()
    WHERE  PrId = @PrId AND IsActive = 1;

    -- Log
    INSERT INTO PROJ.TBL_PR_REVISION_LOG (PrId, RevisionNo, Reason, RevisedBy, RevisedDate)
    VALUES (@PrId, 0, 'CLOSE: ' + @Reason, @ClosedBy, GETDATE());

    SELECT CAST(@PrId AS NVARCHAR(20));
END
GO

IF OBJECT_ID(N'[proj].[sp_ConfirmGRN]') IS NOT NULL DROP PROCEDURE [proj].[sp_ConfirmGRN];
GO

CREATE PROCEDURE proj.sp_ConfirmGRN
    @ReceiptId    INT,
    @ModifiedBy   NVARCHAR(100) = NULL,
    @PasswordHash NVARCHAR(500) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    BEGIN TRY
        IF NOT EXISTS (SELECT 1 FROM proj.TBL_STOCK_RECEIPT WHERE ReceiptId=@ReceiptId AND Status='Draft' AND IsActive=1)
            THROW 50200, 'GRN not found or already confirmed.', 1;
        IF NOT EXISTS (SELECT 1 FROM proj.TBL_STOCK_RECEIPT_LINE WHERE ReceiptId=@ReceiptId AND IsActive=1)
            THROW 50201, 'Cannot confirm a GRN with no lines.', 1;

        IF NULLIF(@ModifiedBy,'') IS NULL
            RAISERROR('User is required to confirm.', 16, 1);
        IF NOT EXISTS (SELECT 1 FROM proj.TBL_USERS
                       WHERE UserName = @ModifiedBy AND PasswordHash = @PasswordHash AND IsActive = 1)
            RAISERROR('Incorrect password. Confirmation not authorised.', 16, 1);

        DECLARE @ReceiptNo NVARCHAR(30), @GrnPoId INT;
        SELECT @ReceiptNo = ReceiptNo, @GrnPoId = PoId
        FROM proj.TBL_STOCK_RECEIPT WHERE ReceiptId = @ReceiptId;

        DECLARE @LineId INT, @ItemId INT, @Qty DECIMAL(18,4), @UnitCost DECIMAL(18,4),
                @IsJobStock BIT, @LineJobId NVARCHAR(50), @UomId INT,
                @BaseUomId INT, @ConvFactor DECIMAL(18,6),
                @StockQty DECIMAL(18,4), @StockUnitCost DECIMAL(18,4),
                @ConvErrMsg NVARCHAR(400),
                @EffIsJobStock BIT, @IsInHouseJob BIT;

        DECLARE cur CURSOR FOR
            SELECT ReceiptLineId, ItemId, Qty, UnitCost, IsJobStock, JobId, UomId
            FROM proj.TBL_STOCK_RECEIPT_LINE
            WHERE ReceiptId=@ReceiptId AND IsActive=1;

        OPEN cur;
        FETCH NEXT FROM cur INTO @LineId, @ItemId, @Qty, @UnitCost, @IsJobStock, @LineJobId, @UomId;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            SELECT @BaseUomId = BaseUomId FROM proj.TBL_ITEM WHERE ItemId = @ItemId;
            SET @ConvFactor = NULL;
            IF @UomId IS NOT NULL AND @BaseUomId IS NOT NULL AND @UomId <> @BaseUomId
            BEGIN
                SELECT @ConvFactor = ConversionFactor
                FROM proj.TBL_ITEM_UOM_CONVERSION
                WHERE ItemId=@ItemId AND FromUomId=@UomId AND ToUomId=@BaseUomId AND IsActive=1;
                IF @ConvFactor IS NULL OR @ConvFactor = 0
                BEGIN
                    SET @ConvErrMsg = 'No UOM conversion defined for item ' +
                        ISNULL((SELECT ItemCode FROM proj.TBL_ITEM WHERE ItemId=@ItemId), CAST(@ItemId AS NVARCHAR(20))) +
                        ' (' + ISNULL((SELECT UomCode FROM proj.TBL_ITEM_UOM WHERE UomId=@UomId), '?') +
                        ' to ' + ISNULL((SELECT UomCode FROM proj.TBL_ITEM_UOM WHERE UomId=@BaseUomId), '?') +
                        '). Configure it in Item master > UOM Conversions.';
                    RAISERROR(@ConvErrMsg, 16, 1);
                END
                SET @StockQty      = @Qty * @ConvFactor;
                SET @StockUnitCost = @UnitCost / @ConvFactor;
            END
            ELSE
            BEGIN
                SET @StockQty      = @Qty;
                SET @StockUnitCost = @UnitCost;
            END

            -- Detect in-house (budget-header-linked) job. In-house GRN receipts
            -- go into QtyStoreStock (IsJobStock=0) — the computed column handles
            -- the display automatically. Only non-in-house job-tagged GRNs
            -- (EXC_COSTING etc.) increment QtyJobStock (IsJobStock=1).
            SET @IsInHouseJob = 0;
            IF NULLIF(@LineJobId,'') IS NOT NULL
            BEGIN
                SELECT @IsInHouseJob = ISNULL(jt.IsBudgetHeaderLinked, 0)
                FROM proj.TBL_JOB j
                JOIN proj.TBL_JOBTYPE jt ON jt.JobTypeId = j.JobTypeId
                WHERE j.JobId = @LineJobId;
            END
            SET @EffIsJobStock = CASE WHEN NULLIF(@LineJobId,'') IS NOT NULL AND @IsInHouseJob = 0 THEN 1 ELSE 0 END;

            IF EXISTS (SELECT 1 FROM proj.TBL_STOCK_BALANCE WHERE ItemId=@ItemId)
            BEGIN
                DECLARE @OldQty DECIMAL(18,4), @OldCost DECIMAL(18,4), @OldJobQty DECIMAL(18,4);
                SELECT @OldQty=QtyOnHand, @OldCost=AvgUnitCost, @OldJobQty=QtyJobStock
                FROM proj.TBL_STOCK_BALANCE WHERE ItemId=@ItemId;

                DECLARE @NewAvgCost DECIMAL(18,4) =
                    CASE WHEN (@OldQty + @StockQty) > 0
                         THEN ((@OldQty * @OldCost) + (@StockQty * @StockUnitCost)) / (@OldQty + @StockQty)
                         ELSE @StockUnitCost END;

                UPDATE proj.TBL_STOCK_BALANCE
                SET QtyOnHand       = QtyOnHand + @StockQty,
                    QtyJobStock     = QtyJobStock + CASE WHEN @EffIsJobStock=1 THEN @StockQty ELSE 0 END,
                    AvgUnitCost     = @NewAvgCost,
                    LastReceiptDate = GETDATE(),
                    UpdatedDate     = GETDATE()
                WHERE ItemId = @ItemId;
            END
            ELSE
            BEGIN
                INSERT INTO proj.TBL_STOCK_BALANCE
                    (ItemId, QtyOnHand, QtyJobStock, AvgUnitCost, LastReceiptDate, UpdatedDate)
                VALUES
                    (@ItemId, @StockQty, CASE WHEN @EffIsJobStock=1 THEN @StockQty ELSE 0 END, @StockUnitCost, GETDATE(), GETDATE());
            END

            -- JobId kept for traceability; IsJobStock=0 for in-house so it
            -- shows as store stock rather than job-committed stock.
            INSERT INTO proj.TBL_STOCK_LEDGER
                (ItemId, TransType, RefId, RefNo, QtyIn, QtyOut, UnitCost, IsJobStock, JobId, CreatedBy)
            VALUES
                (@ItemId, 'RECEIPT', @ReceiptId, @ReceiptNo, @StockQty, 0, @StockUnitCost,
                 @EffIsJobStock, NULLIF(@LineJobId,''), @ModifiedBy);

            FETCH NEXT FROM cur INTO @LineId, @ItemId, @Qty, @UnitCost, @IsJobStock, @LineJobId, @UomId;
        END
        CLOSE cur; DEALLOCATE cur;

        UPDATE proj.TBL_STOCK_RECEIPT
        SET Status=N'Confirmed', ModifiedBy=@ModifiedBy, ModifiedDate=GETDATE()
        WHERE ReceiptId=@ReceiptId;

        -- Auto-advance linked PO to Sent on first confirmed GRN for this PO.
        -- Status guard is idempotent across multiple GRNs and rollback-safe
        -- (inside the same transaction).
        IF @GrnPoId IS NOT NULL
        BEGIN
            UPDATE proj.TBL_PURCHASE_ORDER
            SET Status       = 'Sent',
                PoSentDate   = ISNULL(PoSentDate, GETDATE()),
                ModifiedBy   = @ModifiedBy,
                ModifiedDate = GETDATE()
            WHERE PoId     = @GrnPoId
              AND Status   NOT IN ('Sent', 'Received', 'Closed', 'Cancelled')
              AND IsActive = 1;
        END

        COMMIT;
        SELECT @ReceiptNo AS ReceiptNo, N'Confirmed' AS Status;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        IF CURSOR_STATUS('global','cur') >= 0 BEGIN CLOSE cur; DEALLOCATE cur; END;
        THROW;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_ConfirmInvoice]') IS NOT NULL DROP PROCEDURE [proj].[sp_ConfirmInvoice];
GO
CREATE   PROCEDURE PROJ.sp_ConfirmInvoice
    @InvoiceId  INT,
    @ModifiedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM PROJ.TBL_INVOICE WHERE InvoiceId = @InvoiceId AND Status = 'Draft' AND IsActive = 1) BEGIN RAISERROR('Invoice not found or is not in Draft status.', 16, 1); RETURN; END
    IF NOT EXISTS (SELECT 1 FROM PROJ.TBL_INVOICE_LINE WHERE InvoiceId = @InvoiceId AND IsActive = 1) BEGIN RAISERROR('Cannot confirm an Invoice with no lines.', 16, 1); RETURN; END

    UPDATE PROJ.TBL_INVOICE
    SET Status = 'Confirmed', ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE()
    WHERE InvoiceId = @InvoiceId;

    SELECT InvoiceNo, Status FROM PROJ.TBL_INVOICE WHERE InvoiceId = @InvoiceId;
END;
GO

IF OBJECT_ID(N'[proj].[sp_ConfirmIssueReturn]') IS NOT NULL DROP PROCEDURE [proj].[sp_ConfirmIssueReturn];
GO

CREATE PROCEDURE proj.sp_ConfirmIssueReturn
    @ReturnId     INT,
    @ModifiedBy   NVARCHAR(100),
    @PasswordHash NVARCHAR(500) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    BEGIN TRY

        IF NULLIF(@PasswordHash, '') IS NULL
            RAISERROR('Password is required to confirm an issue return.', 16, 1);

        IF NOT EXISTS (
            SELECT 1 FROM proj.TBL_USERS
            WHERE UserName = @ModifiedBy AND PasswordHash = @PasswordHash AND IsActive = 1
        )
            RAISERROR('Incorrect password. Confirmation not authorised.', 16, 1);

        DECLARE @IssueId INT, @ReturnNo NVARCHAR(30), @ReturnDate DATE;
        SELECT @IssueId = r.IssueId, @ReturnNo = r.ReturnNo, @ReturnDate = r.ReturnDate
        FROM proj.TBL_STOCK_ISSUE_RETURN r
        WHERE r.ReturnId = @ReturnId AND r.Status = 'Draft' AND r.IsActive = 1;

        IF @IssueId IS NULL
            RAISERROR('Return note not found or is not in Draft status.', 16, 1);

        IF NOT EXISTS (SELECT 1 FROM proj.TBL_STOCK_ISSUE_RETURN_LINE WHERE ReturnId = @ReturnId)
            RAISERROR('Cannot confirm a return with no lines.', 16, 1);

        DECLARE @CostingType NVARCHAR(20), @JobId NVARCHAR(50);
        SELECT @CostingType = CostingType, @JobId = JobId
        FROM proj.TBL_STOCK_ISSUE WHERE IssueId = @IssueId;

        DECLARE @ReturnLineId INT, @ItemId INT, @ReturnQty DECIMAL(18,4), @UnitCost DECIMAL(18,4), @UomId INT,
                @BaseUomId INT, @ConvFactor DECIMAL(18,6),
                @StockQty DECIMAL(18,4), @StockUnitCost DECIMAL(18,4),
                @ConvErrMsg NVARCHAR(400), @SourceJobId NVARCHAR(50);

        DECLARE line_cur CURSOR LOCAL FAST_FORWARD FOR
            SELECT ReturnLineId, ItemId, ReturnQty, UnitCost, UomId
            FROM proj.TBL_STOCK_ISSUE_RETURN_LINE
            WHERE ReturnId = @ReturnId;

        OPEN line_cur;
        FETCH NEXT FROM line_cur INTO @ReturnLineId, @ItemId, @ReturnQty, @UnitCost, @UomId;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            SELECT @BaseUomId = BaseUomId FROM proj.TBL_ITEM WHERE ItemId = @ItemId;
            SET @ConvFactor = NULL;
            IF @UomId IS NOT NULL AND @BaseUomId IS NOT NULL AND @UomId <> @BaseUomId
            BEGIN
                SELECT @ConvFactor = ConversionFactor
                FROM proj.TBL_ITEM_UOM_CONVERSION
                WHERE ItemId=@ItemId AND FromUomId=@UomId AND ToUomId=@BaseUomId AND IsActive=1;
                IF @ConvFactor IS NULL OR @ConvFactor = 0
                BEGIN
                    SET @ConvErrMsg = 'No UOM conversion defined for item ' +
                        ISNULL((SELECT ItemCode FROM proj.TBL_ITEM WHERE ItemId=@ItemId), CAST(@ItemId AS NVARCHAR(20))) +
                        ' (' + ISNULL((SELECT UomCode FROM proj.TBL_ITEM_UOM WHERE UomId=@UomId), '?') +
                        ' to ' + ISNULL((SELECT UomCode FROM proj.TBL_ITEM_UOM WHERE UomId=@BaseUomId), '?') +
                        '). Configure it in Item master > UOM Conversions.';
                    RAISERROR(@ConvErrMsg, 16, 1);
                END
                SET @StockQty      = @ReturnQty * @ConvFactor;
                SET @StockUnitCost = @UnitCost / @ConvFactor;
            END
            ELSE
            BEGIN
                SET @StockQty      = @ReturnQty;
                SET @StockUnitCost = @UnitCost;
            END

            SET @SourceJobId = NULL;
            SELECT TOP 1 @SourceJobId = j.JobId
            FROM proj.TBL_ITEM it
            JOIN proj.TBL_JOB        j  ON j.BudgetCategoryId = it.BudgetCategoryId
            JOIN proj.TBL_JOBTYPE    jt ON jt.JobTypeId = j.JobTypeId AND ISNULL(jt.IsBudgetHeaderLinked,0) = 1
            JOIN proj.TBL_JOB_STATUS js ON js.JobStatusId = j.JobStatusId AND ISNULL(js.IsClosed,0) = 0
            WHERE it.ItemId = @ItemId AND it.BudgetCategoryId IS NOT NULL
            ORDER BY j.JobCreatedDate DESC;

            IF @SourceJobId IS NOT NULL
            BEGIN
                INSERT INTO proj.TBL_STOCK_LEDGER
                    (ItemId, TransDate, TransType, RefId, RefNo, QtyIn, QtyOut, UnitCost, IsJobStock, JobId, CreatedBy)
                VALUES (@ItemId, @ReturnDate, 'RETURN', @ReturnId, @ReturnNo,
                        @StockQty, 0, @StockUnitCost, 0, @SourceJobId, @ModifiedBy);

                UPDATE proj.TBL_STOCK_BALANCE
                SET QtyOnHand = QtyOnHand + @StockQty, UpdatedDate = GETDATE()
                WHERE ItemId = @ItemId;

                IF @@ROWCOUNT = 0
                    INSERT INTO proj.TBL_STOCK_BALANCE (ItemId, QtyOnHand, QtyJobStock, AvgUnitCost, UpdatedDate)
                    VALUES (@ItemId, @StockQty, 0, @StockUnitCost, GETDATE());
            END
            ELSE
            BEGIN
                DECLARE @IsJobStock BIT = CASE WHEN @CostingType = 'EXC_COSTING' THEN 1 ELSE 0 END;

                INSERT INTO proj.TBL_STOCK_LEDGER
                    (ItemId, TransDate, TransType, RefId, RefNo, QtyIn, QtyOut, UnitCost, IsJobStock, JobId, CreatedBy)
                VALUES (@ItemId, @ReturnDate, 'RETURN', @ReturnId, @ReturnNo,
                        @StockQty, 0, @StockUnitCost, @IsJobStock, @JobId, @ModifiedBy);

                IF @CostingType = 'INC_COSTING'
                BEGIN
                    UPDATE proj.TBL_STOCK_BALANCE
                    SET QtyOnHand = QtyOnHand + @StockQty, UpdatedDate = GETDATE()
                    WHERE ItemId = @ItemId;
                    IF @@ROWCOUNT = 0
                        INSERT INTO proj.TBL_STOCK_BALANCE (ItemId, QtyOnHand, QtyJobStock, AvgUnitCost, UpdatedDate)
                        VALUES (@ItemId, @StockQty, 0, @StockUnitCost, GETDATE());
                END
                ELSE
                BEGIN
                    UPDATE proj.TBL_STOCK_BALANCE
                    SET QtyOnHand   = QtyOnHand   + @StockQty,
                        QtyJobStock = QtyJobStock + @StockQty,
                        UpdatedDate = GETDATE()
                    WHERE ItemId = @ItemId;
                    IF @@ROWCOUNT = 0
                        INSERT INTO proj.TBL_STOCK_BALANCE (ItemId, QtyOnHand, QtyJobStock, AvgUnitCost, UpdatedDate)
                        VALUES (@ItemId, @StockQty, @StockQty, @StockUnitCost, GETDATE());
                END
            END

            FETCH NEXT FROM line_cur INTO @ReturnLineId, @ItemId, @ReturnQty, @UnitCost, @UomId;
        END

        CLOSE line_cur; DEALLOCATE line_cur;

        UPDATE proj.TBL_STOCK_ISSUE_RETURN
        SET Status = 'Confirmed', ModifiedBy = @ModifiedBy, ModifiedDate = SYSDATETIME()
        WHERE ReturnId = @ReturnId;

        COMMIT TRANSACTION;
        SELECT @ReturnId AS ReturnId, 'Confirmed' AS NewStatus;

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        IF CURSOR_STATUS('local','line_cur') >= 0 BEGIN CLOSE line_cur; DEALLOCATE line_cur; END
        DECLARE @ErrMsg NVARCHAR(2048) = ERROR_MESSAGE();
        RAISERROR(@ErrMsg, 16, 1);
    END CATCH
END;
GO

IF OBJECT_ID(N'[proj].[sp_ConfirmStockIssue]') IS NOT NULL DROP PROCEDURE [proj].[sp_ConfirmStockIssue];
GO

CREATE PROCEDURE proj.sp_ConfirmStockIssue
    @IssueId    INT,
    @ModifiedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    BEGIN TRY
        IF NOT EXISTS (
            SELECT 1 FROM proj.TBL_STOCK_ISSUE
            WHERE IssueId = @IssueId AND Status = 'Draft' AND IsActive = 1)
            THROW 50300, 'Issue Note not found or already confirmed.', 1;

        IF NOT EXISTS (
            SELECT 1 FROM proj.TBL_STOCK_ISSUE_LINE
            WHERE IssueId = @IssueId AND IsActive = 1)
            THROW 50301, 'Cannot confirm an Issue Note with no lines.', 1;

        DECLARE @IssueNo NVARCHAR(30), @JobId NVARCHAR(50), @CostingType NVARCHAR(20);
        SELECT @IssueNo = IssueNo, @JobId = JobId, @CostingType = CostingType
        FROM proj.TBL_STOCK_ISSUE WHERE IssueId = @IssueId;

        DECLARE @ItemId INT, @Qty DECIMAL(18,4), @UnitCost DECIMAL(18,4), @UomId INT,
                @BaseUomId INT, @ConvFactor DECIMAL(18,6),
                @StockQty DECIMAL(18,4), @StockUnitCost DECIMAL(18,4),
                @ConvErrMsg NVARCHAR(400),
                @SourceJobId NVARCHAR(50), @SrcBal DECIMAL(18,4), @ShortMsg NVARCHAR(400);

        DECLARE cur CURSOR FOR
            SELECT ItemId, Qty, UnitCost, UomId
            FROM proj.TBL_STOCK_ISSUE_LINE
            WHERE IssueId = @IssueId AND IsActive = 1;

        OPEN cur;
        FETCH NEXT FROM cur INTO @ItemId, @Qty, @UnitCost, @UomId;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            SELECT @BaseUomId = BaseUomId FROM proj.TBL_ITEM WHERE ItemId = @ItemId;
            SET @ConvFactor = NULL;
            IF @UomId IS NOT NULL AND @BaseUomId IS NOT NULL AND @UomId <> @BaseUomId
            BEGIN
                SELECT @ConvFactor = ConversionFactor
                FROM proj.TBL_ITEM_UOM_CONVERSION
                WHERE ItemId=@ItemId AND FromUomId=@UomId AND ToUomId=@BaseUomId AND IsActive=1;
                IF @ConvFactor IS NULL OR @ConvFactor = 0
                BEGIN
                    SET @ConvErrMsg = 'No UOM conversion defined for item ' +
                        ISNULL((SELECT ItemCode FROM proj.TBL_ITEM WHERE ItemId=@ItemId), CAST(@ItemId AS NVARCHAR(20))) +
                        ' (' + ISNULL((SELECT UomCode FROM proj.TBL_ITEM_UOM WHERE UomId=@UomId), '?') +
                        ' to ' + ISNULL((SELECT UomCode FROM proj.TBL_ITEM_UOM WHERE UomId=@BaseUomId), '?') +
                        '). Configure it in Item master > UOM Conversions.';
                    RAISERROR(@ConvErrMsg, 16, 1);
                END
                SET @StockQty      = @Qty * @ConvFactor;
                SET @StockUnitCost = @UnitCost / @ConvFactor;
            END
            ELSE
            BEGIN
                SET @StockQty      = @Qty;
                SET @StockUnitCost = @UnitCost;
            END

            -- Derive the SOURCE in-house job for this item via its budget header
            SET @SourceJobId = NULL;
            SELECT TOP 1 @SourceJobId = j.JobId
            FROM proj.TBL_ITEM it
            JOIN proj.TBL_JOB        j  ON j.BudgetCategoryId = it.BudgetCategoryId
            JOIN proj.TBL_JOBTYPE    jt ON jt.JobTypeId = j.JobTypeId AND ISNULL(jt.IsBudgetHeaderLinked,0) = 1
            JOIN proj.TBL_JOB_STATUS js ON js.JobStatusId = j.JobStatusId AND ISNULL(js.IsClosed,0) = 0
            WHERE it.ItemId = @ItemId AND it.BudgetCategoryId IS NOT NULL
            ORDER BY j.JobCreatedDate DESC;

            IF @SourceJobId IS NOT NULL
            BEGIN
                -- In-house GRN receipts are stored with IsJobStock=0 (store stock).
                -- Balance check uses JobId only (no IsJobStock filter) to handle
                -- both new receipts and any legacy IsJobStock=1 entries.
                SELECT @SrcBal = ISNULL(SUM(QtyIn - QtyOut), 0)
                FROM proj.TBL_STOCK_LEDGER
                WHERE ItemId = @ItemId AND JobId = @SourceJobId;

                IF @SrcBal < @StockQty
                BEGIN
                    SET @ShortMsg = 'Insufficient in-house stock for item ' +
                        ISNULL((SELECT ItemCode FROM proj.TBL_ITEM WHERE ItemId=@ItemId), CAST(@ItemId AS NVARCHAR(20))) +
                        ' in job ' + @SourceJobId + ' (have ' + CAST(@SrcBal AS NVARCHAR(30)) +
                        ', need ' + CAST(@StockQty AS NVARCHAR(30)) + ').';
                    THROW 50304, @ShortMsg, 1;
                END

                -- Only QtyOnHand decreases; QtyStoreStock (computed = QtyOnHand - QtyJobStock)
                -- auto-decreases. QtyJobStock is NOT touched for in-house stock.
                UPDATE proj.TBL_STOCK_BALANCE
                SET QtyOnHand     = QtyOnHand - @StockQty,
                    LastIssueDate = GETDATE(),
                    UpdatedDate   = GETDATE()
                WHERE ItemId = @ItemId;

                INSERT INTO proj.TBL_STOCK_LEDGER
                    (ItemId, TransType, RefId, RefNo, QtyIn, QtyOut, UnitCost, IsJobStock, JobId, CreatedBy)
                VALUES
                    (@ItemId, 'ISSUE', @IssueId, @IssueNo, 0, @StockQty, @StockUnitCost,
                     0, @SourceJobId, @ModifiedBy);
            END
            ELSE IF @CostingType = 'EXC_COSTING'
            BEGIN
                UPDATE proj.TBL_STOCK_BALANCE
                SET QtyJobStock   = QtyJobStock - @StockQty,
                    QtyOnHand     = CASE WHEN QtyOnHand - @StockQty < 0 THEN 0 ELSE QtyOnHand - @StockQty END,
                    LastIssueDate = GETDATE(), UpdatedDate = GETDATE()
                WHERE ItemId = @ItemId AND ISNULL(QtyJobStock,0) >= @StockQty;

                IF @@ROWCOUNT = 0
                    THROW 50302, 'Insufficient job stock for one or more items.', 1;

                INSERT INTO proj.TBL_STOCK_LEDGER
                    (ItemId, TransType, RefId, RefNo, QtyIn, QtyOut, UnitCost, IsJobStock, JobId, CreatedBy)
                VALUES
                    (@ItemId, 'ISSUE', @IssueId, @IssueNo, 0, @StockQty, @StockUnitCost, 1, @JobId, @ModifiedBy);
            END
            ELSE
            BEGIN
                UPDATE proj.TBL_STOCK_BALANCE
                SET QtyOnHand     = QtyOnHand - @StockQty,
                    LastIssueDate = GETDATE(), UpdatedDate = GETDATE()
                WHERE ItemId = @ItemId AND ISNULL(QtyOnHand,0) >= @StockQty;

                IF @@ROWCOUNT = 0
                    THROW 50303, 'Insufficient stock for one or more items.', 1;

                INSERT INTO proj.TBL_STOCK_LEDGER
                    (ItemId, TransType, RefId, RefNo, QtyIn, QtyOut, UnitCost, IsJobStock, JobId, CreatedBy)
                VALUES
                    (@ItemId, 'ISSUE', @IssueId, @IssueNo, 0, @StockQty, @StockUnitCost, 0, @JobId, @ModifiedBy);
            END

            FETCH NEXT FROM cur INTO @ItemId, @Qty, @UnitCost, @UomId;
        END
        CLOSE cur; DEALLOCATE cur;

        UPDATE proj.TBL_STOCK_ISSUE
        SET Status = N'Confirmed', ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE()
        WHERE IssueId = @IssueId;

        -- Auto-advance job stage: first confirmed issue note → STAGE3
        IF NOT EXISTS (
            SELECT 1 FROM proj.TBL_STOCK_ISSUE
            WHERE JobId = @JobId AND Status = 'Confirmed' AND IssueId <> @IssueId AND IsActive = 1
        )
        BEGIN
            UPDATE proj.TBL_JOB
            SET JobStageId = 'STAGE3'
            WHERE JobId = @JobId AND JobStageId IN ('STAGE1', 'STAGE2');
        END

        COMMIT;
        SELECT @IssueNo AS IssueNo, N'Confirmed' AS Status;

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        IF CURSOR_STATUS('global','cur') >= 0 BEGIN CLOSE cur; DEALLOCATE cur; END;
        THROW;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_ConfirmStockTransfer]') IS NOT NULL DROP PROCEDURE [proj].[sp_ConfirmStockTransfer];
GO

CREATE PROCEDURE proj.sp_ConfirmStockTransfer
    @TransferId INT,
    @ModifiedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    BEGIN TRY
        DECLARE @TransferNo NVARCHAR(30), @FromJobId NVARCHAR(50), @ToJobId NVARCHAR(50), @TDate DATE;
        SELECT @TransferNo=TransferNo, @FromJobId=FromJobId, @ToJobId=ToJobId, @TDate=TransferDate
        FROM proj.TBL_STOCK_TRANSFER WHERE TransferId=@TransferId AND Status='Draft' AND IsActive=1;

        IF @TransferNo IS NULL THROW 50620, 'Transfer not found or already confirmed.', 1;
        IF NOT EXISTS (SELECT 1 FROM proj.TBL_STOCK_TRANSFER_LINE WHERE TransferId=@TransferId AND IsActive=1)
            THROW 50621, 'Cannot confirm a transfer with no lines.', 1;

        -- Determine if source/destination jobs are in-house (store-stock buckets)
        DECLARE @FromIsInHouse BIT = 0, @ToIsInHouse BIT = 0;
        IF NULLIF(@FromJobId,'') IS NOT NULL
            SELECT @FromIsInHouse = ISNULL(jt.IsBudgetHeaderLinked,0)
            FROM proj.TBL_JOB j JOIN proj.TBL_JOBTYPE jt ON jt.JobTypeId = j.JobTypeId
            WHERE j.JobId = @FromJobId;
        IF NULLIF(@ToJobId,'') IS NOT NULL
            SELECT @ToIsInHouse = ISNULL(jt.IsBudgetHeaderLinked,0)
            FROM proj.TBL_JOB j JOIN proj.TBL_JOBTYPE jt ON jt.JobTypeId = j.JobTypeId
            WHERE j.JobId = @ToJobId;

        DECLARE @ItemId INT, @Qty DECIMAL(18,4), @UnitCost DECIMAL(18,4),
                @Bal DECIMAL(18,4), @Msg NVARCHAR(400);

        DECLARE c CURSOR LOCAL FAST_FORWARD FOR
            SELECT ItemId, Qty, UnitCost FROM proj.TBL_STOCK_TRANSFER_LINE
            WHERE TransferId=@TransferId AND IsActive=1;
        OPEN c;
        FETCH NEXT FROM c INTO @ItemId, @Qty, @UnitCost;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            -- Balance check on JobId only — covers IsJobStock=0 (in-house) and IsJobStock=1
            SELECT @Bal = ISNULL(SUM(QtyIn - QtyOut),0)
            FROM proj.TBL_STOCK_LEDGER
            WHERE ItemId=@ItemId AND JobId=@FromJobId;

            IF @Bal < @Qty
            BEGIN
                SET @Msg = 'Insufficient stock in source job ' + @FromJobId + ' for item ' +
                    ISNULL((SELECT ItemCode FROM proj.TBL_ITEM WHERE ItemId=@ItemId), CAST(@ItemId AS NVARCHAR(20))) +
                    ' (have ' + CAST(@Bal AS NVARCHAR(30)) + ', need ' + CAST(@Qty AS NVARCHAR(30)) + ').';
                THROW 50622, @Msg, 1;
            END

            -- OUT from source, IN to destination.
            -- IsJobStock=0 for in-house jobs (store stock); 1 for regular job buckets.
            -- TBL_STOCK_BALANCE QtyOnHand is net-zero (OUT cancels IN), so no balance update needed.
            INSERT INTO proj.TBL_STOCK_LEDGER
                (ItemId, TransDate, TransType, RefId, RefNo, QtyIn, QtyOut, UnitCost, IsJobStock, JobId, CreatedBy)
            VALUES
                (@ItemId, @TDate, 'TRANSFER', @TransferId, @TransferNo,
                 0, @Qty, @UnitCost, CASE WHEN @FromIsInHouse=1 THEN 0 ELSE 1 END, @FromJobId, @ModifiedBy),
                (@ItemId, @TDate, 'TRANSFER', @TransferId, @TransferNo,
                 @Qty, 0, @UnitCost, CASE WHEN @ToIsInHouse=1 THEN 0 ELSE 1 END, @ToJobId, @ModifiedBy);

            FETCH NEXT FROM c INTO @ItemId, @Qty, @UnitCost;
        END
        CLOSE c; DEALLOCATE c;

        UPDATE proj.TBL_STOCK_TRANSFER
        SET Status='Confirmed', ModifiedBy=@ModifiedBy, ModifiedDate=GETDATE()
        WHERE TransferId=@TransferId;

        COMMIT;
        SELECT @TransferNo AS TransferNo, 'Confirmed' AS Status;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        IF CURSOR_STATUS('local','c') >= 0 BEGIN CLOSE c; DEALLOCATE c; END;
        THROW;
    END CATCH
END;
GO

IF OBJECT_ID(N'[proj].[sp_CopyBom]') IS NOT NULL DROP PROCEDURE [proj].[sp_CopyBom];
GO

CREATE   PROCEDURE proj.sp_CopyBom
    @SourceBomHeaderId INT,
    @TargetJobId       NVARCHAR(50),
    @CreatedBy         NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- ── 1. Validate source BOM ─────────────────────────────────────
    DECLARE @SrcJobId       NVARCHAR(50),
            @SrcJobTypeId   NVARCHAR(10),
            @SrcVersion     INT,
            @SrcStatus      NVARCHAR(20),
            @SrcDescription NVARCHAR(500);

    SELECT  @SrcJobId       = JobId,
            @SrcJobTypeId   = JobTypeId,
            @SrcVersion     = BomVersion,
            @SrcStatus      = BomStatus,
            @SrcDescription = BomDescription
    FROM    proj.TBL_BOM_HEADER
    WHERE   BomHeaderId = @SourceBomHeaderId
      AND   IsActive    = 1;

    IF @SrcJobId IS NULL
        THROW 50001, 'Source BOM not found or is inactive.', 1;

    IF @SrcStatus = 'Cancelled'
        THROW 50002, 'Cannot copy a Cancelled BOM.', 1;

    -- ── 2. Validate target job ─────────────────────────────────────
    DECLARE @TargetJobTypeId NVARCHAR(10);

    SELECT  @TargetJobTypeId = JobTypeId
    FROM    proj.TBL_JOB
    WHERE   JobId = @TargetJobId;

    IF @TargetJobTypeId IS NULL
        THROW 50003, 'Target job not found.', 1;

    -- ── 3. Check no existing active BOM for target job ─────────────
    IF EXISTS (
        SELECT 1 FROM proj.TBL_BOM_HEADER
        WHERE  JobId    = @TargetJobId
          AND  IsActive = 1
    )
        THROW 50004, 'Target job already has an existing BOM. Cannot create a duplicate BOM for the same job.', 1;

    -- ── 4. Insert new BOM header ───────────────────────────────────
    DECLARE @NewBomHeaderId INT;

    INSERT INTO proj.TBL_BOM_HEADER
           (JobId, JobTypeId, BomDate, BomDescription,
            BomVersion, BomStatus, TotalBomValue,
            BomApprovedBy, BomApprovedDate,
            IsActive, CreatedBy, CreatedDate)
    VALUES (@TargetJobId, @TargetJobTypeId, GETDATE(), @SrcDescription,
            1, 'Draft', 0,
            NULL, NULL,
            1, @CreatedBy, GETDATE());

    SET @NewBomHeaderId = SCOPE_IDENTITY();

    -- ── 5. Copy detail lines (reset procurement quantities) ────────
    INSERT INTO proj.TBL_BOM_DETAILS
           (BomHeaderId, JobId, BomSectionId,
            ItemId, ItemDetailId, SortOrder,
            BomRequestedQty, BomReceivedQty, PrCreatedQty, PoCreatedQty,
            UomId, BomPrice, CurrencyId, ExchangeRate,
            ItemReqDate, ExpectedDelivery, BomStatus,
            IsCritical, IsSubstituteAllowed, Remarks,
            IsActive, CreatedBy, CreatedDate)
    SELECT  @NewBomHeaderId, @TargetJobId, BomSectionId,
            ItemId, ItemDetailId, SortOrder,
            BomRequestedQty, 0, 0, 0,
            UomId, BomPrice, CurrencyId, ExchangeRate,
            NULL, NULL, 'Pending',
            IsCritical, IsSubstituteAllowed, Remarks,
            1, @CreatedBy, GETDATE()
    FROM    proj.TBL_BOM_DETAILS
    WHERE   BomHeaderId = @SourceBomHeaderId
      AND   IsActive    = 1;

    -- ── 6. Recalculate TotalBomValue on new header ─────────────────
    UPDATE  proj.TBL_BOM_HEADER
    SET     TotalBomValue = (
                SELECT ISNULL(SUM(BomRequestedQty * BomPrice * ExchangeRate), 0)
                FROM   proj.TBL_BOM_DETAILS
                WHERE  BomHeaderId = @NewBomHeaderId
                  AND  IsActive    = 1
            )
    WHERE   BomHeaderId = @NewBomHeaderId;

    -- ── 7. Return new header ID ────────────────────────────────────
    SELECT @NewBomHeaderId AS NewBomHeaderId;
END
GO

IF OBJECT_ID(N'[proj].[sp_CopyInvoice]') IS NOT NULL DROP PROCEDURE [proj].[sp_CopyInvoice];
GO

CREATE   PROCEDURE proj.sp_CopyInvoice
    @SourceInvoiceId INT,
    @NewInvoiceDate  DATE,
    @NewDueDate      DATE         = NULL,
    @CreatedBy       NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- ── 1. Validate & read source ───────────────────────────────────
    DECLARE @CustomerId     INT,
            @BillingAddress NVARCHAR(1000),
            @CurrencyId     INT,
            @ExchangeRate   DECIMAL(18,6),
            @JobId          VARCHAR(30),
            @LpoNo          NVARCHAR(50),
            @LpoDate        DATE,
            @ContactId      INT,
            @Notes          NVARCHAR(1000);

    SELECT  @CustomerId     = CustomerId,
            @BillingAddress = BillingAddress,
            @CurrencyId     = CurrencyId,
            @ExchangeRate   = ExchangeRate,
            @JobId          = JobId,
            @LpoNo          = LpoNo,
            @LpoDate        = LpoDate,
            @ContactId      = ContactId,
            @Notes          = Notes
    FROM    proj.TBL_INVOICE
    WHERE   InvoiceId = @SourceInvoiceId
      AND   IsActive  = 1;

    IF @CustomerId IS NULL
        THROW 50001, 'Source invoice not found or is inactive.', 1;

    -- ── 2. Generate new invoice number ──────────────────────────────
    DECLARE @NumResult TABLE (DocNumber NVARCHAR(50), NewSeries INT);
    INSERT INTO @NumResult EXEC proj.sp_GetNextDocNumber 'INV';
    DECLARE @NewInvoiceNo NVARCHAR(50);
    SELECT  @NewInvoiceNo = DocNumber FROM @NumResult;

    -- ── 3. Insert new invoice header (all amounts = 0) ──────────────
    DECLARE @NewInvoiceId INT;

    INSERT INTO proj.TBL_INVOICE
           (InvoiceNo, InvoiceDate, CustomerId, BillingAddress,
            CurrencyId, ExchangeRate, DueDate,
            JobId, LpoNo, LpoDate, ContactId,
            SubTotal, TaxAmount, TotalAmount,
            Notes, Status, Revision, IsActive,
            CreatedBy, CreatedDate)
    VALUES (@NewInvoiceNo, @NewInvoiceDate, @CustomerId, @BillingAddress,
            @CurrencyId, @ExchangeRate, @NewDueDate,
            @JobId, @LpoNo, @LpoDate, @ContactId,
            0, 0, 0,
            @Notes, 'Draft', 0, 1,
            @CreatedBy, GETDATE());

    SET @NewInvoiceId = SCOPE_IDENTITY();

    -- ── 4. Copy lines (descriptions/UOM/Qty/VAT kept, amounts = 0) ─
    INSERT INTO proj.TBL_INVOICE_LINE
           (InvoiceId, LineNum, Description, UomName,
            UnitPrice, Qty, Amount, VatPercent, TaxAmount,
            Notes, IsActive, CreatedBy, CreatedDate)
    SELECT  @NewInvoiceId, LineNum, Description, UomName,
            0, Qty, 0, VatPercent, 0,
            Notes, 1, @CreatedBy, GETDATE()
    FROM    proj.TBL_INVOICE_LINE
    WHERE   InvoiceId = @SourceInvoiceId
      AND   IsActive  = 1
    ORDER BY LineNum;

    -- ── 5. Return new IDs ───────────────────────────────────────────
    SELECT @NewInvoiceId AS NewInvoiceId, @NewInvoiceNo AS NewInvoiceNo;
END
GO

IF OBJECT_ID(N'[proj].[sp_CreatePasswordResetToken]') IS NOT NULL DROP PROCEDURE [proj].[sp_CreatePasswordResetToken];
GO

CREATE PROCEDURE proj.sp_CreatePasswordResetToken
    @Email       NVARCHAR(200),
    @UserName    NVARCHAR(100),
    @TokenHash   NVARCHAR(255),
    @ExpiresAt   DATETIME,
    @RequestedIp NVARCHAR(50) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @UserId INT;
    SELECT @UserId = UserId
    FROM   proj.TBL_USERS
    WHERE  Email = @Email AND UserName = @UserName AND IsActive = 1 AND IsLocked = 0;

    -- No matching active user → return no rows (caller still responds generically)
    IF @UserId IS NULL RETURN;

    -- Invalidate any outstanding (unused) tokens for this user
    UPDATE proj.TBL_PASSWORD_RESET
    SET    IsUsed = 1, UsedDate = GETDATE()
    WHERE  UserId = @UserId AND IsUsed = 0;

    INSERT INTO proj.TBL_PASSWORD_RESET (UserId, TokenHash, ExpiresAt, RequestedIp, CreatedDate)
    VALUES (@UserId, @TokenHash, @ExpiresAt, @RequestedIp, GETDATE());

    SELECT u.UserId, u.UserName, u.FullName, u.Email
    FROM   proj.TBL_USERS u
    WHERE  u.UserId = @UserId;
END
GO

IF OBJECT_ID(N'[proj].[sp_DeleteAdjustment]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeleteAdjustment];
GO

CREATE   PROCEDURE proj.sp_DeleteAdjustment @AdjustmentId INT
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM proj.TBL_STOCK_ADJUSTMENT WHERE AdjustmentId=@AdjustmentId AND Status IN ('Posted','Approved'))
    BEGIN RAISERROR('Cannot delete an approved or posted adjustment.',16,1); RETURN; END
    UPDATE proj.TBL_STOCK_ADJUSTMENT SET IsActive=0, ModifiedDate=GETDATE() WHERE AdjustmentId=@AdjustmentId;
    SELECT 'Deleted' AS Result;
END;
GO

IF OBJECT_ID(N'[proj].[sp_DeleteAdjustmentLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeleteAdjustmentLine];
GO

CREATE   PROCEDURE proj.sp_DeleteAdjustmentLine @AdjustmentLineId INT
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @AdjId INT = (SELECT AdjustmentId FROM proj.TBL_STOCK_ADJUSTMENT_LINE WHERE AdjustmentLineId=@AdjustmentLineId);
    IF EXISTS (SELECT 1 FROM proj.TBL_STOCK_ADJUSTMENT WHERE AdjustmentId=@AdjId AND Status IN ('Posted','Approved'))
    BEGIN RAISERROR('Cannot delete a line from an approved or posted adjustment.',16,1); RETURN; END
    DELETE FROM proj.TBL_STOCK_ADJUSTMENT_LINE WHERE AdjustmentLineId=@AdjustmentLineId;
    SELECT 'Deleted' AS Result;
END;
GO

IF OBJECT_ID(N'[proj].[sp_DeleteApprovalDelegate]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeleteApprovalDelegate];
GO

CREATE   PROCEDURE proj.sp_DeleteApprovalDelegate
    @DelegateId INT,
    @DeletedBy  NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE proj.TBL_APPROVAL_DELEGATE
    SET IsActive     = 0,
        ModifiedBy   = @DeletedBy,
        ModifiedDate = GETDATE()
    WHERE DelegateId = @DelegateId;
    SELECT @@ROWCOUNT AS RowsAffected;
END;
GO

IF OBJECT_ID(N'[proj].[sp_DeleteBomDetail]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeleteBomDetail];
GO

-- 3. sp_DeleteBomDetail — also block on PoCreatedQty and BomReceivedQty
CREATE   PROCEDURE proj.sp_DeleteBomDetail
    @BomId      INT,
    @ModifiedBy NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @HeaderId        INT;
    DECLARE @PrCreatedQty    DECIMAL(18,4);
    DECLARE @PoCreatedQty    DECIMAL(18,4);
    DECLARE @BomReceivedQty  DECIMAL(18,4);

    SELECT @HeaderId       = BomHeaderId,
           @PrCreatedQty   = ISNULL(PrCreatedQty,   0),
           @PoCreatedQty   = ISNULL(PoCreatedQty,   0),
           @BomReceivedQty = ISNULL(BomReceivedQty, 0)
    FROM proj.TBL_BOM_DETAILS
    WHERE BomId = @BomId;

    IF @HeaderId IS NULL
    BEGIN
        RAISERROR('BOM line not found.', 16, 1);
        RETURN;
    END

    IF EXISTS (SELECT 1 FROM proj.TBL_BOM_HEADER WHERE BomHeaderId = @HeaderId AND BomStatus = 'Approved')
    BEGIN
        RAISERROR('Cannot delete lines on an Approved BOM.', 16, 1);
        RETURN;
    END

    IF @PrCreatedQty > 0
    BEGIN
        RAISERROR('Cannot delete this line — a Purchase Request has already been raised against it.', 16, 1);
        RETURN;
    END

    IF @PoCreatedQty > 0
    BEGIN
        RAISERROR('Cannot delete this line — a Purchase Order has already been raised against it.', 16, 1);
        RETURN;
    END

    IF @BomReceivedQty > 0
    BEGIN
        RAISERROR('Cannot delete this line — goods have already been received against it.', 16, 1);
        RETURN;
    END

    DELETE FROM proj.TBL_BOM_DETAILS WHERE BomId = @BomId;

    UPDATE proj.TBL_BOM_HEADER
    SET TotalBomValue = (
        SELECT ISNULL(SUM(BomRequestedQty * BomPrice * ExchangeRate), 0)
        FROM proj.TBL_BOM_DETAILS
        WHERE BomHeaderId = @HeaderId
    ),
    ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE()
    WHERE BomHeaderId = @HeaderId;

    SELECT 1 AS Success;
END
GO

IF OBJECT_ID(N'[proj].[sp_DeleteBomHeader]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeleteBomHeader];
GO

CREATE   PROCEDURE proj.sp_DeleteBomHeader
    @BomHeaderId INT,
    @ModifiedBy  NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    -- Must exist and be active
    IF NOT EXISTS (SELECT 1 FROM proj.TBL_BOM_HEADER WHERE BomHeaderId = @BomHeaderId AND IsActive = 1)
    BEGIN
        RAISERROR('BOM not found.', 16, 1);
        RETURN;
    END

    -- Only Draft BOMs can be deleted
    IF EXISTS (SELECT 1 FROM proj.TBL_BOM_HEADER WHERE BomHeaderId = @BomHeaderId AND BomStatus <> 'Draft')
    BEGIN
        RAISERROR('Only Draft BOMs can be deleted.', 16, 1);
        RETURN;
    END

    -- Block if any line already has PRs or POs raised against it
    IF EXISTS (
        SELECT 1 FROM proj.TBL_BOM_DETAILS
        WHERE BomHeaderId = @BomHeaderId
          AND IsActive     = 1
          AND (PrCreatedQty > 0 OR PoCreatedQty > 0 OR BomReceivedQty > 0)
    )
    BEGIN
        RAISERROR('This BOM cannot be deleted because Purchase Requests or Orders have already been raised against its items. Cancel or remove those transactions first.', 16, 1);
        RETURN;
    END

    -- Soft-delete header and all its lines
    UPDATE proj.TBL_BOM_DETAILS
    SET IsActive = 0, ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE()
    WHERE BomHeaderId = @BomHeaderId;

    UPDATE proj.TBL_BOM_HEADER
    SET IsActive = 0, ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE()
    WHERE BomHeaderId = @BomHeaderId;

    SELECT 1 AS Success;
END
GO

IF OBJECT_ID(N'[proj].[sp_DeleteCnAllocation]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeleteCnAllocation];
GO

CREATE   PROCEDURE proj.sp_DeleteCnAllocation
    @AllocationId INT,
    @ModifiedBy   NVARCHAR(100) = NULL,
    @Reason       NVARCHAR(500) = NULL,
    @PasswordHash NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CnId INT, @CnStatus NVARCHAR(20), @InvoiceId INT;
    SELECT @CnId      = a.CnId,
           @CnStatus  = cn.Status,
           @InvoiceId = a.InvoiceId
    FROM   proj.TBL_CREDIT_NOTE_ALLOCATION a
    JOIN   proj.TBL_CREDIT_NOTE cn ON cn.CnId = a.CnId
    WHERE  a.AllocationId = @AllocationId AND a.IsActive = 1;

    IF @CnId IS NULL
        BEGIN RAISERROR('Allocation not found.', 16, 1); RETURN; END
    IF @CnStatus <> 'Approved'
        BEGIN RAISERROR('Allocations can only be changed while the credit note is Approved.', 16, 1); RETURN; END

    IF NULLIF(LTRIM(RTRIM(ISNULL(@Reason, ''))), '') IS NULL
        BEGIN RAISERROR('A reason is required to remove an allocation from an approved credit note.', 16, 1); RETURN; END
    IF NULLIF(@PasswordHash, '') IS NULL
        BEGIN RAISERROR('Password is required.', 16, 1); RETURN; END

    IF NOT EXISTS (
        SELECT 1
        FROM   proj.TBL_USER_ROLES  ur
        JOIN   proj.TBL_ROLE_SECRET rs ON rs.RoleId  = ur.RoleId
        JOIN   proj.TBL_USERS       u  ON u.UserId   = ur.UserId
        WHERE  u.Username         = @ModifiedBy
          AND  rs.SecretKey       = 'RV_REVISE'
          AND  rs.SecretValueHash = @PasswordHash
    )
        BEGIN RAISERROR('Incorrect password. You do not have permission to remove this allocation.', 16, 1); RETURN; END

    UPDATE proj.TBL_CREDIT_NOTE_ALLOCATION
    SET    IsActive     = 0,
           Reason       = @Reason,
           ModifiedBy   = @ModifiedBy,
           ModifiedDate = GETDATE()
    WHERE  AllocationId = @AllocationId;

    DECLARE @ExchangeRate DECIMAL(18,6);
    SELECT @ExchangeRate = ISNULL(NULLIF(ExchangeRate, 0), 1)
    FROM   proj.TBL_CREDIT_NOTE WHERE CnId = @CnId;

    UPDATE proj.TBL_CREDIT_NOTE
    SET    AllocatedAmount = (
               SELECT ISNULL(SUM(AllocatedAmount), 0) / @ExchangeRate
               FROM   proj.TBL_CREDIT_NOTE_ALLOCATION
               WHERE  CnId = @CnId AND IsActive = 1
           ),
           ModifiedDate = GETDATE()
    WHERE  CnId = @CnId;

    -- Refresh the job credit total after removing the allocation.
    DECLARE @JobId NVARCHAR(50) = (SELECT JobId FROM proj.TBL_INVOICE WHERE InvoiceId = @InvoiceId);
    IF NULLIF(@JobId, '') IS NOT NULL
        EXEC proj.sp_RecalcJobCredits @JobId, @ModifiedBy;

    SELECT 'OK' AS Result;
END
GO

