-- 4. sp_DeleteDeliveryLine — add parent status guard (was completely unguarded)
CREATE   PROCEDURE proj.sp_DeleteDeliveryLine
    @DeliveryLineId INT,
    @ActionBy       NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @DeliveryId INT;
    SELECT @DeliveryId = DeliveryId
    FROM proj.TBL_DELIVERY_LINE
    WHERE DeliveryLineId = @DeliveryLineId AND IsActive = 1;

    IF @DeliveryId IS NULL
    BEGIN
        RAISERROR('Delivery line not found or already deleted.', 16, 1); RETURN;
    END

    DECLARE @DeliveryStatus NVARCHAR(30);
    SELECT @DeliveryStatus = Status
    FROM proj.TBL_DELIVERY
    WHERE DeliveryId = @DeliveryId AND IsActive = 1;

    IF @DeliveryStatus IS NULL
    BEGIN
        RAISERROR('Delivery not found or is inactive.', 16, 1); RETURN;
    END

    IF @DeliveryStatus <> 'Draft'
    BEGIN
        DECLARE @Msg NVARCHAR(200) = 'Delivery lines can only be deleted when the Delivery is in Draft status. Current status: ' + @DeliveryStatus;
        RAISERROR(@Msg, 16, 1); RETURN;
    END

    UPDATE proj.TBL_DELIVERY_LINE
    SET IsActive = 0, ModifiedBy = @ActionBy, ModifiedDate = GETDATE()
    WHERE DeliveryLineId = @DeliveryLineId;

    SELECT 'OK';
END
GO

IF OBJECT_ID(N'[proj].[sp_DeleteDnAllocation]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeleteDnAllocation];
GO

CREATE PROCEDURE proj.sp_DeleteDnAllocation
    @AllocationId INT,
    @ModifiedBy   NVARCHAR(100) = NULL,
    @Reason       NVARCHAR(500) = NULL,
    @PasswordHash NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @DnId INT, @DnStatus NVARCHAR(20), @SupplierInvoiceId INT;
    SELECT @DnId              = a.DnId,
           @DnStatus          = dn.Status,
           @SupplierInvoiceId = a.SupplierInvoiceId
    FROM   proj.TBL_DEBIT_NOTE_ALLOCATION a
    JOIN   proj.TBL_DEBIT_NOTE dn ON dn.DnId = a.DnId
    WHERE  a.AllocationId = @AllocationId AND a.IsActive = 1;

    IF @DnId IS NULL
        BEGIN RAISERROR('Allocation not found.', 16, 1); RETURN; END
    IF @DnStatus <> 'Approved'
        BEGIN RAISERROR('Allocations can only be changed while the debit note is Approved.', 16, 1); RETURN; END

    IF NULLIF(LTRIM(RTRIM(ISNULL(@Reason, ''))), '') IS NULL
        BEGIN RAISERROR('A reason is required to remove an allocation from an approved debit note.', 16, 1); RETURN; END
    IF NULLIF(@PasswordHash, '') IS NULL
        BEGIN RAISERROR('Password is required.', 16, 1); RETURN; END

    IF NOT EXISTS (
        SELECT 1
        FROM   proj.TBL_USER_ROLES  ur
        JOIN   proj.TBL_ROLE_SECRET rs ON rs.RoleId  = ur.RoleId
        JOIN   proj.TBL_USERS       u  ON u.UserId   = ur.UserId
        WHERE  u.Username         = @ModifiedBy
          AND  rs.SecretKey       = 'PV_REVISE'
          AND  rs.SecretValueHash = @PasswordHash
    )
        BEGIN RAISERROR('Incorrect password. You do not have permission to remove this allocation.', 16, 1); RETURN; END

    UPDATE proj.TBL_DEBIT_NOTE_ALLOCATION
    SET    IsActive     = 0,
           Reason       = @Reason,
           ModifiedBy   = @ModifiedBy,
           ModifiedDate = GETDATE()
    WHERE  AllocationId = @AllocationId;

    DECLARE @ExchangeRate DECIMAL(18,6);
    SELECT @ExchangeRate = ISNULL(NULLIF(ExchangeRate, 0), 1)
    FROM   proj.TBL_DEBIT_NOTE WHERE DnId = @DnId;

    UPDATE proj.TBL_DEBIT_NOTE
    SET    AllocatedAmount = (
               SELECT ISNULL(SUM(AllocatedAmount), 0) / @ExchangeRate
               FROM   proj.TBL_DEBIT_NOTE_ALLOCATION
               WHERE  DnId = @DnId AND IsActive = 1
           ),
           ModifiedDate = GETDATE()
    WHERE  DnId = @DnId;

    SELECT 'OK' AS Result;
END
GO

