CREATE PROCEDURE proj.sp_DeleteGRNLine
    @GrnDetailId INT
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM proj.TBL_GRN_DETAIL WHERE GrnDetailId = @GrnDetailId AND IsActive = 1)
    BEGIN SELECT N'NotExists'; RETURN; END

    -- Guard: parent GRN must be in Draft status
    DECLARE @GrnId INT, @GrnStatus NVARCHAR(30);
    SELECT @GrnId = GrnId FROM proj.TBL_GRN_DETAIL WHERE GrnDetailId = @GrnDetailId;
    SELECT @GrnStatus = Status FROM proj.TBL_GRN_HEADER WHERE GrnId = @GrnId AND IsActive = 1;

    IF @GrnStatus IS NULL
    BEGIN
        RAISERROR('GRN not found or is inactive.', 16, 1); RETURN;
    END
    IF @GrnStatus <> 'Draft'
    BEGIN
        RAISERROR('GRN lines can only be deleted when the GRN is in Draft status. Current status: %s', 16, 1, @GrnStatus); RETURN;
    END

    UPDATE proj.TBL_GRN_DETAIL SET IsActive = 0 WHERE GrnDetailId = @GrnDetailId;
    SELECT N'OK';
END
GO

IF OBJECT_ID(N'[proj].[sp_DeleteInactiveRoles]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeleteInactiveRoles];
GO

CREATE   PROCEDURE proj.sp_DeleteInactiveRoles
AS
BEGIN
    SET NOCOUNT ON;

    -- Capture inactive role IDs
    DECLARE @InactiveRoles TABLE (RoleId INT);
    INSERT INTO @InactiveRoles (RoleId)
    SELECT RoleId FROM proj.TBL_ROLES WHERE IsActive = 0 OR IsActive IS NULL;

    IF NOT EXISTS (SELECT 1 FROM @InactiveRoles)
    BEGIN
        SELECT 0 AS DeletedRoles, 0 AS DeletedUserRoles, 0 AS DeletedRoleSecrets;
        RETURN;
    END

    DECLARE @DelUserRoles  INT = 0;
    DECLARE @DelSecrets    INT = 0;
    DECLARE @DelRoles      INT = 0;

    -- 1. TBL_USER_ROLES
    DELETE ur
    FROM proj.TBL_USER_ROLES ur
    JOIN @InactiveRoles ir ON ir.RoleId = ur.RoleId;
    SET @DelUserRoles = @@ROWCOUNT;

    -- 2. TBL_ROLE_SECRET
    DELETE rs
    FROM proj.TBL_ROLE_SECRET rs
    JOIN @InactiveRoles ir ON ir.RoleId = rs.RoleId;
    SET @DelSecrets = @@ROWCOUNT;

    -- 3. TBL_ROLES (parent — last)
    DELETE r
    FROM proj.TBL_ROLES r
    JOIN @InactiveRoles ir ON ir.RoleId = r.RoleId;
    SET @DelRoles = @@ROWCOUNT;

    SELECT @DelRoles AS DeletedRoles, @DelUserRoles AS DeletedUserRoles, @DelSecrets AS DeletedRoleSecrets;
END;
GO

