CREATE   PROCEDURE PROJ.sp_DeleteInvoice
    @InvoiceId  INT,
    @ModifiedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM PROJ.TBL_INVOICE WHERE InvoiceId = @InvoiceId AND IsActive = 1)
    BEGIN SELECT 'NotExists' AS Result; RETURN; END
    IF NOT EXISTS (SELECT 1 FROM PROJ.TBL_INVOICE WHERE InvoiceId = @InvoiceId AND Status = 'Draft')
    BEGIN SELECT 'CannotDelete' AS Result; RETURN; END

    UPDATE PROJ.TBL_INVOICE_LINE
    SET IsActive = 0, ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE()
    WHERE InvoiceId = @InvoiceId AND IsActive = 1;

    UPDATE PROJ.TBL_INVOICE
    SET IsActive = 0, ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE()
    WHERE InvoiceId = @InvoiceId;

    SELECT 'Deleted' AS Result;
END;
GO

IF OBJECT_ID(N'[proj].[sp_DeleteInvoiceLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeleteInvoiceLine];
GO

CREATE   PROCEDURE PROJ.sp_DeleteInvoiceLine
    @InvoiceLineId  INT,
    @ModifiedBy     NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @InvoiceId INT;
    SELECT @InvoiceId = InvoiceId FROM PROJ.TBL_INVOICE_LINE WHERE InvoiceLineId = @InvoiceLineId AND IsActive = 1;
    IF @InvoiceId IS NULL RAISERROR('Invoice line not found.', 16, 1);
    IF EXISTS (SELECT 1 FROM PROJ.TBL_INVOICE WHERE InvoiceId = @InvoiceId AND Status <> 'Draft')
        RAISERROR('Cannot delete lines of a non-Draft Invoice.', 16, 1);

    UPDATE PROJ.TBL_INVOICE_LINE
    SET IsActive = 0, ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE()
    WHERE InvoiceLineId = @InvoiceLineId;

    DECLARE @Sub DECIMAL(18,2) = (SELECT ISNULL(SUM(Amount),    0) FROM PROJ.TBL_INVOICE_LINE WHERE InvoiceId = @InvoiceId AND IsActive = 1);
    DECLARE @Tax DECIMAL(18,2) = (SELECT ISNULL(SUM(TaxAmount), 0) FROM PROJ.TBL_INVOICE_LINE WHERE InvoiceId = @InvoiceId AND IsActive = 1);
    UPDATE PROJ.TBL_INVOICE
    SET SubTotal = @Sub, TaxAmount = @Tax, TotalAmount = @Sub + @Tax,
        ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE()
    WHERE InvoiceId = @InvoiceId;
END;
GO

