    DELETE isu FROM proj.TBL_ITEM_SUPPLIER isu JOIN proj.TBL_ITEM_DETAIL d ON d.ItemDetailId=isu.ItemDetailId WHERE d.ItemId=@ItemId;
    DELETE FROM proj.TBL_ITEM_DETAIL WHERE ItemId=@ItemId;
    DELETE FROM proj.TBL_ITEM WHERE ItemId=@ItemId;
    SELECT 'Deleted';
END;
