CREATE   PROCEDURE proj.sp_DeleteJobBudget
    @JobBudgetId INT
AS
BEGIN
    SET NOCOUNT ON;

    -- Guard: refuse to delete a row from an already-approved revision
    IF EXISTS (
        SELECT 1 FROM proj.TBL_JOB_BUDGET
        WHERE JobBudgetId = @JobBudgetId AND IsApproved = 1
    )
    BEGIN
        RAISERROR('Cannot delete a line from an approved budget revision. Revise it first.', 16, 1);
