CREATE PROCEDURE proj.sp_DeleteJobExpense
    @ExpenseId INT,
    @JobId     NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE proj.TBL_JOB_EXPENSE
    SET IsDeleted    = 1,
        ModifiedDate = GETDATE()
    WHERE ExpenseId = @ExpenseId AND JobId = @JobId;

    -- Keep TotalExpenses in sync (exclude soft-deleted rows)
    UPDATE proj.TBL_JOB_FINANCE
