IF OBJECT_ID(N'[proj].[sp_DeleteManhour]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeleteManhour];
GO

-- 6. sp_DeleteManhour — block deletion of non-Draft batches (was soft-deleting them silently)
CREATE   PROCEDURE proj.sp_DeleteManhour
    @BatchId    INT,
    @DeletedBy  NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Status NVARCHAR(20);
    SELECT TOP 1 @Status = Status
    FROM proj.TBL_MANHOUR
    WHERE BatchId = @BatchId AND IsActive = 1;

    IF @Status IS NULL
    BEGIN
        RAISERROR('Batch not found.', 16, 1);
        RETURN;
    END

    IF @Status <> 'Draft'
    BEGIN
        DECLARE @Msg NVARCHAR(200) = 'Cannot delete a manhour batch that has been submitted or approved. Current status: ' + @Status;
        RAISERROR(@Msg, 16, 1);
        RETURN;
    END

    DELETE FROM proj.TBL_MANHOUR WHERE BatchId = @BatchId;

    SELECT 'Deleted' AS Result;
END;
GO

IF OBJECT_ID(N'[proj].[sp_DeleteManhourLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeleteManhourLine];
GO
CREATE PROCEDURE proj.sp_DeleteManhourLine
    @ManhourId  INT,
    @DeletedBy  NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    -- Verify the line exists and get its batch status
    DECLARE @BatchStatus NVARCHAR(50);

    SELECT @BatchStatus = m2.Status
    FROM   proj.TBL_MANHOUR m1
    JOIN   proj.TBL_MANHOUR m2
           ON m2.BatchId = m1.BatchId AND m2.ManhourId = m1.ManhourId
    WHERE  m1.ManhourId = @ManhourId AND m1.IsActive = 1;

    -- Simpler: just read Status directly from the row
    SELECT @BatchStatus = Status
    FROM   proj.TBL_MANHOUR
    WHERE  ManhourId = @ManhourId AND IsActive = 1;

    IF @BatchStatus IS NULL
    BEGIN
        SELECT -1 AS Result, 'Line not found or already deleted.' AS Message;
        RETURN;
    END

    IF @BatchStatus = 'Approved'
    BEGIN
        SELECT -1 AS Result, 'Cannot delete lines from an approved batch.' AS Message;
        RETURN;
    END

    -- Soft-delete the line
    UPDATE proj.TBL_MANHOUR
    SET    IsActive     = 0,
           ModifiedBy   = @DeletedBy,
           ModifiedDate = GETDATE()
    WHERE  ManhourId = @ManhourId;

    SELECT 1 AS Result, 'Line deleted successfully.' AS Message;
END;
GO

