IF OBJECT_ID(N'[proj].[sp_DeletePO]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeletePO];
GO

-- 2. sp_DeletePO — block if any line already has goods received
CREATE   PROCEDURE PROJ.sp_DeletePO
    @PoId INT
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM PROJ.TBL_PURCHASE_ORDER WHERE PoId = @PoId AND IsActive = 1)
    BEGIN SELECT N'NotExists'; RETURN; END

    IF EXISTS (SELECT 1 FROM PROJ.TBL_PURCHASE_ORDER WHERE PoId = @PoId AND Status NOT IN (N'Draft'))
    BEGIN SELECT N'CannotDelete'; RETURN; END

    -- Block if any line has goods already received (GRN done)
    IF EXISTS (
        SELECT 1 FROM PROJ.TBL_PURCHASE_ORDER_LINE
        WHERE PoId = @PoId AND IsActive = 1 AND ISNULL(ReceivedQty, 0) > 0
    )
    BEGIN
        RAISERROR('Cannot delete this PO — goods have already been received against one or more lines.', 16, 1);
        RETURN;
    END

    UPDATE PROJ.TBL_PURCHASE_ORDER      SET IsActive = 0 WHERE PoId = @PoId;
    UPDATE PROJ.TBL_PURCHASE_ORDER_LINE SET IsActive = 0 WHERE PoId = @PoId;
    SELECT N'OK';
END
GO

IF OBJECT_ID(N'[proj].[sp_DeletePOAnnexure]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeletePOAnnexure];
GO
CREATE   PROCEDURE proj.sp_DeletePOAnnexure
    @AnnexureId  INT,
    @ModifiedBy  NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @PoStatus NVARCHAR(30);
    SELECT @PoStatus = po.Status FROM proj.TBL_PURCHASE_ORDER po
    JOIN proj.TBL_PURCHASE_ORDER_ANNEXURE a ON a.PoId = po.PoId
    WHERE a.AnnexureId = @AnnexureId AND po.IsActive = 1;
    IF @PoStatus NOT IN ('Draft','Rejected') THROW 60130, 'Annexures can only be deleted while the PO is in Draft.', 1;

    UPDATE proj.TBL_PURCHASE_ORDER_ANNEXURE SET IsActive=0, ModifiedBy=@ModifiedBy, ModifiedDate=GETDATE() WHERE AnnexureId=@AnnexureId;
    UPDATE proj.TBL_PURCHASE_ORDER_ANNEXURE_DETAIL SET IsActive=0, ModifiedBy=@ModifiedBy, ModifiedDate=GETDATE() WHERE AnnexureId=@AnnexureId AND IsActive=1;
    DELETE FROM proj.TBL_PURCHASE_ORDER_ANNEXURE_LINE_LINK WHERE AnnexureId=@AnnexureId;
END;
GO

IF OBJECT_ID(N'[proj].[sp_DeletePOAnnexureDetail]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeletePOAnnexureDetail];
GO
CREATE   PROCEDURE proj.sp_DeletePOAnnexureDetail
    @AnnexureDetailId INT,
    @ModifiedBy       NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @PoStatus NVARCHAR(30);
    SELECT @PoStatus = po.Status
    FROM proj.TBL_PURCHASE_ORDER po
    JOIN proj.TBL_PURCHASE_ORDER_ANNEXURE a ON a.PoId = po.PoId
    JOIN proj.TBL_PURCHASE_ORDER_ANNEXURE_DETAIL d ON d.AnnexureId = a.AnnexureId
    WHERE d.AnnexureDetailId = @AnnexureDetailId AND po.IsActive = 1 AND a.IsActive = 1;
    IF @PoStatus NOT IN ('Draft','Rejected') THROW 60120, 'Annexures can only be edited while the PO is in Draft.', 1;

    UPDATE proj.TBL_PURCHASE_ORDER_ANNEXURE_DETAIL
    SET IsActive = 0, ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE()
    WHERE AnnexureDetailId = @AnnexureDetailId;
END;
GO

IF OBJECT_ID(N'[proj].[sp_DeletePOLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeletePOLine];
GO

CREATE PROCEDURE PROJ.sp_DeletePOLine
    @PoLineId INT
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM PROJ.TBL_PURCHASE_ORDER_LINE WHERE PoLineId = @PoLineId)
    BEGIN SELECT 'NotExists' AS Result; RETURN; END

    DECLARE @PoId        INT;
    DECLARE @PrLineId    INT           = NULL;
    DECLARE @OrderedQty  DECIMAL(18,4) = 0;
    DECLARE @ReceivedQty DECIMAL(18,4) = 0;

    SELECT @PoId = PoId, @PrLineId = PrLineId,
           @OrderedQty = OrderedQty, @ReceivedQty = ISNULL(ReceivedQty, 0)
    FROM PROJ.TBL_PURCHASE_ORDER_LINE WHERE PoLineId = @PoLineId;

    DECLARE @PoStatus NVARCHAR(30);
    SELECT @PoStatus = Status FROM PROJ.TBL_PURCHASE_ORDER WHERE PoId = @PoId AND IsActive = 1;
    IF @PoStatus IS NULL BEGIN RAISERROR('Purchase Order not found or is inactive.', 16, 1); RETURN; END
    IF @PoStatus <> 'Draft'
    BEGIN
        DECLARE @PoMsg NVARCHAR(200) = 'PO lines can only be deleted when the Purchase Order is in Draft status. Current status: ' + @PoStatus;
        RAISERROR(@PoMsg, 16, 1); RETURN;
    END

    -- Guard against Draft + confirmed GRN lines (pol.ReceivedQty only reflects
    -- confirmed GRNs; a Draft GRN may already carry received qty for this line)
    DECLARE @TotalGrnQty DECIMAL(18,4);
    SELECT @TotalGrnQty = ISNULL(SUM(d.ReceivedQty), 0)
    FROM   proj.TBL_GRN_DETAIL d
    JOIN   proj.TBL_GRN_HEADER h ON h.GrnId = d.GrnId AND h.IsActive = 1
    WHERE  d.PoLineId = @PoLineId
      AND  d.IsActive = 1
      AND  h.Status  <> 'Cancelled';

    IF @TotalGrnQty > 0
    BEGIN
        DECLARE @RcvMsg NVARCHAR(300) =
            'Cannot delete this line — goods have already been recorded against it in a GRN (qty: '
            + CAST(@TotalGrnQty AS NVARCHAR(30)) + '), including drafts.';
        RAISERROR(@RcvMsg, 16, 1); RETURN;
    END

    DECLARE @BomDetailId INT = NULL;
    IF @PrLineId IS NOT NULL AND @PrLineId > 0
        SELECT @BomDetailId = BomDetailId FROM PROJ.TBL_PURCHASE_REQUEST_LINE WHERE PrLineId = @PrLineId;

    DELETE FROM PROJ.TBL_PURCHASE_ORDER_LINE WHERE PoLineId = @PoLineId;

    IF @PrLineId IS NOT NULL AND @PrLineId > 0
    BEGIN
        UPDATE PROJ.TBL_PURCHASE_REQUEST_LINE
        SET PoCreatedQty = ISNULL(PoCreatedQty, 0) - @OrderedQty
        WHERE PrLineId = @PrLineId;

        EXEC PROJ.sp_RecalcPrStatus @PrLineId, 'SYSTEM';

        IF @BomDetailId IS NOT NULL
        BEGIN
            UPDATE PROJ.TBL_BOM_DETAILS
            SET PoCreatedQty = ISNULL(PoCreatedQty, 0) - @OrderedQty,
                BomStatus    = CASE
                    WHEN BomReceivedQty >= BomRequestedQty                           THEN 'FullyReceived'
                    WHEN BomReceivedQty  > 0                                         THEN 'PartialReceived'
                    WHEN (ISNULL(PoCreatedQty,0)-@OrderedQty) >= BomRequestedQty     THEN 'PORaised'
                    WHEN (ISNULL(PoCreatedQty,0)-@OrderedQty)  > 0                   THEN 'POPartial'
                    WHEN PrCreatedQty >= BomRequestedQty                             THEN 'PRRaised'
                    WHEN PrCreatedQty  > 0                                           THEN 'PRPartial'
                    ELSE 'Pending' END
            WHERE BomId = @BomDetailId AND ISNULL(PoCreatedQty,0) >= @OrderedQty;
        END
    END

    UPDATE PROJ.TBL_PURCHASE_ORDER
    SET TotalAmount = (SELECT ISNULL(SUM(OrderedQty*UnitPrice),0) FROM PROJ.TBL_PURCHASE_ORDER_LINE WHERE PoId=@PoId)
    WHERE PoId = @PoId;

    SELECT 'OK' AS Result;
END
GO

IF OBJECT_ID(N'[proj].[sp_DeletePR]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeletePR];
GO

-- 1. sp_DeletePR — block if any line already has a PO raised
CREATE   PROCEDURE PROJ.sp_DeletePR
    @PrId INT
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM PROJ.TBL_PURCHASE_REQUEST WHERE PrId = @PrId AND IsActive = 1)
    BEGIN SELECT N'NotExists'; RETURN; END

    IF EXISTS (SELECT 1 FROM PROJ.TBL_PURCHASE_REQUEST WHERE PrId = @PrId AND Status <> N'Draft')
    BEGIN SELECT N'CannotDelete'; RETURN; END

    -- Block if any line has been converted to a PO
    IF EXISTS (
        SELECT 1 FROM PROJ.TBL_PURCHASE_REQUEST_LINE
        WHERE PrId = @PrId AND IsActive = 1 AND ISNULL(PoCreatedQty, 0) > 0
    )
    BEGIN
        RAISERROR('Cannot delete this PR — one or more lines have already been converted to a Purchase Order.', 16, 1);
        RETURN;
    END

    UPDATE PROJ.TBL_PURCHASE_REQUEST      SET IsActive = 0 WHERE PrId = @PrId;
    UPDATE PROJ.TBL_PURCHASE_REQUEST_LINE SET IsActive = 0 WHERE PrId = @PrId;
    SELECT N'OK';
END
GO

IF OBJECT_ID(N'[proj].[sp_DeletePRLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeletePRLine];
GO

CREATE PROCEDURE proj.sp_DeletePRLine
    @PrLineId  INT,
    @DeletedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @PrId        INT;
    DECLARE @BomDetailId INT           = NULL;
    DECLARE @RequiredQty DECIMAL(18,4) = 0;

    SELECT @PrId        = PrId,
           @BomDetailId = BomDetailId,
           @RequiredQty = RequiredQty
    FROM proj.TBL_PURCHASE_REQUEST_LINE
    WHERE PrLineId = @PrLineId;

    IF @PrId IS NULL
    BEGIN
        RAISERROR('PR line not found.', 16, 1); RETURN;
    END

    -- Guard: parent PR must be in Draft status
    DECLARE @PrStatus NVARCHAR(30);
    SELECT @PrStatus = Status FROM proj.TBL_PURCHASE_REQUEST WHERE PrId = @PrId AND IsActive = 1;

    IF @PrStatus IS NULL
    BEGIN
        RAISERROR('Purchase Request not found or is inactive.', 16, 1); RETURN;
    END
    IF @PrStatus NOT IN ('Draft')
    BEGIN
        RAISERROR('PR lines can only be deleted when the Purchase Request is in Draft status. Current status: %s', 16, 1, @PrStatus); RETURN;
    END

    -- Guard: cannot delete a line that has already been converted to a PO
    DECLARE @PoCreatedQty DECIMAL(18,4) = 0;
    SELECT @PoCreatedQty = ISNULL(PoCreatedQty, 0)
    FROM proj.TBL_PURCHASE_REQUEST_LINE WHERE PrLineId = @PrLineId;

    IF @PoCreatedQty > 0
    BEGIN
        RAISERROR('Cannot delete this line — a Purchase Order has already been raised against it.', 16, 1); RETURN;
    END

    DELETE FROM proj.TBL_PURCHASE_REQUEST_LINE WHERE PrLineId = @PrLineId;

    IF @BomDetailId IS NOT NULL AND @BomDetailId > 0
    BEGIN
        UPDATE proj.TBL_BOM_DETAILS
        SET PrCreatedQty = ISNULL(PrCreatedQty, 0) - @RequiredQty,
            BomStatus    = CASE
                WHEN BomReceivedQty >= BomRequestedQty                                    THEN 'FullyReceived'
                WHEN BomReceivedQty  > 0                                                  THEN 'PartialReceived'
                WHEN PoCreatedQty   >= BomRequestedQty                                    THEN 'PORaised'
                WHEN PoCreatedQty    > 0                                                  THEN 'POPartial'
                WHEN (ISNULL(PrCreatedQty, 0) - @RequiredQty) >= BomRequestedQty         THEN 'PRRaised'
                WHEN (ISNULL(PrCreatedQty, 0) - @RequiredQty)  > 0                       THEN 'PRPartial'
                ELSE                                                                           'Pending'
            END
        WHERE BomId = @BomDetailId
          AND ISNULL(PrCreatedQty, 0) >= @RequiredQty;
    END

    SELECT N'OK';
END
GO

IF OBJECT_ID(N'[proj].[sp_DeletePvAllocation]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeletePvAllocation];
GO

-- ── sp_DeletePvAllocation ─────────────────────────────────────────────────────
CREATE PROCEDURE proj.sp_DeletePvAllocation
    @AllocationId INT,
    @ModifiedBy   NVARCHAR(100) = NULL,
    @Reason       NVARCHAR(500) = NULL,
    @PasswordHash NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @PvId INT, @PvStatus NVARCHAR(20);
    SELECT @PvId     = a.PvId,
           @PvStatus = pv.Status
    FROM   proj.TBL_PAYMENT_VOUCHER_ALLOCATION a
    JOIN   proj.TBL_PAYMENT_VOUCHER pv ON pv.PvId = a.PvId
    WHERE  a.AllocationId = @AllocationId AND a.IsActive = 1;

    IF @PvId IS NULL
        BEGIN RAISERROR('Allocation not found.',16,1); RETURN; END
    IF @PvStatus <> 'Approved'
        BEGIN RAISERROR('Allocations can only be changed while the payment voucher is Approved.',16,1); RETURN; END
    IF NULLIF(LTRIM(RTRIM(ISNULL(@Reason,''))),   '') IS NULL
        BEGIN RAISERROR('A reason is required to remove an allocation from an approved payment voucher.',16,1); RETURN; END
    IF NULLIF(@PasswordHash,'') IS NULL
        BEGIN RAISERROR('Password is required.',16,1); RETURN; END

    IF NOT EXISTS (
        SELECT 1
        FROM   proj.TBL_USER_ROLES  ur
        JOIN   proj.TBL_ROLE_SECRET rs ON rs.RoleId  = ur.RoleId
        JOIN   proj.TBL_USERS       u  ON u.UserId   = ur.UserId
        WHERE  u.Username = @ModifiedBy AND rs.SecretKey = 'PV_REVISE' AND rs.SecretValueHash = @PasswordHash
    )
        BEGIN RAISERROR('Incorrect password. You do not have permission to remove this allocation.',16,1); RETURN; END

    UPDATE proj.TBL_PAYMENT_VOUCHER_ALLOCATION
    SET    IsActive = 0, Reason = @Reason, ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE()
    WHERE  AllocationId = @AllocationId;

    DECLARE @ExchangeRate DECIMAL(18,6);
    SELECT @ExchangeRate = ISNULL(NULLIF(ExchangeRate,0),1)
    FROM   proj.TBL_PAYMENT_VOUCHER WHERE PvId = @PvId;

    UPDATE proj.TBL_PAYMENT_VOUCHER
    SET    AllocatedAmount = (
               SELECT ISNULL(SUM(AllocatedAmount),0) / @ExchangeRate
               FROM   proj.TBL_PAYMENT_VOUCHER_ALLOCATION
               WHERE  PvId = @PvId AND IsActive = 1
           ),
           ModifiedDate = GETDATE()
    WHERE  PvId = @PvId;

    SELECT 'OK' AS Result;
END
GO

IF OBJECT_ID(N'[proj].[sp_DeleteReceiptVoucher]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeleteReceiptVoucher];
GO

CREATE   PROCEDURE proj.sp_DeleteReceiptVoucher
    @RvId       INT,
    @ModifiedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM proj.TBL_RECEIPT_VOUCHER WHERE RvId=@RvId AND IsActive=1)
    BEGIN SELECT 'NotExists' AS Result; RETURN; END
    IF EXISTS (SELECT 1 FROM proj.TBL_RECEIPT_VOUCHER WHERE RvId=@RvId AND Status<>'Draft')
    BEGIN SELECT 'CannotDelete' AS Result; RETURN; END

    UPDATE proj.TBL_RECEIPT_VOUCHER_ALLOCATION SET IsActive=0, ModifiedBy=@ModifiedBy, ModifiedDate=GETDATE() WHERE RvId=@RvId;
    UPDATE proj.TBL_RECEIPT_VOUCHER            SET IsActive=0, ModifiedBy=@ModifiedBy, ModifiedDate=GETDATE() WHERE RvId=@RvId;
    SELECT 'OK' AS Result;
END
GO

IF OBJECT_ID(N'[proj].[sp_DeleteRole]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeleteRole];
GO

CREATE   PROCEDURE proj.sp_DeleteRole
    @RoleId     INT,
    @ModifiedBy NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM proj.TBL_ROLES WHERE RoleId = @RoleId)
    BEGIN
        SELECT 0 AS Success, N'Role not found.' AS ErrorMessage; RETURN;
    END
    IF EXISTS (SELECT 1 FROM proj.TBL_USER_ROLES WHERE RoleId = @RoleId)
    BEGIN
        SELECT 0 AS Success, N'Cannot delete: role is assigned to one or more users.' AS ErrorMessage; RETURN;
    END
    UPDATE proj.TBL_ROLES SET
        IsActive     = 0,
        ModifiedBy   = @ModifiedBy,
        ModifiedDate = GETDATE()
    WHERE RoleId = @RoleId;
    SELECT 1 AS Success, NULL AS ErrorMessage;
END
GO

IF OBJECT_ID(N'[proj].[sp_DeleteRTV]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeleteRTV];
GO
CREATE PROCEDURE proj.sp_DeleteRTV
    @RtvId INT
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Status NVARCHAR(30);

    SELECT @Status = Status FROM proj.TBL_RETURN_TO_VENDOR
    WHERE RtvId = @RtvId AND IsActive = 1;

    IF @Status IS NULL  RAISERROR('RTV not found.', 16, 1);
    IF @Status <> 'Draft' RAISERROR('Only Draft RTVs can be deleted.', 16, 1);

    -- SP-8: Soft-delete lines and header (preserves audit trail)
    UPDATE proj.TBL_RETURN_TO_VENDOR_LINE
    SET IsActive = 0, ModifiedDate = GETDATE()
    WHERE RtvId = @RtvId AND IsActive = 1;

    UPDATE proj.TBL_RETURN_TO_VENDOR
    SET IsActive = 0, ModifiedDate = GETDATE()
    WHERE RtvId = @RtvId;

    SELECT 'OK';
END;
GO

IF OBJECT_ID(N'[proj].[sp_DeleteRTVLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeleteRTVLine];
GO
CREATE PROCEDURE proj.sp_DeleteRTVLine
    @RtvLineId INT
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @RtvId INT;

    -- SP-7a: include IsActive=1 in the line lookup
    SELECT @RtvId = RtvId FROM proj.TBL_RETURN_TO_VENDOR_LINE
    WHERE RtvLineId = @RtvLineId AND IsActive = 1;

    IF @RtvId IS NULL
        RAISERROR('Return line not found.', 16, 1);

    -- Guard: RTV must be Draft and active
    IF NOT EXISTS (SELECT 1 FROM proj.TBL_RETURN_TO_VENDOR WHERE RtvId = @RtvId AND Status = 'Draft' AND IsActive = 1)
        RAISERROR('Lines can only be deleted on a Draft RTV.', 16, 1);

    -- SP-7b: Soft-delete (preserve audit trail)
    UPDATE proj.TBL_RETURN_TO_VENDOR_LINE
    SET IsActive = 0, ModifiedDate = GETDATE()
    WHERE RtvLineId = @RtvLineId;

    -- Recompute header total (only active lines)
    UPDATE proj.TBL_RETURN_TO_VENDOR
    SET TotalAmount  = (SELECT ISNULL(SUM(LineTotal),0) FROM proj.TBL_RETURN_TO_VENDOR_LINE WHERE RtvId = @RtvId AND IsActive = 1),
        ModifiedDate = GETDATE()
    WHERE RtvId = @RtvId;

    SELECT 'OK';
END;
GO

IF OBJECT_ID(N'[proj].[sp_DeleteRvAllocation]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeleteRvAllocation];
GO

CREATE PROCEDURE proj.sp_DeleteRvAllocation
    @AllocationId INT,
    @ModifiedBy   NVARCHAR(100) = NULL,
    @Reason       NVARCHAR(500) = NULL,
    @PasswordHash NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @RvId INT, @RvStatus NVARCHAR(20), @InvoiceId INT;
    SELECT @RvId      = a.RvId,
           @RvStatus  = rv.Status,
           @InvoiceId = a.InvoiceId
    FROM   proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
    JOIN   proj.TBL_RECEIPT_VOUCHER rv ON rv.RvId = a.RvId
    WHERE  a.AllocationId = @AllocationId AND a.IsActive = 1;

    IF @RvId IS NULL
        BEGIN RAISERROR('Allocation not found.', 16, 1); RETURN; END
    IF @RvStatus <> 'Approved'
        BEGIN RAISERROR('Allocations can only be changed while the receipt voucher is Approved.', 16, 1); RETURN; END

    IF NULLIF(LTRIM(RTRIM(ISNULL(@Reason, ''))), '') IS NULL
        BEGIN RAISERROR('A reason is required to remove an allocation from an approved receipt voucher.', 16, 1); RETURN; END
    IF NULLIF(@PasswordHash, '') IS NULL
        BEGIN RAISERROR('Password is required.', 16, 1); RETURN; END

    IF NOT EXISTS (
        SELECT 1
        FROM   proj.TBL_USER_ROLES  ur
        JOIN   proj.TBL_ROLE_SECRET rs ON rs.RoleId  = ur.RoleId
        JOIN   proj.TBL_USERS       u  ON u.UserId   = ur.UserId
        WHERE  u.Username         = @ModifiedBy
          AND  rs.SecretKey       = 'RV_REVISE'
          AND  rs.SecretValueHash = @PasswordHash
    )
        BEGIN RAISERROR('Incorrect password. You do not have permission to remove this allocation.', 16, 1); RETURN; END

    -- Store the removal reason before soft-deleting
    UPDATE proj.TBL_RECEIPT_VOUCHER_ALLOCATION
    SET    IsActive     = 0,
           Reason       = @Reason,
           ModifiedBy   = @ModifiedBy,
           ModifiedDate = GETDATE()
    WHERE  AllocationId = @AllocationId;

    DECLARE @ExchangeRate DECIMAL(18,6);
    SELECT @ExchangeRate = ISNULL(NULLIF(ExchangeRate, 0), 1)
    FROM   proj.TBL_RECEIPT_VOUCHER WHERE RvId = @RvId;

    UPDATE proj.TBL_RECEIPT_VOUCHER
    SET    AllocatedAmount = (
               SELECT ISNULL(SUM(AllocatedAmount), 0) / @ExchangeRate
               FROM   proj.TBL_RECEIPT_VOUCHER_ALLOCATION
               WHERE  RvId = @RvId AND IsActive = 1
           ),
           ModifiedDate = GETDATE()
    WHERE  RvId = @RvId;

    DECLARE @JobId NVARCHAR(50) =
        (SELECT JobId FROM proj.TBL_INVOICE WHERE InvoiceId = @InvoiceId);
    IF NULLIF(@JobId, '') IS NOT NULL
        EXEC proj.sp_RecalcJobPayments @JobId, @ModifiedBy;

    SELECT 'OK' AS Result;
END
GO

IF OBJECT_ID(N'[proj].[sp_DeleteServiceReceiptLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeleteServiceReceiptLine];
GO

CREATE PROCEDURE proj.sp_DeleteServiceReceiptLine
    @SrvLineId  INT,
    @ModifiedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- Guard: line must exist
    DECLARE @SrvId INT;
    SELECT @SrvId = SrvId FROM proj.TBL_SRV_LINE WHERE SrvLineId = @SrvLineId AND IsActive = 1;

    IF @SrvId IS NULL
    BEGIN
        RAISERROR('Service receipt line not found or already deleted.', 16, 1); RETURN;
    END

    -- Guard: parent SRV must be in Draft status
    DECLARE @SrvStatus NVARCHAR(30);
    SELECT @SrvStatus = Status FROM proj.TBL_SRV_HEADER WHERE SrvId = @SrvId AND IsActive = 1;

    IF @SrvStatus IS NULL
    BEGIN
        RAISERROR('Service Receipt not found or is inactive.', 16, 1); RETURN;
    END
    IF @SrvStatus <> 'Draft'
    BEGIN
        RAISERROR('Service Receipt lines can only be deleted when the receipt is in Draft status. Current status: %s', 16, 1, @SrvStatus); RETURN;
    END

    UPDATE proj.TBL_SRV_LINE
    SET    IsActive = 0, ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE()
    WHERE  SrvLineId = @SrvLineId;

    SELECT CAST(@SrvLineId AS NVARCHAR(20));
END
GO

IF OBJECT_ID(N'[proj].[sp_DeleteStockIssue]') IS NOT NULL DROP PROCEDURE [proj].[sp_DeleteStockIssue];
GO

CREATE PROCEDURE proj.sp_DeleteStockIssue
    @IssueId    INT,
    @ModifiedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM proj.TBL_STOCK_ISSUE WHERE IssueId = @IssueId AND IsActive = 1)
    BEGIN SELECT N'NotExists'; RETURN; END

    IF EXISTS (SELECT 1 FROM proj.TBL_STOCK_ISSUE WHERE IssueId = @IssueId AND Status = 'Confirmed')
    BEGIN SELECT N'CannotDelete'; RETURN; END

    -- Soft-delete lines
    UPDATE proj.TBL_STOCK_ISSUE_LINE
    SET IsActive = 0, ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE()
    WHERE IssueId = @IssueId;

    -- Soft-delete header
    UPDATE proj.TBL_STOCK_ISSUE
    SET IsActive = 0, ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE()
    WHERE IssueId = @IssueId;

    SELECT N'OK';
END;
GO

