-- 5. sp_DeleteSupplierInvoiceLine — add parent Draft status guard (was completely unguarded)
CREATE   PROCEDURE proj.sp_DeleteSupplierInvoiceLine
    @SupplierInvLineId INT,
    @ActionBy          NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @InvoiceId INT;
    SELECT @InvoiceId = SupplierInvoiceId
    FROM proj.TBL_SUPPLIER_INVOICE_LINE
    WHERE SupplierInvLineId = @SupplierInvLineId AND IsActive = 1;

    IF @InvoiceId IS NULL
    BEGIN
        RAISERROR('Supplier invoice line not found or already deleted.', 16, 1); RETURN;
    END

    DECLARE @InvoiceStatus NVARCHAR(30);
    SELECT @InvoiceStatus = Status
    FROM proj.TBL_SUPPLIER_INVOICE
    WHERE SupplierInvoiceId = @InvoiceId AND IsActive = 1;

    IF @InvoiceStatus IS NULL
    BEGIN
        RAISERROR('Supplier Invoice not found or is inactive.', 16, 1); RETURN;
    END

    IF @InvoiceStatus <> 'Draft'
    BEGIN
        DECLARE @Msg NVARCHAR(200) = 'Supplier Invoice lines can only be deleted when the invoice is in Draft status. Current status: ' + @InvoiceStatus;
        RAISERROR(@Msg, 16, 1); RETURN;
    END

    UPDATE proj.TBL_SUPPLIER_INVOICE_LINE
    SET IsActive     = 0,
        ModifiedBy   = @ActionBy,
        ModifiedDate = GETDATE()
    WHERE SupplierInvLineId = @SupplierInvLineId;

    -- Recalculate header totals
    UPDATE proj.TBL_SUPPLIER_INVOICE
    SET SubTotal    = (SELECT ISNULL(SUM(LineTotal),        0) FROM proj.TBL_SUPPLIER_INVOICE_LINE WHERE SupplierInvoiceId = @InvoiceId AND IsActive = 1),
        TaxAmount   = (SELECT ISNULL(SUM(TaxAmount),        0) FROM proj.TBL_SUPPLIER_INVOICE_LINE WHERE SupplierInvoiceId = @InvoiceId AND IsActive = 1),
        TotalAmount = (SELECT ISNULL(SUM(LineTotalWithTax), 0) FROM proj.TBL_SUPPLIER_INVOICE_LINE WHERE SupplierInvoiceId = @InvoiceId AND IsActive = 1),
        ModifiedBy   = @ActionBy,
        ModifiedDate = GETDATE()
    WHERE SupplierInvoiceId = @InvoiceId;

    SELECT 'OK';
END
GO

