IF OBJECT_ID(N'[proj].[sp_ExecuteStockTransfer]') IS NOT NULL DROP PROCEDURE [proj].[sp_ExecuteStockTransfer];
GO

CREATE PROCEDURE proj.sp_ExecuteStockTransfer
    @TransferId INT,
    @ActionBy   NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    BEGIN TRY
        DECLARE @TransferNo NVARCHAR(30), @FromJobId NVARCHAR(50), @ToJobId NVARCHAR(50), @TDate DATE;

        SELECT @TransferNo=TransferNo, @FromJobId=FromJobId, @ToJobId=ToJobId, @TDate=TransferDate
        FROM proj.TBL_STOCK_TRANSFER
        WHERE TransferId=@TransferId AND IsActive=1;

        IF @TransferNo IS NULL THROW 50620, 'Transfer not found.', 1;
        IF NOT EXISTS (
            SELECT 1 FROM proj.TBL_STOCK_TRANSFER_LINE
            WHERE TransferId=@TransferId AND IsActive=1)
            THROW 50621, 'Cannot execute a transfer with no lines.', 1;

        DECLARE @FromIsInHouse BIT = 0, @ToIsInHouse BIT = 0;
        IF NULLIF(@FromJobId,'') IS NOT NULL
            SELECT @FromIsInHouse = ISNULL(jt.IsBudgetHeaderLinked,0)
            FROM proj.TBL_JOB j JOIN proj.TBL_JOBTYPE jt ON jt.JobTypeId = j.JobTypeId
            WHERE j.JobId = @FromJobId;
        IF NULLIF(@ToJobId,'') IS NOT NULL
            SELECT @ToIsInHouse = ISNULL(jt.IsBudgetHeaderLinked,0)
            FROM proj.TBL_JOB j JOIN proj.TBL_JOBTYPE jt ON jt.JobTypeId = j.JobTypeId
            WHERE j.JobId = @ToJobId;

        DECLARE @ItemId INT, @Qty DECIMAL(18,4), @UnitCost DECIMAL(18,4);
        DECLARE @Bal DECIMAL(18,4), @Msg NVARCHAR(400);

        DECLARE c CURSOR LOCAL FAST_FORWARD FOR
            SELECT ItemId, Qty, UnitCost
            FROM proj.TBL_STOCK_TRANSFER_LINE
            WHERE TransferId=@TransferId AND IsActive=1;

        OPEN c;
        FETCH NEXT FROM c INTO @ItemId, @Qty, @UnitCost;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            SELECT @Bal = ISNULL(SUM(QtyIn - QtyOut), 0)
            FROM proj.TBL_STOCK_LEDGER
            WHERE ItemId=@ItemId AND JobId=@FromJobId;

            IF @Bal < @Qty
            BEGIN
                SET @Msg = 'Insufficient stock in source job ' + @FromJobId +
                    ' for item ' +
                    ISNULL((SELECT ItemCode FROM proj.TBL_ITEM WHERE ItemId=@ItemId), CAST(@ItemId AS NVARCHAR)) +
                    ' (available: ' + CAST(@Bal AS NVARCHAR(30)) +
                    ', required: '  + CAST(@Qty  AS NVARCHAR(30)) + ').';
                THROW 50622, @Msg, 1;
            END

            INSERT INTO proj.TBL_STOCK_LEDGER
                (ItemId, TransDate, TransType, RefId, RefNo,
                 QtyIn, QtyOut, UnitCost, IsJobStock, JobId, CreatedBy)
            VALUES
                (@ItemId, @TDate, 'TRANSFER', @TransferId, @TransferNo,
                 0, @Qty, @UnitCost,
                 CASE WHEN @FromIsInHouse=1 THEN 0 ELSE 1 END, @FromJobId, @ActionBy),
                (@ItemId, @TDate, 'TRANSFER', @TransferId, @TransferNo,
                 @Qty, 0, @UnitCost,
                 CASE WHEN @ToIsInHouse=1 THEN 0 ELSE 1 END, @ToJobId, @ActionBy);

            FETCH NEXT FROM c INTO @ItemId, @Qty, @UnitCost;
        END
        CLOSE c; DEALLOCATE c;

        COMMIT;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        IF CURSOR_STATUS('local','c') >= 0 BEGIN CLOSE c; DEALLOCATE c; END;
        THROW;
    END CATCH
END;
GO

IF OBJECT_ID(N'[proj].[sp_GenerateBomFromBudget]') IS NOT NULL DROP PROCEDURE [proj].[sp_GenerateBomFromBudget];
GO

CREATE PROCEDURE proj.sp_GenerateBomFromBudget
    @JobId NVARCHAR(50),
    @RvNo  INT,
    @By    NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM proj.TBL_JOB_BUDGET_ITEM WHERE JobId=@JobId AND RvNo=@RvNo AND IsActive=1) RETURN;

    DECLARE @JobTypeId NVARCHAR(50) = (SELECT JobTypeId FROM proj.TBL_JOB WHERE JobId=@JobId);
    DECLARE @JobCurrencyId INT = (SELECT JobCurrencyId FROM proj.TBL_JOB WHERE JobId=@JobId);
    DECLARE @HdrId INT = (SELECT TOP 1 BomHeaderId FROM proj.TBL_BOM_HEADER WHERE JobId=@JobId AND IsActive=1);

    DECLARE @Agg TABLE (CostCategoryId INT, ItemId INT, Qty DECIMAL(18,4), UnitPrice DECIMAL(18,4), UomId INT);
    INSERT INTO @Agg
    SELECT bi.CostCategoryId, bi.ItemId, SUM(bi.Qty),
           CASE WHEN SUM(bi.Qty) > 0 THEN SUM(bi.Qty * bi.UnitPrice) / SUM(bi.Qty) ELSE 0 END,
           MAX(ISNULL(bi.UomId, i.BaseUomId))
    FROM proj.TBL_JOB_BUDGET_ITEM bi
    JOIN proj.TBL_ITEM i ON i.ItemId = bi.ItemId
    WHERE bi.JobId=@JobId AND bi.RvNo=@RvNo AND bi.IsActive=1 AND bi.Qty > 0
    GROUP BY bi.CostCategoryId, bi.ItemId;

    IF @HdrId IS NULL
    BEGIN
        INSERT INTO proj.TBL_BOM_HEADER (JobId, JobTypeId, BomDate, BomDescription, BomVersion, BomStatus, TotalBomValue, CreatedBy, CreatedDate)
        VALUES (@JobId, @JobTypeId, CAST(GETDATE() AS DATE),
                'Generated from budget Rev ' + CAST(@RvNo AS NVARCHAR(10)), 1, 'Draft', 0, @By, GETDATE());
        SET @HdrId = SCOPE_IDENTITY();
    END
    ELSE
        UPDATE proj.TBL_BOM_HEADER
        SET BomVersion = BomVersion + 1,
            BomDescription = 'Synced from budget Rev ' + CAST(@RvNo AS NVARCHAR(10)),
            ModifiedBy = @By, ModifiedDate = GETDATE()
        WHERE BomHeaderId = @HdrId;

    DECLARE @cat INT, @itm INT, @qty DECIMAL(18,4), @price DECIMAL(18,4), @uom INT,
            @catName NVARCHAR(100), @catCode NVARCHAR(20), @sortOrder INT, @secId INT, @detId INT;

    DECLARE c CURSOR LOCAL FAST_FORWARD FOR
        SELECT a.CostCategoryId, a.ItemId, a.Qty, a.UnitPrice, a.UomId,
               ec.CategoryName, ec.CategoryCode, ISNULL(ec.SortOrder,0)
        FROM @Agg a JOIN proj.TBL_JOB_EXPENSE_CATEGORY ec ON ec.ExpenseCategoryId = a.CostCategoryId;
    OPEN c;
    FETCH NEXT FROM c INTO @cat, @itm, @qty, @price, @uom, @catName, @catCode, @sortOrder;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        SET @secId = (SELECT TOP 1 BomSectionId FROM proj.TBL_BOM_SECTION
                      WHERE JobTypeId=@JobTypeId AND IsActive=1 AND (SectionCode=@catCode OR SectionName=@catName));
        IF @secId IS NULL
        BEGIN
            INSERT INTO proj.TBL_BOM_SECTION (JobTypeId, SectionCode, SectionName, Description, SortOrder, IsActive, CreatedBy, CreatedDate)
            VALUES (@JobTypeId, @catCode, @catName, 'From budget header', @sortOrder, 1, ISNULL(@By,'SYSTEM'), GETDATE());
            SET @secId = SCOPE_IDENTITY();
        END

        SET @detId = (SELECT TOP 1 BomId FROM proj.TBL_BOM_DETAILS
                      WHERE BomHeaderId=@HdrId AND BomSectionId=@secId AND ItemId=@itm AND IsActive=1);

        IF @detId IS NULL
            INSERT INTO proj.TBL_BOM_DETAILS
                (BomHeaderId, JobId, BomSectionId, ItemId, SortOrder, BomRequestedQty, BomReceivedQty, PrCreatedQty, PoCreatedQty,
                 UomId, BomPrice, CurrencyId, ExchangeRate, BomStatus, IsActive, CreatedBy, CreatedDate)
            VALUES (@HdrId, @JobId, @secId, @itm,
                    (SELECT ISNULL(MAX(SortOrder),0)+10 FROM proj.TBL_BOM_DETAILS WHERE BomHeaderId=@HdrId AND BomSectionId=@secId),
                    @qty, 0, 0, 0, @uom, @price, @JobCurrencyId, 1, 'Pending', 1, ISNULL(@By,'SYSTEM'), GETDATE());
        ELSE
            UPDATE proj.TBL_BOM_DETAILS
            SET BomRequestedQty = @qty, BomPrice = @price, UomId = @uom,
                BomStatus = CASE
                    WHEN BomReceivedQty >= @qty THEN 'FullyReceived'
                    WHEN BomReceivedQty  > 0    THEN 'PartialReceived'
                    WHEN PoCreatedQty   >= @qty THEN 'PORaised'
                    WHEN PoCreatedQty    > 0    THEN 'POPartial'
                    WHEN PrCreatedQty   >= @qty THEN 'PRRaised'
                    WHEN PrCreatedQty    > 0    THEN 'PRPartial'
                    ELSE 'Pending' END,
                ModifiedBy = @By, ModifiedDate = GETDATE()
            WHERE BomId = @detId;

        FETCH NEXT FROM c INTO @cat, @itm, @qty, @price, @uom, @catName, @catCode, @sortOrder;
    END
    CLOSE c; DEALLOCATE c;

    UPDATE bd SET IsActive = 0, ModifiedBy = @By, ModifiedDate = GETDATE()
    FROM proj.TBL_BOM_DETAILS bd
    WHERE bd.BomHeaderId = @HdrId AND bd.IsActive = 1
      AND ISNULL(bd.PrCreatedQty,0) = 0
      AND NOT EXISTS (SELECT 1 FROM @Agg a WHERE a.ItemId = bd.ItemId);

    UPDATE proj.TBL_BOM_HEADER
    SET TotalBomValue = (SELECT ISNULL(SUM(BomRequestedQty * BomPrice * ExchangeRate),0)
                         FROM proj.TBL_BOM_DETAILS WHERE BomHeaderId=@HdrId AND IsActive=1)
    WHERE BomHeaderId=@HdrId;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GenerateBomFromBudgetForJob]') IS NOT NULL DROP PROCEDURE [proj].[sp_GenerateBomFromBudgetForJob];
GO

CREATE PROCEDURE proj.sp_GenerateBomFromBudgetForJob
    @JobId NVARCHAR(50),
    @By    NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Rv INT = (SELECT MAX(RvNo) FROM proj.TBL_JOB_BUDGET WHERE JobId = @JobId);
    DECLARE @HdrId INT = (SELECT TOP 1 BomHeaderId FROM proj.TBL_BOM_HEADER WHERE JobId=@JobId AND IsActive=1);
    DECLARE @HasItems BIT = CASE WHEN @Rv IS NOT NULL AND EXISTS (
        SELECT 1 FROM proj.TBL_JOB_BUDGET_ITEM WHERE JobId=@JobId AND RvNo=@Rv AND IsActive=1) THEN 1 ELSE 0 END;
    DECLARE @Locked BIT = CASE WHEN @HdrId IS NOT NULL AND EXISTS (
        SELECT 1 FROM proj.TBL_BOM_DETAILS WHERE BomHeaderId=@HdrId AND IsActive=1 AND PrCreatedQty>0) THEN 1 ELSE 0 END;

    IF @Locked = 1
    BEGIN SELECT 0 AS Created, 'The BOM already has PRs raised — it can no longer be regenerated from the budget.' AS Message; RETURN; END
    IF @HasItems = 0
    BEGIN SELECT 0 AS Created, 'No budget items found. Add items under the budget headers first.' AS Message; RETURN; END

    EXEC proj.sp_GenerateBomFromBudget @JobId = @JobId, @RvNo = @Rv, @By = @By;

    IF EXISTS (SELECT 1 FROM proj.TBL_BOM_HEADER WHERE JobId=@JobId AND IsActive=1)
        SELECT 1 AS Created,
               CASE WHEN @HdrId IS NOT NULL THEN 'BOM rebuilt from the current budget items.'
                    ELSE 'BOM generated from the budget items.' END AS Message;
    ELSE
        SELECT 0 AS Created, 'Nothing was generated.' AS Message;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GenerateJobSeries]') IS NOT NULL DROP PROCEDURE [proj].[sp_GenerateJobSeries];
GO
CREATE PROCEDURE [PROJ].[sp_GenerateJobSeries]
    @JobTypeId NVARCHAR(50),
    @JobID NVARCHAR(100) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @Prefix NVARCHAR(10),
        @Suffix NVARCHAR(10),
        @CurrentSeries INT,
        @StartingSeries INT,
        @NextNumber INT,
        @YearCode NVARCHAR(2),
        @OwnTran BIT = 0;
    SET @YearCode = RIGHT(CAST(YEAR(GETDATE()) AS NVARCHAR), 2);

    BEGIN TRY
        -- Participate in the caller's transaction when there is one; otherwise own it
        IF @@TRANCOUNT = 0 BEGIN BEGIN TRAN; SET @OwnTran = 1; END

        SELECT
            @Prefix = PreFix,
            @Suffix = Suffix,
            @CurrentSeries = CurrentSeries,
            @StartingSeries = CAST(StartingSeries AS INT)
        FROM PROJ.[TBL_JOBTYPE] WITH (UPDLOCK, HOLDLOCK)
        WHERE JobTypeId = @JobTypeId AND IsActive = '1';

        IF @StartingSeries IS NULL AND @CurrentSeries IS NULL AND @Prefix IS NULL
        BEGIN
            DECLARE @msg NVARCHAR(200) = 'Job type not found or inactive: ' + ISNULL(@JobTypeId, '(null)');
            RAISERROR(@msg, 16, 1);
        END

        -- Use StartingSeries if first time
        IF (@CurrentSeries IS NULL OR @CurrentSeries = 0)
            SET @NextNumber = @StartingSeries;
        ELSE
            SET @NextNumber = @CurrentSeries + 1;

        IF @NextNumber IS NULL
        BEGIN
            DECLARE @msg2 NVARCHAR(200) = 'Job type ' + @JobTypeId + ' has no StartingSeries configured.';
            RAISERROR(@msg2, 16, 1);
        END

        UPDATE PROJ.[TBL_JOBTYPE]
        SET CurrentSeries = @NextNumber
        WHERE JobTypeId = @JobTypeId AND IsActive = '1';

        -- Build Job Number
        SET @JobID =
            ISNULL(@Prefix, '') + @YearCode + ISNULL(@Suffix, '') + '-' +
            CAST(@NextNumber AS NVARCHAR);

        IF @OwnTran = 1 COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF @OwnTran = 1 AND @@TRANCOUNT > 0 ROLLBACK TRAN;
        THROW;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_GenerateMHNo]') IS NOT NULL DROP PROCEDURE [proj].[sp_GenerateMHNo];
GO
CREATE PROCEDURE PROJ.sp_GenerateMHNo
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE
        @Prefix      NVARCHAR(20),
        @Separator   NCHAR(1),
        @PadLength   TINYINT,
        @CurSeries   INT,
        @StartSeries INT,
        @CurPeriod   NVARCHAR(8),
        @ThisPeriod  NVARCHAR(8),
        @NextSeries  INT,
        @DocNo       NVARCHAR(30),
        @OwnTran     BIT = 0;

    -- Date component = today's date as yyMMdd (e.g. 260611 for 2026-06-11)
    SET @ThisPeriod = FORMAT(GETDATE(), 'yyMMdd');

    BEGIN TRY
        -- Participate in the caller's transaction when there is one; otherwise own it
        IF @@TRANCOUNT = 0 BEGIN BEGIN TRAN; SET @OwnTran = 1; END

        SELECT
            @Prefix      = Prefix,
            @Separator   = Separator,
            @PadLength   = PadLength,
            @CurSeries   = CurrentSeries,
            @StartSeries = StartingSeries,
            @CurPeriod   = CurrentPeriod
        FROM PROJ.TBL_DOCUMENT_SERIES WITH (UPDLOCK, HOLDLOCK)
        WHERE DocTypeId = 'MH' AND IsActive = 1;

        IF @Prefix IS NULL AND @StartSeries IS NULL
        BEGIN
            RAISERROR('Document series not found or inactive: MH', 16, 1);
        END

        -- Reset the running counter whenever the day changes
        IF @CurPeriod IS NULL OR @CurPeriod <> @ThisPeriod
            SET @NextSeries = @StartSeries;
        ELSE
            SET @NextSeries = ISNULL(@CurSeries, 0) + 1;

        UPDATE PROJ.TBL_DOCUMENT_SERIES
        SET CurrentSeries = @NextSeries,
            CurrentPeriod = @ThisPeriod,
            ModifiedDate  = GETDATE()
        WHERE DocTypeId = 'MH' AND IsActive = 1;

        SET @DocNo = @Prefix + @Separator + @ThisPeriod + @Separator
                   + RIGHT(REPLICATE('0', @PadLength) + CAST(@NextSeries AS NVARCHAR(10)), @PadLength);

        IF @OwnTran = 1 COMMIT TRAN;

        SELECT @DocNo AS DocumentNo;
    END TRY
    BEGIN CATCH
        IF @OwnTran = 1 AND @@TRANCOUNT > 0 ROLLBACK TRAN;
        THROW;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_GetActionPermissions]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetActionPermissions];
GO
CREATE   PROCEDURE proj.sp_GetActionPermissions
    @RoleId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        m.MenuId,
        m.MenuName,
        m.MenuUrl,
        p.MenuName  AS ParentMenuName,
        gp.MenuName AS GrandParentMenuName,
        CASE
            WHEN gp.MenuId IS NOT NULL THEN gp.MenuName + N' › ' + p.MenuName
            WHEN p.MenuId IS NOT NULL
                 AND EXISTS (SELECT 1 FROM proj.TBL_MENU c
                             WHERE c.ParentMenuId = m.MenuId AND c.IsActive = 1)
                 THEN p.MenuName + N' › ' + m.MenuName
            ELSE ISNULL(p.MenuName, N'Top Level')
        END AS SectionName,
        ma.ActionId,
        ma.ActionName,
        ma.ActionCode,
        ISNULL(rma.RoleMenuActionId, 0) AS RoleMenuActionId,
        ISNULL(rma.IsAllowed,        0) AS IsAllowed
    FROM proj.TBL_MENU m
    LEFT JOIN proj.TBL_MENU p  ON p.MenuId  = m.ParentMenuId
    LEFT JOIN proj.TBL_MENU gp ON gp.MenuId = p.ParentMenuId
    INNER JOIN proj.TBL_MENU_ACTIONS ma
            ON ma.MenuId  = m.MenuId
           AND ma.IsActive = 1
    LEFT JOIN proj.TBL_ROLE_MENU_ACTION rma
           ON rma.MenuId   = m.MenuId
          AND rma.ActionId = ma.ActionId
          AND rma.RoleId   = @RoleId
    WHERE m.IsActive = 1
    ORDER BY
        ISNULL(gp.MenuId, ISNULL(p.MenuId, m.MenuId)),
        ISNULL(gp.MenuOrder, ISNULL(p.MenuOrder, m.MenuOrder)),
        ISNULL(p.MenuOrder,  m.MenuOrder),
        m.MenuOrder,
        ma.ActionId;
END;
GO

