IF OBJECT_ID(N'[proj].[sp_GetAdjustment]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetAdjustment];
GO

-- GET header + lines
CREATE   PROCEDURE proj.sp_GetAdjustment
    @AdjustmentId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT a.AdjustmentId, a.AdjustmentNo, a.AdjustmentDate, a.Reason, a.Notes, a.Status,
           a.CreatedBy, a.CreatedDate, a.ModifiedBy, a.ModifiedDate, a.PostedBy, a.PostedDate,
           (SELECT COUNT(*) FROM proj.TBL_STOCK_ADJUSTMENT_LINE WHERE AdjustmentId = a.AdjustmentId AND IsActive=1) AS LineCount
    FROM proj.TBL_STOCK_ADJUSTMENT a
    WHERE a.AdjustmentId = @AdjustmentId AND a.IsActive = 1;

    SELECT l.AdjustmentLineId, l.AdjustmentId, l.LineNum, l.ItemId,
           i.ItemCode, ISNULL(l.ItemDesc, i.ItemName) AS ItemDesc,
           l.AdjustQty, l.UomId, u.UomName, l.UnitCost,
           ABS(l.AdjustQty) * l.UnitCost AS LineValue,
           CASE WHEN l.AdjustQty >= 0 THEN 'IN' ELSE 'OUT' END AS Direction,
           l.Reason, vl.ItemDescription AS ReasonLabel, l.Notes,
           bal.QtyOnHand AS CurrentStock
    FROM proj.TBL_STOCK_ADJUSTMENT_LINE l
    LEFT JOIN proj.TBL_ITEM i        ON i.ItemId = l.ItemId
    LEFT JOIN proj.TBL_ITEM_UOM u    ON u.UomId  = l.UomId
    LEFT JOIN proj.TBL_STOCK_BALANCE bal ON bal.ItemId = l.ItemId
    LEFT JOIN proj.TBL_VLIST vl      ON vl.TypeName='Inventory' AND vl.ListName='AdjustmentReason' AND vl.ItemValue = l.Reason
    WHERE l.AdjustmentId = @AdjustmentId AND l.IsActive = 1
    ORDER BY l.LineNum;
END;
GO

