IF OBJECT_ID(N'[proj].[sp_GetAlertLogs]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetAlertLogs];
GO
CREATE   PROCEDURE proj.sp_GetAlertLogs
    @AlertId  INT           = NULL,
    @Status   NVARCHAR(50)  = NULL,
    @DateFrom DATE          = NULL,
    @DateTo   DATE          = NULL,
    @Page     INT           = 1,
    @PageSize INT           = 20
AS
BEGIN
    SET NOCOUNT ON;
    SELECT l.LogId, l.AlertId, a.AlertName, l.RunDate, l.Status,
           l.ErrorMessage, l.RecipientCount, l.DataRowCount, l.DurationMs,
           COUNT(*) OVER() AS TotalRows
    FROM proj.TBL_EMAIL_ALERT_LOG l
    JOIN proj.TBL_EMAIL_ALERT_CONFIG a ON a.AlertId = l.AlertId
    WHERE (@AlertId  IS NULL OR l.AlertId = @AlertId)
      AND (@Status   IS NULL OR l.Status  = @Status)
      AND (@DateFrom IS NULL OR CAST(l.RunDate AS DATE) >= @DateFrom)
      AND (@DateTo   IS NULL OR CAST(l.RunDate AS DATE) <= @DateTo)
    ORDER BY l.RunDate DESC
    OFFSET (@Page - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;
END
GO

