IF OBJECT_ID(N'[proj].[sp_GetAllApprovals]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetAllApprovals];
GO
CREATE   PROCEDURE proj.sp_GetAllApprovals
    @Status       NVARCHAR(200) = NULL,
    @ModuleCode   NVARCHAR(200) = NULL,
    @SearchText   NVARCHAR(200) = NULL,
    @SubmittedBy  NVARCHAR(200) = NULL,
    @FinalActionBy NVARCHAR(200) = NULL,
    @DateFrom     DATE          = NULL,
    @DateTo       DATE          = NULL,
    @PageNumber   INT           = 1,
    @PageSize     INT           = 50,
    @SortCol      NVARCHAR(50)  = 'SubmittedDate',
    @SortDir      NVARCHAR(4)   = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    SET @SearchText    = NULLIF(LTRIM(RTRIM(@SearchText)),    '');
    SET @SubmittedBy   = NULLIF(LTRIM(RTRIM(@SubmittedBy)),   '');
    SET @FinalActionBy = NULLIF(LTRIM(RTRIM(@FinalActionBy)), '');

    SELECT
        t.TransactionId,
        m.ModuleCode,
        m.ModuleName,
        t.DocumentId,
        t.DocumentNo,
        t.DocumentAmount,
        t.CurrentStatus,
        t.CurrentLevelNo,
        t.TotalLevels,
        p.PolicyName,
        STUFF((
            SELECT ', ' + CASE
                WHEN al.ApproverType = 'Role' THEN ISNULL(r.RoleName, '(role)')
                WHEN al.ApproverType = 'User' THEN ISNULL(u.FullName,  '(user)')
                ELSE 'Anyone' END
            FROM proj.TBL_APPROVAL_LEVEL al
            LEFT JOIN proj.TBL_ROLES r ON r.RoleId = al.ApproverId AND al.ApproverType = 'Role'
            LEFT JOIN proj.TBL_USERS u ON u.UserId = al.ApproverId AND al.ApproverType = 'User'
            WHERE al.PolicyId = t.PolicyId AND al.LevelNo = t.CurrentLevelNo AND al.IsActive = 1
            FOR XML PATH(''), TYPE
        ).value('.','NVARCHAR(MAX)'), 1, 2, '')      AS CurrentApprover,
        t.SubmittedBy,
        t.SubmittedDate,
        t.CompletedDate,
        t.FinalAction,
        t.FinalActionBy,
        t.FinalRemarks,
        DATEDIFF(DAY, t.SubmittedDate, ISNULL(t.CompletedDate, GETDATE())) AS DaysElapsed,
        COUNT(*) OVER() AS TotalRows
    FROM proj.TBL_APPROVAL_TRANSACTION t
    JOIN proj.TBL_APPROVAL_MODULE m ON m.ModuleId = t.ModuleId
    JOIN proj.TBL_APPROVAL_POLICY p ON p.PolicyId = t.PolicyId
    WHERE
        (@Status        IS NULL OR CHARINDEX(',' + t.CurrentStatus + ',', ',' + @Status     + ',') > 0)
        AND (@ModuleCode   IS NULL OR CHARINDEX(',' + m.ModuleCode  + ',', ',' + @ModuleCode + ',') > 0)
        AND (@SearchText   IS NULL OR t.DocumentNo     LIKE N'%' + @SearchText   + N'%'
                                   OR t.SubmittedBy    LIKE N'%' + @SearchText   + N'%'
                                   OR t.FinalActionBy  LIKE N'%' + @SearchText   + N'%')
        AND (@SubmittedBy   IS NULL OR t.SubmittedBy   LIKE N'%' + @SubmittedBy   + N'%')
        AND (@FinalActionBy IS NULL OR t.FinalActionBy LIKE N'%' + @FinalActionBy + N'%')
        AND (@DateFrom IS NULL OR CAST(t.SubmittedDate AS DATE) >= @DateFrom)
        AND (@DateTo   IS NULL OR CAST(t.SubmittedDate AS DATE) <= @DateTo)
    ORDER BY
        CASE WHEN @SortCol='SubmittedDate' AND @SortDir='DESC' THEN t.SubmittedDate  END DESC,
        CASE WHEN @SortCol='SubmittedDate' AND @SortDir='ASC'  THEN t.SubmittedDate  END ASC,
        CASE WHEN @SortCol='DocumentNo'    AND @SortDir='DESC' THEN t.DocumentNo     END DESC,
        CASE WHEN @SortCol='DocumentNo'    AND @SortDir='ASC'  THEN t.DocumentNo     END ASC,
        CASE WHEN @SortCol='CurrentStatus' AND @SortDir='DESC' THEN t.CurrentStatus  END DESC,
        CASE WHEN @SortCol='CurrentStatus' AND @SortDir='ASC'  THEN t.CurrentStatus  END ASC,
        CASE WHEN @SortCol='DaysElapsed'   AND @SortDir='DESC'
             THEN DATEDIFF(DAY, t.SubmittedDate, ISNULL(t.CompletedDate, GETDATE())) END DESC,
        CASE WHEN @SortCol='DaysElapsed'   AND @SortDir='ASC'
             THEN DATEDIFF(DAY, t.SubmittedDate, ISNULL(t.CompletedDate, GETDATE())) END ASC,
        t.SubmittedDate DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetApprovalDelegates]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetApprovalDelegates];
GO

CREATE   PROCEDURE proj.sp_GetApprovalDelegates
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        d.DelegateId,
        d.LevelId,
        lv.LevelNo,
        lv.LevelName,
        lv.ApproverType,
        p.PolicyId,
        p.PolicyName,
        m.ModuleCode,
        m.ModuleName,
        d.OriginalUserId,
        ou.FullName   AS OriginalUserName,
        d.DelegateUserId,
        du.FullName   AS DelegateUserName,
        d.FromDate,
        d.ToDate,
        d.Reason,
        d.IsActive,
        CASE WHEN d.IsActive = 1
              AND CAST(GETDATE() AS date) BETWEEN d.FromDate AND d.ToDate
             THEN 1 ELSE 0 END AS IsCurrentlyActive,
        d.CreatedBy,
        d.CreatedDate,
        d.ModifiedBy,
        d.ModifiedDate
    FROM proj.TBL_APPROVAL_DELEGATE d
    JOIN proj.TBL_APPROVAL_LEVEL  lv ON lv.LevelId  = d.LevelId
    JOIN proj.TBL_APPROVAL_POLICY p  ON p.PolicyId  = lv.PolicyId
    JOIN proj.TBL_APPROVAL_MODULE m  ON m.ModuleId  = p.ModuleId
    JOIN proj.TBL_USERS           ou ON ou.UserId   = d.OriginalUserId
    JOIN proj.TBL_USERS           du ON du.UserId   = d.DelegateUserId
    ORDER BY d.IsActive DESC, d.FromDate DESC;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetApprovalHistory]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetApprovalHistory];
GO

-- ══════════════════════════════════════════════════════════════
-- sp_GetApprovalHistory
-- Full audit log for a transaction
-- ══════════════════════════════════════════════════════════════
CREATE   PROCEDURE PROJ.sp_GetApprovalHistory
    @TransactionId INT
AS
BEGIN
    SET NOCOUNT ON;

    -- Transaction summary
    SELECT
        t.TransactionId,
        m.ModuleCode,
        m.ModuleName,
        t.DocumentId,
        t.DocumentNo,
        t.DocumentAmount,
        t.PolicyId,
        p.PolicyName,
        t.CurrentStatus,
        t.CurrentLevelNo,
        t.TotalLevels,
        t.SubmittedBy,
        t.SubmittedDate,
        t.CompletedDate,
        t.FinalAction,
        t.FinalActionBy,
        t.FinalRemarks
    FROM   PROJ.TBL_APPROVAL_TRANSACTION t
    JOIN   PROJ.TBL_APPROVAL_MODULE      m ON m.ModuleId = t.ModuleId
    JOIN   PROJ.TBL_APPROVAL_POLICY      p ON p.PolicyId = t.PolicyId
    WHERE  t.TransactionId = @TransactionId;

    -- Level definitions for this policy (to show full pipeline)
    SELECT
        lv.LevelNo,
        lv.LevelName,
        lv.ApproverType,
        CASE lv.ApproverType
            WHEN 'Role' THEN r.RoleName
            WHEN 'User' THEN u.FullName
            ELSE NULL
        END AS ApproverName,
        lv.IsMandatory
    FROM   PROJ.TBL_APPROVAL_TRANSACTION t
    JOIN   PROJ.TBL_APPROVAL_LEVEL       lv ON lv.PolicyId = t.PolicyId AND lv.IsActive = 1
    LEFT JOIN PROJ.TBL_ROLES             r  ON r.RoleId = lv.ApproverId AND lv.ApproverType = 'Role'
    LEFT JOIN PROJ.TBL_USERS             u  ON u.UserId = lv.ApproverId AND lv.ApproverType = 'User'
    WHERE  t.TransactionId = @TransactionId
    ORDER BY lv.LevelNo;

    -- Audit log
    SELECT
        l.LogId,
        l.LevelNo,
        lv.LevelName,
        l.Action,
        l.ActionBy,
        l.ActionByName,
        l.ActionDate,
        l.Remarks,
        l.IsDelegated,
        l.DelegatedFromName,
        l.IsTimedOut
    FROM   PROJ.TBL_APPROVAL_LOG      l
    LEFT JOIN PROJ.TBL_APPROVAL_LEVEL lv ON lv.LevelId = l.LevelId
    WHERE  l.TransactionId = @TransactionId
    ORDER BY l.LogId;
END;
GO

