IF OBJECT_ID(N'[proj].[sp_GetApprovalPolicies]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetApprovalPolicies];
GO

CREATE   PROCEDURE PROJ.sp_GetApprovalPolicies
    @ModuleCode NVARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        p.PolicyId, p.ModuleId, m.ModuleCode, m.ModuleName,
        p.PolicyName, p.Description, p.AmountFrom, p.AmountTo,
        p.TotalLevels, p.IsSequential, p.IsActive, p.SortOrder,
        p.CreatedBy, p.CreatedDate
    FROM   PROJ.TBL_APPROVAL_POLICY p
    JOIN   PROJ.TBL_APPROVAL_MODULE m ON m.ModuleId = p.ModuleId
    WHERE  (@ModuleCode IS NULL OR m.ModuleCode = @ModuleCode)
    ORDER BY m.ModuleCode, p.SortOrder, p.PolicyId;

    SELECT
        lv.LevelId, lv.PolicyId, lv.LevelNo, lv.LevelName,
        lv.ApproverType, lv.ApproverId,
        CASE UPPER(lv.ApproverType)
            WHEN 'ANY'  THEN 'Anyone'
            WHEN 'ROLE' THEN r.RoleName
            WHEN 'USER' THEN u.FullName
            ELSE NULL
        END AS ApproverName,
        lv.IsMandatory, lv.AllowSelfApproval, lv.TimeoutHours, lv.OnTimeoutAction, lv.IsActive
    FROM   PROJ.TBL_APPROVAL_POLICY p
    JOIN   PROJ.TBL_APPROVAL_MODULE m  ON m.ModuleId = p.ModuleId
    JOIN   PROJ.TBL_APPROVAL_LEVEL  lv ON lv.PolicyId = p.PolicyId
    LEFT JOIN PROJ.TBL_ROLES        r  ON r.RoleId = lv.ApproverId AND UPPER(lv.ApproverType) = 'ROLE'
    LEFT JOIN PROJ.TBL_USERS        u  ON u.UserId = lv.ApproverId AND UPPER(lv.ApproverType) = 'USER'
    WHERE  (@ModuleCode IS NULL OR m.ModuleCode = @ModuleCode)
      AND  lv.IsActive = 1
    ORDER BY lv.PolicyId, lv.LevelNo;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetApprovalPolicy]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetApprovalPolicy];
GO


-- ============================================================
-- STORED PROCEDURES
-- ============================================================

-- ── sp_GetApprovalPolicy ─────────────────────────────────────
-- Resolves which policy applies to a document based on module + amount
-- ──────────────────────────────────────────────────────────────
CREATE PROCEDURE proj.sp_GetApprovalPolicy
    @ModuleCode     nvarchar(20),
    @Amount         decimal(18,2) = 0
AS
BEGIN
    SET NOCOUNT ON;
    SELECT TOP 1
        p.PolicyId,
        p.PolicyName,
        p.TotalLevels,
        p.IsSequential,
        m.ModuleId,
        m.ModuleCode,
        m.IsAmountBased
    FROM   proj.TBL_APPROVAL_POLICY p
    JOIN   proj.TBL_APPROVAL_MODULE m ON p.ModuleId = m.ModuleId
    WHERE  m.ModuleCode = @ModuleCode
    AND    p.IsActive   = 1
    AND    m.IsActive   = 1
    AND    (m.IsAmountBased = 0
            OR (
                (@Amount >= ISNULL(p.AmountFrom, 0))
                AND
                (@Amount < ISNULL(p.AmountTo, 999999999))
            ))
    ORDER BY p.AmountFrom ASC;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetApprovalStatus]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetApprovalStatus];
GO
CREATE PROCEDURE PROJ.sp_GetApprovalStatus
    @ModuleCode NVARCHAR(20),
    @DocumentId INT,
    @UserId     INT = 0
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @ModuleId INT;
    SELECT @ModuleId = ModuleId FROM PROJ.TBL_APPROVAL_MODULE
    WHERE ModuleCode = @ModuleCode AND IsActive = 1;

    SELECT
        t.TransactionId, t.DocumentNo, t.DocumentAmount,
        t.PolicyId, p.PolicyName,
        t.CurrentStatus, t.CurrentLevelNo, t.TotalLevels,
        t.SubmittedBy, t.SubmittedDate, t.CompletedDate,
        t.FinalAction, t.FinalActionBy, t.FinalRemarks,
        (SELECT TOP 1 LevelId FROM PROJ.TBL_APPROVAL_LEVEL al
         WHERE al.PolicyId = t.PolicyId AND al.LevelNo = t.CurrentLevelNo AND al.IsActive = 1) AS LevelId,
        STUFF((SELECT ', ' + ISNULL(al.LevelName,'')
               FROM PROJ.TBL_APPROVAL_LEVEL al
               WHERE al.PolicyId = t.PolicyId AND al.LevelNo = t.CurrentLevelNo AND al.IsActive = 1
               FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS LevelName,
        (SELECT TOP 1 al.ApproverType FROM PROJ.TBL_APPROVAL_LEVEL al
         WHERE al.PolicyId = t.PolicyId AND al.LevelNo = t.CurrentLevelNo AND al.IsActive = 1
         ORDER BY al.LevelId) AS ApproverType,
        (SELECT TOP 1 al.ApproverId FROM PROJ.TBL_APPROVAL_LEVEL al
         WHERE al.PolicyId = t.PolicyId AND al.LevelNo = t.CurrentLevelNo AND al.IsActive = 1
         ORDER BY al.LevelId) AS ApproverId,
        STUFF((SELECT ', ' + (CASE al.ApproverType WHEN 'Role' THEN r.RoleName WHEN 'User' THEN uu.FullName ELSE 'Anyone' END)
               FROM PROJ.TBL_APPROVAL_LEVEL al
               LEFT JOIN PROJ.TBL_ROLES r  ON r.RoleId  = al.ApproverId AND al.ApproverType = 'Role'
               LEFT JOIN PROJ.TBL_USERS uu ON uu.UserId = al.ApproverId AND al.ApproverType = 'User'
               WHERE al.PolicyId = t.PolicyId AND al.LevelNo = t.CurrentLevelNo AND al.IsActive = 1
               FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS ApproverName,
        STUFF((SELECT DISTINCT ', ' + cu.FullName
               FROM PROJ.TBL_APPROVAL_LEVEL al
               JOIN PROJ.TBL_USER_ROLES cur ON cur.RoleId = al.ApproverId AND al.ApproverType = 'Role'
               JOIN PROJ.TBL_USERS      cu  ON cu.UserId  = cur.UserId AND cu.IsActive = 1
               WHERE al.PolicyId = t.PolicyId AND al.LevelNo = t.CurrentLevelNo AND al.IsActive = 1
               FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS ApproverUsers,
        (t.CurrentLevelNo + 1) AS NextLevelNo,
        STUFF((SELECT ', ' + ISNULL(al.LevelName,'')
               FROM PROJ.TBL_APPROVAL_LEVEL al
               WHERE al.PolicyId = t.PolicyId AND al.LevelNo = t.CurrentLevelNo + 1 AND al.IsActive = 1
               FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS NextLevelName,
        STUFF((SELECT ', ' + (CASE al.ApproverType WHEN 'Role' THEN r.RoleName WHEN 'User' THEN uu.FullName ELSE 'Anyone' END)
               FROM PROJ.TBL_APPROVAL_LEVEL al
               LEFT JOIN PROJ.TBL_ROLES r  ON r.RoleId  = al.ApproverId AND al.ApproverType = 'Role'
               LEFT JOIN PROJ.TBL_USERS uu ON uu.UserId = al.ApproverId AND al.ApproverType = 'User'
               WHERE al.PolicyId = t.PolicyId AND al.LevelNo = t.CurrentLevelNo + 1 AND al.IsActive = 1
               FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS NextApproverName,
        STUFF((SELECT DISTINCT ', ' + nu.FullName
               FROM PROJ.TBL_APPROVAL_LEVEL al
               JOIN PROJ.TBL_USER_ROLES nur ON nur.RoleId = al.ApproverId AND al.ApproverType = 'Role'
               JOIN PROJ.TBL_USERS      nu  ON nu.UserId  = nur.UserId AND nu.IsActive = 1
               WHERE al.PolicyId = t.PolicyId AND al.LevelNo = t.CurrentLevelNo + 1 AND al.IsActive = 1
               FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS NextApproverUsers,
        CASE
            WHEN t.CurrentStatus IN ('Approved','Rejected','Cancelled','SentBack') THEN 0
            WHEN EXISTS (
                SELECT 1 FROM PROJ.TBL_APPROVAL_LEVEL al
                WHERE al.PolicyId = t.PolicyId AND al.IsActive = 1
                  AND al.LevelNo >= t.CurrentLevelNo
                  AND (al.ApproverType = 'ANY'
                    OR (al.ApproverType = 'Role' AND EXISTS (SELECT 1 FROM PROJ.TBL_USER_ROLES ur2 WHERE ur2.UserId = @UserId AND ur2.RoleId = al.ApproverId))
                    OR (al.ApproverType = 'User' AND al.ApproverId = @UserId))
            ) THEN 1 ELSE 0
        END AS CanAct,
        CASE
            WHEN t.CurrentStatus IN ('Approved','Rejected','Cancelled','SentBack') THEN 0
            WHEN t.SubmittedBy = (SELECT UserName FROM PROJ.TBL_USERS WHERE UserId = @UserId) THEN 1
            WHEN EXISTS (
                SELECT 1 FROM PROJ.TBL_APPROVAL_LEVEL al
                WHERE al.PolicyId = t.PolicyId AND al.LevelNo = t.CurrentLevelNo AND al.IsActive = 1
                  AND ((al.ApproverType = 'Role' AND EXISTS (SELECT 1 FROM PROJ.TBL_USER_ROLES ur WHERE ur.UserId = @UserId AND ur.RoleId = al.ApproverId))
                    OR (al.ApproverType = 'User' AND al.ApproverId = @UserId))
            ) THEN 1 ELSE 0
        END AS CanCancel
    FROM   PROJ.TBL_APPROVAL_TRANSACTION t
    JOIN   PROJ.TBL_APPROVAL_POLICY      p ON p.PolicyId = t.PolicyId
    WHERE  t.ModuleId   = @ModuleId
      AND  t.DocumentId = @DocumentId;

    -- Audit log — newest first
    SELECT
        l.LogId, l.LevelNo, lv.LevelName,
        l.Action, l.ActionBy, l.ActionByName, l.ActionDate, l.Remarks,
        l.IsDelegated, l.DelegatedFromName, l.IsTimedOut
    FROM   PROJ.TBL_APPROVAL_LOG        l
    JOIN   PROJ.TBL_APPROVAL_TRANSACTION t  ON t.TransactionId = l.TransactionId
    LEFT JOIN PROJ.TBL_APPROVAL_LEVEL   lv  ON lv.LevelId = l.LevelId
    WHERE  t.ModuleId   = @ModuleId
      AND  t.DocumentId = @DocumentId
    ORDER BY l.ActionDate DESC, l.LogId DESC;
END;
GO

