CREATE   PROCEDURE proj.sp_GetAvailableAlertViews AS
BEGIN
    SET NOCOUNT ON;
    SELECT name AS ViewName,
        CASE name
            WHEN 'vw_AlertLowStock'           THEN 'Low Stock Alert'
            WHEN 'vw_AlertOutOfStock'         THEN 'Out of Stock Alert'
            WHEN 'vw_AlertNegativeStock'      THEN 'Negative Stock Alert'
            WHEN 'vw_AlertMinStockBreach'     THEN 'Minimum Stock Level Breach'
            WHEN 'vw_AlertOverStock'          THEN 'Overstock (Above Max Level)'
            WHEN 'vw_AlertPendingApprovals'   THEN 'Pending Approvals'
            WHEN 'vw_AlertReceivables'        THEN 'Receivables Outstanding'
            WHEN 'vw_AlertOverdueInvoices'    THEN 'Overdue Customer Invoices (Aging)'
            WHEN 'vw_AlertSupplierInvoiceDue' THEN 'Supplier Invoices Due / Overdue'
            WHEN 'vw_AlertPaymentFollowupDue' THEN 'Payment Follow-up Due'
            WHEN 'vw_AlertJobBudget'          THEN 'Job Budget Exceeded'
            ELSE name
        END AS ViewLabel
    FROM sys.views
    WHERE schema_id = SCHEMA_ID('proj') AND name LIKE 'vw_Alert%'
    ORDER BY ViewLabel;
END
GO

