-- sp_GetBomDetails: get all active detail lines for a header (lightweight, no dual result set)
CREATE   PROCEDURE proj.sp_GetBomDetails
    @BomHeaderId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        d.BomId,
        d.BomHeaderId,
        d.JobId,
        d.BomSectionId,
        s.SectionCode,
        s.SectionName,
        s.SortOrder   AS SectionSortOrder,
        d.ItemId,
        i.ItemCode,
        i.ItemName,
        d.ItemDetailId,
        d.SortOrder,
        d.BomRequestedQty,
        d.BomReceivedQty,
        d.PrCreatedQty,
        d.PoCreatedQty,
        d.UomId,
        u.UomCode,
        d.BomPrice,
        d.CurrencyId,
        d.ExchangeRate,
        d.ItemReqDate,
        d.ExpectedDelivery,
        d.BomStatus,
        d.IsCritical,
        d.IsSubstituteAllowed,
        d.Remarks,
        d.CreatedBy,
        d.CreatedDate,
        d.ModifiedBy,
        d.ModifiedDate,
        ROUND(d.BomRequestedQty * d.BomPrice * d.ExchangeRate, 4) AS LineTotal,
        ROUND(d.BomRequestedQty - d.BomReceivedQty, 4)            AS BalanceQty
    FROM proj.TBL_BOM_DETAILS d
    JOIN proj.TBL_BOM_SECTION  s  ON s.BomSectionId = d.BomSectionId
    JOIN proj.TBL_ITEM         i  ON i.ItemId        = d.ItemId
    LEFT JOIN proj.TBL_ITEM_UOM u ON u.UomId         = d.UomId
    WHERE d.BomHeaderId = @BomHeaderId
      AND d.IsActive    = 1
    ORDER BY s.SortOrder, d.SortOrder, d.BomId;
END
GO

