GO

CREATE PROCEDURE proj.sp_GetBomWithDetails
    @BomHeaderId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        h.BomHeaderId, h.JobId, h.JobTypeId, h.BomDate, h.BomDescription,
        h.BomVersion, h.BomStatus, h.TotalBomValue, h.BomApprovedBy, h.BomApprovedDate,
        h.IsActive, h.CreatedBy, h.CreatedDate, h.ModifiedBy, h.ModifiedDate,
        j.JobDescription, j.ProjectName, j.JobTypeId AS JobJobTypeId,
        c.CustomerName, jt.JobTypeName,
        ISNULL(jt.IsBudgetHeaderLinked, 0) AS IsBudgetHeaderLinked,
        ISNULL(jt.IsCostingRequired, 1)    AS IsCostingRequired
    FROM proj.TBL_BOM_HEADER h
    LEFT JOIN proj.TBL_JOB      j  ON j.JobId      = h.JobId
    LEFT JOIN proj.TBL_CUSTOMER c  ON c.CustomerId = j.CustomerId
    LEFT JOIN proj.TBL_JOBTYPE  jt ON jt.JobTypeId = j.JobTypeId
    WHERE h.BomHeaderId = @BomHeaderId AND h.IsActive = 1;

    SELECT
        d.BomId, d.BomHeaderId, d.JobId, d.BomSectionId,
        s.SectionCode, s.SectionName, s.SortOrder AS SectionSortOrder,
        d.ItemId, i.ItemCode, i.ItemName, d.ItemDetailId, d.SortOrder,
        d.BomRequestedQty, d.BomReceivedQty, d.PrCreatedQty, d.PoCreatedQty,
        u.UomCode, d.UomId, d.BomPrice, d.CurrencyId, d.ExchangeRate,
        d.ItemReqDate, d.ExpectedDelivery, d.BomStatus, d.IsCritical, d.IsSubstituteAllowed,
        d.Remarks, d.IsActive, d.CreatedBy, d.CreatedDate, d.ModifiedBy, d.ModifiedDate,
        ROUND(d.BomRequestedQty * d.BomPrice * d.ExchangeRate, 4) AS LineTotal,
        ROUND(d.BomRequestedQty - d.BomReceivedQty, 4)            AS BalanceQty
    FROM proj.TBL_BOM_DETAILS d
    JOIN proj.TBL_BOM_SECTION s  ON s.BomSectionId = d.BomSectionId
    JOIN proj.TBL_ITEM        i  ON i.ItemId        = d.ItemId
    LEFT JOIN proj.TBL_ITEM_UOM u ON u.UomId        = d.UomId
    WHERE d.BomHeaderId = @BomHeaderId AND d.IsActive = 1
    ORDER BY s.SortOrder, d.SortOrder, d.BomId;
END
GO

