IF OBJECT_ID(N'[proj].[sp_GetCreditNote]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetCreditNote];
GO

CREATE PROCEDURE proj.sp_GetCreditNote
    @CnId INT
AS
BEGIN
    SET NOCOUNT ON;

    -- RS1: Header
    SELECT cn.CnId, cn.CnNumber, cn.CnDate, cn.CustomerId, c.CustomerName, c.CustomerCode,
           cn.CurrencyId, cur.ShortName AS CurrencyShort,
           cn.ExchangeRate, cn.CreditAmount, cn.AllocatedAmount,
           (cn.CreditAmount - cn.AllocatedAmount) AS UnallocatedAmount,
           cn.CreditType, cn.Reason, cn.Notes, cn.Status,
           cn.ReviseReason, cn.RevisedBy, cn.RevisedDate,
           cn.CancelReason, cn.CancelledBy, cn.CancelledDate,
           cn.CreatedBy, cn.CreatedDate, cn.ModifiedBy, cn.ModifiedDate
    FROM proj.TBL_CREDIT_NOTE cn
    LEFT JOIN proj.TBL_CUSTOMER c   ON c.CustomerId   = cn.CustomerId
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = cn.CurrencyId
    WHERE cn.CnId = @CnId AND cn.IsActive = 1;

    -- RS2: Allocations — AllocatedAmount is BASE; divide by invoice rate for display
    SELECT a.AllocationId, a.CnId, a.InvoiceId, i.InvoiceNo, i.InvoiceDate, i.JobId,
           i.TotalAmount AS InvoiceTotal,
           cur2.ShortName AS CurrencyShort,
           ROUND(a.AllocatedAmount / NULLIF(i.ExchangeRate, 0), 2) AS AllocatedAmount,
           a.AllocatedAmount AS AllocatedAmountBase,
           a.Reason,
           ROUND(ISNULL(paid.PaidByOthers, 0) / NULLIF(i.ExchangeRate, 0), 2) AS PaidByOthers,
           i.TotalAmount - ROUND(ISNULL(paid.PaidByOthers, 0) / NULLIF(i.ExchangeRate, 0), 2) AS Outstanding,
           a.CreatedBy,  a.CreatedDate,
           a.ModifiedBy, a.ModifiedDate
    FROM proj.TBL_CREDIT_NOTE_ALLOCATION a
    JOIN proj.TBL_INVOICE i ON i.InvoiceId = a.InvoiceId
    LEFT JOIN proj.TBL_CURRENCY cur2 ON cur2.CurrencyId = i.CurrencyId
    OUTER APPLY (
        SELECT ISNULL(SUM(a2.AllocatedAmount), 0) AS PaidByOthers
        FROM   proj.TBL_CREDIT_NOTE_ALLOCATION a2
        JOIN   proj.TBL_CREDIT_NOTE cn2 ON cn2.CnId = a2.CnId
        WHERE  a2.InvoiceId = a.InvoiceId AND a2.IsActive = 1
          AND  cn2.Status = 'Approved' AND cn2.IsActive = 1 AND a2.CnId <> a.CnId
    ) paid
    WHERE a.CnId = @CnId AND a.IsActive = 1
    ORDER BY a.AllocationId;
END
GO

