IF OBJECT_ID(N'[proj].[sp_GetCustomerFollowupHistory]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetCustomerFollowupHistory];
GO

CREATE PROCEDURE PROJ.sp_GetCustomerFollowupHistory
    @CustomerId INT
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Today DATE = CAST(GETDATE() AS DATE);
    ;WITH InvoiceOutstanding AS (
        SELECT
            i.TotalAmount * i.ExchangeRate
                - COALESCE(rv_paid.RvPaid, 0)
                - COALESCE(cn_paid.CnPaid, 0) AS OutstandingBase,
            CASE WHEN i.DueDate IS NULL OR i.DueDate >= @Today THEN 0
                 ELSE DATEDIFF(DAY, i.DueDate, GETDATE()) END AS DaysOverdue
        FROM proj.TBL_INVOICE i
        LEFT JOIN (
            SELECT a.InvoiceId, SUM(CASE WHEN a.IsActive = 1 THEN a.AllocatedAmount ELSE 0 END) AS RvPaid
            FROM proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
            INNER JOIN proj.TBL_RECEIPT_VOUCHER rv ON a.RvId = rv.RvId
            WHERE rv.Status = 'Approved' AND rv.IsActive = 1 GROUP BY a.InvoiceId
        ) rv_paid ON i.InvoiceId = rv_paid.InvoiceId
        LEFT JOIN (
            SELECT a.InvoiceId, SUM(CASE WHEN a.IsActive = 1 THEN a.AllocatedAmount ELSE 0 END) AS CnPaid
            FROM proj.TBL_CREDIT_NOTE_ALLOCATION a
            INNER JOIN proj.TBL_CREDIT_NOTE cn ON a.CnId = cn.CnId
            WHERE cn.Status = 'Approved' AND cn.IsActive = 1 GROUP BY a.InvoiceId
        ) cn_paid ON i.InvoiceId = cn_paid.InvoiceId
        WHERE i.IsActive = 1 AND i.Status NOT IN ('Draft','Cancelled')
          AND i.CustomerId = @CustomerId
          AND (i.TotalAmount * i.ExchangeRate
                - COALESCE(rv_paid.RvPaid, 0)
                - COALESCE(cn_paid.CnPaid, 0)) > 0.005
    )
    SELECT c.CustomerId, c.CustomerName, c.CustomerCode, c.Phone, c.Mobile, c.Email, c.SalesPerson, c.CreditDays,
        ISNULL((SELECT SUM(OutstandingBase) FROM InvoiceOutstanding), 0) AS TotalPendingBase,
        ISNULL((SELECT SUM(CASE WHEN DaysOverdue > 0 THEN OutstandingBase ELSE 0 END) FROM InvoiceOutstanding), 0) AS OverdueAmountBase,
        ISNULL((SELECT MAX(DaysOverdue) FROM InvoiceOutstanding), 0) AS MaxDaysOverdue
    FROM proj.TBL_CUSTOMER c WHERE c.CustomerId = @CustomerId;

    SELECT f.FollowupId, f.CustomerId, f.ContactDate, f.ContactPerson, f.ContactMode, f.Outcome, f.Notes,
        f.PromiseAmount, f.PromiseDate, f.NextFollowupDate, f.PromiseStatus, f.OutstandingSnapshot,
        f.CreatedBy, f.CreatedDate, f.ModifiedBy, f.ModifiedDate
    FROM PROJ.TBL_PAYMENT_FOLLOWUP f
    WHERE f.CustomerId = @CustomerId AND f.IsActive = 1
    ORDER BY f.ContactDate DESC, f.FollowupId DESC;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetCustomerForInvoice]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetCustomerForInvoice];
GO

CREATE   PROCEDURE PROJ.sp_GetCustomerForInvoice
    @CustomerId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT c.CustomerId, c.CustomerName, c.VatNumber, c.CurrencyId,
           cu.ShortName AS CurrencyShort, cu.Symbol AS CurrencySymbol,
           c.CreditDays, c.Phone, c.Email
    FROM PROJ.TBL_CUSTOMER c
    INNER JOIN PROJ.TBL_CURRENCY cu ON cu.CurrencyId = c.CurrencyId
    WHERE c.CustomerId = @CustomerId AND c.IsActive = 1;

    SELECT
        a.CustomerAddressId, a.AddressType, a.IsDefault,
        RTRIM(
            ISNULL(a.AddressLine1 + CHAR(10), '') +
            ISNULL(a.AddressLine2 + CHAR(10), '') +
            ISNULL(a.City         + CHAR(10), '') +
            ISNULL(a.State + CASE WHEN a.PostalCode IS NOT NULL THEN ' ' + a.PostalCode ELSE '' END + CHAR(10), '') +
            ISNULL((SELECT cn.CountryName FROM PROJ.TBL_COUNTRY cn WHERE cn.CountryId = a.CountryId), '')
        ) AS FullAddress
    FROM PROJ.TBL_CUSTOMER_ADDRESS a
    WHERE a.CustomerId = @CustomerId AND a.IsActive = 1
    ORDER BY a.IsDefault DESC, a.CustomerAddressId;

    SELECT CustomerContactId, ContactName, Designation, Phone, Mobile, Email, IsPrimary
    FROM PROJ.TBL_CUSTOMER_CONTACT
    WHERE CustomerId = @CustomerId AND IsActive = 1
    ORDER BY IsPrimary DESC, ContactName;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetCustomerInvoiceReceivables]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetCustomerInvoiceReceivables];
GO

CREATE PROCEDURE proj.sp_GetCustomerInvoiceReceivables
    @CustomerId    INT           = NULL,
    @InvoiceNo     NVARCHAR(50)  = NULL,
    @JobId         NVARCHAR(50)  = NULL,
    @CurrencyId    INT           = NULL,
    @Status        NVARCHAR(50)  = NULL,
    @DateFrom      DATE          = NULL,
    @DateTo        DATE          = NULL,
    @DueDateFrom   DATE          = NULL,
    @DueDateTo     DATE          = NULL,
    @PageNumber    INT           = 1,
    @PageSize      INT           = 50,
    @SortColumn    NVARCHAR(50)  = 'InvoiceDate',
    @SortDirection NVARCHAR(4)   = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH InvData AS (
        SELECT
            i.InvoiceId, i.InvoiceNo, i.InvoiceDate, i.DueDate, i.CustomerId,
            cur.ShortName AS CurrencyShort, i.ExchangeRate,
            i.TotalAmount AS InvoiceAmount,
            i.TotalAmount * i.ExchangeRate AS InvoiceAmountBase,
            -- AllocatedAmount is now base; convert back to invoice currency for display
            ROUND((COALESCE(rv.RvPaid,0) + COALESCE(cn.CnPaid,0)) / NULLIF(i.ExchangeRate,0), 2) AS ReceivedAmount,
            i.TotalAmount
                - ROUND((COALESCE(rv.RvPaid,0) + COALESCE(cn.CnPaid,0)) / NULLIF(i.ExchangeRate,0), 2) AS PendingAmount,
            i.TotalAmount * i.ExchangeRate
                - COALESCE(rv.RvPaid,0) - COALESCE(cn.CnPaid,0)                                   AS PendingAmountBase,
            CASE WHEN COALESCE(rv.RvPaid,0)+COALESCE(cn.CnPaid,0)=0 THEN 'Unpaid' ELSE 'PartiallyPaid' END AS PaymentStatus,
            i.JobId,
            CASE WHEN i.DueDate IS NULL OR i.DueDate >= CAST(GETDATE() AS DATE) THEN 0
                 ELSE DATEDIFF(DAY, i.DueDate, GETDATE()) END AS DaysOverdue
        FROM proj.TBL_INVOICE i
        LEFT JOIN proj.TBL_CURRENCY cur ON i.CurrencyId = cur.CurrencyId
        LEFT JOIN (
            SELECT a.InvoiceId, SUM(CASE WHEN a.IsActive=1 THEN a.AllocatedAmount ELSE 0 END) AS RvPaid
            FROM proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
            INNER JOIN proj.TBL_RECEIPT_VOUCHER rv ON a.RvId = rv.RvId
            WHERE rv.Status = 'Approved' AND rv.IsActive = 1
            GROUP BY a.InvoiceId
        ) rv ON i.InvoiceId = rv.InvoiceId
        LEFT JOIN (
            SELECT a.InvoiceId, SUM(CASE WHEN a.IsActive=1 THEN a.AllocatedAmount ELSE 0 END) AS CnPaid
            FROM proj.TBL_CREDIT_NOTE_ALLOCATION a
            INNER JOIN proj.TBL_CREDIT_NOTE cn ON a.CnId = cn.CnId
            WHERE cn.Status = 'Approved' AND cn.IsActive = 1
            GROUP BY a.InvoiceId
        ) cn ON i.InvoiceId = cn.InvoiceId
        WHERE i.IsActive = 1
          AND i.Status NOT IN ('Draft','Cancelled')
          AND (@CustomerId  IS NULL OR i.CustomerId  = @CustomerId)
          AND (@InvoiceNo   IS NULL OR i.InvoiceNo   LIKE '%'+@InvoiceNo+'%')
          AND (@JobId       IS NULL OR i.JobId       LIKE '%'+@JobId+'%')
          AND (@CurrencyId  IS NULL OR i.CurrencyId  = @CurrencyId)
          AND (@DateFrom    IS NULL OR i.InvoiceDate >= @DateFrom)
          AND (@DateTo      IS NULL OR i.InvoiceDate <= @DateTo)
          AND (@DueDateFrom IS NULL OR i.DueDate     >= @DueDateFrom)
          AND (@DueDateTo   IS NULL OR i.DueDate     <= @DueDateTo)
    ),
    Filtered AS (
        SELECT *, COUNT(*) OVER () AS TotalRows
        FROM InvData
        WHERE PendingAmountBase > 0
          AND (@Status IS NULL OR @Status='' OR PaymentStatus=@Status)
    )
    SELECT * FROM Filtered
    ORDER BY
        CASE WHEN @SortDirection='ASC'  THEN CASE @SortColumn WHEN 'InvoiceNo' THEN InvoiceNo WHEN 'PaymentStatus' THEN PaymentStatus ELSE NULL END END ASC,
        CASE WHEN @SortDirection='ASC'  THEN CASE @SortColumn
            WHEN 'InvoiceDate'       THEN CAST(CAST(InvoiceDate AS DATETIME) AS FLOAT)
            WHEN 'DueDate'           THEN CAST(CAST(COALESCE(DueDate,'9999-12-31') AS DATETIME) AS FLOAT)
            WHEN 'PendingAmount'     THEN CAST(PendingAmount AS FLOAT)
            WHEN 'PendingAmountBase' THEN CAST(PendingAmountBase AS FLOAT)
            WHEN 'DaysOverdue'       THEN CAST(DaysOverdue AS FLOAT)
            ELSE CAST(CAST(InvoiceDate AS DATETIME) AS FLOAT) END END ASC,
        CASE WHEN @SortDirection='DESC' THEN CASE @SortColumn WHEN 'InvoiceNo' THEN InvoiceNo WHEN 'PaymentStatus' THEN PaymentStatus ELSE NULL END END DESC,
        CASE WHEN @SortDirection='DESC' THEN CASE @SortColumn
            WHEN 'InvoiceDate'       THEN CAST(CAST(InvoiceDate AS DATETIME) AS FLOAT)
            WHEN 'DueDate'           THEN CAST(CAST(COALESCE(DueDate,'9999-12-31') AS DATETIME) AS FLOAT)
            WHEN 'PendingAmount'     THEN CAST(PendingAmount AS FLOAT)
            WHEN 'PendingAmountBase' THEN CAST(PendingAmountBase AS FLOAT)
            WHEN 'DaysOverdue'       THEN CAST(DaysOverdue AS FLOAT)
            ELSE CAST(CAST(InvoiceDate AS DATETIME) AS FLOAT) END END DESC
    OFFSET (@PageNumber-1)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetCustomerList]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetCustomerList];
GO

CREATE   PROCEDURE [PROJ].[sp_GetCustomerList]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        C.*,
        CR.CurrencyName,
        PT.TermName AS PaymentTermName,

        -- ── Credit Flag (computed) ─────────────────────────────────
        -- BLACK  : Manual hold — always overrides everything
        -- RED    : Future — overdue invoices (placeholder for Phase 2)
        -- YELLOW : Future — approaching credit limit  (placeholder)
        -- GREEN  : Good standing
        CASE
            WHEN C.CreditHold = 1                          THEN 'BLACK'
            -- Phase 2: add invoice/payment checks here
            -- WHEN overdue > 30 days                      THEN 'RED'
            -- WHEN outstanding > CreditLimit * 0.8        THEN 'YELLOW'
            ELSE                                                'GREEN'
        END AS CreditFlag,

        -- Human-readable label for the flag
        CASE
            WHEN C.CreditHold = 1 THEN 'Credit Hold'
            ELSE                       'Good Standing'
        END AS CreditFlagLabel

    FROM PROJ.TBL_CUSTOMER C
    LEFT JOIN PROJ.TBL_CURRENCY     CR ON C.CurrencyId      = CR.CurrencyId
    LEFT JOIN PROJ.TBL_PAYMENT_TERMS PT ON C.PaymentTermsId = PT.PaymentTermsId
    ORDER BY C.CustomerName ASC;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetCustomerOpenInvoices]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetCustomerOpenInvoices];
GO
CREATE PROCEDURE proj.sp_GetCustomerOpenInvoices
    @CustomerId INT,
    @RvId       INT = 0
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        i.InvoiceId, i.InvoiceNo, i.InvoiceDate, i.DueDate, i.JobId,
        i.CurrencyId, cur.ShortName AS CurrencyShort,
        i.ExchangeRate AS InvoiceExchangeRate,
        i.TotalAmount,
        ROUND(ISNULL(paid.PaidByOthers, 0) / NULLIF(i.ExchangeRate, 0), 2)                        AS PaidAmount,
        i.TotalAmount - ROUND(ISNULL(paid.PaidByOthers, 0) / NULLIF(i.ExchangeRate, 0), 2)        AS Outstanding,
        ROUND(ISNULL(thisrv.ThisRvAllocated, 0) / NULLIF(i.ExchangeRate, 0), 2)                   AS ThisRvAllocated,
        ROUND(ISNULL(paid.CnPaidBase, 0) / NULLIF(i.ExchangeRate, 0), 2)                          AS CnPaid
    FROM proj.TBL_INVOICE i
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = i.CurrencyId
    OUTER APPLY (
        SELECT ISNULL(rv_paid.Amt, 0) + ISNULL(cn_paid.Amt, 0) AS PaidByOthers,
               ISNULL(cn_paid.Amt, 0)                           AS CnPaidBase
        FROM (VALUES(1)) x(d)
        OUTER APPLY (
            SELECT ISNULL(SUM(a.AllocatedAmount), 0) AS Amt
            FROM   proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
            JOIN   proj.TBL_RECEIPT_VOUCHER rv ON rv.RvId = a.RvId
            WHERE  a.InvoiceId = i.InvoiceId AND a.IsActive = 1
              AND  rv.IsActive = 1 AND rv.Status = 'Approved' AND rv.RvId <> @RvId
        ) rv_paid
        OUTER APPLY (
            SELECT ISNULL(SUM(a.AllocatedAmount), 0) AS Amt
            FROM   proj.TBL_CREDIT_NOTE_ALLOCATION a
            JOIN   proj.TBL_CREDIT_NOTE cn ON cn.CnId = a.CnId
            WHERE  a.InvoiceId = i.InvoiceId AND a.IsActive = 1
              AND  cn.IsActive = 1 AND cn.Status = 'Approved'
        ) cn_paid
    ) paid
    OUTER APPLY (
        SELECT ISNULL(SUM(a.AllocatedAmount), 0) AS ThisRvAllocated
        FROM   proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
        WHERE  a.InvoiceId = i.InvoiceId AND a.IsActive = 1 AND a.RvId = @RvId
    ) thisrv
    WHERE i.CustomerId = @CustomerId AND i.IsActive = 1 AND i.Status = 'Confirmed'
      AND ((i.TotalAmount * i.ExchangeRate - ISNULL(paid.PaidByOthers, 0)) > 0.005
           OR ISNULL(thisrv.ThisRvAllocated, 0) > 0)
    ORDER BY i.InvoiceDate, i.InvoiceId;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetCustomerOpenInvoicesForCN]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetCustomerOpenInvoicesForCN];
