CREATE PROCEDURE proj.sp_GetCustomerOpenInvoicesForCN
    @CustomerId INT,
    @CnId       INT = 0
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        i.InvoiceId, i.InvoiceNo, i.InvoiceDate, i.DueDate, i.JobId,
        i.CurrencyId, cur.ShortName AS CurrencyShort,
        i.TotalAmount,
        ROUND(ISNULL(paid.PaidByOthers, 0) / NULLIF(i.ExchangeRate, 0), 2)                         AS PaidAmount,
        i.TotalAmount - ROUND(ISNULL(paid.PaidByOthers, 0) / NULLIF(i.ExchangeRate, 0), 2)         AS Outstanding,
        ROUND(ISNULL(thiscn.ThisCnAllocated, 0) / NULLIF(i.ExchangeRate, 0), 2)                    AS ThisCnAllocated
    FROM proj.TBL_INVOICE i
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = i.CurrencyId
    OUTER APPLY (
        SELECT
            ISNULL(rv_paid.Amt,0) + ISNULL(cn_paid.Amt,0) AS PaidByOthers
        FROM (VALUES(1)) x(d)
        OUTER APPLY (
            SELECT ISNULL(SUM(a.AllocatedAmount), 0) AS Amt
            FROM   proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
            JOIN   proj.TBL_RECEIPT_VOUCHER rv ON rv.RvId = a.RvId
            WHERE  a.InvoiceId = i.InvoiceId AND a.IsActive = 1
              AND  rv.IsActive = 1 AND rv.Status = 'Approved'
        ) rv_paid
        OUTER APPLY (
            SELECT ISNULL(SUM(a.AllocatedAmount), 0) AS Amt
            FROM   proj.TBL_CREDIT_NOTE_ALLOCATION a
            JOIN   proj.TBL_CREDIT_NOTE cn ON cn.CnId = a.CnId
            WHERE  a.InvoiceId = i.InvoiceId AND a.IsActive = 1
              AND  cn.IsActive = 1 AND cn.Status = 'Approved' AND cn.CnId <> @CnId
        ) cn_paid
    ) paid
    OUTER APPLY (
        SELECT ISNULL(SUM(a.AllocatedAmount), 0) AS ThisCnAllocated
        FROM   proj.TBL_CREDIT_NOTE_ALLOCATION a
        WHERE  a.InvoiceId = i.InvoiceId AND a.IsActive = 1 AND a.CnId = @CnId
    ) thiscn
    WHERE i.CustomerId = @CustomerId AND i.IsActive = 1 AND i.Status = 'Confirmed'
      AND ((i.TotalAmount * i.ExchangeRate - ISNULL(paid.PaidByOthers, 0)) > 0.005
           OR ISNULL(thiscn.ThisCnAllocated, 0) > 0)
    ORDER BY i.InvoiceDate, i.InvoiceId;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetCustomerPaymentHistory]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetCustomerPaymentHistory];
GO

CREATE PROCEDURE proj.sp_GetCustomerPaymentHistory
    @CustomerId INT
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH InvoiceTotals AS (
        SELECT
            i.InvoiceId,
            i.TotalAmount * i.ExchangeRate                                      AS InvoiceBase,
            COALESCE(rv.RvPaid,0) + COALESCE(cn.CnPaid,0)                      AS PaidBase,
            i.TotalAmount * i.ExchangeRate
                - COALESCE(rv.RvPaid,0) - COALESCE(cn.CnPaid,0)                AS OutstandingBase,
            CASE WHEN i.DueDate IS NULL OR i.DueDate >= CAST(GETDATE() AS DATE) THEN 0
                 ELSE DATEDIFF(DAY, i.DueDate, GETDATE()) END AS DaysOverdue
        FROM proj.TBL_INVOICE i
        LEFT JOIN (
            SELECT a.InvoiceId, SUM(CASE WHEN a.IsActive=1 THEN a.AllocatedAmount ELSE 0 END) AS RvPaid
            FROM proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
            INNER JOIN proj.TBL_RECEIPT_VOUCHER rv ON a.RvId = rv.RvId
            WHERE rv.Status = 'Approved' AND rv.IsActive = 1
            GROUP BY a.InvoiceId
        ) rv ON i.InvoiceId = rv.InvoiceId
        LEFT JOIN (
            SELECT a.InvoiceId, SUM(CASE WHEN a.IsActive=1 THEN a.AllocatedAmount ELSE 0 END) AS CnPaid
            FROM proj.TBL_CREDIT_NOTE_ALLOCATION a
            INNER JOIN proj.TBL_CREDIT_NOTE cn ON a.CnId = cn.CnId
            WHERE cn.Status = 'Approved' AND cn.IsActive = 1
            GROUP BY a.InvoiceId
        ) cn ON i.InvoiceId = cn.InvoiceId
        WHERE i.IsActive = 1
          AND i.Status NOT IN ('Draft','Cancelled')
          AND i.CustomerId = @CustomerId
    )
    -- RS1: Summary
    SELECT
        ISNULL(SUM(InvoiceBase),     0) AS InvoicesRaised,
        ISNULL(SUM(PaidBase),        0) AS ReceiptsReceived,
        ISNULL(SUM(OutstandingBase), 0) AS OutstandingBalance,
        ISNULL(SUM(CASE WHEN DaysOverdue>0 THEN OutstandingBase ELSE 0 END),0) AS OverdueAmount
    FROM InvoiceTotals;

    -- RS2: Receipt voucher history (header amounts are in RV currency — unchanged)
    SELECT
        rv.RvNumber, rv.RvDate,
        cur.ShortName AS CurrencyShort,
        rv.ExchangeRate,
        rv.AmountReceived,
        rv.AmountReceived  * rv.ExchangeRate AS AmountBase,
        rv.AllocatedAmount,
        rv.AllocatedAmount * rv.ExchangeRate AS AllocatedBase,
        rv.Status, rv.PaymentMode, rv.CreatedBy, rv.CreatedDate
    FROM proj.TBL_RECEIPT_VOUCHER rv
    LEFT JOIN proj.TBL_CURRENCY cur ON rv.CurrencyId = cur.CurrencyId
    WHERE rv.CustomerId = @CustomerId
      AND rv.Status NOT IN ('Cancelled')
    ORDER BY rv.RvDate DESC;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetCustomerReceivables]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetCustomerReceivables];
GO

CREATE PROCEDURE proj.sp_GetCustomerReceivables
    @SearchText    NVARCHAR(200) = NULL,
    @CustomerId    INT           = NULL,
    @CurrencyId    INT           = NULL,
    @Status        NVARCHAR(50)  = NULL,
    @DateFrom      DATE          = NULL,
    @DateTo        DATE          = NULL,
    @PageNumber    INT           = 1,
    @PageSize      INT           = 20,
    @SortColumn    NVARCHAR(50)  = 'TotalPendingBase',
    @SortDirection NVARCHAR(4)   = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH InvoiceOutstanding AS (
        SELECT
            i.InvoiceId, i.CustomerId, i.CurrencyId,
            cur.ShortName                                                   AS CurrencyShort,
            i.TotalAmount,
            i.ExchangeRate,
            COALESCE(rv.RvPaid,0) + COALESCE(cn.CnPaid,0)                 AS TotalPaidBase,
            i.TotalAmount * i.ExchangeRate                                  AS InvoiceAmountBase,
            i.TotalAmount * i.ExchangeRate
                - COALESCE(rv.RvPaid,0) - COALESCE(cn.CnPaid,0)           AS OutstandingBase,
            CASE WHEN i.DueDate IS NULL OR i.DueDate >= CAST(GETDATE() AS DATE) THEN 0 ELSE 1 END AS IsOverdue
        FROM proj.TBL_INVOICE i
        LEFT JOIN proj.TBL_CURRENCY cur ON i.CurrencyId = cur.CurrencyId
        LEFT JOIN (
            SELECT a.InvoiceId, SUM(CASE WHEN a.IsActive=1 THEN a.AllocatedAmount ELSE 0 END) AS RvPaid
            FROM proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
            INNER JOIN proj.TBL_RECEIPT_VOUCHER rv ON a.RvId = rv.RvId
            WHERE rv.Status = 'Approved' AND rv.IsActive = 1
            GROUP BY a.InvoiceId
        ) rv ON i.InvoiceId = rv.InvoiceId
        LEFT JOIN (
            SELECT a.InvoiceId, SUM(CASE WHEN a.IsActive=1 THEN a.AllocatedAmount ELSE 0 END) AS CnPaid
            FROM proj.TBL_CREDIT_NOTE_ALLOCATION a
            INNER JOIN proj.TBL_CREDIT_NOTE cn ON a.CnId = cn.CnId
            WHERE cn.Status = 'Approved' AND cn.IsActive = 1
            GROUP BY a.InvoiceId
        ) cn ON i.InvoiceId = cn.InvoiceId
        WHERE i.IsActive = 1
          AND i.Status NOT IN ('Draft','Cancelled')
          AND (@CurrencyId IS NULL OR i.CurrencyId = @CurrencyId)
          AND (@DateFrom   IS NULL OR i.InvoiceDate >= @DateFrom)
          AND (@DateTo     IS NULL OR i.InvoiceDate <= @DateTo)
    ),
    CustomerSummary AS (
        SELECT
            c.CustomerId, c.CustomerName, c.CustomerCode,
            COUNT(io.InvoiceId)  AS TotalInvoiceCount,
            SUM(CASE WHEN io.TotalPaidBase = 0 THEN 1 ELSE 0 END) AS UnpaidCount,
            SUM(CASE WHEN io.TotalPaidBase > 0 AND io.TotalPaidBase < io.InvoiceAmountBase THEN 1 ELSE 0 END) AS PartiallyPaidCount,
            ISNULL(SUM(io.TotalAmount), 0)                                               AS TotalInvoiceAmount,
            ISNULL(SUM(io.TotalPaidBase / NULLIF(io.ExchangeRate, 0)), 0)               AS TotalReceivedAmount,
            CASE WHEN COUNT(DISTINCT io.CurrencyId) = 1 THEN MAX(io.CurrencyShort) ELSE 'Multi' END AS InvoiceCurrencyShort,
            ISNULL(SUM(io.InvoiceAmountBase), 0)                                         AS TotalInvoiceAmountBase,
            ISNULL(SUM(io.TotalPaidBase), 0)                                             AS TotalReceivedAmountBase,
            ISNULL(SUM(io.OutstandingBase), 0)                                           AS TotalPendingBase,
            ISNULL(SUM(CASE WHEN io.IsOverdue=1 THEN io.OutstandingBase ELSE 0 END), 0) AS OverdueAmountBase
        FROM InvoiceOutstanding io
        INNER JOIN proj.TBL_CUSTOMER c ON io.CustomerId = c.CustomerId
        WHERE io.OutstandingBase > 0
          AND (@CustomerId IS NULL OR io.CustomerId = @CustomerId)
          AND (@SearchText IS NULL
               OR c.CustomerName LIKE '%'+@SearchText+'%'
               OR c.CustomerCode LIKE '%'+@SearchText+'%')
        GROUP BY c.CustomerId, c.CustomerName, c.CustomerCode
        HAVING ISNULL(SUM(io.OutstandingBase),0) > 0
           AND (@Status IS NULL OR @Status = ''
                OR (@Status='Unpaid'        AND SUM(CASE WHEN io.TotalPaidBase=0 THEN 1 ELSE 0 END)>0)
                OR (@Status='PartiallyPaid' AND SUM(CASE WHEN io.TotalPaidBase>0 AND io.TotalPaidBase<io.InvoiceAmountBase THEN 1 ELSE 0 END)>0))
    ),
    Filtered AS (SELECT *, COUNT(*) OVER () AS TotalRows FROM CustomerSummary)
    SELECT * FROM Filtered
    ORDER BY
        CASE WHEN @SortDirection='ASC'  THEN CASE @SortColumn WHEN 'CustomerName' THEN CustomerName ELSE NULL END END ASC,
        CASE WHEN @SortDirection='ASC'  THEN CASE @SortColumn
            WHEN 'TotalPendingBase'        THEN TotalPendingBase
            WHEN 'TotalInvoiceAmountBase'  THEN TotalInvoiceAmountBase
            WHEN 'TotalReceivedAmountBase' THEN TotalReceivedAmountBase
            WHEN 'TotalInvoiceCount'       THEN CAST(TotalInvoiceCount AS DECIMAL(18,2))
            WHEN 'OverdueAmountBase'       THEN OverdueAmountBase
            ELSE TotalPendingBase END END ASC,
        CASE WHEN @SortDirection='DESC' THEN CASE @SortColumn WHEN 'CustomerName' THEN CustomerName ELSE NULL END END DESC,
        CASE WHEN @SortDirection='DESC' THEN CASE @SortColumn
            WHEN 'TotalPendingBase'        THEN TotalPendingBase
            WHEN 'TotalInvoiceAmountBase'  THEN TotalInvoiceAmountBase
            WHEN 'TotalReceivedAmountBase' THEN TotalReceivedAmountBase
            WHEN 'TotalInvoiceCount'       THEN CAST(TotalInvoiceCount AS DECIMAL(18,2))
            WHEN 'OverdueAmountBase'       THEN OverdueAmountBase
            ELSE TotalPendingBase END END DESC
    OFFSET (@PageNumber-1)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetCustomersPaged]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetCustomersPaged];
GO
CREATE PROCEDURE [PROJ].[sp_GetCustomersPaged]
    @SearchTerm NVARCHAR(100) = '',
    @PageNumber INT = 1,
    @PageSize INT = 10
AS
BEGIN
    SET NOCOUNT ON;

    -- 1. Get Count
    DECLARE @TotalCount INT;
    SELECT @TotalCount = COUNT(*) FROM TBL_CUSTOMER 
    WHERE (CustomerName LIKE '%' + @SearchTerm + '%' OR CustomerCode LIKE '%' + @SearchTerm + '%');

    -- 2. Get Data as a Simple Pipe/Comma String
    DECLARE @DataString NVARCHAR(MAX);
    
    -- We build a custom string: Code,Name;Code,Name;
    SELECT @DataString = COALESCE(@DataString + ';', '') + 
           (CustomerCode + ',' + CustomerName + ',' + ISNULL(Email,'') + ',' + ISNULL(Mobile,''))
    FROM (
        SELECT CustomerCode, CustomerName, Email, Mobile
        FROM TBL_CUSTOMER
        WHERE (CustomerName LIKE '%' + @SearchTerm + '%' OR CustomerCode LIKE '%' + @SearchTerm + '%')
        ORDER BY CustomerId
        OFFSET (@PageNumber - 1) * @PageSize ROWS
        FETCH NEXT @PageSize ROWS ONLY
    ) AS PagedData;

    -- 3. Return: TotalCount|Code,Name,Email,Mobile;Code,Name,Email,Mobile
    SELECT CAST(@TotalCount AS VARCHAR(10)) + '|' + ISNULL(@DataString, '')
END
GO

IF OBJECT_ID(N'[proj].[sp_GetCustomersPagedCustom]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetCustomersPagedCustom];
GO
CREATE PROCEDURE [PROJ].[sp_GetCustomersPagedCustom]
 @SearchTerm NVARCHAR(100) = '',
    @PageNumber INT = 1,
    @PageSize INT = 10,
    @SortColumn NVARCHAR(50) = 'CustomerName',
    @SortOrder NVARCHAR(10) = 'ASC'
AS
BEGIN
    SET NOCOUNT ON;

    -- 1. Get Total Count
    DECLARE @TotalCount INT;
    SELECT @TotalCount = COUNT(*) FROM TBL_CUSTOMER 
    WHERE (CustomerName LIKE '%' + @SearchTerm + '%' OR CustomerCode LIKE '%' + @SearchTerm + '%');

    -- 2. Build the Data String (Pipe/Semicolon format)
    DECLARE @DataString NVARCHAR(MAX);
    
    -- We build the string inside the SELECT using the sorted PagedData
    SELECT @DataString = COALESCE(@DataString + ';', '') + 
           (CustomerCode + ',' + CustomerName + ',' + ISNULL(Email,'') + ',' + ISNULL(Mobile,''))
    FROM (
        SELECT CustomerCode, CustomerName, Email, Mobile
        FROM TBL_CUSTOMER
        WHERE (CustomerName LIKE '%' + @SearchTerm + '%' OR CustomerCode LIKE '%' + @SearchTerm + '%')
        ORDER BY 
            CASE WHEN @SortOrder = 'ASC' THEN
                CASE 
                    WHEN @SortColumn = 'CustomerCode' THEN CustomerCode
                    WHEN @SortColumn = 'CustomerName' THEN CustomerName
                    ELSE CustomerName 
                END
            END ASC,
            CASE WHEN @SortOrder = 'DESC' THEN
                CASE 
                    WHEN @SortColumn = 'CustomerCode' THEN CustomerCode
                    WHEN @SortColumn = 'CustomerName' THEN CustomerName
                    ELSE CustomerName 
                END
            END DESC
        OFFSET (@PageNumber - 1) * @PageSize ROWS
        FETCH NEXT @PageSize ROWS ONLY
    ) AS PagedData;

    -- 3. Return: TotalCount|Code,Name,Email,Mobile;Code,Name,Email,Mobile
    SELECT CAST(@TotalCount AS VARCHAR(10)) + '|' + ISNULL(@DataString, '')
END
GO

IF OBJECT_ID(N'[proj].[sp_GetDashboard]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetDashboard];
GO
CREATE   PROCEDURE proj.sp_GetDashboard
    @UserId INT
AS
BEGIN
    SET NOCOUNT ON;

    -- ── 1. Top KPIs ──────────────────────────────────────────────────────────
    SELECT
        (SELECT COUNT(*) FROM proj.TBL_JOB WHERE JobStatusId=1)                                                          AS ActiveJobs,
        (SELECT COUNT(*) FROM proj.TBL_PURCHASE_REQUEST  WHERE IsActive=1 AND Status NOT IN ('Cancelled','Rejected'))     AS OpenPRs,
        (SELECT COUNT(*) FROM proj.TBL_PURCHASE_ORDER    WHERE IsActive=1 AND Status NOT IN ('Cancelled','Received','Completed')) AS OpenPOs,
        -- Count only transactions the current user can actually action (matches myApprovals logic)
        (SELECT COUNT(*)
         FROM proj.TBL_APPROVAL_TRANSACTION t
         WHERE t.CurrentStatus = 'Pending'
           AND t.CurrentLevelNo <= t.TotalLevels
           AND EXISTS (
               SELECT 1 FROM proj.TBL_APPROVAL_LEVEL al
               WHERE al.PolicyId = t.PolicyId AND al.LevelNo = t.CurrentLevelNo AND al.IsActive = 1
                 AND (
                       al.ApproverType = 'ANY'
                    OR (al.ApproverType = 'User' AND al.ApproverId = @UserId)
                    OR (al.ApproverType = 'Role' AND EXISTS (
                           SELECT 1 FROM proj.TBL_USER_ROLES ur
                           WHERE ur.UserId = @UserId AND ur.RoleId = al.ApproverId))
                 )
           )
        )                                                                                                                  AS PendingApprovals,
        (SELECT COUNT(*) FROM proj.TBL_INVOICE           WHERE IsActive=1 AND Status='Confirmed')                         AS OpenInvoices;

    -- ── 2. Job Summary ───────────────────────────────────────────────────────
    SELECT
        SUM(CASE WHEN JobStatusId=1 THEN 1 ELSE 0 END) AS ActiveJobs,
        SUM(CASE WHEN JobStatusId=4 THEN 1 ELSE 0 END) AS CompletedJobs,
        SUM(CASE WHEN JobStatusId=5 THEN 1 ELSE 0 END) AS CancelledJobs,
        SUM(CASE WHEN JobStatusId=2 THEN 1 ELSE 0 END) AS WaitingJobs,
        SUM(CASE WHEN JobStatusId=3 THEN 1 ELSE 0 END) AS FreezedJobs
    FROM proj.TBL_JOB;

    -- ── 3. My Pending Approvals ──────────────────────────────────────────────
    SELECT TOP 6
        t.TransactionId, m.ModuleCode, t.DocumentNo,
        t.DocumentAmount, t.SubmittedDate,
        DATEDIFF(DAY, t.SubmittedDate, GETDATE()) AS DaysPending,
        t.CurrentLevelNo, t.TotalLevels, t.DocumentId
    FROM proj.TBL_APPROVAL_TRANSACTION t
    JOIN proj.TBL_APPROVAL_MODULE m ON m.ModuleId = t.ModuleId
    WHERE t.CurrentStatus = 'Pending'
      AND t.CurrentLevelNo <= t.TotalLevels
      AND EXISTS (
          SELECT 1 FROM proj.TBL_APPROVAL_LEVEL al
          WHERE al.PolicyId=t.PolicyId AND al.LevelNo=t.CurrentLevelNo AND al.IsActive=1
            AND (
                  al.ApproverType='ANY'
               OR (al.ApproverType='User' AND al.ApproverId=@UserId)
               OR (al.ApproverType='Role' AND EXISTS (
                      SELECT 1 FROM proj.TBL_USER_ROLES ur
                      WHERE ur.UserId=@UserId AND ur.RoleId=al.ApproverId))
            )
      )
    ORDER BY t.SubmittedDate;

    -- ── 4. PR Status ─────────────────────────────────────────────────────────
    SELECT
        SUM(CASE WHEN Status='Draft'           THEN 1 ELSE 0 END) AS DraftPR,
        SUM(CASE WHEN Status='PendingApproval' THEN 1 ELSE 0 END) AS PendingPR,
        SUM(CASE WHEN Status='Approved'        THEN 1 ELSE 0 END) AS ApprovedPR
    FROM proj.TBL_PURCHASE_REQUEST WHERE IsActive=1;

    -- ── 5. PO Status ─────────────────────────────────────────────────────────
    SELECT
        SUM(CASE WHEN Status='Draft'    THEN 1 ELSE 0 END) AS DraftPO,
        SUM(CASE WHEN Status='Sent'     THEN 1 ELSE 0 END) AS SentPO,
        SUM(CASE WHEN Status='Partial'  THEN 1 ELSE 0 END) AS PartialPO,
        SUM(CASE WHEN Status='Approved' THEN 1 ELSE 0 END) AS ApprovedPO
    FROM proj.TBL_PURCHASE_ORDER WHERE IsActive=1;

    -- ── 6. Inventory Status ──────────────────────────────────────────────────
    SELECT
        COUNT(*)                                                           AS TotalItems,
        SUM(CASE WHEN QtyOnHand <= 0                   THEN 1 ELSE 0 END) AS OutOfStock,
        SUM(CASE WHEN QtyOnHand > 0 AND QtyOnHand <= 5 THEN 1 ELSE 0 END) AS LowStock,
        ISNULL(SUM(QtyOnHand * AvgUnitCost), 0)                            AS StockValue,
        (SELECT COUNT(*) FROM proj.TBL_GRN_HEADER
         WHERE IsActive=1 AND Status NOT IN ('Confirmed','Cancelled'))      AS PendingGRN
    FROM proj.TBL_STOCK_BALANCE;

    -- ── 7. Financial Summary ─────────────────────────────────────────────────
    SELECT
        ISNULL((SELECT SUM(TotalAmount)    FROM proj.TBL_INVOICE           WHERE IsActive=1 AND Status IN ('Confirmed','Paid')),0) AS CustomerInvoices,
        ISNULL((SELECT SUM(TotalAmount)    FROM proj.TBL_SUPPLIER_INVOICE  WHERE IsActive=1 AND Status='Approved'),0)             AS SupplierInvoices,
        ISNULL((SELECT SUM(AmountReceived) FROM proj.TBL_RECEIPT_VOUCHER   WHERE IsActive=1 AND Status='Approved'),0)             AS Receipts,
        ISNULL((SELECT SUM(AmountPaid)     FROM proj.TBL_PAYMENT_VOUCHER   WHERE IsActive=1 AND Status='Approved'),0)             AS Payments,
        ISNULL((SELECT SUM(TotalAmount)    FROM proj.TBL_INVOICE           WHERE IsActive=1 AND Status IN ('Confirmed','Paid')),0)
          - ISNULL((SELECT SUM(AmountReceived) FROM proj.TBL_RECEIPT_VOUCHER WHERE IsActive=1 AND Status='Approved'),0)           AS Receivables,
        ISNULL((SELECT SUM(TotalAmount)    FROM proj.TBL_SUPPLIER_INVOICE  WHERE IsActive=1 AND Status='Approved'),0)
          - ISNULL((SELECT SUM(AmountPaid) FROM proj.TBL_PAYMENT_VOUCHER   WHERE IsActive=1 AND Status='Approved'),0)             AS Payables;

    -- ── 8. Job Costing Summary ───────────────────────────────────────────────
    SELECT
        ISNULL(SUM(f.OrderValue),    0)                                        AS TotalOrderValue,
        ISNULL((SELECT SUM(ActualAmount) FROM proj.VW_JOB_COST_ACTUAL), 0)     AS TotalActualCost,
        ISNULL(SUM(f.TotalInvoicing), 0)                                       AS TotalInvoiced
    FROM proj.TBL_JOB_FINANCE f
    JOIN proj.TBL_JOB j ON j.JobId = f.JobId
    WHERE j.JobStatusId IN (1,2,3);
END
GO

IF OBJECT_ID(N'[proj].[sp_GetDebitNote]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetDebitNote];
GO

CREATE PROCEDURE proj.sp_GetDebitNote
    @DnId INT
AS
BEGIN
    SET NOCOUNT ON;

    -- RS1: Header
    SELECT dn.DnId, dn.DnNumber, dn.DnDate, dn.SupplierId,
           s.SupplierName, s.SupplierCode,
           dn.CurrencyId, cur.ShortName AS CurrencyShort,
           dn.ExchangeRate, dn.DebitAmount, dn.AllocatedAmount,
           (dn.DebitAmount - dn.AllocatedAmount) AS UnallocatedAmount,
           dn.DebitType, dn.Reason, dn.Notes, dn.Status,
           dn.ReviseReason, dn.RevisedBy, dn.RevisedDate,
           dn.CancelReason, dn.CancelledBy, dn.CancelledDate,
           dn.CreatedBy, dn.CreatedDate, dn.ModifiedBy, dn.ModifiedDate
    FROM proj.TBL_DEBIT_NOTE dn
    LEFT JOIN proj.TBL_SUPPLIER s   ON s.SupplierId   = dn.SupplierId
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = dn.CurrencyId
    WHERE dn.DnId = @DnId AND dn.IsActive = 1;

    -- RS2: Allocations — AllocatedAmount is BASE; divide by invoice rate for display
    SELECT a.AllocationId, a.DnId, a.SupplierInvoiceId,
           si.InvoiceNo, si.InvoiceDate, si.SupplierInvRef,
           jobs.JobId,
           si.TotalAmount AS InvoiceTotal,
           ci.ShortName  AS InvoiceCurrencyShort,
           cdn.ShortName AS DnCurrencyShort,
           ROUND(a.AllocatedAmount / NULLIF(si.ExchangeRate,  0), 2) AS AllocatedAmount,
           ROUND(a.AllocatedAmount / NULLIF(dn_hdr.ExchangeRate, 0), 2) AS AllocatedAmountDnCcy,
           a.AllocatedAmount AS AllocatedAmountBase,
           a.Reason,
           ROUND(ISNULL(paid.PaidByOthers, 0) / NULLIF(si.ExchangeRate, 0), 2) AS PaidByOthers,
           si.TotalAmount - ROUND(ISNULL(paid.PaidByOthers, 0) / NULLIF(si.ExchangeRate, 0), 2) AS Outstanding,
           a.CreatedBy,  a.CreatedDate,
           a.ModifiedBy, a.ModifiedDate
    FROM proj.TBL_DEBIT_NOTE_ALLOCATION a
    JOIN proj.TBL_SUPPLIER_INVOICE si  ON si.SupplierInvoiceId = a.SupplierInvoiceId
    JOIN proj.TBL_DEBIT_NOTE       dn_hdr ON dn_hdr.DnId       = a.DnId
    LEFT JOIN proj.TBL_CURRENCY    ci  ON ci.CurrencyId        = si.CurrencyId
    LEFT JOIN proj.TBL_CURRENCY    cdn ON cdn.CurrencyId       = dn_hdr.CurrencyId
    OUTER APPLY (
        SELECT ISNULL(pv_paid.Amt, 0) + ISNULL(dn_paid.Amt, 0) AS PaidByOthers
        FROM (VALUES(1)) x(d)
        OUTER APPLY (
            SELECT ISNULL(SUM(a2.AllocatedAmount), 0) AS Amt
            FROM   proj.TBL_PAYMENT_VOUCHER_ALLOCATION a2
            JOIN   proj.TBL_PAYMENT_VOUCHER pv ON pv.PvId = a2.PvId
            WHERE  a2.SupplierInvoiceId = a.SupplierInvoiceId AND a2.IsActive = 1
              AND  pv.Status = 'Approved' AND pv.IsActive = 1
        ) pv_paid
        OUTER APPLY (
            SELECT ISNULL(SUM(a3.AllocatedAmount), 0) AS Amt
            FROM   proj.TBL_DEBIT_NOTE_ALLOCATION a3
            JOIN   proj.TBL_DEBIT_NOTE dn2 ON dn2.DnId = a3.DnId
            WHERE  a3.SupplierInvoiceId = a.SupplierInvoiceId AND a3.IsActive = 1
              AND  dn2.Status = 'Approved' AND dn2.IsActive = 1 AND a3.DnId <> a.DnId
        ) dn_paid
    ) paid
    OUTER APPLY (
        SELECT TOP 1 po.JobId
        FROM   proj.TBL_SUPPLIER_INVOICE_LINE sil
        JOIN   proj.TBL_PURCHASE_ORDER_LINE   pol ON pol.PoLineId = sil.PoLineId
        JOIN   proj.TBL_PURCHASE_ORDER         po  ON po.PoId     = pol.PoId
        WHERE  sil.SupplierInvoiceId = a.SupplierInvoiceId AND sil.IsActive = 1
          AND  po.JobId IS NOT NULL
    ) jobs
    WHERE a.DnId = @DnId AND a.IsActive = 1
    ORDER BY a.AllocationId;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetDelivery]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetDelivery];
