CREATE PROCEDURE proj.sp_GetDelivery
    @DeliveryId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        d.DeliveryId, d.DeliveryNo, d.DeliveryDate, d.InvoiceId, i.InvoiceNo,
        d.CustomerId, c.CustomerName,
        d.JobId, j.JobDescription, j.ProjectName AS JobTitle,
        d.DeliveryAddress, d.ContactId,
        cc.ContactName, cc.Designation AS ContactDesignation,
        cc.Phone AS ContactPhone, cc.Mobile AS ContactMobile, cc.Email AS ContactEmail,
        d.Consignee, d.ConsigneeAddress, d.ConsigneeLpoNo, d.ConsigneeLpoDate, d.ConsigneeTrn,
        d.VehicleNo, d.DeliveredBy, d.DeliveredByDate,
        d.BuyerTrnNo, d.BuyerLpoNo, d.BuyerLpoDate,
        d.Notes, d.Status, d.CreatedBy, d.CreatedDate, d.ModifiedBy, d.ModifiedDate,
        (SELECT COUNT(*) FROM proj.TBL_DOCUMENTS
         WHERE ReferenceTable = 'DN' AND ReferenceKey = CAST(d.DeliveryId AS NVARCHAR(50)) AND IsActive = 1) AS DocumentCount
    FROM proj.TBL_DELIVERY d
    INNER JOIN proj.TBL_CUSTOMER         c  ON c.CustomerId         = d.CustomerId
    LEFT  JOIN proj.TBL_INVOICE          i  ON i.InvoiceId          = d.InvoiceId
    LEFT  JOIN proj.TBL_CUSTOMER_CONTACT cc ON cc.CustomerContactId = d.ContactId
    LEFT  JOIN proj.TBL_JOB              j  ON j.JobId              = d.JobId
    WHERE d.DeliveryId = @DeliveryId AND d.IsActive = 1;

    SELECT
        l.DeliveryLineId, l.DeliveryId, l.InvoiceLineId, l.LineNum,
        l.Description, l.UomName, l.Qty, l.Remarks
    FROM proj.TBL_DELIVERY_LINE l
    WHERE l.DeliveryId = @DeliveryId AND l.IsActive = 1
    ORDER BY l.LineNum;
END
GO

