IF OBJECT_ID(N'[proj].[sp_GetFifoCost]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetFifoCost];
GO
-- 2. Create FIFO cost SP
CREATE PROCEDURE proj.sp_GetFifoCost
    @ItemId INT
AS
BEGIN
    SET NOCOUNT ON;

    -- Total qty issued out for this item
    DECLARE @TotalOut DECIMAL(18,4) = ISNULL(
        (SELECT SUM(QtyOut) FROM proj.TBL_STOCK_LEDGER
         WHERE ItemId = @ItemId AND QtyOut > 0), 0);

    -- Walk receipts oldest-first; first batch whose cumulative in exceeds total out = FIFO layer
    DECLARE @RunningIn DECIMAL(18,4) = 0;
    DECLARE @FifoCost  DECIMAL(18,4) = NULL;
    DECLARE @QtyIn     DECIMAL(18,4);
    DECLARE @UnitCost  DECIMAL(18,4);

    DECLARE cur CURSOR LOCAL FAST_FORWARD FOR
        SELECT QtyIn, UnitCost
        FROM   proj.TBL_STOCK_LEDGER
        WHERE  ItemId = @ItemId AND QtyIn > 0
        ORDER  BY TransDate ASC, LedgerId ASC;

    OPEN cur;
    FETCH NEXT FROM cur INTO @QtyIn, @UnitCost;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        SET @RunningIn = @RunningIn + @QtyIn;
        SET @FifoCost  = @UnitCost;
        IF @RunningIn > @TotalOut BREAK;
        FETCH NEXT FROM cur INTO @QtyIn, @UnitCost;
    END
    CLOSE cur; DEALLOCATE cur;

    -- Fallback: use average cost from stock balance if no ledger entries
    IF @FifoCost IS NULL
        SELECT @FifoCost = ISNULL(AvgUnitCost, 0)
        FROM   proj.TBL_STOCK_BALANCE
        WHERE  ItemId = @ItemId;

    SELECT ISNULL(@FifoCost, 0) AS FifoCost;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetFollowupWorklist]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetFollowupWorklist];
GO

CREATE PROCEDURE PROJ.sp_GetFollowupWorklist
    @SearchText     NVARCHAR(200) = NULL,
    @State          NVARCHAR(30)  = NULL,
    @ShowAll        BIT           = 0,
    @PageNumber     INT           = 1,
    @PageSize       INT           = 20,
    @SortColumn     NVARCHAR(50)  = 'Priority',
    @SortDirection  NVARCHAR(4)   = 'ASC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Today DATE = CAST(GETDATE() AS DATE);
    ;WITH InvoiceOutstanding AS (
        SELECT
            i.CustomerId,
            i.TotalAmount * i.ExchangeRate
                - COALESCE(rv_paid.RvPaid, 0) - COALESCE(cn_paid.CnPaid, 0) AS OutstandingBase,
            CASE WHEN i.DueDate IS NULL OR i.DueDate >= @Today THEN 0
                 ELSE DATEDIFF(DAY, i.DueDate, GETDATE()) END AS DaysOverdue
        FROM proj.TBL_INVOICE i
        LEFT JOIN (
            SELECT a.InvoiceId, SUM(CASE WHEN a.IsActive = 1 THEN a.AllocatedAmount ELSE 0 END) AS RvPaid
            FROM proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
            INNER JOIN proj.TBL_RECEIPT_VOUCHER rv ON a.RvId = rv.RvId
            WHERE rv.Status = 'Approved' AND rv.IsActive = 1 GROUP BY a.InvoiceId
        ) rv_paid ON i.InvoiceId = rv_paid.InvoiceId
        LEFT JOIN (
            SELECT a.InvoiceId, SUM(CASE WHEN a.IsActive = 1 THEN a.AllocatedAmount ELSE 0 END) AS CnPaid
            FROM proj.TBL_CREDIT_NOTE_ALLOCATION a
            INNER JOIN proj.TBL_CREDIT_NOTE cn ON a.CnId = cn.CnId
            WHERE cn.Status = 'Approved' AND cn.IsActive = 1 GROUP BY a.InvoiceId
        ) cn_paid ON i.InvoiceId = cn_paid.InvoiceId
        WHERE i.IsActive = 1 AND i.Status NOT IN ('Draft','Cancelled')
          AND (i.TotalAmount * i.ExchangeRate - COALESCE(rv_paid.RvPaid,0) - COALESCE(cn_paid.CnPaid,0)) > 0
    ),
    CustomerOutstanding AS (
        SELECT io.CustomerId,
            SUM(io.OutstandingBase) AS TotalPendingBase,
            SUM(CASE WHEN io.DaysOverdue > 0 THEN io.OutstandingBase ELSE 0 END) AS OverdueAmountBase,
            MAX(io.DaysOverdue) AS MaxDaysOverdue
        FROM InvoiceOutstanding io GROUP BY io.CustomerId HAVING SUM(io.OutstandingBase) > 0
    ),
    LatestFollowup AS (
        SELECT * FROM (
            SELECT f.FollowupId, f.CustomerId, f.ContactDate, f.Outcome, f.Notes,
                f.PromiseAmount, f.PromiseDate, f.NextFollowupDate, f.PromiseStatus, f.CreatedBy,
                ROW_NUMBER() OVER (PARTITION BY f.CustomerId ORDER BY f.ContactDate DESC, f.FollowupId DESC) AS rn
            FROM PROJ.TBL_PAYMENT_FOLLOWUP f WHERE f.IsActive = 1
        ) x WHERE x.rn = 1
    ),
    FollowupCounts AS (
        SELECT CustomerId, COUNT(*) AS FollowupCount FROM PROJ.TBL_PAYMENT_FOLLOWUP WHERE IsActive = 1 GROUP BY CustomerId
    ),
    Worklist AS (
        SELECT co.CustomerId, c.CustomerName, c.CustomerCode, c.Phone, c.Mobile, c.Email, c.SalesPerson,
            co.TotalPendingBase, co.OverdueAmountBase, co.MaxDaysOverdue,
            ISNULL(fc.FollowupCount, 0) AS FollowupCount,
            lf.FollowupId AS LastFollowupId, lf.ContactDate AS LastContactDate, lf.Outcome AS LastOutcome,
            lf.Notes AS LastNotes, lf.CreatedBy AS LastContactBy,
            lf.PromiseAmount, lf.PromiseDate, lf.NextFollowupDate, lf.PromiseStatus,
            CASE
                WHEN lf.PromiseStatus = 'Open' AND lf.PromiseDate IS NOT NULL AND lf.PromiseDate <  @Today THEN 'PromiseBroken'
                WHEN lf.PromiseStatus = 'Open' AND lf.PromiseDate IS NOT NULL AND lf.PromiseDate =  @Today THEN 'PromiseDue'
                WHEN lf.NextFollowupDate IS NOT NULL AND lf.NextFollowupDate <= @Today THEN 'FollowupDue'
                WHEN lf.FollowupId IS NULL AND co.MaxDaysOverdue > 0 THEN 'NeverContacted'
                WHEN lf.NextFollowupDate IS NOT NULL AND lf.NextFollowupDate > @Today THEN 'Scheduled'
                ELSE 'NoActionDue'
            END AS FollowupState
        FROM CustomerOutstanding co
        INNER JOIN proj.TBL_CUSTOMER c ON co.CustomerId = c.CustomerId
        LEFT JOIN LatestFollowup lf ON co.CustomerId = lf.CustomerId
        LEFT JOIN FollowupCounts fc ON co.CustomerId = fc.CustomerId
        WHERE (@SearchText IS NULL OR c.CustomerName LIKE '%' + @SearchText + '%' OR c.CustomerCode LIKE '%' + @SearchText + '%')
    ),
    Prioritised AS (
        SELECT *, CASE FollowupState
            WHEN 'PromiseBroken' THEN 1 WHEN 'PromiseDue' THEN 2 WHEN 'NeverContacted' THEN 3
            WHEN 'FollowupDue' THEN 4 WHEN 'Scheduled' THEN 5 ELSE 6 END AS Priority
        FROM Worklist
    ),
    Filtered AS (
        SELECT *, COUNT(*) OVER () AS TotalRows FROM Prioritised
        WHERE (@State IS NULL OR @State = '' OR FollowupState = @State) AND (@ShowAll = 1 OR Priority <= 4)
    )
    SELECT * FROM Filtered
    ORDER BY
        CASE WHEN @SortDirection = 'ASC' THEN CASE @SortColumn WHEN 'CustomerName' THEN CustomerName ELSE NULL END END ASC,
        CASE WHEN @SortDirection = 'ASC' THEN CASE @SortColumn
            WHEN 'Priority' THEN CAST(Priority AS DECIMAL(18,2))
            WHEN 'TotalPendingBase' THEN TotalPendingBase
            WHEN 'OverdueAmountBase' THEN OverdueAmountBase
            WHEN 'MaxDaysOverdue' THEN CAST(MaxDaysOverdue AS DECIMAL(18,2))
            WHEN 'PromiseDate' THEN CAST(CAST(PromiseDate AS DATETIME) AS FLOAT)
            WHEN 'NextFollowupDate' THEN CAST(CAST(NextFollowupDate AS DATETIME) AS FLOAT)
            ELSE CAST(Priority AS DECIMAL(18,2)) END END ASC,
        CASE WHEN @SortDirection = 'DESC' THEN CASE @SortColumn WHEN 'CustomerName' THEN CustomerName ELSE NULL END END DESC,
        CASE WHEN @SortDirection = 'DESC' THEN CASE @SortColumn
            WHEN 'Priority' THEN CAST(Priority AS DECIMAL(18,2))
            WHEN 'TotalPendingBase' THEN TotalPendingBase
            WHEN 'OverdueAmountBase' THEN OverdueAmountBase
            WHEN 'MaxDaysOverdue' THEN CAST(MaxDaysOverdue AS DECIMAL(18,2))
            WHEN 'PromiseDate' THEN CAST(CAST(PromiseDate AS DATETIME) AS FLOAT)
            WHEN 'NextFollowupDate' THEN CAST(CAST(NextFollowupDate AS DATETIME) AS FLOAT)
            ELSE CAST(Priority AS DECIMAL(18,2)) END END DESC,
        OverdueAmountBase DESC, CustomerId ASC
    OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetFollowupWorklistSummary]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetFollowupWorklistSummary];
GO

CREATE PROCEDURE PROJ.sp_GetFollowupWorklistSummary
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Today DATE = CAST(GETDATE() AS DATE);
    ;WITH InvoiceOutstanding AS (
        SELECT i.CustomerId,
            i.TotalAmount * i.ExchangeRate
                - COALESCE(rv_paid.RvPaid, 0)
                - COALESCE(cn_paid.CnPaid, 0) AS OutstandingBase,
            CASE WHEN i.DueDate IS NULL OR i.DueDate >= @Today THEN 0
                 ELSE DATEDIFF(DAY, i.DueDate, GETDATE()) END AS DaysOverdue
        FROM proj.TBL_INVOICE i
        LEFT JOIN (
            SELECT a.InvoiceId, SUM(CASE WHEN a.IsActive = 1 THEN a.AllocatedAmount ELSE 0 END) AS RvPaid
            FROM proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
            INNER JOIN proj.TBL_RECEIPT_VOUCHER rv ON a.RvId = rv.RvId
            WHERE rv.Status = 'Approved' AND rv.IsActive = 1 GROUP BY a.InvoiceId
        ) rv_paid ON i.InvoiceId = rv_paid.InvoiceId
        LEFT JOIN (
            SELECT a.InvoiceId, SUM(CASE WHEN a.IsActive = 1 THEN a.AllocatedAmount ELSE 0 END) AS CnPaid
            FROM proj.TBL_CREDIT_NOTE_ALLOCATION a
            INNER JOIN proj.TBL_CREDIT_NOTE cn ON a.CnId = cn.CnId
            WHERE cn.Status = 'Approved' AND cn.IsActive = 1 GROUP BY a.InvoiceId
        ) cn_paid ON i.InvoiceId = cn_paid.InvoiceId
        WHERE i.IsActive = 1 AND i.Status NOT IN ('Draft','Cancelled')
          AND (i.TotalAmount * i.ExchangeRate
                - COALESCE(rv_paid.RvPaid, 0)
                - COALESCE(cn_paid.CnPaid, 0)) > 0.005
    ),
    CustomerOutstanding AS (
        SELECT CustomerId, SUM(OutstandingBase) AS TotalPendingBase,
               SUM(CASE WHEN DaysOverdue > 0 THEN OutstandingBase ELSE 0 END) AS OverdueAmountBase,
               MAX(DaysOverdue) AS MaxDaysOverdue
        FROM InvoiceOutstanding GROUP BY CustomerId HAVING SUM(OutstandingBase) > 0
    ),
    LatestFollowup AS (
        SELECT * FROM (
            SELECT f.CustomerId, f.FollowupId, f.PromiseDate, f.NextFollowupDate, f.PromiseStatus,
                   ROW_NUMBER() OVER (PARTITION BY f.CustomerId ORDER BY f.ContactDate DESC, f.FollowupId DESC) rn
            FROM PROJ.TBL_PAYMENT_FOLLOWUP f WHERE f.IsActive = 1
        ) x WHERE rn = 1
    ),
    States AS (
        SELECT co.OverdueAmountBase, co.MaxDaysOverdue,
            CASE
                WHEN lf.PromiseStatus = 'Open' AND lf.PromiseDate < @Today THEN 'PromiseBroken'
                WHEN lf.PromiseStatus = 'Open' AND lf.PromiseDate = @Today THEN 'PromiseDue'
                WHEN lf.NextFollowupDate IS NOT NULL AND lf.NextFollowupDate <= @Today THEN 'FollowupDue'
                WHEN lf.FollowupId IS NULL AND co.MaxDaysOverdue > 0 THEN 'NeverContacted'
                ELSE 'NoActionDue'
            END AS FollowupState
        FROM CustomerOutstanding co LEFT JOIN LatestFollowup lf ON co.CustomerId = lf.CustomerId
    )
    SELECT
        SUM(CASE WHEN FollowupState IN ('PromiseBroken','PromiseDue','FollowupDue','NeverContacted') THEN 1 ELSE 0 END) AS ActionDueCount,
        SUM(CASE WHEN FollowupState = 'PromiseBroken' THEN 1 ELSE 0 END) AS BrokenPromiseCount,
        SUM(CASE WHEN FollowupState = 'PromiseDue' THEN 1 ELSE 0 END) AS PromiseDueCount,
        SUM(CASE WHEN FollowupState = 'NeverContacted' THEN 1 ELSE 0 END) AS NeverContactedCount,
        ISNULL(SUM(OverdueAmountBase), 0) AS TotalOverdueBase
    FROM States;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetGRN]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetGRN];
GO

CREATE PROCEDURE proj.sp_GetGRN
    @GrnId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        g.GrnId, g.GrnNumber, g.GrnDate, g.Status,
        g.PoId, po.PoNumber,
        g.SupplierId, s.SupplierCode, s.SupplierName,
        s.Phone AS SupplierPhone, s.Email AS SupplierEmail,
        (SELECT TOP 1
            NULLIF(LTRIM(RTRIM(
                ISNULL(sa.AddressLine1 + ', ', '') +
                ISNULL(NULLIF(LTRIM(RTRIM(sa.State)),'') + ', ', '') +
                ISNULL(cn.CountryName, '')
            )), '')
         FROM proj.TBL_SUPPLIER_ADDRESS sa
         LEFT JOIN proj.TBL_COUNTRY cn ON cn.CountryId = sa.CountryId
         WHERE sa.SupplierId = g.SupplierId AND sa.IsActive = 1
         ORDER BY sa.IsDefault DESC, sa.SupplierAddressId ASC
        ) AS SupplierAddress,
        g.JobId, j.ProjectName AS JobTitle,
        g.ReceivedDate, g.ReceivedBy, g.ReceivedFrom,
        g.DoNo, g.ShipmentBy, g.DeliveryTerms, g.DeliveryLocation, g.ShipmentDetails,
        g.InvoiceNo, g.InvoiceDate,
        g.CurrencyId, c.CurrencyName, c.ShortName AS CurrencyShort, c.Symbol AS CurrencySymbol,
        g.ExchangeRate, g.TotalAmount,
        g.BoeNo, g.BoeDate,
        g.IsRegistered, g.RegisteredBy, g.RegisteredDate,
        g.Remarks, g.IsActive,
        g.CreatedBy, g.CreatedDate, g.ModifiedBy, g.ModifiedDate,
        -- Computed from lines
        (SELECT COUNT(*)
         FROM proj.TBL_GRN_DETAIL d WHERE d.GrnId = g.GrnId AND d.IsActive = 1) AS LineCount,
        (SELECT ISNULL(SUM(d.ReceivedQty * d.UnitPrice), 0)
         FROM proj.TBL_GRN_DETAIL d WHERE d.GrnId = g.GrnId AND d.IsActive = 1) AS LinesSubTotal,
        (SELECT ISNULL(SUM(d.ReceivedQty * d.UnitPrice * (1 + d.TaxPct / 100.0)), 0)
         FROM proj.TBL_GRN_DETAIL d WHERE d.GrnId = g.GrnId AND d.IsActive = 1) AS LinesTotalWithTax,
        -- Document count
        (SELECT COUNT(*)
         FROM proj.TBL_DOCUMENTS doc
         WHERE doc.ReferenceTable = 'GRN'
           AND doc.ReferenceKey   = CAST(g.GrnId AS NVARCHAR(20))
           AND doc.IsActive       = 1) AS DocumentCount
    FROM proj.TBL_GRN_HEADER        g
    LEFT JOIN proj.TBL_PURCHASE_ORDER po ON po.PoId         = g.PoId
    LEFT JOIN proj.TBL_SUPPLIER       s  ON s.SupplierId    = g.SupplierId
    LEFT JOIN proj.TBL_JOB            j  ON j.JobId         = g.JobId
    LEFT JOIN proj.TBL_CURRENCY       c  ON c.CurrencyId    = g.CurrencyId
    WHERE g.GrnId = @GrnId AND g.IsActive = 1;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetGRNLines]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetGRNLines];
GO
CREATE PROCEDURE proj.sp_GetGRNLines
    @GrnId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        d.GrnDetailId, d.GrnId, d.LineNum,
        d.PoLineId, d.PrLineId,
        d.ItemId, d.ItemCode, d.ItemDesc,
        d.OrderedQty, d.ReceivedQty, d.RejectedQty,
        d.ReceivedQty - ISNULL(d.RejectedQty,0)                                    AS AcceptedQty,
        d.UomId, d.UomName,
        i.BaseUomId,
        bu.UomCode                                                                  AS BaseUomCode,
        bu.UomName                                                                  AS BaseUomName,
        ISNULL(uc.ConversionFactor, 1)                                              AS ConversionFactor,
        (d.ReceivedQty - ISNULL(d.RejectedQty,0)) * ISNULL(uc.ConversionFactor,1)  AS StockQty,
        -- 1 when the line UOM differs from the item's base UOM but no active
        -- conversion is defined → posting (Receive) will be blocked.
        CASE WHEN d.ItemId IS NOT NULL
              AND i.BaseUomId IS NOT NULL
              AND d.UomId IS NOT NULL
              AND d.UomId <> i.BaseUomId
              AND uc.ConversionFactor IS NULL
             THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END                            AS ConversionMissing,
        d.UnitPrice, d.TaxPct,
        d.ReceivedQty * d.UnitPrice                                                 AS LineTotal,
        d.ReceivedQty * d.UnitPrice * (1 + d.TaxPct / 100.0)                       AS LineTotalWithTax,
        d.BatchNo, d.SerialNo, d.ExpiryDate,
        d.StorageLocation, d.BinLocation,
        d.QcStatus, d.QcRemarks,
        d.Remarks, d.CreatedBy, d.CreatedDate
    FROM proj.TBL_GRN_DETAIL d
    LEFT JOIN proj.TBL_ITEM             i  ON i.ItemId   = d.ItemId
    LEFT JOIN proj.TBL_ITEM_UOM         bu ON bu.UomId   = i.BaseUomId
    LEFT JOIN proj.TBL_ITEM_UOM_CONVERSION uc
           ON uc.ItemId    = d.ItemId
          AND uc.FromUomId = d.UomId
          AND uc.ToUomId   = i.BaseUomId
          AND uc.IsActive  = 1
    WHERE d.GrnId = @GrnId AND d.IsActive = 1
    ORDER BY d.LineNum;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetGRNLinesForInvoice]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetGRNLinesForInvoice];
GO

CREATE   PROCEDURE proj.sp_GetGRNLinesForInvoice
    @GrnId INT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @EffQty NVARCHAR(200) = 'ISNULL(d.AcceptedQty, d.ReceivedQty)';

    SELECT
        d.GrnDetailId,
        d.GrnId,
        g.GrnNumber,
        d.PoLineId,
        po.PoNumber,
        d.ItemId,
        d.ItemCode,
        d.ItemDesc,
        d.UomName,
        ISNULL(d.AcceptedQty, d.ReceivedQty)                AS ReceivedQty,
        ISNULL((
            SELECT SUM(l.Qty)
            FROM proj.TBL_SUPPLIER_INVOICE_LINE l
            WHERE l.GrnDetailId = d.GrnDetailId AND l.IsActive = 1
        ), 0)                                               AS AlreadyInvoicedQty,
        ISNULL(d.AcceptedQty, d.ReceivedQty) - ISNULL((
            SELECT SUM(l.Qty)
            FROM proj.TBL_SUPPLIER_INVOICE_LINE l
            WHERE l.GrnDetailId = d.GrnDetailId AND l.IsActive = 1
        ), 0)                                               AS PendingQty,
        d.UnitPrice,
        d.TaxPct
    FROM proj.TBL_GRN_DETAIL d
    INNER JOIN proj.TBL_GRN_HEADER g ON g.GrnId = d.GrnId
    LEFT JOIN  proj.TBL_PURCHASE_ORDER po ON po.PoId = g.PoId
    WHERE d.GrnId = @GrnId
      AND d.IsActive = 1
      AND ISNULL(d.AcceptedQty, d.ReceivedQty) > ISNULL((
            SELECT SUM(l.Qty)
            FROM proj.TBL_SUPPLIER_INVOICE_LINE l
            WHERE l.GrnDetailId = d.GrnDetailId AND l.IsActive = 1
          ), 0)
    ORDER BY d.LineNum;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetGRNLinesForRTV]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetGRNLinesForRTV];
GO
CREATE PROCEDURE proj.sp_GetGRNLinesForRTV
    @GrnId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT d.GrnDetailId, d.LineNum, d.ItemId, d.ItemCode, d.ItemDesc,
           d.AcceptedQty, d.ReceivedQty, d.RejectedQty,
           d.UomId, d.UomName, d.UnitPrice AS UnitCost,
           d.PoLineId, d.PrLineId,
           i.BaseUomId,
           bu.UomCode AS BaseUomCode,
           ISNULL(uc.ConversionFactor, 1) AS ConversionFactor,
           -- Accepted qty expressed in the item's base UOM (how much stock a full return removes)
           d.AcceptedQty * ISNULL(uc.ConversionFactor, 1) AS AcceptedStockQty,
           ISNULL(sb.QtyOnHand, 0) AS CurrentStock
    FROM   proj.TBL_GRN_DETAIL d
    LEFT JOIN proj.TBL_STOCK_BALANCE sb ON sb.ItemId = d.ItemId
    LEFT JOIN proj.TBL_ITEM          i  ON i.ItemId  = d.ItemId
    LEFT JOIN proj.TBL_ITEM_UOM      bu ON bu.UomId  = i.BaseUomId
    LEFT JOIN proj.TBL_ITEM_UOM_CONVERSION uc
           ON uc.ItemId=d.ItemId AND uc.FromUomId=d.UomId AND uc.ToUomId=i.BaseUomId AND uc.IsActive=1
    WHERE  d.GrnId = @GrnId AND d.IsActive = 1 AND d.AcceptedQty > 0
    ORDER  BY d.LineNum;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetGRNQCItems]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetGRNQCItems];
