IF OBJECT_ID(N'[proj].[sp_GetGRNQCLog]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetGRNQCLog];
GO

CREATE PROCEDURE proj.sp_GetGRNQCLog
    @GrnId INT
AS
BEGIN
    SET NOCOUNT ON;

    -- Header (now includes decision fields)
    SELECT l.QcLogId, l.GrnId, l.CheckedBy, l.CheckedDate, l.Remarks,
           l.Decision, l.DecisionNotes, l.DecisionBy, l.DecisionDate,
           u.FullName  AS CheckedByName,
           db.FullName AS DecisionByName
    FROM   proj.TBL_GRN_QC_LOG l
    LEFT   JOIN proj.TBL_USERS u  ON u.Username  = l.CheckedBy
    LEFT   JOIN proj.TBL_USERS db ON db.Username = l.DecisionBy
    WHERE  l.GrnId = @GrnId
    ORDER  BY l.CheckedDate DESC;

    -- Details for all logs of this GRN
    SELECT d.QcDetailId, d.QcItemId, d.QcLogId, d.ItemName, d.IsChecked, d.Notes
    FROM   proj.TBL_GRN_QC_LOG_DETAIL d
    JOIN   proj.TBL_GRN_QC_LOG        l ON l.QcLogId = d.QcLogId
    WHERE  l.GrnId = @GrnId
    ORDER  BY d.QcLogId, d.QcDetailId;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetGRNsForSupplierInvoice]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetGRNsForSupplierInvoice];
GO
CREATE PROCEDURE proj.sp_GetGRNsForSupplierInvoice
    @SupplierId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        g.GrnId,
        g.GrnNumber,
        g.GrnDate,
        po.PoNumber,
        g.TotalAmount,
        g.Status
    FROM proj.TBL_GRN_HEADER g
    INNER JOIN proj.TBL_PURCHASE_ORDER po ON po.PoId = g.PoId
    WHERE g.SupplierId = @SupplierId
      AND g.IsActive   = 1
      AND g.Status     IN ('Received', 'Invoiced')   -- include partially-invoiced GRNs
      AND EXISTS (
            SELECT 1
            FROM proj.TBL_GRN_DETAIL d
            WHERE d.GrnId = g.GrnId
              AND d.IsActive = 1
              AND ISNULL(d.AcceptedQty, d.ReceivedQty) > ISNULL((
                    SELECT SUM(l.Qty)
                    FROM proj.TBL_SUPPLIER_INVOICE_LINE l
                    WHERE l.GrnDetailId = d.GrnDetailId AND l.IsActive = 1
                  ), 0)
      )
    ORDER BY g.GrnDate DESC, g.GrnId DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetGRNUnregPreview]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetGRNUnregPreview];
GO
CREATE PROCEDURE proj.sp_GetGRNUnregPreview
    @GrnId INT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @GrnDate      DATE,
            @ReceivedDate DATE,
            @PoId         INT;

    SELECT @GrnDate      = GrnDate,
           @ReceivedDate = ReceivedDate,
           @PoId         = PoId
    FROM   proj.TBL_GRN_HEADER
    WHERE  GrnId = @GrnId AND IsActive = 1;

    DECLARE @RefDate DATE = ISNULL(@ReceivedDate, @GrnDate);

    -- ── Header ────────────────────────────────────────────────────────────────
    SELECT
        g.GrnId,
        g.GrnNumber,
        g.GrnDate,
        g.PoId,
        po.PoNumber,
        g.SupplierId,
        s.SupplierName,
        g.Status,
        g.TotalAmount,
        g.InvoiceNo,
        CAST(CASE WHEN g.CancelledDate IS NOT NULL THEN 1 ELSE 0 END AS BIT) AS AlreadyCancelled,
        CAST(CASE WHEN g.InvoiceNo IS NOT NULL AND g.InvoiceNo <> '' THEN 1 ELSE 0 END AS BIT) AS HasInvoice,
        -- Would any item go negative if reversed? (reverse qty in GRN UOM → base)
        CAST(CASE WHEN EXISTS (
            SELECT 1
            FROM   proj.TBL_GRN_DETAIL d
            JOIN   proj.TBL_STOCK_BALANCE sb ON sb.ItemId = d.ItemId
            LEFT  JOIN proj.TBL_ITEM i ON i.ItemId = d.ItemId
            LEFT  JOIN proj.TBL_ITEM_UOM_CONVERSION uc
                   ON uc.ItemId=d.ItemId AND uc.FromUomId=d.UomId AND uc.ToUomId=i.BaseUomId AND uc.IsActive=1
            WHERE  d.GrnId    = g.GrnId
              AND  d.IsActive = 1
              AND  d.ItemId   IS NOT NULL
              AND  (sb.QtyOnHand - (d.ReceivedQty - ISNULL(d.RejectedQty, 0)) * ISNULL(uc.ConversionFactor,1)) < 0
        ) THEN 1 ELSE 0 END AS BIT) AS WouldGoNegative,
        -- Any stock OUT transactions after this GRN's received date?
        CAST(CASE WHEN EXISTS (
            SELECT 1
            FROM   proj.TBL_STOCK_LEDGER sl
            JOIN   proj.TBL_GRN_DETAIL   d  ON d.ItemId = sl.ItemId
            WHERE  d.GrnId        = g.GrnId
              AND  d.IsActive     = 1
              AND  d.ItemId       IS NOT NULL
              AND  sl.QtyOut      > 0
              AND  CAST(sl.TransDate AS DATE) > @RefDate
        ) THEN 1 ELSE 0 END AS BIT) AS HasPostGrnIssues,
        -- PO status after reversal
        CASE
            WHEN (
                SELECT ISNULL(SUM(pl.ReceivedQty), 0)
                FROM   proj.TBL_PURCHASE_ORDER_LINE pl
                WHERE  pl.PoId = g.PoId AND pl.IsActive = 1
            ) - (
                SELECT ISNULL(SUM(gd.ReceivedQty - ISNULL(gd.RejectedQty, 0)), 0)
                FROM   proj.TBL_GRN_DETAIL gd
                WHERE  gd.GrnId = g.GrnId AND gd.IsActive = 1 AND gd.PoLineId IS NOT NULL
            ) <= 0 THEN po.Status + ' > Approved'
            ELSE po.Status + ' > Partial'
        END AS PoStatusAfter
    FROM  proj.TBL_GRN_HEADER g
    LEFT JOIN proj.TBL_PURCHASE_ORDER po ON po.PoId      = g.PoId
    LEFT JOIN proj.TBL_SUPPLIER       s  ON s.SupplierId = g.SupplierId
    WHERE g.GrnId = @GrnId AND g.IsActive = 1;

    -- ── Lines — show accepted qty + per-line blocking detail ─────────────────
    SELECT
        gd.GrnDetailId,
        gd.LineNum,
        gd.ItemCode,
        gd.ItemDesc,
        gd.OrderedQty,
        gd.ReceivedQty,
        gd.RejectedQty,
        gd.AcceptedQty,
        gd.UomName,
        gd.UnitPrice,
        gd.LineTotal,
        gd.LineTotalWithTax,
        gd.PoLineId,
        -- Current balance for this item (base UOM)
        ISNULL(sb.QtyOnHand, 0) AS CurrentStock,
        -- Reverse qty expressed in base UOM
        (gd.ReceivedQty - ISNULL(gd.RejectedQty,0)) * ISNULL(uc.ConversionFactor,1) AS ReverseStockQty,
        -- Would this line's reversal alone cause negative? (compared in base UOM)
        CAST(CASE
            WHEN gd.ItemId IS NOT NULL
             AND ISNULL(sb.QtyOnHand, 0) - (gd.ReceivedQty - ISNULL(gd.RejectedQty,0)) * ISNULL(uc.ConversionFactor,1) < 0
            THEN 1 ELSE 0
        END AS BIT) AS WouldGoNegative,
        -- Earliest post-GRN issue for this item (for display)
        (
            SELECT TOP 1 CONVERT(NVARCHAR(20), CAST(sl.TransDate AS DATE), 23)
                         + ' (' + sl.TransType + ' ' + CAST(sl.QtyOut AS NVARCHAR(20)) + ')'
            FROM   proj.TBL_STOCK_LEDGER sl
            WHERE  sl.ItemId  = gd.ItemId
              AND  sl.QtyOut  > 0
              AND  CAST(sl.TransDate AS DATE) > @RefDate
            ORDER  BY sl.TransDate
        ) AS FirstPostIssue
    FROM  proj.TBL_GRN_DETAIL gd
    LEFT JOIN proj.TBL_STOCK_BALANCE sb ON sb.ItemId = gd.ItemId
    LEFT JOIN proj.TBL_ITEM i ON i.ItemId = gd.ItemId
    LEFT JOIN proj.TBL_ITEM_UOM_CONVERSION uc
           ON uc.ItemId=gd.ItemId AND uc.FromUomId=gd.UomId AND uc.ToUomId=i.BaseUomId AND uc.IsActive=1
    WHERE gd.GrnId = @GrnId AND gd.IsActive = 1
    ORDER BY gd.LineNum;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetInvoice]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetInvoice];
GO

CREATE   PROCEDURE PROJ.sp_GetInvoice
    @InvoiceId  INT          = NULL,
    @InvoiceNo  NVARCHAR(30) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Id INT = @InvoiceId;
    IF @Id IS NULL OR @Id = 0
        SELECT @Id = InvoiceId FROM PROJ.TBL_INVOICE
        WHERE InvoiceNo = @InvoiceNo AND IsActive = 1;

    SELECT
        i.InvoiceId, i.InvoiceNo, i.InvoiceDate,
        i.CustomerId, c.CustomerName, c.VatNumber AS CustomerVatNo,
        i.BillingAddress,
        i.CurrencyId, cu.ShortName AS CurrencyShort, cu.Symbol AS CurrencySymbol,
        cu.IsBaseCurrency,
        i.ExchangeRate,
        i.DueDate, i.JobId, j.JobDescription AS JobTitle,
        i.LpoNo, i.LpoDate,
        i.ContactId,
        cc.ContactName, cc.Designation AS ContactDesignation,
        cc.Phone AS ContactPhone, cc.Email AS ContactEmail,
        i.SubTotal, i.TaxAmount, i.TotalAmount,
        i.Notes, i.Status, i.Revision,
        (SELECT COUNT(*) FROM PROJ.TBL_INVOICE_LINE l
         WHERE l.InvoiceId = i.InvoiceId AND l.IsActive = 1) AS LineCount,
        (SELECT COUNT(*) FROM PROJ.TBL_DOCUMENTS d
         WHERE d.ReferenceTable = 'TBL_INVOICE'
           AND d.ReferenceKey   = CAST(i.InvoiceId AS NVARCHAR(20))
           AND d.IsActive       = 1) AS DocumentCount,
        i.CreatedBy, i.CreatedDate, i.ModifiedBy, i.ModifiedDate
    FROM PROJ.TBL_INVOICE i
    INNER JOIN PROJ.TBL_CUSTOMER  c  ON c.CustomerId  = i.CustomerId
    INNER JOIN PROJ.TBL_CURRENCY  cu ON cu.CurrencyId = i.CurrencyId
    LEFT  JOIN PROJ.VW_JOB        j  ON j.JobId       = i.JobId
    LEFT  JOIN PROJ.TBL_CUSTOMER_CONTACT cc ON cc.CustomerContactId = i.ContactId
    WHERE i.InvoiceId = @Id AND i.IsActive = 1;

    SELECT
        l.InvoiceLineId, l.InvoiceId, l.LineNum,
        l.Description, l.UomName,
        l.UnitPrice, l.Qty, l.Amount,
        l.VatPercent, l.TaxAmount,
        l.Notes, l.CreatedBy, l.CreatedDate, l.ModifiedBy, l.ModifiedDate
    FROM PROJ.TBL_INVOICE_LINE l
    WHERE l.InvoiceId = @Id AND l.IsActive = 1
    ORDER BY l.LineNum;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetInvoiceAllocationHistory]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetInvoiceAllocationHistory];
GO

CREATE PROCEDURE proj.sp_GetInvoiceAllocationHistory
    @InvoiceId INT
AS
BEGIN
    SET NOCOUNT ON;

    -- AllocatedAmount is stored in BASE currency (AED).
    -- Divide by invoice.ExchangeRate to display in the invoice's original currency.

    SELECT
        a.AllocationId,
        a.RvId,
        rv.RvNumber,
        rv.RvDate,
        rv.Status        AS RvStatus,
        ROUND(a.AllocatedAmount / NULLIF(i.ExchangeRate, 0), 2) AS AllocatedAmount,
        a.AllocatedAmount AS AllocatedAmountBase,
        a.Reason,
        a.IsActive,
        a.CreatedBy,
        a.CreatedDate,
        a.ModifiedBy,
        a.ModifiedDate
    FROM  proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
    JOIN  proj.TBL_RECEIPT_VOUCHER rv ON rv.RvId      = a.RvId
    JOIN  proj.TBL_INVOICE         i  ON i.InvoiceId  = a.InvoiceId
    WHERE a.InvoiceId = @InvoiceId
    ORDER BY a.CreatedDate DESC, a.AllocationId DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetInvoiceLinesForDelivery]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetInvoiceLinesForDelivery];
GO

CREATE   PROCEDURE proj.sp_GetInvoiceLinesForDelivery
    @InvoiceId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        il.InvoiceLineId,
        il.InvoiceId,
        i.InvoiceNo,
        il.LineNum,
        il.Description,
        il.UomName,
        il.Qty                                              AS InvoiceQty,
        ISNULL((
            SELECT SUM(dl.Qty)
            FROM proj.TBL_DELIVERY_LINE dl
            INNER JOIN proj.TBL_DELIVERY d ON d.DeliveryId = dl.DeliveryId
            WHERE dl.InvoiceLineId = il.InvoiceLineId
              AND dl.IsActive = 1
              AND d.IsActive  = 1
              AND d.Status   <> 'Cancelled'
        ), 0)                                               AS AlreadyDeliveredQty,
        il.Qty - ISNULL((
            SELECT SUM(dl.Qty)
            FROM proj.TBL_DELIVERY_LINE dl
            INNER JOIN proj.TBL_DELIVERY d ON d.DeliveryId = dl.DeliveryId
            WHERE dl.InvoiceLineId = il.InvoiceLineId
              AND dl.IsActive = 1
              AND d.IsActive  = 1
              AND d.Status   <> 'Cancelled'
        ), 0)                                               AS PendingQty,
        il.UnitPrice,
        il.VatPercent
    FROM proj.TBL_INVOICE_LINE il
    INNER JOIN proj.TBL_INVOICE i ON i.InvoiceId = il.InvoiceId
    WHERE il.InvoiceId = @InvoiceId
      AND il.IsActive  = 1
      AND il.Qty > ISNULL((
            SELECT SUM(dl.Qty)
            FROM proj.TBL_DELIVERY_LINE dl
            INNER JOIN proj.TBL_DELIVERY d ON d.DeliveryId = dl.DeliveryId
            WHERE dl.InvoiceLineId = il.InvoiceLineId
              AND dl.IsActive = 1
              AND d.IsActive  = 1
              AND d.Status   <> 'Cancelled'
          ), 0)
    ORDER BY il.LineNum;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetInvoicePayments]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetInvoicePayments];
GO

CREATE PROCEDURE proj.sp_GetInvoicePayments
    @InvoiceId INT
AS
BEGIN
    SET NOCOUNT ON;

    -- AllocatedAmount is stored in BASE currency (AED).
    -- Divide by invoice.ExchangeRate to present amount in the invoice's original currency.

    SELECT
        a.AllocationId,
        'RV'                 AS SourceType,
        a.RvId               AS RvId,
        rv.RvNumber          AS RvNumber,
        rv.RvDate            AS RvDate,
        rv.PaymentMode       AS PaymentMode,
        rv.ReferenceNo       AS ReferenceNo,
        rv.ReferenceDate     AS ReferenceDate,
        rv.BankName          AS BankName,
        rv.Status            AS RvStatus,
        cur.ShortName        AS RvCurrency,
        rv.ExchangeRate      AS RvExchangeRate,
        ROUND(a.AllocatedAmount / NULLIF(i.ExchangeRate, 0), 2) AS AllocatedAmount,
        a.AllocatedAmount    AS AllocatedAmountBase,
        a.CreatedBy, a.CreatedDate, a.ModifiedBy, a.ModifiedDate
    FROM proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
    JOIN proj.TBL_INVOICE         i   ON i.InvoiceId     = a.InvoiceId
    JOIN proj.TBL_RECEIPT_VOUCHER rv  ON rv.RvId         = a.RvId
    LEFT JOIN proj.TBL_CURRENCY   cur ON cur.CurrencyId  = rv.CurrencyId
    WHERE a.InvoiceId = @InvoiceId
      AND a.IsActive  = 1
      AND rv.IsActive = 1

    UNION ALL

    SELECT
        a.AllocationId,
        'CN'                        AS SourceType,
        a.CnId                      AS RvId,
        cn.CnNumber                 AS RvNumber,
        CAST(cn.CnDate AS DATETIME) AS RvDate,
        'Credit Note'               AS PaymentMode,
        cn.CreditType               AS ReferenceNo,
        NULL                        AS ReferenceDate,
        NULL                        AS BankName,
        cn.Status                   AS RvStatus,
        cur.ShortName               AS RvCurrency,
        cn.ExchangeRate             AS RvExchangeRate,
        ROUND(a.AllocatedAmount / NULLIF(i.ExchangeRate, 0), 2) AS AllocatedAmount,
        a.AllocatedAmount           AS AllocatedAmountBase,
        a.CreatedBy, a.CreatedDate, a.ModifiedBy, a.ModifiedDate
    FROM proj.TBL_CREDIT_NOTE_ALLOCATION a
    JOIN proj.TBL_INVOICE     i   ON i.InvoiceId    = a.InvoiceId
    JOIN proj.TBL_CREDIT_NOTE cn  ON cn.CnId        = a.CnId
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = cn.CurrencyId
    WHERE a.InvoiceId = @InvoiceId
      AND a.IsActive  = 1
      AND cn.IsActive = 1
      AND cn.Status   = 'Approved'

    ORDER BY RvDate, RvNumber;
END
GO

