CREATE PROCEDURE proj.sp_GetInvoicePvAllocationHistory
    @SupplierInvoiceId INT
AS
BEGIN
    SET NOCOUNT ON;

    -- AllocatedAmount is stored in BASE currency (AED).
    -- Divide by invoice.ExchangeRate to display in the invoice's original currency.

    SELECT
        a.AllocationId,
        a.PvId,
        pv.PvNumber,
        pv.PvDate,
        pv.Status        AS PvStatus,
        ROUND(a.AllocatedAmount / NULLIF(si.ExchangeRate, 0), 2) AS AllocatedAmount,
        a.AllocatedAmount AS AllocatedAmountBase,
        a.Reason,
        a.IsActive,
        a.CreatedBy,     a.CreatedDate,
        a.ModifiedBy,    a.ModifiedDate
    FROM  proj.TBL_PAYMENT_VOUCHER_ALLOCATION a
    JOIN  proj.TBL_PAYMENT_VOUCHER   pv ON pv.PvId              = a.PvId
    JOIN  proj.TBL_SUPPLIER_INVOICE  si ON si.SupplierInvoiceId = a.SupplierInvoiceId
    WHERE a.SupplierInvoiceId = @SupplierInvoiceId
    ORDER BY a.CreatedDate DESC, a.AllocationId DESC;
END
