IF OBJECT_ID(N'[proj].[sp_GetInvoicePvAllocations]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetInvoicePvAllocations];
GO

CREATE PROCEDURE proj.sp_GetInvoicePvAllocations
    @SupplierInvoiceId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        pva.AllocationId,
        pv.PvNumber                                                 AS PvNumber,
        pv.PvDate,
        cur.ShortName                                               AS PvCurrencyShort,
        pv.ExchangeRate                                             AS PvExchangeRate,
        icur.ShortName                                              AS InvoiceCurrencyShort,
        ROUND(pva.AllocatedAmount / NULLIF(si.ExchangeRate, 0), 2) AS AllocatedAmount,
        pva.AllocatedAmount                                         AS AllocatedAmountBase,
        'PV'                                                        AS SourceType,
        pv.PaymentMode,
        pva.CreatedBy,
        pva.CreatedDate
    FROM proj.TBL_PAYMENT_VOUCHER_ALLOCATION pva
    JOIN  proj.TBL_PAYMENT_VOUCHER  pv   ON pv.PvId              = pva.PvId
    JOIN  proj.TBL_SUPPLIER_INVOICE si   ON si.SupplierInvoiceId = pva.SupplierInvoiceId
    LEFT JOIN proj.TBL_CURRENCY     cur  ON cur.CurrencyId        = pv.CurrencyId
    LEFT JOIN proj.TBL_CURRENCY     icur ON icur.CurrencyId       = si.CurrencyId
    WHERE pva.SupplierInvoiceId = @SupplierInvoiceId
      AND ISNULL(pva.IsActive, 1) = 1
      AND pv.Status = 'Approved' AND pv.IsActive = 1

    UNION ALL

    SELECT
        dna.AllocationId,
        dn.DnNumber                                                 AS PvNumber,
        dn.DnDate                                                   AS PvDate,
        cur.ShortName                                               AS PvCurrencyShort,
        dn.ExchangeRate                                             AS PvExchangeRate,
        icur.ShortName                                              AS InvoiceCurrencyShort,
        ROUND(dna.AllocatedAmount / NULLIF(si.ExchangeRate, 0), 2) AS AllocatedAmount,
        dna.AllocatedAmount                                         AS AllocatedAmountBase,
        'DN'                                                        AS SourceType,
        NULL                                                        AS PaymentMode,
        dna.CreatedBy,
        dna.CreatedDate
    FROM proj.TBL_DEBIT_NOTE_ALLOCATION dna
    JOIN  proj.TBL_DEBIT_NOTE       dn   ON dn.DnId               = dna.DnId
    JOIN  proj.TBL_SUPPLIER_INVOICE si   ON si.SupplierInvoiceId  = dna.SupplierInvoiceId
    LEFT JOIN proj.TBL_CURRENCY     cur  ON cur.CurrencyId         = dn.CurrencyId
    LEFT JOIN proj.TBL_CURRENCY     icur ON icur.CurrencyId        = si.CurrencyId
    WHERE dna.SupplierInvoiceId = @SupplierInvoiceId
      AND ISNULL(dna.IsActive, 1) = 1
      AND dn.Status = 'Approved' AND dn.IsActive = 1

    ORDER BY PvDate DESC, AllocationId DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetInvoiceReceiptAllocations]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetInvoiceReceiptAllocations];
GO

CREATE PROCEDURE proj.sp_GetInvoiceReceiptAllocations
    @InvoiceId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        a.AllocationId,
        rv.RvNumber,
        rv.RvDate,
        cur.ShortName                                             AS RvCurrencyShort,
        rv.ExchangeRate                                           AS RvExchangeRate,
        icur.ShortName                                            AS InvoiceCurrencyShort,
        ROUND(a.AllocatedAmount / NULLIF(i.ExchangeRate, 0), 2)  AS AllocatedAmount,
        a.AllocatedAmount                                         AS AllocatedAmountBase,
        'RV'                                                      AS SourceType,
        a.CreatedBy,
        a.CreatedDate
    FROM proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
    INNER JOIN proj.TBL_INVOICE          i    ON a.InvoiceId   = i.InvoiceId
    INNER JOIN proj.TBL_RECEIPT_VOUCHER  rv   ON a.RvId        = rv.RvId
    LEFT  JOIN proj.TBL_CURRENCY         cur  ON rv.CurrencyId = cur.CurrencyId
    LEFT  JOIN proj.TBL_CURRENCY         icur ON i.CurrencyId  = icur.CurrencyId
    WHERE a.InvoiceId = @InvoiceId
      AND a.IsActive  = 1
      AND rv.Status = 'Approved' AND rv.IsActive = 1

    UNION ALL

    SELECT
        a.AllocationId,
        cn.CnNumber                                               AS RvNumber,
        cn.CnDate                                                 AS RvDate,
        cur.ShortName                                             AS RvCurrencyShort,
        cn.ExchangeRate                                           AS RvExchangeRate,
        icur.ShortName                                            AS InvoiceCurrencyShort,
        ROUND(a.AllocatedAmount / NULLIF(i.ExchangeRate, 0), 2)  AS AllocatedAmount,
        a.AllocatedAmount                                         AS AllocatedAmountBase,
        'CN'                                                      AS SourceType,
        a.CreatedBy,
        a.CreatedDate
    FROM proj.TBL_CREDIT_NOTE_ALLOCATION a
    INNER JOIN proj.TBL_INVOICE          i    ON a.InvoiceId  = i.InvoiceId
    INNER JOIN proj.TBL_CREDIT_NOTE      cn   ON a.CnId       = cn.CnId
    LEFT  JOIN proj.TBL_CURRENCY         cur  ON cn.CurrencyId = cur.CurrencyId
    LEFT  JOIN proj.TBL_CURRENCY         icur ON i.CurrencyId  = icur.CurrencyId
    WHERE a.InvoiceId = @InvoiceId
      AND a.IsActive  = 1
      AND cn.Status = 'Approved' AND cn.IsActive = 1

    ORDER BY CreatedDate DESC;
END;
GO

