IF OBJECT_ID(N'[proj].[sp_GetIssueLinesForReturn]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetIssueLinesForReturn];
GO

-- ── sp_GetIssueLinesForReturn ─────────────────────────────────────────────
-- Returns issue lines with how much qty is still returnable
CREATE   PROCEDURE proj.sp_GetIssueLinesForReturn
    @IssueId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        il.IssueLineId,
        il.IssueId,
        il.LineNum,
        il.ItemId,
        it.ItemCode,
        it.ItemName,
        il.ItemDesc,
        il.Qty                              AS IssuedQty,
        il.UomId,
        u.UomCode                           AS UomName,
        il.UnitCost,
        ISNULL(SUM(
            CASE WHEN r.Status IN ('Draft','Confirmed') THEN rl.ReturnQty ELSE 0 END
        ), 0)                               AS AlreadyReturnedQty,
        il.Qty - ISNULL(SUM(
            CASE WHEN r.Status IN ('Draft','Confirmed') THEN rl.ReturnQty ELSE 0 END
        ), 0)                               AS AvailableToReturnQty
    FROM proj.TBL_STOCK_ISSUE_LINE il
    JOIN proj.TBL_ITEM it ON it.ItemId = il.ItemId
    LEFT JOIN proj.TBL_ITEM_UOM u ON u.UomId = il.UomId
    LEFT JOIN proj.TBL_STOCK_ISSUE_RETURN_LINE rl ON rl.IssueLineId = il.IssueLineId
    LEFT JOIN proj.TBL_STOCK_ISSUE_RETURN r ON r.ReturnId = rl.ReturnId AND r.IsActive = 1
    WHERE il.IssueId = @IssueId AND il.IsActive = 1
    GROUP BY
        il.IssueLineId, il.IssueId, il.LineNum, il.ItemId,
        it.ItemCode, it.ItemName, il.ItemDesc, il.Qty,
        il.UomId, u.UomCode, il.UnitCost
    HAVING il.Qty - ISNULL(SUM(
        CASE WHEN r.Status IN ('Draft','Confirmed') THEN rl.ReturnQty ELSE 0 END
    ), 0) > 0
    ORDER BY il.LineNum;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetIssueReturn]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetIssueReturn];
GO
CREATE PROCEDURE proj.sp_GetIssueReturn
    @ReturnId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        r.ReturnId,
        r.ReturnNo,
        r.ReturnDate,
        r.IssueId,
        i.IssueNo,
        i.JobId,
        i.CostingType,
        i.IssuedTo,
        r.ReturnedBy,
        r.Notes,
        r.Status,
        r.CreatedBy,
        r.CreatedDate,
        r.ModifiedBy,
        r.ModifiedDate,
        (SELECT TOP 1 sl.TransDate
         FROM proj.TBL_STOCK_LEDGER sl
         WHERE sl.TransType = 'RETURN' AND sl.RefId = r.ReturnId
         ORDER BY sl.LedgerId DESC)  AS PostedDate
    FROM proj.TBL_STOCK_ISSUE_RETURN r
    JOIN proj.TBL_STOCK_ISSUE i ON i.IssueId = r.IssueId
    WHERE r.ReturnId = @ReturnId AND r.IsActive = 1;

    SELECT
        rl.ReturnLineId,
        rl.ReturnId,
        rl.IssueLineId,
        rl.LineNum,
        rl.ItemId,
        it.ItemCode,
        it.ItemName,
        rl.ItemDesc,
        rl.ReturnQty,
        rl.UomId,
        u.UomCode  AS UomName,
        rl.UnitCost,
        ROUND(rl.ReturnQty * rl.UnitCost, 2) AS TotalCost,
        rl.Notes,
        rl.CreatedBy,
        rl.CreatedDate
    FROM proj.TBL_STOCK_ISSUE_RETURN_LINE rl
    JOIN proj.TBL_ITEM it ON it.ItemId = rl.ItemId
    LEFT JOIN proj.TBL_ITEM_UOM u ON u.UomId = rl.UomId
    WHERE rl.ReturnId = @ReturnId
    ORDER BY rl.LineNum;
END;
GO

