IF OBJECT_ID(N'[proj].[sp_GetItemDefaults]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetItemDefaults];
GO

CREATE   PROCEDURE proj.sp_GetItemDefaults
    @ItemId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        i.ItemId,
        i.BaseUomId,
        u.UomCode    AS BaseUomCode,
        ISNULL(
            (
                SELECT TOP 1 pol.UnitPrice
                FROM   proj.TBL_PURCHASE_ORDER_LINE pol
                JOIN   proj.TBL_PURCHASE_ORDER      po  ON po.PoId = pol.PoId
                WHERE  pol.ItemId = i.ItemId
                AND    po.Status IN ('Approved','Sent','Partial','Received')
                ORDER  BY po.PoDate DESC, pol.PoLineId DESC
            ), 0
        ) AS LastPurchasePrice,
        ISNULL(
            (
                SELECT TOP 1 c.ShortName
                FROM   proj.TBL_PURCHASE_ORDER_LINE pol
                JOIN   proj.TBL_PURCHASE_ORDER      po  ON po.PoId = pol.PoId
                JOIN   proj.TBL_CURRENCY            c   ON c.CurrencyId = po.CurrencyId
                WHERE  pol.ItemId = i.ItemId
                AND    po.Status IN ('Approved','Sent','Partial','Received')
                ORDER  BY po.PoDate DESC, pol.PoLineId DESC
            ), ''
        ) AS LastPriceCurrency
    FROM  proj.TBL_ITEM      i
    JOIN  proj.TBL_ITEM_UOM  u ON u.UomId = i.BaseUomId
    WHERE i.ItemId = @ItemId;
END;
GO

