CREATE PROCEDURE proj.sp_GetItemDetails @ItemId INT AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        d.ItemDetailId, d.ItemId, d.SKUCode,
        d.CountryOfOriginId, cy.CountryName,
        d.Brand, d.Model, d.Colour, d.Size, d.Grade,
        d.SupplierPartNo, d.ManufacturerPartNo,
        d.StandardCost, d.ListPrice,
        d.Weight, d.WeightUom, d.LeadTimeDays, d.ShelfLifeDays,
        d.MinStockLevel, d.MaxStockLevel, d.ReorderLevel,
        d.IsDefault, d.IsActive,
        d.CreatedBy, d.CreatedDate, d.ModifiedBy, d.ModifiedDate
    FROM proj.TBL_ITEM_DETAIL d
    LEFT JOIN proj.TBL_COUNTRY cy ON cy.CountryId = d.CountryOfOriginId
