IF OBJECT_ID(N'[proj].[sp_GetJobBudget]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetJobBudget];
GO

CREATE PROCEDURE proj.sp_GetJobBudget
    @JobId NVARCHAR(50),
    @RvNo  INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @LatestRv INT = ISNULL((SELECT MAX(RvNo) FROM proj.TBL_JOB_BUDGET WHERE JobId = @JobId), 0);
    DECLARE @TargetRv INT = ISNULL(@RvNo, @LatestRv);

    -- Result 1: header (for the SELECTED revision)
    SELECT
        @JobId      AS JobId,
        @TargetRv   AS CurrentRvNo,          -- the revision being shown
        @LatestRv   AS LatestRvNo,
        CASE WHEN @TargetRv < @LatestRv THEN 1 ELSE 0 END AS IsHistorical,
        ISNULL((SELECT TOP 1 IsApproved FROM proj.TBL_JOB_BUDGET WHERE JobId=@JobId AND RvNo=@TargetRv), 0) AS IsApproved,
        (SELECT TOP 1 ApprovedBy   FROM proj.TBL_JOB_BUDGET WHERE JobId=@JobId AND RvNo=@TargetRv AND IsApproved=1) AS ApprovedBy,
        (SELECT TOP 1 ApprovedDate FROM proj.TBL_JOB_BUDGET WHERE JobId=@JobId AND RvNo=@TargetRv AND IsApproved=1) AS ApprovedDate,
        (SELECT COUNT(DISTINCT RvNo) FROM proj.TBL_JOB_BUDGET WHERE JobId=@JobId) AS TotalRevisions;

    -- Result 2: lines for the selected revision
    SELECT
        ec.ExpenseCategoryId            AS CostCategoryId,
        ec.CategoryCode, ec.CategoryName, ec.SortOrder,
        b.JobBudgetId,
        @TargetRv                       AS RvNo,
        ISNULL(b.BudgetedAmount, 0)     AS BudgetedAmount,
        b.Qty, b.UnitPrice, b.UomId, u.UomCode, u.UomName, b.Notes,
        b.CurrencyId, cur.ShortName     AS CurrencyShort, b.ExchangeRate,
        ISNULL(b.AmountInBaseCurrency, proj.fn_ToBase(ISNULL(b.BudgetedAmount,0), ISNULL(b.ExchangeRate,1))) AS AmountInBaseCurrency,
        ISNULL(b.IsApproved, 0)         AS IsApproved,
        b.CreatedBy, b.CreatedDate, b.ModifiedBy, b.ModifiedDate,
        ISNULL(a.ActualAmount, 0)       AS ActualAmount,
        ISNULL(b.AmountInBaseCurrency, proj.fn_ToBase(ISNULL(b.BudgetedAmount,0), ISNULL(b.ExchangeRate,1)))
          - ISNULL(a.ActualAmount, 0)   AS Variance
    FROM  proj.TBL_JOB_EXPENSE_CATEGORY ec
    LEFT JOIN proj.TBL_JOB_BUDGET b
           ON b.JobId = @JobId AND b.CostCategoryId = ec.ExpenseCategoryId AND b.RvNo = @TargetRv
    LEFT JOIN proj.TBL_ITEM_UOM u   ON u.UomId      = b.UomId
    LEFT JOIN proj.TBL_CURRENCY  cur ON cur.CurrencyId = b.CurrencyId
    LEFT JOIN proj.VW_JOB_COST_ACTUAL a
           ON a.JobId = @JobId AND a.CostCategoryId = ec.ExpenseCategoryId
    WHERE ec.IsActive = 1 AND ec.UsedForBudget = 1
    ORDER BY ec.SortOrder;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetJobBudgetItemLog]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetJobBudgetItemLog];
GO

CREATE PROCEDURE proj.sp_GetJobBudgetItemLog
    @JobId  NVARCHAR(50),
    @RvNo   INT = NULL,
    @ItemId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        l.LogId, l.BudgetItemId, l.JobId, l.RvNo, l.CostCategoryId,
        ec.CategoryName AS BudgetHeader,
        l.ItemId, i.ItemCode, i.ItemName,
        l.Action, l.OldQty, l.NewQty,
        (ISNULL(l.NewQty,0) - ISNULL(l.OldQty,0)) AS QtyDelta,
        l.OldUnitPrice, l.NewUnitPrice,
        l.Reason,
        l.ChangedBy, l.ChangedDate
    FROM proj.TBL_JOB_BUDGET_ITEM_LOG l
    LEFT JOIN proj.TBL_JOB_EXPENSE_CATEGORY ec ON ec.ExpenseCategoryId = l.CostCategoryId
    LEFT JOIN proj.TBL_ITEM i ON i.ItemId = l.ItemId
    WHERE l.JobId = @JobId
      AND (@RvNo   IS NULL OR l.RvNo   = @RvNo)
      AND (@ItemId IS NULL OR l.ItemId = @ItemId)
    ORDER BY l.ChangedDate DESC, l.LogId DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetJobBudgetItems]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetJobBudgetItems];
GO

-- 2. Add LastPurchasePrice + currency to sp_GetJobBudgetItems
CREATE PROCEDURE proj.sp_GetJobBudgetItems
    @JobId NVARCHAR(50),
    @RvNo  INT = NULL,
    @CostCategoryId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Rv INT = ISNULL(@RvNo, (SELECT MAX(RvNo) FROM proj.TBL_JOB_BUDGET WHERE JobId=@JobId));
    SELECT bi.BudgetItemId, bi.JobId, bi.RvNo, bi.CostCategoryId,
           ec.CategoryName AS BudgetHeader, ec.CategoryCode AS BudgetHeaderCode,
           bi.ItemId, i.ItemCode, i.ItemName, i.IsPurchasable,
           bi.Qty, bi.UomId, u.UomCode, bi.UnitPrice,
           (bi.Qty * bi.UnitPrice) AS LineTotal, bi.Notes,
           -- Last purchase price hint (most recent confirmed PO line for this item)
           lpp.LastPurchasePrice, lpp.LastPurchaseCurrencyShort
    FROM proj.TBL_JOB_BUDGET_ITEM bi
    LEFT JOIN proj.TBL_JOB_EXPENSE_CATEGORY ec ON ec.ExpenseCategoryId = bi.CostCategoryId
    LEFT JOIN proj.TBL_ITEM     i ON i.ItemId = bi.ItemId
    LEFT JOIN proj.TBL_ITEM_UOM u ON u.UomId  = bi.UomId
    OUTER APPLY (
        SELECT TOP 1 pol.UnitPrice AS LastPurchasePrice, cur.ShortName AS LastPurchaseCurrencyShort
        FROM proj.TBL_PURCHASE_ORDER_LINE pol
        JOIN proj.TBL_PURCHASE_ORDER po  ON po.PoId      = pol.PoId
        LEFT JOIN proj.TBL_CURRENCY  cur ON cur.CurrencyId = po.CurrencyId
        WHERE pol.ItemId = bi.ItemId AND pol.UnitPrice > 0
        ORDER BY po.PoDate DESC
    ) lpp
    WHERE bi.JobId=@JobId AND bi.RvNo=@Rv AND bi.IsActive=1
      AND (@CostCategoryId IS NULL OR bi.CostCategoryId=@CostCategoryId)
    ORDER BY ec.SortOrder, i.ItemCode;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetJobBudgetRevisions]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetJobBudgetRevisions];
GO

CREATE   PROCEDURE proj.sp_GetJobBudgetRevisions
    @JobId NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @LatestRv INT = ISNULL((SELECT MAX(RvNo) FROM proj.TBL_JOB_BUDGET WHERE JobId=@JobId), 0);
    SELECT
        b.RvNo,
        MAX(CAST(b.IsApproved AS INT))                          AS IsApproved,
        CASE WHEN b.RvNo = @LatestRv THEN 1 ELSE 0 END          AS IsCurrent,
        MAX(b.ApprovedBy)                                       AS ApprovedBy,
        MAX(b.ApprovedDate)                                     AS ApprovedDate,
        MAX(b.RevisionReason)                                   AS RevisionReason,
        SUM(ISNULL(b.AmountInBaseCurrency,
            proj.fn_ToBase(ISNULL(b.BudgetedAmount,0), ISNULL(b.ExchangeRate,1)))) AS TotalBudgetBase
    FROM proj.TBL_JOB_BUDGET b
    WHERE b.JobId = @JobId
    GROUP BY b.RvNo
    ORDER BY b.RvNo DESC;
END
GO

