IF OBJECT_ID(N'[proj].[sp_GetJobCloseReadiness]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetJobCloseReadiness];
GO
CREATE   PROCEDURE proj.sp_GetJobCloseReadiness
    @JobId  NVARCHAR(50),
    @Action NVARCHAR(10)   -- 'complete' or 'cancel'
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @IsInHouseJob BIT = 0;
    SELECT @IsInHouseJob = ISNULL(jt.IsBudgetHeaderLinked, 0)
    FROM proj.TBL_JOB j
    JOIN proj.TBL_JOBTYPE jt ON jt.JobTypeId = j.JobTypeId
    WHERE j.JobId = @JobId;

    -- Load check labels from VList once
    CREATE TABLE #Labels (CheckKey NVARCHAR(50), Label NVARCHAR(200));
    INSERT INTO #Labels (CheckKey, Label)
    SELECT ItemValue, ItemDescription FROM proj.TBL_VLIST
    WHERE TypeName = 'Job' AND ListName = 'CloseCheck' AND IsActive = 1;

    CREATE TABLE #Checks (
        SortOrder  INT,
        CheckKey   NVARCHAR(50),
        CheckLabel NVARCHAR(300),
        Passed     BIT,
        Detail     NVARCHAR(MAX) NULL
    );

    -- ── 1. Remaining stock (both) ─────────────────────────────────────────
    DECLARE @StockCount INT = 0, @StockDetail NVARCHAR(MAX) = N'';
    SELECT @StockCount = COUNT(*) FROM (
        SELECT sl.ItemId FROM proj.TBL_STOCK_LEDGER sl
        WHERE sl.JobId = @JobId GROUP BY sl.ItemId HAVING SUM(sl.QtyIn - sl.QtyOut) > 0
    ) x;
    IF @StockCount > 0
        SELECT @StockDetail = STRING_AGG(i.ItemCode + ' (' + CAST(CAST(net.NetQty AS DECIMAL(18,2)) AS NVARCHAR(30)) + ')', ', ')
        FROM (SELECT sl.ItemId, SUM(sl.QtyIn - sl.QtyOut) AS NetQty FROM proj.TBL_STOCK_LEDGER sl
              WHERE sl.JobId = @JobId GROUP BY sl.ItemId HAVING SUM(sl.QtyIn - sl.QtyOut) > 0) net
        JOIN proj.TBL_ITEM i ON i.ItemId = net.ItemId;
    INSERT INTO #Checks VALUES (1, 'stock',
        ISNULL((SELECT Label FROM #Labels WHERE CheckKey = 'stock'), 'No remaining stock in job bucket'),
        CASE WHEN @StockCount = 0 THEN 1 ELSE 0 END,
        CASE WHEN @StockCount > 0 THEN CAST(@StockCount AS NVARCHAR(10)) + ' item(s) still have stock: ' + @StockDetail ELSE NULL END);

    -- ── 2. Draft issue notes (both) ───────────────────────────────────────
    DECLARE @DraftIssues INT = (SELECT COUNT(*) FROM proj.TBL_STOCK_ISSUE WHERE JobId = @JobId AND IsActive = 1 AND Status = 'Draft');
    INSERT INTO #Checks VALUES (2, 'draftIssues',
        ISNULL((SELECT Label FROM #Labels WHERE CheckKey = 'draftIssues'), 'No draft issue notes'),
        CASE WHEN @DraftIssues = 0 THEN 1 ELSE 0 END,
        CASE WHEN @DraftIssues > 0 THEN CAST(@DraftIssues AS NVARCHAR(10)) + ' draft issue note(s) must be confirmed or deleted' ELSE NULL END);

    -- ── 3. Draft GRNs (both) ──────────────────────────────────────────────
    DECLARE @DraftGRNs INT = 0, @GrnDetail NVARCHAR(MAX) = N'';
    SELECT @DraftGRNs = COUNT(*) FROM proj.TBL_STOCK_RECEIPT WHERE JobId = @JobId AND IsActive = 1 AND Status = 'Draft';
    IF @DraftGRNs > 0
        SELECT @GrnDetail = STRING_AGG(ReceiptNo, ', ') FROM proj.TBL_STOCK_RECEIPT WHERE JobId = @JobId AND IsActive = 1 AND Status = 'Draft';
    INSERT INTO #Checks VALUES (3, 'draftGRNs',
        ISNULL((SELECT Label FROM #Labels WHERE CheckKey = 'draftGRNs'), 'No draft GRNs'),
        CASE WHEN @DraftGRNs = 0 THEN 1 ELSE 0 END,
        CASE WHEN @DraftGRNs > 0 THEN CAST(@DraftGRNs AS NVARCHAR(10)) + ' draft GRN(s) must be confirmed or deleted: ' + @GrnDetail ELSE NULL END);

    -- ── 4. Open purchase orders (both) ────────────────────────────────────
    DECLARE @OpenPos INT = 0, @PoDetail NVARCHAR(MAX) = N'';
    SELECT @OpenPos = COUNT(*) FROM proj.TBL_PURCHASE_ORDER WHERE JobId = @JobId AND IsActive = 1 AND Status NOT IN (N'Cancelled', N'Closed', N'Received');
    IF @OpenPos > 0
        SELECT @PoDetail = STRING_AGG(PoNumber, ', ') FROM proj.TBL_PURCHASE_ORDER WHERE JobId = @JobId AND IsActive = 1 AND Status NOT IN (N'Cancelled', N'Closed', N'Received');
    INSERT INTO #Checks VALUES (4, 'openPos',
        ISNULL((SELECT Label FROM #Labels WHERE CheckKey = 'openPos'), 'No open purchase orders'),
        CASE WHEN @OpenPos = 0 THEN 1 ELSE 0 END,
        CASE WHEN @OpenPos > 0 THEN CAST(@OpenPos AS NVARCHAR(10)) + ' open PO(s): ' + @PoDetail ELSE NULL END);

    -- ── 5. Open purchase requests (both) ─────────────────────────────────
    DECLARE @OpenPRs INT = 0, @PrDetail NVARCHAR(MAX) = N'';
    SELECT @OpenPRs = COUNT(*) FROM proj.TBL_PURCHASE_REQUEST WHERE JobId = @JobId AND IsActive = 1 AND Status NOT IN (N'Cancelled', N'Closed');
    IF @OpenPRs > 0
        SELECT @PrDetail = STRING_AGG(PrNumber, ', ') FROM proj.TBL_PURCHASE_REQUEST WHERE JobId = @JobId AND IsActive = 1 AND Status NOT IN (N'Cancelled', N'Closed');
    INSERT INTO #Checks VALUES (5, 'openPRs',
        ISNULL((SELECT Label FROM #Labels WHERE CheckKey = 'openPRs'), 'No open purchase requests'),
        CASE WHEN @OpenPRs = 0 THEN 1 ELSE 0 END,
        CASE WHEN @OpenPRs > 0 THEN CAST(@OpenPRs AS NVARCHAR(10)) + ' open PR(s): ' + @PrDetail ELSE NULL END);

    -- ── 6. Variations ─────────────────────────────────────────────────────
    IF @Action = 'cancel'
    BEGIN
        DECLARE @PendingVars INT = 0, @VarDetail NVARCHAR(MAX) = N'';
        SELECT @PendingVars = COUNT(*) FROM proj.TBL_JOB WHERE ParentJobId = @JobId AND ISNULL(JobStatusId, 0) <> 5;
        IF @PendingVars > 0
            SELECT @VarDetail = STRING_AGG(JobId, ', ') FROM proj.TBL_JOB WHERE ParentJobId = @JobId AND ISNULL(JobStatusId, 0) <> 5;
        INSERT INTO #Checks VALUES (6, 'variations',
            ISNULL((SELECT Label FROM #Labels WHERE CheckKey = 'variations'), 'All additional jobs cancelled'),
            CASE WHEN @PendingVars = 0 THEN 1 ELSE 0 END,
            CASE WHEN @PendingVars > 0 THEN CAST(@PendingVars AS NVARCHAR(10)) + ' additional job(s) must be cancelled: ' + @VarDetail ELSE NULL END);
    END
    ELSE
    BEGIN
        DECLARE @OpenVars INT = 0, @VarDetailC NVARCHAR(MAX) = N'';
        SELECT @OpenVars = COUNT(*) FROM proj.TBL_JOB WHERE ParentJobId = @JobId AND ISNULL(JobStatusId, 0) NOT IN (4, 5);
        IF @OpenVars > 0
            SELECT @VarDetailC = STRING_AGG(JobId, ', ') FROM proj.TBL_JOB WHERE ParentJobId = @JobId AND ISNULL(JobStatusId, 0) NOT IN (4, 5);
        INSERT INTO #Checks VALUES (6, 'variationsComplete',
            ISNULL((SELECT Label FROM #Labels WHERE CheckKey = 'variationsComplete'), 'All additional jobs completed or cancelled'),
            CASE WHEN @OpenVars = 0 THEN 1 ELSE 0 END,
            CASE WHEN @OpenVars > 0 THEN CAST(@OpenVars AS NVARCHAR(10)) + ' additional job(s) still open: ' + @VarDetailC ELSE NULL END);
    END

    -- ── 7+. Cancel-only ───────────────────────────────────────────────────
    IF @Action = 'cancel'
    BEGIN
        DECLARE @ActiveInvoices INT = (
            SELECT COUNT(*) FROM proj.TBL_INVOICE i
            WHERE (i.JobId = @JobId OR i.JobId IN (SELECT JobId FROM proj.TBL_JOB WHERE ParentJobId = @JobId))
              AND ISNULL(i.Status, N'') NOT IN (N'CANCELLED', N'VOID')
        );
        INSERT INTO #Checks VALUES (7, 'invoices',
            ISNULL((SELECT Label FROM #Labels WHERE CheckKey = 'invoices'), 'No active invoices'),
            CASE WHEN @ActiveInvoices = 0 THEN 1 ELSE 0 END,
            CASE WHEN @ActiveInvoices > 0 THEN CAST(@ActiveInvoices AS NVARCHAR(10)) + ' active invoice(s) must be cancelled first' ELSE NULL END);

        DECLARE @ActiveReceipts INT = (
            SELECT COUNT(DISTINCT rv.RvId) FROM proj.TBL_RECEIPT_VOUCHER rv
            JOIN proj.TBL_RECEIPT_VOUCHER_ALLOCATION a ON a.RvId = rv.RvId AND ISNULL(a.IsActive, 1) = 1
            JOIN proj.TBL_INVOICE i ON i.InvoiceId = a.InvoiceId
            WHERE (i.JobId = @JobId OR i.JobId IN (SELECT JobId FROM proj.TBL_JOB WHERE ParentJobId = @JobId))
              AND ISNULL(rv.IsActive, 1) = 1 AND ISNULL(rv.Status, N'') NOT IN (N'CANCELLED', N'VOID')
        );
        INSERT INTO #Checks VALUES (8, 'receipts',
            ISNULL((SELECT Label FROM #Labels WHERE CheckKey = 'receipts'), 'No active receipt vouchers (RV)'),
            CASE WHEN @ActiveReceipts = 0 THEN 1 ELSE 0 END,
            CASE WHEN @ActiveReceipts > 0 THEN CAST(@ActiveReceipts AS NVARCHAR(10)) + ' active receipt voucher(s) must be cancelled first' ELSE NULL END);
    END

    -- ── 7+. Complete-only ─────────────────────────────────────────────────
    IF @Action = 'complete'
    BEGIN
        DECLARE @DraftInvoices INT = 0, @InvDetail NVARCHAR(MAX) = N'';
        SELECT @DraftInvoices = COUNT(*) FROM proj.TBL_INVOICE WHERE JobId = @JobId AND IsActive = 1 AND Status = 'Draft';
        IF @DraftInvoices > 0
            SELECT @InvDetail = STRING_AGG(InvoiceNo, ', ') FROM proj.TBL_INVOICE WHERE JobId = @JobId AND IsActive = 1 AND Status = 'Draft';
        INSERT INTO #Checks VALUES (7, 'draftInvoices',
            ISNULL((SELECT Label FROM #Labels WHERE CheckKey = 'draftInvoices'), 'No draft invoices'),
            CASE WHEN @DraftInvoices = 0 THEN 1 ELSE 0 END,
            CASE WHEN @DraftInvoices > 0 THEN CAST(@DraftInvoices AS NVARCHAR(10)) + ' invoice(s) still in Draft — confirm or delete: ' + @InvDetail ELSE NULL END);

        DECLARE @OpenMOM INT = (SELECT COUNT(*) FROM proj.TBL_MOM_TASK WHERE JobId = @JobId AND IsActive = 1 AND Status = 'Open');
        INSERT INTO #Checks VALUES (8, 'momTasks',
            ISNULL((SELECT Label FROM #Labels WHERE CheckKey = 'momTasks'), 'No open MOM tasks'),
            CASE WHEN @OpenMOM = 0 THEN 1 ELSE 0 END,
            CASE WHEN @OpenMOM > 0 THEN CAST(@OpenMOM AS NVARCHAR(10)) + ' open MOM task(s) must be closed or cancelled' ELSE NULL END);

        IF @IsInHouseJob = 1
        BEGIN
            INSERT INTO #Checks VALUES (9, 'financial',
                ISNULL((SELECT Label FROM #Labels WHERE CheckKey = 'financial'), 'Financial check (N/A — in-house job)'),
                1, NULL);
        END
        ELSE
        BEGIN
            DECLARE @OrderValueBase DECIMAL(18,2) = 0, @TotalInvoiced DECIMAL(18,2) = 0, @TotalPaid DECIMAL(18,2) = 0;
            SELECT @OrderValueBase = ISNULL(jf.OrderValue * ISNULL(jf.ExchangeRate, 1), 0),
                   @TotalInvoiced  = ISNULL(jf.TotalInvoicing, 0),
                   @TotalPaid      = ISNULL(jf.TotalPayments,  0)
            FROM proj.TBL_JOB_FINANCE jf WHERE jf.JobId = @JobId;

            DECLARE @InvoiceOk BIT = CASE WHEN @TotalInvoiced >= @OrderValueBase * 0.99 THEN 1 ELSE 0 END;
            DECLARE @PaymentOk BIT = CASE WHEN @TotalPaid     >= @TotalInvoiced  * 0.99 THEN 1 ELSE 0 END;

            INSERT INTO #Checks VALUES (9, 'invoicing',
                ISNULL((SELECT Label FROM #Labels WHERE CheckKey = 'invoicing'), 'Invoiced ≥ 99% of order value')
                    + ' (' + FORMAT(@OrderValueBase * 0.99, 'N2') + ')',
                @InvoiceOk,
                CASE WHEN @InvoiceOk = 0 THEN 'Invoiced ' + FORMAT(@TotalInvoiced, 'N2') + ' of required ' + FORMAT(@OrderValueBase * 0.99, 'N2') ELSE NULL END);

            INSERT INTO #Checks VALUES (10, 'payment',
                ISNULL((SELECT Label FROM #Labels WHERE CheckKey = 'payment'), 'Paid ≥ 99% of total invoiced')
                    + ' (' + FORMAT(@TotalInvoiced * 0.99, 'N2') + ')',
                @PaymentOk,
                CASE WHEN @PaymentOk = 0 THEN 'Paid ' + FORMAT(@TotalPaid, 'N2') + ' of required ' + FORMAT(@TotalInvoiced * 0.99, 'N2') ELSE NULL END);
        END
    END

    SELECT SortOrder, CheckKey, CheckLabel, Passed, Detail FROM #Checks ORDER BY SortOrder;
    DROP TABLE #Labels;
    DROP TABLE #Checks;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetJobCompletionCheck]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetJobCompletionCheck];
GO

CREATE   PROCEDURE proj.sp_GetJobCompletionCheck
    @JobId NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        j.JobId,
        ISNULL(jf.OrderValue, 0)                                         AS OrderValue,
        ISNULL(jf.OrderValue, 0) * ISNULL(jf.ExchangeRate, 1)           AS OrderValueBase,
        ISNULL(jf.TotalInvoicing, 0)                                     AS TotalInvoiced,
        ISNULL(jf.TotalPayments,  0)                                     AS TotalPaid,
        CASE WHEN ISNULL(jf.OrderValue,0) * ISNULL(jf.ExchangeRate,1) = 0 THEN CAST(0 AS DECIMAL(10,2))
             ELSE CAST(ROUND(ISNULL(jf.TotalInvoicing,0)
                        / (ISNULL(jf.OrderValue,0) * ISNULL(jf.ExchangeRate,1)) * 100, 2) AS DECIMAL(10,2))
        END                                                              AS InvoicedPct,
        CASE WHEN ISNULL(jf.TotalInvoicing,0) = 0 THEN CAST(0 AS DECIMAL(10,2))
             ELSE CAST(ROUND(ISNULL(jf.TotalPayments,0)
                        / ISNULL(jf.TotalInvoicing,0) * 100, 2) AS DECIMAL(10,2))
        END                                                              AS PaidPct,
        CASE WHEN ISNULL(jf.TotalInvoicing,0)
                  >= ISNULL(jf.OrderValue,0) * ISNULL(jf.ExchangeRate,1) * 0.99
             THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END                AS InvoiceOk,
        CASE WHEN ISNULL(jf.TotalPayments,0)
                  >= ISNULL(jf.TotalInvoicing,0) * 0.99
             THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END                AS PaymentOk,
        CASE WHEN ISNULL(jf.TotalInvoicing,0)
                  >= ISNULL(jf.OrderValue,0) * ISNULL(jf.ExchangeRate,1) * 0.99
              AND  ISNULL(jf.TotalPayments,0)
                  >= ISNULL(jf.TotalInvoicing,0) * 0.99
             THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END                AS CanComplete,
        c.ShortName                                                      AS CurrencyCode,
        ISNULL(jf.ExchangeRate, 1)                                       AS ExchangeRate
    FROM proj.TBL_JOB j
    LEFT JOIN proj.TBL_JOB_FINANCE jf ON jf.JobId      = j.JobId
    LEFT JOIN proj.TBL_CURRENCY    c  ON c.CurrencyId  = j.JobCurrencyId
    WHERE j.JobId = @JobId;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetJobEngineers]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetJobEngineers];
GO

CREATE   PROCEDURE PROJ.sp_GetJobEngineers @JobId NVARCHAR(50) AS
BEGIN
    SET NOCOUNT ON;
    SELECT je.JobEngineerId, je.JobId, je.EngineerId,
           e.EngineerName, e.Email,
           je.Role, je.AssignedDate, je.AssignedBy, je.Completed,
           je.ModifiedBy, je.ModifiedDate
    FROM PROJ.TBL_JOB_ENGINEER je
    INNER JOIN PROJ.TBL_ENGINEER e ON je.EngineerId = e.EngineerId
    WHERE je.JobId = @JobId ORDER BY je.AssignedDate;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetJobExpenseCategoryList]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetJobExpenseCategoryList];
GO

CREATE PROCEDURE proj.sp_GetJobExpenseCategoryList AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        ExpenseCategoryId,
        CategoryCode,
        CategoryName,
        SortOrder
    FROM proj.TBL_JOB_EXPENSE_CATEGORY
    WHERE IsActive = 1 AND UsedForExpense = 1
    ORDER BY SortOrder, ExpenseCategoryId;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetJobExpenses]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetJobExpenses];
GO
CREATE PROCEDURE proj.sp_GetJobExpenses @JobId NVARCHAR(50) AS
BEGIN
    SET NOCOUNT ON;
    SELECT e.ExpenseId, e.JobId, e.ExpenseCategoryId, ec.CategoryName,
           e.ExpenseDescription, e.ExpenseAmount, e.ExpenseDate,
           e.CurrencyId, cur.ShortName AS CurrencyName,
           e.ExchangeRate, e.AmountInBaseCurrency,
           e.ReferenceNo, e.Remarks,
           e.IsApproved, e.ApprovedBy, e.ApprovedDate,
           e.CreatedBy, e.CreatedDate, e.ModifiedBy, e.ModifiedDate
    FROM proj.TBL_JOB_EXPENSE e
    LEFT JOIN proj.TBL_JOB_EXPENSE_CATEGORY ec ON e.ExpenseCategoryId = ec.ExpenseCategoryId
    LEFT JOIN proj.TBL_CURRENCY cur ON e.CurrencyId = cur.CurrencyId
    WHERE e.JobId = @JobId AND e.IsDeleted = 0
    ORDER BY e.ExpenseDate DESC, e.ExpenseId DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetJobLifecycle]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetJobLifecycle];
GO
CREATE   PROCEDURE proj.sp_GetJobLifecycle
    @JobId NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT  CompletedDate, CompletedReason, CompletedBy,
            CancelledDate, CancelledReason, CancelledBy
    FROM    proj.TBL_JOB
    WHERE   JobId = @JobId;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetJobLockState]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetJobLockState];
GO
CREATE   PROCEDURE proj.sp_GetJobLockState
    @JobId NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT  j.JobId,
            j.JobStatusId,
            js.StatusName,
            CAST(proj.fn_IsJobLocked(j.JobId) AS BIT)              AS IsLocked,
            CAST(CASE WHEN j.JobStatusId IN (3,4,5) THEN 1 ELSE 0 END AS BIT) AS IsClosed,
            CAST(CASE WHEN j.JobStatusId = 4 THEN 1 ELSE 0 END AS BIT)        AS IsCompleted,
            CAST(CASE WHEN j.JobStatusId = 5 THEN 1 ELSE 0 END AS BIT)        AS IsCancelled,
            j.CompletedDate, j.CompletedReason, j.CompletedBy,
            j.CancelledDate, j.CancelledReason, j.CancelledBy
    FROM    proj.TBL_JOB j
    JOIN    proj.TBL_JOB_STATUS js ON js.JobStatusId = j.JobStatusId
    WHERE   j.JobId = @JobId;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetJobMaterialsForPR]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetJobMaterialsForPR];
GO

CREATE PROCEDURE proj.sp_GetJobMaterialsForPR
    @JobId  NVARCHAR(50),
    @PrId   INT = 0
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        bd.BomId                                        AS bomDetailId,
        bd.ItemId                                       AS componentItemId,
        i.ItemCode                                      AS componentItemCode,
        i.ItemName                                      AS componentItemName,
        bd.BomRequestedQty                              AS plannedQty,
        ISNULL(bd.BomReceivedQty, 0)                    AS issuedQty,
        bd.BomRequestedQty - ISNULL(bd.PrCreatedQty,0) AS remainingQty,
        bd.UomId                                        AS uomId,
        u.UomName                                       AS uomName,
        bd.Remarks                                      AS remarks,
        CAST(CASE WHEN @PrId > 0 AND EXISTS (
            SELECT 1 FROM proj.TBL_PURCHASE_REQUEST_LINE prl
            WHERE prl.BomDetailId = bd.BomId
              AND prl.PrId        = @PrId
              AND prl.IsActive    = 1
        ) THEN 1 ELSE 0 END AS BIT)                    AS alreadyAdded,
        bs.SectionName                                  AS sectionName,
        bd.BomPrice                                     AS unitPrice,
        bd.BomStatus                                    AS status,
        bd.SortOrder
    FROM proj.TBL_BOM_DETAILS bd
    JOIN  proj.TBL_BOM_HEADER  bh ON bh.BomHeaderId = bd.BomHeaderId
    LEFT JOIN proj.TBL_ITEM    i  ON i.ItemId        = bd.ItemId
    LEFT JOIN proj.TBL_ITEM_UOM u ON u.UomId         = bd.UomId
    LEFT JOIN proj.TBL_BOM_SECTION bs ON bs.BomSectionId = bd.BomSectionId
    WHERE bd.JobId    = @JobId
      AND bd.IsActive = 1
      AND bh.IsActive = 1
      AND bh.BomStatus = 'Approved'
      AND bd.BomRequestedQty - ISNULL(bd.PrCreatedQty, 0) > 0
    ORDER BY bd.SortOrder, bd.BomId;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetJobMeta]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetJobMeta];
GO
CREATE   PROCEDURE proj.sp_GetJobMeta
    @JobId NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        m.JobId,
        m.BayId,
        b.BayName,
        m.JobCategoryId,
        c.JobCategoryName,
        m.QualityLevelId,
        q.QualityLevelName,
        q.Description   AS QualityDescription,
        m.TotalUnits,
        m.DeliveredUnit,
        m.CreatedBy,
        m.CreatedDate,
        m.ModifiedBy,
        m.ModifiedDate
    FROM proj.TBL_JOB_META m
    LEFT JOIN proj.TBL_JOB_BAY      b ON m.BayId          = b.BayId
    LEFT JOIN proj.TBL_JOB_CATEGORY c ON m.JobCategoryId   = c.JobCategoryId
    LEFT JOIN proj.TBL_JOB_QUALITY  q ON m.QualityLevelId  = q.QualityLevelId
    WHERE m.JobId = @JobId;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetJobOverview]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetJobOverview];
GO
CREATE PROCEDURE proj.sp_GetJobOverview
    @JobId NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @JobRate DECIMAL(18,6) = ISNULL((SELECT JobExcRate FROM proj.TBL_JOB WHERE JobId = @JobId), 1);
    DECLARE @Div     DECIMAL(18,6) = ISNULL(NULLIF(@JobRate, 0), 1);

    -- RS1: Job Header
    SELECT
        j.JobId, j.JobDescription, j.ProjectName, j.JobDate,
        j.LpoRef, j.LpoDate, j.ContractRef, j.ExternalRef,
        j.ParentJobId, j.ApprovalStatus,
        j.JobCreatedBy, j.JobCreatedDate, j.JobLastModifiedBy, j.JobLastUpdatedDate,
        jt.JobTypeId, jt.JobTypeName,
        js.JobStatusId, js.StatusName AS JobStatusName, js.IsClosed,
        jsg.JobStageId, jsg.JobStageName,
        c.CustomerId, c.CustomerCode, c.CustomerName,
        c.Phone AS CustomerPhone, c.Email AS CustomerEmail,
        cur.CurrencyId, cur.ShortName AS CurrencyCode, cur.Symbol AS CurrencySymbol,
        (SELECT ShortName FROM proj.TBL_CURRENCY WHERE IsBaseCurrency = 1) AS BaseCurrencyCode,
        j.JobExcRate AS ExchangeRate,
        jd.JobPlannedStartDate, jd.JobExpectedCompleteDate, jd.JobActualCompleteDate,
        jd.JobExpectedDeliveryDate, jd.JobActualDeliveryDate,
        jm.TotalUnits, bay.BayName,
        qual.QualityLevelName, cat.JobCategoryName,
        jtr.JobPaymentTerms, jtr.WarrantyTerms, jtr.JobDeliveryTerms,
        (SELECT STRING_AGG(e2.EngineerName, ', ')
         FROM proj.TBL_JOB_ENGINEER je2
         JOIN proj.TBL_ENGINEER e2 ON e2.EngineerId = je2.EngineerId
         WHERE je2.JobId = j.JobId) AS EngineerNames
    FROM proj.TBL_JOB j
    LEFT JOIN proj.TBL_JOBTYPE         jt   ON jt.JobTypeId       = j.JobTypeId
    LEFT JOIN proj.TBL_JOB_STATUS      js   ON js.JobStatusId     = j.JobStatusId
    LEFT JOIN proj.TBL_JOB_STAGE       jsg  ON jsg.JobStageId     = j.JobStageId
    LEFT JOIN proj.TBL_CUSTOMER        c    ON c.CustomerId        = j.CustomerId
    LEFT JOIN proj.TBL_CURRENCY        cur  ON cur.CurrencyId      = j.JobCurrencyId
    LEFT JOIN proj.TBL_JOB_DATES       jd   ON jd.JobId           = j.JobId
    LEFT JOIN proj.TBL_JOB_META        jm   ON jm.JobId           = j.JobId
    LEFT JOIN proj.TBL_JOB_BAY         bay  ON bay.BayId          = jm.BayId
    LEFT JOIN proj.TBL_JOB_QUALITY     qual ON qual.QualityLevelId = jm.QualityLevelId
    LEFT JOIN proj.TBL_JOB_CATEGORY    cat  ON cat.JobCategoryId   = jm.JobCategoryId
    LEFT JOIN proj.TBL_JOB_TERMS       jtr  ON jtr.JobId          = j.JobId
    WHERE j.JobId = @JobId;

    -- RS2: Financial Summary
    SELECT
        jf.OrderValue,
        jf.TotalInvoicing / @Div  AS TotalInvoicing,
        jf.TotalPayments  / @Div  AS TotalPayments,
        jf.TotalCredit    / @Div  AS TotalCredit,
        jf.BalanceAmount  / @Div  AS BalanceAmount,
        jf.JobAdvanceAmount,
        jf.IsLDApplicable, jf.LDAmount, jf.LDPercent, jf.ExchangeRate,
        ISNULL((SELECT SUM(ISNULL(AmountInBaseCurrency, proj.fn_ToBase(BudgetedAmount, ISNULL(ExchangeRate,1)))) FROM proj.TBL_JOB_BUDGET WHERE JobId = @JobId AND IsCurrent = 1), 0) / @Div AS TotalBudget,
        (ISNULL(vca.TotalActual, 0) + ISNULL(iss_t.IssueTotal, 0) - ISNULL(ret_t.ReturnTotal, 0)) / @Div AS TotalActual,
        ISNULL(po_t.PoTotal,      0) / @Div AS PoTotal,
        ISNULL(iss_t.IssueTotal,  0) / @Div AS IssueTotal,
        ISNULL(ret_t.ReturnTotal, 0) / @Div AS ReturnTotal,
        ISNULL(cout_t.CashOut,    0) / @Div AS CashOut,
        ISNULL(mh_t.ManhourTotal, 0) / @Div AS ManhourTotal,
        ISNULL(ex_t.ExpenseTotal, 0) / @Div AS ExpenseTotal,
        ISNULL(srv_t.ServiceTotal,0) / @Div AS ServiceTotal
    FROM proj.TBL_JOB_FINANCE jf
    OUTER APPLY (
        SELECT ISNULL(SUM(ActualAmount), 0) AS TotalActual
        FROM proj.VW_JOB_COST_ACTUAL WHERE JobId = @JobId
    ) vca
    OUTER APPLY (
        SELECT ISNULL(SUM(proj.fn_ToBase(pol.OrderedQty * pol.UnitPrice, po.ExchangeRate)), 0) AS PoTotal
        FROM proj.TBL_PURCHASE_ORDER po
        JOIN proj.TBL_PURCHASE_ORDER_LINE pol ON pol.PoId = po.PoId AND pol.IsActive = 1
        WHERE po.JobId = @JobId AND po.IsActive = 1
          AND po.Status NOT IN ('Draft','Cancelled') AND po.ExpenseCategoryId IS NOT NULL
    ) po_t
    OUTER APPLY (
        SELECT ISNULL(SUM(il.Qty * il.UnitCost), 0) AS IssueTotal
        FROM proj.TBL_STOCK_ISSUE i
        JOIN proj.TBL_STOCK_ISSUE_LINE il ON il.IssueId = i.IssueId AND il.IsActive = 1
        WHERE i.JobId = @JobId AND i.IsActive = 1 AND i.Status = 'Confirmed' AND i.CostingType != 'EXC_COSTING'
    ) iss_t
    OUTER APPLY (
        SELECT ISNULL(SUM(rl.ReturnQty * rl.UnitCost), 0) AS ReturnTotal
        FROM   proj.TBL_STOCK_ISSUE_RETURN      r
        JOIN   proj.TBL_STOCK_ISSUE_RETURN_LINE rl ON rl.ReturnId = r.ReturnId
        JOIN   proj.TBL_STOCK_ISSUE             ri ON ri.IssueId  = r.IssueId
        WHERE  ri.JobId = @JobId AND r.IsActive = 1
          AND  r.Status IN ('Confirmed', 'Approved')
    ) ret_t
    OUTER APPLY (
        SELECT ISNULL(SUM(pva.AllocatedAmount * sh.JobShare), 0) AS CashOut
        FROM   proj.TBL_PAYMENT_VOUCHER_ALLOCATION pva
        JOIN   proj.TBL_PAYMENT_VOUCHER             pv ON pv.PvId = pva.PvId
        CROSS APPLY (
            SELECT CASE
                WHEN pva.PoId IS NOT NULL THEN
                    (SELECT CASE WHEN po3.JobId = @JobId THEN 1.0 ELSE 0 END
                     FROM proj.TBL_PURCHASE_ORDER po3
                     WHERE po3.PoId = pva.PoId)
                ELSE
                    (SELECT CASE WHEN totals.AllSum > 0
                                 THEN totals.JobSum * 1.0 / totals.AllSum
                                 ELSE 0 END
                     FROM (
                        SELECT
                            SUM(CASE WHEN po.JobId = @JobId THEN ISNULL(sil.LineTotal,0) ELSE 0 END) AS JobSum,
                            SUM(ISNULL(sil.LineTotal,0))                                              AS AllSum
                        FROM proj.TBL_SUPPLIER_INVOICE_LINE sil
                        LEFT JOIN proj.TBL_PURCHASE_ORDER_LINE pol ON pol.PoLineId = sil.PoLineId
                        LEFT JOIN proj.TBL_PURCHASE_ORDER       po ON po.PoId      = pol.PoId
                        WHERE sil.SupplierInvoiceId = pva.SupplierInvoiceId AND sil.IsActive = 1
                     ) totals)
            END AS JobShare
        ) sh
        WHERE  pva.IsActive = 1 AND pv.Status = 'Approved' AND pv.IsActive = 1
          AND  ISNULL(sh.JobShare, 0) > 0
    ) cout_t
    OUTER APPLY (
        SELECT ISNULL(SUM(Hours * NHRate + OvertimeHours * OTRate), 0) AS ManhourTotal
        FROM proj.TBL_MANHOUR WHERE JobId = @JobId AND Status = 'Approved' AND IsActive = 1
    ) mh_t
    OUTER APPLY (
        SELECT ISNULL(SUM(ISNULL(AmountInBaseCurrency, proj.fn_ToBase(ExpenseAmount, ExchangeRate))), 0) AS ExpenseTotal
        FROM proj.TBL_JOB_EXPENSE WHERE JobId = @JobId AND IsApproved = 1
    ) ex_t
    OUTER APPLY (
        SELECT ISNULL(SUM(l.TotalCost), 0) AS ServiceTotal
        FROM proj.TBL_SRV_HEADER h
        JOIN proj.TBL_SRV_LINE l ON l.SrvId = h.SrvId AND l.IsActive = 1
        WHERE h.JobId = @JobId AND h.Status = 'Confirmed' AND h.IsActive = 1
    ) srv_t
    WHERE jf.JobId = @JobId;

    -- RS3: Budget vs Actual
    SELECT
        b.JobBudgetId, b.CostCategoryId,
        ISNULL(cat.CategoryName, 'Category ' + CAST(b.CostCategoryId AS NVARCHAR)) AS CategoryName,
        b.Qty, b.UnitPrice,
        ISNULL(b.AmountInBaseCurrency, proj.fn_ToBase(b.BudgetedAmount, ISNULL(b.ExchangeRate,1))) / @Div AS BudgetedAmount,
        b.Notes, b.RvNo, b.IsApproved,
        ISNULL(a.ActualAmount, 0) / @Div AS ActualAmount,
        (ISNULL(b.AmountInBaseCurrency, proj.fn_ToBase(b.BudgetedAmount, ISNULL(b.ExchangeRate,1))) - ISNULL(a.ActualAmount, 0)) / @Div AS Variance
    FROM proj.TBL_JOB_BUDGET b
    LEFT JOIN proj.TBL_JOB_EXPENSE_CATEGORY cat ON cat.ExpenseCategoryId = b.CostCategoryId
    LEFT JOIN proj.VW_JOB_COST_ACTUAL a ON a.JobId = @JobId AND a.CostCategoryId = b.CostCategoryId
    WHERE b.JobId = @JobId AND b.IsCurrent = 1
    ORDER BY CategoryName;

    -- RS4: Engineers
    SELECT je.JobEngineerId, je.EngineerId, e.EngineerName,
           je.TeamId, t.TeamName, je.Role,
           je.AssignedDate, je.Completed, je.AssignedBy
    FROM proj.TBL_JOB_ENGINEER je
    LEFT JOIN proj.TBL_ENGINEER e ON e.EngineerId = je.EngineerId
    LEFT JOIN proj.TBL_TEAM     t ON t.TeamId     = je.TeamId
    WHERE je.JobId = @JobId
    ORDER BY je.AssignedDate;

    -- RS5: Manhour Summary
    SELECT
        SUM(Hours) AS TotalNHHours, SUM(OvertimeHours) AS TotalOTHours,
        SUM(Hours + OvertimeHours) AS TotalHours,
        SUM(Hours * NHRate + OvertimeHours * OTRate) AS TotalCost,
        SUM(CASE WHEN Site = 'Y' THEN Hours + OvertimeHours ELSE 0 END) AS SiteHours,
        SUM(CASE WHEN Site = 'Y' THEN Hours * NHRate + OvertimeHours * OTRate ELSE 0 END) AS SiteCost,
        SUM(CASE WHEN ISNULL(Site,'N') != 'Y' THEN Hours + OvertimeHours ELSE 0 END) AS NonSiteHours,
        SUM(CASE WHEN ISNULL(Site,'N') != 'Y' THEN Hours * NHRate + OvertimeHours * OTRate ELSE 0 END) AS NonSiteCost,
        SUM(CASE WHEN MType = 'M' THEN Hours + OvertimeHours ELSE 0 END) AS MechHours,
        SUM(CASE WHEN MType = 'M' THEN Hours * NHRate + OvertimeHours * OTRate ELSE 0 END) AS MechCost,
        SUM(CASE WHEN MType = 'E' THEN Hours + OvertimeHours ELSE 0 END) AS ElecHours,
        SUM(CASE WHEN MType = 'E' THEN Hours * NHRate + OvertimeHours * OTRate ELSE 0 END) AS ElecCost,
        MAX(ModifiedDate) AS LastUpdated
    FROM proj.TBL_MANHOUR
    WHERE JobId = @JobId AND Status = 'Approved' AND IsActive = 1;

    -- RS6: Manhour by Employee
    SELECT m.EmployeeId, emp.EmpCode, emp.EmployeeName,
           SUM(m.Hours) AS TotalNHHours, SUM(m.OvertimeHours) AS TotalOTHours,
           SUM(m.Hours + m.OvertimeHours) AS TotalHours,
           SUM(m.Hours * m.NHRate) AS NHCost, SUM(m.OvertimeHours * m.OTRate) AS OTCost,
           SUM(m.Hours * m.NHRate + m.OvertimeHours * m.OTRate) AS TotalCost
    FROM proj.TBL_MANHOUR m
    JOIN proj.TBL_EMPLOYEE emp ON emp.EmployeeId = m.EmployeeId
    WHERE m.JobId = @JobId AND m.Status = 'Approved' AND m.IsActive = 1
    GROUP BY m.EmployeeId, emp.EmpCode, emp.EmployeeName
    ORDER BY emp.EmployeeName;

    -- RS7: Purchase Orders
    SELECT po.PoId, po.PoNumber, po.PoDate, po.VendorName, po.Status,
           po.TotalAmount, cur.ShortName AS CurrencyCode, po.DeliveryDate,
           ISNULL(po.ExchangeRate, 1) AS ExchangeRate,
           po.ApprovedBy, po.ApprovedDate,
           po.ExpenseCategoryId,
           ISNULL(ec.CategoryName, 'Uncategorised') AS ExpenseCategoryName,
           ROUND(ISNULL(paid.PoPaid, 0) / NULLIF(ISNULL(po.ExchangeRate, 1), 0), 2) AS PaidAmount,
           po.TotalAmount - ROUND(ISNULL(paid.PoPaid, 0) / NULLIF(ISNULL(po.ExchangeRate, 1), 0), 2) AS BalanceAmount,
           proj.fn_ToBase(po.TotalAmount, po.ExchangeRate) / @Div                              AS TotalAmountBase,
           ISNULL(paid.PoPaid, 0) / @Div                                                       AS PaidAmountBase,
           (proj.fn_ToBase(po.TotalAmount, po.ExchangeRate) - ISNULL(paid.PoPaid, 0)) / @Div   AS BalanceAmountBase
    FROM proj.TBL_PURCHASE_ORDER po
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = po.CurrencyId
    LEFT JOIN proj.TBL_JOB_EXPENSE_CATEGORY ec ON ec.ExpenseCategoryId = po.ExpenseCategoryId
    OUTER APPLY (
        SELECT
            ISNULL((SELECT SUM(pva.AllocatedAmount)
                    FROM proj.TBL_PAYMENT_VOUCHER_ALLOCATION pva
                    JOIN proj.TBL_PAYMENT_VOUCHER pv ON pv.PvId = pva.PvId
                    WHERE pva.PoId = po.PoId AND pva.IsActive = 1
                      AND pv.Status = 'Approved' AND pv.IsActive = 1), 0)
          + ISNULL((SELECT SUM(sil.LineTotal / si_t.AllSum * pva.AllocatedAmount)
                    FROM proj.TBL_SUPPLIER_INVOICE_LINE       sil
                    JOIN proj.TBL_PURCHASE_ORDER_LINE         pol ON pol.PoLineId = sil.PoLineId AND pol.PoId = po.PoId
                    JOIN proj.TBL_PAYMENT_VOUCHER_ALLOCATION  pva ON pva.SupplierInvoiceId = sil.SupplierInvoiceId
                                                                  AND pva.IsActive = 1
                                                                  AND pva.PoId IS NULL
                    JOIN proj.TBL_PAYMENT_VOUCHER             pv  ON pv.PvId = pva.PvId AND pv.Status = 'Approved' AND pv.IsActive = 1
                    JOIN (
                        SELECT SupplierInvoiceId, SUM(ISNULL(LineTotal,0)) AS AllSum
                        FROM proj.TBL_SUPPLIER_INVOICE_LINE
                        WHERE IsActive = 1
                        GROUP BY SupplierInvoiceId
                    ) si_t ON si_t.SupplierInvoiceId = sil.SupplierInvoiceId
                    WHERE sil.IsActive = 1 AND si_t.AllSum > 0), 0) AS PoPaid
        FROM (SELECT 1 AS Dummy) d
    ) paid
    WHERE po.JobId = @JobId AND po.IsActive = 1
    ORDER BY ISNULL(ec.CategoryName, 'Uncategorised'), po.PoDate DESC;

    -- RS8: Stock Issues
    SELECT si.IssueId, si.IssueNo, si.IssueDate, si.Status, si.IssuedTo, si.Notes,
           si.CostingType, COUNT(sil.IssueLineId) AS LineCount,
           ISNULL(SUM(sil.Qty * sil.UnitCost), 0) AS TotalCost,
           (SELECT ShortName FROM proj.TBL_CURRENCY WHERE IsBaseCurrency = 1) AS CurrencyCode
    FROM proj.TBL_STOCK_ISSUE si
    LEFT JOIN proj.TBL_STOCK_ISSUE_LINE sil ON sil.IssueId = si.IssueId AND sil.IsActive = 1
    WHERE si.JobId = @JobId AND si.IsActive = 1
      AND ISNULL(si.CostingType, 'INC_COSTING') <> 'EXC_COSTING'
    GROUP BY si.IssueId, si.IssueNo, si.IssueDate, si.Status, si.IssuedTo, si.Notes, si.CostingType
    ORDER BY si.IssueDate DESC;

    -- RS8b: Issue Returns
    SELECT r.ReturnId, r.ReturnNo, r.ReturnDate, r.Status, r.ReturnedBy, r.Notes,
           i.IssueNo, i.IssueId, i.CostingType,
           COUNT(rl.ReturnLineId) AS LineCount,
           ISNULL(SUM(rl.ReturnQty * rl.UnitCost), 0) AS TotalCost,
           (SELECT ShortName FROM proj.TBL_CURRENCY WHERE IsBaseCurrency = 1) AS CurrencyCode
    FROM proj.TBL_STOCK_ISSUE_RETURN r
    JOIN proj.TBL_STOCK_ISSUE        i  ON i.IssueId = r.IssueId
    LEFT JOIN proj.TBL_STOCK_ISSUE_RETURN_LINE rl ON rl.ReturnId = r.ReturnId
    WHERE i.JobId = @JobId AND r.IsActive = 1
    GROUP BY r.ReturnId, r.ReturnNo, r.ReturnDate, r.Status, r.ReturnedBy, r.Notes,
             i.IssueNo, i.IssueId, i.CostingType
    ORDER BY r.ReturnDate DESC;

    -- RS9: Invoices (main job)
    SELECT inv.InvoiceId, inv.InvoiceNo, inv.InvoiceDate, inv.DueDate,
           inv.SubTotal, inv.TaxAmount, inv.TotalAmount, inv.Status, inv.LpoNo,
           ISNULL(inv.ExchangeRate, 1) AS ExchangeRate,
           proj.fn_ToBase(inv.TotalAmount, inv.ExchangeRate) AS AmountInBaseCurrency,
           cur.ShortName AS CurrencyCode,
           ISNULL((SELECT SUM(rva.AllocatedAmount) / NULLIF(inv.ExchangeRate, 0)
                   FROM proj.TBL_RECEIPT_VOUCHER_ALLOCATION rva
                   JOIN proj.TBL_RECEIPT_VOUCHER rv2 ON rv2.RvId = rva.RvId
                   WHERE rva.InvoiceId = inv.InvoiceId AND rva.IsActive = 1
                     AND rv2.Status = 'Approved' AND rv2.IsActive = 1), 0) AS ReceivedAmount,
           ISNULL((SELECT SUM(cna.AllocatedAmount) / NULLIF(inv.ExchangeRate, 0)
                   FROM proj.TBL_CREDIT_NOTE_ALLOCATION cna
                   JOIN proj.TBL_CREDIT_NOTE cn ON cn.CnId = cna.CnId
                   WHERE cna.InvoiceId = inv.InvoiceId AND cna.IsActive = 1
                     AND cn.Status = 'Approved' AND cn.IsActive = 1), 0) AS CnAmount
    FROM proj.TBL_INVOICE inv
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = inv.CurrencyId
    WHERE inv.JobId = @JobId AND inv.IsActive = 1
    ORDER BY inv.InvoiceDate DESC;

    -- RS9b: Child Job Invoices
    SELECT inv.InvoiceId, inv.InvoiceNo, inv.InvoiceDate, inv.DueDate,
           inv.SubTotal, inv.TaxAmount, inv.TotalAmount, inv.Status,
           ISNULL(inv.ExchangeRate, 1) AS ExchangeRate,
           proj.fn_ToBase(inv.TotalAmount, inv.ExchangeRate) AS AmountInBaseCurrency,
           inv.JobId AS ChildJobId,
           cj.ProjectName AS ChildProjectName,
           cur.ShortName AS CurrencyCode,
           ISNULL((SELECT SUM(rva.AllocatedAmount) / NULLIF(inv.ExchangeRate, 0)
                   FROM proj.TBL_RECEIPT_VOUCHER_ALLOCATION rva
                   JOIN proj.TBL_RECEIPT_VOUCHER rv2 ON rv2.RvId = rva.RvId
                   WHERE rva.InvoiceId = inv.InvoiceId AND rva.IsActive = 1
                     AND rv2.Status = 'Approved' AND rv2.IsActive = 1), 0) AS ReceivedAmount,
           ISNULL((SELECT SUM(cna.AllocatedAmount) / NULLIF(inv.ExchangeRate, 0)
                   FROM proj.TBL_CREDIT_NOTE_ALLOCATION cna
                   JOIN proj.TBL_CREDIT_NOTE cn ON cn.CnId = cna.CnId
                   WHERE cna.InvoiceId = inv.InvoiceId AND cna.IsActive = 1
                     AND cn.Status = 'Approved' AND cn.IsActive = 1), 0) AS CnAmount
    FROM proj.TBL_INVOICE inv
    JOIN proj.TBL_JOB cj ON cj.JobId = inv.JobId
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = inv.CurrencyId
    WHERE cj.ParentJobId = @JobId AND inv.IsActive = 1
    ORDER BY inv.InvoiceDate DESC;

    -- RS9c: Delivery Notes
    SELECT d.DeliveryId, d.DeliveryNo, d.DeliveryDate, d.Status,
           d.Consignee, d.ConsigneeLpoNo, d.ConsigneeLpoDate,
           d.VehicleNo, d.DeliveredBy, d.DeliveredByDate,
           d.InvoiceId, inv.InvoiceNo, d.Notes
    FROM proj.TBL_DELIVERY d
    LEFT JOIN proj.TBL_INVOICE inv ON inv.InvoiceId = d.InvoiceId
    WHERE d.JobId = @JobId AND d.IsActive = 1
    ORDER BY d.DeliveryDate DESC;

    -- RS10: Expenses
    SELECT ex.ExpenseId, ex.ExpenseCategoryId, ec.CategoryName AS ExpenseCategoryName,
           ex.ExpenseDescription, ex.ExpenseDate, ex.ExpenseAmount,
           cur.ShortName AS CurrencyCode, ex.ExchangeRate, ex.AmountInBaseCurrency,
           ex.ReferenceNo, ex.Remarks, ex.IsApproved, ex.ApprovedBy, ex.ApprovedDate, ex.CreatedBy
    FROM proj.TBL_JOB_EXPENSE ex
    LEFT JOIN proj.TBL_JOB_EXPENSE_CATEGORY ec ON ec.ExpenseCategoryId = ex.ExpenseCategoryId
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = ex.CurrencyId
    WHERE ex.JobId = @JobId
    ORDER BY ex.ExpenseDate DESC;

    -- RS11: Audit Trail
    SELECT au.AuditId, au.Action, au.Section, au.OldValue, au.NewValue,
           au.Remarks, au.CreatedBy, au.CreatedDate
    FROM proj.TBL_JOB_AUDIT au
    WHERE au.JobId = @JobId
    ORDER BY au.CreatedDate DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetJobQualityLevels]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetJobQualityLevels];
GO

CREATE   PROCEDURE proj.sp_GetJobQualityLevels
AS
BEGIN
    SET NOCOUNT ON;
    SELECT QualityLevelId, QualityLevelName, Description, SortOrder
    FROM proj.TBL_JOB_QUALITY
    WHERE IsActive = 1
    ORDER BY SortOrder, QualityLevelName;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetJobReportDocs]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetJobReportDocs];
GO
CREATE   PROCEDURE proj.sp_GetJobReportDocs
    @JobId NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    -- RS1: Purchase Orders
    SELECT
        po.PoId,
        po.PoNumber,
        CONVERT(DATE, po.PoDate)  AS PoDate,
        po.Status,
        COALESCE(s.SupplierName, po.VendorName, '—') AS SupplierName,
        po.TotalAmount,
        c.ShortName AS CurrencyShort
    FROM       proj.TBL_PURCHASE_ORDER po
    LEFT JOIN  proj.TBL_SUPPLIER       s  ON s.SupplierId = po.SupplierId
    LEFT JOIN  proj.TBL_CURRENCY       c  ON c.CurrencyId = po.CurrencyId
    WHERE po.JobId    = @JobId
      AND po.IsActive = 1
    ORDER BY po.PoDate DESC;

    -- RS2: Customer Invoices
    SELECT
        inv.InvoiceId,
        inv.InvoiceNo,
        CONVERT(DATE, inv.InvoiceDate) AS InvoiceDate,
        inv.Status,
        inv.TotalAmount,
        c.ShortName AS CurrencyShort
    FROM  proj.TBL_INVOICE inv
    LEFT JOIN proj.TBL_CURRENCY c ON c.CurrencyId = inv.CurrencyId
    WHERE inv.JobId    = @JobId
      AND inv.IsActive = 1
    ORDER BY inv.InvoiceDate DESC;
END;
GO

