CREATE PROCEDURE proj.sp_GetJobsForCustomer
    @CustomerId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT JobId, ProjectName, JobDate
    FROM   proj.VW_JOB
    WHERE  CustomerId = @CustomerId
      AND  ISNULL(IsClosedStatus, 0) = 0
      AND  ApprovalStatus = 'Approved'
    ORDER BY JobDate DESC, JobId DESC;
END
