IF OBJECT_ID(N'[proj].[sp_GetJobStockBreakdown]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetJobStockBreakdown];
GO
-- Read SPs: remove IsJobStock=1 filter — JobId filter is sufficient
-- In-house entries: IsJobStock=0, JobId=in-house-job
-- Regular job entries: IsJobStock=1, JobId=regular-job
-- General store entries: IsJobStock=0, JobId=NULL (excluded by JobId IS NOT NULL)

CREATE PROCEDURE proj.sp_GetJobStockBreakdown
    @ItemId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        l.JobId,
        SUM(l.QtyIn)  AS TotalReceived,
        SUM(l.QtyOut) AS TotalIssued,
        SUM(l.QtyIn) - SUM(l.QtyOut) AS QtyBalance,
        MAX(l.UnitCost) AS LastUnitCost
    FROM proj.TBL_STOCK_LEDGER l
    WHERE l.ItemId = @ItemId
      AND l.JobId IS NOT NULL
    GROUP BY l.JobId
    HAVING SUM(l.QtyIn) - SUM(l.QtyOut) > 0
    ORDER BY l.JobId;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetJobStockItems]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetJobStockItems];
GO

CREATE PROCEDURE proj.sp_GetJobStockItems
    @JobId      NVARCHAR(50),
    @SearchText NVARCHAR(200) = NULL,
    @PageSize   INT           = 20
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        i.ItemId,
        i.ItemCode,
        i.ItemName,
        i.BaseUomId,
        c.CategoryName,
        u.UomCode   AS BaseUom,
        ISNULL(SUM(sl.QtyIn - sl.QtyOut), 0)                AS QtyBalance,
        ISNULL(SUM(CASE WHEN sl.QtyIn > sl.QtyOut THEN sl.QtyIn - sl.QtyOut ELSE 0 END), 0) AS AvailableQty,
        ISNULL(sb.AvgUnitCost, 0)                            AS AvgUnitCost,
        ISNULL(sb.AvgUnitCost, 0)                            AS LastCost,
        ISNULL(SUM(sl.QtyIn - sl.QtyOut), 0)
            * ISNULL(sb.AvgUnitCost, 0)                      AS StockValue,
        MAX(sl.TransDate)                                    AS LastMovementDate
    FROM proj.TBL_STOCK_LEDGER sl
    JOIN  proj.TBL_ITEM           i  ON i.ItemId  = sl.ItemId
    LEFT JOIN proj.TBL_ITEM_CATEGORY c ON c.CategoryId = i.CategoryId
    LEFT JOIN proj.TBL_ITEM_UOM   u  ON u.UomId   = i.BaseUomId
    LEFT JOIN proj.TBL_STOCK_BALANCE sb ON sb.ItemId = sl.ItemId
    WHERE sl.JobId = @JobId
      AND (@SearchText IS NULL
           OR i.ItemName LIKE '%' + @SearchText + '%'
           OR i.ItemCode LIKE '%' + @SearchText + '%')
    GROUP BY i.ItemId, i.ItemCode, i.ItemName, i.BaseUomId, c.CategoryName, u.UomCode, sb.AvgUnitCost
    ORDER BY i.ItemCode, i.ItemName;
END
GO

