IF OBJECT_ID(N'[proj].[sp_GetManhour]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetManhour];
GO

CREATE   PROCEDURE proj.sp_GetManhour
    @BatchId INT
AS
BEGIN
    SET NOCOUNT ON;

    -- Result set 1: batch summary
    SELECT
        m.BatchId,
        MAX(m.DocumentNo)             AS DocumentNo,
        MAX(m.DocumentDate)           AS DocumentDate,
        MAX(m.Status)                 AS Status,
        COUNT(DISTINCT m.JobId)       AS JobCount,
        SUM(m.Hours)                  AS TotalHours,
        SUM(m.OvertimeHours)          AS TotalOTHours,
        COUNT(DISTINCT m.EmployeeId)  AS TotalEmployees,
        MAX(m.Remarks)                AS Remarks,
        MAX(m.UploadedFileName)       AS UploadedFileName,
        MAX(m.CreatedBy)              AS CreatedBy,
        MAX(m.CreatedDate)            AS CreatedDate,
        MAX(m.ModifiedBy)             AS ModifiedBy,
        MAX(m.ModifiedDate)           AS ModifiedDate,
        MAX(ds.BadgeBg)               AS BadgeBg,
        MAX(ds.BadgeColor)            AS BadgeColor,
        MAX(ds.BadgeDot)              AS BadgeDot,
        MAX(CAST(ds.CanEdit   AS INT)) AS CanEdit,
        MAX(CAST(ds.CanDelete AS INT)) AS CanDelete,
        MAX(CAST(ds.CanPrint  AS INT)) AS CanPrint
    FROM proj.TBL_MANHOUR m
    LEFT JOIN proj.TBL_DOCUMENT_STATUS ds ON ds.ModuleName = 'MH' AND ds.StatusCode = m.Status
    WHERE m.BatchId = @BatchId AND m.IsActive = 1
    GROUP BY m.BatchId;

    -- Result set 2: rows
    SELECT
        m.ManhourId,
        m.BatchId,
        m.JobId,
        j.JobDescription,
        m.EmployeeId,
        e.EmpCode,
        e.EmployeeName,
        m.Hours,
        m.OvertimeHours,
        m.Site,
        m.MType,
        m.Remarks
    FROM proj.TBL_MANHOUR m
    LEFT JOIN proj.TBL_JOB      j ON j.JobId      = m.JobId
    LEFT JOIN proj.TBL_EMPLOYEE e ON e.EmployeeId  = m.EmployeeId
    WHERE m.BatchId = @BatchId AND m.IsActive = 1
    ORDER BY m.JobId, e.EmpCode;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetManhourRate]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetManhourRate];
GO

CREATE   PROCEDURE proj.sp_GetManhourRate
    @WorkDate   DATE,
    @JobId      NVARCHAR(50),
    @JobTypeId  NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        ISNULL(r1.NHRate, ISNULL(r2.NHRate, r3.NHRate)) AS NHRate,
        ISNULL(r1.OTRate, ISNULL(r2.OTRate, r3.OTRate)) AS OTRate,
        CASE
            WHEN r1.NHRate IS NOT NULL THEN 1
            WHEN r2.NHRate IS NOT NULL THEN 2
            WHEN r3.NHRate IS NOT NULL THEN 3
            ELSE NULL
        END AS Priority
    FROM (SELECT 1 AS Dummy) x

    OUTER APPLY (
        SELECT TOP 1 NHRate, OTRate
        FROM proj.TBL_MANHOUR_RATE
        WHERE IsActive = 1
          AND JobId = @JobId
          AND @WorkDate BETWEEN EffectiveFrom AND EffectiveTo
    ) r1

    OUTER APPLY (
        SELECT TOP 1 NHRate, OTRate
        FROM proj.TBL_MANHOUR_RATE
        WHERE IsActive = 1
          AND JobTypeId = @JobTypeId
          AND JobId IS NULL
          AND @WorkDate BETWEEN EffectiveFrom AND EffectiveTo
    ) r2

    OUTER APPLY (
        SELECT TOP 1 NHRate, OTRate
        FROM proj.TBL_MANHOUR_RATE
        WHERE IsActive = 1
          AND JobTypeId IS NULL
          AND JobId     IS NULL
          AND @WorkDate BETWEEN EffectiveFrom AND EffectiveTo
    ) r3;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetManhourRateList]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetManhourRateList];
GO

-- ── sp_GetManhourRateList  (management UI list) ───────────────────────────────
CREATE   PROCEDURE proj.sp_GetManhourRateList
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        r.RateId,
        r.JobTypeId,
        jt.JobTypeName,
        r.JobId,
        j.JobDescription,
        r.EffectiveFrom,
        r.EffectiveTo,
        r.NHRate,
        r.OTRate,
        r.Remarks,
        r.IsActive,
        r.CreatedBy,
        r.CreatedDate,
        r.ModifiedBy,
        r.ModifiedDate,
        -- Scope label for display
        CASE
            WHEN r.JobId     IS NOT NULL THEN 'Job'
            WHEN r.JobTypeId IS NOT NULL THEN 'Job Type'
            ELSE 'Default'
        END AS ScopeLabel,
        -- Priority for display ordering
        CASE
            WHEN r.JobId     IS NOT NULL THEN 1
            WHEN r.JobTypeId IS NOT NULL THEN 2
            ELSE 3
        END AS Priority
    FROM proj.TBL_MANHOUR_RATE r
    LEFT JOIN proj.TBL_JOBTYPE jt ON jt.JobTypeId = r.JobTypeId
    LEFT JOIN proj.TBL_JOB     j  ON j.JobId      = r.JobId
    ORDER BY Priority, r.JobTypeId, r.JobId, r.EffectiveFrom;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetMaterialOut]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetMaterialOut];
GO
CREATE PROCEDURE proj.sp_GetMaterialOut
    @MaterialOutId INT = NULL,
    @SubcontractId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        mo.MaterialOutId,
        mo.MaterialOutNo,
        mo.SubcontractId,
        sc.SubcontractNo,
        mo.VendorId,
        s.SupplierName  AS VendorName,
        mo.OutDate,
        mo.Status,
        mo.Notes,
        mo.CreatedBy,
        mo.CreatedDate,
        mo.ModifiedBy,
        mo.ModifiedDate
    FROM proj.TBL_MATERIAL_OUT mo
    LEFT JOIN proj.TBL_SUBCONTRACT_ORDER sc ON sc.SubcontractId = mo.SubcontractId
    LEFT JOIN proj.TBL_SUPPLIER          s  ON s.SupplierId     = mo.VendorId
    WHERE mo.IsActive = 1
      AND (@MaterialOutId IS NULL OR mo.MaterialOutId = @MaterialOutId)
      AND (@SubcontractId IS NULL OR mo.SubcontractId = @SubcontractId);

    IF @MaterialOutId IS NOT NULL
    BEGIN
        SELECT
            mol.MaterialOutLineId,
            mol.MaterialOutId,
            mol.ComponentId,
            mol.ItemId,
            i.ItemCode,
            i.ItemName,
            mol.Qty,
            mol.UomId,
            u.UomName,
            mol.Remarks,
            ISNULL(sb.QtyOnHand, 0) AS QtyOnHand,
            sc_comp.RequiredQty,
            sc_comp.IssuedQty
        FROM proj.TBL_MATERIAL_OUT_LINE mol
        LEFT JOIN proj.TBL_ITEM                  i       ON i.ItemId            = mol.ItemId
        LEFT JOIN proj.TBL_ITEM_UOM              u       ON u.UomId             = mol.UomId
        LEFT JOIN proj.TBL_STOCK_BALANCE         sb      ON sb.ItemId           = mol.ItemId
        LEFT JOIN proj.TBL_SUBCONTRACT_COMPONENT sc_comp ON sc_comp.ComponentId = mol.ComponentId
        WHERE mol.MaterialOutId = @MaterialOutId AND mol.IsActive = 1
        ORDER BY mol.MaterialOutLineId;
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetMenuPermissions]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetMenuPermissions];
GO
CREATE   PROCEDURE proj.sp_GetMenuPermissions
    @RoleId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        m.MenuId,
        m.MenuName,
        m.MenuUrl,
        m.ParentMenuId,
        p.MenuName  AS ParentMenuName,
        gp.MenuName AS GrandParentMenuName,
        -- 3-level node (leaf): SectionName = grandparent › parent
        -- L2 container that itself has active children: group it under its
        --   OWN section header (parent › self) so the container row appears
        --   together with its child report menus in the matrix.
        -- Otherwise: parent name, or "Top Level" for root rows.
        CASE
            WHEN gp.MenuId IS NOT NULL THEN gp.MenuName + N' › ' + p.MenuName
            WHEN p.MenuId IS NOT NULL
                 AND EXISTS (SELECT 1 FROM proj.TBL_MENU c
                             WHERE c.ParentMenuId = m.MenuId AND c.IsActive = 1)
                 THEN p.MenuName + N' › ' + m.MenuName
            ELSE ISNULL(p.MenuName, N'Top Level')
        END AS SectionName,
        ISNULL(rm.RoleMenuId, 0) AS RoleMenuId,
        ISNULL(rm.CanView,    0) AS CanView
    FROM proj.TBL_MENU m
    LEFT JOIN proj.TBL_MENU p  ON p.MenuId  = m.ParentMenuId
    LEFT JOIN proj.TBL_MENU gp ON gp.MenuId = p.ParentMenuId
    LEFT JOIN proj.TBL_ROLE_MENU rm
           ON rm.MenuId = m.MenuId
          AND rm.RoleId = @RoleId
    WHERE m.IsActive = 1
    ORDER BY
        ISNULL(gp.MenuId, ISNULL(p.MenuId, m.MenuId)),
        ISNULL(gp.MenuOrder, ISNULL(p.MenuOrder, m.MenuOrder)),
        ISNULL(p.MenuOrder,  m.MenuOrder),
        m.MenuOrder;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetMenuTree]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetMenuTree];
GO

CREATE   PROCEDURE proj.sp_GetMenuTree
AS
BEGIN
    SET NOCOUNT ON;

    -- All menus with parent name for admin management
    SELECT
        m.MenuId, m.ParentMenuId, m.MenuName,
        ISNULL(m.MenuUrl, '')   AS MenuUrl,
        ISNULL(m.MenuIcon, '')  AS MenuIcon,
        m.MenuOrder, m.IsActive,
        ISNULL(p.MenuName, '')  AS ParentMenuName
    FROM proj.TBL_MENU m
    LEFT JOIN proj.TBL_MENU p ON p.MenuId = m.ParentMenuId
    ORDER BY ISNULL(m.ParentMenuId, m.MenuId), m.MenuOrder;

    -- All actions
    SELECT ma.ActionId, ma.MenuId, ma.ActionName, ma.ActionCode, ma.IsActive
    FROM proj.TBL_MENU_ACTIONS ma
    ORDER BY ma.MenuId, ma.ActionId;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetMOM]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetMOM];
