CREATE   PROCEDURE PROJ.sp_GetMOM
    @MomId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        m.MomId, m.JobId, m.MeetingDate, m.Title,
        m.Venue, m.Attendees, m.Summary, m.Status,
        m.CreatedBy, m.CreatedDate, m.ModifiedBy, m.ModifiedDate
    FROM PROJ.TBL_MOM m
    WHERE m.MomId = @MomId AND m.IsActive = 1;

    SELECT
        t.MomTaskId, t.MomId, t.JobId,
        t.Description, t.DueDate, t.Priority,
        t.AssignedTo, t.Status, t.Remarks,
        t.CreatedBy, t.CreatedDate
    FROM PROJ.TBL_MOM_TASK t
    WHERE t.MomId = @MomId AND t.IsActive = 1
    ORDER BY t.MomTaskId;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetMOMList]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetMOMList];
GO
CREATE   PROCEDURE PROJ.sp_GetMOMList
    @JobId      VARCHAR(30)   = NULL,
    @Status     NVARCHAR(20)  = NULL,
    @DateFrom   DATE          = NULL,
    @DateTo     DATE          = NULL,
    @CreatedBy  NVARCHAR(100) = NULL,
    @AssignedTo NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        m.MomId, m.JobId, m.MeetingDate, m.Title, m.Venue,
        m.Attendees, m.Summary, m.Status,
        m.CreatedBy, m.CreatedDate, m.ModifiedBy, m.ModifiedDate,
        COUNT(t.MomTaskId) AS TotalTasks,
        SUM(CASE WHEN t.Status IN ('Open','InProgress') THEN 1 ELSE 0 END) AS OpenTasks
    FROM PROJ.TBL_MOM m
    LEFT JOIN PROJ.TBL_MOM_TASK t ON t.MomId = m.MomId AND t.IsActive = 1
    WHERE m.IsActive = 1
      AND (@JobId     IS NULL OR m.JobId       = @JobId)
      AND (@Status    IS NULL OR m.Status      = @Status)
      AND (@DateFrom  IS NULL OR m.MeetingDate >= @DateFrom)
      AND (@DateTo    IS NULL OR m.MeetingDate <= @DateTo)
      AND (@CreatedBy IS NULL OR m.CreatedBy   = @CreatedBy)
      AND (@AssignedTo IS NULL OR EXISTS (
            SELECT 1 FROM PROJ.TBL_MOM_TASK x
            WHERE x.MomId = m.MomId AND x.IsActive = 1 AND x.AssignedTo = @AssignedTo
          ))
    GROUP BY
        m.MomId, m.JobId, m.MeetingDate, m.Title, m.Venue,
        m.Attendees, m.Summary, m.Status,
        m.CreatedBy, m.CreatedDate, m.ModifiedBy, m.ModifiedDate
    ORDER BY m.MeetingDate DESC, m.MomId DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetMOMTaskList]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetMOMTaskList];
GO
CREATE   PROCEDURE PROJ.sp_GetMOMTaskList
    @MomId      INT           = NULL,
    @JobId      VARCHAR(30)   = NULL,
    @AssignedTo NVARCHAR(100) = NULL,
    @Status     NVARCHAR(20)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        t.MomTaskId, t.MomId, t.JobId,
        m.Title      AS MomTitle,
        m.MeetingDate,
        t.Description, t.DueDate, t.Priority,
        t.AssignedTo, t.Status, t.Remarks,
        t.CreatedBy, t.CreatedDate, t.ModifiedBy, t.ModifiedDate
    FROM PROJ.TBL_MOM_TASK t
    JOIN PROJ.TBL_MOM m ON m.MomId = t.MomId
    WHERE t.IsActive = 1
      AND (@MomId      IS NULL OR t.MomId      = @MomId)
      AND (@JobId      IS NULL OR t.JobId      = @JobId)
      AND (@AssignedTo IS NULL OR t.AssignedTo = @AssignedTo)
      AND (@Status     IS NULL OR t.Status     = @Status)
    ORDER BY
        CASE t.Priority
            WHEN 'Critical' THEN 1 WHEN 'High' THEN 2 WHEN 'Medium' THEN 3 ELSE 4
        END,
        t.DueDate ASC, t.MomTaskId ASC;
END
GO

