IF OBJECT_ID(N'[proj].[sp_GetPaymentVoucher]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetPaymentVoucher];
GO

CREATE PROCEDURE proj.sp_GetPaymentVoucher
    @PvId INT
AS
BEGIN
    SET NOCOUNT ON;

    -- RS1: Header (AllocatedAmount on PV header is in PV currency)
    SELECT pv.PvId, pv.PvNumber, pv.PvDate, pv.SupplierId, s.SupplierName,
           pv.CurrencyId, cur.ShortName AS CurrencyShort,
           pv.ExchangeRate, pv.AmountPaid, pv.AllocatedAmount,
           (pv.AmountPaid - pv.AllocatedAmount) AS UnallocatedAmount,
           pv.PaymentMode, pv.ReferenceNo, pv.ReferenceDate, pv.BankName, pv.Notes,
           pv.Status, pv.PostedBy, pv.PostedDate,
           pv.CreatedBy, pv.CreatedDate, pv.ModifiedBy, pv.ModifiedDate
    FROM proj.TBL_PAYMENT_VOUCHER pv
    LEFT JOIN proj.TBL_SUPPLIER s   ON s.SupplierId   = pv.SupplierId
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = pv.CurrencyId
    WHERE pv.PvId = @PvId AND pv.IsActive = 1;

    -- RS2: Allocations
    -- AllocatedAmount      = invoice-currency amount  (base / si.ExchangeRate)
    -- AllocatedAmountBase  = stored base amount       (AED)
    -- AllocatedAmountPvCcy = PV-currency amount       (base / pv.ExchangeRate)
    SELECT a.AllocationId, a.PvId, a.SupplierInvoiceId,
           si.InvoiceNo, si.InvoiceDate, si.SupplierInvRef,
           si.TotalAmount AS InvoiceTotal,
           ci.ShortName  AS InvoiceCurrencyShort,
           cpv.ShortName AS PvCurrencyShort,
           ROUND(a.AllocatedAmount / NULLIF(si.ExchangeRate,  0), 2) AS AllocatedAmount,
           ROUND(a.AllocatedAmount / NULLIF(pv.ExchangeRate,  0), 2) AS AllocatedAmountPvCcy,
           a.AllocatedAmount AS AllocatedAmountBase,
           a.PoId,
           po.PoNumber, po.JobId,
           (SELECT STRING_AGG(po2.PoNumber, N', ')
            FROM (
                SELECT DISTINCT po2.PoNumber
                FROM proj.TBL_SUPPLIER_INVOICE_LINE sil
                JOIN proj.TBL_PURCHASE_ORDER_LINE pol2 ON pol2.PoLineId = sil.PoLineId
                JOIN proj.TBL_PURCHASE_ORDER       po2  ON po2.PoId      = pol2.PoId
                WHERE sil.SupplierInvoiceId = a.SupplierInvoiceId AND sil.IsActive = 1
            ) po2) AS SiCoversPoNumbers,
           a.Reason,
           ROUND(ISNULL(paid.PaidByOthers, 0) / NULLIF(si.ExchangeRate, 0), 2) AS PaidByOthers,
           si.TotalAmount - ROUND(ISNULL(paid.PaidByOthers, 0) / NULLIF(si.ExchangeRate, 0), 2) AS Outstanding,
           a.CreatedBy, a.CreatedDate, a.ModifiedBy, a.ModifiedDate, a.IsActive
    FROM proj.TBL_PAYMENT_VOUCHER_ALLOCATION a
    JOIN proj.TBL_PAYMENT_VOUCHER  pv  ON pv.PvId              = a.PvId
    JOIN proj.TBL_SUPPLIER_INVOICE si  ON si.SupplierInvoiceId = a.SupplierInvoiceId
    LEFT JOIN proj.TBL_CURRENCY    ci  ON ci.CurrencyId        = si.CurrencyId
    LEFT JOIN proj.TBL_CURRENCY    cpv ON cpv.CurrencyId       = pv.CurrencyId
    LEFT JOIN proj.TBL_PURCHASE_ORDER po ON po.PoId = a.PoId
    OUTER APPLY (
        SELECT ISNULL(SUM(a2.AllocatedAmount), 0) AS PaidByOthers
        FROM proj.TBL_PAYMENT_VOUCHER_ALLOCATION a2
        JOIN proj.TBL_PAYMENT_VOUCHER pv2 ON pv2.PvId = a2.PvId
        WHERE a2.SupplierInvoiceId = a.SupplierInvoiceId AND a2.IsActive = 1
          AND pv2.Status = 'Approved' AND pv2.IsActive = 1 AND a2.PvId <> a.PvId
    ) paid
    WHERE a.PvId = @PvId AND a.IsActive = 1
    ORDER BY a.AllocationId;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetPendingApprovals]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetPendingApprovals];
GO


-- ── sp_GetPendingApprovals ────────────────────────────────────
-- Get all documents pending approval for a given user.
-- Checks role, department, designation and delegation.
-- ──────────────────────────────────────────────────────────────
CREATE PROCEDURE proj.sp_GetPendingApprovals
    @UserId         int,
    @RoleId         int     = NULL,
    @DepartmentId   int     = NULL,
    @DesignationId  int     = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        t.TransactionId,
        t.DocumentNo,
        t.DocumentAmount,
        t.CurrentLevelNo,
        t.TotalLevels,
        t.SubmittedBy,
        t.SubmittedDate,
        m.ModuleCode,
        m.ModuleName,
        p.PolicyName,
        l.LevelName,
        l.LevelId,
        l.ApproverType,
        l.ApproverId,
        l.TimeoutHours,
        CASE WHEN d.DelegateId IS NOT NULL THEN 1 ELSE 0 END AS IsDelegated,
        d.OriginalUserId AS DelegatedFrom
    FROM proj.TBL_APPROVAL_TRANSACTION t
    JOIN proj.TBL_APPROVAL_MODULE  m ON t.ModuleId = m.ModuleId
    JOIN proj.TBL_APPROVAL_POLICY  p ON t.PolicyId = p.PolicyId
    JOIN proj.TBL_APPROVAL_LEVEL   l ON l.PolicyId = t.PolicyId
                                     AND l.LevelNo  = t.CurrentLevelNo
                                     AND l.IsActive = 1
    -- Check delegation (user receiving delegation)
    LEFT JOIN proj.TBL_APPROVAL_DELEGATE d
        ON d.LevelId        = l.LevelId
        AND d.DelegateUserId = @UserId
        AND d.IsActive      = 1
        AND CAST(GETDATE() AS date) BETWEEN d.FromDate AND d.ToDate
    WHERE t.CurrentStatus = 'InProgress'
    AND (
        -- Direct user assignment
        (l.ApproverType = 'USER'        AND l.ApproverId = @UserId)
        -- Role-based
        OR (l.ApproverType = 'ROLE'        AND l.ApproverId = @RoleId)
        -- Department-based
        OR (l.ApproverType = 'DEPARTMENT'  AND l.ApproverId = @DepartmentId)
        -- Designation-based
        OR (l.ApproverType = 'DESIGNATION' AND l.ApproverId = @DesignationId)
        -- Delegated to this user
        OR d.DelegateId IS NOT NULL
    )
    ORDER BY t.SubmittedDate ASC;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetPO]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetPO];
GO
CREATE PROCEDURE [PROJ].[sp_GetPO]
    @PoId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        po.PoId, po.PoNumber, po.PoDate, po.Revision,
        po.SupplierId,
        s.SupplierCode, s.SupplierName AS SupplierNameResolved,
        (SELECT TOP 1
            NULLIF(TRIM(
                ISNULL(sa.AddressLine1 + ', ', '') +
                ISNULL(NULLIF(sa.State,'') + ', ', '') +
                ISNULL(cn.CountryName, '')
            ), '')
         FROM proj.TBL_SUPPLIER_ADDRESS sa
         LEFT JOIN proj.TBL_COUNTRY cn ON cn.CountryId = sa.CountryId
         WHERE sa.SupplierId = po.SupplierId AND sa.IsActive = 1
         ORDER BY sa.IsDefault DESC, sa.SupplierAddressId ASC
        ) AS SupplierAddress,
        po.SupplierContactId,
        sc.ContactName, sc.Designation AS ContactDesignation,
        sc.Phone AS ContactPhone, sc.Mobile AS ContactMobile, sc.Email AS ContactEmail,
        po.JobId, j.ProjectName AS JobTitle,
        po.VendorName, po.VendorRef, po.VendorQuoteDate,
        po.CurrencyId, c.CurrencyName, c.ShortName AS CurrencyShort, c.Symbol AS CurrencySymbol,
        po.ExchangeRate,
        po.PaymentTermsId, pt.TermName AS PaymentTermName,
        po.DeliveryDate, po.DeliveryAddr, po.DeliveryTerms,
        po.Discount, po.TaxAmount, po.TotalAmount,
        ROUND(po_paid.PaidBase / NULLIF(ISNULL(po.ExchangeRate, 1), 0), 2) AS PaidAmount,
        po.TotalAmount - ROUND(po_paid.PaidBase / NULLIF(ISNULL(po.ExchangeRate, 1), 0), 2) AS BalanceAmount,
        po.InvoiceReceived,
        po.ApprovedBy, po.ApprovedDate,
        po.PoSentDate,
        po.HoldBy, po.HoldDate, po.HoldReason, po.StatusBeforeHold,
        po.Priority,
        po.Status, po.Notes, po.IsActive,
        po.ExpenseCategoryId,
        ec.CategoryCode  AS ExpenseCategoryCode,
        ec.CategoryName  AS ExpenseCategoryName,
        ISNULL(ec.IsSubcontractOrder, 0) AS IsSubcontractOrder,
        po.BudgetHeaderId,
        ISNULL(jt.IsBudgetHeaderLinked, 0) AS IsBudgetHeaderLinked,
        po.CreatedBy, po.CreatedDate, po.ModifiedBy, po.ModifiedDate,
        (SELECT STRING_AGG(x.PrNumber, ', ') WITHIN GROUP (ORDER BY x.PrNumber)
         FROM (SELECT DISTINCT pr2.PrNumber
               FROM PROJ.TBL_PURCHASE_ORDER_LINE   pol2
               JOIN PROJ.TBL_PURCHASE_REQUEST_LINE prl2 ON prl2.PrLineId = pol2.PrLineId AND prl2.IsActive = 1
               JOIN PROJ.TBL_PURCHASE_REQUEST      pr2  ON pr2.PrId      = prl2.PrId
               WHERE pol2.PoId = po.PoId AND pol2.IsActive = 1) x) AS LinkedPRs,
        m.IsWarranty, m.IsPreInspection, m.IsShipping, m.IsCOO, m.IsDrawing,
        m.IsMTC, m.IsQtn, m.IsOthers, m.IsNote1, m.IsNote2, m.IsNote3,
        (SELECT COUNT(*) FROM PROJ.TBL_PURCHASE_ORDER_LINE l WHERE l.PoId = po.PoId AND l.IsActive = 1) AS LineCount,
        (SELECT ISNULL(SUM(l.OrderedQty * l.UnitPrice), 0)
         FROM PROJ.TBL_PURCHASE_ORDER_LINE l WHERE l.PoId = po.PoId AND l.IsActive = 1) AS LinesSubTotal,
        (SELECT ISNULL(SUM(l.OrderedQty * l.UnitPrice * (1 + l.TaxPct / 100)), 0)
         FROM PROJ.TBL_PURCHASE_ORDER_LINE l WHERE l.PoId = po.PoId AND l.IsActive = 1) AS LinesTotalWithTax,
        CAST(CASE WHEN EXISTS (
            SELECT 1 FROM PROJ.TBL_PURCHASE_ORDER_LINE l2
            WHERE l2.PoId = po.PoId AND l2.IsActive = 1 AND l2.ReceivedQty > 0
        ) THEN 1 ELSE 0 END AS BIT) AS HasReceivedLines
    FROM PROJ.TBL_PURCHASE_ORDER          po
    LEFT JOIN PROJ.TBL_SUPPLIER           s  ON s.SupplierId         = po.SupplierId
    LEFT JOIN PROJ.TBL_SUPPLIER_CONTACT   sc ON sc.SupplierContactId = po.SupplierContactId
    LEFT JOIN PROJ.TBL_JOB                j  ON j.JobId              = po.JobId
    LEFT JOIN PROJ.TBL_JOBTYPE            jt ON jt.JobTypeId         = j.JobTypeId
    LEFT JOIN PROJ.TBL_CURRENCY           c  ON c.CurrencyId         = po.CurrencyId
    LEFT JOIN PROJ.TBL_PAYMENT_TERMS      pt ON pt.PaymentTermsId    = po.PaymentTermsId
    LEFT JOIN PROJ.TBL_PURCHASE_ORDER_META m  ON m.PoId              = po.PoId
    LEFT JOIN PROJ.TBL_JOB_EXPENSE_CATEGORY ec ON ec.ExpenseCategoryId = po.ExpenseCategoryId
    OUTER APPLY (
        SELECT
            ISNULL((
                SELECT SUM(pva.AllocatedAmount)
                FROM proj.TBL_PAYMENT_VOUCHER_ALLOCATION pva
                JOIN proj.TBL_PAYMENT_VOUCHER pv ON pv.PvId = pva.PvId
                WHERE pva.PoId = po.PoId AND pva.IsActive = 1
                  AND pv.Status = 'Approved' AND pv.IsActive = 1
            ), 0)
          + ISNULL((
                SELECT SUM(sil.LineTotal / si_t.AllSum * pva.AllocatedAmount)
                FROM proj.TBL_SUPPLIER_INVOICE_LINE       sil
                JOIN proj.TBL_PURCHASE_ORDER_LINE         pol ON pol.PoLineId = sil.PoLineId AND pol.PoId = po.PoId
                JOIN proj.TBL_PAYMENT_VOUCHER_ALLOCATION  pva ON pva.SupplierInvoiceId = sil.SupplierInvoiceId
                                                              AND pva.IsActive = 1 AND pva.PoId IS NULL
                JOIN proj.TBL_PAYMENT_VOUCHER             pv  ON pv.PvId = pva.PvId AND pv.Status = 'Approved' AND pv.IsActive = 1
                JOIN (SELECT SupplierInvoiceId, SUM(ISNULL(LineTotal,0)) AS AllSum
                      FROM proj.TBL_SUPPLIER_INVOICE_LINE WHERE IsActive = 1 GROUP BY SupplierInvoiceId) si_t
                    ON si_t.SupplierInvoiceId = sil.SupplierInvoiceId
                WHERE sil.IsActive = 1 AND si_t.AllSum > 0
            ), 0) AS PaidBase
    ) po_paid
    WHERE po.PoId = @PoId AND po.IsActive = 1;
END
