IF OBJECT_ID(N'[proj].[sp_GetPOAnnexures]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetPOAnnexures];
GO
-- ── Read all annexures + their details + line links for a PO ──────────
CREATE   PROCEDURE proj.sp_GetPOAnnexures
    @PoId INT
AS
BEGIN
    SET NOCOUNT ON;

    -- RS1: Annexure headers
    SELECT a.AnnexureId, a.PoId, a.AnnexureCode, a.Title, a.Notes, a.SortOrder,
           a.IsActive, a.CreatedBy, a.CreatedDate, a.ModifiedBy, a.ModifiedDate,
           (SELECT COUNT(*) FROM proj.TBL_PURCHASE_ORDER_ANNEXURE_DETAIL
            WHERE AnnexureId = a.AnnexureId AND IsActive = 1) AS DetailCount,
           (SELECT COUNT(*) FROM proj.TBL_PURCHASE_ORDER_ANNEXURE_LINE_LINK
            WHERE AnnexureId = a.AnnexureId) AS LineLinkCount
    FROM proj.TBL_PURCHASE_ORDER_ANNEXURE a
    WHERE a.PoId = @PoId AND a.IsActive = 1
    ORDER BY a.SortOrder, a.AnnexureCode;

    -- RS2: All detail rows for those annexures
    SELECT d.AnnexureDetailId, d.AnnexureId, d.LineNum, d.Description, d.Remarks
    FROM proj.TBL_PURCHASE_ORDER_ANNEXURE_DETAIL d
    JOIN proj.TBL_PURCHASE_ORDER_ANNEXURE a ON a.AnnexureId = d.AnnexureId
    WHERE a.PoId = @PoId AND a.IsActive = 1 AND d.IsActive = 1
    ORDER BY d.AnnexureId, d.LineNum;

    -- RS3: Line links (which PO lines each annexure covers)
    SELECT l.AnnexureId, l.PoLineId,
           pol.LineNum AS PoLineNum, pol.ItemDesc
    FROM proj.TBL_PURCHASE_ORDER_ANNEXURE_LINE_LINK l
    JOIN proj.TBL_PURCHASE_ORDER_ANNEXURE a ON a.AnnexureId = l.AnnexureId
    JOIN proj.TBL_PURCHASE_ORDER_LINE pol  ON pol.PoLineId = l.PoLineId
    WHERE a.PoId = @PoId AND a.IsActive = 1;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetPOBudgetCheck]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetPOBudgetCheck];
GO

CREATE   PROCEDURE proj.sp_GetPOBudgetCheck
    @JobId           NVARCHAR(50),
    @CostCategoryId  INT,
    @ExcludePoLineId INT = 0
AS
BEGIN
    SET NOCOUNT ON;

    -- All figures in BASE currency. Budget line carries its own currency/rate.
    DECLARE @JobRate      DECIMAL(18,6) = ISNULL((SELECT JobExcRate FROM proj.TBL_JOB WHERE JobId = @JobId), 1);
    DECLARE @Budgeted     DECIMAL(18,2) = 0;
    DECLARE @CategoryName NVARCHAR(200) = '';

    SELECT @Budgeted = ISNULL(AmountInBaseCurrency, proj.fn_ToBase(ISNULL(BudgetedAmount,0), ISNULL(ExchangeRate, @JobRate)))
    FROM proj.TBL_JOB_BUDGET
    WHERE JobId = @JobId AND CostCategoryId = @CostCategoryId AND IsCurrent = 1;

    SELECT @CategoryName = ISNULL(CategoryName, '')
    FROM proj.TBL_JOB_EXPENSE_CATEGORY
    WHERE ExpenseCategoryId = @CostCategoryId;

    DECLARE @Committed DECIMAL(18,2) = 0;
    SELECT @Committed = ISNULL(SUM(proj.fn_ToBase(pol.OrderedQty * pol.UnitPrice, po.ExchangeRate)), 0)
    FROM proj.TBL_PURCHASE_ORDER      po
    JOIN proj.TBL_PURCHASE_ORDER_LINE pol
        ON pol.PoId = po.PoId AND pol.IsActive = 1
    WHERE po.JobId             = @JobId
      AND po.ExpenseCategoryId = @CostCategoryId
      AND po.Status           != 'Cancelled'
      AND po.IsActive          = 1
      AND pol.PoLineId        != ISNULL(NULLIF(@ExcludePoLineId, 0), -1);

    SELECT
        @CategoryName          AS CategoryName,
        @Budgeted              AS Budgeted,
        @Committed             AS Committed,
        @Budgeted - @Committed AS Remaining;
END
GO

