IF OBJECT_ID(N'[proj].[sp_GetPOLines]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetPOLines];
GO
CREATE PROCEDURE PROJ.sp_GetPOLines
    @PoId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT l.PoLineId, l.PoId, l.LineNum,
           l.PrLineId,
           l.ItemId, ISNULL(l.ItemCode, i.ItemCode) AS ItemCode,
           CASE WHEN l.ItemId IS NOT NULL THEN ISNULL(i.ItemName, l.ItemDesc) ELSE l.ItemDesc END AS ItemDesc,
           l.OrderedQty, l.ReceivedQty,
           l.UomId, ISNULL(u.UomCode, l.UomName) AS UomName,
           l.UnitPrice, l.TaxPct,
           l.OrderedQty * l.UnitPrice                            AS LineTotal,
           l.OrderedQty * l.UnitPrice * (1 + l.TaxPct / 100.0)  AS LineTotalWithTax,
           l.LineStatus,
           l.Remarks, l.CreatedBy, l.CreatedDate
    FROM PROJ.TBL_PURCHASE_ORDER_LINE l
    LEFT JOIN PROJ.TBL_ITEM     i ON i.ItemId = l.ItemId
    LEFT JOIN PROJ.TBL_ITEM_UOM u ON u.UomId  = l.UomId
    WHERE l.PoId = @PoId AND l.IsActive = 1
    ORDER BY l.LineNum, l.PoLineId;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetPOLinesForSRV]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetPOLinesForSRV];
GO
CREATE PROCEDURE proj.sp_GetPOLinesForSRV
    @PoId  INT,
    @SrvId INT = 0    -- pass 0 for new SRV
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        pol.PoLineId,
        pol.LineNum,
        pol.ItemId,
        pol.ItemCode,
        pol.ItemDesc,
        it.TypeCode    AS ItemTypeCode,
        it.TypeName    AS ItemTypeName,
        pol.OrderedQty,
        pol.ReceivedQty,
        pol.OrderedQty - ISNULL(pol.ReceivedQty, 0) AS RemainingQty,
        pol.UomId,
        pol.UomName,
        pol.UnitPrice,
        CASE WHEN EXISTS (
            SELECT 1 FROM proj.TBL_SRV_LINE sl
            JOIN   proj.TBL_SRV_HEADER sh ON sh.SrvId = sl.SrvId
            WHERE  sl.PoLineId = pol.PoLineId
              AND  sl.IsActive = 1
              AND  sh.IsActive = 1
              AND  sh.Status   = 'Confirmed'
              AND  (@SrvId = 0 OR sh.SrvId <> @SrvId)
        ) THEN 1 ELSE 0 END AS AlreadyConfirmed
    FROM  proj.TBL_PURCHASE_ORDER_LINE pol
    JOIN  proj.TBL_ITEM      i  ON i.ItemId      = pol.ItemId
    JOIN  proj.TBL_ITEM_TYPE it ON it.ItemTypeId = i.ItemTypeId
    WHERE pol.PoId = @PoId AND pol.IsActive = 1
      AND (it.IsService = 1 OR it.IsStockable = 0)
    ORDER BY pol.LineNum;
END
GO

