CREATE PROCEDURE proj.sp_GetPOsByPrId
    @PrId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT DISTINCT
        po.PoId,
        po.PoNumber,
        po.PoDate,
        po.Status,
        po.VendorName,
        po.JobId,
        po.TotalAmount,
        po.CurrencyId,
        cur.ShortName   AS CurrencyShort,
        po.CreatedBy,
        po.ModifiedBy,
        po.Revision
    FROM  proj.TBL_PURCHASE_ORDER          po
    JOIN  proj.TBL_PURCHASE_ORDER_LINE     pol ON pol.PoId     = po.PoId     AND pol.IsActive = 1
    JOIN  proj.TBL_PURCHASE_REQUEST_LINE   prl ON prl.PrLineId = pol.PrLineId
    LEFT JOIN proj.TBL_CURRENCY            cur ON cur.CurrencyId = po.CurrencyId
    WHERE prl.PrId     = @PrId
      AND po.IsActive  = 1
    ORDER BY po.PoDate, po.PoNumber;
END;
