CREATE   PROCEDURE PROJ.sp_GetRoles
    @IsActive BIT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT RoleId, RoleName, RoleCode, IsActive, CreatedDate
    FROM   PROJ.TBL_ROLES
    WHERE  (@IsActive IS NULL OR IsActive = @IsActive)
    ORDER  BY RoleName;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetRolesWithSecretStatus]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetRolesWithSecretStatus];
GO

-- List every active role + whether the given secret is configured for it (admin UI)
CREATE   PROCEDURE proj.sp_GetRolesWithSecretStatus
    @SecretKey NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        r.RoleId,
        r.RoleName,
        r.RoleCode,
        CAST(CASE WHEN rs.SecretValueHash IS NOT NULL THEN 1 ELSE 0 END AS BIT) AS IsConfigured,
        rs.ModifiedBy,
        rs.ModifiedDate
    FROM proj.TBL_ROLES r
    LEFT JOIN proj.TBL_ROLE_SECRET rs
           ON rs.RoleId = r.RoleId AND rs.SecretKey = @SecretKey
    WHERE r.IsActive = 1
    ORDER BY r.RoleName;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetRTV]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetRTV];
GO
CREATE PROCEDURE proj.sp_GetRTV
    @RtvId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        r.RtvId, r.RtvNumber, r.RtvDate, r.Status, r.ReturnReason, r.Remarks,
        r.GrnId,  gh.GrnNumber,
        r.PoId,   po.PoNumber,
        r.SupplierId, s.SupplierName, s.SupplierCode,
        r.JobId,
        r.CreatedBy, r.CreatedDate, r.ModifiedBy, r.ModifiedDate,
        (SELECT ISNULL(SUM(l.LineTotal),0) FROM proj.TBL_RETURN_TO_VENDOR_LINE l
         WHERE l.RtvId = r.RtvId AND l.IsActive=1) AS TotalAmount,
        (SELECT COUNT(*) FROM proj.TBL_RETURN_TO_VENDOR_LINE l
         WHERE l.RtvId = r.RtvId AND l.IsActive=1) AS LineCount
    FROM  proj.TBL_RETURN_TO_VENDOR r
    LEFT JOIN proj.TBL_GRN_HEADER     gh ON gh.GrnId    = r.GrnId
    LEFT JOIN proj.TBL_PURCHASE_ORDER po ON po.PoId      = r.PoId
    LEFT JOIN proj.TBL_SUPPLIER        s ON s.SupplierId = r.SupplierId
    WHERE r.RtvId = @RtvId AND r.IsActive = 1;
END;
GO

