    SELECT l.RtvLineId, l.RtvId, l.LineNum, l.GrnDetailId, l.PoLineId, l.PrLineId,
           l.ItemId, l.ItemCode, l.ItemDesc, l.ReturnQty, l.UomId, l.UomName,
           l.UnitCost, l.LineTotal, l.ReturnReason, l.CreatedBy, l.CreatedDate
    FROM   proj.TBL_RETURN_TO_VENDOR_LINE l
