-- ── sp_GetServiceReceipt ─────────────────────────────────────────────────────
CREATE PROCEDURE proj.sp_GetServiceReceipt
    @SrvId INT
AS
BEGIN
    SET NOCOUNT ON;
    -- Header
    SELECT
        h.SrvId, h.SrvNo, h.SrvDate, h.PoId, h.PoNumber,
        h.JobId, h.SupplierName, h.Notes, h.Status, h.IsActive,
        h.CreatedBy, h.CreatedDate, h.ModifiedBy, h.ModifiedDate,
        COUNT(l.SrvLineId) AS LineCount,
        ISNULL(SUM(l.TotalCost), 0) AS TotalCost
    FROM proj.TBL_SRV_HEADER h
    LEFT JOIN proj.TBL_SRV_LINE l ON l.SrvId = h.SrvId AND l.IsActive = 1
    WHERE h.SrvId = @SrvId AND h.IsActive = 1
    GROUP BY h.SrvId, h.SrvNo, h.SrvDate, h.PoId, h.PoNumber,
             h.JobId, h.SupplierName, h.Notes, h.Status, h.IsActive,
             h.CreatedBy, h.CreatedDate, h.ModifiedBy, h.ModifiedDate;

    -- Lines
    SELECT
        l.SrvLineId, l.SrvId, l.LineNum, l.PoLineId,
        l.ItemId, l.ItemCode, l.ItemDesc,
        l.CompletedQty, l.UomId, l.UomName,
        l.UnitCost, l.TotalCost, l.Notes,
        l.IsActive, l.CreatedBy, l.CreatedDate
    FROM proj.TBL_SRV_LINE l
    WHERE l.SrvId = @SrvId AND l.IsActive = 1
    ORDER BY l.LineNum;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetSRVLinesForInvoice]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetSRVLinesForInvoice];
GO
CREATE   PROCEDURE proj.sp_GetSRVLinesForInvoice
    @SrvId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        l.SrvLineId,
        l.SrvId,
        sh.SrvNo                       AS SrvNumber,
        l.PoLineId,
        po.PoNumber,
        l.ItemId,
        l.ItemCode,
        l.ItemDesc,
        l.UomName,
        ISNULL(l.CompletedQty, 0)      AS ReceivedQty,
        ISNULL((
            SELECT SUM(sil.Qty) FROM proj.TBL_SUPPLIER_INVOICE_LINE sil
            WHERE sil.SrvLineId = l.SrvLineId AND sil.IsActive = 1
        ), 0)                          AS AlreadyInvoicedQty,
        ISNULL(l.CompletedQty, 0) - ISNULL((
            SELECT SUM(sil.Qty) FROM proj.TBL_SUPPLIER_INVOICE_LINE sil
            WHERE sil.SrvLineId = l.SrvLineId AND sil.IsActive = 1
        ), 0)                          AS PendingQty,
        l.UnitCost                     AS UnitPrice,
        CAST(0 AS DECIMAL(5,2))        AS TaxPct
    FROM proj.TBL_SRV_LINE l
    INNER JOIN proj.TBL_SRV_HEADER sh ON sh.SrvId = l.SrvId
    LEFT JOIN  proj.TBL_PURCHASE_ORDER po ON po.PoId = sh.PoId
    WHERE l.SrvId = @SrvId
      AND l.IsActive = 1
      AND ISNULL(l.CompletedQty, 0) > ISNULL((
            SELECT SUM(sil.Qty) FROM proj.TBL_SUPPLIER_INVOICE_LINE sil
            WHERE sil.SrvLineId = l.SrvLineId AND sil.IsActive = 1
          ), 0)
    ORDER BY l.LineNum;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetSRVsForSupplierInvoice]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetSRVsForSupplierInvoice];
GO
CREATE PROCEDURE proj.sp_GetSRVsForSupplierInvoice
    @SupplierId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        sh.SrvId,
        sh.SrvNo                       AS SrvNumber,
        sh.SrvDate,
        po.PoNumber,
        (SELECT ISNULL(SUM(l2.TotalCost),0) FROM proj.TBL_SRV_LINE l2 WHERE l2.SrvId=sh.SrvId AND l2.IsActive=1) AS TotalAmount,
        sh.Status
    FROM proj.TBL_SRV_HEADER sh
    INNER JOIN proj.TBL_PURCHASE_ORDER po ON po.PoId = sh.PoId
    WHERE po.SupplierId = @SupplierId
      AND sh.IsActive   = 1
      AND sh.Status     IN ('Confirmed', 'Invoiced')   -- include partially-invoiced SRVs
      AND EXISTS (
            SELECT 1 FROM proj.TBL_SRV_LINE l
            WHERE l.SrvId = sh.SrvId AND l.IsActive = 1
              AND ISNULL(l.CompletedQty, 0) > ISNULL((
                    SELECT SUM(sil.Qty) FROM proj.TBL_SUPPLIER_INVOICE_LINE sil
                    WHERE sil.SrvLineId = l.SrvLineId AND sil.IsActive = 1
                  ), 0)
      )
    ORDER BY sh.SrvDate DESC, sh.SrvId DESC;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetStockAlerts]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetStockAlerts];
GO
CREATE   PROCEDURE proj.sp_GetStockAlerts
    @AlertType     VARCHAR(20)   = NULL,
    @SearchText    NVARCHAR(200) = NULL,
    @CategoryId    INT           = NULL,
    @SubCategoryId INT           = NULL,
    @ItemTypeId    INT           = NULL,
    @ItemId        INT           = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        i.ItemId, i.ItemCode, i.ItemName,
        cat.CategoryName,
        it.TypeName                            AS ItemTypeName,
        u.UomCode                              AS BaseUom,
        ISNULL(sb.QtyOnHand,      0)           AS QtyOnHand,
        ISNULL(id.MinStockLevel,  0)           AS MinStockLevel,
        ISNULL(id.ReorderLevel,   0)           AS ReorderLevel,
        ISNULL(id.MaxStockLevel,  0)           AS MaxStockLevel,
        ISNULL(id.LeadTimeDays,   0)           AS LeadTimeDays,
        CASE
            WHEN ISNULL(id.MinStockLevel, 0) > 0
                 AND ISNULL(sb.QtyOnHand, 0) < ISNULL(id.MinStockLevel, 0)
            THEN ISNULL(id.MinStockLevel, 0) - ISNULL(sb.QtyOnHand, 0)
            ELSE 0
        END                                    AS Shortage,
        CASE
            WHEN ISNULL(id.MaxStockLevel, 0) > 0 AND ISNULL(sb.QtyOnHand, 0) > ISNULL(id.MaxStockLevel, 0)
            THEN ISNULL(sb.QtyOnHand, 0) - ISNULL(id.MaxStockLevel, 0)
            ELSE 0
        END                                    AS Excess,
        CASE
            WHEN ISNULL(sb.QtyOnHand, 0) = 0                                                              THEN 'ZERO_STOCK'
            WHEN ISNULL(sb.QtyOnHand, 0) < ISNULL(id.MinStockLevel, 0) AND ISNULL(id.MinStockLevel, 0) > 0 THEN 'BELOW_MIN'
            WHEN ISNULL(sb.QtyOnHand, 0) <= ISNULL(id.ReorderLevel,  0) AND ISNULL(id.ReorderLevel,  0) > 0 THEN 'BELOW_REORDER'
            WHEN ISNULL(id.MaxStockLevel, 0) > 0 AND ISNULL(sb.QtyOnHand, 0) > ISNULL(id.MaxStockLevel, 0)   THEN 'OVERSTOCK'
        END                                    AS AlertType,
        sb.LastReceiptDate
    FROM proj.TBL_ITEM i
    LEFT JOIN (
        SELECT ItemId, MIN(ItemDetailId) AS ItemDetailId
        FROM   proj.TBL_ITEM_DETAIL
        WHERE  ISNULL(IsActive, 1) = 1
        GROUP BY ItemId
    ) idsel ON idsel.ItemId = i.ItemId
    LEFT JOIN proj.TBL_ITEM_DETAIL   id  ON id.ItemDetailId  = idsel.ItemDetailId
    JOIN  proj.TBL_STOCK_BALANCE     sb  ON sb.ItemId        = i.ItemId
    LEFT JOIN proj.TBL_ITEM_CATEGORY cat ON cat.CategoryId   = i.CategoryId
    LEFT JOIN proj.TBL_ITEM_TYPE     it  ON it.ItemTypeId    = i.ItemTypeId
    LEFT JOIN proj.TBL_ITEM_UOM      u   ON u.UomId          = i.BaseUomId
    WHERE
        i.IsActive    = 1
        AND i.IsStockable = 1
        AND (
               sb.QtyOnHand = 0
            OR (sb.QtyOnHand <  ISNULL(id.MinStockLevel,  0) AND ISNULL(id.MinStockLevel,  0) > 0)
            OR (sb.QtyOnHand <= ISNULL(id.ReorderLevel,   0) AND ISNULL(id.ReorderLevel,   0) > 0)
            OR (sb.QtyOnHand >  ISNULL(id.MaxStockLevel,   0) AND ISNULL(id.MaxStockLevel,  0) > 0)
        )
        AND (
            @AlertType IS NULL
            OR (@AlertType = 'ZERO_STOCK'    AND sb.QtyOnHand = 0)
            OR (@AlertType = 'BELOW_MIN'     AND sb.QtyOnHand <  ISNULL(id.MinStockLevel, 0) AND ISNULL(id.MinStockLevel, 0) > 0)
            OR (@AlertType = 'BELOW_REORDER' AND sb.QtyOnHand <= ISNULL(id.ReorderLevel,  0) AND ISNULL(id.ReorderLevel,  0) > 0)
            OR (@AlertType = 'OVERSTOCK'     AND sb.QtyOnHand >  ISNULL(id.MaxStockLevel,  0) AND ISNULL(id.MaxStockLevel,  0) > 0)
        )
        AND (@ItemId IS NULL OR i.ItemId = @ItemId)
        AND (
               (@CategoryId IS NULL AND @SubCategoryId IS NULL)
            OR (@SubCategoryId IS NOT NULL AND i.CategoryId = @SubCategoryId)
            OR (@SubCategoryId IS NULL AND @CategoryId IS NOT NULL AND (
                   i.CategoryId = @CategoryId
                   OR i.CategoryId IN (SELECT CategoryId FROM proj.TBL_ITEM_CATEGORY WHERE ParentCategoryId = @CategoryId)
               ))
        )
        AND (@ItemTypeId IS NULL OR i.ItemTypeId = @ItemTypeId)
        AND (@SearchText IS NULL OR i.ItemCode LIKE N'%' + @SearchText + N'%' OR i.ItemName LIKE N'%' + @SearchText + N'%')
    ORDER BY
        CASE
            WHEN sb.QtyOnHand = 0 THEN 1
            WHEN sb.QtyOnHand < ISNULL(id.MinStockLevel, 0) AND ISNULL(id.MinStockLevel, 0) > 0 THEN 2
            WHEN sb.QtyOnHand <= ISNULL(id.ReorderLevel, 0) AND ISNULL(id.ReorderLevel, 0) > 0 THEN 3
            ELSE 4
        END,
        i.ItemCode;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetStockAvailability]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetStockAvailability];
GO
-- sp_GetStockAvailability: remove IsJobStock=1 filter from in-house balance check
CREATE PROCEDURE proj.sp_GetStockAvailability
    @ItemId      INT,
    @JobId       NVARCHAR(50)  = NULL,
    @CostingType NVARCHAR(20)  = 'INC_COSTING'
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @AvailableQty DECIMAL(18,4) = 0,
            @JobStock     DECIMAL(18,4) = 0,
            @StoreStock   DECIMAL(18,4) = 0;

    SELECT @JobStock   = ISNULL(QtyJobStock,   0),
           @StoreStock = ISNULL(QtyStoreStock, 0)
    FROM   proj.TBL_STOCK_BALANCE
    WHERE  ItemId = @ItemId;

    DECLARE @SourceJobId NVARCHAR(50) = NULL;
    SELECT TOP 1 @SourceJobId = j.JobId
    FROM proj.TBL_ITEM it
    JOIN proj.TBL_JOB        j  ON j.BudgetCategoryId = it.BudgetCategoryId
    JOIN proj.TBL_JOBTYPE    jt ON jt.JobTypeId = j.JobTypeId AND ISNULL(jt.IsBudgetHeaderLinked,0) = 1
    JOIN proj.TBL_JOB_STATUS js ON js.JobStatusId = j.JobStatusId AND ISNULL(js.IsClosed,0) = 0
    WHERE it.ItemId = @ItemId AND it.BudgetCategoryId IS NOT NULL
    ORDER BY j.JobCreatedDate DESC;

    IF @SourceJobId IS NOT NULL
    BEGIN
        -- In-house stock is IsJobStock=0; filter by JobId only
        SELECT @AvailableQty = ISNULL(SUM(QtyIn - QtyOut), 0)
        FROM  proj.TBL_STOCK_LEDGER
        WHERE ItemId = @ItemId AND JobId = @SourceJobId;
    END
    ELSE IF @CostingType = 'EXC_COSTING' AND @JobId IS NOT NULL
    BEGIN
        SELECT @AvailableQty =
            ISNULL(SUM(CASE WHEN QtyIn  > 0 AND IsJobStock = 1 AND JobId = @JobId THEN QtyIn  ELSE 0 END), 0)
          - ISNULL(SUM(CASE WHEN QtyOut > 0                    AND JobId = @JobId THEN QtyOut ELSE 0 END), 0)
        FROM  proj.TBL_STOCK_LEDGER
        WHERE ItemId = @ItemId;
    END
    ELSE
    BEGIN
        SET @AvailableQty = @StoreStock;
    END

    SELECT
        @ItemId      AS ItemId,
        @JobId       AS JobId,
        @CostingType AS CostingType,
        ISNULL(@AvailableQty, 0) AS AvailableQty,
        @JobStock    AS JobStock,
        @StoreStock  AS StoreStock,
        @SourceJobId AS SourceInHouseJobId;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetStockBalance]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetStockBalance];
GO

CREATE PROCEDURE proj.sp_GetStockBalance
    @SearchText      NVARCHAR(100) = NULL,
    @CategoryId      INT           = NULL,
    @SubCategoryId   INT           = NULL,
    @ItemTypeId      INT           = NULL,
    @StockType       NVARCHAR(10)  = NULL,
    @DateFrom        DATE          = NULL,
    @DateTo          DATE          = NULL,
    @ZeroStock       BIT           = 0,
    @ItemId          INT           = NULL,
    @BudgetCategoryId INT          = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        b.BalanceId,
        i.ItemId,
        i.ItemCode, i.ItemName,
        c.CategoryName,
        t.TypeName  AS ItemTypeName,
        u.UomName   AS BaseUom,
        ISNULL(b.QtyOnHand,    0) AS QtyOnHand,
        ISNULL(b.QtyJobStock,  0) AS QtyJobStock,
        ISNULL(b.QtyStoreStock,0) AS QtyStoreStock,
        ISNULL(b.AvgUnitCost,  0) AS AvgUnitCost,
        CAST(ISNULL(b.QtyOnHand,0) * ISNULL(b.AvgUnitCost,0) AS DECIMAL(18,4)) AS StockValue,
        b.LastReceiptDate, b.LastIssueDate, b.UpdatedDate
    FROM proj.TBL_ITEM i
    LEFT  JOIN proj.TBL_STOCK_BALANCE  b  ON b.ItemId     = i.ItemId
    LEFT  JOIN proj.TBL_ITEM_CATEGORY  c  ON c.CategoryId = i.CategoryId
    LEFT  JOIN proj.TBL_ITEM_TYPE      t  ON t.ItemTypeId = i.ItemTypeId
    LEFT  JOIN proj.TBL_ITEM_UOM       u  ON u.UomId      = i.BaseUomId
    WHERE i.IsActive = 1
      AND (@ZeroStock = 1 OR ISNULL(b.QtyOnHand, 0) > 0)
      AND (@StockType IS NULL
           OR (@StockType = 'JOB'   AND ISNULL(b.QtyJobStock,  0) > 0)
           OR (@StockType = 'STORE' AND ISNULL(b.QtyStoreStock, 0) > 0))
      AND (@ItemId IS NULL OR i.ItemId = @ItemId)
      AND (
              (@CategoryId IS NULL AND @SubCategoryId IS NULL)
           OR (@SubCategoryId IS NOT NULL AND i.CategoryId = @SubCategoryId)
           OR (@SubCategoryId IS NULL AND @CategoryId IS NOT NULL AND (
                  i.CategoryId = @CategoryId
                  OR i.CategoryId IN (SELECT CategoryId FROM proj.TBL_ITEM_CATEGORY WHERE ParentCategoryId = @CategoryId)
               ))
          )
      AND (@ItemTypeId IS NULL OR i.ItemTypeId = @ItemTypeId)
      AND (@DateFrom IS NULL OR CAST(b.LastReceiptDate AS DATE) >= @DateFrom)
      AND (@DateTo   IS NULL OR CAST(b.LastReceiptDate AS DATE) <= @DateTo)
      AND (@SearchText IS NULL OR i.ItemCode LIKE N'%'+@SearchText+N'%'
                               OR i.ItemName LIKE N'%'+@SearchText+N'%')
      AND (@BudgetCategoryId IS NULL OR EXISTS (
              SELECT 1
              FROM proj.TBL_STOCK_LEDGER sl
              JOIN proj.TBL_JOB j ON j.JobId = sl.JobId
              WHERE sl.ItemId = i.ItemId
                AND j.BudgetCategoryId = @BudgetCategoryId
          ))
    ORDER BY i.ItemCode;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetStockByJob]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetStockByJob];
GO
CREATE PROCEDURE PROJ.sp_GetStockByJob
    @SearchText NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH JobItem AS (
        SELECT
            l.JobId,
            l.ItemId,
            SUM(l.QtyIn - l.QtyOut)                          AS QtyBalance,
            SUM(l.QtyIn * l.UnitCost - l.QtyOut * l.UnitCost) AS ValueBalance
        FROM proj.TBL_STOCK_LEDGER l
        WHERE l.JobId IS NOT NULL
        GROUP BY l.JobId, l.ItemId
        HAVING SUM(l.QtyIn - l.QtyOut) > 0
    ),
    JobAgg AS (
        SELECT
            ji.JobId,
            COUNT(*)              AS ItemCount,
            SUM(ji.QtyBalance)    AS TotalQty,
            SUM(ji.ValueBalance)  AS TotalValue
        FROM JobItem ji
        GROUP BY ji.JobId
    )
    SELECT
        a.JobId,
        j.ProjectName,
        j.JobDescription,
        j.JobTypeId,
        jt.JobTypeName,
        j.CustomerId,
        c.CustomerName,
        j.JobStatusId,
        js.StatusName               AS JobStatusName,
        a.ItemCount,
        a.TotalQty,
        a.TotalValue
    FROM JobAgg a
    INNER JOIN proj.TBL_JOB          j  ON j.JobId       = a.JobId
    LEFT  JOIN proj.TBL_JOBTYPE      jt ON jt.JobTypeId  = j.JobTypeId
    LEFT  JOIN proj.TBL_CUSTOMER     c  ON c.CustomerId  = j.CustomerId
    LEFT  JOIN proj.TBL_JOB_STATUS   js ON js.JobStatusId = j.JobStatusId
    WHERE (@SearchText IS NULL
           OR a.JobId          LIKE '%' + @SearchText + '%'
           OR j.ProjectName    LIKE '%' + @SearchText + '%'
           OR c.CustomerName   LIKE '%' + @SearchText + '%'
           OR jt.JobTypeName   LIKE '%' + @SearchText + '%')
    ORDER BY a.TotalValue DESC, a.JobId;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetStockIssue]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetStockIssue];
GO
CREATE PROCEDURE proj.sp_GetStockIssue
    @IssueId INT           = NULL,
    @IssueNo NVARCHAR(30)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Id INT = @IssueId;
    IF @Id IS NULL OR @Id = 0
        SELECT @Id = IssueId FROM proj.TBL_STOCK_ISSUE WHERE IssueNo = @IssueNo AND IsActive = 1;

    -- Header (with job customer/project info + actual ledger posting datetime)
    SELECT i.IssueId, i.IssueNo, i.IssueDate, i.JobId, i.CostingType,
           i.IssuedTo, i.Notes, i.Status,
           i.CreatedBy, i.CreatedDate, i.ModifiedBy, i.ModifiedDate,
           j.CustomerName, j.ProjectName,
           (SELECT TOP 1 sl.TransDate
            FROM proj.TBL_STOCK_LEDGER sl
            WHERE sl.TransType = 'ISSUE' AND sl.RefId = i.IssueId
            ORDER BY sl.LedgerId DESC)  AS PostedDate
    FROM   proj.TBL_STOCK_ISSUE i
    LEFT   JOIN proj.VW_JOB j ON j.JobId = i.JobId
    WHERE  i.IssueId = @Id AND i.IsActive = 1;

    -- Lines
    SELECT l.IssueLineId, l.IssueId, l.LineNum,
           l.ItemId, it.ItemCode, it.ItemName, l.ItemDesc,
           l.Qty, l.UomId, u.UomName, l.UnitCost,
           CAST(l.Qty * l.UnitCost AS DECIMAL(18,4)) AS TotalCost,
           l.Notes, l.CreatedBy, l.CreatedDate, l.ModifiedBy, l.ModifiedDate
    FROM   proj.TBL_STOCK_ISSUE_LINE l
    INNER  JOIN proj.TBL_ITEM     it ON it.ItemId = l.ItemId
    LEFT   JOIN proj.TBL_ITEM_UOM u  ON u.UomId   = l.UomId
    WHERE  l.IssueId = @Id AND l.IsActive = 1
    ORDER  BY l.LineNum;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetStockLedger]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetStockLedger];
GO

CREATE PROCEDURE proj.sp_GetStockLedger
    @ItemId     INT,
    @DateFrom   DATE = NULL,
    @DateTo     DATE = NULL,
    @PageNumber INT  = 1,
    @PageSize   INT  = 50
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

    -- Running balances must be computed over ALL rows first (before pagination)
    -- so the balance on page 2 correctly carries forward from page 1.
    WITH Ledger AS (
        SELECT
            l.LedgerId, l.ItemId, l.TransDate, l.TransType,
            l.RefId, l.RefNo, l.QtyIn, l.QtyOut, l.UnitCost,
            CAST(CASE WHEN l.QtyIn > 0 THEN l.QtyIn * l.UnitCost
                      ELSE l.QtyOut * l.UnitCost END AS DECIMAL(18,4)) AS LineValue,
            l.IsJobStock, l.JobId, l.CreatedBy,
            -- Running total stock (QtyOnHand after this entry)
            SUM(l.QtyIn - l.QtyOut)
                OVER (PARTITION BY l.ItemId ORDER BY l.LedgerId
                      ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
                AS RunningTotalStock,
            -- Running job stock
            SUM(CASE WHEN l.IsJobStock = 1 THEN l.QtyIn - l.QtyOut ELSE 0 END)
                OVER (PARTITION BY l.ItemId ORDER BY l.LedgerId
                      ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
                AS RunningJobStock,
            COUNT(*) OVER () AS TotalRows
        FROM proj.TBL_STOCK_LEDGER l
        WHERE l.ItemId = @ItemId
          AND (@DateFrom IS NULL OR CAST(l.TransDate AS DATE) >= @DateFrom)
          AND (@DateTo   IS NULL OR CAST(l.TransDate AS DATE) <= @DateTo)
    )
    SELECT
        LedgerId, ItemId, TransDate, TransType,
        RefId, RefNo, QtyIn, QtyOut, UnitCost, LineValue,
        IsJobStock, JobId, CreatedBy,
        CAST(RunningTotalStock AS DECIMAL(18,4)) AS TotalStock,
        CAST(RunningJobStock   AS DECIMAL(18,4)) AS JobStock,
        CAST(RunningTotalStock - RunningJobStock AS DECIMAL(18,4)) AS StoreStock,
        TotalRows
    FROM Ledger
    ORDER BY LedgerId DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetStockReceipt]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetStockReceipt];
GO
CREATE PROCEDURE proj.sp_GetStockReceipt
    @ReceiptId INT = NULL,
    @ReceiptNo NVARCHAR(30) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Id INT = @ReceiptId;
    IF @Id IS NULL OR @Id = 0
        SELECT @Id = ReceiptId FROM proj.TBL_STOCK_RECEIPT WHERE ReceiptNo = @ReceiptNo AND IsActive = 1;

    -- Header
    SELECT r.ReceiptId, r.ReceiptNo, r.ReceiptDate, r.ReceiptType,
           r.JobId, r.PoId, r.PoNumber, r.SupplierId, r.SupplierName, r.SupplierRef,
           r.Notes, r.Status, r.GrnId, r.CreatedBy, r.CreatedDate, r.ModifiedBy, r.ModifiedDate
    FROM proj.TBL_STOCK_RECEIPT r
    WHERE r.ReceiptId = @Id AND r.IsActive = 1;

    -- Lines
    SELECT l.ReceiptLineId, l.ReceiptId, l.LineNum,
           l.ItemId, i.ItemCode, i.ItemName, l.ItemDesc,
           l.Qty, l.UomId, u.UomName, l.UnitCost,
           CAST(l.Qty * l.UnitCost AS DECIMAL(18,4)) AS TotalCost,
           l.IsJobStock, l.JobId AS LineJobId, l.Notes,
           l.CreatedBy, l.CreatedDate, l.ModifiedBy, l.ModifiedDate
    FROM proj.TBL_STOCK_RECEIPT_LINE l
    INNER JOIN proj.TBL_ITEM   i ON i.ItemId  = l.ItemId
    LEFT JOIN  proj.TBL_ITEM_UOM u ON u.UomId = l.UomId
    WHERE l.ReceiptId = @Id AND l.IsActive = 1
    ORDER BY l.LineNum;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetStockTransfer]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetStockTransfer];
GO

-- 3. Update sp_GetStockTransfer — return TransferReason and new audit fields
CREATE   PROCEDURE proj.sp_GetStockTransfer
    @TransferId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        t.TransferId, t.TransferNo, t.TransferDate, t.Status,
        t.TransferReason, t.Notes, t.IsActive,
        t.FromJobId, fj.ProjectName AS FromJobName,
        t.ToJobId,   tj.ProjectName AS ToJobName,
        t.CreatedBy, t.CreatedDate,
        t.ModifiedBy, t.ModifiedDate,
        (SELECT COUNT(*) FROM proj.TBL_STOCK_TRANSFER_LINE l
         WHERE l.TransferId = t.TransferId AND l.IsActive = 1) AS LineCount
    FROM proj.TBL_STOCK_TRANSFER t
    LEFT JOIN proj.TBL_JOB fj ON fj.JobId = t.FromJobId
    LEFT JOIN proj.TBL_JOB tj ON tj.JobId = t.ToJobId
    WHERE t.TransferId = @TransferId;

    SELECT
        l.TransferLineId, l.TransferId, l.LineNum, l.ItemId,
        i.ItemCode, i.ItemName,
        l.Qty, l.AvailableQty,
        l.UomId, u.UomCode, u.UomName,
        l.UnitCost,
        (l.Qty * l.UnitCost) AS LineValue,
        l.Notes
    FROM proj.TBL_STOCK_TRANSFER_LINE l
    LEFT JOIN proj.TBL_ITEM     i ON i.ItemId = l.ItemId
    LEFT JOIN proj.TBL_ITEM_UOM u ON u.UomId  = l.UomId
    WHERE l.TransferId = @TransferId AND l.IsActive = 1
    ORDER BY l.LineNum;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetSubcontractList]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetSubcontractList];
GO
CREATE   PROCEDURE proj.sp_GetSubcontractList
    @Search          NVARCHAR(100)   = NULL,
    @Status          NVARCHAR(20)    = NULL,
    @SubcontractType NVARCHAR(20)    = NULL,
    @VendorId        INT             = NULL,
    @JobId           NVARCHAR(50)    = NULL,
    @Page            INT             = 1,
    @PageSize        INT             = 20,
    @TotalRows       INT             OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT @TotalRows = COUNT(*)
    FROM proj.TBL_SUBCONTRACT_ORDER o
    LEFT JOIN proj.TBL_SUPPLIER s ON s.SupplierId = o.VendorId
    WHERE o.IsActive = 1
      AND (@Status          IS NULL OR o.Status          = @Status)
      AND (@SubcontractType IS NULL OR o.SubcontractType = @SubcontractType)
      AND (@VendorId        IS NULL OR o.VendorId        = @VendorId)
      AND (@JobId           IS NULL OR o.JobId           = @JobId)
      AND (@Search IS NULL OR
           o.SubcontractNo      LIKE '%' + @Search + '%' OR
           s.SupplierName       LIKE '%' + @Search + '%' OR
           o.ServiceDescription LIKE '%' + @Search + '%' OR
           o.JobId              LIKE '%' + @Search + '%');

    SELECT
        o.SubcontractId,
        o.SubcontractNo,
        o.SubcontractType,
        o.Status,
        o.VendorId,
        s.SupplierName  AS VendorName,
        o.JobId,
        o.OutputItemId,
        i.ItemCode      AS OutputItemCode,
        i.ItemName      AS OutputItemName,
        o.OutputQty,
        o.ExpectedDate,
        o.PoId,
        po.PoNumber,
        o.CreatedBy,
        o.CreatedDate,
        o.ModifiedDate,
        ISNULL(sr.TotalReceivedQty, 0) AS TotalReceivedQty
    FROM proj.TBL_SUBCONTRACT_ORDER o
    LEFT JOIN proj.TBL_SUPPLIER       s  ON s.SupplierId  = o.VendorId
    LEFT JOIN proj.TBL_ITEM           i  ON i.ItemId       = o.OutputItemId
    LEFT JOIN proj.TBL_PURCHASE_ORDER po ON po.PoId        = o.PoId
    LEFT JOIN (
        SELECT SubcontractId, SUM(ReceivedQty) AS TotalReceivedQty
        FROM proj.TBL_SUBCONTRACT_RECEIPT
        WHERE Status = 'Posted' AND IsActive = 1
        GROUP BY SubcontractId
    ) sr ON sr.SubcontractId = o.SubcontractId
    WHERE o.IsActive = 1
      AND (@Status          IS NULL OR o.Status          = @Status)
      AND (@SubcontractType IS NULL OR o.SubcontractType = @SubcontractType)
      AND (@VendorId        IS NULL OR o.VendorId        = @VendorId)
      AND (@JobId           IS NULL OR o.JobId           = @JobId)
      AND (@Search IS NULL OR
           o.SubcontractNo      LIKE '%' + @Search + '%' OR
           s.SupplierName       LIKE '%' + @Search + '%' OR
           o.ServiceDescription LIKE '%' + @Search + '%' OR
           o.JobId              LIKE '%' + @Search + '%')
    ORDER BY o.SubcontractId DESC
    OFFSET (@Page - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetSubcontractOrder]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetSubcontractOrder];
GO
CREATE   PROCEDURE proj.sp_GetSubcontractOrder
    @SubcontractId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        o.SubcontractId,
        o.SubcontractNo,
        o.SubcontractType,
        o.VendorId,
        s.SupplierName  AS VendorName,
        s.SupplierCode  AS VendorCode,
        o.JobId,
        o.BudgetHeaderId,
        o.OutputItemId,
        i.ItemCode      AS OutputItemCode,
        i.ItemName      AS OutputItemName,
        o.OutputQty,
        o.OutputUomId,
        u.UomName       AS OutputUomName,
        o.ServiceDescription,
        o.ExpectedDate,
        o.Status,
        o.Remarks,
        o.PoId,
        po.PoNumber,
        o.CreatedBy,
        o.CreatedDate,
        o.ModifiedBy,
        o.ModifiedDate,
        ISNULL(sc.TotalComponents, 0)  AS TotalComponents,
        ISNULL(mo.TotalIssued, 0)      AS TotalMaterialOuts,
        ISNULL(sr.TotalReceipts, 0)    AS TotalReceipts,
        ISNULL(sr.TotalReceivedQty, 0) AS TotalReceivedQty
    FROM proj.TBL_SUBCONTRACT_ORDER o
    LEFT JOIN proj.TBL_SUPPLIER      s  ON s.SupplierId = o.VendorId
    LEFT JOIN proj.TBL_ITEM          i  ON i.ItemId     = o.OutputItemId
    LEFT JOIN proj.TBL_ITEM_UOM      u  ON u.UomId      = o.OutputUomId
    LEFT JOIN proj.TBL_PURCHASE_ORDER po ON po.PoId     = o.PoId
    LEFT JOIN (
        SELECT SubcontractId, COUNT(*) AS TotalComponents
        FROM proj.TBL_SUBCONTRACT_COMPONENT WHERE IsActive = 1
        GROUP BY SubcontractId
    ) sc ON sc.SubcontractId = o.SubcontractId
    LEFT JOIN (
        SELECT SubcontractId, COUNT(*) AS TotalIssued
        FROM proj.TBL_MATERIAL_OUT WHERE IsActive = 1 AND Status = 'Posted'
        GROUP BY SubcontractId
    ) mo ON mo.SubcontractId = o.SubcontractId
    LEFT JOIN (
        SELECT SubcontractId,
               COUNT(*)         AS TotalReceipts,
               SUM(ReceivedQty) AS TotalReceivedQty
        FROM proj.TBL_SUBCONTRACT_RECEIPT WHERE IsActive = 1 AND Status = 'Posted'
        GROUP BY SubcontractId
    ) sr ON sr.SubcontractId = o.SubcontractId
    WHERE o.IsActive = 1
      AND (@SubcontractId IS NULL OR o.SubcontractId = @SubcontractId);

    IF @SubcontractId IS NOT NULL
    BEGIN
        SELECT
            c.ComponentId,
            c.SubcontractId,
            c.ItemId,
            i.ItemCode,
            i.ItemName,
            c.UomId,
            u.UomName,
            c.RequiredQty,
            c.IssuedQty,
            ISNULL(sb.QtyOnHand, 0) AS QtyOnHand
        FROM proj.TBL_SUBCONTRACT_COMPONENT c
        LEFT JOIN proj.TBL_ITEM         i  ON i.ItemId  = c.ItemId
        LEFT JOIN proj.TBL_ITEM_UOM     u  ON u.UomId   = c.UomId
        LEFT JOIN proj.TBL_STOCK_BALANCE sb ON sb.ItemId = c.ItemId
        WHERE c.SubcontractId = @SubcontractId AND c.IsActive = 1
        ORDER BY c.ComponentId;
    END
END;
GO

