CREATE   PROCEDURE proj.sp_GetSubcontractReceiptList
    @SubcontractId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        r.SubcontractReceiptId,
        r.ReceiptNo,
        r.SubcontractId,
        r.VendorId,
        r.ReceiptDate,
        r.ReceivedQty,
        r.UnitCost,
        r.VendorRef,
