CREATE   PROCEDURE proj.sp_GetSupplier
    @SupplierId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        V.*,
        (SELECT COUNT(*) FROM proj.TBL_SUPPLIER_CONTACT WHERE SupplierId = V.SupplierId AND IsActive = 1) AS ContactCount,
        (SELECT COUNT(*) FROM proj.TBL_SUPPLIER_ADDRESS WHERE SupplierId = V.SupplierId AND IsActive = 1) AS AddressCount,
        (SELECT COUNT(*) FROM proj.TBL_SUPPLIER_BANK    WHERE SupplierId = V.SupplierId AND IsActive = 1) AS BankCount
    FROM proj.VW_SUPPLIER V
    WHERE V.SupplierId = @SupplierId;
END
GO

