-- Fix: filter inactive records out of the address list
CREATE   PROCEDURE proj.sp_GetSupplierAddressList
    @SupplierId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT A.*, C.CountryName
    FROM   proj.TBL_SUPPLIER_ADDRESS A
    LEFT JOIN proj.TBL_COUNTRY C ON A.CountryId = C.CountryId
    WHERE  A.SupplierId = @SupplierId
      AND  A.IsActive   = 1;
END
