CREATE   PROCEDURE proj.sp_GetSupplierBankList
    @SupplierId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        B.SupplierBankId, B.SupplierId, B.BankName, B.AccountName,
        B.AccountNumber, B.IBAN, B.SwiftCode, B.BranchName,
        B.CurrencyId,
        C.CurrencyName, C.ShortName AS CurrencyShortName, C.Symbol AS CurrencySymbol,
        B.IsDefault, B.IsActive, B.CreatedBy, B.ModifiedBy
    FROM proj.TBL_SUPPLIER_BANK B
