IF OBJECT_ID(N'[proj].[sp_GetSupplierInvoice]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetSupplierInvoice];
GO

CREATE PROCEDURE proj.sp_GetSupplierInvoice
    @SupplierInvoiceId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        si.SupplierInvoiceId, si.InvoiceNo, si.SupplierInvRef, si.InvoiceDate,
        si.SupplierId, s.SupplierName,
        si.CurrencyId, si.ExchangeRate, si.PaymentTermsId, pt.TermName AS PaymentTermsName,
        si.DueDate, si.SubTotal, si.TaxAmount, si.TotalAmount, si.Notes, si.Status,
        si.CreatedBy, si.CreatedDate, si.ModifiedBy, si.ModifiedDate,
        -- AllocatedAmount is BASE; divide by invoice rate for invoice-currency display
        ROUND(alloc.PvBase / NULLIF(si.ExchangeRate, 0), 2)  AS PaidAmount,
        ROUND(alloc.DnBase / NULLIF(si.ExchangeRate, 0), 2)  AS DebitNoteAmount,
        si.TotalAmount
            - ROUND(alloc.PvBase / NULLIF(si.ExchangeRate, 0), 2)
            - ROUND(alloc.DnBase / NULLIF(si.ExchangeRate, 0), 2) AS BalanceAmount
    FROM proj.TBL_SUPPLIER_INVOICE si
    INNER JOIN proj.TBL_SUPPLIER s     ON s.SupplierId     = si.SupplierId
    LEFT JOIN  proj.TBL_PAYMENT_TERMS pt ON pt.PaymentTermsId = si.PaymentTermsId
    OUTER APPLY (
        SELECT
            ISNULL((
                SELECT SUM(a.AllocatedAmount)
                FROM   proj.TBL_PAYMENT_VOUCHER_ALLOCATION a
                JOIN   proj.TBL_PAYMENT_VOUCHER pv ON pv.PvId = a.PvId
                WHERE  a.SupplierInvoiceId = si.SupplierInvoiceId
                  AND  a.IsActive = 1 AND pv.IsActive = 1 AND pv.Status = 'Approved'
            ), 0) AS PvBase,
            ISNULL((
                SELECT SUM(a.AllocatedAmount)
                FROM   proj.TBL_DEBIT_NOTE_ALLOCATION a
                JOIN   proj.TBL_DEBIT_NOTE dn ON dn.DnId = a.DnId
                WHERE  a.SupplierInvoiceId = si.SupplierInvoiceId
                  AND  a.IsActive = 1 AND dn.IsActive = 1 AND dn.Status = 'Approved'
            ), 0) AS DnBase
    ) alloc
    WHERE si.SupplierInvoiceId = @SupplierInvoiceId AND si.IsActive = 1;

    SELECT
        l.SupplierInvLineId, l.SupplierInvoiceId, l.LineNum,
        l.GrnDetailId, l.GrnId, g.GrnNumber,
        l.SrvId, l.SrvLineId, sh.SrvNo AS SrvNumber,
        l.PoLineId,
        ISNULL(po_g.PoNumber, po_s.PoNumber) AS PoNumber,
        l.ItemId, l.ItemCode, l.ItemDesc, l.UomName,
        l.Qty, l.UnitPrice, l.TaxPct, l.TaxAmount,
        l.LineTotal, l.LineTotalWithTax, l.Notes
    FROM proj.TBL_SUPPLIER_INVOICE_LINE l
    LEFT JOIN proj.TBL_GRN_HEADER       g     ON g.GrnId   = l.GrnId
    LEFT JOIN proj.TBL_SRV_HEADER       sh    ON sh.SrvId  = l.SrvId
    LEFT JOIN proj.TBL_PURCHASE_ORDER   po_g  ON po_g.PoId = g.PoId
    LEFT JOIN proj.TBL_PURCHASE_ORDER   po_s  ON po_s.PoId = sh.PoId
    WHERE l.SupplierInvoiceId = @SupplierInvoiceId AND l.IsActive = 1
    ORDER BY l.LineNum;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetSupplierInvoicePayables]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetSupplierInvoicePayables];
GO

CREATE PROCEDURE proj.sp_GetSupplierInvoicePayables
    @SupplierId   INT           = NULL,
    @InvoiceNo    NVARCHAR(100) = NULL,
    @CurrencyId   INT           = NULL,
    @Status       NVARCHAR(50)  = NULL,
    @DateFrom     DATE          = NULL,
    @DateTo       DATE          = NULL,
    @DueDateFrom  DATE          = NULL,
    @DueDateTo    DATE          = NULL,
    @PageNumber   INT           = 1,
    @PageSize     INT           = 50,
    @SortColumn   NVARCHAR(100) = N'InvoiceDate',
    @SortDirection NVARCHAR(4)  = N'DESC'
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH InvoiceCalc AS (
        SELECT
            si.SupplierInvoiceId,
            si.InvoiceNo,
            si.SupplierInvRef,
            si.InvoiceDate,
            si.DueDate,
            si.SupplierId,
            si.CurrencyId,
            cur.ShortName                                                    AS CurrencyShort,
            si.ExchangeRate,
            si.TotalAmount                                                   AS InvoiceAmount,
            si.TotalAmount * si.ExchangeRate                                 AS InvoiceAmountBase,
            -- AllocatedAmount now base; PV payments + DN credits, both Approved only.
            -- Convert to invoice currency for display.
            ROUND((COALESCE(pva.PaidAmount,0) + COALESCE(dna.DnAmount,0)) / NULLIF(si.ExchangeRate, 0), 2) AS PaidAmount,
            si.TotalAmount - ROUND((COALESCE(pva.PaidAmount,0) + COALESCE(dna.DnAmount,0)) / NULLIF(si.ExchangeRate, 0), 2) AS PendingAmount,
            si.TotalAmount * si.ExchangeRate - COALESCE(pva.PaidAmount,0) - COALESCE(dna.DnAmount,0)   AS PendingAmountBase,
            CASE
                WHEN COALESCE(pva.PaidAmount,0) + COALESCE(dna.DnAmount,0) = 0 THEN 'Unpaid'
                ELSE 'PartiallyPaid'
            END AS PaymentStatus,
            CASE
                WHEN si.DueDate IS NULL OR si.DueDate >= CAST(GETDATE() AS DATE) THEN 0
                ELSE DATEDIFF(DAY, si.DueDate, GETDATE())
            END AS DaysOverdue
        FROM proj.TBL_SUPPLIER_INVOICE si
        LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = si.CurrencyId
        LEFT JOIN (
            SELECT a.SupplierInvoiceId,
                   SUM(CASE WHEN ISNULL(a.IsActive, 1) = 1 THEN a.AllocatedAmount ELSE 0 END) AS PaidAmount
            FROM proj.TBL_PAYMENT_VOUCHER_ALLOCATION a
            INNER JOIN proj.TBL_PAYMENT_VOUCHER pv ON pv.PvId = a.PvId
            WHERE pv.Status = 'Approved' AND pv.IsActive = 1
            GROUP BY a.SupplierInvoiceId
        ) pva ON pva.SupplierInvoiceId = si.SupplierInvoiceId
        LEFT JOIN (
            SELECT a.SupplierInvoiceId,
                   SUM(CASE WHEN ISNULL(a.IsActive, 1) = 1 THEN a.AllocatedAmount ELSE 0 END) AS DnAmount
            FROM proj.TBL_DEBIT_NOTE_ALLOCATION a
            INNER JOIN proj.TBL_DEBIT_NOTE dn ON dn.DnId = a.DnId
            WHERE dn.Status = 'Approved' AND dn.IsActive = 1
            GROUP BY a.SupplierInvoiceId
        ) dna ON dna.SupplierInvoiceId = si.SupplierInvoiceId
        WHERE si.IsActive = 1
          AND si.Status NOT IN ('Draft', 'Cancelled')
          AND (@SupplierId  IS NULL OR si.SupplierId  = @SupplierId)
          AND (@CurrencyId  IS NULL OR si.CurrencyId  = @CurrencyId)
          AND (@InvoiceNo   IS NULL OR si.InvoiceNo LIKE N'%' + @InvoiceNo + N'%')
          AND (@DateFrom    IS NULL OR si.InvoiceDate >= @DateFrom)
          AND (@DateTo      IS NULL OR si.InvoiceDate <= @DateTo)
          AND (@DueDateFrom IS NULL OR si.DueDate    >= @DueDateFrom)
          AND (@DueDateTo   IS NULL OR si.DueDate    <= @DueDateTo)
          AND si.TotalAmount * si.ExchangeRate - COALESCE(pva.PaidAmount,0) - COALESCE(dna.DnAmount,0) > 0
    ),
    Filtered AS (
        SELECT *
        FROM InvoiceCalc
        WHERE (@Status IS NULL
               OR (@Status = 'Unpaid'        AND PaymentStatus = 'Unpaid')
               OR (@Status = 'PartiallyPaid' AND PaymentStatus = 'PartiallyPaid'))
    ),
    Ranked AS (
        SELECT *, COUNT(*) OVER () AS TotalRows,
               ROW_NUMBER() OVER (
                   ORDER BY
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='InvoiceDate'       THEN InvoiceDate       END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='InvoiceDate'       THEN InvoiceDate       END DESC,
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='DueDate'           THEN DueDate           END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='DueDate'           THEN DueDate           END DESC,
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='InvoiceNo'         THEN InvoiceNo         END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='InvoiceNo'         THEN InvoiceNo         END DESC,
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='CurrencyShort'     THEN CurrencyShort     END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='CurrencyShort'     THEN CurrencyShort     END DESC,
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='PaymentStatus'     THEN PaymentStatus     END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='PaymentStatus'     THEN PaymentStatus     END DESC,
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='PendingAmount'     THEN PendingAmount     END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='PendingAmount'     THEN PendingAmount     END DESC,
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='PendingAmountBase' THEN PendingAmountBase END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='PendingAmountBase' THEN PendingAmountBase END DESC,
                       InvoiceDate DESC
               ) AS RowNum
        FROM Filtered
    )
    SELECT
        SupplierInvoiceId, InvoiceNo, SupplierInvRef,
        InvoiceDate, DueDate,
        CurrencyShort, ExchangeRate,
        InvoiceAmount, InvoiceAmountBase,
        PaidAmount, PendingAmount, PendingAmountBase,
        PaymentStatus, DaysOverdue,
        TotalRows
    FROM Ranked
    WHERE RowNum BETWEEN (@PageNumber - 1) * @PageSize + 1
                     AND  @PageNumber      * @PageSize
    ORDER BY RowNum;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetSupplierInvoicePos]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetSupplierInvoicePos];
GO
CREATE   PROCEDURE proj.sp_GetSupplierInvoicePos
    @SupplierInvoiceId INT
AS
BEGIN
    SET NOCOUNT ON;

    -- Only return POs that are actually represented on this SI's lines (via
    -- PoLineId). Service POs surface here too when their lines were imported
    -- through "Import from SRV" — that wires sil.SrvLineId → SRV → PoLineId
    -- under the hood, so the SI line has a real PoLineId and joins cleanly.
    -- A service PO with a confirmed SRV but no SI line entry is intentionally
    -- NOT shown here — pay for it by importing the SRV onto the SI first.
    SELECT DISTINCT
        po.PoId, po.PoNumber, po.JobId,
        N'SI Line' AS Source,
        (SELECT SUM(ISNULL(sil.LineTotal, 0))
         FROM   proj.TBL_SUPPLIER_INVOICE_LINE sil
         JOIN   proj.TBL_PURCHASE_ORDER_LINE   pol2 ON pol2.PoLineId = sil.PoLineId
         WHERE  sil.SupplierInvoiceId = @SupplierInvoiceId AND sil.IsActive = 1
           AND  pol2.PoId = po.PoId) AS LinesValueForThisPo,
        (SELECT SUM(ISNULL(sil2.LineTotal, 0))
         FROM   proj.TBL_SUPPLIER_INVOICE_LINE sil2
         WHERE  sil2.SupplierInvoiceId = @SupplierInvoiceId AND sil2.IsActive = 1) AS InvoiceTotalLines
    FROM   proj.TBL_SUPPLIER_INVOICE_LINE sil
    JOIN   proj.TBL_PURCHASE_ORDER_LINE   pol ON pol.PoLineId = sil.PoLineId
    JOIN   proj.TBL_PURCHASE_ORDER         po  ON po.PoId      = pol.PoId
    WHERE  sil.SupplierInvoiceId = @SupplierInvoiceId AND sil.IsActive = 1
    ORDER BY po.PoNumber;
END;
GO

