IF OBJECT_ID(N'[proj].[sp_GetSupplierOpenInvoices]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetSupplierOpenInvoices];
GO

CREATE PROCEDURE proj.sp_GetSupplierOpenInvoices
    @SupplierId INT,
    @PvId       INT = 0
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH inv AS (
        SELECT
            si.SupplierInvoiceId,
            si.InvoiceNo,
            si.InvoiceDate,
            si.DueDate,
            si.SupplierInvRef,
            si.CurrencyId,
            cur.ShortName                                                         AS CurrencyShort,
            si.ExchangeRate                                                       AS InvoiceExchangeRate,
            si.TotalAmount,
            ROUND(ISNULL(paid.PaidAmount,   0) / NULLIF(si.ExchangeRate, 0), 2) AS PaidAmount,
            ROUND(ISNULL(thisPv.ThisPvAllocated, 0) / NULLIF(si.ExchangeRate, 0), 2) AS ThisPvAllocated,
            ISNULL(paid.PaidAmount,   0)                                          AS PaidBase,
            ISNULL(thisPv.ThisPvAllocated, 0)                                     AS ThisPvAllocatedBase,
            si.ExchangeRate
        FROM proj.TBL_SUPPLIER_INVOICE si
        LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = si.CurrencyId
        OUTER APPLY (
            SELECT ISNULL(pv_paid.Amt, 0) + ISNULL(dn_paid.Amt, 0) AS PaidAmount
            FROM (VALUES(1)) x(d)
            OUTER APPLY (
                SELECT ISNULL(SUM(a.AllocatedAmount), 0) AS Amt
                FROM   proj.TBL_PAYMENT_VOUCHER_ALLOCATION a
                JOIN   proj.TBL_PAYMENT_VOUCHER pv ON pv.PvId = a.PvId
                WHERE  a.SupplierInvoiceId = si.SupplierInvoiceId
                  AND  a.IsActive = 1 AND pv.Status = 'Approved'
                  AND  pv.IsActive = 1 AND pv.PvId <> ISNULL(@PvId, 0)
            ) pv_paid
            OUTER APPLY (
                SELECT ISNULL(SUM(a.AllocatedAmount), 0) AS Amt
                FROM   proj.TBL_DEBIT_NOTE_ALLOCATION a
                JOIN   proj.TBL_DEBIT_NOTE dn ON dn.DnId = a.DnId
                WHERE  a.SupplierInvoiceId = si.SupplierInvoiceId
                  AND  a.IsActive = 1 AND dn.Status = 'Approved' AND dn.IsActive = 1
            ) dn_paid
        ) paid
        OUTER APPLY (
            SELECT ISNULL(SUM(a2.AllocatedAmount), 0) AS ThisPvAllocated
            FROM   proj.TBL_PAYMENT_VOUCHER_ALLOCATION a2
            WHERE  a2.SupplierInvoiceId = si.SupplierInvoiceId
              AND  a2.PvId = @PvId AND a2.IsActive = 1
        ) thisPv
        WHERE si.SupplierId = @SupplierId AND si.IsActive = 1 AND si.Status = 'Approved'
    )
    SELECT
        i.SupplierInvoiceId, i.InvoiceNo, i.InvoiceDate, i.DueDate, i.SupplierInvRef,
        i.CurrencyId, i.CurrencyShort, i.InvoiceExchangeRate,
        i.TotalAmount, i.PaidAmount,
        (i.TotalAmount - i.PaidAmount) AS Outstanding,
        i.ThisPvAllocated,
        ISNULL(STUFF((SELECT DISTINCT ', ' + po.PoNumber
            FROM proj.TBL_SUPPLIER_INVOICE_LINE sil
            JOIN proj.TBL_PURCHASE_ORDER_LINE pol ON pol.PoLineId = sil.PoLineId
            JOIN proj.TBL_PURCHASE_ORDER po ON po.PoId = pol.PoId
            WHERE sil.SupplierInvoiceId = i.SupplierInvoiceId AND sil.IsActive = 1
            FOR XML PATH(''), TYPE).value('.','NVARCHAR(MAX)'), 1, 2, ''), '') AS PoNumbers,
        ISNULL(STUFF((SELECT DISTINCT ', ' + CAST(po2.JobId AS NVARCHAR(50))
            FROM proj.TBL_SUPPLIER_INVOICE_LINE sil2
            JOIN proj.TBL_PURCHASE_ORDER_LINE pol2 ON pol2.PoLineId = sil2.PoLineId
            JOIN proj.TBL_PURCHASE_ORDER po2 ON po2.PoId = pol2.PoId
            WHERE sil2.SupplierInvoiceId = i.SupplierInvoiceId AND sil2.IsActive = 1
              AND po2.JobId IS NOT NULL
            FOR XML PATH(''), TYPE).value('.','NVARCHAR(MAX)'), 1, 2, ''), '') AS JobIds
    FROM inv i
    WHERE (i.TotalAmount * i.ExchangeRate - i.PaidBase) > 0.005 OR i.ThisPvAllocatedBase > 0
    ORDER BY i.InvoiceDate, i.SupplierInvoiceId;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetSupplierOpenInvoicesForDN]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetSupplierOpenInvoicesForDN];
GO

CREATE PROCEDURE proj.sp_GetSupplierOpenInvoicesForDN
    @SupplierId INT,
    @DnId       INT = 0
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH inv AS (
        SELECT
            si.SupplierInvoiceId,
            si.InvoiceNo,
            si.InvoiceDate,
            si.DueDate,
            si.SupplierInvRef,
            si.CurrencyId,
            cur.ShortName                                                                           AS CurrencyShort,
            si.TotalAmount,
            ROUND(ISNULL(paid.PaidByOthers, 0) / NULLIF(si.ExchangeRate, 0), 2)                   AS PaidAmount,
            ROUND(ISNULL(thisDn.ThisDnAllocated, 0) / NULLIF(si.ExchangeRate, 0), 2)              AS ThisDnAllocated,
            ISNULL(paid.PaidByOthers, 0)                                                            AS PaidBase,
            ISNULL(thisDn.ThisDnAllocated, 0)                                                       AS ThisDnAllocatedBase,
            si.ExchangeRate
        FROM proj.TBL_SUPPLIER_INVOICE si
        LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = si.CurrencyId
        OUTER APPLY (
            SELECT ISNULL(pv_paid.Amt,0) + ISNULL(dn_paid.Amt,0) AS PaidByOthers
            FROM (VALUES(1)) x(d)
            OUTER APPLY (
                SELECT ISNULL(SUM(a.AllocatedAmount), 0) AS Amt
                FROM   proj.TBL_PAYMENT_VOUCHER_ALLOCATION a
                JOIN   proj.TBL_PAYMENT_VOUCHER pv ON pv.PvId = a.PvId
                WHERE  a.SupplierInvoiceId = si.SupplierInvoiceId AND a.IsActive = 1
                  AND  pv.Status = 'Approved' AND pv.IsActive = 1
            ) pv_paid
            OUTER APPLY (
                SELECT ISNULL(SUM(a.AllocatedAmount), 0) AS Amt
                FROM   proj.TBL_DEBIT_NOTE_ALLOCATION a
                JOIN   proj.TBL_DEBIT_NOTE dn ON dn.DnId = a.DnId
                WHERE  a.SupplierInvoiceId = si.SupplierInvoiceId AND a.IsActive = 1
                  AND  dn.IsActive = 1 AND dn.Status = 'Approved' AND dn.DnId <> @DnId
            ) dn_paid
        ) paid
        OUTER APPLY (
            SELECT ISNULL(SUM(a.AllocatedAmount), 0) AS ThisDnAllocated
            FROM   proj.TBL_DEBIT_NOTE_ALLOCATION a
            WHERE  a.SupplierInvoiceId = si.SupplierInvoiceId AND a.IsActive = 1 AND a.DnId = @DnId
        ) thisDn
        WHERE si.SupplierId = @SupplierId AND si.IsActive = 1 AND si.Status = 'Approved'
    )
    SELECT
        i.SupplierInvoiceId,
        i.InvoiceNo,
        i.InvoiceDate,
        i.DueDate,
        i.SupplierInvRef,
        i.CurrencyId,
        i.CurrencyShort,
        i.TotalAmount,
        i.PaidAmount,
        (i.TotalAmount - i.PaidAmount) AS Outstanding,
        i.ThisDnAllocated,
        ISNULL(
            STUFF((
                SELECT DISTINCT ', ' + po.PoNumber
                FROM   proj.TBL_SUPPLIER_INVOICE_LINE sil
                JOIN   proj.TBL_PURCHASE_ORDER_LINE   pol ON pol.PoLineId = sil.PoLineId
                JOIN   proj.TBL_PURCHASE_ORDER         po  ON po.PoId     = pol.PoId
                WHERE  sil.SupplierInvoiceId = i.SupplierInvoiceId AND sil.IsActive = 1
                FOR XML PATH(''), TYPE
            ).value('.','NVARCHAR(MAX)'), 1, 2, '')
        , '') AS PoNumbers,
        ISNULL(
            STUFF((
                SELECT DISTINCT ', ' + CAST(po2.JobId AS NVARCHAR(50))
                FROM   proj.TBL_SUPPLIER_INVOICE_LINE sil2
                JOIN   proj.TBL_PURCHASE_ORDER_LINE   pol2 ON pol2.PoLineId = sil2.PoLineId
                JOIN   proj.TBL_PURCHASE_ORDER         po2  ON po2.PoId     = pol2.PoId
                WHERE  sil2.SupplierInvoiceId = i.SupplierInvoiceId AND sil2.IsActive = 1
                  AND  po2.JobId IS NOT NULL
                FOR XML PATH(''), TYPE
            ).value('.','NVARCHAR(MAX)'), 1, 2, '')
        , '') AS JobIds
    FROM inv i
    WHERE (i.TotalAmount * i.ExchangeRate - i.PaidBase) > 0.005 OR i.ThisDnAllocatedBase > 0
    ORDER BY i.InvoiceDate, i.SupplierInvoiceId;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetSupplierPayables]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetSupplierPayables];
GO

CREATE PROCEDURE proj.sp_GetSupplierPayables
    @SearchText   NVARCHAR(200) = NULL,
    @SupplierId   INT           = NULL,
    @CurrencyId   INT           = NULL,
    @Status       NVARCHAR(50)  = NULL,
    @DateFrom     DATE          = NULL,
    @DateTo       DATE          = NULL,
    @PageNumber   INT           = 1,
    @PageSize     INT           = 20,
    @SortColumn   NVARCHAR(100) = N'TotalPendingBase',
    @SortDirection NVARCHAR(4)  = N'DESC'
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH InvoiceCalc AS (
        SELECT
            si.SupplierInvoiceId,
            si.SupplierId,
            si.CurrencyId,
            cur.ShortName                                                  AS CurrencyShort,
            si.TotalAmount,
            si.TotalAmount * si.ExchangeRate                               AS TotalAmountBase,
            COALESCE(pva.PaidAmount,0) + COALESCE(dna.DnAmount,0)          AS PaidAmountBase,
            ROUND((COALESCE(pva.PaidAmount,0) + COALESCE(dna.DnAmount,0)) / NULLIF(si.ExchangeRate, 0), 2) AS PaidAmount,
            si.TotalAmount - ROUND((COALESCE(pva.PaidAmount,0) + COALESCE(dna.DnAmount,0)) / NULLIF(si.ExchangeRate, 0), 2) AS PendingAmount,
            si.TotalAmount * si.ExchangeRate - COALESCE(pva.PaidAmount,0) - COALESCE(dna.DnAmount,0) AS PendingAmountBase,
            CASE
                WHEN COALESCE(pva.PaidAmount,0) + COALESCE(dna.DnAmount,0) = 0 THEN 'Unpaid'
                ELSE 'PartiallyPaid'
            END AS PaymentStatus,
            CASE
                WHEN si.DueDate < CAST(GETDATE() AS DATE) AND si.DueDate IS NOT NULL
                THEN si.TotalAmount * si.ExchangeRate - COALESCE(pva.PaidAmount,0) - COALESCE(dna.DnAmount,0)
                ELSE 0
            END AS OverdueAmountBase
        FROM proj.TBL_SUPPLIER_INVOICE si
        LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = si.CurrencyId
        LEFT JOIN (
            SELECT a.SupplierInvoiceId,
                   SUM(CASE WHEN ISNULL(a.IsActive, 1) = 1 THEN a.AllocatedAmount ELSE 0 END) AS PaidAmount
            FROM proj.TBL_PAYMENT_VOUCHER_ALLOCATION a
            INNER JOIN proj.TBL_PAYMENT_VOUCHER pv ON pv.PvId = a.PvId
            WHERE pv.Status = 'Approved' AND pv.IsActive = 1
            GROUP BY a.SupplierInvoiceId
        ) pva ON pva.SupplierInvoiceId = si.SupplierInvoiceId
        LEFT JOIN (
            SELECT a.SupplierInvoiceId,
                   SUM(CASE WHEN ISNULL(a.IsActive, 1) = 1 THEN a.AllocatedAmount ELSE 0 END) AS DnAmount
            FROM proj.TBL_DEBIT_NOTE_ALLOCATION a
            INNER JOIN proj.TBL_DEBIT_NOTE dn ON dn.DnId = a.DnId
            WHERE dn.Status = 'Approved' AND dn.IsActive = 1
            GROUP BY a.SupplierInvoiceId
        ) dna ON dna.SupplierInvoiceId = si.SupplierInvoiceId
        WHERE si.IsActive = 1
          AND si.Status NOT IN ('Draft', 'Cancelled')
          AND (@DateFrom   IS NULL OR si.InvoiceDate >= @DateFrom)
          AND (@DateTo     IS NULL OR si.InvoiceDate <= @DateTo)
          AND (@CurrencyId IS NULL OR si.CurrencyId  =  @CurrencyId)
          AND si.TotalAmount * si.ExchangeRate - COALESCE(pva.PaidAmount,0) - COALESCE(dna.DnAmount,0) > 0
    ),
    SupplierSummary AS (
        SELECT
            s.SupplierId,
            s.SupplierName,
            s.SupplierCode,
            COUNT(*)                                              AS TotalInvoiceCount,
            SUM(CASE WHEN ic.PaymentStatus = 'Unpaid'        THEN 1 ELSE 0 END) AS UnpaidCount,
            SUM(CASE WHEN ic.PaymentStatus = 'PartiallyPaid' THEN 1 ELSE 0 END) AS PartiallyPaidCount,
            SUM(ic.TotalAmount)                                   AS TotalInvoiceAmount,
            SUM(ic.PaidAmount)                                    AS TotalPaidAmount,
            SUM(ic.TotalAmountBase)                               AS TotalInvoiceAmountBase,
            SUM(ic.PaidAmountBase)                                AS TotalPaidAmountBase,
            SUM(ic.PendingAmountBase)                             AS TotalPendingBase,
            SUM(ic.OverdueAmountBase)                             AS OverdueAmountBase,
            CASE WHEN COUNT(DISTINCT ic.CurrencyId) = 1
                 THEN MAX(ic.CurrencyShort) ELSE 'Multi' END      AS InvoiceCurrencyShort
        FROM InvoiceCalc ic
        JOIN proj.TBL_SUPPLIER s ON s.SupplierId = ic.SupplierId
        WHERE (@SupplierId  IS NULL OR s.SupplierId   = @SupplierId)
          AND (@SearchText  IS NULL OR s.SupplierName LIKE N'%' + @SearchText + N'%'
                                    OR s.SupplierCode LIKE N'%' + @SearchText + N'%')
          AND (@Status      IS NULL OR ic.PaymentStatus = @Status)
        GROUP BY s.SupplierId, s.SupplierName, s.SupplierCode
    ),
    Ranked AS (
        SELECT *, COUNT(*) OVER () AS TotalRows,
               ROW_NUMBER() OVER (
                   ORDER BY
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='SupplierName'           THEN SupplierName           END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='SupplierName'           THEN SupplierName           END DESC,
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='InvoiceCurrencyShort'   THEN InvoiceCurrencyShort   END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='InvoiceCurrencyShort'   THEN InvoiceCurrencyShort   END DESC,
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='TotalInvoiceCount'      THEN TotalInvoiceCount      END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='TotalInvoiceCount'      THEN TotalInvoiceCount      END DESC,
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='TotalInvoiceAmountBase' THEN TotalInvoiceAmountBase END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='TotalInvoiceAmountBase' THEN TotalInvoiceAmountBase END DESC,
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='TotalPaidAmountBase'    THEN TotalPaidAmountBase    END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='TotalPaidAmountBase'    THEN TotalPaidAmountBase    END DESC,
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='TotalPendingBase'       THEN TotalPendingBase       END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='TotalPendingBase'       THEN TotalPendingBase       END DESC,
                       CASE WHEN @SortDirection='ASC'  AND @SortColumn='OverdueAmountBase'      THEN OverdueAmountBase      END ASC,
                       CASE WHEN @SortDirection='DESC' AND @SortColumn='OverdueAmountBase'      THEN OverdueAmountBase      END DESC,
                       TotalPendingBase DESC
               ) AS RowNum
        FROM SupplierSummary
    )
    SELECT
        SupplierId, SupplierName, SupplierCode,
        TotalInvoiceCount, UnpaidCount, PartiallyPaidCount,
        TotalInvoiceAmount, TotalPaidAmount, InvoiceCurrencyShort,
        TotalInvoiceAmountBase, TotalPaidAmountBase,
        TotalPendingBase, OverdueAmountBase,
        TotalRows
    FROM Ranked
    WHERE RowNum BETWEEN (@PageNumber - 1) * @PageSize + 1
                     AND  @PageNumber      * @PageSize
    ORDER BY RowNum;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetSupplierPaymentHistory]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetSupplierPaymentHistory];
GO

CREATE PROCEDURE proj.sp_GetSupplierPaymentHistory
    @SupplierId INT
AS
BEGIN
    SET NOCOUNT ON;

    -- RS1: Summary — PV payments + DN credits, both Approved+Active, already base
    SELECT
        ISNULL(SUM(si.TotalAmount * si.ExchangeRate), 0)                   AS InvoicesRaised,
        ISNULL(SUM(COALESCE(pva.PaidAmount,0) + COALESCE(dna.DnAmount,0)), 0) AS PaymentsMade,
        ISNULL(SUM(si.TotalAmount * si.ExchangeRate
                   - COALESCE(pva.PaidAmount,0) - COALESCE(dna.DnAmount,0)), 0) AS OutstandingBalance,
        ISNULL(SUM(
            CASE WHEN si.DueDate < CAST(GETDATE() AS DATE) AND si.DueDate IS NOT NULL
                 THEN si.TotalAmount * si.ExchangeRate - COALESCE(pva.PaidAmount,0) - COALESCE(dna.DnAmount,0)
                 ELSE 0 END), 0)                                            AS OverdueAmount
    FROM proj.TBL_SUPPLIER_INVOICE si
    LEFT JOIN (
        SELECT a.SupplierInvoiceId,
               SUM(CASE WHEN ISNULL(a.IsActive, 1) = 1 THEN a.AllocatedAmount ELSE 0 END) AS PaidAmount
        FROM proj.TBL_PAYMENT_VOUCHER_ALLOCATION a
        INNER JOIN proj.TBL_PAYMENT_VOUCHER pv ON pv.PvId = a.PvId
        WHERE pv.Status = 'Approved' AND pv.IsActive = 1
        GROUP BY a.SupplierInvoiceId
    ) pva ON pva.SupplierInvoiceId = si.SupplierInvoiceId
    LEFT JOIN (
        SELECT a.SupplierInvoiceId,
               SUM(CASE WHEN ISNULL(a.IsActive, 1) = 1 THEN a.AllocatedAmount ELSE 0 END) AS DnAmount
        FROM proj.TBL_DEBIT_NOTE_ALLOCATION a
        INNER JOIN proj.TBL_DEBIT_NOTE dn ON dn.DnId = a.DnId
        WHERE dn.Status = 'Approved' AND dn.IsActive = 1
        GROUP BY a.SupplierInvoiceId
    ) dna ON dna.SupplierInvoiceId = si.SupplierInvoiceId
    WHERE si.IsActive = 1
      AND si.Status NOT IN ('Draft', 'Cancelled')
      AND si.SupplierId = @SupplierId;

    -- RS2: Payment voucher history (header amounts are in PV currency — unchanged)
    SELECT
        pv.PvNumber,
        pv.PvDate,
        cur.ShortName                                AS CurrencyShort,
        pv.ExchangeRate,
        pv.AmountPaid,
        pv.AmountPaid * pv.ExchangeRate              AS AmountBase,
        ISNULL(pv.AllocatedAmount, 0)                AS AllocatedAmount,
        ISNULL(pv.AllocatedAmount, 0) * pv.ExchangeRate AS AllocatedBase,
        pv.Status,
        pv.PaymentMode,
        pv.CreatedBy,
        pv.CreatedDate
    FROM proj.TBL_PAYMENT_VOUCHER pv
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = pv.CurrencyId
    WHERE pv.IsActive = 1
      AND pv.SupplierId = @SupplierId
    ORDER BY pv.PvDate DESC, pv.PvId DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_GetTransferableJobStock]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetTransferableJobStock];
GO
CREATE PROCEDURE proj.sp_GetTransferableJobStock
    @JobId NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        i.ItemId,
        i.ItemCode,
        i.ItemName,
        i.BaseUomId                              AS UomId,
        u.UomName,
        u.UomCode,
        ISNULL(SUM(sl.QtyIn - sl.QtyOut), 0)   AS AvailableQty,
        ISNULL(sb.AvgUnitCost, 0)               AS AvgUnitCost
    FROM proj.TBL_STOCK_LEDGER sl
    JOIN  proj.TBL_ITEM        i  ON i.ItemId  = sl.ItemId
    LEFT JOIN proj.TBL_ITEM_UOM u  ON u.UomId   = i.BaseUomId
    LEFT JOIN proj.TBL_STOCK_BALANCE sb ON sb.ItemId = sl.ItemId
    WHERE sl.JobId = @JobId
    GROUP BY i.ItemId, i.ItemCode, i.ItemName, i.BaseUomId, u.UomName, u.UomCode, sb.AvgUnitCost
    HAVING ISNULL(SUM(sl.QtyIn - sl.QtyOut), 0) > 0
    ORDER BY i.ItemCode, i.ItemName;
END;
GO

IF OBJECT_ID(N'[proj].[sp_GetUserBudgetPasswordForVerify]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetUserBudgetPasswordForVerify];
GO
CREATE   PROCEDURE proj.sp_GetUserBudgetPasswordForVerify
    @UserName NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT u.UserId,
           CAST(CASE WHEN us.UserSecretId IS NULL THEN 0 ELSE 1 END AS BIT) AS HasPassword,
           us.SecretValueHash AS ExistingHash
    FROM proj.TBL_USERS u
    LEFT JOIN proj.TBL_USER_SECRET us
           ON us.UserId = u.UserId AND us.SecretKey = 'BUDGET_PASSWORD'
    WHERE u.UserName = @UserName;
END
GO

