IF OBJECT_ID(N'[proj].[sp_GetUserMenus]') IS NOT NULL DROP PROCEDURE [proj].[sp_GetUserMenus];
GO

CREATE   PROCEDURE proj.sp_GetUserMenus
    @UserId INT
AS
BEGIN
    SET NOCOUNT ON;

    -- 1. Collect the user's active roles
    CREATE TABLE #UserRoles (RoleId INT PRIMARY KEY);
    INSERT INTO #UserRoles
        SELECT RoleId FROM proj.TBL_USER_ROLES WHERE UserId = @UserId;

    -- 2. Whitelist: menus explicitly granted CanView = 1 for ANY of the user's roles
    CREATE TABLE #Allowed (MenuId INT PRIMARY KEY);
    INSERT INTO #Allowed
        SELECT DISTINCT rm.MenuId
        FROM proj.TBL_ROLE_MENU rm
        JOIN #UserRoles ur ON ur.RoleId = rm.RoleId
        WHERE rm.CanView = 1;

    -- 3. Blocked: menus where ALL roles say CanView = 0 (no role overrides)
    CREATE TABLE #Blocked (MenuId INT PRIMARY KEY);
    INSERT INTO #Blocked
        SELECT rm.MenuId
        FROM proj.TBL_ROLE_MENU rm
        JOIN #UserRoles ur ON ur.RoleId = rm.RoleId
        GROUP BY rm.MenuId
        HAVING MAX(CAST(rm.CanView AS INT)) = 0;

    -- 4. Top-level section groups (gate menus: non-navigable, no parent).
    --    A section must be in #Allowed for its children to appear.
    --    NO ROW for a section = treated as not allowed (deny-by-default).
    CREATE TABLE #TopLevelGroups (MenuId INT PRIMARY KEY);
    INSERT INTO #TopLevelGroups
        SELECT MenuId FROM proj.TBL_MENU
        WHERE ParentMenuId IS NULL AND MenuUrl IS NULL AND IsActive = 1;

    -- 5. Visible leaf pages
    --      A) Top-level leaf (Dashboard, My Approvals) — just needs to be in #Allowed
    --      B) 1-level deep (parent is a section group) — section must be in #Allowed
    --      C) 2-levels deep (parent is mid-level group, grandparent is section)
    --         — grandparent section must be in #Allowed; mid-level must not be blocked
    ;WITH FilteredLeaves AS (
        SELECT m.MenuId
        FROM proj.TBL_MENU m
        WHERE m.IsActive  = 1
          AND m.MenuUrl  IS NOT NULL
          AND m.MenuId   IN (SELECT MenuId FROM #Allowed)
          AND m.MenuId  NOT IN (SELECT MenuId FROM #Blocked)
          AND (
              m.ParentMenuId IS NULL                          -- A: top-level leaf
              OR (  m.ParentMenuId IN (SELECT MenuId FROM #TopLevelGroups)
                AND m.ParentMenuId IN (SELECT MenuId FROM #Allowed) )  -- B: 1-level deep
              OR EXISTS (                                      -- C: 2-levels deep
                  SELECT 1 FROM proj.TBL_MENU parent
                  WHERE  parent.MenuId        = m.ParentMenuId
                    AND  parent.ParentMenuId IS NOT NULL
                    AND  parent.MenuId       NOT IN (SELECT MenuId FROM #Blocked)
                    AND  parent.ParentMenuId  IN (SELECT MenuId FROM #Allowed)
              )
          )
    ),
    WithParents AS (
        SELECT MenuId FROM FilteredLeaves
        UNION
        SELECT DISTINCT m.ParentMenuId
        FROM   proj.TBL_MENU m
        JOIN   FilteredLeaves fl ON fl.MenuId = m.MenuId
        WHERE  m.ParentMenuId IS NOT NULL
        UNION
        SELECT DISTINCT p.ParentMenuId
        FROM   proj.TBL_MENU m
        JOIN   FilteredLeaves fl ON fl.MenuId = m.MenuId
        JOIN   proj.TBL_MENU  p  ON p.MenuId  = m.ParentMenuId
        WHERE  p.ParentMenuId IS NOT NULL
    )
    -- Result set 1: sidebar menu items
    SELECT m.MenuId, m.ParentMenuId, m.MenuName, m.MenuUrl, m.MenuIcon, m.MenuOrder
    FROM   proj.TBL_MENU m
    JOIN   WithParents wp ON wp.MenuId = m.MenuId
    WHERE  m.IsActive = 1
    ORDER  BY m.ParentMenuId, m.MenuOrder;

    -- Result set 2: permitted action keys for visible pages
    ;WITH FilteredLeaves AS (
        SELECT m.MenuId
        FROM proj.TBL_MENU m
        WHERE m.IsActive  = 1
          AND m.MenuUrl  IS NOT NULL
          AND m.MenuId   IN (SELECT MenuId FROM #Allowed)
          AND m.MenuId  NOT IN (SELECT MenuId FROM #Blocked)
          AND (
              m.ParentMenuId IS NULL
              OR (  m.ParentMenuId IN (SELECT MenuId FROM #TopLevelGroups)
                AND m.ParentMenuId IN (SELECT MenuId FROM #Allowed) )
              OR EXISTS (
                  SELECT 1 FROM proj.TBL_MENU parent
                  WHERE  parent.MenuId        = m.ParentMenuId
                    AND  parent.ParentMenuId IS NOT NULL
                    AND  parent.MenuId       NOT IN (SELECT MenuId FROM #Blocked)
                    AND  parent.ParentMenuId  IN (SELECT MenuId FROM #Allowed)
              )
          )
    )
    SELECT DISTINCT
        ma.ActionId,
        rma.MenuId,
        ma.ActionName,
        ma.ActionCode,
        rma.IsAllowed
    FROM   proj.TBL_ROLE_MENU_ACTION rma
    JOIN   #UserRoles ur ON ur.RoleId = rma.RoleId
    JOIN   FilteredLeaves fl ON fl.MenuId = rma.MenuId
    JOIN   proj.TBL_MENU_ACTIONS ma ON ma.ActionId = rma.ActionId AND ma.MenuId = rma.MenuId
    WHERE  rma.IsAllowed = 1 AND ma.IsActive = 1;

    DROP TABLE #UserRoles;
    DROP TABLE #Allowed;
    DROP TABLE #Blocked;
    DROP TABLE #TopLevelGroups;
END;
GO

