IF OBJECT_ID(N'[proj].[sp_HoldPO]') IS NOT NULL DROP PROCEDURE [proj].[sp_HoldPO];
GO

CREATE PROCEDURE proj.sp_HoldPO
    @PoId      INT,
    @Reason    NVARCHAR(500),
    @HeldBy    NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    IF LTRIM(RTRIM(ISNULL(@Reason, ''))) = ''
        RAISERROR('A reason is required to place a PO on hold.', 16, 1);

    DECLARE @CurrentStatus NVARCHAR(30);
    SELECT @CurrentStatus = Status
    FROM proj.TBL_PURCHASE_ORDER
    WHERE PoId = @PoId AND IsActive = 1;

    IF @CurrentStatus IS NULL
        RAISERROR('Purchase Order not found or is inactive.', 16, 1);

    IF @CurrentStatus = 'Hold'
        RAISERROR('This Purchase Order is already on hold.', 16, 1);

    IF @CurrentStatus NOT IN ('Approved', 'Partial', 'Sent')
    BEGIN
        DECLARE @Msg NVARCHAR(200) = 'Only Approved, Partial, or Sent POs can be placed on hold. Current status: ' + @CurrentStatus + '.';
        RAISERROR(@Msg, 16, 1);
    END

    UPDATE proj.TBL_PURCHASE_ORDER
    SET Status           = 'Hold',
        StatusBeforeHold = @CurrentStatus,
        HoldBy           = @HeldBy,
        HoldDate         = GETDATE(),
        HoldReason       = @Reason,
        ModifiedBy       = @HeldBy,
        ModifiedDate     = GETDATE()
    WHERE PoId = @PoId AND IsActive = 1;

    -- Log the hold event
    INSERT INTO proj.TBL_PO_HOLD_LOG (PoId, Action, Reason, PreviousStatus, ActionBy, ActionDate)
    VALUES (@PoId, 'Hold', @Reason, @CurrentStatus, @HeldBy, GETDATE());

    SELECT @PoId AS PoId;
END
GO

IF OBJECT_ID(N'[proj].[sp_ImportAdjustmentLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_ImportAdjustmentLine];
GO

CREATE PROCEDURE proj.sp_ImportAdjustmentLine
    @AdjustmentId INT,
    @ItemCode     NVARCHAR(50),
    @AdjustQty    DECIMAL(18,4),
    @UnitCost     DECIMAL(18,4) = 0,
    @UomCode      NVARCHAR(20)  = NULL,
    @Reason       NVARCHAR(50)  = NULL,
    @Notes        NVARCHAR(300) = NULL,
    @CreatedBy    NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM proj.TBL_STOCK_ADJUSTMENT WHERE AdjustmentId = @AdjustmentId AND Status IN ('Draft','Rejected'))
    BEGIN RAISERROR('Lines can only be imported into a Draft or Rejected adjustment.', 16, 1); RETURN; END

    IF NULLIF(LTRIM(RTRIM(@ItemCode)), '') IS NULL
    BEGIN RAISERROR('Item code is required.', 16, 1); RETURN; END
    IF @AdjustQty IS NULL OR @AdjustQty <= 0
    BEGIN RAISERROR('Quantity must be greater than zero.', 16, 1); RETURN; END
    IF ISNULL(@UnitCost, 0) < 0
    BEGIN RAISERROR('Unit cost cannot be negative.', 16, 1); RETURN; END

    DECLARE @ItemId INT, @ItemDesc NVARCHAR(300), @BaseUomId INT;
    SELECT @ItemId = ItemId, @ItemDesc = ItemName, @BaseUomId = BaseUomId
    FROM proj.TBL_ITEM WHERE ItemCode = @ItemCode AND IsActive = 1;

    IF @ItemId IS NULL
    BEGIN
        DECLARE @mNF NVARCHAR(200) = 'Item code not found or inactive: ' + @ItemCode;
        RAISERROR(@mNF, 16, 1); RETURN;
    END

    DECLARE @UomId INT = NULL;
    IF NULLIF(LTRIM(RTRIM(@UomCode)), '') IS NOT NULL
    BEGIN
        SELECT @UomId = UomId FROM proj.TBL_ITEM_UOM WHERE UomCode = @UomCode AND IsActive = 1;
        IF @UomId IS NULL
        BEGIN
            DECLARE @mU NVARCHAR(200) = 'UOM code not found: ' + @UomCode;
            RAISERROR(@mU, 16, 1); RETURN;
        END

        IF @BaseUomId IS NOT NULL AND @UomId <> @BaseUomId
           AND NOT EXISTS (
               SELECT 1 FROM proj.TBL_ITEM_UOM_CONVERSION
               WHERE ItemId = @ItemId AND FromUomId = @UomId AND ToUomId = @BaseUomId AND IsActive = 1
           )
        BEGIN
            DECLARE @mC NVARCHAR(300) =
                'No UOM conversion for ' + @ItemCode + ' (' + @UomCode + ' to ' +
                ISNULL((SELECT UomCode FROM proj.TBL_ITEM_UOM WHERE UomId = @BaseUomId), '?') +
                '). Use the base UOM or configure the conversion in Item master.';
            RAISERROR(@mC, 16, 1); RETURN;
        END
    END
    ELSE
        SET @UomId = @BaseUomId;

    DECLARE @LineNum INT;
    SELECT @LineNum = ISNULL(MAX(LineNum), 0) + 1
    FROM proj.TBL_STOCK_ADJUSTMENT_LINE WHERE AdjustmentId = @AdjustmentId AND IsActive = 1;

    INSERT INTO proj.TBL_STOCK_ADJUSTMENT_LINE
        (AdjustmentId, LineNum, ItemId, ItemDesc, AdjustQty, UomId, UnitCost, Reason, Notes, CreatedBy)
    VALUES (@AdjustmentId, @LineNum, @ItemId, @ItemDesc, @AdjustQty, NULLIF(@UomId,0), ISNULL(@UnitCost,0), @Reason, @Notes, @CreatedBy);

    SELECT CAST(SCOPE_IDENTITY() AS INT) AS NewId;
END
GO

IF OBJECT_ID(N'[proj].[sp_ImportEmployees]') IS NOT NULL DROP PROCEDURE [proj].[sp_ImportEmployees];
GO
CREATE   PROCEDURE proj.sp_ImportEmployees
    @EmployeesJson NVARCHAR(MAX),
    @SavedBy       NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT r.EmpCode, r.EmployeeName,
               ISNULL(NULLIF(LTRIM(RTRIM(r.EmpType)), ''), 'COMPANY') AS EmpType,
               NULLIF(LTRIM(RTRIM(r.SupplierCode)), '')               AS SupplierCode
        INTO #Import
        FROM OPENJSON(@EmployeesJson)
        WITH (
            EmpCode      NVARCHAR(20)  '$.empCode',
            EmployeeName NVARCHAR(100) '$.employeeName',
            EmpType      NVARCHAR(20)  '$.empType',
            SupplierCode NVARCHAR(50)  '$.supplierCode'
        ) r;

        ALTER TABLE #Import ADD SupplierId INT NULL, ErrorMsg NVARCHAR(500) NULL;

        -- 1. EmpType must be COMPANY or OUTSOURCED
        UPDATE #Import
        SET ErrorMsg = ISNULL(ErrorMsg + ' | ', '')
                     + 'EmpType "' + EmpType + '" is invalid — must be COMPANY or OUTSOURCED'
        WHERE EmpType NOT IN ('COMPANY', 'OUTSOURCED');

        -- 2. Resolve supplier by code
        UPDATE i SET i.SupplierId = s.SupplierId
        FROM #Import i
        JOIN proj.TBL_SUPPLIER s ON s.SupplierCode = i.SupplierCode AND s.IsActive = 1;

        -- 3. OUTSOURCED must have a valid supplier
        UPDATE #Import
        SET ErrorMsg = ISNULL(ErrorMsg + ' | ', '')
                     + CASE
                           WHEN SupplierCode IS NULL THEN 'SUPPLIER_CODE is required for OUTSOURCED'
                           ELSE 'SUPPLIER_CODE "' + SupplierCode + '" not found in supplier list'
                       END
        WHERE EmpType = 'OUTSOURCED' AND SupplierId IS NULL AND ErrorMsg NOT LIKE '%invalid%';

        -- 4. COMPANY must NOT have a supplier
        UPDATE #Import
        SET ErrorMsg = ISNULL(ErrorMsg + ' | ', '')
                     + 'SUPPLIER_CODE provided but EmpType is COMPANY'
        WHERE EmpType = 'COMPANY' AND SupplierCode IS NOT NULL AND ErrorMsg NOT LIKE '%invalid%';

        -- 5. Duplicate empcode against existing records
        UPDATE #Import
        SET ErrorMsg = ISNULL(ErrorMsg + ' | ', '') + 'EmpCode already exists in the system'
        WHERE EmpCode IN (SELECT EmpCode FROM proj.TBL_EMPLOYEE);

        -- 6. Insert valid rows only
        INSERT INTO proj.TBL_EMPLOYEE
            (EmpCode, EmployeeName, EmpType, SupplierId, IsActive, CreatedBy, CreatedDate)
        SELECT EmpCode, EmployeeName, EmpType, SupplierId, 1, @SavedBy, GETDATE()
        FROM #Import WHERE ErrorMsg IS NULL;

        COMMIT TRANSACTION;

        SELECT EmpCode, EmployeeName, EmpType, SupplierCode,
               CASE WHEN ErrorMsg IS NULL THEN 1 ELSE 0 END AS Success,
               ISNULL(ErrorMsg, 'Imported successfully') AS Message
        FROM #Import;

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        THROW;
    END CATCH
END;
GO

IF OBJECT_ID(N'[proj].[sp_ImportJobBudgetItem]') IS NOT NULL DROP PROCEDURE [proj].[sp_ImportJobBudgetItem];
GO

CREATE PROCEDURE proj.sp_ImportJobBudgetItem
    @JobId        NVARCHAR(50),
    @RvNo         INT,
    @BudgetHeader NVARCHAR(200) = NULL,
    @ItemCode     NVARCHAR(50),
    @Qty          DECIMAL(18,4),
    @UnitPrice    DECIMAL(18,4) = 0,
    @By           NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM proj.TBL_JOB WHERE JobId=@JobId AND ApprovalStatus='Approved')
        BEGIN SELECT 0 AS Success, 'The job must be approved before its budget can be edited.' AS Message; RETURN; END

    DECLARE @ItemId INT = (SELECT TOP 1 ItemId FROM proj.TBL_ITEM WHERE ItemCode = @ItemCode);
    IF @ItemId IS NULL BEGIN SELECT 0 AS Success, CONCAT('Item not found: ', @ItemCode) AS Message; RETURN; END
    IF ISNULL(@Qty,0) <= 0 BEGIN SELECT 0 AS Success, 'Qty must be greater than zero.' AS Message; RETURN; END

    DECLARE @Costing BIT, @JobCat INT;
    SELECT @Costing = ISNULL(jt.IsCostingRequired,1), @JobCat = j.BudgetCategoryId
    FROM proj.TBL_JOB j JOIN proj.TBL_JOBTYPE jt ON jt.JobTypeId = j.JobTypeId WHERE j.JobId = @JobId;

    DECLARE @CatId INT;
    IF @Costing = 0 AND @JobCat IS NOT NULL
        SET @CatId = @JobCat;
    ELSE
        SET @CatId = (SELECT TOP 1 ExpenseCategoryId FROM proj.TBL_JOB_EXPENSE_CATEGORY
                      WHERE IsActive=1 AND UsedForBudget=1 AND (CategoryCode=@BudgetHeader OR CategoryName=@BudgetHeader));

    IF @CatId IS NULL BEGIN SELECT 0 AS Success, CONCAT('Budget header not found: ', ISNULL(@BudgetHeader,'(blank)')) AS Message; RETURN; END

    BEGIN TRY
        BEGIN TRAN;
        IF EXISTS (SELECT 1 FROM proj.TBL_JOB_BUDGET WHERE JobId=@JobId AND RvNo=@RvNo AND IsApproved=1)
            THROW 50720, 'Budget revision is approved and locked.', 1;

        DECLARE @Uom INT = (SELECT BaseUomId FROM proj.TBL_ITEM WHERE ItemId=@ItemId);
        DECLARE @existId INT = (SELECT TOP 1 BudgetItemId FROM proj.TBL_JOB_BUDGET_ITEM
            WHERE JobId=@JobId AND RvNo=@RvNo AND CostCategoryId=@CatId AND ItemId=@ItemId AND IsActive=1);
        DECLARE @oldQty DECIMAL(18,4), @oldPrice DECIMAL(18,4);
        IF @existId IS NOT NULL
        BEGIN
            SELECT @oldQty = Qty, @oldPrice = UnitPrice FROM proj.TBL_JOB_BUDGET_ITEM WHERE BudgetItemId=@existId;
            UPDATE proj.TBL_JOB_BUDGET_ITEM
            SET Qty = Qty + @Qty,
                UnitPrice = CASE WHEN ISNULL(@UnitPrice,0) > 0 THEN @UnitPrice ELSE UnitPrice END,
                ModifiedBy = @By, ModifiedDate = GETDATE()
            WHERE BudgetItemId = @existId;
            INSERT INTO proj.TBL_JOB_BUDGET_ITEM_LOG (BudgetItemId,JobId,RvNo,CostCategoryId,ItemId,Action,OldQty,NewQty,OldUnitPrice,NewUnitPrice,ChangedBy)
            VALUES (@existId,@JobId,@RvNo,@CatId,@ItemId,'INCREASE',@oldQty,@oldQty+@Qty,@oldPrice,
                    CASE WHEN ISNULL(@UnitPrice,0)>0 THEN @UnitPrice ELSE @oldPrice END,@By);
        END
        ELSE
        BEGIN
            INSERT INTO proj.TBL_JOB_BUDGET_ITEM (JobId, RvNo, CostCategoryId, ItemId, Qty, UomId, UnitPrice, CreatedBy)
            VALUES (@JobId, @RvNo, @CatId, @ItemId, @Qty, @Uom, @UnitPrice, @By);
            INSERT INTO proj.TBL_JOB_BUDGET_ITEM_LOG (BudgetItemId,JobId,RvNo,CostCategoryId,ItemId,Action,OldQty,NewQty,OldUnitPrice,NewUnitPrice,ChangedBy)
            VALUES (CAST(SCOPE_IDENTITY() AS INT),@JobId,@RvNo,@CatId,@ItemId,'ADD',NULL,@Qty,NULL,@UnitPrice,@By);
        END

        DECLARE @Sum DECIMAL(18,2) = ISNULL((SELECT SUM(Qty*UnitPrice) FROM proj.TBL_JOB_BUDGET_ITEM
            WHERE JobId=@JobId AND RvNo=@RvNo AND CostCategoryId=@CatId AND IsActive=1),0);
        EXEC proj.sp_SetJobBudget @JobId=@JobId, @CostCategoryId=@CatId, @RvNo=@RvNo, @BudgetedAmount=@Sum, @CreatedBy=@By;

        COMMIT;
        SELECT 1 AS Success, CASE WHEN @existId IS NOT NULL THEN 'Merged into existing item' ELSE 'Imported' END AS Message;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        SELECT 0 AS Success, ERROR_MESSAGE() AS Message;
    END CATCH
END;
GO

IF OBJECT_ID(N'[proj].[sp_IssueItemsPerJob]') IS NOT NULL DROP PROCEDURE [proj].[sp_IssueItemsPerJob];
GO

CREATE   PROCEDURE proj.sp_IssueItemsPerJob
    @JobId  NVARCHAR(50) = NULL,
    @Status NVARCHAR(50) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        si.IssueId,
        si.IssueNo,
        si.IssueDate,
        si.JobId,
        j.ProjectName,
        si.Status,
        si.IssuedTo,
        sl.IssueLineId,
        sl.LineNum,
        i.ItemCode,
        ISNULL(NULLIF(LTRIM(RTRIM(i.ItemName)),''), sl.ItemDesc) AS ItemDesc,
        sl.Qty,
        u.UomCode                             AS UomName,
        sl.UnitCost,
        ROUND(sl.Qty * sl.UnitCost, 2)        AS LineTotal,
        sl.Notes
    FROM  proj.TBL_STOCK_ISSUE_LINE sl
    JOIN  proj.TBL_STOCK_ISSUE      si ON si.IssueId = sl.IssueId
    LEFT JOIN proj.TBL_ITEM          i ON i.ItemId   = sl.ItemId
    LEFT JOIN proj.TBL_ITEM_UOM      u ON u.UomId    = sl.UomId
    LEFT JOIN proj.TBL_JOB           j ON j.JobId    = si.JobId
    WHERE sl.IsActive = 1
      AND si.IsActive = 1
      AND (@JobId  IS NULL OR si.JobId  = @JobId)
      AND (@Status IS NULL OR si.Status = @Status)
    ORDER BY si.IssueDate DESC, si.IssueNo, sl.LineNum;
END
GO

IF OBJECT_ID(N'[proj].[sp_JobItemLedgerIn]') IS NOT NULL DROP PROCEDURE [proj].[sp_JobItemLedgerIn];
GO

CREATE   PROCEDURE proj.sp_JobItemLedgerIn
    @DateFrom date         = NULL,
    @DateTo   date         = NULL,
    @JobId    nvarchar(50) = NULL,
    @ItemId   int          = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        gh.GrnId,
        gh.GrnNumber,
        gh.GrnDate,
        gh.JobId,
        j.ProjectName,
        s.SupplierName,
        po.PoNumber,
        gd.GrnDetailId,
        gd.LineNum,
        ISNULL(NULLIF(LTRIM(RTRIM(it.ItemName)),''), gd.ItemDesc) AS ItemDesc,
        gd.ReceivedQty,
        gd.UomName,
        gd.UnitPrice,
        ISNULL(gd.LineTotal, gd.ReceivedQty * gd.UnitPrice)       AS LineTotal,
        gh.InvoiceNo,
        gh.DoNo,
        gh.Status,
        gh.CreatedBy
    FROM proj.TBL_GRN_HEADER          gh
    JOIN proj.TBL_GRN_DETAIL           gd ON gd.GrnId      = gh.GrnId
    LEFT JOIN proj.TBL_SUPPLIER        s  ON s.SupplierId  = gh.SupplierId
    LEFT JOIN proj.TBL_PURCHASE_ORDER  po ON po.PoId       = gh.PoId
    LEFT JOIN proj.TBL_ITEM            it ON it.ItemId     = gd.ItemId
    JOIN proj.TBL_JOB                  j  ON j.JobId       = gh.JobId
    WHERE gh.IsActive = 1 AND gd.IsActive = 1
      AND (@JobId    IS NULL OR gh.JobId    = @JobId)
      AND (@ItemId   IS NULL OR gd.ItemId   = @ItemId)
      AND (@DateFrom IS NULL OR gh.GrnDate >= @DateFrom)
      AND (@DateTo   IS NULL OR gh.GrnDate <= @DateTo)
    ORDER BY gh.GrnDate, gh.GrnNumber, gd.LineNum;
END;
GO

IF OBJECT_ID(N'[proj].[sp_JobItemLedgerLookups]') IS NOT NULL DROP PROCEDURE [proj].[sp_JobItemLedgerLookups];
GO

-- Lookup SP for filter dropdowns
CREATE   PROCEDURE proj.sp_JobItemLedgerLookups
AS
BEGIN
    SET NOCOUNT ON;
    -- Job Types
    SELECT 'jobtype' AS ResultSet, CAST(JobTypeId AS nvarchar) AS Id, JobTypeName AS Name
    FROM proj.TBL_JOBTYPE WHERE IsActive = 1 ORDER BY SortOrder, JobTypeName;

    -- Item Categories (root level only, Level=0 or ParentCategoryId IS NULL)
    SELECT 'category' AS ResultSet, CAST(CategoryId AS nvarchar) AS Id, CategoryName AS Name
    FROM proj.TBL_ITEM_CATEGORY WHERE ParentCategoryId IS NULL AND IsActive = 1 ORDER BY CategoryName;

    -- All subcategories (with ParentCategoryId for client-side filtering)
    SELECT 'subcategory' AS ResultSet,
           CAST(CategoryId AS nvarchar)       AS Id,
           CategoryName                        AS Name,
           CAST(ParentCategoryId AS nvarchar)  AS ParentId
    FROM proj.TBL_ITEM_CATEGORY WHERE ParentCategoryId IS NOT NULL AND IsActive = 1 ORDER BY CategoryName;

    -- Item Types
    SELECT 'itemtype' AS ResultSet, CAST(ItemTypeId AS nvarchar) AS Id, TypeName AS Name
    FROM proj.TBL_ITEM_TYPE WHERE IsActive = 1 ORDER BY SortOrder, TypeName;
END;
GO

IF OBJECT_ID(N'[proj].[sp_JobItemLedgerOut]') IS NOT NULL DROP PROCEDURE [proj].[sp_JobItemLedgerOut];
GO

CREATE   PROCEDURE proj.sp_JobItemLedgerOut
    @DateFrom date         = NULL,
    @DateTo   date         = NULL,
    @JobId    nvarchar(50) = NULL,
    @ItemId   int          = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        si.IssueId,
        si.IssueNo,
        si.IssueDate,
        si.JobId,
        j.ProjectName,
        si.IssuedTo,
        sl.IssueLineId,
        sl.LineNum,
        ISNULL(NULLIF(LTRIM(RTRIM(it.ItemName)),''), sl.ItemDesc) AS ItemDesc,
        sl.Qty,
        u.UomName,
        sl.UnitCost,
        sl.Qty * sl.UnitCost    AS LineTotal,
        sl.Notes,
        si.Status,
        si.CreatedBy
    FROM proj.TBL_STOCK_ISSUE      si
    JOIN proj.TBL_STOCK_ISSUE_LINE sl ON sl.IssueId   = si.IssueId
    JOIN proj.TBL_ITEM             it ON it.ItemId     = sl.ItemId
    LEFT JOIN proj.TBL_ITEM_UOM    u  ON u.UomId       = it.BaseUomId
    JOIN proj.TBL_JOB              j  ON j.JobId       = si.JobId
    WHERE si.IsActive = 1 AND sl.IsActive = 1
      AND (@JobId    IS NULL OR si.JobId     = @JobId)
      AND (@ItemId   IS NULL OR sl.ItemId    = @ItemId)
      AND (@DateFrom IS NULL OR si.IssueDate >= @DateFrom)
      AND (@DateTo   IS NULL OR si.IssueDate <= @DateTo)
    ORDER BY si.IssueDate, si.IssueNo, sl.LineNum;
END;
GO

IF OBJECT_ID(N'[proj].[sp_JobItemLedgerSummary]') IS NOT NULL DROP PROCEDURE [proj].[sp_JobItemLedgerSummary];
GO

CREATE   PROCEDURE proj.sp_JobItemLedgerSummary
    @DateFrom      date         = NULL,
    @DateTo        date         = NULL,
    @JobId         nvarchar(50) = NULL,
    @JobTypeId     nvarchar(20) = NULL,
    @CategoryId    int          = NULL,
    @SubCategoryId int          = NULL,
    @ItemTypeId    int          = NULL,
    @ItemId        int          = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- Received (IN) aggregated by Job + Item
    ;WITH ReceivedCTE AS (
        SELECT
            gh.JobId,
            gd.ItemId,
            SUM(gd.ReceivedQty)                                           AS TotalReceivedQty,
            SUM(ISNULL(gd.LineTotal, gd.ReceivedQty * gd.UnitPrice))      AS TotalReceivedValue
        FROM proj.TBL_GRN_HEADER  gh
        JOIN proj.TBL_GRN_DETAIL  gd ON gd.GrnId   = gh.GrnId
        WHERE gh.IsActive = 1 AND gd.IsActive = 1
          AND gd.ItemId IS NOT NULL
          AND (@JobId    IS NULL OR gh.JobId    = @JobId)
          AND (@DateFrom IS NULL OR gh.GrnDate >= @DateFrom)
          AND (@DateTo   IS NULL OR gh.GrnDate <= @DateTo)
        GROUP BY gh.JobId, gd.ItemId
    ),
    -- Issued (OUT) aggregated by Job + Item
    IssuedCTE AS (
        SELECT
            si.JobId,
            sl.ItemId,
            SUM(sl.Qty)                   AS TotalIssuedQty,
            SUM(sl.Qty * sl.UnitCost)     AS TotalIssuedValue
        FROM proj.TBL_STOCK_ISSUE      si
        JOIN proj.TBL_STOCK_ISSUE_LINE sl ON sl.IssueId = si.IssueId
        WHERE si.IsActive = 1 AND sl.IsActive = 1
          AND (@JobId    IS NULL OR si.JobId    = @JobId)
          AND (@DateFrom IS NULL OR si.IssueDate >= @DateFrom)
          AND (@DateTo   IS NULL OR si.IssueDate <= @DateTo)
        GROUP BY si.JobId, sl.ItemId
    ),
    Combined AS (
        SELECT
            ISNULL(r.JobId,  i.JobId)  AS JobId,
            ISNULL(r.ItemId, i.ItemId) AS ItemId,
            ISNULL(r.TotalReceivedQty,   0) AS TotalReceivedQty,
            ISNULL(r.TotalReceivedValue, 0) AS TotalReceivedValue,
            ISNULL(i.TotalIssuedQty,     0) AS TotalIssuedQty,
            ISNULL(i.TotalIssuedValue,   0) AS TotalIssuedValue
        FROM ReceivedCTE r
        FULL OUTER JOIN IssuedCTE i ON i.JobId = r.JobId AND i.ItemId = r.ItemId
    )
    SELECT
        c.JobId,
        j.ProjectName,
        j.JobTypeId,
        jt.JobTypeName,
        c.ItemId,
        it.ItemCode,
        it.ItemName,
        u.UomName,
        -- Category hierarchy: if item's category has a parent, show parent as Category
        CASE WHEN ic.ParentCategoryId IS NULL THEN ic.CategoryName
             ELSE pic.CategoryName END AS CategoryName,
        CASE WHEN ic.ParentCategoryId IS NULL THEN NULL
             ELSE ic.CategoryName END  AS SubCategoryName,
        ic.CategoryId                  AS ItemCategoryId,
        ISNULL(ic.ParentCategoryId, ic.CategoryId) AS RootCategoryId,
        itp.TypeName                   AS ItemTypeName,
        itp.ItemTypeId,
        c.TotalReceivedQty,
        c.TotalReceivedValue,
        c.TotalIssuedQty,
        c.TotalIssuedValue,
        c.TotalReceivedQty  - c.TotalIssuedQty   AS NetQty,
        c.TotalReceivedValue - c.TotalIssuedValue AS NetValue
    FROM Combined c
    JOIN proj.TBL_JOB         j   ON j.JobId      = c.JobId
    JOIN proj.TBL_JOBTYPE     jt  ON jt.JobTypeId = j.JobTypeId
    JOIN proj.TBL_ITEM        it  ON it.ItemId     = c.ItemId
    JOIN proj.TBL_ITEM_UOM    u   ON u.UomId       = it.BaseUomId
    JOIN proj.TBL_ITEM_CATEGORY ic  ON ic.CategoryId = it.CategoryId
    LEFT JOIN proj.TBL_ITEM_CATEGORY pic ON pic.CategoryId = ic.ParentCategoryId
    JOIN proj.TBL_ITEM_TYPE   itp ON itp.ItemTypeId = it.ItemTypeId
    WHERE
        (@JobTypeId     IS NULL OR j.JobTypeId    = @JobTypeId)
        -- Category filter: match root or any child
        AND (@CategoryId IS NULL
             OR ic.CategoryId = @CategoryId
             OR ic.ParentCategoryId = @CategoryId)
        -- Subcategory filter: exact match
        AND (@SubCategoryId IS NULL OR it.CategoryId = @SubCategoryId)
        AND (@ItemTypeId IS NULL OR it.ItemTypeId  = @ItemTypeId)
        AND (@ItemId     IS NULL OR c.ItemId       = @ItemId)
    ORDER BY c.JobId, it.ItemCode;
END;
GO

