IF OBJECT_ID(N'[proj].[sp_PostAdjustment]') IS NOT NULL DROP PROCEDURE [proj].[sp_PostAdjustment];
GO

CREATE PROCEDURE proj.sp_PostAdjustment
    @AdjustmentId INT,
    @PostedBy     NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    BEGIN TRY
        DECLARE @AdjNo NVARCHAR(30), @Status NVARCHAR(20);
        SELECT @AdjNo = AdjustmentNo, @Status = Status
        FROM proj.TBL_STOCK_ADJUSTMENT WHERE AdjustmentId = @AdjustmentId AND IsActive = 1;

        IF @AdjNo IS NULL
            RAISERROR('Adjustment not found.', 16, 1);
        IF @Status = 'Posted'
            RAISERROR('Adjustment already posted.', 16, 1);
        IF NOT EXISTS (SELECT 1 FROM proj.TBL_STOCK_ADJUSTMENT_LINE WHERE AdjustmentId=@AdjustmentId AND IsActive=1)
            RAISERROR('Cannot post an adjustment with no lines.', 16, 1);

        DECLARE @ItemId INT, @Qty DECIMAL(18,4), @UnitCost DECIMAL(18,4), @UomId INT,
                @BaseUomId INT, @ConvFactor DECIMAL(18,6),
                @StockQty DECIMAL(18,4), @StockUnitCost DECIMAL(18,4),
                @ConvErrMsg NVARCHAR(400),
                @SourceJobId NVARCHAR(50), @SrcBal DECIMAL(18,4), @ShortMsg NVARCHAR(400);

        DECLARE cur CURSOR LOCAL FOR
            SELECT ItemId, AdjustQty, UnitCost, UomId
            FROM proj.TBL_STOCK_ADJUSTMENT_LINE
            WHERE AdjustmentId = @AdjustmentId AND IsActive = 1;

        OPEN cur;
        FETCH NEXT FROM cur INTO @ItemId, @Qty, @UnitCost, @UomId;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            SELECT @BaseUomId = BaseUomId FROM proj.TBL_ITEM WHERE ItemId = @ItemId;
            SET @ConvFactor = NULL;
            IF @UomId IS NOT NULL AND @BaseUomId IS NOT NULL AND @UomId <> @BaseUomId
            BEGIN
                SELECT @ConvFactor = ConversionFactor
                FROM proj.TBL_ITEM_UOM_CONVERSION
                WHERE ItemId=@ItemId AND FromUomId=@UomId AND ToUomId=@BaseUomId AND IsActive=1;
                IF @ConvFactor IS NULL OR @ConvFactor = 0
                BEGIN
                    SET @ConvErrMsg = 'No UOM conversion defined for item ' +
                        ISNULL((SELECT ItemCode FROM proj.TBL_ITEM WHERE ItemId=@ItemId), CAST(@ItemId AS NVARCHAR(20))) +
                        ' (' + ISNULL((SELECT UomCode FROM proj.TBL_ITEM_UOM WHERE UomId=@UomId), '?') +
                        ' to ' + ISNULL((SELECT UomCode FROM proj.TBL_ITEM_UOM WHERE UomId=@BaseUomId), '?') +
                        '). Configure it in Item master > UOM Conversions.';
                    RAISERROR(@ConvErrMsg, 16, 1);
                END
                SET @StockQty      = @Qty * @ConvFactor;
                SET @StockUnitCost = CASE WHEN ABS(@ConvFactor) > 0 THEN @UnitCost / @ConvFactor ELSE @UnitCost END;
            END
            ELSE
            BEGIN
                SET @StockQty      = @Qty;
                SET @StockUnitCost = @UnitCost;
            END

            IF NOT EXISTS (SELECT 1 FROM proj.TBL_STOCK_BALANCE WHERE ItemId=@ItemId)
                INSERT INTO proj.TBL_STOCK_BALANCE (ItemId, QtyOnHand, AvgUnitCost, UpdatedDate)
                VALUES (@ItemId, 0, @StockUnitCost, GETDATE());

            -- Derive the in-house job for this item via its budget header
            SET @SourceJobId = NULL;
            SELECT TOP 1 @SourceJobId = j.JobId
            FROM proj.TBL_ITEM it
            JOIN proj.TBL_JOB        j  ON j.BudgetCategoryId = it.BudgetCategoryId
            JOIN proj.TBL_JOBTYPE    jt ON jt.JobTypeId = j.JobTypeId AND ISNULL(jt.IsBudgetHeaderLinked,0) = 1
            JOIN proj.TBL_JOB_STATUS js ON js.JobStatusId = j.JobStatusId AND ISNULL(js.IsClosed,0) = 0
            WHERE it.ItemId = @ItemId AND it.BudgetCategoryId IS NOT NULL
            ORDER BY j.JobCreatedDate DESC;

            IF @SourceJobId IS NOT NULL
            BEGIN
                -- In-house item: adjust against store stock (IsJobStock=0).
                -- QtyStoreStock is computed (QtyOnHand - QtyJobStock); only touch QtyOnHand.
                IF @StockQty >= 0
                BEGIN
                    UPDATE proj.TBL_STOCK_BALANCE
                    SET QtyOnHand = QtyOnHand + @StockQty,
                        LastReceiptDate = GETDATE(), UpdatedDate = GETDATE()
                    WHERE ItemId = @ItemId;

                    INSERT INTO proj.TBL_STOCK_LEDGER
                        (ItemId, TransType, RefId, RefNo, QtyIn, QtyOut, UnitCost, IsJobStock, JobId, CreatedBy)
                    VALUES
                        (@ItemId, 'ADJ-IN', @AdjustmentId, @AdjNo, @StockQty, 0, @StockUnitCost, 0, @SourceJobId, @PostedBy);
                END
                ELSE
                BEGIN
                    -- Balance check using JobId only (covers both new IsJobStock=0
                    -- and any legacy IsJobStock=1 in-house ledger entries)
                    SELECT @SrcBal = ISNULL(SUM(QtyIn - QtyOut), 0)
                    FROM proj.TBL_STOCK_LEDGER
                    WHERE ItemId = @ItemId AND JobId = @SourceJobId;

                    IF @SrcBal < ABS(@StockQty)
                    BEGIN
                        SET @ShortMsg = 'Adjustment would drive in-house stock negative for item ' +
                            ISNULL((SELECT ItemCode FROM proj.TBL_ITEM WHERE ItemId=@ItemId), CAST(@ItemId AS NVARCHAR(20))) +
                            ' in job ' + @SourceJobId + ' (have ' + CAST(@SrcBal AS NVARCHAR(30)) +
                            ', need ' + CAST(ABS(@StockQty) AS NVARCHAR(30)) + ').';
                        RAISERROR(@ShortMsg, 16, 1);
                    END

                    UPDATE proj.TBL_STOCK_BALANCE
                    SET QtyOnHand = QtyOnHand - ABS(@StockQty),
                        UpdatedDate = GETDATE()
                    WHERE ItemId = @ItemId;

                    INSERT INTO proj.TBL_STOCK_LEDGER
                        (ItemId, TransType, RefId, RefNo, QtyIn, QtyOut, UnitCost, IsJobStock, JobId, CreatedBy)
                    VALUES
                        (@ItemId, 'ADJ-OUT', @AdjustmentId, @AdjNo, 0, ABS(@StockQty), @StockUnitCost, 0, @SourceJobId, @PostedBy);
                END
            END
            ELSE IF @StockQty < 0
            BEGIN
                -- Regular store item: ADJ-OUT against general stock
                UPDATE proj.TBL_STOCK_BALANCE
                SET QtyOnHand = QtyOnHand - ABS(@StockQty), UpdatedDate = GETDATE()
                WHERE ItemId = @ItemId AND ISNULL(QtyOnHand,0) >= ABS(@StockQty);

                IF @@ROWCOUNT = 0
                    RAISERROR('Adjustment would drive stock negative for one or more items.', 16, 1);

                INSERT INTO proj.TBL_STOCK_LEDGER
                    (ItemId, TransType, RefId, RefNo, QtyIn, QtyOut, UnitCost, IsJobStock, JobId, CreatedBy)
                VALUES
                    (@ItemId, 'ADJ-OUT', @AdjustmentId, @AdjNo, 0, ABS(@StockQty), @StockUnitCost, 0, NULL, @PostedBy);
            END
            ELSE
            BEGIN
                -- Regular store item: ADJ-IN to general stock
                UPDATE proj.TBL_STOCK_BALANCE
                SET QtyOnHand = QtyOnHand + @StockQty, LastReceiptDate = GETDATE(), UpdatedDate = GETDATE()
                WHERE ItemId = @ItemId;

                INSERT INTO proj.TBL_STOCK_LEDGER
                    (ItemId, TransType, RefId, RefNo, QtyIn, QtyOut, UnitCost, IsJobStock, JobId, CreatedBy)
                VALUES
                    (@ItemId, 'ADJ-IN', @AdjustmentId, @AdjNo, @StockQty, 0, @StockUnitCost, 0, NULL, @PostedBy);
            END

            FETCH NEXT FROM cur INTO @ItemId, @Qty, @UnitCost, @UomId;
        END
        CLOSE cur; DEALLOCATE cur;

        UPDATE proj.TBL_STOCK_ADJUSTMENT
        SET Status='Posted', PostedBy=@PostedBy, PostedDate=GETDATE(), ModifiedBy=@PostedBy, ModifiedDate=GETDATE()
        WHERE AdjustmentId=@AdjustmentId;

        COMMIT;
        -- no result set — runs as an approval post-hook inside sp_ProcessApproval
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        IF CURSOR_STATUS('local','cur') >= 0 BEGIN CLOSE cur; DEALLOCATE cur; END
        DECLARE @Msg NVARCHAR(500) = ERROR_MESSAGE();
        RAISERROR(@Msg, 16, 1); RETURN;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_PostCnApproval]') IS NOT NULL DROP PROCEDURE [proj].[sp_PostCnApproval];
