CREATE PROCEDURE proj.sp_PostCnApproval
    @CnId       INT,
    @ApprovedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    -- Validate currency/rate
    DECLARE @CurrencyId INT, @Rate DECIMAL(18,6);
    SELECT @CurrencyId = CurrencyId, @Rate = ExchangeRate
    FROM proj.TBL_CREDIT_NOTE WHERE CnId = @CnId;
    EXEC proj.sp_ValidateTxnCurrency @CurrencyId, @Rate, N'Credit note';
    -- No job recalc needed for CN allocations (credit offset, not cash payment)
    -- If future requirement: iterate through allocated invoices' jobs here
END
GO

IF OBJECT_ID(N'[proj].[sp_PostDnApproval]') IS NOT NULL DROP PROCEDURE [proj].[sp_PostDnApproval];
GO

CREATE PROCEDURE proj.sp_PostDnApproval
    @DnId       INT,
    @ApprovedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    -- Validate currency/rate (mirror sp_PostCnApproval)
    DECLARE @CurrencyId INT, @Rate DECIMAL(18,6);
    SELECT @CurrencyId = CurrencyId, @Rate = ExchangeRate
    FROM proj.TBL_DEBIT_NOTE WHERE DnId = @DnId;
    EXEC proj.sp_ValidateTxnCurrency @CurrencyId, @Rate, N'Debit note';
    -- No job recalc needed for DN allocations (debit offset, not cash payment)
END
GO

IF OBJECT_ID(N'[proj].[sp_PostInvoiceApproval]') IS NOT NULL DROP PROCEDURE [proj].[sp_PostInvoiceApproval];
GO

CREATE   PROCEDURE proj.sp_PostInvoiceApproval
    @InvoiceId  INT,
    @ApprovedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @JobId NVARCHAR(50), @CurrencyId INT, @Rate DECIMAL(18,6);
    SELECT @JobId = JobId, @CurrencyId = CurrencyId, @Rate = ExchangeRate
    FROM proj.TBL_INVOICE WHERE InvoiceId = @InvoiceId;

    -- Guard: never post an invoice to job finance with a missing/invalid currency or rate.
    EXEC proj.sp_ValidateTxnCurrency @CurrencyId, @Rate, N'Invoice';

    IF NULLIF(@JobId, '') IS NOT NULL
        EXEC proj.sp_RecalcJobInvoicing @JobId, @ApprovedBy;
END
GO

IF OBJECT_ID(N'[proj].[sp_PostIssueReturnApproval]') IS NOT NULL DROP PROCEDURE [proj].[sp_PostIssueReturnApproval];
GO
-- sp_PostIssueReturnApproval: add in-house job detection (same as sp_ConfirmIssueReturn)
CREATE PROCEDURE proj.sp_PostIssueReturnApproval
    @ReturnId INT,
    @PostedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @IssueId    INT,
                @ReturnNo   NVARCHAR(30),
                @ReturnDate DATE;

        SELECT @IssueId = r.IssueId, @ReturnNo = r.ReturnNo, @ReturnDate = r.ReturnDate
        FROM proj.TBL_STOCK_ISSUE_RETURN r
        WHERE r.ReturnId = @ReturnId AND r.IsActive = 1;

        IF @IssueId IS NULL THROW 60200, 'Issue Return not found.', 1;

        IF EXISTS (SELECT 1 FROM proj.TBL_STOCK_LEDGER
                   WHERE TransType = 'RETURN' AND RefId = @ReturnId)
        BEGIN
            COMMIT TRANSACTION;
            RETURN;
        END

        DECLARE @CostingType NVARCHAR(20), @JobId NVARCHAR(50);
        SELECT @CostingType = CostingType, @JobId = JobId
        FROM proj.TBL_STOCK_ISSUE WHERE IssueId = @IssueId;

        DECLARE @ReturnLineId INT, @ItemId INT, @ReturnQty DECIMAL(18,4), @UnitCost DECIMAL(18,4),
                @SourceJobId NVARCHAR(50);

        DECLARE line_cur CURSOR LOCAL FAST_FORWARD FOR
            SELECT ReturnLineId, ItemId, ReturnQty, UnitCost
            FROM proj.TBL_STOCK_ISSUE_RETURN_LINE
            WHERE ReturnId = @ReturnId;
        OPEN line_cur;
        FETCH NEXT FROM line_cur INTO @ReturnLineId, @ItemId, @ReturnQty, @UnitCost;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            -- Derive in-house source job via the item's budget header
            SET @SourceJobId = NULL;
            SELECT TOP 1 @SourceJobId = j.JobId
            FROM proj.TBL_ITEM it
            JOIN proj.TBL_JOB        j  ON j.BudgetCategoryId = it.BudgetCategoryId
            JOIN proj.TBL_JOBTYPE    jt ON jt.JobTypeId = j.JobTypeId AND ISNULL(jt.IsBudgetHeaderLinked,0) = 1
            JOIN proj.TBL_JOB_STATUS js ON js.JobStatusId = j.JobStatusId AND ISNULL(js.IsClosed,0) = 0
            WHERE it.ItemId = @ItemId AND it.BudgetCategoryId IS NOT NULL
            ORDER BY j.JobCreatedDate DESC;

            IF @SourceJobId IS NOT NULL
            BEGIN
                -- In-house return: stock goes back as store stock (IsJobStock=0)
                INSERT INTO proj.TBL_STOCK_LEDGER
                    (ItemId, TransDate, TransType, RefId, RefNo, QtyIn, QtyOut, UnitCost, IsJobStock, JobId, CreatedBy)
                VALUES
                    (@ItemId, @ReturnDate, 'RETURN', @ReturnId, @ReturnNo,
                     @ReturnQty, 0, @UnitCost, 0, @SourceJobId, @PostedBy);

                UPDATE proj.TBL_STOCK_BALANCE
                SET QtyOnHand = QtyOnHand + @ReturnQty, UpdatedDate = GETDATE()
                WHERE ItemId = @ItemId;
                IF @@ROWCOUNT = 0
                    INSERT INTO proj.TBL_STOCK_BALANCE (ItemId, QtyOnHand, QtyJobStock, AvgUnitCost, UpdatedDate)
                    VALUES (@ItemId, @ReturnQty, 0, @UnitCost, GETDATE());
            END
            ELSE
            BEGIN
                DECLARE @IsJobStock BIT = CASE WHEN @CostingType = 'EXC_COSTING' THEN 1 ELSE 0 END;

                INSERT INTO proj.TBL_STOCK_LEDGER
                    (ItemId, TransDate, TransType, RefId, RefNo, QtyIn, QtyOut,
                     UnitCost, IsJobStock, JobId, CreatedBy)
                VALUES
                    (@ItemId, @ReturnDate, 'RETURN', @ReturnId, @ReturnNo,
                     @ReturnQty, 0, @UnitCost, @IsJobStock, @JobId, @PostedBy);

                IF @CostingType = 'INC_COSTING'
                BEGIN
                    UPDATE proj.TBL_STOCK_BALANCE
                    SET QtyOnHand = QtyOnHand + @ReturnQty, UpdatedDate = GETDATE()
                    WHERE ItemId = @ItemId;
                    IF @@ROWCOUNT = 0
                        INSERT INTO proj.TBL_STOCK_BALANCE (ItemId, QtyOnHand, QtyJobStock, AvgUnitCost, UpdatedDate)
                        VALUES (@ItemId, @ReturnQty, 0, @UnitCost, GETDATE());
                END
                ELSE
                BEGIN
                    UPDATE proj.TBL_STOCK_BALANCE
                    SET QtyOnHand = QtyOnHand + @ReturnQty,
                        QtyJobStock = QtyJobStock + @ReturnQty,
                        UpdatedDate = GETDATE()
                    WHERE ItemId = @ItemId;
                    IF @@ROWCOUNT = 0
                        INSERT INTO proj.TBL_STOCK_BALANCE (ItemId, QtyOnHand, QtyJobStock, AvgUnitCost, UpdatedDate)
                        VALUES (@ItemId, @ReturnQty, @ReturnQty, @UnitCost, GETDATE());
                END
            END

            FETCH NEXT FROM line_cur INTO @ReturnLineId, @ItemId, @ReturnQty, @UnitCost;
        END
        CLOSE line_cur;
        DEALLOCATE line_cur;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

IF OBJECT_ID(N'[proj].[sp_PostMaterialOut]') IS NOT NULL DROP PROCEDURE [proj].[sp_PostMaterialOut];
GO
CREATE PROCEDURE proj.sp_PostMaterialOut
    @MaterialOutId  INT,
    @ActionBy       NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        DECLARE @Status        NVARCHAR(20);
        DECLARE @SubcontractId INT;

        SELECT
            @Status        = Status,
            @SubcontractId = SubcontractId
        FROM proj.TBL_MATERIAL_OUT
        WHERE MaterialOutId = @MaterialOutId AND IsActive = 1;

        IF @Status IS NULL
            RAISERROR('Material Out document not found.', 16, 1);
        IF @Status <> 'Draft'
            RAISERROR('Only Draft Material Out documents can be posted.', 16, 1);

        BEGIN TRANSACTION;

            -- Update component IssuedQty for tracking
            UPDATE sc SET
                sc.IssuedQty = sc.IssuedQty + mol.Qty
            FROM proj.TBL_SUBCONTRACT_COMPONENT sc
            JOIN proj.TBL_MATERIAL_OUT_LINE mol ON mol.ComponentId = sc.ComponentId
            WHERE mol.MaterialOutId = @MaterialOutId AND mol.IsActive = 1;

            -- Mark as Posted
            UPDATE proj.TBL_MATERIAL_OUT SET
                Status       = 'Posted',
                ModifiedBy   = @ActionBy,
                ModifiedDate = GETDATE()
            WHERE MaterialOutId = @MaterialOutId;

            -- Advance subcontract to InProgress
            UPDATE proj.TBL_SUBCONTRACT_ORDER SET
                Status       = 'InProgress',
                ModifiedBy   = @ActionBy,
                ModifiedDate = GETDATE()
            WHERE SubcontractId = @SubcontractId AND Status = 'Approved';

        COMMIT TRANSACTION;

        SELECT 'Posted' AS Status;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        DECLARE @ErrMsg NVARCHAR(MAX) = ERROR_MESSAGE();
        EXEC proj.sp_WriteLog @Action='sp_PostMaterialOut', @Message=@ErrMsg, @UserId=@ActionBy;
        THROW;
    END CATCH
END;
GO

IF OBJECT_ID(N'[proj].[sp_PostPvApproval]') IS NOT NULL DROP PROCEDURE [proj].[sp_PostPvApproval];
