IF OBJECT_ID(N'[proj].[sp_PostRTV]') IS NOT NULL DROP PROCEDURE [proj].[sp_PostRTV];
GO
CREATE PROCEDURE proj.sp_PostRTV
    @RtvId        INT,
    @PostedBy     NVARCHAR(100),
    @Reason       NVARCHAR(500),
    @PasswordHash NVARCHAR(500)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    BEGIN TRY

        IF NULLIF(@PostedBy, '') IS NULL
            RAISERROR('PostedBy is required.', 16, 1);

        IF NOT EXISTS (
            SELECT 1 FROM proj.TBL_USERS
            WHERE UserName = @PostedBy AND PasswordHash = @PasswordHash AND IsActive = 1)
            RAISERROR('Incorrect password.', 16, 1);

        IF LTRIM(RTRIM(ISNULL(@Reason, ''))) = ''
            RAISERROR('A reason is required to post the RTV.', 16, 1);

        DECLARE @Status    NVARCHAR(30),
                @RtvNumber NVARCHAR(50),
                @GrnId     INT,
                @JobId     NVARCHAR(50);

        SELECT @Status    = Status,
               @RtvNumber = RtvNumber,
               @GrnId     = GrnId,
               @JobId     = JobId
        FROM   proj.TBL_RETURN_TO_VENDOR
        WHERE  RtvId = @RtvId AND IsActive = 1;

        IF @Status IS NULL    RAISERROR('RTV not found.', 16, 1);
        IF @Status <> 'Draft' RAISERROR('Only Draft RTVs can be posted.', 16, 1);

        IF NOT EXISTS (
            SELECT 1 FROM proj.TBL_RETURN_TO_VENDOR_LINE
            WHERE RtvId = @RtvId AND IsActive = 1 AND ReturnQty > 0)
            RAISERROR('RTV has no lines with return quantity. Add lines before posting.', 16, 1);

        IF NOT EXISTS (
            SELECT 1 FROM proj.TBL_RETURN_TO_VENDOR_LINE
            WHERE RtvId = @RtvId AND IsActive = 1 AND ReturnQty > 0 AND ItemId IS NOT NULL)
            RAISERROR('No lines are linked to a catalog item. Select items from the item master so stock movements can be recorded.', 16, 1);

        -- In-house jobs (IsBudgetHeaderLinked=1) → store stock (IsJobStock=0).
        -- All other jobs → job stock (IsJobStock=1).
        DECLARE @IsInHouseJob BIT = 0;
        IF NULLIF(@JobId,'') IS NOT NULL
            SELECT @IsInHouseJob = ISNULL(jt.IsBudgetHeaderLinked, 0)
            FROM   proj.TBL_JOB j
            JOIN   proj.TBL_JOBTYPE jt ON jt.JobTypeId = j.JobTypeId
            WHERE  j.JobId = @JobId;

        DECLARE @IsJobStockBit BIT = CASE WHEN NULLIF(@JobId,'') IS NOT NULL AND @IsInHouseJob = 0 THEN 1 ELSE 0 END;

        DECLARE @NegItems NVARCHAR(500) = '';
        SELECT @NegItems = @NegItems +
               ISNULL(l.ItemCode, 'ItemId:'+CAST(l.ItemId AS NVARCHAR)) +
               ' (balance=' + CAST(ISNULL(sb.QtyOnHand,0) AS NVARCHAR) +
               ', return='  + CAST(l.ReturnQty * ISNULL(uc.ConversionFactor,1) AS NVARCHAR) + ') '
        FROM   proj.TBL_RETURN_TO_VENDOR_LINE l
        LEFT  JOIN proj.TBL_STOCK_BALANCE sb ON sb.ItemId = l.ItemId
        LEFT  JOIN proj.TBL_ITEM i ON i.ItemId = l.ItemId
        LEFT  JOIN proj.TBL_ITEM_UOM_CONVERSION uc
               ON uc.ItemId    = l.ItemId
              AND uc.FromUomId = l.UomId
              AND uc.ToUomId   = i.BaseUomId
              AND uc.IsActive  = 1
        WHERE  l.RtvId = @RtvId AND l.IsActive = 1 AND l.ItemId IS NOT NULL AND l.ReturnQty > 0
          AND  (ISNULL(sb.QtyOnHand,0) - l.ReturnQty * ISNULL(uc.ConversionFactor,1)) < 0;

        IF LEN(@NegItems) > 0
        BEGIN
            DECLARE @NM NVARCHAR(600) = 'Cannot post: stock would go negative. Affected: ' + @NegItems;
            RAISERROR(@NM, 16, 1);
        END

        DECLARE @ItemId    INT,
                @ItemCode  NVARCHAR(50),
                @ReturnQty DECIMAL(18,4),
                @UnitCost  DECIMAL(18,4),
                @UomId     INT,
                @PoLineId  INT,
                @PrLineId  INT,
                @BaseUomId INT,
                @ConvFactor DECIMAL(18,6),
                @StockQty   DECIMAL(18,4),
                @StockUnitCost DECIMAL(18,4),
                @ConvErrMsg NVARCHAR(400);

        DECLARE cur CURSOR LOCAL FAST_FORWARD FOR
            SELECT ItemId, ItemCode, ReturnQty, UnitCost, UomId, PoLineId, PrLineId
            FROM   proj.TBL_RETURN_TO_VENDOR_LINE
            WHERE  RtvId = @RtvId AND IsActive = 1 AND ItemId IS NOT NULL AND ReturnQty > 0;

        OPEN cur;
        FETCH NEXT FROM cur INTO @ItemId, @ItemCode, @ReturnQty, @UnitCost, @UomId, @PoLineId, @PrLineId;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            SELECT @BaseUomId = BaseUomId FROM proj.TBL_ITEM WHERE ItemId = @ItemId;
            SET @ConvFactor = NULL;
            IF @UomId IS NOT NULL AND @BaseUomId IS NOT NULL AND @UomId <> @BaseUomId
            BEGIN
                SELECT @ConvFactor = ConversionFactor
                FROM proj.TBL_ITEM_UOM_CONVERSION
                WHERE ItemId=@ItemId AND FromUomId=@UomId AND ToUomId=@BaseUomId AND IsActive=1;
                IF @ConvFactor IS NULL OR @ConvFactor = 0
                BEGIN
                    SET @ConvErrMsg = 'No UOM conversion defined for "' + ISNULL(@ItemCode,CAST(@ItemId AS NVARCHAR(20))) +
                                      '". Configure in Item master > UOM Conversions tab.';
                    RAISERROR(@ConvErrMsg, 16, 1);
                END
                SET @StockQty      = @ReturnQty * @ConvFactor;
                SET @StockUnitCost = @UnitCost / @ConvFactor;
            END
            ELSE
            BEGIN
                SET @StockQty      = @ReturnQty;
                SET @StockUnitCost = @UnitCost;
            END

            UPDATE proj.TBL_STOCK_BALANCE
            SET    QtyOnHand   = CASE WHEN QtyOnHand   - @StockQty < 0 THEN 0 ELSE QtyOnHand   - @StockQty END,
                   QtyJobStock = CASE WHEN @IsJobStockBit = 1
                                      THEN CASE WHEN QtyJobStock - @StockQty < 0 THEN 0 ELSE QtyJobStock - @StockQty END
                                      ELSE QtyJobStock END,
                   UpdatedDate = GETDATE()
            WHERE  ItemId = @ItemId;

            IF @@ROWCOUNT = 0
            BEGIN
                DECLARE @BalMsg NVARCHAR(200) = 'No stock balance record found for item ' +
                    ISNULL(@ItemCode, CAST(@ItemId AS NVARCHAR)) + '. Cannot post.';
                RAISERROR(@BalMsg, 16, 1);
            END

            INSERT INTO proj.TBL_STOCK_LEDGER
                (ItemId, TransDate, TransType, RefId, RefNo, QtyIn, QtyOut, UnitCost, IsJobStock, JobId, CreatedBy)
            VALUES
                (@ItemId, GETDATE(), 'RTV', @RtvId, @RtvNumber,
                 0, @StockQty, @StockUnitCost, @IsJobStockBit, NULLIF(@JobId,''), @PostedBy);

            IF NULLIF(@PoLineId, 0) IS NOT NULL
                UPDATE proj.TBL_PURCHASE_ORDER_LINE
                SET    ReceivedQty  = CASE WHEN ReceivedQty - @ReturnQty < 0 THEN 0 ELSE ReceivedQty - @ReturnQty END,
                       ModifiedBy   = @PostedBy,
                       ModifiedDate = GETDATE()
                WHERE  PoLineId = @PoLineId;

            IF NULLIF(@PoLineId, 0) IS NOT NULL
                EXEC proj.sp_RecalcPoLineStatus @PoLineId, @PostedBy;

            IF NULLIF(@PrLineId, 0) IS NOT NULL
                UPDATE bom
                SET    bom.BomReceivedQty = CASE WHEN bom.BomReceivedQty - @ReturnQty < 0 THEN 0 ELSE bom.BomReceivedQty - @ReturnQty END,
                       bom.BomStatus      = CASE
                           WHEN (bom.BomReceivedQty - @ReturnQty) >= bom.BomRequestedQty THEN 'FullyReceived'
                           WHEN (bom.BomReceivedQty - @ReturnQty)  > 0                   THEN 'PartialReceived'
                           WHEN bom.PoCreatedQty >= bom.BomRequestedQty                  THEN 'PORaised'
                           WHEN bom.PoCreatedQty  > 0                                    THEN 'POPartial'
                           WHEN bom.PrCreatedQty >= bom.BomRequestedQty                  THEN 'PRRaised'
                           WHEN bom.PrCreatedQty  > 0                                    THEN 'PRPartial'
                           ELSE 'Pending'
                       END,
                       bom.ModifiedBy     = @PostedBy,
                       bom.ModifiedDate   = GETDATE()
                FROM   proj.TBL_BOM_DETAILS bom
                JOIN   proj.TBL_PURCHASE_REQUEST_LINE prl ON prl.BomDetailId = bom.BomId
                WHERE  prl.PrLineId = @PrLineId AND prl.IsActive = 1;

            FETCH NEXT FROM cur INTO @ItemId, @ItemCode, @ReturnQty, @UnitCost, @UomId, @PoLineId, @PrLineId;
        END
        CLOSE cur; DEALLOCATE cur;

        UPDATE proj.TBL_RETURN_TO_VENDOR
        SET    Status       = 'Posted',
               PostReason   = @Reason,
               PostedBy     = @PostedBy,
               PostedDate   = GETDATE(),
               ModifiedBy   = @PostedBy,
               ModifiedDate = GETDATE()
        WHERE  RtvId = @RtvId;

        COMMIT;
        SELECT CAST(@RtvId AS NVARCHAR(20));

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        IF CURSOR_STATUS('local','cur') >= 0 BEGIN CLOSE cur; DEALLOCATE cur; END
        DECLARE @Msg NVARCHAR(2048) = ERROR_MESSAGE();
        RAISERROR(@Msg, 16, 1); RETURN;
    END CATCH
END;
GO

IF OBJECT_ID(N'[proj].[sp_PostRvApproval]') IS NOT NULL DROP PROCEDURE [proj].[sp_PostRvApproval];
GO

CREATE   PROCEDURE proj.sp_PostRvApproval
    @RvId       INT,
    @ApprovedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- Guard: the RV must carry a valid currency + rate before its payments post to jobs.
    DECLARE @CurrencyId INT, @Rate DECIMAL(18,6);
    SELECT @CurrencyId = CurrencyId, @Rate = ExchangeRate
    FROM proj.TBL_RECEIPT_VOUCHER WHERE RvId = @RvId;
    EXEC proj.sp_ValidateTxnCurrency @CurrencyId, @Rate, N'Receipt voucher';

    -- Refresh payments for every job the RV touches (covers revise -> re-approve).
    DECLARE @JobId NVARCHAR(50);
    DECLARE jc CURSOR LOCAL FAST_FORWARD FOR
        SELECT DISTINCT i.JobId
        FROM   proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
        JOIN   proj.TBL_INVOICE i ON i.InvoiceId = a.InvoiceId
        WHERE  a.RvId = @RvId AND a.IsActive = 1 AND NULLIF(i.JobId,'') IS NOT NULL;
    OPEN jc; FETCH NEXT FROM jc INTO @JobId;
    WHILE @@FETCH_STATUS = 0
    BEGIN EXEC proj.sp_RecalcJobPayments @JobId, @ApprovedBy; FETCH NEXT FROM jc INTO @JobId; END
    CLOSE jc; DEALLOCATE jc;
END
GO

IF OBJECT_ID(N'[proj].[sp_PostSubcontractReceipt]') IS NOT NULL DROP PROCEDURE [proj].[sp_PostSubcontractReceipt];
GO

CREATE PROCEDURE proj.sp_PostSubcontractReceipt
    @SubcontractReceiptId INT,
    @ActionBy             NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        DECLARE @Status        NVARCHAR(20);
        DECLARE @SubcontractId INT;
        DECLARE @ReceiptNo     NVARCHAR(30);
        DECLARE @ReceiptDate   DATE;
        DECLARE @ReceivedQty   DECIMAL(18,4);
        DECLARE @UnitCost      DECIMAL(18,4);
        DECLARE @OutputItemId  INT;
        DECLARE @JobId         NVARCHAR(50);
        DECLARE @SCStatus      NVARCHAR(20);
        DECLARE @OutputQty     DECIMAL(18,4);
        DECLARE @SourceJobId   NVARCHAR(50), @EffJobId NVARCHAR(50), @IsJobStk BIT;

        SELECT
            @Status        = r.Status,
            @SubcontractId = r.SubcontractId,
            @ReceiptNo     = r.ReceiptNo,
            @ReceiptDate   = r.ReceiptDate,
            @ReceivedQty   = r.ReceivedQty,
            @UnitCost      = r.UnitCost
        FROM proj.TBL_SUBCONTRACT_RECEIPT r
        WHERE r.SubcontractReceiptId = @SubcontractReceiptId AND r.IsActive = 1;

        IF @Status IS NULL
            RAISERROR('Subcontract receipt not found.', 16, 1);
        IF @Status <> 'Draft'
            RAISERROR('Only Draft receipts can be posted.', 16, 1);

        SELECT
            @OutputItemId = OutputItemId,
            @JobId        = JobId,
            @SCStatus     = Status,
            @OutputQty    = OutputQty
        FROM proj.TBL_SUBCONTRACT_ORDER
        WHERE SubcontractId = @SubcontractId AND IsActive = 1;

        IF @OutputItemId IS NULL
            RAISERROR('Subcontract order not found or output item not set.', 16, 1);
        IF @SCStatus NOT IN ('Approved','InProgress')
            RAISERROR('Subcontract order is not in a valid state to receive goods.', 16, 1);

        -- Derive in-house job via the output item's budget header.
        -- In-house receipts are store stock (IsJobStock=0); only QtyOnHand is updated.
        SET @SourceJobId = NULL;
        SELECT TOP 1 @SourceJobId = j.JobId
        FROM proj.TBL_ITEM it
        JOIN proj.TBL_JOB        j  ON j.BudgetCategoryId = it.BudgetCategoryId
        JOIN proj.TBL_JOBTYPE    jt ON jt.JobTypeId = j.JobTypeId AND ISNULL(jt.IsBudgetHeaderLinked,0) = 1
        JOIN proj.TBL_JOB_STATUS js ON js.JobStatusId = j.JobStatusId AND ISNULL(js.IsClosed,0) = 0
        WHERE it.ItemId = @OutputItemId AND it.BudgetCategoryId IS NOT NULL
        ORDER BY j.JobCreatedDate DESC;

        IF @SourceJobId IS NOT NULL
            SELECT @EffJobId = @SourceJobId, @IsJobStk = 0;  -- in-house: store stock
        ELSE
            SELECT @EffJobId = @JobId, @IsJobStk = CASE WHEN @JobId IS NOT NULL THEN 1 ELSE 0 END;

        BEGIN TRANSACTION;

            IF EXISTS (SELECT 1 FROM proj.TBL_STOCK_BALANCE WHERE ItemId = @OutputItemId)
            BEGIN
                DECLARE @OldQty    DECIMAL(18,4);
                DECLARE @OldCost   DECIMAL(18,4);
                SELECT @OldQty = QtyOnHand, @OldCost = AvgUnitCost
                FROM proj.TBL_STOCK_BALANCE WHERE ItemId = @OutputItemId;

                DECLARE @NewAvgCost DECIMAL(18,4) =
                    CASE WHEN (@OldQty + @ReceivedQty) = 0 THEN 0
                         ELSE ((@OldQty * @OldCost) + (@ReceivedQty * @UnitCost))
                              / (@OldQty + @ReceivedQty)
                    END;

                -- In-house: only QtyOnHand increases (QtyStoreStock auto-adjusts as computed column).
                -- Non-in-house job: QtyJobStock also increases.
                UPDATE proj.TBL_STOCK_BALANCE SET
                    QtyOnHand       = QtyOnHand + @ReceivedQty,
                    QtyJobStock     = ISNULL(QtyJobStock,0) + CASE WHEN @IsJobStk = 1 THEN @ReceivedQty ELSE 0 END,
                    AvgUnitCost     = @NewAvgCost,
                    LastReceiptDate = GETDATE(),
                    UpdatedDate     = GETDATE()
                WHERE ItemId = @OutputItemId;
            END
            ELSE
            BEGIN
                INSERT INTO proj.TBL_STOCK_BALANCE
                    (ItemId, QtyOnHand, QtyJobStock, AvgUnitCost, LastReceiptDate, UpdatedDate)
                VALUES
                    (@OutputItemId, @ReceivedQty,
                     CASE WHEN @IsJobStk = 1 THEN @ReceivedQty ELSE 0 END,
                     @UnitCost, GETDATE(), GETDATE());
            END

            INSERT INTO proj.TBL_STOCK_LEDGER
                (ItemId, TransDate, TransType, RefId, RefNo, QtyIn, QtyOut, UnitCost, IsJobStock, JobId, CreatedBy)
            VALUES
                (@OutputItemId, CAST(@ReceiptDate AS DATETIME), 'SC_IN',
                 @SubcontractReceiptId, @ReceiptNo,
                 @ReceivedQty, 0, @UnitCost,
                 @IsJobStk, @EffJobId, @ActionBy);

            UPDATE proj.TBL_SUBCONTRACT_RECEIPT SET
                Status       = 'Posted',
                ModifiedBy   = @ActionBy,
                ModifiedDate = GETDATE()
            WHERE SubcontractReceiptId = @SubcontractReceiptId;

            DECLARE @TotalReceived DECIMAL(18,4);
            SELECT @TotalReceived = ISNULL(SUM(ReceivedQty), 0)
            FROM proj.TBL_SUBCONTRACT_RECEIPT
            WHERE SubcontractId = @SubcontractId AND Status = 'Posted' AND IsActive = 1;

            UPDATE proj.TBL_SUBCONTRACT_ORDER SET
                Status       = CASE WHEN @TotalReceived >= @OutputQty THEN 'Received' ELSE 'InProgress' END,
                ModifiedBy   = @ActionBy,
                ModifiedDate = GETDATE()
            WHERE SubcontractId = @SubcontractId;

        COMMIT TRANSACTION;

        SELECT 'Posted' AS Status;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        DECLARE @ErrMsg NVARCHAR(MAX) = ERROR_MESSAGE();
        EXEC proj.sp_WriteLog @Action='sp_PostSubcontractReceipt', @Message=@ErrMsg, @UserId=@ActionBy;
        THROW;
    END CATCH
END;
GO

IF OBJECT_ID(N'[proj].[sp_PreviewDocNumber]') IS NOT NULL DROP PROCEDURE [proj].[sp_PreviewDocNumber];
GO

CREATE PROCEDURE proj.sp_PreviewDocNumber
    @DocTypeId NVARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @FullYear SMALLINT = YEAR(GETDATE());

    DECLARE @Prefix        NVARCHAR(20),
            @Suffix        NVARCHAR(20),
            @Separator     NCHAR(1),
            @IncYear       BIT,
            @YrDigits      TINYINT,
            @PadLen        TINYINT,
            @CurrentSeries INT,
            @StartSeries   INT,
            @ResetYearly   BIT,
            @CurrentYear   SMALLINT;

    SELECT
        @Prefix        = Prefix,
        @Suffix        = Suffix,
        @Separator     = Separator,
        @IncYear       = IncludeYear,
        @YrDigits      = YearDigits,
        @PadLen        = PadLength,
        @CurrentSeries = CurrentSeries,
        @StartSeries   = StartingSeries,
        @ResetYearly   = ResetYearly,
        @CurrentYear   = CurrentYear
    FROM proj.TBL_DOCUMENT_SERIES
    WHERE DocTypeId = @DocTypeId AND IsActive = 1;

    IF @Prefix IS NULL
    BEGIN
        SELECT NULL AS PreviewNumber, NULL AS NextSeries;
        RETURN;
    END

    -- Use the same year key logic as sp_GetNextDocNumber so reset detection matches
    DECLARE @ThisYear SMALLINT =
        CASE WHEN @YrDigits = 4
             THEN @FullYear
             ELSE CAST(RIGHT(CAST(@FullYear AS VARCHAR(4)), 2) AS SMALLINT)
        END;

    DECLARE @NextSeries INT =
        CASE WHEN @ResetYearly = 1
                  AND (@CurrentYear IS NULL OR @CurrentYear <> @ThisYear)
             THEN @StartSeries
             ELSE @CurrentSeries + 1
        END;

    DECLARE @YearStr  NVARCHAR(4)  = CASE WHEN @YrDigits = 4
                                          THEN CAST(@FullYear AS NVARCHAR(4))
                                          ELSE RIGHT(CAST(@FullYear AS NVARCHAR(4)), 2)
                                     END;
    DECLARE @NumStr   NVARCHAR(20) = RIGHT(REPLICATE('0', @PadLen) + CAST(@NextSeries AS NVARCHAR(20)), @PadLen);

    DECLARE @DocNumber NVARCHAR(50) =
        ISNULL(@Prefix, '') +
        CASE WHEN @IncYear = 1 THEN ISNULL(@Separator, '-') + @YearStr ELSE '' END +
        ISNULL(@Suffix, '') +
        ISNULL(@Separator, '-') + @NumStr;

    SELECT @DocNumber AS PreviewNumber, @NextSeries AS NextSeries;
END;
GO

IF OBJECT_ID(N'[proj].[sp_PreviewJobId]') IS NOT NULL DROP PROCEDURE [proj].[sp_PreviewJobId];
GO

CREATE PROCEDURE [PROJ].[sp_PreviewJobId]
    @JobTypeId NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE
        @Prefix             NVARCHAR(10),
        @Suffix             NVARCHAR(10),
        @CurrentSeries      INT,
        @StartingSeries     INT,
        @NextNumber         INT,
        @YearCode           NVARCHAR(2),
        @IsCostingRequired  BIT,
        @RequiresParentJob  BIT,
        @IsBudgetHeaderLinked BIT,
        @JobTypeName        NVARCHAR(100);

    SET @YearCode = RIGHT(CAST(YEAR(GETDATE()) AS NVARCHAR), 2);

    SELECT
        @Prefix            = PreFix,
        @Suffix            = Suffix,
        @CurrentSeries     = CurrentSeries,
        @StartingSeries    = CAST(StartingSeries AS INT),
        @IsCostingRequired = ISNULL(IsCostingRequired, 0),
        @RequiresParentJob = ISNULL(RequiresParentJob, 0),
        @IsBudgetHeaderLinked = ISNULL(IsBudgetHeaderLinked, 0),
        @JobTypeName       = JobTypeName
    FROM PROJ.TBL_JOBTYPE
    WHERE JobTypeId = @JobTypeId AND IsActive = 1;

    IF (@CurrentSeries IS NULL OR @CurrentSeries = 0)
        SET @NextNumber = @StartingSeries;
    ELSE
        SET @NextNumber = @CurrentSeries + 1;

    DECLARE @PreviewJobId NVARCHAR(100);
    SET @PreviewJobId =
        ISNULL(@Prefix, '') +
        @YearCode +
        ISNULL(@Suffix, '') + '-' +
        CAST(@NextNumber AS NVARCHAR);

    SELECT
        @PreviewJobId      AS PreviewJobId,
        @JobTypeName       AS JobTypeName,
        @IsCostingRequired AS IsCostingRequired,
        @RequiresParentJob AS RequiresParentJob,
        @IsBudgetHeaderLinked AS IsBudgetHeaderLinked,
        @NextNumber        AS NextSeries;
END
GO

IF OBJECT_ID(N'[proj].[sp_ProcessApproval]') IS NOT NULL DROP PROCEDURE [proj].[sp_ProcessApproval];
GO
CREATE PROCEDURE PROJ.sp_ProcessApproval
    @TransactionId INT,
    @Action        NVARCHAR(20),
    @ActionBy      INT,
    @ActionByName  NVARCHAR(100),
    @Remarks       NVARCHAR(500) = NULL,
    @OverrideBudget BIT          = 0
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF @Action NOT IN ('Approve','Reject','SendBack','Cancel')
        BEGIN
            SELECT @TransactionId AS TransactionId, NULL AS NewStatus, 0 AS IsComplete, 'Invalid action.' AS Message, NULL AS ModuleCode, NULL AS DocumentId;
            ROLLBACK; RETURN;
        END
        DECLARE @LogAction NVARCHAR(20) = CASE @Action WHEN 'Approve' THEN 'Approved' WHEN 'Reject' THEN 'Rejected' WHEN 'SendBack' THEN 'Returned' WHEN 'Cancel' THEN 'Cancelled' END;
        DECLARE @ModuleId INT, @ModuleCode NVARCHAR(20), @DocumentId INT, @PostApprovalSP NVARCHAR(200), @PolicyId INT,
                @CurrentStatus NVARCHAR(20), @CurrentLevelNo INT, @TotalLevels INT, @SubmittedBy NVARCHAR(100), @DocumentTable NVARCHAR(100),
                @DocumentIdCol NVARCHAR(50), @StatusColumn NVARCHAR(50), @ModifiedByCol NVARCHAR(50), @ModifiedDateCol NVARCHAR(50),
                @ApprovedStatus NVARCHAR(30), @RejectedStatus NVARCHAR(30), @CancelledStatus NVARCHAR(30);
        SELECT @ModuleId = t.ModuleId, @ModuleCode = m.ModuleCode, @DocumentId = t.DocumentId, @PostApprovalSP = m.PostApprovalSP,
               @PolicyId = t.PolicyId, @CurrentStatus = t.CurrentStatus, @CurrentLevelNo = t.CurrentLevelNo, @TotalLevels = t.TotalLevels,
               @SubmittedBy = t.SubmittedBy, @DocumentTable = m.DocumentTable, @DocumentIdCol = m.DocumentIdColumn,
               @StatusColumn = ISNULL(m.StatusColumn,'Status'), @ModifiedByCol = ISNULL(m.ModifiedByColumn,'ModifiedBy'),
               @ModifiedDateCol = ISNULL(m.ModifiedDateColumn,'ModifiedDate'), @ApprovedStatus = ISNULL(m.ApprovedStatus,'Approved'),
               @RejectedStatus = ISNULL(m.RejectedStatus,'Rejected'), @CancelledStatus = ISNULL(m.CancelledStatus,'Draft')
        FROM PROJ.TBL_APPROVAL_TRANSACTION t JOIN PROJ.TBL_APPROVAL_MODULE m ON m.ModuleId = t.ModuleId WHERE t.TransactionId = @TransactionId;
        IF @ModuleId IS NULL
        BEGIN
            SELECT @TransactionId AS TransactionId, NULL AS NewStatus, 0 AS IsComplete, 'Transaction not found.' AS Message, NULL AS ModuleCode, NULL AS DocumentId;
            ROLLBACK; RETURN;
        END
        IF @CurrentStatus IN ('Approved','Rejected','Cancelled','SentBack')
        BEGIN
            SELECT @TransactionId AS TransactionId, @CurrentStatus AS NewStatus, 1 AS IsComplete, 'Transaction is already complete.' AS Message, @ModuleCode AS ModuleCode, @DocumentId AS DocumentId;
            ROLLBACK; RETURN;
        END
        DECLARE @CurrentLevelId INT = NULL, @AllowSelfApproval BIT = 0;
        SELECT TOP 1 @CurrentLevelId = al.LevelId, @AllowSelfApproval = al.AllowSelfApproval
        FROM PROJ.TBL_APPROVAL_LEVEL al WHERE al.PolicyId = @PolicyId AND al.LevelNo = @CurrentLevelNo AND al.IsActive = 1
          AND (al.ApproverType = 'ANY' OR (al.ApproverType = 'Role' AND EXISTS (SELECT 1 FROM PROJ.TBL_USER_ROLES ur WHERE ur.UserId = @ActionBy AND ur.RoleId = al.ApproverId)) OR (al.ApproverType = 'User' AND al.ApproverId = @ActionBy))
        ORDER BY al.LevelId;
        IF @CurrentLevelId IS NULL
            SELECT TOP 1 @CurrentLevelId = al.LevelId, @AllowSelfApproval = al.AllowSelfApproval
            FROM PROJ.TBL_APPROVAL_LEVEL al WHERE al.PolicyId = @PolicyId AND al.LevelNo = @CurrentLevelNo AND al.IsActive = 1 ORDER BY al.LevelId;
        DECLARE @UserCanAct BIT = 0;
        IF @Action = 'Cancel' AND @ActionByName = @SubmittedBy SET @UserCanAct = 1;
        IF @UserCanAct = 0 AND EXISTS (SELECT 1 FROM PROJ.TBL_APPROVAL_LEVEL al WHERE al.PolicyId = @PolicyId AND al.LevelNo = @CurrentLevelNo AND al.IsActive = 1
              AND (al.ApproverType = 'ANY' OR (al.ApproverType = 'Role' AND EXISTS (SELECT 1 FROM PROJ.TBL_USER_ROLES ur WHERE ur.UserId = @ActionBy AND ur.RoleId = al.ApproverId)) OR (al.ApproverType = 'User' AND al.ApproverId = @ActionBy)))
            SET @UserCanAct = 1;
        IF @UserCanAct = 0 AND @Action <> 'Cancel'
            IF EXISTS (SELECT 1 FROM PROJ.TBL_APPROVAL_DELEGATE ad JOIN PROJ.TBL_APPROVAL_LEVEL al ON al.LevelId = ad.LevelId
                WHERE al.PolicyId = @PolicyId AND al.LevelNo = @CurrentLevelNo AND al.IsActive = 1 AND ad.DelegateUserId = @ActionBy AND ad.IsActive = 1 AND CAST(GETDATE() AS date) BETWEEN ad.FromDate AND ad.ToDate)
                SET @UserCanAct = 1;
        DECLARE @UserMaxLevel INT = NULL;
        IF @Action = 'Approve'
        BEGIN
            SELECT @UserMaxLevel = MAX(al.LevelNo) FROM PROJ.TBL_APPROVAL_LEVEL al WHERE al.PolicyId = @PolicyId AND al.IsActive = 1 AND al.LevelNo >= @CurrentLevelNo
               AND ((al.ApproverType = 'Role' AND EXISTS (SELECT 1 FROM PROJ.TBL_USER_ROLES ur WHERE ur.UserId = @ActionBy AND ur.RoleId = al.ApproverId)) OR (al.ApproverType = 'User' AND al.ApproverId = @ActionBy) OR al.ApproverType = 'ANY');
            IF @UserMaxLevel IS NOT NULL AND @UserMaxLevel > @CurrentLevelNo SET @UserCanAct = 1;
        END
        IF @UserCanAct = 1 AND @AllowSelfApproval = 0 AND @ActionByName = @SubmittedBy AND @Action IN ('Approve','Reject')
        BEGIN
            SELECT @TransactionId AS TransactionId, NULL AS NewStatus, 0 AS IsComplete, 'Self-approval is not permitted for this level.' AS Message, NULL AS ModuleCode, NULL AS DocumentId;
            ROLLBACK; RETURN;
        END
        IF @UserCanAct = 0
        BEGIN
            SELECT @TransactionId AS TransactionId, NULL AS NewStatus, 0 AS IsComplete, 'You do not have the required role to perform this action at level ' + CAST(@CurrentLevelNo AS NVARCHAR) + '.' AS Message, NULL AS ModuleCode, NULL AS DocumentId;
            ROLLBACK; RETURN;
        END
        -- PO budget guard — BASE currency (mirrors sp_GetPOBudgetCheck); bypassable via @OverrideBudget
        IF @Action = 'Approve' AND @ModuleCode = 'PO'
        BEGIN
            DECLARE @ApJobId NVARCHAR(50), @ApCategoryId INT, @ApPoTotalBase DECIMAL(18,2);
            SELECT @ApJobId = JobId, @ApCategoryId = ExpenseCategoryId, @ApPoTotalBase = ISNULL(TotalAmount, 0) * ISNULL(ExchangeRate, 1)
            FROM PROJ.TBL_PURCHASE_ORDER WHERE PoId = @DocumentId AND IsActive = 1;
            IF @ApJobId IS NOT NULL AND @ApCategoryId IS NOT NULL
            BEGIN
                DECLARE @ApJobRate DECIMAL(18,6) = ISNULL((SELECT JobExcRate FROM PROJ.TBL_JOB WHERE JobId = @ApJobId), 1);
                DECLARE @ApBudgeted DECIMAL(18,2) = 0, @ApBudgetExists BIT = 0;
                SELECT @ApBudgetExists = 1, @ApBudgeted = ISNULL(AmountInBaseCurrency, PROJ.fn_ToBase(ISNULL(BudgetedAmount, 0), ISNULL(ExchangeRate, @ApJobRate)))
                FROM PROJ.TBL_JOB_BUDGET WHERE JobId = @ApJobId AND CostCategoryId = @ApCategoryId AND IsCurrent = 1;
                IF @ApBudgetExists = 0
                BEGIN
                    SELECT @TransactionId AS TransactionId, NULL AS NewStatus, 0 AS IsComplete,
                           'Cannot approve: no approved budget line exists for the expense category on this job. Add a budget line first.' AS Message, @ModuleCode AS ModuleCode, @DocumentId AS DocumentId;
                    ROLLBACK; RETURN;
                END
                DECLARE @ApCommitted DECIMAL(18,2) = 0;
                SELECT @ApCommitted = ISNULL(SUM(PROJ.fn_ToBase(pol.OrderedQty * pol.UnitPrice, po.ExchangeRate)), 0)
                FROM PROJ.TBL_PURCHASE_ORDER po JOIN PROJ.TBL_PURCHASE_ORDER_LINE pol ON pol.PoId = po.PoId AND pol.IsActive = 1
                WHERE po.JobId = @ApJobId AND po.ExpenseCategoryId = @ApCategoryId AND po.Status != 'Cancelled' AND po.IsActive = 1 AND po.PoId != @DocumentId;
                IF (@ApCommitted + @ApPoTotalBase) > @ApBudgeted AND @OverrideBudget = 0
                BEGIN
                    DECLARE @ApBudMsg NVARCHAR(600) = 'Cannot approve: PO would exceed the budget for this expense category (base currency). '
                        + 'Budgeted: ' + FORMAT(@ApBudgeted,'N2') + ' | Already committed: ' + FORMAT(@ApCommitted,'N2')
                        + ' | This PO: ' + FORMAT(@ApPoTotalBase,'N2') + ' | Over by: ' + FORMAT(@ApCommitted+@ApPoTotalBase-@ApBudgeted,'N2');
                    SELECT @TransactionId AS TransactionId, NULL AS NewStatus, 0 AS IsComplete, @ApBudMsg AS Message, @ModuleCode AS ModuleCode, @DocumentId AS DocumentId;
                    ROLLBACK; RETURN;
                END
            END
        END
        DECLARE @Now DATETIME = GETDATE();
        DECLARE @NewStatus NVARCHAR(50);
        DECLARE @NewLevelNo INT = @CurrentLevelNo;
        DECLARE @IsComplete BIT = 0;
        DECLARE @FinalAction NVARCHAR(20) = NULL;
        DECLARE @CompletedDate DATETIME = NULL;
        IF @Action = 'Approve' AND @UserMaxLevel IS NOT NULL AND @UserMaxLevel > @CurrentLevelNo
        BEGIN
            DECLARE @LoopLvl INT = @CurrentLevelNo;
            WHILE @LoopLvl < @UserMaxLevel
            BEGIN
                DECLARE @LoopLvlId INT;
                SELECT TOP 1 @LoopLvlId = LevelId FROM PROJ.TBL_APPROVAL_LEVEL WHERE PolicyId = @PolicyId AND LevelNo = @LoopLvl AND IsActive = 1 ORDER BY LevelId;
                INSERT INTO PROJ.TBL_APPROVAL_LOG (TransactionId, LevelId, LevelNo, Action, ActionBy, ActionByName, ActionDate, Remarks, IsDelegated, DelegatedFromUserId, DelegatedFromName, IsTimedOut)
                VALUES (@TransactionId, @LoopLvlId, @LoopLvl, 'Approved', @ActionBy, @ActionByName, @Now, ISNULL(NULLIF(LTRIM(RTRIM(@Remarks)), ''), '(no remarks)') + ' [auto-approved by senior approver]', 0, NULL, NULL, 0);
                SET @LoopLvl += 1;
            END
            SET @CurrentLevelNo = @UserMaxLevel;
            SELECT TOP 1 @CurrentLevelId = al.LevelId FROM PROJ.TBL_APPROVAL_LEVEL al WHERE al.PolicyId = @PolicyId AND al.LevelNo = @UserMaxLevel AND al.IsActive = 1
              AND ((al.ApproverType = 'Role' AND EXISTS (SELECT 1 FROM PROJ.TBL_USER_ROLES ur WHERE ur.UserId = @ActionBy AND ur.RoleId = al.ApproverId)) OR (al.ApproverType = 'User' AND al.ApproverId = @ActionBy) OR al.ApproverType = 'ANY') ORDER BY al.LevelId;
            SET @NewLevelNo = @UserMaxLevel;
        END
        IF @Action = 'Approve'
        BEGIN
            IF @CurrentLevelNo >= @TotalLevels
            BEGIN SET @NewStatus = @ApprovedStatus; SET @IsComplete = 1; SET @FinalAction = 'Approved'; SET @CompletedDate = @Now; END
            ELSE
            BEGIN
                SET @NewLevelNo = @CurrentLevelNo + 1;
                SELECT TOP 1 @NewStatus = ISNULL(PendingStatus, 'PendingApproval') FROM PROJ.TBL_APPROVAL_LEVEL WHERE PolicyId = @PolicyId AND LevelNo = @NewLevelNo AND IsActive = 1 ORDER BY LevelId;
                IF @NewStatus IS NULL SET @NewStatus = 'PendingApproval';
            END
        END
        ELSE IF @Action = 'Reject'
        BEGIN SET @NewStatus = @RejectedStatus; SET @IsComplete = 1; SET @FinalAction = 'Rejected'; SET @CompletedDate = @Now; END
        ELSE IF @Action = 'SendBack'
        BEGIN
            IF @CurrentLevelNo <= 1
            BEGIN SET @NewStatus = @CancelledStatus; SET @IsComplete = 1; SET @FinalAction = 'SentBack'; SET @CompletedDate = @Now; SET @NewLevelNo = 1; END
            ELSE
            BEGIN
                SET @NewLevelNo = @CurrentLevelNo - 1;
                SELECT TOP 1 @NewStatus = ISNULL(PendingStatus, 'PendingApproval') FROM PROJ.TBL_APPROVAL_LEVEL WHERE PolicyId = @PolicyId AND LevelNo = @NewLevelNo AND IsActive = 1 ORDER BY LevelId;
                IF @NewStatus IS NULL SET @NewStatus = 'PendingApproval';
            END
        END
        ELSE IF @Action = 'Cancel'
        BEGIN SET @NewStatus = @CancelledStatus; SET @IsComplete = 1; SET @FinalAction = 'Cancelled'; SET @CompletedDate = @Now; END
        DECLARE @IsDelegated BIT = 0, @DelegatedFromUserId INT = NULL, @DelegatedFromName NVARCHAR(100) = NULL;
        SELECT TOP 1 @IsDelegated = 1, @DelegatedFromUserId = ad.OriginalUserId, @DelegatedFromName = ou.FullName
        FROM PROJ.TBL_APPROVAL_DELEGATE ad JOIN PROJ.TBL_USERS ou ON ou.UserId = ad.OriginalUserId
        WHERE ad.LevelId = @CurrentLevelId AND ad.DelegateUserId = @ActionBy AND ad.IsActive = 1 AND CAST(GETDATE() AS date) BETWEEN ad.FromDate AND ad.ToDate;
        INSERT INTO PROJ.TBL_APPROVAL_LOG (TransactionId, LevelId, LevelNo, Action, ActionBy, ActionByName, ActionDate, Remarks, IsDelegated, DelegatedFromUserId, DelegatedFromName, IsTimedOut)
        VALUES (@TransactionId, @CurrentLevelId, @CurrentLevelNo, @LogAction, @ActionBy, @ActionByName, @Now,
             CASE WHEN @OverrideBudget = 1 AND @Action = 'Approve' THEN ISNULL(NULLIF(LTRIM(RTRIM(@Remarks)),''),'(no remarks)') + ' [BUDGET OVERRIDE]' ELSE @Remarks END,
             @IsDelegated, @DelegatedFromUserId, @DelegatedFromName, 0);
        UPDATE PROJ.TBL_APPROVAL_TRANSACTION
        SET CurrentStatus = CASE WHEN @IsComplete = 1 THEN @FinalAction ELSE 'Pending' END, CurrentLevelNo = @NewLevelNo, FinalAction = @FinalAction,
            FinalActionBy = CASE WHEN @IsComplete = 1 THEN @ActionByName ELSE NULL END, FinalRemarks = CASE WHEN @IsComplete = 1 THEN @Remarks ELSE NULL END,
            CompletedDate = @CompletedDate, ModifiedBy = @ActionByName, ModifiedDate = @Now WHERE TransactionId = @TransactionId;
        DECLARE @Sql NVARCHAR(1000) = N'UPDATE PROJ.' + QUOTENAME(@DocumentTable) + N' SET ' + QUOTENAME(@StatusColumn) + N' = @NewSt' + N', ' + QUOTENAME(@ModifiedByCol) + N' = @Who' + N', ' + QUOTENAME(@ModifiedDateCol) + N' = @When' + N' WHERE ' + QUOTENAME(@DocumentIdCol) + N' = @DocId';
        EXEC sp_executesql @Sql, N'@NewSt NVARCHAR(50), @Who NVARCHAR(100), @When DATETIME, @DocId INT', @NewStatus, @ActionByName, @Now, @DocumentId;
        
        -- Stamp ApprovedBy / ApprovedDate on the document when fully approved (if columns exist)
        IF @IsComplete = 1 AND @FinalAction = 'Approved'
           AND COL_LENGTH('PROJ.' + @DocumentTable, 'ApprovedBy') IS NOT NULL
        BEGIN
            DECLARE @ApStampSql NVARCHAR(600) = N'UPDATE PROJ.' + QUOTENAME(@DocumentTable)
                + N' SET ApprovedBy = @Who'
                + CASE WHEN COL_LENGTH('PROJ.' + @DocumentTable, 'ApprovedDate') IS NOT NULL
                       THEN N', ApprovedDate = @When' ELSE N'' END
                + N' WHERE ' + QUOTENAME(@DocumentIdCol) + N' = @DocId';
            EXEC sp_executesql @ApStampSql, N'@Who NVARCHAR(100), @When DATETIME, @DocId INT', @ActionByName, @Now, @DocumentId;
        END
        IF @IsComplete = 1 AND @FinalAction = 'Approved' AND @PostApprovalSP IS NOT NULL
        BEGIN
            DECLARE @HookSql NVARCHAR(500);
            IF @OverrideBudget = 1 AND @ModuleCode = 'MH' SET @HookSql = N'EXEC ' + @PostApprovalSP + N' @DocId, @By, @OverrideBudget = 1';
            ELSE SET @HookSql = N'EXEC ' + @PostApprovalSP + N' @DocId, @By';
            EXEC sp_executesql @HookSql, N'@DocId INT, @By NVARCHAR(100)', @DocumentId, @ActionByName;
        END
        COMMIT TRANSACTION;
        SELECT @TransactionId AS TransactionId, @NewStatus AS NewStatus, @IsComplete AS IsComplete, 'Action processed successfully.' AS Message, @ModuleCode AS ModuleCode, @DocumentId AS DocumentId;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        SELECT @TransactionId AS TransactionId, NULL AS NewStatus, 0 AS IsComplete, ERROR_MESSAGE() AS Message, NULL AS ModuleCode, NULL AS DocumentId;
    END CATCH
END;
GO

IF OBJECT_ID(N'[proj].[sp_ReassignMOMTask]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReassignMOMTask];
GO
CREATE   PROCEDURE PROJ.sp_ReassignMOMTask
    @MomTaskId  INT,
    @ToUser     NVARCHAR(100),
    @Remarks    NVARCHAR(MAX) = NULL,
    @ActionBy   NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @FromUser NVARCHAR(100), @OldStatus NVARCHAR(20), @CreatedBy NVARCHAR(100);
    SELECT @FromUser = AssignedTo, @OldStatus = Status, @CreatedBy = CreatedBy
    FROM PROJ.TBL_MOM_TASK WHERE MomTaskId = @MomTaskId AND IsActive = 1;

    -- Task must exist
    IF @OldStatus IS NULL
    BEGIN
        SELECT 'NOTFOUND';
        RETURN;
    END

    -- Only the assignee or the assigner may act
    IF @ActionBy <> @FromUser AND @ActionBy <> @CreatedBy
    BEGIN
        SELECT 'UNAUTHORIZED';
        RETURN;
    END

    -- A closed task cannot be reassigned
    IF @OldStatus = 'Closed'
    BEGIN
        SELECT 'INVALID';
        RETURN;
    END

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE PROJ.TBL_MOM_TASK
        SET AssignedTo   = @ToUser,
            Status       = 'Reassigned',
            ModifiedBy   = @ActionBy,
            ModifiedDate = GETDATE()
        WHERE MomTaskId = @MomTaskId;

        INSERT INTO PROJ.TBL_MOM_TASK_LOG (MomTaskId, Action, FromUser, ToUser, OldStatus, NewStatus, Remarks, ActionBy, ActionDate)
        VALUES (@MomTaskId, 'Reassigned', @FromUser, @ToUser, @OldStatus, 'Reassigned', @Remarks, @ActionBy, GETDATE());

        COMMIT;
        SELECT CAST(@MomTaskId AS NVARCHAR(20));
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        THROW;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_RecalcJobCredits]') IS NOT NULL DROP PROCEDURE [proj].[sp_RecalcJobCredits];
GO

CREATE   PROCEDURE proj.sp_RecalcJobCredits
    @JobId      NVARCHAR(50),
    @ModifiedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF NULLIF(@JobId, '') IS NULL RETURN;

    -- AllocatedAmount is stored in base currency (AED) — no conversion, same as RV payments.
    DECLARE @Total DECIMAL(18,2);
    SELECT @Total = ISNULL(SUM(a.AllocatedAmount), 0)
    FROM   proj.TBL_CREDIT_NOTE_ALLOCATION a
    JOIN   proj.TBL_CREDIT_NOTE cn ON cn.CnId      = a.CnId
    JOIN   proj.TBL_INVOICE     i  ON i.InvoiceId  = a.InvoiceId
    WHERE  i.JobId    = @JobId
      AND  a.IsActive = 1
      AND  cn.IsActive = 1
      AND  cn.Status  = 'Approved';

    IF EXISTS (SELECT 1 FROM proj.TBL_JOB_FINANCE WHERE JobId = @JobId)
        UPDATE proj.TBL_JOB_FINANCE
        SET    TotalCredit  = @Total,
               ModifiedBy   = ISNULL(@ModifiedBy, ModifiedBy),
               ModifiedDate = GETDATE()
        WHERE  JobId = @JobId;
    ELSE
        INSERT INTO proj.TBL_JOB_FINANCE (JobId, OrderValue, TotalCredit, CreatedBy, CreatedDate)
        VALUES (@JobId, 0, @Total, ISNULL(@ModifiedBy, 'system'), GETDATE());
END
GO

IF OBJECT_ID(N'[proj].[sp_RecalcJobInvoicing]') IS NOT NULL DROP PROCEDURE [proj].[sp_RecalcJobInvoicing];
GO

CREATE   PROCEDURE proj.sp_RecalcJobInvoicing
    @JobId      NVARCHAR(50),
    @ModifiedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF NULLIF(@JobId, '') IS NULL RETURN;

    -- Sum of all approved (Confirmed) invoices on this job, converted to base currency
    DECLARE @Total DECIMAL(18,2);
    SELECT @Total = ISNULL(SUM(TotalAmount * ISNULL(ExchangeRate, 1)), 0)
    FROM   proj.TBL_INVOICE
    WHERE  JobId = @JobId AND Status = 'Confirmed' AND IsActive = 1;

    IF EXISTS (SELECT 1 FROM proj.TBL_JOB_FINANCE WHERE JobId = @JobId)
        UPDATE proj.TBL_JOB_FINANCE
        SET    TotalInvoicing = @Total,
               ModifiedBy     = ISNULL(@ModifiedBy, ModifiedBy),
               ModifiedDate   = GETDATE()
        WHERE  JobId = @JobId;
    ELSE
        INSERT INTO proj.TBL_JOB_FINANCE (JobId, OrderValue, TotalInvoicing, CreatedBy, CreatedDate)
        VALUES (@JobId, 0, @Total, ISNULL(@ModifiedBy, 'system'), GETDATE());
END
GO

IF OBJECT_ID(N'[proj].[sp_RecalcJobPayments]') IS NOT NULL DROP PROCEDURE [proj].[sp_RecalcJobPayments];
GO

-- AllocatedAmount rows are now stored in base currency (AED).
-- Remove the × ExchangeRate multiplication — it was double-converting.
CREATE PROCEDURE proj.sp_RecalcJobPayments
    @JobId      NVARCHAR(50),
    @ModifiedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF NULLIF(@JobId, '') IS NULL RETURN;

    -- AllocatedAmount is stored in base/invoice currency (AED) — no conversion needed.
    DECLARE @Total DECIMAL(18,2);
    SELECT @Total = ISNULL(SUM(a.AllocatedAmount), 0)
    FROM   proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
    JOIN   proj.TBL_RECEIPT_VOUCHER            rv ON rv.RvId      = a.RvId
    JOIN   proj.TBL_INVOICE                    i  ON i.InvoiceId  = a.InvoiceId
    WHERE  i.JobId    = @JobId
      AND  a.IsActive = 1
      AND  rv.IsActive = 1
      AND  rv.Status  = 'Approved';

    IF EXISTS (SELECT 1 FROM proj.TBL_JOB_FINANCE WHERE JobId = @JobId)
        UPDATE proj.TBL_JOB_FINANCE
        SET    TotalPayments = @Total,
               ModifiedBy    = ISNULL(@ModifiedBy, ModifiedBy),
               ModifiedDate  = GETDATE()
        WHERE  JobId = @JobId;
    ELSE
        INSERT INTO proj.TBL_JOB_FINANCE
            (JobId, OrderValue, TotalPayments, CreatedBy, CreatedDate)
        VALUES (@JobId, 0, @Total, ISNULL(@ModifiedBy, 'system'), GETDATE());
END
GO

IF OBJECT_ID(N'[proj].[sp_RecalcPoLineStatus]') IS NOT NULL DROP PROCEDURE [proj].[sp_RecalcPoLineStatus];
GO
CREATE   PROCEDURE proj.sp_RecalcPoLineStatus
    @PoLineId INT,
    @ChangedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @PoId INT;
    SELECT @PoId = PoId FROM proj.TBL_PURCHASE_ORDER_LINE WHERE PoLineId = @PoLineId AND IsActive = 1;
    IF @PoId IS NULL RETURN;

    UPDATE proj.TBL_PURCHASE_ORDER_LINE
    SET LineStatus = CASE WHEN ISNULL(ReceivedQty,0) <= 0 THEN 'Open'
                          WHEN ISNULL(ReceivedQty,0) >= OrderedQty THEN 'Received'
                          ELSE 'Partial' END,
        ModifiedBy = ISNULL(@ChangedBy, ModifiedBy), ModifiedDate = GETDATE()
    WHERE PoLineId = @PoLineId AND LineStatus NOT IN ('Closed','Cancelled');

    UPDATE po
    SET po.Status = CASE
            WHEN NOT EXISTS (SELECT 1 FROM proj.TBL_PURCHASE_ORDER_LINE l
                             WHERE l.PoId=@PoId AND l.IsActive=1 AND l.LineStatus NOT IN ('Received','Closed','Cancelled'))
                 AND EXISTS (SELECT 1 FROM proj.TBL_PURCHASE_ORDER_LINE l
                             WHERE l.PoId=@PoId AND l.IsActive=1 AND l.LineStatus='Received') THEN 'Received'
            WHEN EXISTS (SELECT 1 FROM proj.TBL_PURCHASE_ORDER_LINE l
                         WHERE l.PoId=@PoId AND l.IsActive=1 AND ISNULL(l.ReceivedQty,0) > 0) THEN 'Partial'
            WHEN po.Status IN ('Partial','Received') THEN 'Approved'
            ELSE po.Status END,
        po.ModifiedBy = ISNULL(@ChangedBy, po.ModifiedBy), po.ModifiedDate = GETDATE()
    FROM proj.TBL_PURCHASE_ORDER po
    WHERE po.PoId = @PoId AND po.Status NOT IN ('Cancelled','Closed','Draft','Hold');
END
GO

IF OBJECT_ID(N'[proj].[sp_RecalcPrStatus]') IS NOT NULL DROP PROCEDURE [proj].[sp_RecalcPrStatus];
GO

CREATE PROCEDURE PROJ.sp_RecalcPrStatus
    @PrLineId  INT,
    @ChangedBy NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @PrId INT;
    SELECT @PrId = PrId FROM PROJ.TBL_PURCHASE_REQUEST_LINE
    WHERE PrLineId = @PrLineId AND IsActive = 1;

    IF @PrId IS NULL RETURN;

    -- Recalculate this line's status
    UPDATE PROJ.TBL_PURCHASE_REQUEST_LINE
    SET    LineStatus    = CASE
               WHEN ISNULL(PoCreatedQty,0) >= RequiredQty AND RequiredQty > 0 THEN 'Ordered'
               WHEN ISNULL(PoCreatedQty,0)  > 0                               THEN 'Partial'
               ELSE 'Open'
           END,
           ModifiedBy    = @ChangedBy,
           ModifiedDate  = GETDATE()
    WHERE  PrLineId   = @PrLineId
      AND  LineStatus NOT IN ('Closed','Cancelled');

    -- Recalculate PR header status
    DECLARE @PrStatus NVARCHAR(30);
    SELECT @PrStatus = Status FROM PROJ.TBL_PURCHASE_REQUEST WHERE PrId = @PrId;

    IF @PrStatus NOT IN ('Draft','Cancelled','Closed','Rejected')
    BEGIN
        UPDATE PROJ.TBL_PURCHASE_REQUEST
        SET    Status = CASE
                   -- All active lines are fully ordered / closed / cancelled
                   -- AND at least one line is actually 'Ordered' (not all-Cancelled)
                   WHEN NOT EXISTS (
                       SELECT 1 FROM PROJ.TBL_PURCHASE_REQUEST_LINE
                       WHERE PrId = @PrId AND IsActive = 1
                         AND LineStatus NOT IN ('Ordered','Closed','Cancelled')
                   ) AND EXISTS (
                       SELECT 1 FROM PROJ.TBL_PURCHASE_REQUEST_LINE
                       WHERE PrId = @PrId AND IsActive = 1
                         AND LineStatus = 'Ordered'
                   ) THEN 'Ordered'
                   -- At least one line has some PO qty
                   WHEN EXISTS (
                       SELECT 1 FROM PROJ.TBL_PURCHASE_REQUEST_LINE
                       WHERE PrId = @PrId AND IsActive = 1 AND ISNULL(PoCreatedQty,0) > 0
                   ) THEN 'Partial'
                   -- No lines have any PO qty — revert to Approved if we were Partial/Ordered
                   WHEN @PrStatus IN ('Partial','Ordered') THEN 'Approved'
                   ELSE @PrStatus
               END,
               ModifiedBy   = @ChangedBy,
               ModifiedDate = GETDATE()
        WHERE  PrId = @PrId;
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_ReleasePO]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReleasePO];
GO

CREATE PROCEDURE proj.sp_ReleasePO
    @PoId       INT,
    @ReleasedBy NVARCHAR(100),
    @Reason     NVARCHAR(500) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CurrentStatus NVARCHAR(30);
    DECLARE @PrevStatus    NVARCHAR(30);

    SELECT @CurrentStatus = Status,
           @PrevStatus    = StatusBeforeHold
    FROM proj.TBL_PURCHASE_ORDER
    WHERE PoId = @PoId AND IsActive = 1;

    IF @CurrentStatus IS NULL
        RAISERROR('Purchase Order not found or is inactive.', 16, 1);

    IF @CurrentStatus <> 'Hold'
        RAISERROR('This Purchase Order is not currently on hold.', 16, 1);

    DECLARE @RestoreStatus NVARCHAR(30) = ISNULL(NULLIF(@PrevStatus,''), 'Approved');

    UPDATE proj.TBL_PURCHASE_ORDER
    SET Status           = @RestoreStatus,
        StatusBeforeHold = NULL,
        HoldBy           = NULL,
        HoldDate         = NULL,
        HoldReason       = NULL,
        ModifiedBy       = @ReleasedBy,
        ModifiedDate     = GETDATE()
    WHERE PoId = @PoId AND IsActive = 1;

    -- Log the release with reason
    INSERT INTO proj.TBL_PO_HOLD_LOG (PoId, Action, Reason, PreviousStatus, ActionBy, ActionDate)
    VALUES (@PoId, 'Release', @Reason, 'Hold', @ReleasedBy, GETDATE());

    SELECT @PoId AS PoId;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReorderBomDetails]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReorderBomDetails];
GO

CREATE PROCEDURE proj.sp_ReorderBomDetails
    @BomHeaderId INT,
    @OrderJson   NVARCHAR(MAX),   -- [{bomId, sortOrder}]
    @ModifiedBy  NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE d
    SET    d.SortOrder    = j.sortOrder,
           d.ModifiedBy   = @ModifiedBy,
           d.ModifiedDate = GETDATE()
    FROM   proj.TBL_BOM_DETAILS d
    JOIN   OPENJSON(@OrderJson)
           WITH (bomId INT '$.bomId', sortOrder INT '$.sortOrder') j
           ON j.bomId = d.BomId
    WHERE  d.BomHeaderId = @BomHeaderId
      AND  d.IsActive    = 1;

    SELECT @@ROWCOUNT AS Updated;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportBOM]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportBOM];
GO
CREATE   PROCEDURE proj.sp_ReportBOM
    @DateFrom   DATE          = NULL,
    @DateTo     DATE          = NULL,
    @JobId      NVARCHAR(50)  = NULL,
    @JobTypeId  NVARCHAR(50)  = NULL,
    @BomStatus  NVARCHAR(50)  = NULL,
    @CreatedBy  NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        b.BomHeaderId,
        b.JobId,
        b.BomDate,
        b.BomVersion,
        b.BomStatus,
        b.TotalBomValue,
        b.BomApprovedBy,
        b.BomApprovedDate,
        b.CreatedBy,
        b.CreatedDate,
        j.CustomerName,
        j.ProjectName,
        j.JobTypeName,
        j.CurrencySymbol,
        j.JobExcRate,
        j.JobStatusName,
        ISNULL(lc.LineCount, 0) AS LineCount
    FROM proj.TBL_BOM_HEADER b
    LEFT JOIN proj.VW_JOB j ON j.JobId = b.JobId
    OUTER APPLY (
        SELECT COUNT(*) AS LineCount
        FROM proj.TBL_BOM_DETAILS d
        WHERE d.BomHeaderId = b.BomHeaderId AND d.IsActive = 1
    ) lc
    WHERE b.IsActive = 1
      AND (@DateFrom  IS NULL OR CAST(b.BomDate AS DATE) >= @DateFrom)
      AND (@DateTo    IS NULL OR CAST(b.BomDate AS DATE) <= @DateTo)
      AND (@JobId     IS NULL OR b.JobId     LIKE '%' + @JobId + '%')
      AND (@JobTypeId IS NULL OR b.JobTypeId = @JobTypeId)
      AND (@BomStatus IS NULL OR b.BomStatus = @BomStatus)
      AND (@CreatedBy IS NULL OR b.CreatedBy LIKE '%' + @CreatedBy + '%')
    ORDER BY b.BomDate DESC, b.JobId, b.BomVersion DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportCreditNotes]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportCreditNotes];
GO

CREATE   PROCEDURE proj.sp_ReportCreditNotes
    @DateFrom   DATE          = NULL,
    @DateTo     DATE          = NULL,
    @CustomerId INT           = NULL,
    @Status     NVARCHAR(50)  = NULL,
    @CreditType NVARCHAR(50)  = NULL,
    @CreatedBy  NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @BaseCcy NVARCHAR(10) = (SELECT ShortName FROM proj.TBL_CURRENCY WHERE IsBaseCurrency=1);

    SELECT
        cn.CnId,
        cn.CnNumber,
        cn.CnDate,
        cn.CustomerId,
        c.CustomerName,
        cur.ShortName                                               AS CurrencyShort,
        ISNULL(cn.ExchangeRate, 1)                                 AS ExchangeRate,
        @BaseCcy                                                   AS BaseCurrency,
        cn.CreditType,
        cn.CreditAmount,
        cn.CreditAmount * ISNULL(cn.ExchangeRate, 1)               AS CreditAmountBase,
        cn.AllocatedAmount,
        cn.AllocatedAmount * ISNULL(cn.ExchangeRate, 1)            AS AllocatedBase,
        (cn.CreditAmount - ISNULL(cn.AllocatedAmount, 0))          AS UnallocatedAmount,
        (cn.CreditAmount - ISNULL(cn.AllocatedAmount, 0))
            * ISNULL(cn.ExchangeRate, 1)                           AS UnallocatedBase,
        cn.Status,
        cn.Reason,
        cn.CreatedBy,
        cn.CreatedDate
    FROM proj.TBL_CREDIT_NOTE cn
    LEFT JOIN proj.TBL_CUSTOMER c   ON c.CustomerId   = cn.CustomerId
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = cn.CurrencyId
    WHERE cn.IsActive = 1
      AND (@DateFrom   IS NULL OR cn.CnDate     >= @DateFrom)
      AND (@DateTo     IS NULL OR cn.CnDate     <= @DateTo)
      AND (@CustomerId IS NULL OR cn.CustomerId  = @CustomerId)
      AND (@Status     IS NULL OR cn.Status      = @Status)
      AND (@CreditType IS NULL OR cn.CreditType  = @CreditType)
      AND (@CreatedBy  IS NULL OR cn.CreatedBy   = @CreatedBy)
    ORDER BY cn.CnDate DESC, cn.CnId DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportDebitNotes]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportDebitNotes];
