CREATE   PROCEDURE proj.sp_ReportDebitNotes
    @DateFrom   DATE          = NULL,
    @DateTo     DATE          = NULL,
    @SupplierId INT           = NULL,
    @Status     NVARCHAR(50)  = NULL,
    @DebitType  NVARCHAR(50)  = NULL,
    @CreatedBy  NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @BaseCcy NVARCHAR(10) = (SELECT ShortName FROM proj.TBL_CURRENCY WHERE IsBaseCurrency=1);

    SELECT
        dn.DnId,
        dn.DnNumber,
        dn.DnDate,
        dn.SupplierId,
        s.SupplierName,
        cur.ShortName                                               AS CurrencyShort,
        ISNULL(dn.ExchangeRate, 1)                                 AS ExchangeRate,
        @BaseCcy                                                   AS BaseCurrency,
        dn.DebitType,
        dn.DebitAmount,
        dn.DebitAmount * ISNULL(dn.ExchangeRate, 1)                AS DebitAmountBase,
        dn.AllocatedAmount,
        dn.AllocatedAmount * ISNULL(dn.ExchangeRate, 1)            AS AllocatedBase,
        (dn.DebitAmount - ISNULL(dn.AllocatedAmount, 0))           AS UnallocatedAmount,
        (dn.DebitAmount - ISNULL(dn.AllocatedAmount, 0))
            * ISNULL(dn.ExchangeRate, 1)                           AS UnallocatedBase,
        dn.Status,
        dn.Reason,
        dn.CreatedBy,
        dn.CreatedDate
    FROM proj.TBL_DEBIT_NOTE dn
    LEFT JOIN proj.TBL_SUPPLIER s   ON s.SupplierId   = dn.SupplierId
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = dn.CurrencyId
    WHERE dn.IsActive = 1
      AND (@DateFrom   IS NULL OR dn.DnDate     >= @DateFrom)
      AND (@DateTo     IS NULL OR dn.DnDate     <= @DateTo)
      AND (@SupplierId IS NULL OR dn.SupplierId  = @SupplierId)
      AND (@Status     IS NULL OR dn.Status      = @Status)
      AND (@DebitType  IS NULL OR dn.DebitType   = @DebitType)
      AND (@CreatedBy  IS NULL OR dn.CreatedBy   = @CreatedBy)
    ORDER BY dn.DnDate DESC, dn.DnId DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportGRNs]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportGRNs];
GO

-- ── GRN REPORT ──────────────────────────────────────────────────────────
CREATE   PROCEDURE proj.sp_ReportGRNs
    @DateFrom   DATE          = NULL,
    @DateTo     DATE          = NULL,
    @SupplierId INT           = NULL,
    @JobId      NVARCHAR(50)  = NULL,
    @Status     NVARCHAR(50)  = NULL,
    @CreatedBy  NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        g.GrnId,
        g.GrnNumber,
        CONVERT(DATE, g.GrnDate)        AS GrnDate,
        g.SupplierId,
        g.ReceivedFrom                  AS VendorName,
        g.JobId,
        j.ProjectName                   AS JobTitle,
        g.Status,
        g.DoNo,
        g.InvoiceNo,
        g.TotalAmount,
        cur.ShortName                   AS CurrencyShort,
        g.ReceivedBy,
        g.CreatedBy,
        g.CreatedDate,
        po.PoNumber,
        (SELECT COUNT(*) FROM proj.TBL_GRN_DETAIL d
         WHERE d.GrnId = g.GrnId AND d.IsActive = 1)  AS LineCount
    FROM proj.TBL_GRN_HEADER g
    LEFT JOIN proj.TBL_PURCHASE_ORDER po ON po.PoId = g.PoId AND po.IsActive = 1
    LEFT JOIN proj.TBL_CURRENCY cur      ON cur.CurrencyId = g.CurrencyId
    LEFT JOIN proj.TBL_JOB j             ON j.JobId = g.JobId
    WHERE g.IsActive = 1
      AND (@DateFrom   IS NULL OR CONVERT(DATE, g.GrnDate) >= @DateFrom)
      AND (@DateTo     IS NULL OR CONVERT(DATE, g.GrnDate) <= @DateTo)
      AND (@SupplierId IS NULL OR g.SupplierId = @SupplierId)
      AND (@JobId      IS NULL OR g.JobId = @JobId)
      AND (@Status     IS NULL OR g.Status = @Status)
      AND (@CreatedBy  IS NULL OR g.CreatedBy LIKE '%' + @CreatedBy + '%')
    ORDER BY g.GrnDate DESC, g.GrnNumber;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportGRNUnregs]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportGRNUnregs];
