CREATE   PROCEDURE proj.sp_ReportGRNUnregs
    @DateFrom    DATE          = NULL,
    @DateTo      DATE          = NULL,
    @SupplierId  INT           = NULL,
    @JobId       NVARCHAR(50)  = NULL,
    @CancelledBy NVARCHAR(100) = NULL,
    @CreatedBy   NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        g.GrnId,
        g.GrnNumber,
        g.GrnDate,
        g.SupplierId,
        s.SupplierName,
        g.JobId,
        j.ProjectName     AS JobTitle,
        po.PoNumber,
        g.TotalAmount,
        cur.ShortName     AS CurrencyShort,
        g.DoNo,
        g.InvoiceNo,
        g.CancelledBy,
        g.CancelledDate,
        g.CancelReason,
        g.CreatedBy,
        g.CreatedDate
    FROM proj.TBL_GRN_HEADER g
    LEFT JOIN proj.TBL_SUPPLIER         s   ON s.SupplierId   = g.SupplierId
    LEFT JOIN proj.TBL_PURCHASE_ORDER   po  ON po.PoId        = g.PoId
    LEFT JOIN proj.TBL_CURRENCY         cur ON cur.CurrencyId = g.CurrencyId
    LEFT JOIN proj.TBL_JOB              j   ON j.JobId        = g.JobId
    WHERE
        g.Status       = 'Cancelled'
        AND g.CancelledBy IS NOT NULL
        AND (@DateFrom    IS NULL OR CAST(g.CancelledDate AS DATE) >= @DateFrom)
        AND (@DateTo      IS NULL OR CAST(g.CancelledDate AS DATE) <= @DateTo)
        AND (@SupplierId  IS NULL OR g.SupplierId  = @SupplierId)
        AND (@JobId       IS NULL OR g.JobId        = @JobId)
        AND (@CancelledBy IS NULL OR g.CancelledBy  = @CancelledBy)
        AND (@CreatedBy   IS NULL OR g.CreatedBy    = @CreatedBy)
    ORDER BY g.CancelledDate DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportInHouseStock]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportInHouseStock];
GO
-- sp_ReportInHouseStock: in-house entries are now IsJobStock=0
CREATE PROCEDURE proj.sp_ReportInHouseStock
    @JobId NVARCHAR(50) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        l.JobId AS InHouseJobId,
        j.ProjectName,
        ec.CategoryName AS BudgetHeader,
        l.ItemId, i.ItemCode, i.ItemName,
        SUM(CASE WHEN l.TransType = 'RECEIPT' THEN l.QtyIn ELSE 0 END) AS Purchased,
        SUM(l.QtyOut)                                                    AS Issued,
        SUM(l.QtyIn - l.QtyOut)                                         AS OnHand,
        SUM(l.QtyIn * l.UnitCost - l.QtyOut * l.UnitCost)               AS OnHandValue
    FROM proj.TBL_STOCK_LEDGER l
    JOIN proj.TBL_JOB        j  ON j.JobId      = l.JobId
    JOIN proj.TBL_JOBTYPE    jt ON jt.JobTypeId = j.JobTypeId AND ISNULL(jt.IsBudgetHeaderLinked,0) = 1
    LEFT JOIN proj.TBL_JOB_EXPENSE_CATEGORY ec ON ec.ExpenseCategoryId = j.BudgetCategoryId
    LEFT JOIN proj.TBL_ITEM i ON i.ItemId = l.ItemId
    WHERE l.IsJobStock = 0
      AND l.JobId IS NOT NULL
      AND (@JobId IS NULL OR l.JobId = @JobId)
    GROUP BY l.JobId, j.ProjectName, ec.CategoryName, l.ItemId, i.ItemCode, i.ItemName
    HAVING SUM(CASE WHEN l.TransType = 'RECEIPT' THEN l.QtyIn ELSE 0 END) > 0
        OR SUM(l.QtyIn - l.QtyOut) <> 0
    ORDER BY j.ProjectName, i.ItemCode;
END;
GO

IF OBJECT_ID(N'[proj].[sp_ReportInventoryGRN]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportInventoryGRN];
GO
CREATE   PROCEDURE proj.sp_ReportInventoryGRN
    @DateFrom    DATE          = NULL,
    @DateTo      DATE          = NULL,
    @Status      NVARCHAR(50)  = NULL,
    @ReceiptType NVARCHAR(20)  = NULL,
    @JobId       NVARCHAR(50)  = NULL,
    @CreatedBy   NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        r.ReceiptId,
        r.ReceiptNo,
        r.ReceiptDate,
        r.ReceiptType,
        r.JobId,
        r.SupplierName,
        r.PoNumber,
        r.SupplierRef,
        r.Status,
        r.Notes,
        r.CreatedBy,
        r.CreatedDate,
        COUNT(l.ReceiptLineId)                          AS LineCount,
        ISNULL(SUM(l.Qty * l.UnitCost), 0)             AS TotalCost
    FROM  proj.TBL_STOCK_RECEIPT r
    LEFT JOIN proj.TBL_STOCK_RECEIPT_LINE l
           ON l.ReceiptId = r.ReceiptId AND ISNULL(l.IsActive, 1) = 1
    WHERE r.IsActive = 1
      AND (@DateFrom    IS NULL OR r.ReceiptDate >= @DateFrom)
      AND (@DateTo      IS NULL OR r.ReceiptDate <= @DateTo)
      AND (@Status      IS NULL OR r.Status      =  @Status)
      AND (@ReceiptType IS NULL OR r.ReceiptType =  @ReceiptType)
      AND (@JobId       IS NULL OR r.JobId       =  @JobId)
      AND (@CreatedBy   IS NULL OR r.CreatedBy LIKE N'%' + @CreatedBy + N'%')
    GROUP BY
        r.ReceiptId, r.ReceiptNo, r.ReceiptDate, r.ReceiptType, r.JobId,
        r.SupplierName, r.PoNumber, r.SupplierRef, r.Status, r.Notes,
        r.CreatedBy, r.CreatedDate
    ORDER BY r.ReceiptDate DESC, r.ReceiptId DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportInvoices]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportInvoices];
GO

CREATE   PROCEDURE proj.sp_ReportInvoices
    @DateFrom   DATE          = NULL,
    @DateTo     DATE          = NULL,
    @CustomerId INT           = NULL,
    @JobId      NVARCHAR(50)  = NULL,
    @Status     NVARCHAR(50)  = NULL,
    @CreatedBy  NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @BaseCcy NVARCHAR(10) = (SELECT ShortName FROM proj.TBL_CURRENCY WHERE IsBaseCurrency=1);

    SELECT
        i.InvoiceId,
        i.InvoiceNo,
        i.InvoiceDate,
        i.DueDate,
        i.CustomerId,
        c.CustomerName,
        i.JobId,
        j.ProjectName                                   AS JobTitle,
        cur.ShortName                                   AS CurrencyShort,
        ISNULL(i.ExchangeRate, 1)                       AS ExchangeRate,
        @BaseCcy                                        AS BaseCurrency,
        i.SubTotal,
        i.TaxAmount,
        i.TotalAmount,
        i.SubTotal   * ISNULL(i.ExchangeRate, 1)        AS SubTotalBase,
        i.TaxAmount  * ISNULL(i.ExchangeRate, 1)        AS TaxAmountBase,
        i.TotalAmount * ISNULL(i.ExchangeRate, 1)       AS TotalAmountBase,
        ISNULL(paid.PaidAmount, 0)                      AS PaidBase,
        i.TotalAmount * ISNULL(i.ExchangeRate, 1)
            - ISNULL(paid.PaidAmount, 0)                AS BalanceBase,
        i.Status,
        i.LpoNo
    FROM proj.TBL_INVOICE i
    LEFT JOIN proj.TBL_CUSTOMER c   ON c.CustomerId   = i.CustomerId
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = i.CurrencyId
    LEFT JOIN proj.TBL_JOB j        ON j.JobId        = i.JobId
    OUTER APPLY (
        SELECT ISNULL(rv_paid.Amt, 0) + ISNULL(cn_paid.Amt, 0) AS PaidAmount
        FROM (VALUES(1)) x(d)
        OUTER APPLY (
            SELECT ISNULL(SUM(a.AllocatedAmount), 0) AS Amt
            FROM   proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
            JOIN   proj.TBL_RECEIPT_VOUCHER rv ON rv.RvId = a.RvId
            WHERE  a.InvoiceId = i.InvoiceId AND a.IsActive = 1
              AND  rv.IsActive = 1 AND rv.Status = 'Approved'
        ) rv_paid
        OUTER APPLY (
            SELECT ISNULL(SUM(a.AllocatedAmount), 0) AS Amt
            FROM   proj.TBL_CREDIT_NOTE_ALLOCATION a
            JOIN   proj.TBL_CREDIT_NOTE cn ON cn.CnId = a.CnId
            WHERE  a.InvoiceId = i.InvoiceId AND a.IsActive = 1
              AND  cn.IsActive = 1 AND cn.Status = 'Approved'
        ) cn_paid
    ) paid
    WHERE i.IsActive = 1
      AND (@DateFrom   IS NULL OR i.InvoiceDate >= @DateFrom)
      AND (@DateTo     IS NULL OR i.InvoiceDate <= @DateTo)
      AND (@CustomerId IS NULL OR i.CustomerId   = @CustomerId)
      AND (@JobId      IS NULL OR i.JobId         = @JobId)
      AND (@Status     IS NULL OR i.Status        = @Status)
      AND (@CreatedBy  IS NULL OR i.CreatedBy     = @CreatedBy)
    ORDER BY i.InvoiceDate DESC, i.InvoiceId DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportIssueDetails]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportIssueDetails];
GO

CREATE PROCEDURE proj.sp_ReportIssueDetails
    @DateFrom    DATE          = NULL,
    @DateTo      DATE          = NULL,
    @JobId       NVARCHAR(50)  = NULL,
    @SourceJobId NVARCHAR(50)  = NULL,
    @ItemId      INT           = NULL,
    @ItemTypeId  INT           = NULL,
    @CategoryId  INT           = NULL,
    @SearchText  NVARCHAR(200) = NULL,
    @Status      NVARCHAR(50)  = NULL,
    @CostingType NVARCHAR(20)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        si.IssueId,
        si.IssueNo,
        si.IssueDate,
        si.JobId,
        j.ProjectName,
        si.Status,
        si.CostingType,
        si.IssuedTo,
        sl.IssueLineId,
        sl.LineNum,
        sl.ItemId,
        i.ItemCode,
        ISNULL(NULLIF(LTRIM(RTRIM(i.ItemName)), ''), sl.ItemDesc) AS ItemDesc,
        cat.CategoryName,
        it.TypeName                        AS ItemTypeName,
        sl.Qty,
        u.UomCode                          AS UomName,
        sl.UnitCost,
        ROUND(sl.Qty * sl.UnitCost, 2)     AS LineTotal,
        sl.Notes,
        -- Source IH job from ledger entry for this issue line
        (SELECT TOP 1 led.JobId
         FROM proj.TBL_STOCK_LEDGER led
         JOIN proj.TBL_JOB          sj  ON sj.JobId    = led.JobId
         JOIN proj.TBL_JOBTYPE      sjt ON sjt.JobTypeId = sj.JobTypeId AND sjt.IsBudgetHeaderLinked = 1
         WHERE led.TransType = 'ISSUE'
           AND led.RefId     = si.IssueId
           AND led.ItemId    = sl.ItemId
        ) AS SourceJobId
    FROM  proj.TBL_STOCK_ISSUE_LINE sl
    JOIN  proj.TBL_STOCK_ISSUE      si  ON si.IssueId = sl.IssueId
    LEFT JOIN proj.TBL_ITEM         i   ON i.ItemId   = sl.ItemId
    LEFT JOIN proj.TBL_ITEM_UOM     u   ON u.UomId    = sl.UomId
    LEFT JOIN proj.TBL_ITEM_CATEGORY cat ON cat.CategoryId = i.CategoryId
    LEFT JOIN proj.TBL_ITEM_TYPE     it  ON it.ItemTypeId  = i.ItemTypeId
    LEFT JOIN proj.TBL_JOB          j   ON j.JobId    = si.JobId
    WHERE sl.IsActive = 1
      AND si.IsActive = 1
      AND (@DateFrom    IS NULL OR si.IssueDate >= @DateFrom)
      AND (@DateTo      IS NULL OR si.IssueDate <= @DateTo)
      AND (@JobId       IS NULL OR si.JobId     = @JobId)
      AND (@Status      IS NULL OR si.Status    = @Status)
      AND (@CostingType IS NULL OR si.CostingType = @CostingType)
      AND (@ItemId      IS NULL OR sl.ItemId    = @ItemId)
      AND (@ItemTypeId  IS NULL OR i.ItemTypeId = @ItemTypeId)
      AND (
          @CategoryId IS NULL
          OR i.CategoryId = @CategoryId
          OR i.CategoryId IN (
              SELECT CategoryId FROM proj.TBL_ITEM_CATEGORY WHERE ParentCategoryId = @CategoryId
          )
      )
      AND (@SearchText  IS NULL
           OR i.ItemCode  LIKE N'%' + @SearchText + N'%'
           OR i.ItemName  LIKE N'%' + @SearchText + N'%'
           OR sl.ItemDesc LIKE N'%' + @SearchText + N'%')
      AND (@SourceJobId IS NULL OR EXISTS (
              SELECT 1 FROM proj.TBL_STOCK_LEDGER led
              JOIN proj.TBL_JOB sj ON sj.JobId = led.JobId
              JOIN proj.TBL_JOBTYPE sjt ON sjt.JobTypeId = sj.JobTypeId AND sjt.IsBudgetHeaderLinked = 1
              WHERE led.TransType = 'ISSUE'
                AND led.RefId     = si.IssueId
                AND led.ItemId    = sl.ItemId
                AND led.JobId     = @SourceJobId
          ))
    ORDER BY si.IssueDate DESC, si.IssueNo, sl.LineNum;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportIssuedFromInHouse]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportIssuedFromInHouse];
GO
-- sp_ReportIssuedFromInHouse: issue depletion entries are now IsJobStock=0
CREATE PROCEDURE proj.sp_ReportIssuedFromInHouse
    @JobId NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        l.JobId AS InHouseJobId,
        sj.ProjectName AS InHouseJobName,
        ec.CategoryName AS BudgetHeader,
        l.ItemId, i.ItemCode, i.ItemName,
        SUM(l.QtyOut)                  AS QtyIssued,
        SUM(l.QtyOut * l.UnitCost)     AS ValueIssued
    FROM proj.TBL_STOCK_LEDGER l
    JOIN proj.TBL_STOCK_ISSUE si ON si.IssueId = l.RefId AND l.TransType = 'ISSUE'
    JOIN proj.TBL_JOB        sj ON sj.JobId    = l.JobId
    JOIN proj.TBL_JOBTYPE    jt ON jt.JobTypeId = sj.JobTypeId AND ISNULL(jt.IsBudgetHeaderLinked,0) = 1
    LEFT JOIN proj.TBL_JOB_EXPENSE_CATEGORY ec ON ec.ExpenseCategoryId = sj.BudgetCategoryId
    LEFT JOIN proj.TBL_ITEM i ON i.ItemId = l.ItemId
    WHERE l.IsJobStock = 0 AND l.QtyOut > 0
      AND si.JobId = @JobId AND si.Status = 'Confirmed' AND si.IsActive = 1
    GROUP BY l.JobId, sj.ProjectName, ec.CategoryName, l.ItemId, i.ItemCode, i.ItemName
    ORDER BY sj.ProjectName, i.ItemCode;
END;
GO

IF OBJECT_ID(N'[proj].[sp_ReportIssueReturnDetails]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportIssueReturnDetails];
GO

CREATE PROCEDURE proj.sp_ReportIssueReturnDetails
    @DateFrom    DATE          = NULL,
    @DateTo      DATE          = NULL,
    @JobId       NVARCHAR(50)  = NULL,
    @ReturnToJobId NVARCHAR(50) = NULL,
    @ItemId      INT           = NULL,
    @ItemTypeId  INT           = NULL,
    @CategoryId  INT           = NULL,
    @SearchText  NVARCHAR(200) = NULL,
    @Status      NVARCHAR(50)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        r.ReturnId,
        r.ReturnNo,
        CONVERT(DATE, r.ReturnDate) AS ReturnDate,
        r.Status,
        r.ReturnedBy,
        -- Original issue reference
        i.IssueNo,
        i.JobId,
        j.ProjectName,
        -- Line detail
        rl.ReturnLineId,
        rl.LineNum,
        rl.ItemId,
        it.ItemCode,
        ISNULL(NULLIF(LTRIM(RTRIM(it.ItemName)), ''), rl.ItemDesc) AS ItemDesc,
        cat.CategoryName,
        itp.TypeName  AS ItemTypeName,
        rl.ReturnQty,
        u.UomCode     AS UomName,
        rl.UnitCost,
        ROUND(rl.ReturnQty * rl.UnitCost, 2) AS LineTotal,
        rl.Notes,
        -- Return-to IH job: from ledger RETURN entry for this line's item
        (SELECT TOP 1 led.JobId
         FROM proj.TBL_STOCK_LEDGER led
         JOIN proj.TBL_JOB          rj  ON rj.JobId     = led.JobId
         JOIN proj.TBL_JOBTYPE      rjt ON rjt.JobTypeId = rj.JobTypeId AND rjt.IsBudgetHeaderLinked = 1
         WHERE led.TransType = 'RETURN'
           AND led.RefId     = r.ReturnId
           AND led.ItemId    = rl.ItemId
        ) AS ReturnToJobId
    FROM  proj.TBL_STOCK_ISSUE_RETURN_LINE rl
    JOIN  proj.TBL_STOCK_ISSUE_RETURN  r   ON r.ReturnId  = rl.ReturnId
    LEFT JOIN proj.TBL_STOCK_ISSUE     i   ON i.IssueId   = r.IssueId
    LEFT JOIN proj.TBL_JOB             j   ON j.JobId     = i.JobId
    LEFT JOIN proj.TBL_ITEM            it  ON it.ItemId   = rl.ItemId
    LEFT JOIN proj.TBL_ITEM_UOM        u   ON u.UomId     = rl.UomId
    LEFT JOIN proj.TBL_ITEM_CATEGORY   cat ON cat.CategoryId = it.CategoryId
    LEFT JOIN proj.TBL_ITEM_TYPE       itp ON itp.ItemTypeId = it.ItemTypeId
    WHERE r.IsActive = 1
      AND (@DateFrom    IS NULL OR CONVERT(DATE, r.ReturnDate) >= @DateFrom)
      AND (@DateTo      IS NULL OR CONVERT(DATE, r.ReturnDate) <= @DateTo)
      AND (@JobId       IS NULL OR i.JobId     = @JobId)
      AND (@Status      IS NULL OR r.Status    = @Status)
      AND (@ItemId      IS NULL OR rl.ItemId   = @ItemId)
      AND (@ItemTypeId  IS NULL OR it.ItemTypeId = @ItemTypeId)
      AND (
          @CategoryId IS NULL
          OR it.CategoryId = @CategoryId
          OR it.CategoryId IN (
              SELECT CategoryId FROM proj.TBL_ITEM_CATEGORY WHERE ParentCategoryId = @CategoryId
          )
      )
      AND (@SearchText IS NULL
           OR it.ItemCode  LIKE N'%' + @SearchText + N'%'
           OR it.ItemName  LIKE N'%' + @SearchText + N'%'
           OR rl.ItemDesc  LIKE N'%' + @SearchText + N'%')
      AND (@ReturnToJobId IS NULL OR EXISTS (
              SELECT 1 FROM proj.TBL_STOCK_LEDGER led
              JOIN proj.TBL_JOB rj ON rj.JobId = led.JobId
              JOIN proj.TBL_JOBTYPE rjt ON rjt.JobTypeId = rj.JobTypeId AND rjt.IsBudgetHeaderLinked = 1
              WHERE led.TransType = 'RETURN'
                AND led.RefId     = r.ReturnId
                AND led.ItemId    = rl.ItemId
                AND led.JobId     = @ReturnToJobId
          ))
    ORDER BY r.ReturnDate DESC, r.ReturnNo, rl.LineNum;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportIssueReturns]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportIssueReturns];
GO

-- ── ISSUE RETURN REPORT ──────────────────────────────────────────────────
CREATE   PROCEDURE proj.sp_ReportIssueReturns
    @DateFrom  DATE          = NULL,
    @DateTo    DATE          = NULL,
    @JobId     NVARCHAR(50)  = NULL,
    @Status    NVARCHAR(50)  = NULL,
    @CreatedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        r.ReturnId,
        r.ReturnNo,
        CONVERT(DATE, r.ReturnDate)     AS ReturnDate,
        i.IssueNo,
        i.JobId,
        j.ProjectName                   AS JobTitle,
        r.Status,
        r.ReturnedBy,
        r.CreatedBy,
        r.CreatedDate,
        (SELECT COUNT(*) FROM proj.TBL_STOCK_ISSUE_RETURN_LINE l
         WHERE l.ReturnId = r.ReturnId) AS LineCount,
        ISNULL((SELECT SUM(l.ReturnQty * l.UnitCost)
         FROM proj.TBL_STOCK_ISSUE_RETURN_LINE l
         WHERE l.ReturnId = r.ReturnId), 0) AS TotalValue
    FROM proj.TBL_STOCK_ISSUE_RETURN r
    LEFT JOIN proj.TBL_STOCK_ISSUE i ON i.IssueId = r.IssueId
    LEFT JOIN proj.TBL_JOB j         ON j.JobId = i.JobId
    WHERE r.IsActive = 1
      AND (@DateFrom  IS NULL OR CONVERT(DATE, r.ReturnDate) >= @DateFrom)
      AND (@DateTo    IS NULL OR CONVERT(DATE, r.ReturnDate) <= @DateTo)
      AND (@JobId     IS NULL OR i.JobId = @JobId)
      AND (@Status    IS NULL OR r.Status = @Status)
      AND (@CreatedBy IS NULL OR r.CreatedBy LIKE '%' + @CreatedBy + '%')
    ORDER BY r.ReturnDate DESC, r.ReturnNo;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportIssues]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportIssues];
GO

CREATE PROCEDURE proj.sp_ReportIssues
    @DateFrom    DATE          = NULL,
    @DateTo      DATE          = NULL,
    @JobId       NVARCHAR(50)  = NULL,
    @SourceJobId NVARCHAR(50)  = NULL,
    @Status      NVARCHAR(50)  = NULL,
    @CreatedBy   NVARCHAR(100) = NULL,
    @CostingType NVARCHAR(50)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        i.IssueId,
        i.IssueNo,
        CONVERT(DATE, i.IssueDate) AS IssueDate,
        i.JobId,
        j.ProjectName              AS JobTitle,
        i.Status,
        i.IssuedTo,
        i.CostingType,
        i.CreatedBy,
        i.CreatedDate,
        (SELECT COUNT(*) FROM proj.TBL_STOCK_ISSUE_LINE l
         WHERE l.IssueId = i.IssueId AND l.IsActive = 1)  AS LineCount,
        ISNULL((SELECT SUM(l.Qty * l.UnitCost)
         FROM proj.TBL_STOCK_ISSUE_LINE l
         WHERE l.IssueId = i.IssueId AND l.IsActive = 1), 0) AS TotalValue,
        -- Source IH job: derived from the ledger entry written at confirmation
        (SELECT TOP 1 sl.JobId
         FROM proj.TBL_STOCK_LEDGER sl
         JOIN proj.TBL_JOB          sj  ON sj.JobId    = sl.JobId
         JOIN proj.TBL_JOBTYPE      sjt ON sjt.JobTypeId = sj.JobTypeId AND sjt.IsBudgetHeaderLinked = 1
         WHERE sl.TransType = 'ISSUE' AND sl.RefId = i.IssueId
        ) AS SourceJobId
    FROM proj.TBL_STOCK_ISSUE i
    LEFT JOIN proj.TBL_JOB j ON j.JobId = i.JobId
    WHERE i.IsActive = 1
      AND (@DateFrom    IS NULL OR CONVERT(DATE, i.IssueDate) >= @DateFrom)
      AND (@DateTo      IS NULL OR CONVERT(DATE, i.IssueDate) <= @DateTo)
      AND (@JobId       IS NULL OR i.JobId = @JobId)
      AND (@Status      IS NULL OR i.Status = @Status)
      AND (@CreatedBy   IS NULL OR i.CreatedBy LIKE '%' + @CreatedBy + '%')
      AND (@CostingType IS NULL OR i.CostingType = @CostingType)
      AND (@SourceJobId IS NULL OR EXISTS (
              SELECT 1 FROM proj.TBL_STOCK_LEDGER sl
              JOIN proj.TBL_JOB sj ON sj.JobId = sl.JobId
              JOIN proj.TBL_JOBTYPE sjt ON sjt.JobTypeId = sj.JobTypeId AND sjt.IsBudgetHeaderLinked = 1
              WHERE sl.TransType = 'ISSUE' AND sl.RefId = i.IssueId AND sl.JobId = @SourceJobId
          ))
    ORDER BY i.IssueDate DESC, i.IssueNo;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportJobBudgetVariance]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportJobBudgetVariance];
GO

CREATE PROCEDURE proj.sp_ReportJobBudgetVariance
    @DateFrom       DATE          = NULL,
    @DateTo         DATE          = NULL,
    @CustomerId     INT           = NULL,
    @JobTypeId      NVARCHAR(50)  = NULL,
    @JobStageId     NVARCHAR(10)  = NULL,
    @JobStatusId    INT           = NULL,
    @ApprovalStatus NVARCHAR(50)  = NULL,
    @OverBudgetOnly BIT           = 0
AS
BEGIN
    SET NOCOUNT ON;

    -- ── Filtered job set (header fields + job rate) ──────────────────────────
    ;WITH jobs AS (
        SELECT
            j.JobId, j.ProjectName, j.JobDate, j.JobTypeName, j.JobStageName,
            j.CustomerId, j.CustomerName, j.JobStatusName, j.ApprovalStatus,
            j.CurrencySymbol, ISNULL(j.JobExcRate, 1) AS JobExcRate
        FROM proj.VW_JOB j
        WHERE (@DateFrom        IS NULL OR CAST(j.JobDate AS DATE) >= @DateFrom)
          AND (@DateTo          IS NULL OR CAST(j.JobDate AS DATE) <= @DateTo)
          AND (@CustomerId      IS NULL OR j.CustomerId    = @CustomerId)
          AND (@JobTypeId       IS NULL OR j.JobTypeId     = @JobTypeId)
          AND (@JobStageId      IS NULL OR j.JobStageId    = @JobStageId)
          AND (@JobStatusId     IS NULL OR j.JobStatusId   = @JobStatusId)
          AND (@ApprovalStatus  IS NULL OR j.ApprovalStatus = @ApprovalStatus)
    ),
    -- Budget (base) per job + per category — current budget only
    budcat AS (
        SELECT b.JobId, b.CostCategoryId,
               SUM(ISNULL(b.AmountInBaseCurrency, proj.fn_ToBase(b.BudgetedAmount, ISNULL(b.ExchangeRate,1)))) AS Budgeted
        FROM proj.TBL_JOB_BUDGET b
        WHERE b.IsCurrent = 1
        GROUP BY b.JobId, b.CostCategoryId
    ),
    -- Categorised actual (base) per job + category (manhours, PO, approved expenses)
    actcat AS (
        SELECT a.JobId, a.CostCategoryId, a.ActualAmount AS Actual
        FROM proj.VW_JOB_COST_ACTUAL a
    ),
    -- Per-category comparison
    catcmp AS (
        SELECT COALESCE(b.JobId, a.JobId)               AS JobId,
               COALESCE(b.CostCategoryId, a.CostCategoryId) AS CostCategoryId,
               ISNULL(b.Budgeted, 0)                     AS Budgeted,
               ISNULL(a.Actual,   0)                     AS Actual
        FROM budcat b
        FULL OUTER JOIN actcat a
          ON a.JobId = b.JobId AND a.CostCategoryId = b.CostCategoryId
    ),
    -- Stock issues (base) per job — Confirmed, costed; minus confirmed returns
    iss AS (
        SELECT i.JobId, SUM(il.Qty * il.UnitCost) AS Amt
        FROM proj.TBL_STOCK_ISSUE i
        JOIN proj.TBL_STOCK_ISSUE_LINE il ON il.IssueId = i.IssueId AND il.IsActive = 1
        WHERE i.IsActive = 1 AND i.Status = 'Confirmed'
          AND ISNULL(i.CostingType, 'INC_COSTING') <> 'EXC_COSTING'
        GROUP BY i.JobId
    ),
    ret AS (
        SELECT ri.JobId, SUM(rl.ReturnQty * rl.UnitCost) AS Amt
        FROM proj.TBL_STOCK_ISSUE_RETURN r
        JOIN proj.TBL_STOCK_ISSUE_RETURN_LINE rl ON rl.ReturnId = r.ReturnId
        JOIN proj.TBL_STOCK_ISSUE             ri ON ri.IssueId  = r.IssueId
        WHERE r.IsActive = 1 AND r.Status IN ('Confirmed','Approved')
        GROUP BY ri.JobId
    ),
    -- Roll up per job
    rollup AS (
        SELECT
            j.JobId,
            ISNULL((SELECT SUM(Budgeted) FROM budcat b WHERE b.JobId = j.JobId), 0)                 AS BudgetBase,
            ISNULL((SELECT SUM(Actual)   FROM actcat a WHERE a.JobId = j.JobId), 0)                 AS CatActualBase,
            ISNULL(iss.Amt, 0) - ISNULL(ret.Amt, 0)                                                  AS IssueNetBase,
            ISNULL((SELECT COUNT(*) FROM catcmp c WHERE c.JobId = j.JobId AND c.Actual > c.Budgeted), 0) AS OverCatCount
        FROM jobs j
        LEFT JOIN iss ON iss.JobId = j.JobId
        LEFT JOIN ret ON ret.JobId = j.JobId
    )
    -- ── RS1: Job-level summary ───────────────────────────────────────────────
    SELECT
        j.JobId, j.ProjectName, j.JobDate, j.JobTypeName, j.JobStageName,
        j.CustomerId, j.CustomerName, j.JobStatusName, j.ApprovalStatus,
        j.CurrencySymbol, j.JobExcRate AS ExchangeRate,
        -- base (AED) — comparable across jobs
        r.BudgetBase                                              AS TotalBudgetBase,
        (r.CatActualBase + r.IssueNetBase)                        AS TotalActualBase,
        (r.BudgetBase - (r.CatActualBase + r.IssueNetBase))       AS VarianceBase,
        -- job currency
        r.BudgetBase / NULLIF(j.JobExcRate, 0)                    AS TotalBudget,
        (r.CatActualBase + r.IssueNetBase) / NULLIF(j.JobExcRate, 0) AS TotalActual,
        (r.BudgetBase - (r.CatActualBase + r.IssueNetBase)) / NULLIF(j.JobExcRate, 0) AS Variance,
        CASE WHEN r.BudgetBase > 0
             THEN ((r.CatActualBase + r.IssueNetBase) - r.BudgetBase) * 100.0 / r.BudgetBase
             ELSE NULL END                                        AS VariancePct,
        r.OverCatCount + CASE WHEN r.IssueNetBase > 0 THEN 1 ELSE 0 END AS OverCategoryCount,
        CASE
            WHEN r.BudgetBase <= 0 AND (r.CatActualBase + r.IssueNetBase) > 0 THEN 'No Budget'
            WHEN (r.CatActualBase + r.IssueNetBase) > r.BudgetBase            THEN 'Over'
            ELSE 'Within'
        END                                                       AS BudgetStatus
    FROM jobs j
    JOIN rollup r ON r.JobId = j.JobId
    WHERE (@OverBudgetOnly = 0
           OR (r.CatActualBase + r.IssueNetBase) > r.BudgetBase)
    ORDER BY (r.CatActualBase + r.IssueNetBase) - r.BudgetBase DESC;

    -- ── RS2: Per-category breakdown (real categories + Uncategorised issues) ──
    ;WITH jobs AS (
        SELECT j.JobId, ISNULL(j.JobExcRate, 1) AS JobExcRate
        FROM proj.VW_JOB j
        WHERE (@DateFrom        IS NULL OR CAST(j.JobDate AS DATE) >= @DateFrom)
          AND (@DateTo          IS NULL OR CAST(j.JobDate AS DATE) <= @DateTo)
          AND (@CustomerId      IS NULL OR j.CustomerId    = @CustomerId)
          AND (@JobTypeId       IS NULL OR j.JobTypeId     = @JobTypeId)
          AND (@JobStageId      IS NULL OR j.JobStageId    = @JobStageId)
          AND (@JobStatusId     IS NULL OR j.JobStatusId   = @JobStatusId)
          AND (@ApprovalStatus  IS NULL OR j.ApprovalStatus = @ApprovalStatus)
    ),
    budcat AS (
        SELECT b.JobId, b.CostCategoryId,
               SUM(ISNULL(b.AmountInBaseCurrency, proj.fn_ToBase(b.BudgetedAmount, ISNULL(b.ExchangeRate,1)))) AS Budgeted
        FROM proj.TBL_JOB_BUDGET b WHERE b.IsCurrent = 1
        GROUP BY b.JobId, b.CostCategoryId
    ),
    actcat AS (
        SELECT a.JobId, a.CostCategoryId, a.ActualAmount AS Actual FROM proj.VW_JOB_COST_ACTUAL a
    ),
    catcmp AS (
        SELECT COALESCE(b.JobId, a.JobId) AS JobId,
               COALESCE(b.CostCategoryId, a.CostCategoryId) AS CostCategoryId,
               ISNULL(b.Budgeted, 0) AS Budgeted, ISNULL(a.Actual, 0) AS Actual
        FROM budcat b FULL OUTER JOIN actcat a
          ON a.JobId = b.JobId AND a.CostCategoryId = b.CostCategoryId
    ),
    iss AS (
        SELECT i.JobId, SUM(il.Qty * il.UnitCost) AS Amt
        FROM proj.TBL_STOCK_ISSUE i
        JOIN proj.TBL_STOCK_ISSUE_LINE il ON il.IssueId = i.IssueId AND il.IsActive = 1
        WHERE i.IsActive = 1 AND i.Status = 'Confirmed'
          AND ISNULL(i.CostingType, 'INC_COSTING') <> 'EXC_COSTING'
        GROUP BY i.JobId
    ),
    ret AS (
        SELECT ri.JobId, SUM(rl.ReturnQty * rl.UnitCost) AS Amt
        FROM proj.TBL_STOCK_ISSUE_RETURN r
        JOIN proj.TBL_STOCK_ISSUE_RETURN_LINE rl ON rl.ReturnId = r.ReturnId
        JOIN proj.TBL_STOCK_ISSUE             ri ON ri.IssueId  = r.IssueId
        WHERE r.IsActive = 1 AND r.Status IN ('Confirmed','Approved')
        GROUP BY ri.JobId
    )
    SELECT
        j.JobId,
        c.CostCategoryId,
        ISNULL(cat.CategoryName, 'Category ' + CAST(c.CostCategoryId AS NVARCHAR(20))) AS CategoryName,
        c.Budgeted                                  AS BudgetedBase,
        c.Actual                                    AS ActualBase,
        (c.Budgeted - c.Actual)                     AS VarianceBase,
        c.Budgeted / NULLIF(j.JobExcRate, 0)        AS Budgeted,
        c.Actual   / NULLIF(j.JobExcRate, 0)        AS Actual,
        (c.Budgeted - c.Actual) / NULLIF(j.JobExcRate, 0) AS Variance,
        CAST(CASE WHEN c.Actual > c.Budgeted THEN 1 ELSE 0 END AS BIT) AS IsOver
    FROM jobs j
    JOIN catcmp c ON c.JobId = j.JobId
    LEFT JOIN proj.TBL_JOB_EXPENSE_CATEGORY cat ON cat.ExpenseCategoryId = c.CostCategoryId
    WHERE c.Budgeted <> 0 OR c.Actual <> 0

    UNION ALL

    SELECT
        j.JobId,
        NULL                                        AS CostCategoryId,
        'Uncategorised (Stock Issues)'              AS CategoryName,
        0                                           AS BudgetedBase,
        (ISNULL(iss.Amt,0) - ISNULL(ret.Amt,0))     AS ActualBase,
        -(ISNULL(iss.Amt,0) - ISNULL(ret.Amt,0))    AS VarianceBase,
        0                                           AS Budgeted,
        (ISNULL(iss.Amt,0) - ISNULL(ret.Amt,0)) / NULLIF(j.JobExcRate, 0) AS Actual,
        -(ISNULL(iss.Amt,0) - ISNULL(ret.Amt,0)) / NULLIF(j.JobExcRate, 0) AS Variance,
        CAST(1 AS BIT)                              AS IsOver
    FROM jobs j
    LEFT JOIN iss ON iss.JobId = j.JobId
    LEFT JOIN ret ON ret.JobId = j.JobId
    WHERE (ISNULL(iss.Amt,0) - ISNULL(ret.Amt,0)) <> 0
    ORDER BY j.JobId, IsOver DESC, VarianceBase ASC;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportJobs]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportJobs];
GO

CREATE PROCEDURE proj.sp_ReportJobs
    @DateFrom       DATE          = NULL,
    @DateTo         DATE          = NULL,
    @CustomerId     INT           = NULL,
    @JobTypeId      NVARCHAR(50)  = NULL,
    @JobStageId     NVARCHAR(10)  = NULL,
    @JobStatusId    INT           = NULL,
    @ApprovalStatus NVARCHAR(50)  = NULL,
    @CreatedBy      NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        j.JobNumId,
        j.JobId,
        j.ProjectName,
        j.JobDate,
        j.JobTypeName,
        j.JobStageName,
        j.CustomerId,
        j.CustomerName,
        j.JobStatusName,
        j.ApprovalStatus,
        j.CurrencySymbol,
        j.JobExcRate                                                            AS ExchangeRate,
        j.OrderValue,
        j.OrderValue      * ISNULL(j.JobExcRate, 1)                            AS OrderValueBase,
        j.TotalActual,
        j.TotalExpenses,
        j.TotalInvoicing,
        j.TotalInvoicing  * ISNULL(j.JobExcRate, 1)                            AS TotalInvoicingBase,
        ROUND(j.TotalPayments / NULLIF(j.JobExcRate, 0), 2)                    AS TotalPayments,
        j.TotalPayments                                                         AS TotalPaymentsBase,
        ROUND(j.TotalCredit   / NULLIF(j.JobExcRate, 0), 2)                    AS TotalCredit,
        j.TotalCredit                                                           AS TotalCreditBase,
        j.TotalBomValue,
        j.LpoRef,
        j.ContractRef,
        j.ExternalRef,
        j.ParentJobId,
        j.JobCreatedBy,
        j.JobCreatedDate,
        j.IsClosedStatus,
        j.JobPlannedStartDate,
        j.JobExpectedCompleteDate,
        j.JobActualCompleteDate,
        j.JobExpectedDeliveryDate
    FROM proj.VW_JOB j
    WHERE
        (@DateFrom        IS NULL OR CAST(j.JobDate AS DATE) >= @DateFrom)
        AND (@DateTo      IS NULL OR CAST(j.JobDate AS DATE) <= @DateTo)
        AND (@CustomerId  IS NULL OR j.CustomerId      = @CustomerId)
        AND (@JobTypeId   IS NULL OR j.JobTypeId       = @JobTypeId)
        AND (@JobStageId  IS NULL OR j.JobStageId      = @JobStageId)
        AND (@JobStatusId IS NULL OR j.JobStatusId     = @JobStatusId)
        AND (@ApprovalStatus IS NULL OR j.ApprovalStatus = @ApprovalStatus)
        AND (@CreatedBy   IS NULL OR j.JobCreatedBy    = @CreatedBy)
    ORDER BY j.JobDate DESC, j.JobId ASC;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportManhours]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportManhours];
GO
CREATE   PROCEDURE proj.sp_ReportManhours
    @DateFrom   DATE         = NULL,
    @DateTo     DATE         = NULL,
    @JobId      NVARCHAR(50) = NULL,
    @Status     NVARCHAR(50) = NULL,
    @MType      NVARCHAR(10) = NULL,
    @Site       NVARCHAR(5)  = NULL,
    @EmployeeId INT          = NULL,
    @EmpType    NVARCHAR(20) = NULL,   -- 'COMPANY' | 'OUTSOURCED' | NULL = all
    @SupplierId INT          = NULL    -- filter to one outsourcing supplier
AS
BEGIN
    SET NOCOUNT ON;

    -- ── Result set 1: batch-level summary ────────────────────────────────
    SELECT
        m.BatchId,
        m.DocumentNo,
        m.DocumentDate,
        m.Status,
        m.UploadedFileName,
        m.CreatedBy,
        m.CreatedDate,
        COUNT(DISTINCT m.JobId)         AS JobCount,
        COUNT(DISTINCT m.EmployeeId)    AS EmployeeCount,
        SUM(ISNULL(m.Hours, 0))         AS TotalHours,
        SUM(ISNULL(m.OvertimeHours, 0)) AS TotalOTHours
    FROM proj.TBL_MANHOUR m
    LEFT JOIN proj.TBL_EMPLOYEE e ON e.EmployeeId = m.EmployeeId
    WHERE m.IsActive = 1
      AND (@DateFrom   IS NULL OR m.DocumentDate >= @DateFrom)
      AND (@DateTo     IS NULL OR m.DocumentDate <= @DateTo)
      AND (@JobId      IS NULL OR m.JobId      =  @JobId)
      AND (@Status     IS NULL OR m.Status     =  @Status)
      AND (@MType      IS NULL OR m.MType      =  @MType)
      AND (@Site       IS NULL OR m.Site       =  @Site)
      AND (@EmployeeId IS NULL OR m.EmployeeId =  @EmployeeId)
      AND (@EmpType    IS NULL OR e.EmpType    =  @EmpType)
      AND (@SupplierId IS NULL OR e.SupplierId =  @SupplierId)
    GROUP BY
        m.BatchId, m.DocumentNo, m.DocumentDate, m.Status,
        m.UploadedFileName, m.CreatedBy, m.CreatedDate
    ORDER BY m.DocumentDate DESC, m.BatchId DESC;

    -- ── Result set 2: supplier-wise summary (outsourced employees) ───────
    -- Only employees linked to an outsourcing supplier contribute here.
    SELECT
        e.SupplierId,
        s.SupplierName,
        COUNT(DISTINCT m.EmployeeId)    AS EmployeeCount,
        COUNT(DISTINCT m.BatchId)       AS BatchCount,
        SUM(ISNULL(m.Hours, 0))         AS TotalHours,
        SUM(ISNULL(m.OvertimeHours, 0)) AS TotalOTHours
    FROM proj.TBL_MANHOUR m
    JOIN proj.TBL_EMPLOYEE e ON e.EmployeeId = m.EmployeeId AND e.SupplierId IS NOT NULL
    JOIN proj.TBL_SUPPLIER s ON s.SupplierId = e.SupplierId
    WHERE m.IsActive = 1
      AND (@DateFrom   IS NULL OR m.DocumentDate >= @DateFrom)
      AND (@DateTo     IS NULL OR m.DocumentDate <= @DateTo)
      AND (@JobId      IS NULL OR m.JobId      =  @JobId)
      AND (@Status     IS NULL OR m.Status     =  @Status)
      AND (@MType      IS NULL OR m.MType      =  @MType)
      AND (@Site       IS NULL OR m.Site       =  @Site)
      AND (@EmployeeId IS NULL OR m.EmployeeId =  @EmployeeId)
      AND (@SupplierId IS NULL OR e.SupplierId =  @SupplierId)
    GROUP BY e.SupplierId, s.SupplierName
    ORDER BY TotalHours DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportOpenPoCommitment]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportOpenPoCommitment];
GO

CREATE PROCEDURE proj.sp_ReportOpenPoCommitment
    @DateFrom          DATE = NULL,
    @DateTo            DATE = NULL,
    @SupplierId        INT  = NULL,
    @JobId             NVARCHAR(50) = NULL,
    @ExpenseCategoryId INT  = NULL,
    @OverdueOnly       BIT  = 0
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Today DATE = CAST(GETDATE() AS DATE);

    ;WITH lines AS (
        SELECT
            po.PoId, po.PoNumber, po.PoDate, po.DeliveryDate,
            po.SupplierId, po.VendorName, po.JobId,
            po.CurrencyId, ISNULL(po.ExchangeRate,1) AS ExchangeRate,
            po.Status AS PoStatus, po.ExpenseCategoryId,
            pol.PoLineId, pol.LineNum, pol.ItemCode, pol.ItemDesc, pol.UomName,
            pol.OrderedQty, pol.ReceivedQty,
            (pol.OrderedQty - pol.ReceivedQty)                          AS OpenQty,
            pol.UnitPrice,
            (pol.OrderedQty - pol.ReceivedQty) * pol.UnitPrice          AS OpenValue,
            ((pol.OrderedQty - pol.ReceivedQty) * pol.UnitPrice) * ISNULL(po.ExchangeRate,1) AS OpenValueBase,
            pol.LineStatus,
            CASE WHEN po.DeliveryDate IS NOT NULL AND po.DeliveryDate < @Today
                 THEN DATEDIFF(DAY, po.DeliveryDate, @Today) ELSE 0 END AS DaysOverdue,
            recv.LastGrnDate
        FROM proj.TBL_PURCHASE_ORDER po
        JOIN proj.TBL_PURCHASE_ORDER_LINE pol ON pol.PoId = po.PoId AND pol.IsActive = 1
        OUTER APPLY (
            SELECT MAX(g.GrnDate) AS LastGrnDate
            FROM proj.TBL_GRN_DETAIL gd
            JOIN proj.TBL_GRN_HEADER g ON g.GrnId = gd.GrnId AND g.IsActive = 1 AND g.Status NOT IN ('Cancelled')
            WHERE gd.PoLineId = pol.PoLineId AND gd.IsActive = 1
        ) recv
        WHERE po.IsActive = 1
          AND po.Status NOT IN ('Draft','Cancelled')
          AND (pol.OrderedQty - pol.ReceivedQty) > 0.0001
          AND (@DateFrom          IS NULL OR po.PoDate >= @DateFrom)
          AND (@DateTo            IS NULL OR po.PoDate <= @DateTo)
          AND (@SupplierId        IS NULL OR po.SupplierId = @SupplierId)
          AND (@JobId             IS NULL OR po.JobId = @JobId)
          AND (@ExpenseCategoryId IS NULL OR po.ExpenseCategoryId = @ExpenseCategoryId)
    )
    SELECT
        l.PoId, l.PoNumber, l.PoDate, l.DeliveryDate,
        l.SupplierId, l.VendorName, l.JobId,
        cur.ShortName AS CurrencyShort, l.ExchangeRate,
        l.PoStatus, ISNULL(ec.CategoryName,'Uncategorised') AS ExpenseCategoryName,
        l.PoLineId, l.LineNum, l.ItemCode, l.ItemDesc, l.UomName,
        l.OrderedQty, l.ReceivedQty, l.OpenQty, l.UnitPrice,
        l.OpenValue, l.OpenValueBase,
        l.LineStatus, l.LastGrnDate,
        l.DaysOverdue,
        CASE
            WHEN l.DeliveryDate IS NULL          THEN 'No Due Date'
            WHEN l.DaysOverdue = 0               THEN 'Not Due'
            WHEN l.DaysOverdue BETWEEN  1 AND 30 THEN '0_30'
            WHEN l.DaysOverdue BETWEEN 31 AND 60 THEN '31_60'
            WHEN l.DaysOverdue BETWEEN 61 AND 90 THEN '61_90'
            ELSE '90Plus'
        END AS AgingBucket
    FROM lines l
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = l.CurrencyId
    LEFT JOIN proj.TBL_JOB_EXPENSE_CATEGORY ec ON ec.ExpenseCategoryId = l.ExpenseCategoryId
    WHERE (@OverdueOnly = 0 OR l.DaysOverdue > 0)
    ORDER BY l.DaysOverdue DESC, l.OpenValueBase DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportPaymentVouchers]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportPaymentVouchers];
GO
CREATE   PROCEDURE proj.sp_ReportPaymentVouchers
    @DateFrom    DATE          = NULL,
    @DateTo      DATE          = NULL,
    @SupplierId  INT           = NULL,
    @Status      NVARCHAR(50)  = NULL,
    @CreatedBy   NVARCHAR(100) = NULL,
    @PaymentMode NVARCHAR(50)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        pv.PvId,
        pv.PvNumber,
        pv.PvDate,
        pv.SupplierId,
        s.SupplierName,
        cur.ShortName                                       AS CurrencyShort,
        pv.ExchangeRate,
        pv.AmountPaid,
        ISNULL(pv.AllocatedAmount, 0)                      AS AllocatedAmount,
        pv.AmountPaid - ISNULL(pv.AllocatedAmount, 0)     AS UnallocatedAmount,
        pv.PaymentMode,
        pv.ReferenceNo,
        pv.ReferenceDate,
        pv.BankName,
        pv.Status,
        pv.CreatedBy,
        pv.CreatedDate
    FROM proj.TBL_PAYMENT_VOUCHER pv
    JOIN  proj.TBL_SUPPLIER s   ON s.SupplierId   = pv.SupplierId
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = pv.CurrencyId
    WHERE pv.IsActive = 1
      AND (@DateFrom    IS NULL OR pv.PvDate      >= @DateFrom)
      AND (@DateTo      IS NULL OR pv.PvDate      <= @DateTo)
      AND (@SupplierId  IS NULL OR pv.SupplierId  =  @SupplierId)
      AND (@Status      IS NULL OR pv.Status      =  @Status)
      AND (@CreatedBy   IS NULL OR pv.CreatedBy LIKE N'%' + @CreatedBy + N'%')
      AND (@PaymentMode IS NULL OR pv.PaymentMode =  @PaymentMode)
    ORDER BY pv.PvDate DESC, pv.PvId DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportPOs]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportPOs];
GO
CREATE   PROCEDURE proj.sp_ReportPOs
    @DateFrom    DATE         = NULL,
    @DateTo      DATE         = NULL,
    @SupplierId  INT          = NULL,
    @Status      NVARCHAR(50) = NULL,
    @JobId       NVARCHAR(50) = NULL,
    @CreatedBy   NVARCHAR(100)= NULL,
    @Priority    NVARCHAR(20) = NULL,
    @NoGrnOnly   BIT          = 0,
    @GrnFilter   NVARCHAR(10) = NULL,
    @ApprovedBy  NVARCHAR(100)= NULL,
    @SubmittedBy NVARCHAR(100)= NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        po.PoId,
        po.PoNumber,
        CONVERT(DATE, po.PoDate)                            AS PoDate,
        po.SupplierId,
        po.VendorName,
        po.JobId,
        j.ProjectName                                       AS JobTitle,
        po.Status,
        po.Priority,
        cur.ShortName                                       AS CurrencyShort,
        po.ExchangeRate,
        po.TotalAmount,
        po.TotalAmount * ISNULL(po.ExchangeRate, 1)        AS TotalAmountBase,
        po.TaxAmount,
        po.TaxAmount   * ISNULL(po.ExchangeRate, 1)        AS TaxAmountBase,
        po.Revision,
        po.CreatedBy,
        po.ModifiedBy,
        po.VendorRef,
        CONVERT(DATE, po.DeliveryDate)                     AS DeliveryDate,
        po.CreatedDate,
        appr.SubmittedBy                                    AS SubmittedBy,
        CASE WHEN appr.FinalAction = 'Approved' THEN appr.FinalActionBy END AS ApprovedBy,
        CASE WHEN appr.FinalAction = 'Approved' THEN appr.CompletedDate END AS ApprovedDate,
        (SELECT COUNT(*) FROM proj.TBL_PURCHASE_ORDER_LINE l
         WHERE l.PoId = po.PoId AND l.IsActive = 1)        AS LineCount,
        (SELECT COUNT(*) FROM proj.TBL_GRN_HEADER g
         WHERE g.PoId = po.PoId AND g.IsActive = 1
           AND ISNULL(g.Status,'') <> 'Cancelled')         AS GrnCount,
        ISNULL((
            SELECT SUM(gd.ReceivedQty * gd.UnitPrice)
            FROM proj.TBL_GRN_DETAIL gd
            JOIN proj.TBL_GRN_HEADER gh ON gh.GrnId = gd.GrnId
            WHERE gh.PoId = po.PoId AND gh.IsActive = 1 AND gd.IsActive = 1
              AND ISNULL(gh.Status,'') <> 'Cancelled'
        ), 0)                                               AS ReceivedAmount,
        ISNULL((
            SELECT SUM(gd.ReceivedQty * gd.UnitPrice * ISNULL(gh.ExchangeRate, 1))
            FROM proj.TBL_GRN_DETAIL gd
            JOIN proj.TBL_GRN_HEADER gh ON gh.GrnId = gd.GrnId
            WHERE gh.PoId = po.PoId AND gh.IsActive = 1 AND gd.IsActive = 1
              AND ISNULL(gh.Status,'') <> 'Cancelled'
        ), 0)                                               AS ReceivedAmountBase,
        STUFF((
            SELECT DISTINCT ', ' + pr.PrNumber
            FROM proj.TBL_PURCHASE_ORDER_LINE pol
            JOIN proj.TBL_PURCHASE_REQUEST_LINE prl ON prl.PrLineId = pol.PrLineId
            JOIN proj.TBL_PURCHASE_REQUEST pr        ON pr.PrId = prl.PrId
            WHERE pol.PoId = po.PoId AND pol.IsActive = 1
            FOR XML PATH(''), TYPE).value('.','NVARCHAR(MAX)'), 1, 2, ''
        )                                                   AS LinkedPRs
    FROM proj.TBL_PURCHASE_ORDER po
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = po.CurrencyId
    LEFT JOIN proj.TBL_JOB j        ON j.JobId = po.JobId
    OUTER APPLY (
        SELECT TOP 1 at.SubmittedBy, at.FinalAction, at.FinalActionBy, at.CompletedDate
        FROM proj.TBL_APPROVAL_TRANSACTION at
        WHERE at.ModuleId = 2 AND at.DocumentId = po.PoId
        ORDER BY at.TransactionId DESC
    ) appr
    WHERE po.IsActive = 1
      AND (@DateFrom   IS NULL OR CONVERT(DATE, po.PoDate) >= @DateFrom)
      AND (@DateTo     IS NULL OR CONVERT(DATE, po.PoDate) <= @DateTo)
      AND (@SupplierId IS NULL OR po.SupplierId = @SupplierId)
      AND (@Status     IS NULL OR po.Status = @Status)
      AND (@JobId      IS NULL OR po.JobId LIKE '%' + @JobId + '%')
      AND (@CreatedBy  IS NULL OR po.CreatedBy LIKE '%' + @CreatedBy + '%')
      AND (@Priority   IS NULL OR po.Priority = @Priority)
      AND (@ApprovedBy IS NULL OR (appr.FinalAction = 'Approved' AND appr.FinalActionBy LIKE '%' + @ApprovedBy + '%'))
      AND (@SubmittedBy IS NULL OR appr.SubmittedBy LIKE '%' + @SubmittedBy + '%')
      AND (
           @NoGrnOnly = 0
           OR NOT EXISTS (
               SELECT 1 FROM proj.TBL_GRN_HEADER g
               WHERE g.PoId = po.PoId AND g.IsActive = 1
                 AND ISNULL(g.Status,'') <> 'Cancelled'
           )
      )
      AND (
           @GrnFilter IS NULL OR @GrnFilter IN ('', 'ALL')
           OR (@GrnFilter = 'NONE' AND NOT EXISTS (
                   SELECT 1 FROM proj.TBL_GRN_HEADER g
                   WHERE g.PoId = po.PoId AND g.IsActive = 1
                     AND ISNULL(g.Status,'') <> 'Cancelled'))
           OR (@GrnFilter = 'ONLY' AND EXISTS (
                   SELECT 1 FROM proj.TBL_GRN_HEADER g
                   WHERE g.PoId = po.PoId AND g.IsActive = 1
                     AND ISNULL(g.Status,'') <> 'Cancelled'))
      )
    ORDER BY po.PoDate DESC, po.PoNumber;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportPRs]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportPRs];
GO

CREATE   PROCEDURE proj.sp_ReportPRs
    @DateFrom   DATE          = NULL,
    @DateTo     DATE          = NULL,
    @Status     NVARCHAR(50)  = NULL,
    @Priority   NVARCHAR(20)  = NULL,
    @JobId      NVARCHAR(50)  = NULL,
    @CreatedBy  NVARCHAR(100) = NULL,
    @NoPOOnly   BIT           = 0
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        pr.PrId,
        pr.PrNumber,
        CONVERT(DATE, pr.PrDate)        AS PrDate,
        pr.RequestedBy,
        pr.JobId,
        j.ProjectName                   AS JobTitle,
        pr.Status,
        pr.Priority,
        pr.CreatedBy,
        pr.CreatedDate,
        pr.Notes,
        -- Line count
        (SELECT COUNT(*) FROM proj.TBL_PURCHASE_REQUEST_LINE l
         WHERE l.PrId = pr.PrId AND l.IsActive = 1)   AS LineCount,
        -- PO count (distinct POs raised from this PR)
        (SELECT COUNT(DISTINCT pol.PoId)
         FROM proj.TBL_PURCHASE_REQUEST_LINE prl
         JOIN proj.TBL_PURCHASE_ORDER_LINE pol ON pol.PrLineId = prl.PrLineId
         JOIN proj.TBL_PURCHASE_ORDER po       ON po.PoId = pol.PoId AND po.IsActive = 1
         WHERE prl.PrId = pr.PrId AND prl.IsActive = 1 AND pol.IsActive = 1) AS PoCount,
        -- Linked PO numbers
        STUFF((
            SELECT DISTINCT ', ' + po2.PoNumber
            FROM proj.TBL_PURCHASE_REQUEST_LINE prl2
            JOIN proj.TBL_PURCHASE_ORDER_LINE pol2 ON pol2.PrLineId = prl2.PrLineId
            JOIN proj.TBL_PURCHASE_ORDER po2        ON po2.PoId = pol2.PoId AND po2.IsActive = 1
            WHERE prl2.PrId = pr.PrId AND prl2.IsActive = 1 AND pol2.IsActive = 1
            FOR XML PATH(''), TYPE).value('.','NVARCHAR(MAX)'), 1, 2, ''
        )                                              AS LinkedPOs
    FROM proj.TBL_PURCHASE_REQUEST pr
    LEFT JOIN proj.TBL_JOB j ON j.JobId = pr.JobId
    WHERE pr.IsActive = 1
      AND (@DateFrom  IS NULL OR CONVERT(DATE, pr.PrDate) >= @DateFrom)
      AND (@DateTo    IS NULL OR CONVERT(DATE, pr.PrDate) <= @DateTo)
      AND (@Status    IS NULL OR pr.Status = @Status)
      AND (@Priority  IS NULL OR pr.Priority = @Priority)
      AND (@JobId     IS NULL OR pr.JobId = @JobId)
      AND (@CreatedBy IS NULL OR pr.CreatedBy LIKE '%' + @CreatedBy + '%')
      AND (
          @NoPOOnly = 0
          OR NOT EXISTS (
              SELECT 1
              FROM proj.TBL_PURCHASE_REQUEST_LINE prl3
              JOIN proj.TBL_PURCHASE_ORDER_LINE pol3 ON pol3.PrLineId = prl3.PrLineId
              JOIN proj.TBL_PURCHASE_ORDER po3        ON po3.PoId = pol3.PoId AND po3.IsActive = 1
              WHERE prl3.PrId = pr.PrId AND prl3.IsActive = 1 AND pol3.IsActive = 1
          )
      )
    ORDER BY pr.PrDate DESC, pr.PrNumber;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportPurchaseDetails]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportPurchaseDetails];
GO
CREATE   PROCEDURE proj.sp_ReportPurchaseDetails
    @DateFrom    DATE          = NULL,
    @DateTo      DATE          = NULL,
    @ReceiptType NVARCHAR(20)  = NULL,   -- NULL=All | 'STORE' | 'JOB'
    @JobId       NVARCHAR(50)  = NULL,
    @ItemId      INT           = NULL,
    @ItemTypeId  INT           = NULL,
    @CategoryId  INT           = NULL,
    @SearchText  NVARCHAR(200) = NULL,
    @Status      NVARCHAR(50)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        r.ReceiptId,
        r.ReceiptNo,
        r.ReceiptDate,
        r.ReceiptType,
        COALESCE(rl.JobId, r.JobId)                AS JobId,
        j.ProjectName,
        r.SupplierName,
        r.PoNumber,
        r.SupplierRef,
        r.Status,
        rl.ReceiptLineId,
        rl.LineNum,
        rl.ItemId,
        i.ItemCode,
        ISNULL(NULLIF(LTRIM(RTRIM(i.ItemName)), ''), rl.ItemDesc) AS ItemDesc,
        cat.CategoryName,
        it.TypeName                                AS ItemTypeName,
        rl.Qty,
        u.UomCode                                  AS UomName,
        rl.UnitCost,
        ROUND(rl.Qty * rl.UnitCost, 2)             AS LineTotal,
        rl.IsJobStock,
        rl.Notes
    FROM  proj.TBL_STOCK_RECEIPT_LINE rl
    JOIN  proj.TBL_STOCK_RECEIPT      r   ON r.ReceiptId  = rl.ReceiptId
    LEFT JOIN proj.TBL_ITEM           i   ON i.ItemId     = rl.ItemId
    LEFT JOIN proj.TBL_ITEM_UOM       u   ON u.UomId      = rl.UomId
    LEFT JOIN proj.TBL_ITEM_CATEGORY  cat ON cat.CategoryId = i.CategoryId
    LEFT JOIN proj.TBL_ITEM_TYPE      it  ON it.ItemTypeId  = i.ItemTypeId
    LEFT JOIN proj.TBL_JOB            j   ON j.JobId      = COALESCE(rl.JobId, r.JobId)
    WHERE rl.IsActive = 1
      AND r.IsActive  = 1
      AND (@DateFrom    IS NULL OR r.ReceiptDate >= @DateFrom)
      AND (@DateTo      IS NULL OR r.ReceiptDate <= @DateTo)
      AND (@ReceiptType IS NULL OR r.ReceiptType =  @ReceiptType)
      AND (@JobId       IS NULL OR COALESCE(rl.JobId, r.JobId) = @JobId)
      AND (@ItemId      IS NULL OR rl.ItemId     =  @ItemId)
      AND (@ItemTypeId  IS NULL OR i.ItemTypeId  =  @ItemTypeId)
      -- category: exact match OR items in subcategories of the given parent
      AND (
          @CategoryId IS NULL
          OR i.CategoryId = @CategoryId
          OR i.CategoryId IN (
              SELECT CategoryId FROM proj.TBL_ITEM_CATEGORY WHERE ParentCategoryId = @CategoryId
          )
      )
      AND (@Status      IS NULL OR r.Status =  @Status)
      AND (@SearchText  IS NULL
           OR i.ItemCode  LIKE N'%' + @SearchText + N'%'
           OR i.ItemName  LIKE N'%' + @SearchText + N'%'
           OR rl.ItemDesc LIKE N'%' + @SearchText + N'%')
    ORDER BY r.ReceiptDate DESC, r.ReceiptNo, rl.LineNum;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportReceiptVouchers]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportReceiptVouchers];
GO

CREATE   PROCEDURE proj.sp_ReportReceiptVouchers
    @DateFrom   DATE          = NULL,
    @DateTo     DATE          = NULL,
    @CustomerId INT           = NULL,
    @Status     NVARCHAR(50)  = NULL,
    @CreatedBy  NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @BaseCcy NVARCHAR(10) = (SELECT ShortName FROM proj.TBL_CURRENCY WHERE IsBaseCurrency=1);

    SELECT
        rv.RvId,
        rv.RvNumber,
        rv.RvDate,
        rv.CustomerId,
        c.CustomerName,
        cur.ShortName                                           AS CurrencyShort,
        ISNULL(rv.ExchangeRate, 1)                             AS ExchangeRate,
        @BaseCcy                                               AS BaseCurrency,
        rv.PaymentMode,
        rv.ReferenceNo,
        rv.AmountReceived,
        rv.AmountReceived * ISNULL(rv.ExchangeRate, 1)         AS AmountReceivedBase,
        rv.AllocatedAmount,
        rv.AllocatedAmount * ISNULL(rv.ExchangeRate, 1)        AS AllocatedBase,
        (rv.AmountReceived - ISNULL(rv.AllocatedAmount, 0))    AS UnallocatedAmount,
        (rv.AmountReceived - ISNULL(rv.AllocatedAmount, 0))
            * ISNULL(rv.ExchangeRate, 1)                       AS UnallocatedBase,
        rv.Status,
        rv.CreatedBy,
        rv.CreatedDate
    FROM proj.TBL_RECEIPT_VOUCHER rv
    LEFT JOIN proj.TBL_CUSTOMER c   ON c.CustomerId   = rv.CustomerId
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = rv.CurrencyId
    WHERE rv.IsActive = 1
      AND (@DateFrom   IS NULL OR rv.RvDate     >= @DateFrom)
      AND (@DateTo     IS NULL OR rv.RvDate     <= @DateTo)
      AND (@CustomerId IS NULL OR rv.CustomerId  = @CustomerId)
      AND (@Status     IS NULL OR rv.Status      = @Status)
      AND (@CreatedBy  IS NULL OR rv.CreatedBy   = @CreatedBy)
    ORDER BY rv.RvDate DESC, rv.RvId DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportRTVs]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportRTVs];
GO
CREATE PROCEDURE proj.sp_ReportRTVs
    @DateFrom   DATE          = NULL,
    @DateTo     DATE          = NULL,
    @SupplierId INT           = NULL,
    @JobId      NVARCHAR(50)  = NULL,
    @Status     NVARCHAR(50)  = NULL,
    @CreatedBy  NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        r.RtvId,
        r.RtvNumber,
        r.RtvDate,
        r.Status,
        r.SupplierId,
        s.SupplierName,
        g.GrnNumber,
        po.PoNumber,
        r.JobId,
        j.ProjectName                               AS JobTitle,
        r.ReturnReason,
        cur.ShortName                               AS CurrencyShort,
        ISNULL(po.ExchangeRate, 1)                  AS ExchangeRate,
        r.TotalAmount,
        r.TotalAmount * ISNULL(po.ExchangeRate, 1)  AS TotalAmountBase,
        r.Remarks,
        r.CreatedBy,
        r.CreatedDate,
        ISNULL(lc.LineCount, 0)                     AS LineCount
    FROM proj.TBL_RETURN_TO_VENDOR r
    LEFT JOIN proj.TBL_SUPPLIER         s   ON s.SupplierId  = r.SupplierId
    LEFT JOIN proj.TBL_GRN_HEADER       g   ON g.GrnId       = r.GrnId
    LEFT JOIN proj.TBL_PURCHASE_ORDER   po  ON po.PoId       = r.PoId
    LEFT JOIN proj.TBL_CURRENCY         cur ON cur.CurrencyId = po.CurrencyId
    LEFT JOIN proj.TBL_JOB              j   ON j.JobId       = r.JobId
    LEFT JOIN (
        SELECT RtvId, COUNT(*) AS LineCount
        FROM proj.TBL_RETURN_TO_VENDOR_LINE
        GROUP BY RtvId
    ) lc ON lc.RtvId = r.RtvId
    WHERE
        r.IsActive = 1
        AND (@DateFrom   IS NULL OR r.RtvDate    >= @DateFrom)
        AND (@DateTo     IS NULL OR r.RtvDate    <= @DateTo)
        AND (@SupplierId IS NULL OR r.SupplierId  = @SupplierId)
        AND (@JobId      IS NULL OR r.JobId       = @JobId)
        AND (@Status     IS NULL OR r.Status      = @Status)
        AND (@CreatedBy  IS NULL OR r.CreatedBy   = @CreatedBy)
    ORDER BY r.RtvDate DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportSRVs]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportSRVs];
GO
CREATE PROCEDURE proj.sp_ReportSRVs
    @DateFrom  DATE          = NULL,
    @DateTo    DATE          = NULL,
    @JobId     NVARCHAR(50)  = NULL,
    @Status    NVARCHAR(50)  = NULL,
    @CreatedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        s.SrvId,
        s.SrvNo,
        CONVERT(DATE, s.SrvDate)                        AS SrvDate,
        s.SupplierName,
        s.PoNumber,
        s.JobId,
        j.ProjectName                                   AS JobTitle,
        s.Status,
        cur.ShortName                                   AS CurrencyShort,
        ISNULL(po.ExchangeRate, 1)                      AS ExchangeRate,
        s.CreatedBy,
        s.CreatedDate,
        (SELECT COUNT(*) FROM proj.TBL_SRV_LINE l
         WHERE l.SrvId = s.SrvId AND l.IsActive = 1)   AS LineCount,
        ISNULL((SELECT SUM(l.TotalCost)
         FROM proj.TBL_SRV_LINE l
         WHERE l.SrvId = s.SrvId AND l.IsActive = 1), 0) AS TotalCost,
        ISNULL((SELECT SUM(l.TotalCost)
         FROM proj.TBL_SRV_LINE l
         WHERE l.SrvId = s.SrvId AND l.IsActive = 1), 0)
            * ISNULL(po.ExchangeRate, 1)                AS TotalCostBase
    FROM proj.TBL_SRV_HEADER s
    LEFT JOIN proj.TBL_JOB              j   ON j.JobId       = s.JobId
    LEFT JOIN proj.TBL_PURCHASE_ORDER   po  ON po.PoId       = s.PoId
    LEFT JOIN proj.TBL_CURRENCY         cur ON cur.CurrencyId = po.CurrencyId
    WHERE s.IsActive = 1
      AND (@DateFrom  IS NULL OR CONVERT(DATE, s.SrvDate) >= @DateFrom)
      AND (@DateTo    IS NULL OR CONVERT(DATE, s.SrvDate) <= @DateTo)
      AND (@JobId     IS NULL OR s.JobId = @JobId)
      AND (@Status    IS NULL OR s.Status = @Status)
      AND (@CreatedBy IS NULL OR s.CreatedBy LIKE '%' + @CreatedBy + '%')
    ORDER BY s.SrvDate DESC, s.SrvNo;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportStockAdjustments]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportStockAdjustments];
GO
CREATE   PROCEDURE proj.sp_ReportStockAdjustments
    @DateFrom  DATE          = NULL,
    @DateTo    DATE          = NULL,
    @Status    NVARCHAR(50)  = NULL,
    @Reason    NVARCHAR(200) = NULL,
    @CreatedBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        a.AdjustmentId,
        a.AdjustmentNo,
        a.AdjustmentDate,
        a.Reason,
        a.Notes,
        a.Status,
        a.PostedBy,
        a.PostedDate,
        a.CreatedBy,
        a.CreatedDate,
        COUNT(l.AdjustmentLineId)                                AS LineCount,
        ISNULL(SUM(ABS(l.AdjustQty) * ISNULL(l.UnitCost, 0)), 0) AS TotalValue
    FROM  proj.TBL_STOCK_ADJUSTMENT a
    LEFT JOIN proj.TBL_STOCK_ADJUSTMENT_LINE l
           ON l.AdjustmentId = a.AdjustmentId AND ISNULL(l.IsActive, 1) = 1
    WHERE a.IsActive = 1
      AND (@DateFrom IS NULL OR a.AdjustmentDate >= @DateFrom)
      AND (@DateTo   IS NULL OR a.AdjustmentDate <= @DateTo)
      AND (@Status   IS NULL OR a.Status  = @Status)
      AND (@Reason   IS NULL OR a.Reason  = @Reason)
      AND (@CreatedBy IS NULL OR a.CreatedBy LIKE N'%' + @CreatedBy + N'%')
    GROUP BY
        a.AdjustmentId, a.AdjustmentNo, a.AdjustmentDate, a.Reason, a.Notes,
        a.Status, a.PostedBy, a.PostedDate, a.CreatedBy, a.CreatedDate
    ORDER BY a.AdjustmentDate DESC, a.AdjustmentId DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportSupplierInvoices]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportSupplierInvoices];
GO

CREATE PROCEDURE proj.sp_ReportSupplierInvoices
    @DateFrom   DATE          = NULL,
    @DateTo     DATE          = NULL,
    @SupplierId INT           = NULL,
    @Status     NVARCHAR(50)  = NULL,
    @CreatedBy  NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        si.SupplierInvoiceId,
        si.InvoiceNo,
        si.SupplierInvRef,
        si.InvoiceDate,
        si.SupplierId,
        s.SupplierName,
        cur.ShortName                                                          AS CurrencyShort,
        si.ExchangeRate,
        si.DueDate,
        si.SubTotal,
        si.TaxAmount,
        si.TotalAmount,
        -- AllocatedAmount is BASE; PV payments + DN credits, both Approved only.
        -- Divide by invoice rate for invoice-currency display.
        ROUND(paid.PaidBase / NULLIF(si.ExchangeRate, 0), 2)                   AS PaidAmount,
        si.TotalAmount - ROUND(paid.PaidBase / NULLIF(si.ExchangeRate, 0), 2)  AS BalanceAmount,
        si.Status,
        si.Notes,
        si.CreatedBy,
        si.CreatedDate
    FROM proj.TBL_SUPPLIER_INVOICE si
    JOIN  proj.TBL_SUPPLIER s      ON s.SupplierId   = si.SupplierId
    LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = si.CurrencyId
    OUTER APPLY (
        SELECT ISNULL(pv_paid.Amt, 0) + ISNULL(dn_paid.Amt, 0) AS PaidBase
        FROM (VALUES(1)) x(d)
        OUTER APPLY (
            SELECT ISNULL(SUM(a.AllocatedAmount), 0) AS Amt
            FROM   proj.TBL_PAYMENT_VOUCHER_ALLOCATION a
            JOIN   proj.TBL_PAYMENT_VOUCHER pv ON pv.PvId = a.PvId
            WHERE  a.SupplierInvoiceId = si.SupplierInvoiceId AND a.IsActive = 1
              AND  pv.Status = 'Approved' AND pv.IsActive = 1
        ) pv_paid
        OUTER APPLY (
            SELECT ISNULL(SUM(a.AllocatedAmount), 0) AS Amt
            FROM   proj.TBL_DEBIT_NOTE_ALLOCATION a
            JOIN   proj.TBL_DEBIT_NOTE dn ON dn.DnId = a.DnId
            WHERE  a.SupplierInvoiceId = si.SupplierInvoiceId AND a.IsActive = 1
              AND  dn.Status = 'Approved' AND dn.IsActive = 1
        ) dn_paid
    ) paid
    WHERE si.IsActive = 1
      AND (@DateFrom   IS NULL OR si.InvoiceDate >= @DateFrom)
      AND (@DateTo     IS NULL OR si.InvoiceDate <= @DateTo)
      AND (@SupplierId IS NULL OR si.SupplierId  =  @SupplierId)
      AND (@Status     IS NULL OR si.Status      =  @Status)
      AND (@CreatedBy  IS NULL OR si.CreatedBy LIKE N'%' + @CreatedBy + N'%')
    ORDER BY si.InvoiceDate DESC, si.SupplierInvoiceId DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReportVendorScorecard]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReportVendorScorecard];
GO

CREATE PROCEDURE proj.sp_ReportVendorScorecard
    @DateFrom   DATE = NULL,
    @DateTo     DATE = NULL,
    @SupplierId INT  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Today DATE = CAST(GETDATE() AS DATE);

    ;WITH polines AS (
        SELECT po.SupplierId, po.PoId, pol.PoLineId, po.PoDate, po.DeliveryDate,
               ISNULL(po.ExchangeRate,1) AS Rate,
               pol.OrderedQty, pol.ReceivedQty, pol.UnitPrice
        FROM proj.TBL_PURCHASE_ORDER po
        JOIN proj.TBL_PURCHASE_ORDER_LINE pol ON pol.PoId = po.PoId AND pol.IsActive = 1
        WHERE po.IsActive = 1 AND po.Status NOT IN ('Draft','Cancelled')
          AND (@DateFrom   IS NULL OR po.PoDate >= @DateFrom)
          AND (@DateTo     IS NULL OR po.PoDate <= @DateTo)
          AND (@SupplierId IS NULL OR po.SupplierId = @SupplierId)
    ),
    recv AS (
        SELECT gd.PoLineId,
               SUM(gd.ReceivedQty) AS RecvQty,
               SUM(gd.RejectedQty) AS RejQty,
               MAX(g.GrnDate)      AS LastGrnDate
        FROM proj.TBL_GRN_DETAIL gd
        JOIN proj.TBL_GRN_HEADER g ON g.GrnId = gd.GrnId AND g.IsActive = 1 AND g.Status NOT IN ('Cancelled')
        WHERE gd.IsActive = 1
        GROUP BY gd.PoLineId
    ),
    lineeval AS (
        SELECT p.SupplierId, p.PoLineId, p.PoDate, p.DeliveryDate,
               p.OrderedQty, p.ReceivedQty, p.UnitPrice, p.Rate,
               r.RecvQty, r.RejQty, r.LastGrnDate,
               CASE WHEN p.ReceivedQty >= p.OrderedQty THEN 1 ELSE 0 END AS InFull,
               CASE WHEN p.DeliveryDate IS NOT NULL AND p.ReceivedQty >= p.OrderedQty THEN 1 ELSE 0 END AS Evaluable,
               CASE WHEN p.DeliveryDate IS NOT NULL AND p.ReceivedQty >= p.OrderedQty
                         AND r.LastGrnDate IS NOT NULL AND r.LastGrnDate <= p.DeliveryDate THEN 1 ELSE 0 END AS OnTimeInFull,
               CASE WHEN r.LastGrnDate IS NOT NULL THEN DATEDIFF(DAY, p.PoDate, r.LastGrnDate) END AS LeadDays,
               (p.OrderedQty - p.ReceivedQty) * p.UnitPrice * p.Rate AS OpenBase
        FROM polines p
        LEFT JOIN recv r ON r.PoLineId = p.PoLineId
    ),
    povals AS (
        SELECT po.SupplierId,
               SUM(ISNULL(po.TotalAmount,0) * ISNULL(po.ExchangeRate,1)) AS PoValueBase,
               COUNT(*) AS PoCount
        FROM proj.TBL_PURCHASE_ORDER po
        WHERE po.IsActive = 1 AND po.Status NOT IN ('Draft','Cancelled')
          AND (@DateFrom   IS NULL OR po.PoDate >= @DateFrom)
          AND (@DateTo     IS NULL OR po.PoDate <= @DateTo)
          AND (@SupplierId IS NULL OR po.SupplierId = @SupplierId)
        GROUP BY po.SupplierId
    )
    SELECT
        s.SupplierId, s.SupplierName, s.SupplierCode,
        ISNULL(pv.PoCount, 0)                                        AS PoCount,
        ISNULL(pv.PoValueBase, 0)                                    AS PoValueBase,
        COUNT(le.PoLineId)                                           AS TotalLines,
        SUM(CASE WHEN le.ReceivedQty > 0 THEN 1 ELSE 0 END)         AS ReceivedLines,
        SUM(CASE WHEN le.OpenBase > 0 THEN 1 ELSE 0 END)           AS OpenLines,
        SUM(le.InFull)                                              AS InFullLines,
        SUM(le.Evaluable)                                          AS EvaluableLines,
        SUM(le.OnTimeInFull)                                       AS OtifLines,
        CAST(100.0 * SUM(le.OnTimeInFull) / NULLIF(SUM(le.Evaluable),0) AS DECIMAL(5,1)) AS OtifPct,
        CAST(100.0 * SUM(le.InFull)       / NULLIF(COUNT(le.PoLineId),0) AS DECIMAL(5,1)) AS FillRatePct,
        CAST(AVG(CAST(le.LeadDays AS FLOAT)) AS DECIMAL(8,1))      AS AvgLeadDays,
        SUM(ISNULL(le.RejQty,0))                                   AS RejectedQty,
        SUM(ISNULL(le.RecvQty,0))                                  AS ReceivedQtyTotal,
        CAST(100.0 * SUM(ISNULL(le.RejQty,0)) / NULLIF(SUM(ISNULL(le.RecvQty,0)),0) AS DECIMAL(5,1)) AS RejectPct,
        SUM(CASE WHEN le.OpenBase > 0 THEN le.OpenBase ELSE 0 END) AS OpenCommitmentBase,
        SUM(CASE WHEN le.DeliveryDate IS NOT NULL AND le.DeliveryDate < @Today
                      AND le.ReceivedQty < le.OrderedQty THEN 1 ELSE 0 END) AS LateOpenLines
    FROM lineeval le
    JOIN proj.TBL_SUPPLIER s ON s.SupplierId = le.SupplierId
    LEFT JOIN povals pv ON pv.SupplierId = le.SupplierId
    GROUP BY s.SupplierId, s.SupplierName, s.SupplierCode, pv.PoCount, pv.PoValueBase
    ORDER BY OtifPct ASC, OpenCommitmentBase DESC;
END
GO

IF OBJECT_ID(N'[proj].[sp_ResetPasswordWithToken]') IS NOT NULL DROP PROCEDURE [proj].[sp_ResetPasswordWithToken];
GO

CREATE   PROCEDURE proj.sp_ResetPasswordWithToken
    @TokenHash    NVARCHAR(255),
    @PasswordHash NVARCHAR(255)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @ResetId INT, @UserId INT;
    SELECT @ResetId = r.ResetId, @UserId = r.UserId
    FROM   proj.TBL_PASSWORD_RESET r
    JOIN   proj.TBL_USERS          u ON u.UserId = r.UserId
    WHERE  r.TokenHash = @TokenHash
      AND  r.IsUsed    = 0
      AND  r.ExpiresAt > GETDATE()
      AND  u.IsActive  = 1
      AND  u.IsLocked  = 0;

    IF @ResetId IS NULL
    BEGIN
        SELECT 0 AS Success,
               N'This password reset link is invalid or has expired. Please request a new one.' AS Message;
        RETURN;
    END

    UPDATE proj.TBL_USERS
    SET    PasswordHash       = @PasswordHash,
           LastPasswordChange = GETDATE(),
           ModifiedBy         = N'PasswordReset',
           ModifiedDate       = GETDATE()
    WHERE  UserId = @UserId;

    -- Mark this token (and any other outstanding ones) as used
    UPDATE proj.TBL_PASSWORD_RESET
    SET    IsUsed = 1, UsedDate = GETDATE()
    WHERE  UserId = @UserId AND IsUsed = 0;

    SELECT 1 AS Success, CAST(NULL AS NVARCHAR(200)) AS Message;
END
GO

IF OBJECT_ID(N'[proj].[sp_ResetUserPassword]') IS NOT NULL DROP PROCEDURE [proj].[sp_ResetUserPassword];
GO

CREATE   PROCEDURE proj.sp_ResetUserPassword
    @UserId       INT,
    @PasswordHash NVARCHAR(255),
    @ModifiedBy   NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM proj.TBL_USERS WHERE UserId = @UserId)
    BEGIN
        SELECT 0 AS Success, N'User not found.' AS ErrorMessage; RETURN;
    END
    UPDATE proj.TBL_USERS SET
        PasswordHash       = @PasswordHash,
        LastPasswordChange = GETDATE(),
        ModifiedBy         = @ModifiedBy,
        ModifiedDate       = GETDATE()
    WHERE UserId = @UserId;
    SELECT 1 AS Success, NULL AS ErrorMessage;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReviseBom]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReviseBom];
GO

CREATE   PROCEDURE proj.sp_ReviseBom
    @BomHeaderId  INT,
    @RevisedBy    NVARCHAR(100),
    @Reason       NVARCHAR(500),
    @PasswordHash NVARCHAR(500)
AS
BEGIN
    SET NOCOUNT ON;

    -- Validate reason
    IF LTRIM(RTRIM(ISNULL(@Reason, ''))) = ''
    BEGIN
        RAISERROR('A reason is required to revise the BOM.', 16, 1);
        RETURN;
    END

    -- Validate password against the user's own login password
    IF NOT EXISTS (
        SELECT 1 FROM proj.TBL_USERS
        WHERE UserName = @RevisedBy AND PasswordHash = @PasswordHash AND IsActive = 1
    )
    BEGIN
        RAISERROR('Incorrect password.', 16, 1);
        RETURN;
    END

    -- Must exist and be Approved
    IF NOT EXISTS (
        SELECT 1 FROM proj.TBL_BOM_HEADER
        WHERE BomHeaderId = @BomHeaderId AND BomStatus = 'Approved' AND IsActive = 1
    )
    BEGIN
        RAISERROR('BOM not found or is not in Approved status.', 16, 1);
        RETURN;
    END

    -- Reset BOM back to Draft and increment version
    UPDATE proj.TBL_BOM_HEADER
    SET  BomStatus       = 'Draft',
         BomVersion      = BomVersion + 1,
         BomApprovedBy   = NULL,
         BomApprovedDate = NULL,
         ModifiedBy      = @RevisedBy,
         ModifiedDate    = GETDATE()
    WHERE BomHeaderId = @BomHeaderId;

    -- Cancel the approval transaction so the BOM can be re-submitted
    UPDATE proj.TBL_APPROVAL_TRANSACTION
    SET  CurrentStatus  = 'Cancelled',
         FinalAction    = 'Cancelled',
         FinalActionBy  = @RevisedBy,
         FinalRemarks   = 'Cancelled — BOM revised back to Draft. Reason: ' + @Reason,
         CompletedDate  = GETDATE(),
         ModifiedBy     = @RevisedBy,
         ModifiedDate   = GETDATE()
    WHERE ModuleId      = 5   -- BOM module
      AND DocumentId    = @BomHeaderId
      AND CurrentStatus NOT IN ('Cancelled', 'Rejected');

    SELECT @BomHeaderId AS BomHeaderId;
END;
GO

IF OBJECT_ID(N'[proj].[sp_ReviseCreditNote]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReviseCreditNote];
GO

CREATE   PROCEDURE proj.sp_ReviseCreditNote
    @CnId         INT,
    @RevisedBy    NVARCHAR(100),
    @Reason       NVARCHAR(500) = NULL,
    @PasswordHash NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    BEGIN TRY
        DECLARE @Status NVARCHAR(20);
        SELECT @Status = Status FROM proj.TBL_CREDIT_NOTE WHERE CnId = @CnId AND IsActive = 1;
        IF @Status IS NULL       THROW 51000, 'Credit note not found.', 1;
        IF @Status <> 'Approved' THROW 51000, 'Only Approved credit notes can be revised.', 1;

        IF NULLIF(LTRIM(RTRIM(ISNULL(@Reason, ''))), '') IS NULL
            THROW 51000, 'A reason is required to revise an approved credit note.', 1;
        IF NULLIF(@PasswordHash, '') IS NULL
            THROW 51000, 'Password is required.', 1;

        IF NOT EXISTS (
            SELECT 1
            FROM   proj.TBL_USER_ROLES  ur
            JOIN   proj.TBL_ROLE_SECRET rs ON rs.RoleId    = ur.RoleId
            JOIN   proj.TBL_USERS       u  ON u.UserId     = ur.UserId
            WHERE  u.Username           = @RevisedBy
              AND  rs.SecretKey         = 'RV_REVISE'
              AND  rs.SecretValueHash   = @PasswordHash
        )
            THROW 51000, 'Incorrect password. You do not have permission to revise this credit note.', 1;

        DECLARE @ModId INT;
        SELECT @ModId = ModuleId FROM proj.TBL_APPROVAL_MODULE WHERE ModuleCode = 'CN';

        -- Capture affected jobs BEFORE suspending allocations
        DECLARE @Jobs TABLE (JobId NVARCHAR(50) PRIMARY KEY);
        INSERT INTO @Jobs (JobId)
        SELECT DISTINCT i.JobId
        FROM   proj.TBL_CREDIT_NOTE_ALLOCATION a
        JOIN   proj.TBL_INVOICE i ON i.InvoiceId = a.InvoiceId
        WHERE  a.CnId = @CnId AND a.IsActive = 1 AND NULLIF(i.JobId,'') IS NOT NULL;

        UPDATE proj.TBL_CREDIT_NOTE
        SET    Status        = 'Draft',
               ReviseReason  = @Reason,
               RevisedBy     = @RevisedBy,
               RevisedDate   = GETDATE(),
               ModifiedBy    = @RevisedBy,
               ModifiedDate  = GETDATE()
        WHERE  CnId = @CnId;

        UPDATE proj.TBL_CREDIT_NOTE_ALLOCATION
        SET    IsActive     = 0,
               ModifiedBy   = @RevisedBy,
               ModifiedDate = GETDATE()
        WHERE  CnId = @CnId AND IsActive = 1;

        UPDATE proj.TBL_CREDIT_NOTE
        SET    AllocatedAmount = 0,
               ModifiedDate   = GETDATE()
        WHERE  CnId = @CnId;

        UPDATE proj.TBL_APPROVAL_TRANSACTION
        SET    CurrentStatus = 'Cancelled',
               FinalAction   = 'Cancelled',
               FinalActionBy = @RevisedBy,
               FinalRemarks  = ISNULL(FinalRemarks + ' | ', '') + 'Revised — ' + @Reason,
               CompletedDate = GETDATE(),
               ModifiedBy    = @RevisedBy,
               ModifiedDate  = GETDATE()
        WHERE  ModuleId      = @ModId
          AND  DocumentId    = @CnId
          AND  CurrentStatus NOT IN ('Cancelled', 'Rejected');

        -- Recalc job credit totals for every affected job (credits now removed)
        DECLARE @J NVARCHAR(50);
        DECLARE jr CURSOR LOCAL FAST_FORWARD FOR SELECT JobId FROM @Jobs;
        OPEN jr; FETCH NEXT FROM jr INTO @J;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            EXEC proj.sp_RecalcJobCredits @J, @RevisedBy;
            FETCH NEXT FROM jr INTO @J;
        END
        CLOSE jr; DEALLOCATE jr;

        COMMIT;
        SELECT @CnId AS CnId;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        DECLARE @msg NVARCHAR(2048) = ERROR_MESSAGE();
        THROW 51000, @msg, 1;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_ReviseDebitNote]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReviseDebitNote];
GO

CREATE PROCEDURE proj.sp_ReviseDebitNote
    @DnId         INT,
    @RevisedBy    NVARCHAR(100),
    @Reason       NVARCHAR(500) = NULL,
    @PasswordHash NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    BEGIN TRY
        DECLARE @Status NVARCHAR(20);
        SELECT @Status = Status FROM proj.TBL_DEBIT_NOTE WHERE DnId = @DnId AND IsActive = 1;
        IF @Status IS NULL       THROW 51000, 'Debit note not found.', 1;
        IF @Status <> 'Approved' THROW 51000, 'Only Approved debit notes can be revised.', 1;

        IF NULLIF(LTRIM(RTRIM(ISNULL(@Reason, ''))), '') IS NULL
            THROW 51000, 'A reason is required to revise an approved debit note.', 1;
        IF NULLIF(@PasswordHash, '') IS NULL
            THROW 51000, 'Password is required.', 1;

        IF NOT EXISTS (
            SELECT 1
            FROM   proj.TBL_USER_ROLES  ur
            JOIN   proj.TBL_ROLE_SECRET rs ON rs.RoleId    = ur.RoleId
            JOIN   proj.TBL_USERS       u  ON u.UserId     = ur.UserId
            WHERE  u.Username           = @RevisedBy
              AND  rs.SecretKey         = 'PV_REVISE'
              AND  rs.SecretValueHash   = @PasswordHash
        )
            THROW 51000, 'Incorrect password. You do not have permission to revise this debit note.', 1;

        DECLARE @ModId INT;
        SELECT @ModId = ModuleId FROM proj.TBL_APPROVAL_MODULE WHERE ModuleCode = 'DN';

        UPDATE proj.TBL_DEBIT_NOTE
        SET    Status        = 'Draft',
               ReviseReason  = @Reason,
               RevisedBy     = @RevisedBy,
               RevisedDate   = GETDATE(),
               ModifiedBy    = @RevisedBy,
               ModifiedDate  = GETDATE()
        WHERE  DnId = @DnId;

        UPDATE proj.TBL_DEBIT_NOTE_ALLOCATION
        SET    IsActive     = 0,
               ModifiedBy   = @RevisedBy,
               ModifiedDate = GETDATE()
        WHERE  DnId = @DnId AND IsActive = 1;

        UPDATE proj.TBL_DEBIT_NOTE
        SET    AllocatedAmount = 0,
               ModifiedDate   = GETDATE()
        WHERE  DnId = @DnId;

        UPDATE proj.TBL_APPROVAL_TRANSACTION
        SET    CurrentStatus = 'Cancelled',
               FinalAction   = 'Cancelled',
               FinalActionBy = @RevisedBy,
               FinalRemarks  = ISNULL(FinalRemarks + ' | ', '') + 'Revised — ' + @Reason,
               CompletedDate = GETDATE(),
               ModifiedBy    = @RevisedBy,
               ModifiedDate  = GETDATE()
        WHERE  ModuleId      = @ModId
          AND  DocumentId    = @DnId
          AND  CurrentStatus NOT IN ('Cancelled', 'Rejected');

        COMMIT;
        SELECT @DnId AS DnId;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        DECLARE @msg NVARCHAR(2048) = ERROR_MESSAGE();
        THROW 51000, @msg, 1;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_ReviseInvoice]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReviseInvoice];
GO

CREATE   PROCEDURE proj.sp_ReviseInvoice
    @InvoiceId    INT,
    @Reason       NVARCHAR(500),
    @PasswordHash NVARCHAR(500),
    @RevisedBy    NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    -- 1. Invoice must exist and be Confirmed
    IF NOT EXISTS (
        SELECT 1 FROM proj.TBL_INVOICE
        WHERE InvoiceId = @InvoiceId AND Status = 'Confirmed' AND IsActive = 1
    )
        THROW 51000, 'Invoice not found or is not in Confirmed status.', 1;

    -- 2. Reason is mandatory
    IF LTRIM(RTRIM(ISNULL(@Reason, ''))) = ''
        THROW 51000, 'A reason is required to revise a confirmed invoice.', 1;

    -- 3. Block if any active (Approved) receipt voucher allocations exist
    DECLARE @RvCount   INT = 0;
    DECLARE @RvTotal   DECIMAL(18,2) = 0;
    DECLARE @RvNumbers NVARCHAR(500) = '';
    DECLARE @ErrMsg    NVARCHAR(1000);

    SELECT
        @RvCount   = COUNT(*),
        @RvTotal   = SUM(a.AllocatedAmount),
        @RvNumbers = STRING_AGG(rv.RvNumber, ', ')
    FROM proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
    JOIN proj.TBL_RECEIPT_VOUCHER rv
         ON rv.RvId = a.RvId AND rv.IsActive = 1 AND rv.Status = 'Approved'
    WHERE a.InvoiceId = @InvoiceId AND a.IsActive = 1;

    IF @RvCount > 0
    BEGIN
        SET @ErrMsg = 'Cannot revise — ' + CAST(@RvCount AS NVARCHAR) +
                      ' receipt(s) totalling ' + FORMAT(@RvTotal,'N2') +
                      ' received against this invoice (' + @RvNumbers +
                      '). Unregister all receipts first.';
        THROW 51000, @ErrMsg, 1;
    END

    -- 4. Validate password via TBL_ROLE_SECRET (SecretKey = 'INVOICE_REVISE')
    DECLARE @UserId INT;
    SELECT @UserId = UserId FROM proj.TBL_USERS
    WHERE UserName = @RevisedBy AND IsActive = 1;

    IF @UserId IS NULL
        THROW 51000, 'Revising user not found.', 1;

    IF NOT EXISTS (
        SELECT 1
        FROM   proj.TBL_USER_ROLES  ur
        JOIN   proj.TBL_ROLE_SECRET rs
               ON  rs.RoleId         = ur.RoleId
               AND rs.SecretKey       = 'INVOICE_REVISE'
               AND rs.SecretValueHash = @PasswordHash
        WHERE  ur.UserId = @UserId
    )
        THROW 51000, 'Invalid password. You are not authorised to revise confirmed invoices.', 1;

    -- 5. Revert to Draft, increment revision, stamp audit
    DECLARE @JobId NVARCHAR(50);
    SELECT @JobId = JobId FROM proj.TBL_INVOICE WHERE InvoiceId = @InvoiceId;

    UPDATE proj.TBL_INVOICE
    SET    Status       = 'Draft',
           Revision     = ISNULL(Revision, 0) + 1,
           ReviseReason = @Reason,
           RevisedBy    = @RevisedBy,
           RevisedDate  = GETDATE(),
           ModifiedBy   = @RevisedBy,
           ModifiedDate = GETDATE()
    WHERE  InvoiceId = @InvoiceId;

    -- 6. Cancel the completed approval transaction so it can be re-submitted
    UPDATE proj.TBL_APPROVAL_TRANSACTION
    SET    CurrentStatus = 'Cancelled',
           FinalAction   = 'Cancelled',
           FinalActionBy = @RevisedBy,
           FinalRemarks  = 'Cancelled — Invoice revised back to Draft. Reason: ' + @Reason,
           CompletedDate = GETDATE(),
           ModifiedBy    = @RevisedBy,
           ModifiedDate  = GETDATE()
    WHERE  ModuleId      = 3
      AND  DocumentId    = @InvoiceId
      AND  CurrentStatus NOT IN ('Cancelled', 'Rejected');

    -- 7. Recalculate job invoicing total
    IF NULLIF(@JobId, '') IS NOT NULL
        EXEC proj.sp_RecalcJobInvoicing @JobId, @RevisedBy;

    SELECT @InvoiceId AS InvoiceId;
END;
GO

IF OBJECT_ID(N'[proj].[sp_ReviseJob]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReviseJob];
GO
CREATE   PROCEDURE proj.sp_ReviseJob
    @JobId        NVARCHAR(50),
    @Reason       NVARCHAR(500),
    @RevisedBy    NVARCHAR(100),
    @PasswordHash NVARCHAR(500) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NULLIF(LTRIM(RTRIM(@Reason)), '') IS NULL
    BEGIN
        SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
               'Revision reason is required.' AS Message;
        RETURN;
    END

    IF @PasswordHash IS NULL
    BEGIN
        SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
               'Password is required to revise a job.' AS Message;
        RETURN;
    END

    DECLARE @UserId INT = (SELECT TOP 1 UserId FROM proj.TBL_USERS WHERE UserName = @RevisedBy);
    IF @UserId IS NULL
    BEGIN
        SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
               'Acting user not found.' AS Message;
        RETURN;
    END

    DECLARE @JobsMenuId   INT = (SELECT MenuId   FROM proj.TBL_MENU         WHERE MenuUrl = N'/jobs');
    DECLARE @ApproveActId INT = (SELECT ActionId FROM proj.TBL_MENU_ACTIONS WHERE MenuId  = @JobsMenuId AND ActionCode = N'APPROVE');

    IF NOT EXISTS (
        SELECT 1
        FROM   proj.TBL_USER_ROLES ur
        JOIN   proj.TBL_ROLE_SECRET rs
               ON rs.RoleId = ur.RoleId AND rs.SecretKey = N'BUDGET_PASSWORD'
        JOIN   proj.TBL_ROLE_MENU_ACTION rma
               ON rma.RoleId = ur.RoleId AND rma.MenuId = @JobsMenuId
              AND rma.ActionId = @ApproveActId AND rma.IsAllowed = 1
        WHERE  ur.UserId = @UserId
          AND  rs.SecretValueHash = @PasswordHash )
    BEGIN
        SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
               'Incorrect password, or none of your roles is allowed to authorise this action.' AS Message;
        RETURN;
    END

    DECLARE @JobStatusId INT, @StatusName NVARCHAR(50), @IsClosed BIT,
            @CurrentStageId NVARCHAR(10), @CurrentStageName NVARCHAR(100),
            @PreFreezeStageId NVARCHAR(10), @PreFreezeStageName NVARCHAR(100);

    SELECT @JobStatusId      = j.JobStatusId,
           @StatusName       = js.StatusName,
           @IsClosed         = js.IsClosed,
           @CurrentStageId   = j.JobStageId,
           @CurrentStageName = cur_stg.JobStageName,
           @PreFreezeStageId = j.PreFreezeStageId,
           @PreFreezeStageName = pre_stg.JobStageName
    FROM   proj.TBL_JOB j
    JOIN   proj.TBL_JOB_STATUS js     ON js.JobStatusId = j.JobStatusId
    LEFT JOIN proj.TBL_JOB_STAGE cur_stg ON cur_stg.JobStageId = j.JobStageId
    LEFT JOIN proj.TBL_JOB_STAGE pre_stg ON pre_stg.JobStageId = j.PreFreezeStageId
    WHERE  j.JobId = @JobId;

    IF @JobStatusId IS NULL
    BEGIN
        SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
               'Job ' + @JobId + ' not found.' AS Message;
        RETURN;
    END

    IF @IsClosed = 0
    BEGIN
        SELECT 0 AS Success, CAST(NULL AS NVARCHAR(50)) AS JobId,
               'Job ' + @JobId + ' is already Active or On Hold — no revision needed.' AS Message;
        RETURN;
    END

    -- Decide whether the stage needs to roll back.
    -- Applies when the job was Auto-freezed (status 3) AND we still hold a
    -- pre-freeze stage. We never silently rewind a Completed/Cancelled job's
    -- stage — those were manual lifecycle decisions independent of stage.
    DECLARE @RestoreStage BIT =
        CASE WHEN @JobStatusId = 3
              AND @PreFreezeStageId IS NOT NULL
              AND @PreFreezeStageId <> @CurrentStageId
             THEN 1 ELSE 0 END;

    UPDATE proj.TBL_JOB
    SET    JobStatusId        = 1,
           JobStageId         = CASE WHEN @RestoreStage = 1 THEN @PreFreezeStageId ELSE JobStageId END,
           PreFreezeStageId   = NULL,
           JobLastModifiedBy  = @RevisedBy,
           JobLastUpdatedDate = GETDATE()
    WHERE  JobId = @JobId;

    INSERT INTO proj.TBL_JOB_AUDIT (JobId, Action, Section, OldValue, NewValue, Remarks, CreatedBy, CreatedDate)
    VALUES (@JobId, N'JOB_REVISED', N'Lifecycle',
            @StatusName, N'Active', @Reason,
            @RevisedBy, GETDATE());

    -- Also write a STAGE_CHANGED audit row when we rolled the stage back,
    -- so the History tab tells the full story (freeze → revise → stage restored).
    IF @RestoreStage = 1
    BEGIN
        INSERT INTO proj.TBL_JOB_AUDIT (JobId, Action, Section, OldValue, NewValue, Remarks, CreatedBy, CreatedDate)
        VALUES (@JobId, N'STAGE_CHANGED', N'Job',
                @CurrentStageName, @PreFreezeStageName,
                N'Auto-restored on revise (rolled back from freeze stage)',
                @RevisedBy, GETDATE());
    END

    SELECT 1 AS Success, @JobId AS JobId,
           CASE WHEN @RestoreStage = 1
                THEN 'Job ' + @JobId + ' has been revised. Stage rolled back from ''' +
                     @CurrentStageName + ''' to ''' + @PreFreezeStageName + '''.'
                ELSE 'Job ' + @JobId + ' has been revised and reopened.'
           END AS Message;
END;
GO

IF OBJECT_ID(N'[proj].[sp_ReviseJobBudget]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReviseJobBudget];
GO

CREATE PROCEDURE proj.sp_ReviseJobBudget
    @JobId        NVARCHAR(50),
    @PasswordHash NVARCHAR(500),
    @RevisedBy    NVARCHAR(100),
    @Reason       NVARCHAR(500) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @Reason IS NULL OR LTRIM(RTRIM(@Reason)) = N''
    BEGIN RAISERROR('Reason is required to revise the budget.', 16, 1); RETURN; END

    DECLARE @UserId INT = (SELECT TOP 1 UserId FROM proj.TBL_USERS WHERE UserName = @RevisedBy);
    IF @UserId IS NULL
    BEGIN RAISERROR('Acting user not found.', 16, 1); RETURN; END

    DECLARE @JobsMenuId  INT = (SELECT MenuId   FROM proj.TBL_MENU         WHERE MenuUrl = '/jobs');
    DECLARE @ReviseActId INT = (SELECT ActionId FROM proj.TBL_MENU_ACTIONS WHERE MenuId = @JobsMenuId AND ActionCode = 'REVISE');

    DECLARE @HasRevisePerm BIT = CASE WHEN EXISTS (
        SELECT 1 FROM proj.TBL_USER_ROLES ur
        JOIN proj.TBL_ROLE_MENU_ACTION rma
              ON rma.RoleId = ur.RoleId AND rma.MenuId = @JobsMenuId
             AND rma.ActionId = @ReviseActId AND rma.IsAllowed = 1
        WHERE ur.UserId = @UserId
    ) THEN 1 ELSE 0 END;
    IF @HasRevisePerm = 0
    BEGIN RAISERROR('You do not have permission to revise budgets.', 16, 1); RETURN; END

    DECLARE @HasUserSecret BIT = CASE WHEN EXISTS (
        SELECT 1 FROM proj.TBL_USER_SECRET WHERE UserId = @UserId AND SecretKey = 'BUDGET_PASSWORD'
    ) THEN 1 ELSE 0 END;
    DECLARE @AuthSource NVARCHAR(20);

    IF @HasUserSecret = 1
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM proj.TBL_USER_SECRET
                       WHERE UserId = @UserId AND SecretKey = 'BUDGET_PASSWORD' AND SecretValueHash = @PasswordHash)
        BEGIN RAISERROR('Incorrect budget password.', 16, 1); RETURN; END
        SET @AuthSource = N'user';
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM proj.TBL_USER_ROLES ur
                       JOIN proj.TBL_ROLE_SECRET rs ON rs.RoleId = ur.RoleId AND rs.SecretKey = 'BUDGET_PASSWORD'
                       WHERE ur.UserId = @UserId AND rs.SecretValueHash = @PasswordHash)
        BEGIN RAISERROR('Incorrect password, and personal budget password is not set.', 16, 1); RETURN; END
        SET @AuthSource = N'role';
    END

    DECLARE @LatestRv INT = ISNULL((SELECT MAX(RvNo) FROM proj.TBL_JOB_BUDGET WHERE JobId = @JobId), -1);
    IF @LatestRv = -1
    BEGIN RAISERROR('No budget exists for this job to revise.', 16, 1); RETURN; END
    IF NOT EXISTS (SELECT 1 FROM proj.TBL_JOB_BUDGET WHERE JobId = @JobId AND RvNo = @LatestRv AND IsApproved = 1)
    BEGIN RAISERROR('Current revision is not approved yet; no need to revise.', 16, 1); RETURN; END

    DECLARE @NewRv INT = @LatestRv + 1;
    UPDATE proj.TBL_JOB_BUDGET SET IsCurrent = 0 WHERE JobId = @JobId AND RvNo = @LatestRv;

    INSERT INTO proj.TBL_JOB_BUDGET
        (JobId, CostCategoryId, RvNo, BudgetedAmount, Qty, UnitPrice, UomId, Notes,
         CurrencyId, ExchangeRate, AmountInBaseCurrency,
         CreatedBy, CreatedDate, IsApproved, IsCurrent, RevisionReason, RevisedBy, RevisedDate)
    SELECT JobId, CostCategoryId, @NewRv, BudgetedAmount, Qty, UnitPrice, UomId, Notes,
           CurrencyId, ExchangeRate, AmountInBaseCurrency,
           @RevisedBy, GETDATE(), 0, 1, @Reason, @RevisedBy, GETDATE()
    FROM proj.TBL_JOB_BUDGET
    WHERE JobId = @JobId AND RvNo = @LatestRv;

    -- Carry the item lines into the new revision so the revision is editable from
    -- the prior content (and can regenerate the BOM on re-approval).
    INSERT INTO proj.TBL_JOB_BUDGET_ITEM
        (JobId, RvNo, CostCategoryId, ItemId, Qty, UomId, UnitPrice, Notes, IsActive, CreatedBy, CreatedDate)
    SELECT JobId, @NewRv, CostCategoryId, ItemId, Qty, UomId, UnitPrice, Notes, 1, @RevisedBy, GETDATE()
    FROM proj.TBL_JOB_BUDGET_ITEM
    WHERE JobId = @JobId AND RvNo = @LatestRv AND IsActive = 1;

    INSERT INTO proj.TBL_JOB_AUDIT (JobId, Action, Section, OldValue, NewValue, Remarks, CreatedBy, CreatedDate)
    VALUES (@JobId, N'BUDGET_REVISED', N'Budget',
            CONCAT(N'Rev ', @LatestRv), CONCAT(N'Rev ', @NewRv),
            CONCAT(@Reason, N' [auth=', @AuthSource, N']'), @RevisedBy, GETDATE());

    SELECT @NewRv AS NewRvNo, @AuthSource AS AuthSource;
END
GO

IF OBJECT_ID(N'[proj].[sp_RevisePaymentVoucher]') IS NOT NULL DROP PROCEDURE [proj].[sp_RevisePaymentVoucher];
GO

-- ── sp_RevisePaymentVoucher ───────────────────────────────────────────────────
CREATE PROCEDURE proj.sp_RevisePaymentVoucher
    @PvId         INT,
    @RevisedBy    NVARCHAR(100),
    @Reason       NVARCHAR(500) = NULL,
    @PasswordHash NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    BEGIN TRY
        DECLARE @Status NVARCHAR(20);
        SELECT @Status = Status FROM proj.TBL_PAYMENT_VOUCHER WHERE PvId = @PvId AND IsActive = 1;
        IF @Status IS NULL       THROW 51000,'Payment voucher not found.',1;
        IF @Status <> 'Approved' THROW 51000,'Only Approved payment vouchers can be revised.',1;
        IF NULLIF(LTRIM(RTRIM(ISNULL(@Reason,''))),   '') IS NULL THROW 51000,'A reason is required.',1;
        IF NULLIF(@PasswordHash,'') IS NULL THROW 51000,'Password is required.',1;

        IF NOT EXISTS (
            SELECT 1 FROM proj.TBL_USER_ROLES ur
            JOIN proj.TBL_ROLE_SECRET rs ON rs.RoleId  = ur.RoleId
            JOIN proj.TBL_USERS       u  ON u.UserId   = ur.UserId
            WHERE u.Username = @RevisedBy AND rs.SecretKey = 'PV_REVISE' AND rs.SecretValueHash = @PasswordHash
        ) THROW 51000,'Incorrect password.',1;

        DECLARE @ModId INT;
        SELECT @ModId = ModuleId FROM proj.TBL_APPROVAL_MODULE WHERE ModuleCode = 'PV';

        UPDATE proj.TBL_PAYMENT_VOUCHER
        SET    Status = 'Draft', ReviseReason = @Reason, RevisedBy = @RevisedBy,
               RevisedDate = GETDATE(), ModifiedBy = @RevisedBy, ModifiedDate = GETDATE()
        WHERE  PvId = @PvId;

        UPDATE proj.TBL_APPROVAL_TRANSACTION
        SET    CurrentStatus = 'Cancelled', FinalAction = 'Cancelled', FinalActionBy = @RevisedBy,
               FinalRemarks = ISNULL(FinalRemarks+' | ','')+'Revised — '+@Reason,
               CompletedDate = GETDATE(), ModifiedBy = @RevisedBy, ModifiedDate = GETDATE()
        WHERE  ModuleId = @ModId AND DocumentId = @PvId
          AND  CurrentStatus NOT IN ('Cancelled','Rejected');

        COMMIT;
        SELECT @PvId AS PvId;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        DECLARE @msg NVARCHAR(2048) = ERROR_MESSAGE();
        THROW 51000, @msg, 1;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_RevisePO]') IS NOT NULL DROP PROCEDURE [proj].[sp_RevisePO];
GO
CREATE PROCEDURE proj.sp_RevisePO
    @PoId         INT,
    @RevisedBy    NVARCHAR(100),
    @Reason       NVARCHAR(500),
    @PasswordHash NVARCHAR(500)
AS
BEGIN
    SET NOCOUNT ON;

    -- Validate password
    IF NOT EXISTS (
        SELECT 1 FROM proj.TBL_USERS
        WHERE UserName = @RevisedBy AND PasswordHash = @PasswordHash AND IsActive = 1
    )
        RAISERROR('Incorrect password.', 16, 1);

    -- Validate reason
    IF LTRIM(RTRIM(ISNULL(@Reason, ''))) = ''
        RAISERROR('A reason is required to revise the PO.', 16, 1);

    -- Block if PO is fully received (all lines done) — partial is allowed
    DECLARE @PoStatus NVARCHAR(30);
    SELECT @PoStatus = Status
    FROM proj.TBL_PURCHASE_ORDER
    WHERE PoId = @PoId AND IsActive = 1;

    IF @PoStatus = 'Received'
        RAISERROR('Cannot revise: this PO is fully received. Use a new PO or Return to Vendor for corrections.', 16, 1);

    IF @PoStatus NOT IN ('Approved', 'Sent', 'Partial')
    BEGIN
        DECLARE @StatusMsg NVARCHAR(200) = 'Cannot revise: PO must be in Approved, Sent, or Partial status. Current status: ' + ISNULL(@PoStatus, 'Unknown') + '.';
        RAISERROR(@StatusMsg, 16, 1);
    END

    DECLARE @NewRevision INT;

    UPDATE proj.TBL_PURCHASE_ORDER
    SET    Status       = 'Draft',
           Revision     = Revision + 1,
           ModifiedBy   = @RevisedBy,
           ModifiedDate = GETDATE()
    WHERE  PoId     = @PoId
      AND  IsActive = 1;

    IF @@ROWCOUNT = 0
        RAISERROR('Purchase order not found or is inactive.', 16, 1);

    SELECT @NewRevision = Revision FROM proj.TBL_PURCHASE_ORDER WHERE PoId = @PoId;

    -- Cancel existing approval transaction so it can be re-submitted
    UPDATE proj.TBL_APPROVAL_TRANSACTION
    SET    CurrentStatus  = 'Cancelled',
           FinalAction    = 'Cancelled',
           FinalActionBy  = @RevisedBy,
           FinalRemarks   = 'Cancelled — PO revised back to Draft. Reason: ' + @Reason,
           CompletedDate  = GETDATE(),
           ModifiedBy     = @RevisedBy,
           ModifiedDate   = GETDATE()
    WHERE  ModuleId      = 2
      AND  DocumentId    = @PoId
      AND  CurrentStatus NOT IN ('Cancelled', 'Rejected');

    -- Write revision log
    INSERT INTO proj.TBL_PO_REVISION_LOG (PoId, RevisionNo, Reason, RevisedBy, RevisedDate)
    VALUES (@PoId, @NewRevision, @Reason, @RevisedBy, GETDATE());

    SELECT @PoId AS PoId;
END
GO

IF OBJECT_ID(N'[proj].[sp_RevisePR]') IS NOT NULL DROP PROCEDURE [proj].[sp_RevisePR];
GO
CREATE PROCEDURE PROJ.sp_RevisePR
    @PrId      INT,
    @RevisedBy NVARCHAR(100),
    @Reason    NVARCHAR(500)
AS
BEGIN
    SET NOCOUNT ON;

    IF LTRIM(RTRIM(ISNULL(@Reason, ''))) = ''
        RAISERROR('A reason is required to revise the PR.', 16, 1);

    DECLARE @CurrentStatus NVARCHAR(30);
    SELECT @CurrentStatus = Status
    FROM PROJ.TBL_PURCHASE_REQUEST
    WHERE PrId = @PrId AND IsActive = 1;

    IF @CurrentStatus IS NULL
        RAISERROR('Purchase Request not found or is inactive.', 16, 1);

    -- Only Approved or Partial can be revised
    -- Ordered = all lines fully covered → use Close instead
    IF @CurrentStatus NOT IN ('Approved', 'Partial')
    BEGIN
        DECLARE @StatusMsg NVARCHAR(200) = 'Cannot revise: PR must be Approved or Partial. Current status: '
            + ISNULL(@CurrentStatus, 'Unknown') + '.';
        RAISERROR(@StatusMsg, 16, 1);
    END

    -- Increment revision and reset to Draft
    UPDATE PROJ.TBL_PURCHASE_REQUEST
    SET    Status       = 'Draft',
           Revision     = Revision + 1,
           ModifiedBy   = @RevisedBy,
           ModifiedDate = GETDATE()
    WHERE  PrId = @PrId AND IsActive = 1;

    -- Cancel existing approval transaction so it can be re-submitted
    UPDATE PROJ.TBL_APPROVAL_TRANSACTION
    SET    CurrentStatus  = 'Cancelled',
           FinalAction    = 'Cancelled',
           FinalActionBy  = @RevisedBy,
           FinalRemarks   = 'Cancelled — PR revised back to Draft. Reason: ' + @Reason,
           CompletedDate  = GETDATE(),
           ModifiedBy     = @RevisedBy,
           ModifiedDate   = GETDATE()
    WHERE  ModuleId      = 1   -- PR module
      AND  DocumentId    = @PrId
      AND  CurrentStatus NOT IN ('Cancelled', 'Rejected');

    -- Log the revision
    DECLARE @NewRevision INT;
    SELECT @NewRevision = Revision FROM PROJ.TBL_PURCHASE_REQUEST WHERE PrId = @PrId;

    INSERT INTO PROJ.TBL_PR_REVISION_LOG (PrId, RevisionNo, Reason, RevisedBy, RevisedDate)
    VALUES (@PrId, @NewRevision, @Reason, @RevisedBy, GETDATE());

    SELECT @PrId AS PrId;
END
GO

IF OBJECT_ID(N'[proj].[sp_ReviseReceiptVoucher]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReviseReceiptVoucher];
GO

CREATE PROCEDURE proj.sp_ReviseReceiptVoucher
    @RvId         INT,
    @RevisedBy    NVARCHAR(100),
    @Reason       NVARCHAR(500) = NULL,
    @PasswordHash NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    BEGIN TRY
        -- ── Guards ───────────────────────────────────────────────────────────
        DECLARE @Status NVARCHAR(20);
        SELECT @Status = Status FROM proj.TBL_RECEIPT_VOUCHER WHERE RvId = @RvId AND IsActive = 1;
        IF @Status IS NULL       THROW 51000, 'Receipt voucher not found.', 1;
        IF @Status <> 'Approved' THROW 51000, 'Only Approved receipt vouchers can be revised.', 1;

        IF NULLIF(LTRIM(RTRIM(ISNULL(@Reason, ''))), '') IS NULL
            THROW 51000, 'A reason is required to revise an approved receipt voucher.', 1;

        IF NULLIF(@PasswordHash, '') IS NULL
            THROW 51000, 'Password is required.', 1;

        IF NOT EXISTS (
            SELECT 1
            FROM   proj.TBL_USER_ROLES  ur
            JOIN   proj.TBL_ROLE_SECRET rs ON rs.RoleId    = ur.RoleId
            JOIN   proj.TBL_USERS       u  ON u.UserId     = ur.UserId
            WHERE  u.Username           = @RevisedBy
              AND  rs.SecretKey         = 'RV_REVISE'
              AND  rs.SecretValueHash   = @PasswordHash
        )
            THROW 51000, 'Incorrect password. You do not have permission to revise this receipt voucher.', 1;

        -- ── Execute revision ─────────────────────────────────────────────────
        DECLARE @ModId INT;
        SELECT @ModId = ModuleId FROM proj.TBL_APPROVAL_MODULE WHERE ModuleCode = 'RV';

        UPDATE proj.TBL_RECEIPT_VOUCHER
        SET    Status       = 'Draft',
               ReviseReason = @Reason,
               RevisedBy    = @RevisedBy,
               RevisedDate  = GETDATE(),
               ModifiedBy   = @RevisedBy,
               ModifiedDate = GETDATE()
        WHERE  RvId = @RvId;

        UPDATE proj.TBL_APPROVAL_TRANSACTION
        SET    CurrentStatus = 'Cancelled',
               FinalAction   = 'Cancelled',
               FinalActionBy = @RevisedBy,
               FinalRemarks  = ISNULL(FinalRemarks + ' | ', '') + 'Revised — ' + @Reason,
               CompletedDate = GETDATE(),
               ModifiedBy    = @RevisedBy,
               ModifiedDate  = GETDATE()
        WHERE  ModuleId      = @ModId
          AND  DocumentId    = @RvId
          AND  CurrentStatus NOT IN ('Cancelled', 'Rejected');

        DECLARE @JobId NVARCHAR(50);
        DECLARE jc CURSOR LOCAL FAST_FORWARD FOR
            SELECT DISTINCT i.JobId
            FROM   proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
            JOIN   proj.TBL_INVOICE i ON i.InvoiceId = a.InvoiceId
            WHERE  a.RvId    = @RvId
              AND  a.IsActive = 1
              AND  NULLIF(i.JobId, '') IS NOT NULL;
        OPEN jc; FETCH NEXT FROM jc INTO @JobId;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            EXEC proj.sp_RecalcJobPayments @JobId, @RevisedBy;
            FETCH NEXT FROM jc INTO @JobId;
        END
        CLOSE jc; DEALLOCATE jc;

        COMMIT;
        SELECT @RvId AS RvId;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        IF CURSOR_STATUS('local', 'jc') >= 0 BEGIN CLOSE jc; DEALLOCATE jc; END
        DECLARE @msg NVARCHAR(2048) = ERROR_MESSAGE();
        THROW 51000, @msg, 1;
    END CATCH
END
GO

IF OBJECT_ID(N'[proj].[sp_ReviseSupplierInvoice]') IS NOT NULL DROP PROCEDURE [proj].[sp_ReviseSupplierInvoice];
GO

CREATE   PROCEDURE proj.sp_ReviseSupplierInvoice
    @SupplierInvoiceId  INT,
    @Reason             NVARCHAR(500),
    @PasswordHash       NVARCHAR(500),
    @RevisedBy          NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    -- 1. Invoice must exist and be in Approved status
    IF NOT EXISTS (
        SELECT 1 FROM proj.TBL_SUPPLIER_INVOICE
        WHERE SupplierInvoiceId = @SupplierInvoiceId
          AND Status = 'Approved'
          AND IsActive = 1
    )
        THROW 51000, 'Invoice not found or is not in Approved status.', 1;

    -- 2. Reason is mandatory
    IF LTRIM(RTRIM(ISNULL(@Reason, ''))) = ''
        THROW 51000, 'A reason is required to revise an approved invoice.', 1;

    -- 3. Validate password: the user must belong to a role that has
    --    SecretKey = 'INVOICE_REVISE' with the matching hash.
    --    Resolve username → UserId via TBL_USERS (UserName = @RevisedBy)
    DECLARE @UserId INT;
    SELECT @UserId = UserId FROM proj.TBL_USERS
    WHERE UserName = @RevisedBy AND IsActive = 1;

    IF @UserId IS NULL
        THROW 51000, 'Revising user not found.', 1;

    IF NOT EXISTS (
        SELECT 1
        FROM   proj.TBL_USER_ROLES  ur
        JOIN   proj.TBL_ROLE_SECRET rs
               ON rs.RoleId         = ur.RoleId
              AND rs.SecretKey       = 'INVOICE_REVISE'
              AND rs.SecretValueHash = @PasswordHash
        WHERE  ur.UserId = @UserId
    )
        THROW 51000, 'Invalid password. You are not authorised to revise approved invoices.', 1;

    -- 4. Revert to Draft, stamp revision audit
    UPDATE proj.TBL_SUPPLIER_INVOICE
    SET    Status       = 'Draft',
           ReviseReason = @Reason,
           RevisedBy    = @RevisedBy,
           RevisedDate  = GETDATE(),
           ModifiedBy   = @RevisedBy,
           ModifiedDate = GETDATE()
    WHERE  SupplierInvoiceId = @SupplierInvoiceId;
END;
GO

IF OBJECT_ID(N'[proj].[sp_SaveActionPermission]') IS NOT NULL DROP PROCEDURE [proj].[sp_SaveActionPermission];
GO

CREATE   PROCEDURE proj.sp_SaveActionPermission
    @RoleId    INT,
    @MenuId    INT,
    @ActionId  INT,
    @IsAllowed BIT
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (
        SELECT 1 FROM proj.TBL_ROLE_MENU_ACTION
        WHERE RoleId = @RoleId AND MenuId = @MenuId AND ActionId = @ActionId)
        UPDATE proj.TBL_ROLE_MENU_ACTION
        SET IsAllowed = @IsAllowed
        WHERE RoleId = @RoleId AND MenuId = @MenuId AND ActionId = @ActionId;
    ELSE
        INSERT INTO proj.TBL_ROLE_MENU_ACTION (RoleId, MenuId, ActionId, IsAllowed)
        VALUES (@RoleId, @MenuId, @ActionId, @IsAllowed);
    SELECT 1 AS Success;
END
GO

IF OBJECT_ID(N'[proj].[sp_SaveApprovalDelegate]') IS NOT NULL DROP PROCEDURE [proj].[sp_SaveApprovalDelegate];
GO

CREATE   PROCEDURE proj.sp_SaveApprovalDelegate
    @DelegateId     INT           = 0,
    @LevelId        INT,
    @OriginalUserId INT,
    @DelegateUserId INT,
    @FromDate       DATE,
    @ToDate         DATE,
    @Reason         NVARCHAR(300) = NULL,
    @IsActive       BIT           = 1,
    @SavedBy        NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    IF @OriginalUserId = @DelegateUserId
    BEGIN
        SELECT -1 AS DelegateId, 'Cannot delegate to yourself.' AS Message;
        RETURN;
    END

    IF @FromDate > @ToDate
    BEGIN
        SELECT -1 AS DelegateId, 'From Date cannot be after To Date.' AS Message;
        RETURN;
    END

    IF NOT EXISTS (SELECT 1 FROM proj.TBL_APPROVAL_LEVEL WHERE LevelId = @LevelId AND IsActive = 1)
    BEGIN
        SELECT -1 AS DelegateId, 'Approval level not found or inactive.' AS Message;
        RETURN;
    END

    IF NOT EXISTS (SELECT 1 FROM proj.TBL_USERS WHERE UserId = @OriginalUserId AND IsActive = 1)
    BEGIN
        SELECT -1 AS DelegateId, 'Original user not found.' AS Message;
        RETURN;
    END

    IF NOT EXISTS (SELECT 1 FROM proj.TBL_USERS WHERE UserId = @DelegateUserId AND IsActive = 1)
    BEGIN
        SELECT -1 AS DelegateId, 'Delegate user not found.' AS Message;
        RETURN;
    END

    IF @DelegateId = 0
    BEGIN
        INSERT INTO proj.TBL_APPROVAL_DELEGATE
            (LevelId, OriginalUserId, DelegateUserId, FromDate, ToDate, Reason, IsActive, CreatedBy)
        VALUES
            (@LevelId, @OriginalUserId, @DelegateUserId, @FromDate, @ToDate, @Reason, @IsActive, @SavedBy);
        SELECT CAST(SCOPE_IDENTITY() AS INT) AS DelegateId, 'Delegate created successfully.' AS Message;
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM proj.TBL_APPROVAL_DELEGATE WHERE DelegateId = @DelegateId)
        BEGIN
            SELECT -1 AS DelegateId, 'Delegate record not found.' AS Message;
            RETURN;
        END
        UPDATE proj.TBL_APPROVAL_DELEGATE
        SET LevelId        = @LevelId,
            OriginalUserId = @OriginalUserId,
            DelegateUserId = @DelegateUserId,
            FromDate       = @FromDate,
            ToDate         = @ToDate,
            Reason         = @Reason,
            IsActive       = @IsActive,
            ModifiedBy     = @SavedBy,
            ModifiedDate   = GETDATE()
        WHERE DelegateId = @DelegateId;
        SELECT @DelegateId AS DelegateId, 'Delegate updated successfully.' AS Message;
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SaveApprovalPolicy]') IS NOT NULL DROP PROCEDURE [proj].[sp_SaveApprovalPolicy];
GO
CREATE   PROCEDURE PROJ.sp_SaveApprovalPolicy
    @PolicyId     INT,
    @ModuleCode   NVARCHAR(20),
    @PolicyName   NVARCHAR(100),
    @Description  NVARCHAR(300) = NULL,
    @AmountFrom   DECIMAL(18,4) = NULL,
    @AmountTo     DECIMAL(18,4) = NULL,
    @IsSequential BIT           = 1,
    @IsActive     BIT           = 1,
    @SortOrder    INT           = 0,
    @SavedBy      NVARCHAR(50),
    @LevelsJson   NVARCHAR(MAX) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @ModuleId INT;
        SELECT @ModuleId = ModuleId FROM PROJ.TBL_APPROVAL_MODULE WHERE ModuleCode = @ModuleCode;
        IF @ModuleId IS NULL
        BEGIN
            SELECT -1 AS PolicyId, 'Module not found.' AS Message;
            ROLLBACK; RETURN;
        END

        DECLARE @Now         DATETIME = GETDATE();
        DECLARE @OutPolicyId INT;

        IF @PolicyId = 0
        BEGIN
            DECLARE @LevelCount INT = 0;
            IF @LevelsJson IS NOT NULL
                SELECT @LevelCount = COUNT(DISTINCT JSON_VALUE(value, '$.levelNo'))
                FROM OPENJSON(@LevelsJson);

            INSERT INTO PROJ.TBL_APPROVAL_POLICY
                (ModuleId, PolicyName, Description, AmountFrom, AmountTo,
                 TotalLevels, IsSequential, IsActive, SortOrder, CreatedBy, CreatedDate)
            VALUES
                (@ModuleId, @PolicyName, @Description, @AmountFrom, @AmountTo,
                 @LevelCount, @IsSequential, @IsActive, @SortOrder, @SavedBy, @Now);
            SET @OutPolicyId = SCOPE_IDENTITY();
        END
        ELSE
        BEGIN
            SET @OutPolicyId = @PolicyId;
            UPDATE PROJ.TBL_APPROVAL_POLICY
            SET PolicyName   = @PolicyName,  Description  = @Description,
                AmountFrom   = @AmountFrom,  AmountTo     = @AmountTo,
                IsSequential = @IsSequential, IsActive    = @IsActive,
                SortOrder    = @SortOrder,
                ModifiedBy   = @SavedBy,     ModifiedDate = @Now
            WHERE PolicyId = @PolicyId;
        END

        IF @LevelsJson IS NOT NULL
        BEGIN
            -- LevelId is now part of the payload — null/0 means "new row".
            SELECT
                CAST(NULLIF(j.LevelId, 0) AS INT)                                   AS LevelId,
                CAST(j.LevelNo AS INT)                                              AS LevelNo,
                j.LevelName,
                UPPER(LTRIM(RTRIM(j.ApproverType)))                                 AS ApproverType,
                CASE WHEN UPPER(LTRIM(RTRIM(j.ApproverType))) = 'ANY'
                     THEN NULL ELSE CAST(j.ApproverId AS INT) END                   AS ApproverId,
                CAST(ISNULL(j.IsMandatory,       1) AS BIT)                          AS IsMandatory,
                CAST(ISNULL(j.AllowSelfApproval, 0) AS BIT)                          AS AllowSelfApproval,
                CAST(ISNULL(j.TimeoutHours,      0) AS INT)                          AS TimeoutHours,
                j.OnTimeoutAction
            INTO #NewLevels
            FROM OPENJSON(@LevelsJson)
            WITH (
                LevelId           INT           '$.levelId',
                LevelNo           INT           '$.levelNo',
                LevelName         NVARCHAR(100) '$.levelName',
                ApproverType      NVARCHAR(20)  '$.approverType',
                ApproverId        INT           '$.approverId',
                IsMandatory       BIT           '$.isMandatory',
                AllowSelfApproval BIT           '$.allowSelfApproval',
                TimeoutHours      INT           '$.timeoutHours',
                OnTimeoutAction   NVARCHAR(20)  '$.onTimeoutAction'
            ) j;

            -- Guards (unchanged)
            IF EXISTS (SELECT 1 FROM #NewLevels WHERE ApproverType NOT IN ('ANY','ROLE','USER'))
            BEGIN
                SELECT -1 AS PolicyId, 'Each level must use approver type ANY, ROLE or USER.' AS Message;
                ROLLBACK; DROP TABLE #NewLevels; RETURN;
            END
            IF EXISTS (SELECT 1 FROM #NewLevels WHERE ApproverType IN ('ROLE','USER') AND ApproverId IS NULL)
            BEGIN
                SELECT -1 AS PolicyId, 'Role/User levels must have an approver selected.' AS Message;
                ROLLBACK; DROP TABLE #NewLevels; RETURN;
            END

            -- 1) Soft-delete rows whose LevelId no longer appears in the payload
            UPDATE PROJ.TBL_APPROVAL_LEVEL
            SET    IsActive = 0, ModifiedBy = @SavedBy, ModifiedDate = @Now
            WHERE  PolicyId = @OutPolicyId AND IsActive = 1
              AND  LevelId NOT IN (SELECT LevelId FROM #NewLevels WHERE LevelId IS NOT NULL);

            -- 2) Update existing rows by LevelId (allows multiple rows per LevelNo)
            UPDATE al
            SET    al.LevelNo           = nl.LevelNo,
                   al.LevelName         = nl.LevelName,
                   al.ApproverType      = nl.ApproverType,
                   al.ApproverId        = nl.ApproverId,
                   al.IsMandatory       = nl.IsMandatory,
                   al.AllowSelfApproval = nl.AllowSelfApproval,
                   al.TimeoutHours      = nl.TimeoutHours,
                   al.OnTimeoutAction   = nl.OnTimeoutAction,
                   al.IsActive          = 1,
                   al.ModifiedBy        = @SavedBy,
                   al.ModifiedDate      = @Now
            FROM   PROJ.TBL_APPROVAL_LEVEL al
            JOIN   #NewLevels nl ON nl.LevelId = al.LevelId
            WHERE  al.PolicyId = @OutPolicyId;

            -- 3) Insert NEW rows (LevelId is NULL or doesn't belong to this policy)
            INSERT INTO PROJ.TBL_APPROVAL_LEVEL
                (PolicyId, LevelNo, LevelName, ApproverType, ApproverId,
                 IsMandatory, AllowSelfApproval, TimeoutHours, OnTimeoutAction,
                 IsActive, CreatedBy, CreatedDate)
            SELECT
                @OutPolicyId,
                nl.LevelNo, nl.LevelName, nl.ApproverType, nl.ApproverId,
                nl.IsMandatory, nl.AllowSelfApproval, nl.TimeoutHours, nl.OnTimeoutAction,
                1, @SavedBy, @Now
            FROM #NewLevels nl
            WHERE nl.LevelId IS NULL
               OR NOT EXISTS (
                    SELECT 1 FROM PROJ.TBL_APPROVAL_LEVEL al
                    WHERE al.LevelId = nl.LevelId AND al.PolicyId = @OutPolicyId
               );

            DROP TABLE #NewLevels;

            -- TotalLevels = distinct LevelNo across active rows (matches engine semantics)
            UPDATE PROJ.TBL_APPROVAL_POLICY
            SET TotalLevels = (
                SELECT COUNT(DISTINCT LevelNo) FROM PROJ.TBL_APPROVAL_LEVEL
                WHERE PolicyId = @OutPolicyId AND IsActive = 1
            )
            WHERE PolicyId = @OutPolicyId;
        END

        COMMIT TRANSACTION;
        SELECT @OutPolicyId AS PolicyId, 'Saved successfully.' AS Message;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        IF OBJECT_ID('tempdb..#NewLevels') IS NOT NULL DROP TABLE #NewLevels;
        SELECT -1 AS PolicyId, ERROR_MESSAGE() AS Message;
    END CATCH
END;
GO

