IF OBJECT_ID(N'[proj].[sp_SaveEmployee]') IS NOT NULL DROP PROCEDURE [proj].[sp_SaveEmployee];
GO
CREATE   PROCEDURE proj.sp_SaveEmployee
    @EmployeeId   INT            = 0,
    @EmpCode      NVARCHAR(20),
    @EmployeeName NVARCHAR(100),
    @EmpType      NVARCHAR(20)   = 'COMPANY',
    @SupplierId   INT            = NULL,
    @IsActive     BIT            = 1,
    @SavedBy      NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (SELECT 1 FROM proj.TBL_EMPLOYEE WHERE EmpCode = @EmpCode AND EmployeeId <> @EmployeeId)
    BEGIN SELECT -1 AS EmployeeId, 'Employee code already exists.' AS Message; RETURN; END

    IF @EmpType = 'OUTSOURCED' AND @SupplierId IS NULL
    BEGIN SELECT -1 AS EmployeeId, 'A supplier must be selected for outsourced employees.' AS Message; RETURN; END

    IF @EmpType = 'COMPANY' SET @SupplierId = NULL;

    IF @EmployeeId = 0
    BEGIN
        INSERT INTO proj.TBL_EMPLOYEE
            (EmpCode, EmployeeName, EmpType, SupplierId, IsActive, CreatedBy, CreatedDate)
        VALUES (@EmpCode, @EmployeeName, @EmpType, @SupplierId, @IsActive, @SavedBy, GETDATE());
        SELECT SCOPE_IDENTITY() AS EmployeeId, 'Saved successfully.' AS Message;
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_EMPLOYEE
        SET EmpCode = @EmpCode, EmployeeName = @EmployeeName, EmpType = @EmpType,
            SupplierId = @SupplierId, IsActive = @IsActive,
            ModifiedBy = @SavedBy, ModifiedDate = GETDATE()
        WHERE EmployeeId = @EmployeeId;
        SELECT @EmployeeId AS EmployeeId, 'Saved successfully.' AS Message;
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SaveGRNQCLog]') IS NOT NULL DROP PROCEDURE [proj].[sp_SaveGRNQCLog];
GO

CREATE PROCEDURE proj.sp_SaveGRNQCLog
    @GrnId         INT,
    @CheckedBy     NVARCHAR(100),
    @Remarks       NVARCHAR(1000) = NULL,
    @ItemsJson     NVARCHAR(MAX),
    @Decision      NVARCHAR(30)   = NULL,   -- Accept | ConditionalAccept | Reject
    @DecisionNotes NVARCHAR(500)  = NULL,
    @DecisionBy    NVARCHAR(100)  = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- Validate decision is provided
    IF @Decision IS NULL OR @Decision NOT IN ('Accept', 'ConditionalAccept', 'Reject')
        RAISERROR('A valid Usage Decision (Accept, ConditionalAccept, or Reject) is required.', 16, 1);

    -- For Accept/ConditionalAccept: all required items must be checked
    IF @Decision IN ('Accept', 'ConditionalAccept')
    BEGIN
        IF EXISTS (
            SELECT 1
            FROM   proj.TBL_GRN_QC_ITEM qi
            WHERE  qi.IsRequired = 1 AND qi.IsActive = 1
              AND  NOT EXISTS (
                  SELECT 1 FROM OPENJSON(@ItemsJson)
                  WITH (qcItemId INT '$.qcItemId', isChecked BIT '$.isChecked')
                  WHERE qcItemId = qi.QcItemId AND isChecked = 1
              )
        )
            RAISERROR('All mandatory checklist items must be checked before accepting.', 16, 1);
    END

    -- For Reject: DecisionNotes (rejection reason) is required
    IF @Decision = 'Reject' AND (@DecisionNotes IS NULL OR LTRIM(RTRIM(@DecisionNotes)) = '')
        RAISERROR('A rejection reason is required when rejecting a GRN.', 16, 1);

    INSERT INTO proj.TBL_GRN_QC_LOG
        (GrnId, CheckedBy, CheckedDate, Remarks, Decision, DecisionNotes, DecisionBy, DecisionDate)
    VALUES
        (@GrnId, @CheckedBy, GETDATE(), @Remarks, @Decision, @DecisionNotes, @DecisionBy, GETDATE());

    DECLARE @QcLogId INT = SCOPE_IDENTITY();

    INSERT INTO proj.TBL_GRN_QC_LOG_DETAIL (QcLogId, QcItemId, ItemName, IsChecked, Notes)
    SELECT @QcLogId,
           j.qcItemId,
           j.itemName,
           ISNULL(j.isChecked, 0),
           NULLIF(LTRIM(RTRIM(j.notes)), '')
    FROM   OPENJSON(@ItemsJson)
    WITH (
        qcItemId  INT            '$.qcItemId',
        itemName  NVARCHAR(200)  '$.itemName',
        isChecked BIT            '$.isChecked',
        notes     NVARCHAR(500)  '$.notes'
    ) j;

    SELECT @QcLogId AS QcLogId;
END
GO

IF OBJECT_ID(N'[proj].[sp_SaveManhour]') IS NOT NULL DROP PROCEDURE [proj].[sp_SaveManhour];
GO

CREATE PROCEDURE proj.sp_SaveManhour
    @BatchId          INT           = NULL,
    @DocumentDate     DATE,
    @Remarks          NVARCHAR(500) = NULL,
    @UploadedFileName NVARCHAR(255) = NULL,
    @SavedBy          NVARCHAR(50),
    @Lines            NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @IsNew      BIT = CASE WHEN @BatchId IS NULL OR @BatchId = 0 THEN 1 ELSE 0 END;
        DECLARE @DocNo      NVARCHAR(30);
        DECLARE @NewBatchId INT;

        -- ── Parse lines into temp table ───────────────────────────────────────
        SELECT
            j.JobId, j.EmployeeId, j.Hours, j.OvertimeHours,
            ISNULL(NULLIF(j.Site, ''),  'N') AS Site,
            ISNULL(NULLIF(j.MType,''),  'M') AS MType,
            j.Remarks                        AS LineRemarks
        INTO #Lines
        FROM OPENJSON(@Lines)
        WITH (
            JobId         NVARCHAR(50)  '$.jobId',
            EmployeeId    INT           '$.employeeId',
            Hours         DECIMAL(6,2)  '$.hours',
            OvertimeHours DECIMAL(6,2)  '$.overtimeHours',
            Site          NVARCHAR(100) '$.site',
            MType         NVARCHAR(50)  '$.mType',
            Remarks       NVARCHAR(500) '$.remarks'
        ) j;

        -- ── Job status check: block closed jobs ───────────────────────────────
        DECLARE @ClosedJobs NVARCHAR(MAX);
        SELECT @ClosedJobs = STRING_AGG(x.Entry, ', ')
        FROM (
            SELECT DISTINCT l.JobId + ' (' + js.StatusName + ')' AS Entry
            FROM #Lines l
            JOIN proj.TBL_JOB        jb ON jb.JobId      = l.JobId
            JOIN proj.TBL_JOB_STATUS js ON js.JobStatusId = jb.JobStatusId
            WHERE js.IsClosed = 1
        ) x;

        IF @ClosedJobs IS NOT NULL
        BEGIN
            ROLLBACK TRANSACTION;
            SELECT -1 AS BatchId,
                   CAST(NULL AS NVARCHAR(30))  AS DocumentNo,
                   CAST(NULL AS NVARCHAR(20))  AS Status,
                   'Cannot upload manhour for closed job(s): ' + @ClosedJobs AS ErrorMessage;
            RETURN;
        END;

        -- ── Budget-approved check ─────────────────────────────────────────────
        DECLARE @UnapprovedJobs NVARCHAR(MAX);
        SELECT @UnapprovedJobs = STRING_AGG(x.Entry, ', ')
        FROM (
            SELECT DISTINCT l.JobId + ' (' + proj.fn_GetJobBudgetState(l.JobId) + ')' AS Entry
            FROM #Lines l
            WHERE proj.fn_GetJobBudgetState(l.JobId) <> N'APPROVED'
        ) x;

        IF @UnapprovedJobs IS NOT NULL
        BEGIN
            ROLLBACK TRANSACTION;
            SELECT -1 AS BatchId,
                   CAST(NULL AS NVARCHAR(30)) AS DocumentNo,
                   CAST(NULL AS NVARCHAR(20)) AS Status,
                   'Cannot upload manhour — these job(s) have no approved budget: ' + @UnapprovedJobs AS ErrorMessage;
            RETURN;
        END;

        -- ── Cross-batch duplicate check: same job + employee + date in another active batch ──
        DECLARE @Duplicates NVARCHAR(MAX);
        SELECT @Duplicates = STRING_AGG(x.Entry, ', ')
        FROM (
            SELECT DISTINCT
                l.JobId + '/' + e.EmpCode
                + ' (already in ' + existing.DocumentNo + ')' AS Entry
            FROM #Lines l
            JOIN proj.TBL_EMPLOYEE e ON e.EmployeeId = l.EmployeeId
            JOIN proj.TBL_MANHOUR existing
                ON  existing.JobId       = l.JobId
                AND existing.EmployeeId  = l.EmployeeId
                AND existing.DocumentDate= @DocumentDate
                AND existing.IsActive    = 1
                AND existing.Status     NOT IN ('Cancelled')
                AND (@IsNew = 1 OR existing.BatchId <> @BatchId)
        ) x;

        IF @Duplicates IS NOT NULL
        BEGIN
            ROLLBACK TRANSACTION;
            SELECT -1 AS BatchId,
                   CAST(NULL AS NVARCHAR(30)) AS DocumentNo,
                   CAST(NULL AS NVARCHAR(20)) AS Status,
                   'Duplicate entries — these job/employee combinations already exist for '
                   + CAST(@DocumentDate AS NVARCHAR(20)) + ': ' + @Duplicates AS ErrorMessage;
            RETURN;
        END;

        -- ── Assign BatchId / DocNo ────────────────────────────────────────────
        IF @IsNew = 1
        BEGIN
            SET @NewBatchId = NEXT VALUE FOR proj.SEQ_MANHOUR_BATCH;
            -- Document number from the MH document series (date-based: MH-yyMMdd-NNN)
            DECLARE @GenNo TABLE (DocumentNo NVARCHAR(30));
            INSERT INTO @GenNo EXEC proj.sp_GenerateMHNo;
            SELECT @DocNo = DocumentNo FROM @GenNo;
        END
        ELSE
        BEGIN
            SET @NewBatchId = @BatchId;
            SELECT TOP 1 @DocNo = DocumentNo
            FROM proj.TBL_MANHOUR
            WHERE BatchId = @BatchId AND IsActive = 1;
            DELETE FROM proj.TBL_MANHOUR WHERE BatchId = @BatchId;
        END

        -- ── Insert lines ──────────────────────────────────────────────────────
        INSERT INTO proj.TBL_MANHOUR
            (BatchId, DocumentNo, DocumentDate, JobId, EmployeeId,
             Hours, OvertimeHours, Site, MType, Remarks, Status,
             UploadedFileName, IsActive, CreatedBy, CreatedDate)
        SELECT
            @NewBatchId, @DocNo, @DocumentDate,
            l.JobId, l.EmployeeId, l.Hours, l.OvertimeHours,
            l.Site, l.MType,
            COALESCE(l.LineRemarks, @Remarks),
            'Draft', @UploadedFileName, 1, @SavedBy, GETDATE()
        FROM #Lines l;

        -- ── Patch batch-level remarks / audit on re-save ──────────────────────
        UPDATE proj.TBL_MANHOUR
        SET Remarks      = COALESCE(Remarks, @Remarks),
            ModifiedBy   = CASE WHEN @IsNew = 0 THEN @SavedBy  ELSE NULL END,
            ModifiedDate = CASE WHEN @IsNew = 0 THEN GETDATE() ELSE NULL END
        WHERE BatchId = @NewBatchId;

        COMMIT TRANSACTION;
        SELECT @NewBatchId AS BatchId, @DocNo AS DocumentNo,
               'Draft'    AS Status,  CAST(NULL AS NVARCHAR(MAX)) AS ErrorMessage;

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

IF OBJECT_ID(N'[proj].[sp_SaveManhourRate]') IS NOT NULL DROP PROCEDURE [proj].[sp_SaveManhourRate];
GO

-- ── sp_SaveManhourRate  (insert / update) ─────────────────────────────────────
CREATE   PROCEDURE proj.sp_SaveManhourRate
    @RateId       INT,
    @JobTypeId    NVARCHAR(50),
    @JobId        NVARCHAR(50),
    @EffectiveFrom DATE,
    @EffectiveTo   DATE,
    @NHRate       DECIMAL(10,4),
    @OTRate       DECIMAL(10,4),
    @Remarks      NVARCHAR(200),
    @IsActive     BIT,
    @SavedBy      NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    -- Validate dates
    IF @EffectiveTo < @EffectiveFrom
    BEGIN
        SELECT -1 AS RateId, 'Effective To must be on or after Effective From.' AS Message;
        RETURN;
    END;

    -- Warn on overlap within same scope (same JobTypeId + JobId bucket)
    IF EXISTS (
        SELECT 1 FROM proj.TBL_MANHOUR_RATE
        WHERE RateId <> @RateId
          AND IsActive = 1
          AND (JobTypeId = @JobTypeId OR (JobTypeId IS NULL AND @JobTypeId IS NULL))
          AND (JobId     = @JobId     OR (JobId     IS NULL AND @JobId     IS NULL))
          AND EffectiveFrom <= @EffectiveTo
          AND EffectiveTo   >= @EffectiveFrom
    )
    BEGIN
        SELECT -2 AS RateId, 'An active rate for the same scope already covers part of this date range.' AS Message;
        RETURN;
    END;

    IF @RateId = 0
    BEGIN
        INSERT INTO proj.TBL_MANHOUR_RATE
            (JobTypeId, JobId, EffectiveFrom, EffectiveTo, NHRate, OTRate, Remarks, IsActive, CreatedBy, CreatedDate)
        VALUES
            (NULLIF(@JobTypeId,''), NULLIF(@JobId,''), @EffectiveFrom, @EffectiveTo,
             @NHRate, @OTRate, NULLIF(@Remarks,''), @IsActive, @SavedBy, GETDATE());

        SELECT SCOPE_IDENTITY() AS RateId, 'Rate created successfully.' AS Message;
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_MANHOUR_RATE SET
            JobTypeId     = NULLIF(@JobTypeId,''),
            JobId         = NULLIF(@JobId,''),
            EffectiveFrom = @EffectiveFrom,
            EffectiveTo   = @EffectiveTo,
            NHRate        = @NHRate,
            OTRate        = @OTRate,
            Remarks       = NULLIF(@Remarks,''),
            IsActive      = @IsActive,
            ModifiedBy    = @SavedBy,
            ModifiedDate  = GETDATE()
        WHERE RateId = @RateId;

        SELECT @RateId AS RateId, 'Rate updated successfully.' AS Message;
    END;
END;
GO

IF OBJECT_ID(N'[proj].[sp_SaveMaterialOut]') IS NOT NULL DROP PROCEDURE [proj].[sp_SaveMaterialOut];
GO
CREATE PROCEDURE proj.sp_SaveMaterialOut
    @MaterialOutId  INT             = NULL,
    @SubcontractId  INT,
    @OutDate        DATE            = NULL,
    @Notes          NVARCHAR(500)   = NULL,
    @LinesJson      NVARCHAR(MAX)   = NULL,
    @ActionBy       NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        IF NOT EXISTS (
            SELECT 1 FROM proj.TBL_SUBCONTRACT_ORDER
            WHERE SubcontractId = @SubcontractId AND IsActive = 1
              AND Status IN ('Approved','InProgress')
        )
            RAISERROR('Subcontract order must be Approved or InProgress to create Material Out.', 16, 1);

        IF @OutDate IS NULL SET @OutDate = CAST(GETDATE() AS DATE);

        IF @MaterialOutId IS NULL
        BEGIN
            DECLARE @MaterialOutNo NVARCHAR(30);
            DECLARE @tMTO TABLE (DocNumber NVARCHAR(50), NewSeries INT);
            INSERT INTO @tMTO EXEC proj.sp_GetNextDocNumber 'MTO';
            SELECT @MaterialOutNo = DocNumber FROM @tMTO;

            DECLARE @VendorId INT;
            SELECT @VendorId = VendorId FROM proj.TBL_SUBCONTRACT_ORDER WHERE SubcontractId = @SubcontractId;

            INSERT INTO proj.TBL_MATERIAL_OUT
                (MaterialOutNo, SubcontractId, VendorId, OutDate, Status, Notes, CreatedBy)
            VALUES
                (@MaterialOutNo, @SubcontractId, @VendorId, @OutDate, 'Draft', @Notes, @ActionBy);

            SET @MaterialOutId = SCOPE_IDENTITY();
        END
        ELSE
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM proj.TBL_MATERIAL_OUT WHERE MaterialOutId = @MaterialOutId AND Status = 'Draft')
                RAISERROR('Only Draft Material Out documents can be edited.', 16, 1);

            UPDATE proj.TBL_MATERIAL_OUT SET
                OutDate      = @OutDate,
                Notes        = @Notes,
                ModifiedBy   = @ActionBy,
                ModifiedDate = GETDATE()
            WHERE MaterialOutId = @MaterialOutId;
        END

        IF @LinesJson IS NOT NULL
        BEGIN
            UPDATE proj.TBL_MATERIAL_OUT_LINE SET IsActive = 0
            WHERE MaterialOutId = @MaterialOutId;

            INSERT INTO proj.TBL_MATERIAL_OUT_LINE
                (MaterialOutId, ComponentId, ItemId, Qty, UomId, Remarks, IsActive)
            SELECT
                @MaterialOutId, l.ComponentId, l.ItemId, l.Qty, l.UomId, l.Remarks, 1
            FROM OPENJSON(@LinesJson) WITH (
                ComponentId INT             '$.componentId',
                ItemId      INT             '$.itemId',
                Qty         DECIMAL(18,4)   '$.qty',
                UomId       INT             '$.uomId',
                Remarks     NVARCHAR(300)   '$.remarks'
            ) l
            WHERE l.Qty > 0;
        END

        SELECT @MaterialOutId AS MaterialOutId;
    END TRY
    BEGIN CATCH
        DECLARE @ErrMsg NVARCHAR(MAX) = ERROR_MESSAGE();
        EXEC proj.sp_WriteLog @Action='sp_SaveMaterialOut', @Message=@ErrMsg, @UserId=@ActionBy;
        THROW;
    END CATCH
END;
GO

IF OBJECT_ID(N'[proj].[sp_SaveMenu]') IS NOT NULL DROP PROCEDURE [proj].[sp_SaveMenu];
GO

CREATE   PROCEDURE proj.sp_SaveMenu
    @MenuId       INT,             -- 0 = new
    @ParentMenuId INT = NULL,
    @MenuName     VARCHAR(100),
    @MenuUrl      VARCHAR(200) = NULL,
    @MenuIcon     VARCHAR(50)  = NULL,
    @MenuOrder    INT          = 0,
    @IsActive     BIT          = 1
AS
BEGIN
    SET NOCOUNT ON;

    IF @MenuId = 0
    BEGIN
        INSERT INTO proj.TBL_MENU (ParentMenuId, MenuName, MenuUrl, MenuIcon, MenuOrder, IsActive)
        VALUES (NULLIF(@ParentMenuId, 0), @MenuName, NULLIF(@MenuUrl,''), NULLIF(@MenuIcon,''), @MenuOrder, @IsActive);
        SELECT CAST(SCOPE_IDENTITY() AS INT) AS MenuId;
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_MENU
        SET ParentMenuId = NULLIF(@ParentMenuId, 0),
            MenuName     = @MenuName,
            MenuUrl      = NULLIF(@MenuUrl, ''),
            MenuIcon     = NULLIF(@MenuIcon, ''),
            MenuOrder    = @MenuOrder,
            IsActive     = @IsActive
        WHERE MenuId = @MenuId;
        SELECT @MenuId AS MenuId;
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SaveMenuPermission]') IS NOT NULL DROP PROCEDURE [proj].[sp_SaveMenuPermission];
GO

CREATE   PROCEDURE proj.sp_SaveMenuPermission
    @RoleId  INT,
    @MenuId  INT,
    @CanView BIT
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM proj.TBL_ROLE_MENU WHERE RoleId = @RoleId AND MenuId = @MenuId)
        UPDATE proj.TBL_ROLE_MENU SET CanView = @CanView WHERE RoleId = @RoleId AND MenuId = @MenuId;
    ELSE
        INSERT INTO proj.TBL_ROLE_MENU (RoleId, MenuId, CanView) VALUES (@RoleId, @MenuId, @CanView);
    SELECT 1 AS Success;
END
GO

IF OBJECT_ID(N'[proj].[sp_SavePaymentFollowup]') IS NOT NULL DROP PROCEDURE [proj].[sp_SavePaymentFollowup];
GO

-- ====================================================================
-- sp_SavePaymentFollowup
--   Insert (FollowupId = 0) or update a contact log entry.
--   Setting Outcome = 'Promised' with a PromiseDate opens a promise.
--   Returns the FollowupId.
-- ====================================================================
CREATE   PROCEDURE PROJ.sp_SavePaymentFollowup
    @FollowupId         INT,
    @CustomerId         INT,
    @ContactDate        DATE,
    @ContactPerson      NVARCHAR(150)   = NULL,
    @ContactMode        NVARCHAR(20)    = NULL,
    @Outcome            NVARCHAR(30),
    @Notes              NVARCHAR(MAX)   = NULL,
    @PromiseAmount      DECIMAL(18,2)   = NULL,
    @PromiseDate        DATE            = NULL,
    @NextFollowupDate   DATE            = NULL,
    @OutstandingSnapshot DECIMAL(18,2)  = NULL,
    @CreatedBy          NVARCHAR(100),
    @ModifiedBy         NVARCHAR(100)   = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- A promise is "Open" only when an outcome of Promised/PartialPayment carries a future-dated promise.
    DECLARE @PromiseStatus NVARCHAR(20) =
        CASE WHEN @Outcome IN ('Promised','PartialPayment') AND @PromiseDate IS NOT NULL
             THEN 'Open' ELSE 'None' END;

    IF @FollowupId = 0
    BEGIN
        INSERT INTO PROJ.TBL_PAYMENT_FOLLOWUP
            (CustomerId, ContactDate, ContactPerson, ContactMode, Outcome, Notes,
             PromiseAmount, PromiseDate, NextFollowupDate, PromiseStatus,
             OutstandingSnapshot, IsActive, CreatedBy, CreatedDate)
        VALUES
            (@CustomerId, @ContactDate, @ContactPerson, @ContactMode, @Outcome, @Notes,
             @PromiseAmount, @PromiseDate, @NextFollowupDate, @PromiseStatus,
             @OutstandingSnapshot, 1, @CreatedBy, GETDATE());

        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        UPDATE PROJ.TBL_PAYMENT_FOLLOWUP
        SET ContactDate         = @ContactDate,
            ContactPerson       = @ContactPerson,
            ContactMode         = @ContactMode,
            Outcome             = @Outcome,
            Notes               = @Notes,
            PromiseAmount       = @PromiseAmount,
            PromiseDate         = @PromiseDate,
            NextFollowupDate    = @NextFollowupDate,
            -- Preserve a manually-resolved Kept/Broken; otherwise recompute Open/None.
            PromiseStatus       = CASE WHEN PromiseStatus IN ('Kept','Broken') THEN PromiseStatus
                                       ELSE @PromiseStatus END,
            ModifiedBy          = @ModifiedBy,
            ModifiedDate        = GETDATE()
        WHERE FollowupId = @FollowupId;

        SELECT CAST(@FollowupId AS NVARCHAR(20));
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SaveSubcontractOrder]') IS NOT NULL DROP PROCEDURE [proj].[sp_SaveSubcontractOrder];
GO
CREATE PROCEDURE proj.sp_SaveSubcontractOrder
    @SubcontractId      INT             = NULL,
    @SubcontractType    NVARCHAR(20)    = 'MATERIAL_OUT',
    @VendorId           INT,
    @JobId              NVARCHAR(50)    = NULL,
    @BudgetHeaderId     INT             = NULL,
    @OutputItemId       INT,
    @OutputQty          DECIMAL(18,4)   = 0,
    @OutputUomId        INT             = NULL,
    @ServiceDescription NVARCHAR(500)   = NULL,
    @ExpectedDate       DATE            = NULL,
    @Remarks            NVARCHAR(1000)  = NULL,
    @ComponentsJson     NVARCHAR(MAX)   = NULL,
    @PoId               INT             = NULL,
    @ActionBy           NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        IF @SubcontractType NOT IN ('MATERIAL_OUT','SERVICE_ONLY')
            RAISERROR('SubcontractType must be MATERIAL_OUT or SERVICE_ONLY.', 16, 1);
        IF @OutputQty <= 0
            RAISERROR('Output quantity must be greater than zero.', 16, 1);
        IF @SubcontractId IS NULL AND @PoId IS NULL
            RAISERROR('A Purchase Order must be linked when creating a Subcontract Order.', 16, 1);

        -- On create: PO must be Approved
        IF @SubcontractId IS NULL AND @PoId IS NOT NULL
        BEGIN
            DECLARE @PoStatus NVARCHAR(20);
            SELECT @PoStatus = Status FROM proj.TBL_PURCHASE_ORDER WHERE PoId = @PoId AND IsActive = 1;
            IF @PoStatus IS NULL
                RAISERROR('Purchase Order not found.', 16, 1);
            IF @PoStatus <> 'Approved'
                RAISERROR('Only Approved Purchase Orders can be used to create a Subcontract Order.', 16, 1);
        END

        IF @SubcontractId IS NULL
        BEGIN
            DECLARE @SubcontractNo NVARCHAR(30);
            DECLARE @tSCO TABLE (DocNumber NVARCHAR(50), NewSeries INT);
            INSERT INTO @tSCO EXEC proj.sp_GetNextDocNumber 'SCO';
            SELECT @SubcontractNo = DocNumber FROM @tSCO;

            INSERT INTO proj.TBL_SUBCONTRACT_ORDER
                (SubcontractNo, SubcontractType, VendorId, JobId, BudgetHeaderId,
                 OutputItemId, OutputQty, OutputUomId, ServiceDescription,
                 ExpectedDate, Status, Remarks, PoId, CreatedBy)
            VALUES
                (@SubcontractNo, @SubcontractType, @VendorId, @JobId, @BudgetHeaderId,
                 @OutputItemId, @OutputQty, @OutputUomId, @ServiceDescription,
                 @ExpectedDate, 'Draft', @Remarks, @PoId, @ActionBy);
            SET @SubcontractId = SCOPE_IDENTITY();
        END
        ELSE
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM proj.TBL_SUBCONTRACT_ORDER WHERE SubcontractId = @SubcontractId AND IsActive = 1)
                RAISERROR('Subcontract order not found.', 16, 1);
            IF NOT EXISTS (SELECT 1 FROM proj.TBL_SUBCONTRACT_ORDER WHERE SubcontractId = @SubcontractId AND Status = 'Draft')
                RAISERROR('Only Draft orders can be edited.', 16, 1);
            UPDATE proj.TBL_SUBCONTRACT_ORDER SET
                SubcontractType     = @SubcontractType,
                VendorId            = @VendorId,
                JobId               = @JobId,
                BudgetHeaderId      = @BudgetHeaderId,
                OutputItemId        = @OutputItemId,
                OutputQty           = @OutputQty,
                OutputUomId         = @OutputUomId,
                ServiceDescription  = @ServiceDescription,
                ExpectedDate        = @ExpectedDate,
                Remarks             = @Remarks,
                PoId                = @PoId,
                ModifiedBy          = @ActionBy,
                ModifiedDate        = GETDATE()
            WHERE SubcontractId = @SubcontractId;
        END

        IF @ComponentsJson IS NOT NULL
        BEGIN
            UPDATE proj.TBL_SUBCONTRACT_COMPONENT SET IsActive = 0
            WHERE SubcontractId = @SubcontractId;

            INSERT INTO proj.TBL_SUBCONTRACT_COMPONENT
                (SubcontractId, ItemId, UomId, RequiredQty, IssuedQty, IsActive)
            SELECT
                @SubcontractId, c.ItemId, c.UomId, c.RequiredQty, 0, 1
            FROM OPENJSON(@ComponentsJson) WITH (
                ItemId      INT             '$.itemId',
                UomId       INT             '$.uomId',
                RequiredQty DECIMAL(18,4)   '$.requiredQty'
            ) c
            WHERE c.RequiredQty > 0;
        END

        SELECT @SubcontractId AS SubcontractId;
    END TRY
    BEGIN CATCH
        DECLARE @ErrMsg NVARCHAR(MAX) = ERROR_MESSAGE();
        EXEC proj.sp_WriteLog @Action='sp_SaveSubcontractOrder', @Message=@ErrMsg, @UserId=@ActionBy;
        THROW;
    END CATCH
END;
GO

IF OBJECT_ID(N'[proj].[sp_SaveSubcontractReceipt]') IS NOT NULL DROP PROCEDURE [proj].[sp_SaveSubcontractReceipt];
GO
CREATE PROCEDURE proj.sp_SaveSubcontractReceipt
    @SubcontractReceiptId INT             = NULL,
    @SubcontractId        INT,
    @ReceiptDate          DATE            = NULL,
    @ReceivedQty          DECIMAL(18,4),
    @UnitCost             DECIMAL(18,4)   = 0,
    @VendorRef            NVARCHAR(100)   = NULL,
    @Notes                NVARCHAR(500)   = NULL,
    @ActionBy             NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        IF @ReceivedQty <= 0
            RAISERROR('Received quantity must be greater than zero.', 16, 1);

        DECLARE @VendorId INT;
        DECLARE @SCStatus NVARCHAR(20);
        SELECT @VendorId = VendorId, @SCStatus = Status
        FROM proj.TBL_SUBCONTRACT_ORDER
        WHERE SubcontractId = @SubcontractId AND IsActive = 1;

        IF @VendorId IS NULL
            RAISERROR('Subcontract order not found.', 16, 1);
        IF @SCStatus NOT IN ('Approved','InProgress')
            RAISERROR('Subcontract order must be Approved or InProgress to create a receipt.', 16, 1);

        IF @ReceiptDate IS NULL SET @ReceiptDate = CAST(GETDATE() AS DATE);

        IF @SubcontractReceiptId IS NULL
        BEGIN
            DECLARE @ReceiptNo NVARCHAR(30);
            DECLARE @tSCR TABLE (DocNumber NVARCHAR(50), NewSeries INT);
            INSERT INTO @tSCR EXEC proj.sp_GetNextDocNumber 'SCR';
            SELECT @ReceiptNo = DocNumber FROM @tSCR;

            INSERT INTO proj.TBL_SUBCONTRACT_RECEIPT
                (ReceiptNo, SubcontractId, VendorId, ReceiptDate, ReceivedQty,
                 UnitCost, VendorRef, Status, Notes, CreatedBy)
            VALUES
                (@ReceiptNo, @SubcontractId, @VendorId, @ReceiptDate, @ReceivedQty,
                 @UnitCost, @VendorRef, 'Draft', @Notes, @ActionBy);

            SET @SubcontractReceiptId = SCOPE_IDENTITY();
        END
        ELSE
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM proj.TBL_SUBCONTRACT_RECEIPT
                           WHERE SubcontractReceiptId = @SubcontractReceiptId AND Status = 'Draft')
                RAISERROR('Only Draft receipts can be edited.', 16, 1);

            UPDATE proj.TBL_SUBCONTRACT_RECEIPT SET
                ReceiptDate   = @ReceiptDate,
                ReceivedQty   = @ReceivedQty,
                UnitCost      = @UnitCost,
                VendorRef     = @VendorRef,
                Notes         = @Notes,
                ModifiedBy    = @ActionBy,
                ModifiedDate  = GETDATE()
            WHERE SubcontractReceiptId = @SubcontractReceiptId;
        END

        SELECT @SubcontractReceiptId AS SubcontractReceiptId;
    END TRY
    BEGIN CATCH
        DECLARE @ErrMsg NVARCHAR(MAX) = ERROR_MESSAGE();
        EXEC proj.sp_WriteLog @Action='sp_SaveSubcontractReceipt', @Message=@ErrMsg, @UserId=@ActionBy;
        THROW;
    END CATCH
END;
GO

