IF OBJECT_ID(N'[proj].[sp_SearchAdjustments]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchAdjustments];
GO
CREATE   PROCEDURE proj.sp_SearchAdjustments
    @SearchText    NVARCHAR(100) = NULL,
    @Status        NVARCHAR(100) = NULL,
    @Reason        NVARCHAR(50)  = NULL,
    @DateFrom      NVARCHAR(20)  = NULL,
    @DateTo        NVARCHAR(20)  = NULL,
    @ItemTypeId    INT           = NULL,
    @CategoryId    INT           = NULL,
    @SubCategoryId INT           = NULL,
    @ItemId        INT           = NULL,
    @PageNumber    INT           = 1,
    @PageSize      INT           = 20,
    @SortColumn    NVARCHAR(50)  = 'AdjustmentDate',
    @SortDirection NVARCHAR(4)   = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    SET @SearchText = NULLIF(LTRIM(RTRIM(@SearchText)), '');

    ;WITH Filtered AS (
        SELECT a.AdjustmentId, a.AdjustmentNo, a.AdjustmentDate,
               COALESCE(
                   (SELECT vl.ItemDescription FROM proj.TBL_VLIST vl
                    WHERE vl.TypeName='Inventory' AND vl.ListName='AdjustmentReason' AND vl.ItemValue = a.Reason),
                   (SELECT STUFF((
                       SELECT DISTINCT ', ' + ISNULL(vl2.ItemDescription, l2.Reason)
                       FROM proj.TBL_STOCK_ADJUSTMENT_LINE l2
                       LEFT JOIN proj.TBL_VLIST vl2
                           ON vl2.TypeName='Inventory' AND vl2.ListName='AdjustmentReason' AND vl2.ItemValue = l2.Reason
                       WHERE l2.AdjustmentId = a.AdjustmentId AND l2.IsActive = 1 AND l2.Reason IS NOT NULL
                       FOR XML PATH(''), TYPE
                   ).value('.', 'NVARCHAR(MAX)'), 1, 2, ''))
               ) AS Reason,
               a.Notes, a.Status,
               a.CreatedBy, a.CreatedDate,
               (SELECT COUNT(*)                          FROM proj.TBL_STOCK_ADJUSTMENT_LINE l WHERE l.AdjustmentId=a.AdjustmentId AND l.IsActive=1) AS LineCount,
               (SELECT ISNULL(SUM(ABS(l.AdjustQty)*l.UnitCost),0) FROM proj.TBL_STOCK_ADJUSTMENT_LINE l WHERE l.AdjustmentId=a.AdjustmentId AND l.IsActive=1) AS TotalValue,
               COUNT(*) OVER() AS TotalRows
        FROM proj.TBL_STOCK_ADJUSTMENT a
        WHERE a.IsActive = 1
          AND (@SearchText IS NULL OR a.AdjustmentNo LIKE '%'+@SearchText+'%' OR a.Notes LIKE '%'+@SearchText+'%' OR a.CreatedBy LIKE '%'+@SearchText+'%')
          AND (@Status   IS NULL OR @Status = '' OR CHARINDEX(','+a.Status+',', ','+@Status+',') > 0)
          AND (@Reason   IS NULL OR @Reason = '' OR a.Reason = @Reason
               OR EXISTS (SELECT 1 FROM proj.TBL_STOCK_ADJUSTMENT_LINE l WHERE l.AdjustmentId=a.AdjustmentId AND l.IsActive=1 AND l.Reason=@Reason))
          AND (@DateFrom IS NULL OR @DateFrom = '' OR a.AdjustmentDate >= CAST(@DateFrom AS DATE))
          AND (@DateTo   IS NULL OR @DateTo   = '' OR a.AdjustmentDate <= CAST(@DateTo   AS DATE))
          AND (@ItemId   IS NULL OR EXISTS (
                  SELECT 1 FROM proj.TBL_STOCK_ADJUSTMENT_LINE al
                  WHERE al.AdjustmentId = a.AdjustmentId AND al.IsActive = 1 AND al.ItemId = @ItemId))
          AND (@ItemTypeId IS NULL OR EXISTS (
                  SELECT 1 FROM proj.TBL_STOCK_ADJUSTMENT_LINE al
                  JOIN   proj.TBL_ITEM ai ON ai.ItemId = al.ItemId
                  WHERE  al.AdjustmentId = a.AdjustmentId AND al.IsActive = 1 AND ai.ItemTypeId = @ItemTypeId))
          AND (
                  (@CategoryId IS NULL AND @SubCategoryId IS NULL)
               OR (@SubCategoryId IS NOT NULL AND EXISTS (
                      SELECT 1 FROM proj.TBL_STOCK_ADJUSTMENT_LINE al
                      JOIN   proj.TBL_ITEM ai ON ai.ItemId = al.ItemId
                      WHERE  al.AdjustmentId = a.AdjustmentId AND al.IsActive = 1 AND ai.CategoryId = @SubCategoryId))
               OR (@SubCategoryId IS NULL AND @CategoryId IS NOT NULL AND EXISTS (
                      SELECT 1 FROM proj.TBL_STOCK_ADJUSTMENT_LINE al
                      JOIN   proj.TBL_ITEM ai ON ai.ItemId = al.ItemId
                      WHERE  al.AdjustmentId = a.AdjustmentId AND al.IsActive = 1
                        AND (ai.CategoryId = @CategoryId
                             OR ai.CategoryId IN (SELECT CategoryId FROM proj.TBL_ITEM_CATEGORY WHERE ParentCategoryId = @CategoryId))))
          )
    )
    SELECT * FROM Filtered
    ORDER BY
        CASE WHEN @SortColumn='AdjustmentNo'   AND @SortDirection='ASC'  THEN AdjustmentNo   END ASC,
        CASE WHEN @SortColumn='AdjustmentNo'   AND @SortDirection='DESC' THEN AdjustmentNo   END DESC,
        CASE WHEN @SortColumn='Status'         AND @SortDirection='ASC'  THEN Status         END ASC,
        CASE WHEN @SortColumn='Status'         AND @SortDirection='DESC' THEN Status         END DESC,
        CASE WHEN @SortColumn='AdjustmentDate' AND @SortDirection='ASC'  THEN AdjustmentDate END ASC,
        CASE WHEN @SortColumn='AdjustmentDate' AND @SortDirection='DESC' THEN AdjustmentDate END DESC,
        AdjustmentId DESC
    OFFSET (@PageNumber-1)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO

IF OBJECT_ID(N'[proj].[sp_SearchAppLog]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchAppLog];
GO
CREATE   PROCEDURE proj.sp_SearchAppLog
    @DateFrom    DATE          = NULL,
    @DateTo      DATE          = NULL,
    @LogLevel    NVARCHAR(20)  = NULL,
    @Source      NVARCHAR(20)  = NULL,   -- 'SERVER' | 'CLIENT' | NULL=all
    @Controller  NVARCHAR(100) = NULL,
    @UserId      NVARCHAR(100) = NULL,
    @SearchText  NVARCHAR(200) = NULL,
    @PageNumber  INT           = 1,
    @PageSize    INT           = 50
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

    ;WITH Filtered AS (
        SELECT
            LogId, LogLevel, Controller, Action, Message, StackTrace,
            InnerException, RequestPath, UserId, IpAddress, LogDate,
            CASE WHEN Controller LIKE 'CLIENT%' THEN 'CLIENT' ELSE 'SERVER' END AS Source,
            COUNT(*) OVER() AS TotalRows
        FROM proj.TBL_APP_LOG
        WHERE (@DateFrom   IS NULL OR CAST(LogDate AS DATE) >= @DateFrom)
          AND (@DateTo     IS NULL OR CAST(LogDate AS DATE) <= @DateTo)
          AND (@LogLevel   IS NULL OR LogLevel = @LogLevel)
          AND (@Source     IS NULL
               OR (@Source = 'CLIENT' AND Controller LIKE 'CLIENT%')
               OR (@Source = 'SERVER' AND (Controller IS NULL OR Controller NOT LIKE 'CLIENT%')))
          AND (@Controller IS NULL OR Controller LIKE N'%' + @Controller + N'%')
          AND (@UserId     IS NULL OR UserId LIKE N'%' + @UserId + N'%')
          AND (@SearchText IS NULL
               OR Message      LIKE N'%' + @SearchText + N'%'
               OR Action       LIKE N'%' + @SearchText + N'%'
               OR RequestPath  LIKE N'%' + @SearchText + N'%'
               OR StackTrace   LIKE N'%' + @SearchText + N'%')
    )
    SELECT *
    FROM   Filtered
    ORDER  BY LogId DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO

IF OBJECT_ID(N'[proj].[sp_SearchBoms]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchBoms];
GO

CREATE PROCEDURE proj.sp_SearchBoms
    @SearchText          NVARCHAR(100) = NULL,
    @JobId               NVARCHAR(50)  = NULL,
    @BomStatus           NVARCHAR(20)  = NULL,
    @DateFrom            DATE          = NULL,
    @DateTo              DATE          = NULL,
    @ExcludeClosedStatus BIT           = 0,
    @PageNumber          INT           = 1,
    @PageSize            INT           = 20,
    @SortColumn          NVARCHAR(50)  = 'BomDate',
    @SortDirection       NVARCHAR(4)   = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;
    WITH cte AS (
        SELECT
            h.BomHeaderId, h.JobId, h.JobTypeId,
            h.BomDate, h.BomDescription, h.BomVersion,
            h.BomStatus, h.TotalBomValue,
            h.BomApprovedBy, h.BomApprovedDate,
            h.CreatedBy, h.CreatedDate, h.ModifiedBy, h.ModifiedDate,
            j.JobDescription,
            c.CustomerName,
            jt.JobTypeName,
            COUNT(d.BomId)       AS LineCount,
            COUNT(*) OVER ()     AS TotalRows
        FROM proj.TBL_BOM_HEADER h
        LEFT JOIN proj.TBL_JOB          j   ON j.JobId       = h.JobId
        LEFT JOIN proj.TBL_CUSTOMER     c   ON c.CustomerId  = j.CustomerId
        LEFT JOIN proj.TBL_JOBTYPE      jt  ON jt.JobTypeId  = j.JobTypeId
        LEFT JOIN proj.TBL_JOB_STATUS   jst ON jst.JobStatusId = j.JobStatusId
        LEFT JOIN proj.TBL_BOM_DETAILS  d   ON d.BomHeaderId = h.BomHeaderId AND d.IsActive = 1
        WHERE h.IsActive = 1
          AND (@JobId     IS NULL OR h.JobId     = @JobId)
          AND (@BomStatus IS NULL OR h.BomStatus = @BomStatus)
          AND (@DateFrom  IS NULL OR h.BomDate  >= @DateFrom)
          AND (@DateTo    IS NULL OR h.BomDate  <= @DateTo)
          AND (@SearchText IS NULL
               OR h.JobId LIKE N'%'+@SearchText+N'%'
               OR j.JobDescription LIKE N'%'+@SearchText+N'%'
               OR c.CustomerName   LIKE N'%'+@SearchText+N'%')
          AND (@ExcludeClosedStatus = 0 OR ISNULL(jst.IsClosed, 0) = 0)
        GROUP BY h.BomHeaderId, h.JobId, h.JobTypeId, h.BomDate, h.BomDescription,
                 h.BomVersion, h.BomStatus, h.TotalBomValue, h.BomApprovedBy,
                 h.BomApprovedDate, h.CreatedBy, h.CreatedDate, h.ModifiedBy, h.ModifiedDate,
                 j.JobDescription, c.CustomerName, jt.JobTypeName
    )
    SELECT * FROM cte
    ORDER BY
        CASE WHEN @SortColumn='JobId'    AND @SortDirection='ASC'  THEN JobId    END ASC,
        CASE WHEN @SortColumn='JobId'    AND @SortDirection='DESC' THEN JobId    END DESC,
        CASE WHEN @SortColumn='BomDate'  AND @SortDirection='ASC'  THEN BomDate  END ASC,
        CASE WHEN @SortColumn='BomStatus'AND @SortDirection='ASC'  THEN BomStatus END ASC,
        CASE WHEN @SortColumn='BomStatus'AND @SortDirection='DESC' THEN BomStatus END DESC,
        BomDate DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO

IF OBJECT_ID(N'[proj].[sp_SearchCreditNotes]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchCreditNotes];
GO

CREATE PROCEDURE proj.sp_SearchCreditNotes
    @SearchText    NVARCHAR(100) = NULL,
    @CustomerId    INT           = NULL,
    @Status        NVARCHAR(20)  = NULL,
    @DateFrom      DATE          = NULL,
    @DateTo        DATE          = NULL,
    @PageNumber    INT           = 1,
    @PageSize      INT           = 20,
    @SortColumn    NVARCHAR(50)  = 'CnDate',
    @SortDirection NVARCHAR(4)   = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

    ;WITH base AS (
        SELECT cn.CnId, cn.CnNumber, cn.CnDate, cn.CustomerId, c.CustomerName,
               cn.CreditAmount, cn.AllocatedAmount,
               (cn.CreditAmount - cn.AllocatedAmount) AS UnallocatedAmount,
               cn.CreditType, cn.Status,
               COUNT(*) OVER() AS TotalRows
        FROM proj.TBL_CREDIT_NOTE cn
        LEFT JOIN proj.TBL_CUSTOMER c ON c.CustomerId = cn.CustomerId
        WHERE cn.IsActive = 1
          AND (@SearchText IS NULL OR cn.CnNumber LIKE '%'+@SearchText+'%'
                                   OR c.CustomerName LIKE '%'+@SearchText+'%'
                                   OR cn.Reason LIKE '%'+@SearchText+'%')
          AND (@CustomerId IS NULL OR cn.CustomerId = @CustomerId)
          AND (@Status     IS NULL OR cn.Status     = @Status)
          AND (@DateFrom   IS NULL OR cn.CnDate    >= @DateFrom)
          AND (@DateTo     IS NULL OR cn.CnDate    <= @DateTo)
    )
    SELECT * FROM base
    ORDER BY
        CASE WHEN @SortColumn='CnNumber' AND @SortDirection='ASC'  THEN CnNumber END ASC,
        CASE WHEN @SortColumn='CnNumber' AND @SortDirection='DESC' THEN CnNumber END DESC,
        CASE WHEN @SortColumn='CnDate'   AND @SortDirection='ASC'  THEN CnDate   END ASC,
        CASE WHEN @SortColumn='CnDate'   AND @SortDirection='DESC' THEN CnDate   END DESC,
        CASE WHEN @SortColumn='CustomerName' AND @SortDirection='ASC'  THEN CustomerName END ASC,
        CASE WHEN @SortColumn='CustomerName' AND @SortDirection='DESC' THEN CustomerName END DESC,
        CnId DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO

IF OBJECT_ID(N'[proj].[sp_SearchCustomers]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchCustomers];
GO

CREATE   PROCEDURE [PROJ].[sp_SearchCustomers]
    @SearchText         NVARCHAR(200)  = NULL,
    @CustomerCategoryId INT            = NULL,
    @CustomerType       NVARCHAR(50)   = NULL,
    @CurrencyId         INT            = NULL,
    @PaymentTermsId     INT            = NULL,
    @CreditHold         BIT            = NULL,
    @IsActive           BIT            = NULL,
    @CreditFlag         NVARCHAR(10)   = NULL,
    @PageNumber         INT            = 1,
    @PageSize           INT            = 20,
    @SortColumn         NVARCHAR(50)   = 'CustomerName',
    @SortDirection      NVARCHAR(4)    = 'ASC'
AS
BEGIN
    SET NOCOUNT ON;

    IF @SortDirection NOT IN ('ASC','DESC') SET @SortDirection = 'ASC';
    IF @SortColumn NOT IN (
        'CustomerCode','CustomerName','CustomerShortName','CustomerType',
        'CustomerCategoryName','CurrencyName','PaymentTermName',
        'CreditLimit','CreditDays','Mobile','Email','CreditFlag','StatusLabel','SalesPerson'
    ) SET @SortColumn = 'CustomerName';

    -- total count first
    DECLARE @TotalRows INT;
    SELECT @TotalRows = COUNT(*)
    FROM VW_CUSTOMER
    WHERE
        (@SearchText IS NULL OR @SearchText = '' OR
            CustomerCode      LIKE '%' + @SearchText + '%' OR
            CustomerName      LIKE '%' + @SearchText + '%' OR
            CustomerShortName LIKE '%' + @SearchText + '%' OR
            Mobile            LIKE '%' + @SearchText + '%' OR
            Email             LIKE '%' + @SearchText + '%' OR
            Phone             LIKE '%' + @SearchText + '%' OR
            VatNumber         LIKE '%' + @SearchText + '%' OR
            SalesPerson       LIKE '%' + @SearchText + '%')
        AND (@CustomerCategoryId IS NULL OR CustomerCategoryId = @CustomerCategoryId)
        AND (@CustomerType       IS NULL OR CustomerType        = @CustomerType)
        AND (@CurrencyId         IS NULL OR CurrencyId          = @CurrencyId)
        AND (@PaymentTermsId     IS NULL OR PaymentTermsId      = @PaymentTermsId)
        AND (@CreditHold         IS NULL OR CreditHold          = @CreditHold)
        AND (@IsActive           IS NULL OR IsActive            = @IsActive)
        AND (@CreditFlag         IS NULL OR CreditFlag          = @CreditFlag);

    -- paged data
    SELECT
        CustomerId, CustomerCode, CustomerName, CustomerShortName, CustomerRef,
        CustomerCategoryId, CustomerCategoryName, CustomerType, SalesPerson,
        Phone, Mobile, Email, Web,
        CurrencyId, CurrencyName, CurrencyShortName, CurrencySymbol,
        PaymentTermsId, PaymentTermName, PaymentTermDays,
        CreditLimit, CreditDays,
        VatNumber, TaxNumber,
        CreditHold, CreditHoldBy, CreditHoldNote,
        CreditFlag, CreditFlagLabel,
        IsActive, StatusLabel,
        Remarks, CreatedBy, ModifiedBy,
        @TotalRows AS TotalRows
    FROM VW_CUSTOMER
    WHERE
        (@SearchText IS NULL OR @SearchText = '' OR
            CustomerCode      LIKE '%' + @SearchText + '%' OR
            CustomerName      LIKE '%' + @SearchText + '%' OR
            CustomerShortName LIKE '%' + @SearchText + '%' OR
            Mobile            LIKE '%' + @SearchText + '%' OR
            Email             LIKE '%' + @SearchText + '%' OR
            Phone             LIKE '%' + @SearchText + '%' OR
            VatNumber         LIKE '%' + @SearchText + '%' OR
            SalesPerson       LIKE '%' + @SearchText + '%')
        AND (@CustomerCategoryId IS NULL OR CustomerCategoryId = @CustomerCategoryId)
        AND (@CustomerType       IS NULL OR CustomerType        = @CustomerType)
        AND (@CurrencyId         IS NULL OR CurrencyId          = @CurrencyId)
        AND (@PaymentTermsId     IS NULL OR PaymentTermsId      = @PaymentTermsId)
        AND (@CreditHold         IS NULL OR CreditHold          = @CreditHold)
        AND (@IsActive           IS NULL OR IsActive            = @IsActive)
        AND (@CreditFlag         IS NULL OR CreditFlag          = @CreditFlag)
    ORDER BY
        CASE WHEN @SortDirection='ASC' THEN
            CASE @SortColumn
                WHEN 'CustomerCode'         THEN CustomerCode
                WHEN 'CustomerName'         THEN CustomerName
                WHEN 'CustomerShortName'    THEN CustomerShortName
                WHEN 'CustomerType'         THEN CustomerType
                WHEN 'CustomerCategoryName' THEN CustomerCategoryName
                WHEN 'CurrencyName'         THEN CurrencyName
                WHEN 'PaymentTermName'      THEN PaymentTermName
                WHEN 'Mobile'               THEN Mobile
                WHEN 'Email'                THEN Email
                WHEN 'CreditFlag'           THEN CreditFlag
                WHEN 'StatusLabel'          THEN StatusLabel
                WHEN 'SalesPerson'          THEN SalesPerson
            END
        END ASC,
        CASE WHEN @SortDirection='DESC' THEN
            CASE @SortColumn
                WHEN 'CustomerCode'         THEN CustomerCode
                WHEN 'CustomerName'         THEN CustomerName
                WHEN 'CustomerShortName'    THEN CustomerShortName
                WHEN 'CustomerType'         THEN CustomerType
                WHEN 'CustomerCategoryName' THEN CustomerCategoryName
                WHEN 'CurrencyName'         THEN CurrencyName
                WHEN 'PaymentTermName'      THEN PaymentTermName
                WHEN 'Mobile'               THEN Mobile
                WHEN 'Email'                THEN Email
                WHEN 'CreditFlag'           THEN CreditFlag
                WHEN 'StatusLabel'          THEN StatusLabel
                WHEN 'SalesPerson'          THEN SalesPerson
            END
        END DESC,
        CASE WHEN @SortDirection='ASC'  AND @SortColumn='CreditLimit' THEN CreditLimit END ASC,
        CASE WHEN @SortDirection='DESC' AND @SortColumn='CreditLimit' THEN CreditLimit END DESC,
        CASE WHEN @SortDirection='ASC'  AND @SortColumn='CreditDays'  THEN CreditDays  END ASC,
        CASE WHEN @SortDirection='DESC' AND @SortColumn='CreditDays'  THEN CreditDays  END DESC,
        CustomerName ASC
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;
END
GO

IF OBJECT_ID(N'[proj].[sp_SearchDebitNotes]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchDebitNotes];
GO

CREATE PROCEDURE proj.sp_SearchDebitNotes
    @SearchText    NVARCHAR(100) = NULL,
    @SupplierId    INT           = NULL,
    @Status        NVARCHAR(20)  = NULL,
    @DateFrom      DATE          = NULL,
    @DateTo        DATE          = NULL,
    @PageNumber    INT           = 1,
    @PageSize      INT           = 20,
    @SortColumn    NVARCHAR(50)  = 'DnDate',
    @SortDirection NVARCHAR(4)   = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

    ;WITH base AS (
        SELECT dn.DnId, dn.DnNumber, dn.DnDate, dn.SupplierId,
               s.SupplierName, s.SupplierCode,
               dn.DebitAmount, dn.AllocatedAmount,
               (dn.DebitAmount - dn.AllocatedAmount) AS UnallocatedAmount,
               dn.DebitType, dn.Status,
               COUNT(*) OVER() AS TotalRows
        FROM proj.TBL_DEBIT_NOTE dn
        LEFT JOIN proj.TBL_SUPPLIER s ON s.SupplierId = dn.SupplierId
        WHERE dn.IsActive = 1
          AND (@SearchText IS NULL OR dn.DnNumber LIKE '%'+@SearchText+'%'
                                   OR s.SupplierName LIKE '%'+@SearchText+'%'
                                   OR dn.Reason LIKE '%'+@SearchText+'%')
          AND (@SupplierId IS NULL OR dn.SupplierId = @SupplierId)
          AND (@Status     IS NULL OR dn.Status     = @Status)
          AND (@DateFrom   IS NULL OR dn.DnDate    >= @DateFrom)
          AND (@DateTo     IS NULL OR dn.DnDate    <= @DateTo)
    )
    SELECT * FROM base
    ORDER BY
        CASE WHEN @SortColumn='DnNumber' AND @SortDirection='ASC'  THEN DnNumber END ASC,
        CASE WHEN @SortColumn='DnNumber' AND @SortDirection='DESC' THEN DnNumber END DESC,
        CASE WHEN @SortColumn='DnDate'   AND @SortDirection='ASC'  THEN DnDate   END ASC,
        CASE WHEN @SortColumn='DnDate'   AND @SortDirection='DESC' THEN DnDate   END DESC,
        CASE WHEN @SortColumn='SupplierName' AND @SortDirection='ASC'  THEN SupplierName END ASC,
        CASE WHEN @SortColumn='SupplierName' AND @SortDirection='DESC' THEN SupplierName END DESC,
        DnId DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO

IF OBJECT_ID(N'[proj].[sp_SearchDeliveries]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchDeliveries];
