CREATE   PROCEDURE proj.sp_SearchDeliveries
    @SearchText  NVARCHAR(100) = NULL,
    @CustomerId  INT           = NULL,
    @Status      NVARCHAR(20)  = NULL,
    @DateFrom    DATE          = NULL,
    @DateTo      DATE          = NULL,
    @PageNumber  INT           = 1,
    @PageSize    INT           = 20
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        d.DeliveryId,
        d.DeliveryNo,
        d.DeliveryDate,
        d.InvoiceId,
        i.InvoiceNo,
        d.CustomerId,
        c.CustomerName,
        d.JobId,
        d.VehicleNo,
        d.DeliveredBy,
        d.Status,
        d.CreatedBy,
        d.CreatedDate,
        COUNT(*) OVER() AS TotalRows
    FROM proj.TBL_DELIVERY d
    INNER JOIN proj.TBL_CUSTOMER c ON c.CustomerId = d.CustomerId
    LEFT JOIN  proj.TBL_INVOICE  i ON i.InvoiceId  = d.InvoiceId
    WHERE d.IsActive = 1
      AND (@CustomerId IS NULL OR d.CustomerId  = @CustomerId)
      AND (@Status     IS NULL OR d.Status      = @Status)
      AND (@DateFrom   IS NULL OR d.DeliveryDate >= @DateFrom)
      AND (@DateTo     IS NULL OR d.DeliveryDate <= @DateTo)
      AND (@SearchText IS NULL
           OR d.DeliveryNo      LIKE '%' + @SearchText + '%'
           OR i.InvoiceNo       LIKE '%' + @SearchText + '%'
           OR c.CustomerName    LIKE '%' + @SearchText + '%'
           OR d.JobId           LIKE '%' + @SearchText + '%')
    ORDER BY d.DeliveryDate DESC, d.DeliveryId DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;
END
GO

IF OBJECT_ID(N'[proj].[sp_SearchGRNs]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchGRNs];
GO

CREATE PROCEDURE proj.sp_SearchGRNs
    @SearchText    NVARCHAR(100) = NULL,
    @Status        NVARCHAR(200) = NULL,
    @SupplierId    INT           = NULL,
    @JobId         NVARCHAR(50)  = NULL,
    @PoId          INT           = NULL,
    @PoNumber      NVARCHAR(30)  = NULL,
    @CreatedBy     NVARCHAR(100) = NULL,
    @DateFrom      DATE          = NULL,
    @DateTo        DATE          = NULL,
    @PageNumber    INT           = 1,
    @PageSize      INT           = 20,
    @SortColumn    NVARCHAR(50)  = N'GrnDate',
    @SortDirection NVARCHAR(4)   = N'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;
    DECLARE @Total  INT;

    SELECT @Total = COUNT(DISTINCT g.GrnId)
    FROM proj.TBL_GRN_HEADER g
    LEFT JOIN proj.TBL_PURCHASE_ORDER po ON po.PoId      = g.PoId
    LEFT JOIN proj.TBL_SUPPLIER       s  ON s.SupplierId = g.SupplierId
    WHERE g.IsActive = 1
      AND (@SearchText IS NULL OR g.GrnNumber    LIKE N'%'+@SearchText+N'%'
                               OR g.DoNo         LIKE N'%'+@SearchText+N'%'
                               OR g.InvoiceNo    LIKE N'%'+@SearchText+N'%'
                               OR g.ReceivedFrom LIKE N'%'+@SearchText+N'%'
                               OR s.SupplierName LIKE N'%'+@SearchText+N'%'
                               OR g.JobId        LIKE N'%'+@SearchText+N'%')
      AND (@Status     IS NULL OR g.Status     IN (SELECT LTRIM(RTRIM(value)) FROM STRING_SPLIT(@Status, ',')))
      AND (@SupplierId IS NULL OR g.SupplierId  = @SupplierId)
      AND (@JobId      IS NULL OR g.JobId       = @JobId)
      AND (@PoId       IS NULL OR g.PoId        = @PoId)
      AND (@PoNumber   IS NULL OR po.PoNumber   LIKE N'%'+@PoNumber+N'%')
      AND (@CreatedBy  IS NULL OR g.CreatedBy  LIKE N'%'+@CreatedBy+N'%')
      AND (@DateFrom   IS NULL OR g.GrnDate    >= @DateFrom)
      AND (@DateTo     IS NULL OR g.GrnDate    <= @DateTo);

    SELECT
        g.GrnId, g.GrnNumber, g.GrnDate, g.Status,
        g.PoId, po.PoNumber,
        g.SupplierId,
        ISNULL(s.SupplierName, g.ReceivedFrom) AS SupplierName,
        s.SupplierCode,
        g.JobId, j.ProjectName AS JobTitle,
        g.DoNo, g.InvoiceNo, g.InvoiceDate,
        g.ReceivedBy, g.ReceivedDate,
        g.IsRegistered, g.BoeNo,
        g.TotalAmount,
        g.CreatedBy, g.CreatedDate,
        (SELECT COUNT(*) FROM proj.TBL_GRN_DETAIL d WHERE d.GrnId = g.GrnId AND d.IsActive = 1) AS LineCount,
        @Total AS TotalRows
    FROM proj.TBL_GRN_HEADER       g
    LEFT JOIN proj.TBL_PURCHASE_ORDER po ON po.PoId      = g.PoId
    LEFT JOIN proj.TBL_SUPPLIER       s  ON s.SupplierId = g.SupplierId
    LEFT JOIN proj.TBL_JOB            j  ON j.JobId      = g.JobId
    WHERE g.IsActive = 1
      AND (@SearchText IS NULL OR g.GrnNumber    LIKE N'%'+@SearchText+N'%'
                               OR g.DoNo         LIKE N'%'+@SearchText+N'%'
                               OR g.InvoiceNo    LIKE N'%'+@SearchText+N'%'
                               OR g.ReceivedFrom LIKE N'%'+@SearchText+N'%'
                               OR s.SupplierName LIKE N'%'+@SearchText+N'%'
                               OR g.JobId        LIKE N'%'+@SearchText+N'%')
      AND (@Status     IS NULL OR g.Status     IN (SELECT LTRIM(RTRIM(value)) FROM STRING_SPLIT(@Status, ',')))
      AND (@SupplierId IS NULL OR g.SupplierId  = @SupplierId)
      AND (@JobId      IS NULL OR g.JobId       = @JobId)
      AND (@PoId       IS NULL OR g.PoId        = @PoId)
      AND (@PoNumber   IS NULL OR po.PoNumber   LIKE N'%'+@PoNumber+N'%')
      AND (@CreatedBy  IS NULL OR g.CreatedBy  LIKE N'%'+@CreatedBy+N'%')
      AND (@DateFrom   IS NULL OR g.GrnDate    >= @DateFrom)
      AND (@DateTo     IS NULL OR g.GrnDate    <= @DateTo)
    ORDER BY
        CASE WHEN @SortColumn=N'GrnNumber'    AND @SortDirection=N'ASC'  THEN g.GrnNumber    END ASC,
        CASE WHEN @SortColumn=N'GrnNumber'    AND @SortDirection=N'DESC' THEN g.GrnNumber    END DESC,
        CASE WHEN @SortColumn=N'PoNumber'     AND @SortDirection=N'ASC'  THEN po.PoNumber    END ASC,
        CASE WHEN @SortColumn=N'PoNumber'     AND @SortDirection=N'DESC' THEN po.PoNumber    END DESC,
        CASE WHEN @SortColumn=N'SupplierName' AND @SortDirection=N'ASC'  THEN s.SupplierName END ASC,
        CASE WHEN @SortColumn=N'SupplierName' AND @SortDirection=N'DESC' THEN s.SupplierName END DESC,
        CASE WHEN @SortColumn=N'Status'       AND @SortDirection=N'ASC'  THEN g.Status       END ASC,
        CASE WHEN @SortColumn=N'Status'       AND @SortDirection=N'DESC' THEN g.Status       END DESC,
        CASE WHEN @SortColumn=N'GrnDate'      AND @SortDirection=N'ASC'  THEN g.GrnDate      END ASC,
        CASE WHEN @SortColumn=N'GrnDate'      AND @SortDirection=N'DESC' THEN g.GrnDate      END DESC,
        g.GrnId DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO

IF OBJECT_ID(N'[proj].[sp_SearchInvoices]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchInvoices];
GO

-- 3. Update sp_SearchInvoices — add DocumentCount column
CREATE PROCEDURE PROJ.sp_SearchInvoices
    @SearchText    NVARCHAR(100) = NULL,
    @CustomerId    INT           = NULL,
    @JobId         VARCHAR(30)   = NULL,
    @Status        NVARCHAR(20)  = NULL,
    @DateFrom      DATE          = NULL,
    @DateTo        DATE          = NULL,
    @PageNumber    INT           = 1,
    @PageSize      INT           = 20,
    @SortColumn    NVARCHAR(50)  = 'InvoiceDate',
    @SortDirection NVARCHAR(4)   = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;
    WITH cte AS (
        SELECT
            i.InvoiceId, i.InvoiceNo, i.InvoiceDate,
            i.CustomerId, c.CustomerName,
            i.CurrencyId, cu.ShortName AS CurrencyShort, cu.Symbol AS CurrencySymbol,
            i.DueDate, i.JobId, i.LpoNo,
            i.SubTotal, i.TaxAmount, i.TotalAmount,
            i.Status, i.CreatedBy, i.CreatedDate, i.ModifiedBy, i.ModifiedDate,
            (SELECT COUNT(*) FROM PROJ.TBL_INVOICE_LINE l
             WHERE l.InvoiceId = i.InvoiceId AND l.IsActive = 1) AS LineCount,
            (SELECT COUNT(*) FROM PROJ.TBL_DOCUMENTS d
             WHERE d.ReferenceTable = 'TBL_INVOICE'
               AND d.ReferenceKey = CAST(i.InvoiceId AS NVARCHAR(20))
               AND d.IsActive = 1) AS DocumentCount,
            COUNT(*) OVER () AS TotalRows
        FROM PROJ.TBL_INVOICE   i
        INNER JOIN PROJ.TBL_CUSTOMER c  ON c.CustomerId  = i.CustomerId
        INNER JOIN PROJ.TBL_CURRENCY cu ON cu.CurrencyId = i.CurrencyId
        WHERE i.IsActive = 1
          AND (@CustomerId IS NULL OR i.CustomerId  = @CustomerId)
          AND (@JobId      IS NULL OR i.JobId       = @JobId)
          AND (@Status     IS NULL OR i.Status      = @Status)
          AND (@DateFrom   IS NULL OR i.InvoiceDate >= @DateFrom)
          AND (@DateTo     IS NULL OR i.InvoiceDate <= @DateTo)
          AND (@SearchText IS NULL
               OR i.InvoiceNo    LIKE N'%' + @SearchText + N'%'
               OR c.CustomerName LIKE N'%' + @SearchText + N'%'
               OR i.LpoNo        LIKE N'%' + @SearchText + N'%')
    )
    SELECT * FROM cte
    ORDER BY
        CASE WHEN @SortColumn='InvoiceNo'    AND @SortDirection='ASC'  THEN InvoiceNo    END ASC,
        CASE WHEN @SortColumn='InvoiceNo'    AND @SortDirection='DESC' THEN InvoiceNo    END DESC,
        CASE WHEN @SortColumn='InvoiceDate'  AND @SortDirection='ASC'  THEN InvoiceDate  END ASC,
        CASE WHEN @SortColumn='CustomerName' AND @SortDirection='ASC'  THEN CustomerName END ASC,
        CASE WHEN @SortColumn='CustomerName' AND @SortDirection='DESC' THEN CustomerName END DESC,
        CASE WHEN @SortColumn='TotalAmount'  AND @SortDirection='ASC'  THEN TotalAmount  END ASC,
        CASE WHEN @SortColumn='TotalAmount'  AND @SortDirection='DESC' THEN TotalAmount  END DESC,
        CASE WHEN @SortColumn='Status'       AND @SortDirection='ASC'  THEN Status       END ASC,
        CASE WHEN @SortColumn='Status'       AND @SortDirection='DESC' THEN Status       END DESC,
        InvoiceDate DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO

IF OBJECT_ID(N'[proj].[sp_SearchIssueReturns]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchIssueReturns];
GO

-- ── sp_SearchIssueReturns ─────────────────────────────────────────────────
CREATE   PROCEDURE proj.sp_SearchIssueReturns
    @SearchText   NVARCHAR(200) = NULL,
    @IssueId      INT           = NULL,
    @Status       NVARCHAR(30)  = NULL,
    @DateFrom     DATE          = NULL,
    @DateTo       DATE          = NULL,
    @PageNumber   INT           = 1,
    @PageSize     INT           = 20,
    @SortColumn   NVARCHAR(50)  = 'ReturnDate',
    @SortDirection NVARCHAR(4)  = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

    WITH cte AS (
        SELECT
            r.ReturnId,
            r.ReturnNo,
            r.ReturnDate,
            r.IssueId,
            i.IssueNo,
            i.JobId,
            r.ReturnedBy,
            r.Notes,
            r.Status,
            r.CreatedBy,
            r.CreatedDate,
            COUNT(rl.ReturnLineId)                          AS LineCount,
            ISNULL(SUM(rl.ReturnQty * rl.UnitCost), 0)    AS TotalCost,
            COUNT(*) OVER ()                                AS TotalRows
        FROM proj.TBL_STOCK_ISSUE_RETURN r
        JOIN proj.TBL_STOCK_ISSUE i ON i.IssueId = r.IssueId
        LEFT JOIN proj.TBL_STOCK_ISSUE_RETURN_LINE rl ON rl.ReturnId = r.ReturnId AND rl.ReturnId IS NOT NULL
        WHERE r.IsActive = 1
          AND (@Status     IS NULL OR r.Status     = @Status)
          AND (@IssueId    IS NULL OR r.IssueId    = @IssueId)
          AND (@DateFrom   IS NULL OR r.ReturnDate >= @DateFrom)
          AND (@DateTo     IS NULL OR r.ReturnDate <= @DateTo)
          AND (@SearchText IS NULL OR (
                r.ReturnNo LIKE '%' + @SearchText + '%'
             OR i.IssueNo  LIKE '%' + @SearchText + '%'
             OR i.JobId    LIKE '%' + @SearchText + '%'
          ))
        GROUP BY
            r.ReturnId, r.ReturnNo, r.ReturnDate, r.IssueId,
            i.IssueNo, i.JobId, r.ReturnedBy, r.Notes,
            r.Status, r.CreatedBy, r.CreatedDate
    )
    SELECT * FROM cte
    ORDER BY
        CASE WHEN @SortDirection = 'ASC' THEN
            CASE @SortColumn WHEN 'ReturnDate' THEN CONVERT(NVARCHAR(30), ReturnDate, 120) WHEN 'ReturnNo' THEN ReturnNo ELSE CONVERT(NVARCHAR(30), ReturnDate, 120) END
        END ASC,
        CASE WHEN @SortDirection = 'DESC' OR @SortDirection IS NULL THEN
            CASE @SortColumn WHEN 'ReturnDate' THEN CONVERT(NVARCHAR(30), ReturnDate, 120) WHEN 'ReturnNo' THEN ReturnNo ELSE CONVERT(NVARCHAR(30), ReturnDate, 120) END
        END DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO

IF OBJECT_ID(N'[proj].[sp_SearchItems]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchItems];
GO

-- 3. Add LastPurchasePrice + currency to sp_SearchItems
CREATE PROCEDURE proj.sp_SearchItems
    @SearchText    NVARCHAR(200) = NULL,
    @CategoryId    INT           = NULL,
    @ItemTypeId    INT           = NULL,
    @IsActive      BIT           = NULL,
    @BudgetCategoryId INT        = NULL,
    @IsStockable   BIT           = NULL,
    @PageNumber    INT           = 1,
    @PageSize      INT           = 20,
    @SortColumn    NVARCHAR(50)  = 'ItemName',
    @SortDirection NVARCHAR(4)   = 'ASC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;
    SELECT
        i.ItemId, i.ItemCode, i.ItemName, i.ItemNameAr, i.ShortDescription,
        i.CategoryId,  c.CategoryName,
        c.ParentCategoryId,
        pc.CategoryName AS ParentCategoryName,
        i.ItemTypeId,  t.TypeName   AS ItemTypeName,
        i.BaseUomId,   bu.UomCode   AS BaseUomCode, bu.UomName AS BaseUomName,
        i.PurchaseUomId, pu.UomCode AS PurchaseUomCode,
        i.SalesUomId,  su.UomCode   AS SalesUomCode,
        i.Barcode, i.HSCode,
        i.IsStockable, i.IsSaleable, i.IsPurchasable, i.IsActive,
        i.BudgetCategoryId, ec.CategoryName AS BudgetCategoryName, ec.CategoryCode AS BudgetCategoryCode,
        i.CreatedBy, i.CreatedDate, i.ModifiedBy, i.ModifiedDate,
        -- Last purchase price hint (most recent PO line for this item)
        lpp.LastPurchasePrice, lpp.LastPurchaseCurrencyShort,
        COUNT(*) OVER() AS TotalRows
    FROM proj.TBL_ITEM i
    LEFT JOIN proj.TBL_ITEM_CATEGORY c  ON c.CategoryId  = i.CategoryId
    LEFT JOIN proj.TBL_ITEM_CATEGORY pc ON pc.CategoryId = c.ParentCategoryId
    LEFT JOIN proj.TBL_ITEM_TYPE     t  ON t.ItemTypeId  = i.ItemTypeId
    LEFT JOIN proj.TBL_ITEM_UOM      bu ON bu.UomId = i.BaseUomId
    LEFT JOIN proj.TBL_ITEM_UOM      pu ON pu.UomId = i.PurchaseUomId
    LEFT JOIN proj.TBL_ITEM_UOM      su ON su.UomId = i.SalesUomId
    LEFT JOIN proj.TBL_JOB_EXPENSE_CATEGORY ec ON ec.ExpenseCategoryId = i.BudgetCategoryId
    OUTER APPLY (
        SELECT TOP 1 pol.UnitPrice AS LastPurchasePrice, cur.ShortName AS LastPurchaseCurrencyShort
        FROM proj.TBL_PURCHASE_ORDER_LINE pol
        JOIN proj.TBL_PURCHASE_ORDER po  ON po.PoId      = pol.PoId
        LEFT JOIN proj.TBL_CURRENCY  cur ON cur.CurrencyId = po.CurrencyId
        WHERE pol.ItemId = i.ItemId AND pol.UnitPrice > 0
        ORDER BY po.PoDate DESC
    ) lpp
    WHERE
        (@SearchText IS NULL OR i.ItemName LIKE '%' + @SearchText + '%'
                             OR i.ItemCode LIKE '%' + @SearchText + '%'
                             OR i.Barcode  LIKE '%' + @SearchText + '%')
    AND (@CategoryId IS NULL
         OR i.CategoryId = @CategoryId
         OR EXISTS (
             SELECT 1 FROM proj.TBL_ITEM_CATEGORY sub
             WHERE sub.CategoryId = i.CategoryId
               AND sub.ParentCategoryId = @CategoryId
         ))
    AND (@ItemTypeId IS NULL OR i.ItemTypeId = @ItemTypeId)
    AND (@IsActive   IS NULL OR i.IsActive   = @IsActive)
    AND (@BudgetCategoryId IS NULL OR i.BudgetCategoryId = @BudgetCategoryId)
    AND (@IsStockable IS NULL OR i.IsStockable = @IsStockable)
    ORDER BY
        CASE WHEN @SortColumn='ItemCode'     AND @SortDirection='ASC'  THEN i.ItemCode     END ASC,
        CASE WHEN @SortColumn='ItemCode'     AND @SortDirection='DESC' THEN i.ItemCode     END DESC,
        CASE WHEN @SortColumn='CategoryName' AND @SortDirection='ASC'  THEN c.CategoryName END ASC,
        CASE WHEN @SortColumn='CategoryName' AND @SortDirection='DESC' THEN c.CategoryName END DESC,
        CASE WHEN @SortColumn='ItemTypeName' AND @SortDirection='ASC'  THEN t.TypeName     END ASC,
        CASE WHEN @SortColumn='ItemTypeName' AND @SortDirection='DESC' THEN t.TypeName     END DESC,
        CASE WHEN @SortDirection='ASC'  THEN i.ItemName END ASC,
        CASE WHEN @SortDirection='DESC' THEN i.ItemName END DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO

IF OBJECT_ID(N'[proj].[sp_SearchJobs]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchJobs];
