CREATE PROCEDURE PROJ.sp_SearchJobs
    @SearchText          NVARCHAR(200) = NULL,
    @JobTypeId           NVARCHAR(50)  = NULL,
    @JobStageId          NVARCHAR(10)  = NULL,
    @CustomerId          INT           = NULL,
    @JobStatusId         INT           = NULL,
    @JobStatusIds        NVARCHAR(200) = NULL,
    @DateFrom            DATE          = NULL,
    @DateTo              DATE          = NULL,
    @ExcludeClosedStatus BIT           = 0,
    @ApprovalStatus      NVARCHAR(20)  = NULL,
    @PageNumber          INT           = 1,
    @PageSize            INT           = 20,
    @SortColumn          NVARCHAR(50)  = 'JobDate',
    @SortDirection       NVARCHAR(4)   = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;

    SET @SortColumn = CASE @SortColumn
        WHEN 'JobId'          THEN 'JobId'
        WHEN 'JobDate'        THEN 'JobDate'
        WHEN 'CustomerName'   THEN 'CustomerName'
        WHEN 'JobTypeName'    THEN 'JobTypeName'
        WHEN 'JobStageName'   THEN 'JobStageName'
        WHEN 'ProjectName'    THEN 'ProjectName'
        WHEN 'OrderValue'     THEN 'OrderValue'
        WHEN 'CurrencySymbol' THEN 'CurrencySymbol'
        ELSE 'JobDate'
    END;
    SET @SortDirection = CASE WHEN UPPER(@SortDirection) = 'ASC' THEN 'ASC' ELSE 'DESC' END;

    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

    DECLARE @SQL NVARCHAR(MAX) = N'
    WITH CTE AS (
        SELECT *, COUNT(*) OVER() AS TotalRows
        FROM PROJ.VW_JOB
        WHERE 1=1
    ';

    IF @SearchText IS NOT NULL AND @SearchText <> ''
        SET @SQL += N' AND (JobId LIKE ''%'' + @SearchText + ''%''
                        OR CustomerName LIKE ''%'' + @SearchText + ''%''
                        OR ProjectName  LIKE ''%'' + @SearchText + ''%''
                        OR ContractRef  LIKE ''%'' + @SearchText + ''%''
                        OR LpoRef       LIKE ''%'' + @SearchText + ''%'')';

    IF @JobTypeId        IS NOT NULL SET @SQL += N' AND JobTypeId  = @JobTypeId';
    IF @JobStageId       IS NOT NULL SET @SQL += N' AND JobStageId = @JobStageId';
    IF @CustomerId       IS NOT NULL SET @SQL += N' AND CustomerId = @CustomerId';
    IF @JobStatusId      IS NOT NULL SET @SQL += N' AND JobStatusId = @JobStatusId';
    IF @JobStatusIds IS NOT NULL AND @JobStatusIds <> ''
        SET @SQL += N' AND JobStatusId IN (SELECT CAST(value AS INT) FROM STRING_SPLIT(@JobStatusIds, '',''))';
    IF @DateFrom         IS NOT NULL SET @SQL += N' AND CAST(JobDate AS DATE) >= @DateFrom';
    IF @DateTo           IS NOT NULL SET @SQL += N' AND CAST(JobDate AS DATE) <= @DateTo';
    IF @ExcludeClosedStatus = 1      SET @SQL += N' AND (IsClosedStatus = 0 OR IsClosedStatus IS NULL)';
    IF @ApprovalStatus   IS NOT NULL SET @SQL += N' AND ApprovalStatus = @ApprovalStatus';

    SET @SQL += N')
    SELECT * FROM CTE
    ORDER BY ' + @SortColumn + N' ' + @SortDirection + N'
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;';

    EXEC sp_executesql @SQL,
        N'@SearchText NVARCHAR(200), @JobTypeId NVARCHAR(50), @JobStageId NVARCHAR(10),
          @CustomerId INT, @JobStatusId INT, @JobStatusIds NVARCHAR(200),
          @DateFrom DATE, @DateTo DATE,
          @ExcludeClosedStatus BIT, @ApprovalStatus NVARCHAR(20), @Offset INT, @PageSize INT',
        @SearchText, @JobTypeId, @JobStageId, @CustomerId, @JobStatusId, @JobStatusIds,
        @DateFrom, @DateTo, @ExcludeClosedStatus, @ApprovalStatus, @Offset, @PageSize;
END
GO

IF OBJECT_ID(N'[proj].[sp_SearchManhours]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchManhours];
GO

CREATE   PROCEDURE proj.sp_SearchManhours
    @SearchText    NVARCHAR(100) = NULL,
    @JobId         NVARCHAR(50)  = NULL,
    @Status        NVARCHAR(20)  = NULL,
    @CreatedBy     NVARCHAR(50)  = NULL,
    @DateFrom      DATE          = NULL,
    @DateTo        DATE          = NULL,
    @PageNumber    INT           = 1,
    @PageSize      INT           = 20,
    @SortColumn    NVARCHAR(50)  = 'DocumentDate',
    @SortDirection NVARCHAR(4)   = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

    WITH BatchRows AS (
        SELECT m.* FROM proj.TBL_MANHOUR m
        WHERE m.IsActive = 1
          AND (@JobId IS NULL OR m.JobId = @JobId)
    ),
    Batches AS (
        SELECT
            m.BatchId,
            MAX(m.DocumentNo)             AS DocumentNo,
            MAX(m.DocumentDate)           AS DocumentDate,
            MAX(m.Status)                 AS Status,
            COUNT(DISTINCT m.JobId)       AS JobCount,
            SUM(m.Hours)                  AS TotalHours,
            SUM(m.OvertimeHours)          AS TotalOTHours,
            COUNT(DISTINCT m.EmployeeId)  AS TotalEmployees,
            MAX(m.Remarks)                AS Remarks,
            MAX(m.UploadedFileName)       AS UploadedFileName,
            MAX(m.CreatedBy)              AS CreatedBy,
            MAX(m.CreatedDate)            AS CreatedDate,
            MAX(m.ModifiedBy)             AS ModifiedBy,
            MAX(m.ModifiedDate)           AS ModifiedDate
        FROM BatchRows m
        GROUP BY m.BatchId
    ),
    WithBadge AS (
        SELECT b.*,
            ds.BadgeBg, ds.BadgeColor, ds.BadgeDot,
            CAST(ds.CanEdit   AS BIT) AS CanEdit,
            CAST(ds.CanDelete AS BIT) AS CanDelete,
            CAST(ds.CanPrint  AS BIT) AS CanPrint
        FROM Batches b
        LEFT JOIN proj.TBL_DOCUMENT_STATUS ds ON ds.ModuleName = 'MH' AND ds.StatusCode = b.Status
    ),
    Filtered AS (
        SELECT * FROM WithBadge
        WHERE
            (@SearchText IS NULL OR DocumentNo LIKE '%' + @SearchText + '%')
            AND (@Status    IS NULL OR Status    = @Status)
            AND (@CreatedBy IS NULL OR CreatedBy LIKE '%' + @CreatedBy + '%')
            AND (@DateFrom  IS NULL OR DocumentDate >= @DateFrom)
            AND (@DateTo    IS NULL OR DocumentDate <= @DateTo)
    ),
    Counted AS (SELECT *, COUNT(*) OVER () AS TotalRows FROM Filtered)
    SELECT * FROM Counted
    ORDER BY
        CASE WHEN @SortColumn = 'DocumentNo'   AND @SortDirection = 'ASC'  THEN DocumentNo   END ASC,
        CASE WHEN @SortColumn = 'DocumentNo'   AND @SortDirection = 'DESC' THEN DocumentNo   END DESC,
        CASE WHEN @SortColumn = 'Status'       AND @SortDirection = 'ASC'  THEN Status       END ASC,
        CASE WHEN @SortColumn = 'Status'       AND @SortDirection = 'DESC' THEN Status       END DESC,
        CASE WHEN @SortColumn = 'CreatedBy'    AND @SortDirection = 'ASC'  THEN CreatedBy    END ASC,
        CASE WHEN @SortColumn = 'CreatedBy'    AND @SortDirection = 'DESC' THEN CreatedBy    END DESC,
        CASE WHEN @SortColumn = 'DocumentDate' AND @SortDirection = 'ASC'  THEN DocumentDate END ASC,
        DocumentDate DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO

IF OBJECT_ID(N'[proj].[sp_SearchPaymentVouchers]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchPaymentVouchers];
GO

CREATE PROCEDURE proj.sp_SearchPaymentVouchers
    @SearchText    NVARCHAR(100) = NULL,
    @SupplierId    INT           = NULL,
    @Status        NVARCHAR(20)  = NULL,
    @DateFrom      DATE          = NULL,
    @DateTo        DATE          = NULL,
    @PageNumber    INT           = 1,
    @PageSize      INT           = 20,
    @SortColumn    NVARCHAR(50)  = 'PvDate',
    @SortDirection NVARCHAR(4)   = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

    ;WITH base AS (
        SELECT pv.PvId, pv.PvNumber, pv.PvDate, pv.SupplierId, s.SupplierName,
               pv.CurrencyId, c.ShortName AS CurrencyShort,
               pv.ExchangeRate,
               pv.AmountPaid, pv.AllocatedAmount,
               (pv.AmountPaid - pv.AllocatedAmount) AS UnallocatedAmount,
               pv.PaymentMode, pv.ReferenceNo, pv.Status,
               COUNT(*) OVER() AS TotalRows
        FROM proj.TBL_PAYMENT_VOUCHER pv
        LEFT JOIN proj.TBL_SUPPLIER   s ON s.SupplierId  = pv.SupplierId
        LEFT JOIN proj.TBL_CURRENCY   c ON c.CurrencyId  = pv.CurrencyId
        WHERE pv.IsActive = 1
          AND (@SearchText IS NULL OR pv.PvNumber    LIKE '%'+@SearchText+'%'
                                   OR pv.ReferenceNo LIKE '%'+@SearchText+'%'
                                   OR s.SupplierName LIKE '%'+@SearchText+'%')
          AND (@SupplierId IS NULL OR pv.SupplierId = @SupplierId)
          AND (@Status     IS NULL OR pv.Status     = @Status)
          AND (@DateFrom   IS NULL OR pv.PvDate    >= @DateFrom)
          AND (@DateTo     IS NULL OR pv.PvDate    <= @DateTo)
    )
    SELECT * FROM base
    ORDER BY
        CASE WHEN @SortColumn='PvNumber' AND @SortDirection='ASC'  THEN PvNumber END ASC,
        CASE WHEN @SortColumn='PvNumber' AND @SortDirection='DESC' THEN PvNumber END DESC,
        CASE WHEN @SortColumn='PvDate'   AND @SortDirection='ASC'  THEN PvDate   END ASC,
        CASE WHEN @SortColumn='PvDate'   AND @SortDirection='DESC' THEN PvDate   END DESC,
        PvId DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO

IF OBJECT_ID(N'[proj].[sp_SearchPOs]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchPOs];
GO
CREATE PROCEDURE PROJ.sp_SearchPOs
    @SearchText       NVARCHAR(100) = NULL,
    @Status           NVARCHAR(200) = NULL,
    @SupplierId       INT           = NULL,
    @JobId            NVARCHAR(50)  = NULL,
    @Priority         NVARCHAR(20)  = NULL,
    @PrNumber         NVARCHAR(30)  = NULL,
    @CreatedBy        NVARCHAR(100) = NULL,
    @DateFrom         DATE          = NULL,
    @DateTo           DATE          = NULL,
    @IsSubcontractOnly BIT          = NULL,
    @PageNumber       INT           = 1,
    @PageSize         INT           = 20,
    @SortColumn       NVARCHAR(50)  = N'PoDate',
    @SortDirection    NVARCHAR(4)   = N'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;
    DECLARE @Total  INT;

    SELECT @Total = COUNT(DISTINCT po.PoId)
    FROM PROJ.TBL_PURCHASE_ORDER po
    LEFT JOIN PROJ.TBL_SUPPLIER s  ON s.SupplierId = po.SupplierId
    LEFT JOIN PROJ.TBL_JOB_EXPENSE_CATEGORY ec ON ec.ExpenseCategoryId = po.ExpenseCategoryId
    WHERE po.IsActive = 1
      AND (@SearchText IS NULL OR po.PoNumber    LIKE N'%'+@SearchText+N'%'
                               OR po.VendorRef   LIKE N'%'+@SearchText+N'%'
                               OR po.JobId       LIKE N'%'+@SearchText+N'%'
                               OR s.SupplierName LIKE N'%'+@SearchText+N'%'
                               OR s.SupplierCode LIKE N'%'+@SearchText+N'%')
      AND (@Status     IS NULL OR po.Status IN (SELECT LTRIM(RTRIM(value)) FROM STRING_SPLIT(@Status, ',')))
      AND (@SupplierId IS NULL OR po.SupplierId = @SupplierId)
      AND (@JobId      IS NULL OR po.JobId      = @JobId)
      AND (@Priority   IS NULL OR po.Priority   = @Priority)
      AND (@CreatedBy  IS NULL OR po.CreatedBy LIKE N'%'+@CreatedBy+N'%')
      AND (@DateFrom   IS NULL OR CAST(po.CreatedDate AS DATE) >= @DateFrom)
      AND (@DateTo     IS NULL OR CAST(po.CreatedDate AS DATE) <= @DateTo)
      AND (@IsSubcontractOnly IS NULL OR (@IsSubcontractOnly = 1 AND ISNULL(ec.IsSubcontractOrder, 0) = 1))
      AND (@PrNumber IS NULL OR EXISTS (
            SELECT 1 FROM PROJ.TBL_PURCHASE_ORDER_LINE pol
            JOIN PROJ.TBL_PURCHASE_REQUEST_LINE prl ON prl.PrLineId = pol.PrLineId AND prl.IsActive = 1
            JOIN PROJ.TBL_PURCHASE_REQUEST pr ON pr.PrId = prl.PrId
            WHERE pol.PoId = po.PoId AND pol.IsActive = 1 AND pr.PrNumber = @PrNumber));

    SELECT
        po.PoId, po.PoNumber, po.PoDate, po.Revision, po.Status, po.Priority,
        po.SupplierId,
        ISNULL(s.SupplierName, po.VendorName) AS VendorName,
        s.SupplierCode,
        po.VendorRef, po.JobId, j.ProjectName AS JobTitle,
        po.CurrencyId, c.CurrencyName, c.ShortName AS CurrencyShort,
        po.ExchangeRate, po.DeliveryDate, po.DeliveryTerms,
        po.TotalAmount,
        ROUND(po_paid.PaidBase / NULLIF(ISNULL(po.ExchangeRate, 1), 0), 2) AS PaidAmount,
        po.TotalAmount - ROUND(po_paid.PaidBase / NULLIF(ISNULL(po.ExchangeRate, 1), 0), 2) AS BalanceAmount,
        po.InvoiceReceived, po.HoldBy,
        po.ExpenseCategoryId,
        ec.CategoryCode  AS ExpenseCategoryCode,
        ec.CategoryName  AS ExpenseCategoryName,
        ISNULL(ec.IsSubcontractOrder, 0) AS IsSubcontractOrder,
        po.BudgetHeaderId,
        po.CreatedBy, po.CreatedDate,
        (SELECT STRING_AGG(x.PrNumber, ', ') WITHIN GROUP (ORDER BY x.PrNumber)
         FROM (SELECT DISTINCT pr2.PrNumber
               FROM PROJ.TBL_PURCHASE_ORDER_LINE   pol2
               JOIN PROJ.TBL_PURCHASE_REQUEST_LINE prl2 ON prl2.PrLineId = pol2.PrLineId AND prl2.IsActive = 1
               JOIN PROJ.TBL_PURCHASE_REQUEST      pr2  ON pr2.PrId      = prl2.PrId
               WHERE pol2.PoId = po.PoId AND pol2.IsActive = 1) x) AS LinkedPRs,
        (SELECT COUNT(*) FROM PROJ.TBL_PURCHASE_ORDER_LINE l WHERE l.PoId = po.PoId AND l.IsActive = 1) AS LineCount,
        @Total AS TotalRows
    FROM PROJ.TBL_PURCHASE_ORDER po
    LEFT JOIN PROJ.TBL_SUPPLIER  s  ON s.SupplierId  = po.SupplierId
    LEFT JOIN PROJ.TBL_JOB       j  ON j.JobId       = po.JobId
    LEFT JOIN PROJ.TBL_CURRENCY  c  ON c.CurrencyId  = po.CurrencyId
    LEFT JOIN PROJ.TBL_JOB_EXPENSE_CATEGORY ec ON ec.ExpenseCategoryId = po.ExpenseCategoryId
    OUTER APPLY (
        SELECT
            ISNULL((
                SELECT SUM(pva.AllocatedAmount)
                FROM proj.TBL_PAYMENT_VOUCHER_ALLOCATION pva
                JOIN proj.TBL_PAYMENT_VOUCHER pv ON pv.PvId = pva.PvId
                WHERE pva.PoId = po.PoId AND pva.IsActive = 1
                  AND pv.Status = 'Approved' AND pv.IsActive = 1
            ), 0)
          + ISNULL((
                SELECT SUM(sil.LineTotal / si_t.AllSum * pva.AllocatedAmount)
                FROM proj.TBL_SUPPLIER_INVOICE_LINE       sil
                JOIN proj.TBL_PURCHASE_ORDER_LINE         pol ON pol.PoLineId = sil.PoLineId AND pol.PoId = po.PoId
                JOIN proj.TBL_PAYMENT_VOUCHER_ALLOCATION  pva ON pva.SupplierInvoiceId = sil.SupplierInvoiceId
                                                              AND pva.IsActive = 1 AND pva.PoId IS NULL
                JOIN proj.TBL_PAYMENT_VOUCHER             pv  ON pv.PvId = pva.PvId AND pv.Status = 'Approved' AND pv.IsActive = 1
                JOIN (SELECT SupplierInvoiceId, SUM(ISNULL(LineTotal,0)) AS AllSum
                      FROM proj.TBL_SUPPLIER_INVOICE_LINE WHERE IsActive = 1 GROUP BY SupplierInvoiceId) si_t
                    ON si_t.SupplierInvoiceId = sil.SupplierInvoiceId
                WHERE sil.IsActive = 1 AND si_t.AllSum > 0
            ), 0) AS PaidBase
    ) po_paid
    WHERE po.IsActive = 1
      AND (@SearchText IS NULL OR po.PoNumber    LIKE N'%'+@SearchText+N'%'
                               OR po.VendorRef   LIKE N'%'+@SearchText+N'%'
                               OR po.JobId       LIKE N'%'+@SearchText+N'%'
                               OR s.SupplierName LIKE N'%'+@SearchText+N'%'
                               OR s.SupplierCode LIKE N'%'+@SearchText+N'%')
      AND (@Status     IS NULL OR po.Status IN (SELECT LTRIM(RTRIM(value)) FROM STRING_SPLIT(@Status, ',')))
      AND (@SupplierId IS NULL OR po.SupplierId = @SupplierId)
      AND (@JobId      IS NULL OR po.JobId      = @JobId)
      AND (@Priority   IS NULL OR po.Priority   = @Priority)
      AND (@CreatedBy  IS NULL OR po.CreatedBy LIKE N'%'+@CreatedBy+N'%')
      AND (@DateFrom   IS NULL OR CAST(po.CreatedDate AS DATE) >= @DateFrom)
      AND (@DateTo     IS NULL OR CAST(po.CreatedDate AS DATE) <= @DateTo)
      AND (@IsSubcontractOnly IS NULL OR (@IsSubcontractOnly = 1 AND ISNULL(ec.IsSubcontractOrder, 0) = 1))
      AND (@PrNumber IS NULL OR EXISTS (
            SELECT 1 FROM PROJ.TBL_PURCHASE_ORDER_LINE pol
            JOIN PROJ.TBL_PURCHASE_REQUEST_LINE prl ON prl.PrLineId = pol.PrLineId AND prl.IsActive = 1
            JOIN PROJ.TBL_PURCHASE_REQUEST pr ON pr.PrId = prl.PrId
            WHERE pol.PoId = po.PoId AND pol.IsActive = 1 AND pr.PrNumber = @PrNumber))
    ORDER BY
        CASE WHEN @SortColumn=N'PoNumber'   AND @SortDirection=N'ASC'  THEN po.PoNumber   END ASC,
        CASE WHEN @SortColumn=N'PoNumber'   AND @SortDirection=N'DESC' THEN po.PoNumber   END DESC,
        CASE WHEN @SortColumn=N'VendorName' AND @SortDirection=N'ASC'  THEN po.VendorName END ASC,
        CASE WHEN @SortColumn=N'VendorName' AND @SortDirection=N'DESC' THEN po.VendorName END DESC,
        CASE WHEN @SortColumn=N'Status'     AND @SortDirection=N'ASC'  THEN po.Status     END ASC,
        CASE WHEN @SortColumn=N'Status'     AND @SortDirection=N'DESC' THEN po.Status     END DESC,
        CASE WHEN @SortColumn=N'PoDate'     AND @SortDirection=N'ASC'  THEN po.PoDate     END ASC,
        CASE WHEN @SortColumn=N'PoDate'     AND @SortDirection=N'DESC' THEN po.PoDate     END DESC,
        po.PoId DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO

IF OBJECT_ID(N'[proj].[sp_SearchPRs]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchPRs];
GO
CREATE PROCEDURE proj.sp_SearchPRs
    @SearchText    NVARCHAR(100) = NULL,
    @Status        NVARCHAR(200) = NULL,
    @Priority      NVARCHAR(20)  = NULL,
    @JobId         NVARCHAR(50)  = NULL,
    @CreatedBy     NVARCHAR(100) = NULL,
    @DateFrom      DATE          = NULL,
    @DateTo        DATE          = NULL,
    @PageNumber    INT           = 1,
    @PageSize      INT           = 20,
    @SortColumn    NVARCHAR(50)  = N'PrDate',
    @SortDirection NVARCHAR(4)   = N'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;
    DECLARE @Total  INT;

    SELECT @Total = COUNT(*)
    FROM proj.TBL_PURCHASE_REQUEST pr
    WHERE pr.IsActive = 1
      AND (@SearchText IS NULL OR pr.PrNumber               LIKE N'%' + @SearchText + N'%'
                               OR ISNULL(pr.RequestedBy,'') LIKE N'%' + @SearchText + N'%')
      AND (@Status    IS NULL OR pr.Status    IN (SELECT LTRIM(RTRIM(value)) FROM STRING_SPLIT(@Status, ',')))
      AND (@Priority  IS NULL OR pr.Priority  = @Priority)
      AND (@JobId     IS NULL OR pr.JobId     = @JobId)
      AND (@CreatedBy IS NULL OR pr.CreatedBy LIKE N'%' + @CreatedBy + N'%')
      AND (@DateFrom  IS NULL OR CAST(pr.CreatedDate AS DATE) >= @DateFrom)
      AND (@DateTo    IS NULL OR CAST(pr.CreatedDate AS DATE) <= @DateTo);

    SELECT
        pr.PrId, pr.PrNumber, pr.PrDate, pr.RequestedBy,
        pr.JobId, j.ProjectName AS JobTitle,
        pr.Priority, pr.Status, pr.Revision, pr.Notes,
        pr.CreatedBy, pr.CreatedDate,
        (SELECT COUNT(*)
         FROM proj.TBL_PURCHASE_REQUEST_LINE l
         WHERE l.PrId = pr.PrId AND l.IsActive = 1) AS LineCount,
        (SELECT COUNT(DISTINCT pol.PoId)
         FROM proj.TBL_PURCHASE_REQUEST_LINE prl
         INNER JOIN proj.TBL_PURCHASE_ORDER_LINE pol ON pol.PrLineId = prl.PrLineId
         WHERE prl.PrId = pr.PrId AND pol.IsActive = 1) AS PoCount,
        CAST(CASE WHEN EXISTS (
            SELECT 1 FROM proj.TBL_PURCHASE_REQUEST_LINE l
            WHERE l.PrId = pr.PrId AND l.IsActive = 1
              AND (l.RequiredQty - ISNULL(l.PoCreatedQty, 0)) > 0
         ) THEN 0 ELSE
            CASE WHEN EXISTS (SELECT 1 FROM proj.TBL_PURCHASE_REQUEST_LINE l2
                              WHERE l2.PrId = pr.PrId AND l2.IsActive = 1) THEN 1 ELSE 0 END
         END AS BIT) AS FullyOrdered,
        @Total AS TotalRows
    FROM proj.TBL_PURCHASE_REQUEST pr
    LEFT JOIN proj.TBL_JOB j ON j.JobId = pr.JobId
    WHERE pr.IsActive = 1
      AND (@SearchText IS NULL OR pr.PrNumber               LIKE N'%' + @SearchText + N'%'
                               OR ISNULL(pr.RequestedBy,'') LIKE N'%' + @SearchText + N'%')
      AND (@Status    IS NULL OR pr.Status    IN (SELECT LTRIM(RTRIM(value)) FROM STRING_SPLIT(@Status, ',')))
      AND (@Priority  IS NULL OR pr.Priority  = @Priority)
      AND (@JobId     IS NULL OR pr.JobId     = @JobId)
      AND (@CreatedBy IS NULL OR pr.CreatedBy LIKE N'%' + @CreatedBy + N'%')
      AND (@DateFrom  IS NULL OR CAST(pr.CreatedDate AS DATE) >= @DateFrom)
      AND (@DateTo    IS NULL OR CAST(pr.CreatedDate AS DATE) <= @DateTo)
    ORDER BY
        CASE WHEN @SortColumn = N'PrNumber'  AND @SortDirection = N'ASC'  THEN pr.PrNumber  END ASC,
        CASE WHEN @SortColumn = N'PrNumber'  AND @SortDirection = N'DESC' THEN pr.PrNumber  END DESC,
        CASE WHEN @SortColumn = N'Status'    AND @SortDirection = N'ASC'  THEN pr.Status    END ASC,
        CASE WHEN @SortColumn = N'Status'    AND @SortDirection = N'DESC' THEN pr.Status    END DESC,
        CASE WHEN @SortColumn = N'PrDate'    AND @SortDirection = N'ASC'  THEN pr.PrDate    END ASC,
        CASE WHEN @SortColumn = N'PrDate'    AND @SortDirection = N'DESC' THEN pr.PrDate    END DESC,
        pr.PrId DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO

IF OBJECT_ID(N'[proj].[sp_SearchReceiptVouchers]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchReceiptVouchers];
GO

CREATE PROCEDURE proj.sp_SearchReceiptVouchers
    @SearchText    NVARCHAR(100) = NULL,
    @CustomerId    INT           = NULL,
    @Status        NVARCHAR(20)  = NULL,
    @DateFrom      DATE          = NULL,
    @DateTo        DATE          = NULL,
    @PageNumber    INT           = 1,
    @PageSize      INT           = 20,
    @SortColumn    NVARCHAR(50)  = 'RvDate',
    @SortDirection NVARCHAR(4)   = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

    ;WITH base AS (
        SELECT rv.RvId, rv.RvNumber, rv.RvDate, rv.CustomerId, c.CustomerName,
               rv.AmountReceived, rv.AllocatedAmount,
               (rv.AmountReceived - rv.AllocatedAmount) AS UnallocatedAmount,
               rv.PaymentMode, rv.ReferenceNo, rv.Status,
               cur.ShortName AS CurrencyShort,
               rv.ExchangeRate,
               COUNT(*) OVER() AS TotalRows
        FROM proj.TBL_RECEIPT_VOUCHER rv
        LEFT JOIN proj.TBL_CUSTOMER c   ON c.CustomerId   = rv.CustomerId
        LEFT JOIN proj.TBL_CURRENCY cur ON cur.CurrencyId = rv.CurrencyId
        WHERE rv.IsActive = 1
          AND (@SearchText IS NULL OR rv.RvNumber LIKE '%'+@SearchText+'%'
                                   OR rv.ReferenceNo LIKE '%'+@SearchText+'%'
                                   OR c.CustomerName LIKE '%'+@SearchText+'%')
          AND (@CustomerId IS NULL OR rv.CustomerId = @CustomerId)
          AND (@Status     IS NULL OR rv.Status     = @Status)
          AND (@DateFrom   IS NULL OR rv.RvDate    >= @DateFrom)
          AND (@DateTo     IS NULL OR rv.RvDate    <= @DateTo)
    )
    SELECT * FROM base
    ORDER BY
        CASE WHEN @SortColumn='RvNumber' AND @SortDirection='ASC'  THEN RvNumber END ASC,
        CASE WHEN @SortColumn='RvNumber' AND @SortDirection='DESC' THEN RvNumber END DESC,
        CASE WHEN @SortColumn='RvDate'   AND @SortDirection='ASC'  THEN RvDate   END ASC,
        CASE WHEN @SortColumn='RvDate'   AND @SortDirection='DESC' THEN RvDate   END DESC,
        RvId DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO

IF OBJECT_ID(N'[proj].[sp_SearchRoles]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchRoles];
GO

CREATE PROCEDURE proj.sp_SearchRoles
    @SearchText    NVARCHAR(200) = NULL,
    @IsActive      BIT           = NULL,
    @PageNumber    INT           = 1,
    @PageSize      INT           = 20,
    @SortColumn    NVARCHAR(50)  = 'RoleName',
    @SortDirection NVARCHAR(4)   = 'ASC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;
    DECLARE @SQL NVARCHAR(MAX), @OrderBy NVARCHAR(200);

    SET @OrderBy = CASE
        WHEN @SortColumn = 'RoleCode'    THEN 'r.RoleCode'
        WHEN @SortColumn = 'CreatedDate' THEN 'r.CreatedDate'
        ELSE 'r.RoleName'
    END + ' ' + CASE WHEN UPPER(@SortDirection) = 'DESC' THEN 'DESC' ELSE 'ASC' END;

    SET @SQL = N'
    SELECT
        r.RoleId, r.RoleName, r.RoleCode, r.Description,
        r.IsActive, r.IsEngineerRole,
        r.CreatedBy, r.CreatedDate, r.ModifiedBy, r.ModifiedDate,
        (SELECT COUNT(*) FROM proj.TBL_USER_ROLES ur WHERE ur.RoleId = r.RoleId) AS UserCount,
        COUNT(*) OVER() AS TotalRows
    FROM proj.TBL_ROLES r
    WHERE (@SearchText IS NULL OR
           r.RoleName    LIKE N''%'' + @SearchText + N''%'' OR
           r.RoleCode    LIKE N''%'' + @SearchText + N''%'' OR
           r.Description LIKE N''%'' + @SearchText + N''%'')
      AND (@IsActive IS NULL OR r.IsActive = @IsActive)
    ORDER BY ' + @OrderBy + N'
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;';

    EXEC sp_executesql @SQL,
        N'@SearchText NVARCHAR(200), @IsActive BIT, @Offset INT, @PageSize INT',
        @SearchText, @IsActive, @Offset, @PageSize;
END
GO

IF OBJECT_ID(N'[proj].[sp_SearchRTVs]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchRTVs];
GO

CREATE PROCEDURE proj.sp_SearchRTVs
    @SearchText    NVARCHAR(100) = NULL,
    @Status        NVARCHAR(100) = NULL,   -- comma-separated for multiselect: 'Draft,Posted'
    @SupplierId    INT           = NULL,
    @DateFrom      NVARCHAR(20)  = NULL,
    @DateTo        NVARCHAR(20)  = NULL,
    @PageNumber    INT           = 1,
    @PageSize      INT           = 20,
    @SortColumn    NVARCHAR(50)  = 'RtvDate',
    @SortDirection NVARCHAR(4)   = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

    -- Normalise: empty string → NULL
    SET @SearchText = NULLIF(LTRIM(RTRIM(@SearchText)), '');
    SET @Status     = NULLIF(LTRIM(RTRIM(@Status)),     '');

    SELECT
        r.RtvId, r.RtvNumber, r.RtvDate, r.Status,
        r.SupplierId, s.SupplierName, s.SupplierCode,
        r.GrnId, gh.GrnNumber,
        r.PoId,  po.PoNumber,
        r.CreatedBy, r.CreatedDate,
        (SELECT ISNULL(SUM(l.LineTotal),0)
         FROM proj.TBL_RETURN_TO_VENDOR_LINE l
         WHERE l.RtvId = r.RtvId AND l.IsActive=1) AS TotalAmount,
        COUNT(*) OVER() AS TotalRows
    FROM  proj.TBL_RETURN_TO_VENDOR r
    LEFT JOIN proj.TBL_SUPPLIER          s  ON s.SupplierId = r.SupplierId
    LEFT JOIN proj.TBL_GRN_HEADER        gh ON gh.GrnId     = r.GrnId
    LEFT JOIN proj.TBL_PURCHASE_ORDER    po ON po.PoId       = r.PoId
    WHERE r.IsActive = 1
      -- Full-text search across RTV #, GRN #, PO #, supplier name/code
      AND (@SearchText IS NULL
           OR r.RtvNumber      LIKE '%' + @SearchText + '%'
           OR s.SupplierName   LIKE '%' + @SearchText + '%'
           OR s.SupplierCode   LIKE '%' + @SearchText + '%'
           OR gh.GrnNumber     LIKE '%' + @SearchText + '%'
           OR po.PoNumber      LIKE '%' + @SearchText + '%')
      -- Multiselect status: CHARINDEX handles both single ('Draft') and multi ('Draft,Posted')
      AND (@Status IS NULL
           OR CHARINDEX(',' + r.Status + ',', ',' + @Status + ',') > 0)
      AND (@SupplierId IS NULL OR r.SupplierId = @SupplierId)
      AND (@DateFrom   IS NULL OR r.RtvDate   >= CAST(@DateFrom AS DATE))
      AND (@DateTo     IS NULL OR r.RtvDate   <= CAST(@DateTo   AS DATE))
    ORDER BY
        CASE WHEN @SortDirection = 'ASC' THEN
            CASE @SortColumn
                WHEN 'RtvNumber'    THEN r.RtvNumber
                WHEN 'SupplierName' THEN s.SupplierName
                WHEN 'Status'       THEN r.Status
                WHEN 'CreatedBy'    THEN r.CreatedBy
            END
        END ASC,
        CASE WHEN @SortDirection = 'DESC' THEN
            CASE @SortColumn
                WHEN 'RtvNumber'    THEN r.RtvNumber
                WHEN 'SupplierName' THEN s.SupplierName
                WHEN 'Status'       THEN r.Status
                WHEN 'CreatedBy'    THEN r.CreatedBy
            END
        END DESC,
        CASE WHEN @SortDirection = 'ASC'  AND @SortColumn = 'RtvDate'      THEN r.RtvDate      END ASC,
        CASE WHEN @SortDirection = 'DESC' AND @SortColumn = 'RtvDate'      THEN r.RtvDate      END DESC,
        CASE WHEN @SortDirection = 'ASC'  AND @SortColumn = 'TotalAmount'  THEN
            (SELECT ISNULL(SUM(l.LineTotal),0) FROM proj.TBL_RETURN_TO_VENDOR_LINE l WHERE l.RtvId = r.RtvId AND l.IsActive=1)
        END ASC,
        CASE WHEN @SortDirection = 'DESC' AND @SortColumn = 'TotalAmount'  THEN
            (SELECT ISNULL(SUM(l.LineTotal),0) FROM proj.TBL_RETURN_TO_VENDOR_LINE l WHERE l.RtvId = r.RtvId AND l.IsActive=1)
        END DESC,
        r.RtvDate DESC, r.RtvId DESC   -- tiebreaker
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO

IF OBJECT_ID(N'[proj].[sp_SearchServiceReceipts]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchServiceReceipts];
GO

-- ── sp_SearchServiceReceipts ─────────────────────────────────────────────────
CREATE PROCEDURE proj.sp_SearchServiceReceipts
    @SearchText  NVARCHAR(100) = NULL,
    @Status      NVARCHAR(30)  = NULL,
    @JobId       NVARCHAR(50)  = NULL,
    @PoId        INT           = NULL,
    @DateFrom    DATE          = NULL,
    @DateTo      DATE          = NULL,
    @PageNumber  INT           = 1,
    @PageSize    INT           = 20,
    @SortColumn  NVARCHAR(50)  = 'SrvDate',
    @SortDirection NVARCHAR(4) = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

    SELECT
        h.SrvId, h.SrvNo, h.SrvDate, h.PoId, h.PoNumber,
        h.JobId, h.SupplierName, h.Notes, h.Status, h.IsActive,
        h.CreatedBy, h.CreatedDate, h.ModifiedBy, h.ModifiedDate,
        COUNT(l.SrvLineId) AS LineCount,
        ISNULL(SUM(l.TotalCost), 0) AS TotalCost,
        COUNT(*) OVER () AS TotalRows
    FROM proj.TBL_SRV_HEADER h
    LEFT JOIN proj.TBL_SRV_LINE l ON l.SrvId = h.SrvId AND l.IsActive = 1
    WHERE h.IsActive = 1
      AND (@SearchText  IS NULL OR h.SrvNo       LIKE '%' + @SearchText  + '%'
                                OR h.PoNumber    LIKE '%' + @SearchText  + '%'
                                OR h.SupplierName LIKE '%' + @SearchText + '%')
      AND (@Status   IS NULL OR h.Status = @Status)
      AND (@JobId    IS NULL OR h.JobId  = @JobId)
      AND (@PoId     IS NULL OR h.PoId   = @PoId)
      AND (@DateFrom IS NULL OR h.SrvDate >= @DateFrom)
      AND (@DateTo   IS NULL OR h.SrvDate <= @DateTo)
    GROUP BY
        h.SrvId, h.SrvNo, h.SrvDate, h.PoId, h.PoNumber,
        h.JobId, h.SupplierName, h.Notes, h.Status, h.IsActive,
        h.CreatedBy, h.CreatedDate, h.ModifiedBy, h.ModifiedDate
    ORDER BY
        CASE WHEN @SortColumn='SrvDate'  AND @SortDirection='ASC'  THEN h.SrvDate   END ASC,
        CASE WHEN @SortColumn='SrvDate'  AND @SortDirection='DESC' THEN h.SrvDate   END DESC,
        CASE WHEN @SortColumn='SrvNo'    AND @SortDirection='ASC'  THEN h.SrvNo     END ASC,
        CASE WHEN @SortColumn='SrvNo'    AND @SortDirection='DESC' THEN h.SrvNo     END DESC,
        h.SrvDate DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO

IF OBJECT_ID(N'[proj].[sp_SearchStockIssues]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchStockIssues];
GO

CREATE   PROCEDURE proj.sp_SearchStockIssues
    @SearchText    NVARCHAR(100) = NULL,
    @JobId         NVARCHAR(50)  = NULL,
    @CostingType   NVARCHAR(20)  = NULL,
    @Status        NVARCHAR(20)  = NULL,
    @DateFrom      DATE          = NULL,
    @DateTo        DATE          = NULL,
    @PageNumber    INT           = 1,
    @PageSize      INT           = 20,
    @SortColumn    NVARCHAR(50)  = 'IssueDate',
    @SortDirection NVARCHAR(4)   = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;
    WITH cte AS (
        SELECT
            i.IssueId, i.IssueNo, i.IssueDate, i.JobId, i.CostingType,
            i.Notes, i.Status, i.CreatedBy, i.CreatedDate, i.ModifiedBy, i.ModifiedDate,
            ISNULL(SUM(l.Qty * l.UnitCost), 0) AS TotalCost,
            ISNULL(COUNT(l.IssueLineId), 0)    AS LineCount,
            COUNT(*) OVER ()                   AS TotalRows
        FROM proj.TBL_STOCK_ISSUE i
        LEFT JOIN proj.TBL_STOCK_ISSUE_LINE l ON l.IssueId = i.IssueId AND l.IsActive = 1
        WHERE i.IsActive = 1
          AND (@JobId       IS NULL OR i.JobId       = @JobId)
          AND (@CostingType IS NULL OR i.CostingType = @CostingType)
          AND (@Status      IS NULL OR i.Status      = @Status)
          AND (@DateFrom    IS NULL OR i.IssueDate  >= @DateFrom)
          AND (@DateTo      IS NULL OR i.IssueDate  <= @DateTo)
          AND (@SearchText  IS NULL OR i.IssueNo LIKE N'%'+@SearchText+N'%'
                                    OR i.JobId   LIKE N'%'+@SearchText+N'%')
        GROUP BY i.IssueId, i.IssueNo, i.IssueDate, i.JobId, i.CostingType,
                 i.Notes, i.Status, i.CreatedBy, i.CreatedDate, i.ModifiedBy, i.ModifiedDate
    )
    SELECT * FROM cte
    ORDER BY
        CASE WHEN @SortColumn='IssueNo'   AND @SortDirection='ASC'  THEN IssueNo  END ASC,
        CASE WHEN @SortColumn='IssueNo'   AND @SortDirection='DESC' THEN IssueNo  END DESC,
        CASE WHEN @SortColumn='IssueDate' AND @SortDirection='ASC'  THEN IssueDate END ASC,
        CASE WHEN @SortColumn='Status'    AND @SortDirection='ASC'  THEN Status   END ASC,
        CASE WHEN @SortColumn='Status'    AND @SortDirection='DESC' THEN Status   END DESC,
        IssueDate DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO

IF OBJECT_ID(N'[proj].[sp_SearchStockReceipts]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchStockReceipts];
GO
CREATE PROCEDURE proj.sp_SearchStockReceipts
    @SearchText   NVARCHAR(100) = NULL,
    @ReceiptType  NVARCHAR(10)  = NULL,
    @Status       NVARCHAR(20)  = NULL,
    @JobId        NVARCHAR(50)  = NULL,
    @DateFrom     DATE          = NULL,
    @DateTo       DATE          = NULL,
    @PageNumber   INT           = 1,
    @PageSize     INT           = 20,
    @SortColumn   NVARCHAR(50)  = 'ReceiptDate',
    @SortDirection NVARCHAR(4)  = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;
    WITH cte AS (
        SELECT
            r.ReceiptId, r.ReceiptNo, r.ReceiptDate, r.ReceiptType,
            r.JobId, r.PoId, r.PoNumber, r.SupplierId, r.SupplierName, r.SupplierRef,
            r.Notes, r.Status, r.CreatedBy, r.CreatedDate, r.ModifiedBy, r.ModifiedDate,
            ISNULL(SUM(l.Qty * l.UnitCost), 0)   AS TotalCost,
            ISNULL(COUNT(l.ReceiptLineId), 0)     AS LineCount,
            COUNT(*) OVER ()                      AS TotalRows
        FROM proj.TBL_STOCK_RECEIPT r
        LEFT JOIN proj.TBL_STOCK_RECEIPT_LINE l ON l.ReceiptId = r.ReceiptId AND l.IsActive = 1
        WHERE r.IsActive = 1
          AND r.GrnId IS NULL
          AND (@ReceiptType IS NULL OR r.ReceiptType = @ReceiptType)
          AND (@Status      IS NULL OR r.Status      = @Status)
          AND (@JobId       IS NULL OR r.JobId        = @JobId)
          AND (@DateFrom    IS NULL OR r.ReceiptDate >= @DateFrom)
          AND (@DateTo      IS NULL OR r.ReceiptDate <= @DateTo)
          AND (@SearchText  IS NULL OR r.ReceiptNo LIKE N'%'+@SearchText+N'%'
                                    OR r.SupplierName LIKE N'%'+@SearchText+N'%'
                                    OR r.JobId LIKE N'%'+@SearchText+N'%')
        GROUP BY r.ReceiptId, r.ReceiptNo, r.ReceiptDate, r.ReceiptType,
                 r.JobId, r.PoId, r.PoNumber, r.SupplierId, r.SupplierName, r.SupplierRef,
                 r.Notes, r.Status, r.CreatedBy, r.CreatedDate, r.ModifiedBy, r.ModifiedDate
    )
    SELECT * FROM cte
    ORDER BY
        CASE WHEN @SortColumn='ReceiptNo'   AND @SortDirection='ASC'  THEN ReceiptNo   END ASC,
        CASE WHEN @SortColumn='ReceiptNo'   AND @SortDirection='DESC' THEN ReceiptNo   END DESC,
        CASE WHEN @SortColumn='ReceiptDate' AND @SortDirection='ASC'  THEN ReceiptDate END ASC,
        CASE WHEN @SortColumn='Status'      AND @SortDirection='ASC'  THEN Status      END ASC,
        CASE WHEN @SortColumn='Status'      AND @SortDirection='DESC' THEN Status      END DESC,
        ReceiptDate DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO

IF OBJECT_ID(N'[proj].[sp_SearchStockTransfers]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchStockTransfers];
GO

CREATE   PROCEDURE proj.sp_SearchStockTransfers
    @SearchText NVARCHAR(100) = NULL,
    @Status     NVARCHAR(200) = NULL,
    @FromJobId  NVARCHAR(50)  = NULL,
    @ToJobId    NVARCHAR(50)  = NULL,
    @DateFrom   DATE          = NULL,
    @DateTo     DATE          = NULL,
    @PageNumber INT           = 1,
    @PageSize   INT           = 20
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;
    SELECT
        t.TransferId, t.TransferNo, t.TransferDate, t.Status,
        t.FromJobId, fj.ProjectName AS FromJobName,
        t.ToJobId,   tj.ProjectName AS ToJobName,
        (SELECT COUNT(*) FROM proj.TBL_STOCK_TRANSFER_LINE l WHERE l.TransferId=t.TransferId AND l.IsActive=1) AS LineCount,
        t.CreatedBy, t.CreatedDate,
        COUNT(*) OVER() AS TotalRows
    FROM proj.TBL_STOCK_TRANSFER t
    LEFT JOIN proj.TBL_JOB fj ON fj.JobId = t.FromJobId
    LEFT JOIN proj.TBL_JOB tj ON tj.JobId = t.ToJobId
    WHERE t.IsActive = 1
      AND (@SearchText IS NULL OR t.TransferNo LIKE '%'+@SearchText+'%'
                               OR t.FromJobId  LIKE '%'+@SearchText+'%'
                               OR t.ToJobId    LIKE '%'+@SearchText+'%')
      AND (@Status    IS NULL OR t.Status IN (SELECT LTRIM(RTRIM(value)) FROM STRING_SPLIT(@Status, ',')))
      AND (@FromJobId IS NULL OR t.FromJobId = @FromJobId)
      AND (@ToJobId   IS NULL OR t.ToJobId   = @ToJobId)
      AND (@DateFrom  IS NULL OR t.TransferDate >= @DateFrom)
      AND (@DateTo    IS NULL OR t.TransferDate <= @DateTo)
    ORDER BY t.TransferId DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO

IF OBJECT_ID(N'[proj].[sp_SearchSupplierInvoices]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchSupplierInvoices];
GO

CREATE PROCEDURE proj.sp_SearchSupplierInvoices
    @SearchText     NVARCHAR(100) = NULL,
    @SupplierId     INT           = NULL,
    @Status         NVARCHAR(20)  = NULL,
    @DateFrom       DATE          = NULL,
    @DateTo         DATE          = NULL,
    @PageNumber     INT           = 1,
    @PageSize       INT           = 20
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        si.SupplierInvoiceId,
        si.InvoiceNo,
        si.SupplierInvRef,
        si.InvoiceDate,
        si.SupplierId,
        s.SupplierName,
        si.Status,
        si.SubTotal,
        si.TaxAmount,
        si.TotalAmount,
        ROUND(alloc.PaidBase / NULLIF(si.ExchangeRate, 0), 2) AS PaidAmount,
        si.TotalAmount - ROUND(alloc.PaidBase / NULLIF(si.ExchangeRate, 0), 2) AS BalanceAmount,
        si.DueDate,
        si.CreatedBy,
        si.CreatedDate,
        COUNT(*) OVER() AS TotalRows
    FROM proj.TBL_SUPPLIER_INVOICE si
    INNER JOIN proj.TBL_SUPPLIER s ON s.SupplierId = si.SupplierId
    OUTER APPLY (
        SELECT ISNULL(SUM(pva.AllocatedAmount), 0) AS PaidBase
        FROM proj.TBL_PAYMENT_VOUCHER_ALLOCATION pva
        JOIN proj.TBL_PAYMENT_VOUCHER pv ON pv.PvId = pva.PvId
        WHERE pva.SupplierInvoiceId = si.SupplierInvoiceId
          AND pva.IsActive = 1
          AND pv.Status   = 'Approved' AND pv.IsActive = 1
    ) alloc
    WHERE si.IsActive = 1
      AND (@SupplierId IS NULL OR si.SupplierId = @SupplierId)
      AND (@Status     IS NULL OR si.Status     = @Status)
      AND (@DateFrom   IS NULL OR si.InvoiceDate >= @DateFrom)
      AND (@DateTo     IS NULL OR si.InvoiceDate <= @DateTo)
      AND (@SearchText IS NULL OR si.InvoiceNo        LIKE '%' + @SearchText + '%'
                               OR si.SupplierInvRef   LIKE '%' + @SearchText + '%'
                               OR s.SupplierName      LIKE '%' + @SearchText + '%')
    ORDER BY si.InvoiceDate DESC, si.SupplierInvoiceId DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;
END
GO

IF OBJECT_ID(N'[proj].[sp_SearchSuppliers]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchSuppliers];
GO

CREATE   PROCEDURE proj.sp_SearchSuppliers
    @SearchText          NVARCHAR(200) = NULL,
    @SupplierCategoryId  INT           = NULL,
    @SupplierType        NVARCHAR(50)  = NULL,
    @CurrencyId          INT           = NULL,
    @PaymentTermsId      INT           = NULL,
    @IsActive            BIT           = NULL,
    @IsApprovedVendor    BIT           = NULL,
    @IsOnHold            BIT           = NULL,
    @CountryId           INT           = NULL,
    @PageNumber          INT           = 1,
    @PageSize            INT           = 20,
    @SortColumn          NVARCHAR(50)  = 'SupplierName',
    @SortDirection       NVARCHAR(4)   = 'ASC'
AS
BEGIN
    SET NOCOUNT ON;
    IF @SortDirection NOT IN ('ASC','DESC') SET @SortDirection = 'ASC';
    IF @SortColumn NOT IN ('SupplierCode','SupplierName','SupplierShortName','SupplierType',
        'SupplierCategoryName','CurrencyName','PaymentTermName','Mobile','Email',
        'StatusLabel','AccountManager','CountryName','Rating','TradeLicenseExpiry')
        SET @SortColumn = 'SupplierName';

    DECLARE @TotalRows INT;
    SELECT @TotalRows = COUNT(*) FROM proj.VW_SUPPLIER
    WHERE
        (@SearchText IS NULL OR @SearchText = '' OR
            SupplierCode      LIKE '%'+@SearchText+'%' OR
            SupplierName      LIKE '%'+@SearchText+'%' OR
            SupplierShortName LIKE '%'+@SearchText+'%' OR
            Mobile            LIKE '%'+@SearchText+'%' OR
            Email             LIKE '%'+@SearchText+'%' OR
            Phone             LIKE '%'+@SearchText+'%' OR
            VatNumber         LIKE '%'+@SearchText+'%' OR
            TradeLicenseNo    LIKE '%'+@SearchText+'%' OR
            AccountManager    LIKE '%'+@SearchText+'%')
        AND (@SupplierCategoryId IS NULL OR SupplierCategoryId = @SupplierCategoryId)
        AND (@SupplierType       IS NULL OR SupplierType        = @SupplierType)
        AND (@CurrencyId         IS NULL OR CurrencyId          = @CurrencyId)
        AND (@PaymentTermsId     IS NULL OR PaymentTermsId      = @PaymentTermsId)
        AND (@IsActive           IS NULL OR IsActive            = @IsActive)
        AND (@IsApprovedVendor   IS NULL OR IsApprovedVendor    = @IsApprovedVendor)
        AND (@IsOnHold           IS NULL OR IsOnHold            = @IsOnHold)
        AND (@CountryId          IS NULL OR CountryId           = @CountryId);

    SELECT *, @TotalRows AS TotalRows FROM proj.VW_SUPPLIER
    WHERE
        (@SearchText IS NULL OR @SearchText = '' OR
            SupplierCode      LIKE '%'+@SearchText+'%' OR
            SupplierName      LIKE '%'+@SearchText+'%' OR
            SupplierShortName LIKE '%'+@SearchText+'%' OR
            Mobile            LIKE '%'+@SearchText+'%' OR
            Email             LIKE '%'+@SearchText+'%' OR
            Phone             LIKE '%'+@SearchText+'%' OR
            VatNumber         LIKE '%'+@SearchText+'%' OR
            TradeLicenseNo    LIKE '%'+@SearchText+'%' OR
            AccountManager    LIKE '%'+@SearchText+'%')
        AND (@SupplierCategoryId IS NULL OR SupplierCategoryId = @SupplierCategoryId)
        AND (@SupplierType       IS NULL OR SupplierType        = @SupplierType)
        AND (@CurrencyId         IS NULL OR CurrencyId          = @CurrencyId)
        AND (@PaymentTermsId     IS NULL OR PaymentTermsId      = @PaymentTermsId)
        AND (@IsActive           IS NULL OR IsActive            = @IsActive)
        AND (@IsApprovedVendor   IS NULL OR IsApprovedVendor    = @IsApprovedVendor)
        AND (@IsOnHold           IS NULL OR IsOnHold            = @IsOnHold)
        AND (@CountryId          IS NULL OR CountryId           = @CountryId)
    ORDER BY
        CASE WHEN @SortDirection='ASC' THEN
            CASE @SortColumn
                WHEN 'SupplierCode'         THEN SupplierCode
                WHEN 'SupplierName'         THEN SupplierName
                WHEN 'SupplierShortName'    THEN SupplierShortName
                WHEN 'SupplierType'         THEN SupplierType
                WHEN 'SupplierCategoryName' THEN SupplierCategoryName
                WHEN 'CurrencyName'         THEN CurrencyName
                WHEN 'PaymentTermName'      THEN PaymentTermName
                WHEN 'Mobile'               THEN Mobile
                WHEN 'Email'                THEN Email
                WHEN 'StatusLabel'          THEN StatusLabel
                WHEN 'AccountManager'       THEN AccountManager
                WHEN 'CountryName'          THEN CountryName
            END
        END ASC,
        CASE WHEN @SortDirection='DESC' THEN
            CASE @SortColumn
                WHEN 'SupplierCode'         THEN SupplierCode
                WHEN 'SupplierName'         THEN SupplierName
                WHEN 'SupplierShortName'    THEN SupplierShortName
                WHEN 'SupplierType'         THEN SupplierType
                WHEN 'SupplierCategoryName' THEN SupplierCategoryName
                WHEN 'CurrencyName'         THEN CurrencyName
                WHEN 'PaymentTermName'      THEN PaymentTermName
                WHEN 'Mobile'               THEN Mobile
                WHEN 'Email'                THEN Email
                WHEN 'StatusLabel'          THEN StatusLabel
                WHEN 'AccountManager'       THEN AccountManager
                WHEN 'CountryName'          THEN CountryName
            END
        END DESC,
        SupplierName ASC
    OFFSET (@PageNumber-1)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO

IF OBJECT_ID(N'[proj].[sp_SearchUsers]') IS NOT NULL DROP PROCEDURE [proj].[sp_SearchUsers];
GO

CREATE   PROCEDURE proj.sp_SearchUsers
    @SearchText    NVARCHAR(200) = NULL,
    @Status        NVARCHAR(20)  = NULL,
    @RoleId        INT           = NULL,
    @PageNumber    INT           = 1,
    @PageSize      INT           = 20,
    @SortColumn    NVARCHAR(50)  = 'CreatedDate',
    @SortDirection NVARCHAR(4)   = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;
    DECLARE @SQL NVARCHAR(MAX), @OrderBy NVARCHAR(200);

    SET @OrderBy = CASE
        WHEN @SortColumn = 'UserName'    THEN 'u.UserName'
        WHEN @SortColumn = 'FullName'    THEN 'u.FullName'
        WHEN @SortColumn = 'Email'       THEN 'u.Email'
        WHEN @SortColumn = 'UserCode'    THEN 'u.UserCode'
        WHEN @SortColumn = 'RoleName'    THEN 'r.RoleName'
        ELSE 'u.CreatedDate'
    END + ' ' + CASE WHEN UPPER(@SortDirection) = 'ASC' THEN 'ASC' ELSE 'DESC' END;

    SET @SQL = N'
    SELECT
        u.UserId, u.UserCode, u.UserName, u.FullName, u.Email, u.Mobile,
        u.IsActive, u.IsLocked, u.CreatedDate, u.CreatedBy, u.ModifiedDate,
        u.LastLoginDate,
        r.RoleId, r.RoleName,
        COUNT(*) OVER() AS TotalRows
    FROM proj.TBL_USERS u
    LEFT JOIN proj.TBL_USER_ROLES ur ON ur.UserId = u.UserId
    LEFT JOIN proj.TBL_ROLES r       ON r.RoleId  = ur.RoleId AND r.IsActive = 1
    WHERE 1=1
      AND (@SearchText IS NULL OR
           u.UserName LIKE N''%'' + @SearchText + N''%'' OR
           u.FullName  LIKE N''%'' + @SearchText + N''%'' OR
           u.Email     LIKE N''%'' + @SearchText + N''%'' OR
           u.UserCode  LIKE N''%'' + @SearchText + N''%'')
      AND (@Status IS NULL OR
           (@Status = N''Active''   AND u.IsActive = 1 AND u.IsLocked = 0) OR
           (@Status = N''Inactive'' AND u.IsActive = 0) OR
           (@Status = N''Locked''   AND u.IsLocked = 1))
      AND (@RoleId IS NULL OR ur.RoleId = @RoleId)
    ORDER BY ' + @OrderBy + N'
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;';

    EXEC sp_executesql @SQL,
        N'@SearchText NVARCHAR(200), @Status NVARCHAR(20), @RoleId INT, @Offset INT, @PageSize INT',
        @SearchText, @Status, @RoleId, @Offset, @PageSize;
END
GO

IF OBJECT_ID(N'[proj].[sp_SetAdjustment]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetAdjustment];
GO
CREATE   PROCEDURE proj.sp_SetAdjustment
    @AdjustmentId   INT           = 0,
    @AdjustmentDate DATE          = NULL,
    @Reason         NVARCHAR(50)  = NULL,
    @Notes          NVARCHAR(500) = NULL,
    @CreatedBy      NVARCHAR(100) = NULL,
    @ModifiedBy     NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @AdjustmentId IS NULL OR @AdjustmentId <= 0
    BEGIN
        -- ── Mandatory field validation ───────────────────────────────────────
        IF NULLIF(@CreatedBy, '') IS NULL BEGIN RAISERROR('CreatedBy is required.', 16, 1); RETURN; END
        IF @@ERROR <> 0 RETURN;

        DECLARE @NumResult TABLE (DocNumber NVARCHAR(50), NewSeries INT);
        INSERT INTO @NumResult EXEC proj.sp_GetNextDocNumber 'ADJ';
        DECLARE @AdjNo NVARCHAR(50);
        SELECT @AdjNo = DocNumber FROM @NumResult;

        INSERT INTO proj.TBL_STOCK_ADJUSTMENT
            (AdjustmentNo, AdjustmentDate, Reason, Notes, Status, CreatedBy)
        VALUES (@AdjNo, ISNULL(@AdjustmentDate, CAST(GETDATE() AS DATE)), @Reason, @Notes, 'Draft', @CreatedBy);

        SELECT CAST(SCOPE_IDENTITY() AS INT) AS NewId, @AdjNo AS AdjustmentNo;
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM proj.TBL_STOCK_ADJUSTMENT WHERE AdjustmentId = @AdjustmentId AND Status IN ('Draft','Rejected')) BEGIN RAISERROR('Only Draft or Rejected adjustments can be edited.', 16, 1); RETURN; END

        UPDATE proj.TBL_STOCK_ADJUSTMENT
        SET AdjustmentDate = ISNULL(@AdjustmentDate, AdjustmentDate),
            Reason         = @Reason,
            Notes          = @Notes,
            ModifiedBy     = @ModifiedBy,
            ModifiedDate   = GETDATE()
        WHERE AdjustmentId = @AdjustmentId AND IsActive = 1;

        SELECT CAST(@AdjustmentId AS INT) AS NewId, AdjustmentNo
        FROM proj.TBL_STOCK_ADJUSTMENT WHERE AdjustmentId = @AdjustmentId;
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetAdjustmentLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetAdjustmentLine];
GO

CREATE     PROCEDURE proj.sp_SetAdjustmentLine
    @AdjustmentLineId INT           = 0,
    @AdjustmentId     INT,
    @ItemId           INT,
    @ItemDesc         NVARCHAR(300) = NULL,
    @AdjustQty        DECIMAL(18,4),
    @UomId            INT           = NULL,
    @UnitCost         DECIMAL(18,4) = 0,
    @Reason           NVARCHAR(50)  = NULL,
    @Notes            NVARCHAR(300) = NULL,
    @CreatedBy        NVARCHAR(100) = NULL,
    @ModifiedBy       NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- ── Parent status guard ───────────────────────────────────────────────
    IF NOT EXISTS (SELECT 1 FROM proj.TBL_STOCK_ADJUSTMENT WHERE AdjustmentId = @AdjustmentId AND Status IN ('Draft','Rejected'))
    BEGIN RAISERROR('Lines can only be modified on a Draft or Rejected adjustment.', 16, 1); RETURN; END

    -- ── Mandatory field validation ────────────────────────────────────────
    IF NULLIF(@AdjustmentId, 0) IS NULL BEGIN RAISERROR('AdjustmentId is required.',              16, 1); RETURN; END
    IF NULLIF(@ItemId, 0)       IS NULL BEGIN RAISERROR('Item is required.',                       16, 1); RETURN; END
    IF @AdjustQty = 0                   BEGIN RAISERROR('Adjustment quantity cannot be zero.',     16, 1); RETURN; END
    IF ISNULL(@UnitCost, 0)     < 0     BEGIN RAISERROR('Unit cost cannot be negative.',           16, 1); RETURN; END
    IF @@ERROR <> 0 RETURN;

    IF @AdjustmentLineId IS NULL OR @AdjustmentLineId <= 0
    BEGIN
        IF NULLIF(@CreatedBy, '') IS NULL BEGIN RAISERROR('CreatedBy is required.', 16, 1); RETURN; END
        IF @@ERROR <> 0 RETURN;

        DECLARE @LineNum INT;
        SELECT @LineNum = ISNULL(MAX(LineNum),0)+10
        FROM proj.TBL_STOCK_ADJUSTMENT_LINE WHERE AdjustmentId = @AdjustmentId AND IsActive = 1;

        INSERT INTO proj.TBL_STOCK_ADJUSTMENT_LINE
            (AdjustmentId, LineNum, ItemId, ItemDesc, AdjustQty, UomId, UnitCost, Reason, Notes, CreatedBy)
        VALUES (@AdjustmentId, @LineNum, @ItemId, @ItemDesc, @AdjustQty, NULLIF(@UomId,0), ISNULL(@UnitCost,0), @Reason, @Notes, @CreatedBy);

        SELECT CAST(SCOPE_IDENTITY() AS INT) AS NewId;
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_STOCK_ADJUSTMENT_LINE
        SET ItemId      = @ItemId,
            ItemDesc    = @ItemDesc,
            AdjustQty   = @AdjustQty,
            UomId       = NULLIF(@UomId,0),
            UnitCost    = ISNULL(@UnitCost,0),
            Reason      = @Reason,
            Notes       = @Notes,
            ModifiedBy  = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE AdjustmentLineId = @AdjustmentLineId;

        SELECT CAST(@AdjustmentLineId AS INT) AS NewId;
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetApprovalLevel]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetApprovalLevel];
GO


-- ── sp_SetApprovalLevel ──────────────────────────────────────
-- Insert or update a single approval level
-- ──────────────────────────────────────────────────────────────
CREATE PROCEDURE proj.sp_SetApprovalLevel
    @LevelId            int,
    @PolicyId           int,
    @LevelNo            int,
    @LevelName          nvarchar(100)   = NULL,
    @ApproverType       nvarchar(20),
    @ApproverId         int,
    @IsMandatory        bit             = 1,
    @AllowSelfApproval  bit             = 0,
    @TimeoutHours       int             = NULL,
    @OnTimeoutAction    nvarchar(20)    = 'Escalate',
    @IsActive           bit             = 1,
    @CreatedBy          nvarchar(50)    = NULL,
    @ModifiedBy         nvarchar(50)    = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @LevelId = 0
    BEGIN
        INSERT INTO proj.TBL_APPROVAL_LEVEL
            (PolicyId, LevelNo, LevelName, ApproverType, ApproverId,
             IsMandatory, AllowSelfApproval, TimeoutHours, OnTimeoutAction,
             IsActive, CreatedBy, CreatedDate)
        VALUES
            (@PolicyId, @LevelNo, @LevelName, @ApproverType, @ApproverId,
             @IsMandatory, @AllowSelfApproval, @TimeoutHours, @OnTimeoutAction,
             @IsActive, @CreatedBy, GETDATE());

        -- Update TotalLevels on policy
        UPDATE proj.TBL_APPROVAL_POLICY
        SET TotalLevels = (SELECT COUNT(*) FROM proj.TBL_APPROVAL_LEVEL
                           WHERE PolicyId = @PolicyId AND IsActive = 1)
        WHERE PolicyId = @PolicyId;

        SELECT 'Inserted' AS Result, SCOPE_IDENTITY() AS LevelId;
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_APPROVAL_LEVEL SET
            LevelNo          = @LevelNo,
            LevelName        = @LevelName,
            ApproverType     = @ApproverType,
            ApproverId       = @ApproverId,
            IsMandatory      = @IsMandatory,
            AllowSelfApproval= @AllowSelfApproval,
            TimeoutHours     = @TimeoutHours,
            OnTimeoutAction  = @OnTimeoutAction,
            IsActive         = @IsActive,
            ModifiedBy       = @ModifiedBy,
            ModifiedDate     = GETDATE()
        WHERE LevelId = @LevelId;
        SELECT 'Updated' AS Result, @LevelId AS LevelId;
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetApprovalPolicy]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetApprovalPolicy];
GO


-- ── sp_SetApprovalPolicy ─────────────────────────────────────
-- Insert or update a policy with its levels in one call
-- ──────────────────────────────────────────────────────────────
CREATE PROCEDURE proj.sp_SetApprovalPolicy
    @PolicyId       int,
    @ModuleId       int,
    @PolicyName     nvarchar(100),
    @AmountFrom     decimal(18,2) = NULL,
    @AmountTo       decimal(18,2) = NULL,
    @IsSequential   bit           = 1,
    @IsActive       bit           = 1,
    @SortOrder      int           = 0,
    @CreatedBy      nvarchar(50)  = NULL,
    @ModifiedBy     nvarchar(50)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @PolicyId = 0
    BEGIN
        INSERT INTO proj.TBL_APPROVAL_POLICY
            (ModuleId, PolicyName, AmountFrom, AmountTo,
             IsSequential, IsActive, SortOrder, TotalLevels, CreatedBy, CreatedDate)
        VALUES
            (@ModuleId, @PolicyName, @AmountFrom, @AmountTo,
             @IsSequential, @IsActive, @SortOrder, 0, @CreatedBy, GETDATE());
        SELECT 'Inserted' AS Result, SCOPE_IDENTITY() AS PolicyId;
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_APPROVAL_POLICY SET
            PolicyName   = @PolicyName,
            AmountFrom   = @AmountFrom,
            AmountTo     = @AmountTo,
            IsSequential = @IsSequential,
            IsActive     = @IsActive,
            SortOrder    = @SortOrder,
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE PolicyId = @PolicyId;
        SELECT 'Updated' AS Result, @PolicyId AS PolicyId;
    END
END;
GO

