CREATE PROCEDURE proj.sp_SetAppSetting
    @SettingKey   NVARCHAR(100),
    @SettingValue NVARCHAR(500),
    @ModifiedBy   NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM proj.TBL_APP_SETTINGS WHERE SettingKey = @SettingKey)
        UPDATE proj.TBL_APP_SETTINGS
        SET    SettingValue = @SettingValue,
               ModifiedBy   = @ModifiedBy,
               ModifiedDate = GETDATE()
        WHERE  SettingKey = @SettingKey;
    ELSE
        INSERT INTO proj.TBL_APP_SETTINGS (SettingKey, SettingValue, ModifiedBy, ModifiedDate)
