IF OBJECT_ID(N'[proj].[sp_SetBomDetail]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetBomDetail];
GO

CREATE       PROCEDURE proj.sp_SetBomDetail
    @BomId               INT            = 0,
    @BomHeaderId         INT,
    @JobId               NVARCHAR(50),
    @BomSectionId        INT,
    @ItemId              INT,
    @ItemDetailId        INT            = NULL,
    @SortOrder           INT            = 0,
    @BomRequestedQty     DECIMAL(18,4)  = 0,
    @UomId               INT,
    @BomPrice            DECIMAL(18,4)  = 0,
    @CurrencyId          INT            = NULL,
    @ExchangeRate        DECIMAL(18,6)  = 1,
    @ItemReqDate         DATE           = NULL,
    @ExpectedDelivery    DATE           = NULL,
    @IsCritical          BIT            = 0,
    @IsSubstituteAllowed BIT            = 0,
    @Remarks             NVARCHAR(500)  = NULL,
    @CreatedBy           NVARCHAR(100)  = NULL,
    @ModifiedBy          NVARCHAR(100)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    -- Block transactional saves on a closed job (Freezed/Completed/Cancelled).
    IF @JobId IS NOT NULL EXEC proj.sp_AssertJobOpen @JobId;


    -- ── Block edits if header is Approved ─────────────────────────────────
    IF EXISTS (SELECT 1 FROM proj.TBL_BOM_HEADER WHERE BomHeaderId = @BomHeaderId AND BomStatus = 'Approved')
    BEGIN
        RAISERROR('Cannot edit lines on an Approved BOM.', 16, 1); RETURN;
    END

    -- ── Mandatory field validation ────────────────────────────────────────
    IF NULLIF(@BomHeaderId,  0)  IS NULL BEGIN RAISERROR('BomHeaderId is required.',                      16, 1); RETURN; END
    IF NULLIF(@JobId,        '')  IS NULL BEGIN RAISERROR('Job is required.',                             16, 1); RETURN; END
    IF NULLIF(@BomSectionId, 0)  IS NULL BEGIN RAISERROR('BOM Section is required.',                     16, 1); RETURN; END
    IF NULLIF(@ItemId,       0)  IS NULL BEGIN RAISERROR('Item is required.',                             16, 1); RETURN; END
    IF NULLIF(@UomId,        0)  IS NULL BEGIN RAISERROR('Unit of Measure is required.',                 16, 1); RETURN; END
    IF ISNULL(@BomRequestedQty, 0) <= 0  BEGIN RAISERROR('BOM requested quantity must be greater than zero.', 16, 1); RETURN; END
    IF @@ERROR <> 0 RETURN;

    IF @BomId = 0
    BEGIN
        IF NULLIF(@CreatedBy, '') IS NULL BEGIN RAISERROR('CreatedBy is required.', 16, 1); RETURN; END
        IF @@ERROR <> 0 RETURN;

        IF @SortOrder = 0
            SELECT @SortOrder = ISNULL(MAX(SortOrder), 0) + 10
            FROM proj.TBL_BOM_DETAILS
            WHERE BomHeaderId = @BomHeaderId AND BomSectionId = @BomSectionId AND IsActive = 1;

        INSERT INTO proj.TBL_BOM_DETAILS
            (BomHeaderId, JobId, BomSectionId, ItemId, ItemDetailId, SortOrder,
             BomRequestedQty, BomReceivedQty, PrCreatedQty, PoCreatedQty,
             UomId, BomPrice, CurrencyId, ExchangeRate,
             ItemReqDate, ExpectedDelivery, BomStatus,
             IsCritical, IsSubstituteAllowed, Remarks,
             IsActive, CreatedBy, CreatedDate)
        VALUES
            (@BomHeaderId, @JobId, @BomSectionId, @ItemId, @ItemDetailId, @SortOrder,
             @BomRequestedQty, 0, 0, 0,
             @UomId, @BomPrice, @CurrencyId, ISNULL(@ExchangeRate, 1),
             @ItemReqDate, @ExpectedDelivery, 'Pending',
             ISNULL(@IsCritical, 0), ISNULL(@IsSubstituteAllowed, 0), @Remarks,
             1, @CreatedBy, GETDATE());

        DECLARE @NewBomId INT = SCOPE_IDENTITY();

        UPDATE proj.TBL_BOM_HEADER
        SET TotalBomValue = (
            SELECT ISNULL(SUM(BomRequestedQty * BomPrice * ExchangeRate), 0)
            FROM proj.TBL_BOM_DETAILS
            WHERE BomHeaderId = @BomHeaderId AND IsActive = 1
        ),
        ModifiedBy = @CreatedBy, ModifiedDate = GETDATE()
        WHERE BomHeaderId = @BomHeaderId;

        SELECT @NewBomId AS BomId;
    END
    ELSE
    BEGIN
        DECLARE @CurrentPrQty DECIMAL(18,4);
        SELECT @CurrentPrQty = ISNULL(PrCreatedQty, 0)
        FROM proj.TBL_BOM_DETAILS
        WHERE BomId = @BomId AND IsActive = 1;

        IF @BomRequestedQty < @CurrentPrQty
        BEGIN
            DECLARE @ErrMsg NVARCHAR(300) =
                N'Requested qty cannot be less than PR raised qty (' +
                CAST(@CurrentPrQty AS NVARCHAR(50)) + N').';
            RAISERROR(@ErrMsg, 16, 1); RETURN;
        END

        UPDATE proj.TBL_BOM_DETAILS
        SET BomSectionId        = @BomSectionId,
            ItemId              = @ItemId,
            ItemDetailId        = @ItemDetailId,
            SortOrder           = @SortOrder,
            BomRequestedQty     = @BomRequestedQty,
            UomId               = @UomId,
            BomPrice            = @BomPrice,
            CurrencyId          = @CurrencyId,
            ExchangeRate        = ISNULL(@ExchangeRate, 1),
            ItemReqDate         = @ItemReqDate,
            ExpectedDelivery    = @ExpectedDelivery,
            IsCritical          = ISNULL(@IsCritical,          IsCritical),
            IsSubstituteAllowed = ISNULL(@IsSubstituteAllowed, IsSubstituteAllowed),
            Remarks             = @Remarks,
            ModifiedBy          = @ModifiedBy,
            ModifiedDate        = GETDATE(),
            BomStatus           = CASE
                WHEN BomReceivedQty >= @BomRequestedQty THEN 'FullyReceived'
                WHEN BomReceivedQty  > 0                THEN 'PartialReceived'
                WHEN PoCreatedQty   >= @BomRequestedQty THEN 'PORaised'
                WHEN PoCreatedQty    > 0                THEN 'POPartial'
                WHEN PrCreatedQty   >= @BomRequestedQty THEN 'PRRaised'
                WHEN PrCreatedQty    > 0                THEN 'PRPartial'
                ELSE                                         'Pending'
            END
        WHERE BomId = @BomId;

        UPDATE proj.TBL_BOM_HEADER
        SET TotalBomValue = (
            SELECT ISNULL(SUM(BomRequestedQty * BomPrice * ExchangeRate), 0)
            FROM proj.TBL_BOM_DETAILS
            WHERE BomHeaderId = @BomHeaderId AND IsActive = 1
        ),
        ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE()
        WHERE BomHeaderId = @BomHeaderId;

        SELECT @BomId AS BomId;
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_SetBomHeader]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetBomHeader];
GO

CREATE     PROCEDURE proj.sp_SetBomHeader
    @BomHeaderId    INT            = 0,
    @JobId          NVARCHAR(50),
    @JobTypeId      NVARCHAR(50)   = NULL,
    @BomDate        DATE           = NULL,
    @BomDescription NVARCHAR(MAX)  = NULL,
    @BomVersion     TINYINT        = 1,
    @CreatedBy      NVARCHAR(100)  = NULL,
    @ModifiedBy     NVARCHAR(100)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    -- Block transactional saves on a closed job (Freezed/Completed/Cancelled).
    IF @JobId IS NOT NULL EXEC proj.sp_AssertJobOpen @JobId;


    -- Validate job exists
    IF NOT EXISTS (SELECT 1 FROM proj.TBL_JOB WHERE JobId = @JobId)
    BEGIN
        RAISERROR('Job ID ''%s'' does not exist.', 16, 1, @JobId);
        RETURN;
    END

    -- Resolve JobTypeId
    DECLARE @ResolvedJobTypeId NVARCHAR(50) =
        ISNULL(NULLIF(LTRIM(RTRIM(@JobTypeId)), ''),
               (SELECT JobTypeId FROM proj.TBL_JOB WHERE JobId = @JobId));

    IF @BomHeaderId = 0
    BEGIN
        -- Job status guard (new BOMs only)
        DECLARE @IsClosed BIT = 0, @StatusName NVARCHAR(50) = '';
        SELECT @IsClosed = js.IsClosed, @StatusName = js.StatusName
        FROM   proj.TBL_JOB j
        JOIN   proj.TBL_JOB_STATUS js ON js.JobStatusId = j.JobStatusId
        WHERE  j.JobId = @JobId;
        IF @IsClosed = 1
        BEGIN
            DECLARE @ErrMsg NVARCHAR(200) = 'Job ' + @JobId + ' is ' + @StatusName + '. Revise the job to create new transactions.';
            RAISERROR('%s', 16, 1, @ErrMsg);
            RETURN;
        END

        -- Check no BOM already exists for this job
        IF EXISTS (SELECT 1 FROM proj.TBL_BOM_HEADER WHERE JobId = @JobId AND IsActive = 1)
        BEGIN
            RAISERROR('A BOM already exists for Job ''%s''.', 16, 1, @JobId);
            RETURN;
        END

        INSERT INTO proj.TBL_BOM_HEADER
            (JobId, JobTypeId, BomDate, BomDescription, BomVersion, BomStatus, TotalBomValue, CreatedBy, CreatedDate)
        VALUES
            (@JobId,
             @ResolvedJobTypeId,
             ISNULL(@BomDate, CAST(GETDATE() AS DATE)),
             @BomDescription,
             ISNULL(@BomVersion, 1),
             'Draft',
             0,
             @CreatedBy,
             GETDATE());

        SELECT SCOPE_IDENTITY() AS BomHeaderId;
    END
    ELSE
    BEGIN
        -- Block edits on Approved BOMs
        IF EXISTS (SELECT 1 FROM proj.TBL_BOM_HEADER WHERE BomHeaderId = @BomHeaderId AND BomStatus = 'Approved')
        BEGIN
            RAISERROR('Cannot edit an Approved BOM.', 16, 1);
            RETURN;
        END

        UPDATE proj.TBL_BOM_HEADER
        SET
            JobTypeId      = ISNULL(@ResolvedJobTypeId, JobTypeId),
            BomDate        = ISNULL(@BomDate, BomDate),
            BomDescription = @BomDescription,
            BomVersion     = ISNULL(@BomVersion, BomVersion),
            ModifiedBy     = @ModifiedBy,
            ModifiedDate   = GETDATE()
        WHERE BomHeaderId = @BomHeaderId;

        SELECT @BomHeaderId AS BomHeaderId;
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetCnAllocation]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetCnAllocation];
GO

CREATE PROCEDURE proj.sp_SetCnAllocation
    @AllocationId    INT           = 0,
    @CnId            INT,
    @InvoiceId       INT,
    @AllocatedAmount DECIMAL(18,4),   -- received from frontend in invoice currency
    @CreatedBy       NVARCHAR(100) = NULL,
    @ModifiedBy      NVARCHAR(100) = NULL,
    @Reason          NVARCHAR(500) = NULL,
    @PasswordHash    NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CnStatus     NVARCHAR(20),
            @CnCustomer   INT,
            @CreditAmount DECIMAL(18,4),
            @ExchangeRate DECIMAL(18,6);

    SELECT @CnStatus     = Status,
           @CnCustomer   = CustomerId,
           @CreditAmount = CreditAmount,
           @ExchangeRate = ISNULL(NULLIF(ExchangeRate, 0), 1)
    FROM   proj.TBL_CREDIT_NOTE
    WHERE  CnId = @CnId AND IsActive = 1;

    IF @CnStatus IS NULL
        BEGIN RAISERROR('Credit note not found.', 16, 1); RETURN; END
    IF @CnStatus <> 'Approved'
        BEGIN RAISERROR('The credit note must be Approved before registering it against invoices.', 16, 1); RETURN; END
    IF ISNULL(@AllocatedAmount, 0) <= 0
        BEGIN RAISERROR('Allocated amount must be greater than zero.', 16, 1); RETURN; END

    IF NULLIF(LTRIM(RTRIM(ISNULL(@Reason, ''))), '') IS NULL
        BEGIN RAISERROR('A reason is required to modify an allocation on an approved credit note.', 16, 1); RETURN; END
    IF NULLIF(@PasswordHash, '') IS NULL
        BEGIN RAISERROR('Password is required.', 16, 1); RETURN; END

    DECLARE @ActionBy NVARCHAR(100) = ISNULL(@ModifiedBy, @CreatedBy);
    IF NOT EXISTS (
        SELECT 1
        FROM   proj.TBL_USER_ROLES  ur
        JOIN   proj.TBL_ROLE_SECRET rs ON rs.RoleId  = ur.RoleId
        JOIN   proj.TBL_USERS       u  ON u.UserId   = ur.UserId
        WHERE  u.Username         = @ActionBy
          AND  rs.SecretKey       = 'RV_REVISE'
          AND  rs.SecretValueHash = @PasswordHash
    )
        BEGIN RAISERROR('Incorrect password. You do not have permission to modify allocations on this credit note.', 16, 1); RETURN; END

    DECLARE @InvCustomer     INT,
            @InvStatus       NVARCHAR(30),
            @InvTotal        DECIMAL(18,4),
            @InvExchangeRate DECIMAL(18,6);

    SELECT @InvCustomer     = CustomerId,
           @InvStatus       = Status,
           @InvTotal        = TotalAmount,
           @InvExchangeRate = ISNULL(NULLIF(ExchangeRate, 0), 1)
    FROM   proj.TBL_INVOICE
    WHERE  InvoiceId = @InvoiceId AND IsActive = 1;

    IF @InvCustomer IS NULL
        BEGIN RAISERROR('Invoice not found.', 16, 1); RETURN; END
    IF @InvCustomer <> @CnCustomer
        BEGIN RAISERROR('Invoice belongs to a different customer.', 16, 1); RETURN; END
    IF @InvStatus <> 'Confirmed'
        BEGIN RAISERROR('Only Confirmed invoices can have credit applied.', 16, 1); RETURN; END

    -- Convert incoming invoice-currency amount to base for storage
    DECLARE @AllocatedAmountBase DECIMAL(18,4) = @AllocatedAmount * @InvExchangeRate;

    -- Outstanding in base: invoice total base minus other CN credits (base) minus RV payments (base)
    DECLARE @PaidByOthers DECIMAL(18,4);
    SELECT @PaidByOthers = ISNULL(SUM(a.AllocatedAmount), 0)
    FROM   proj.TBL_CREDIT_NOTE_ALLOCATION a
    JOIN   proj.TBL_CREDIT_NOTE cn ON cn.CnId = a.CnId
    WHERE  a.InvoiceId = @InvoiceId AND a.IsActive = 1
      AND  cn.Status = 'Approved' AND cn.IsActive = 1 AND cn.CnId <> @CnId;

    DECLARE @RvPaid DECIMAL(18,4);
    SELECT @RvPaid = ISNULL(SUM(a.AllocatedAmount), 0)
    FROM   proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
    JOIN   proj.TBL_RECEIPT_VOUCHER rv ON rv.RvId = a.RvId
    WHERE  a.InvoiceId = @InvoiceId AND a.IsActive = 1
      AND  rv.Status = 'Approved' AND rv.IsActive = 1;

    DECLARE @Outstanding DECIMAL(18,4) = @InvTotal * @InvExchangeRate - @PaidByOthers - @RvPaid;
    IF @AllocatedAmountBase > @Outstanding
    BEGIN
        DECLARE @m1 NVARCHAR(400) =
            'Allocation (' + CAST(@AllocatedAmount AS NVARCHAR(30)) +
            ') exceeds the invoice outstanding balance (' +
            CAST(ROUND(@Outstanding / @InvExchangeRate, 2) AS NVARCHAR(30)) + ').';
        RAISERROR(@m1, 16, 1); RETURN;
    END

    -- CN balance: all base allocations on this CN must not exceed CreditAmount × CN rate
    DECLARE @OtherAlloc DECIMAL(18,4);
    SELECT @OtherAlloc = ISNULL(SUM(AllocatedAmount), 0)
    FROM   proj.TBL_CREDIT_NOTE_ALLOCATION
    WHERE  CnId = @CnId AND IsActive = 1 AND InvoiceId <> @InvoiceId;

    DECLARE @CnAvailable DECIMAL(18,4) = @CreditAmount * @ExchangeRate;
    IF (@OtherAlloc + @AllocatedAmountBase) > @CnAvailable
    BEGIN
        DECLARE @m2 NVARCHAR(400) =
            'Total allocations (' +
            CAST(ROUND((@OtherAlloc + @AllocatedAmountBase) / @ExchangeRate, 2) AS NVARCHAR(30)) +
            ') would exceed the CN available balance (' +
            CAST(@CreditAmount AS NVARCHAR(30)) + ').';
        RAISERROR(@m2, 16, 1); RETURN;
    END

    DECLARE @ExistingId INT;
    SELECT @ExistingId = AllocationId
    FROM   proj.TBL_CREDIT_NOTE_ALLOCATION
    WHERE  CnId = @CnId AND InvoiceId = @InvoiceId AND IsActive = 1;

    IF @ExistingId IS NOT NULL
        UPDATE proj.TBL_CREDIT_NOTE_ALLOCATION
        SET    AllocatedAmount = @AllocatedAmountBase,
               Reason         = @Reason,
               ModifiedBy     = @ActionBy,
               ModifiedDate   = GETDATE()
        WHERE  AllocationId = @ExistingId;
    ELSE
        INSERT INTO proj.TBL_CREDIT_NOTE_ALLOCATION
            (CnId, InvoiceId, AllocatedAmount, Reason, CreatedBy)
        VALUES (@CnId, @InvoiceId, @AllocatedAmountBase, @Reason, @CreatedBy);

    -- Refresh CN header: sum of base allocations ÷ CN rate = allocated in CN's own currency
    UPDATE proj.TBL_CREDIT_NOTE
    SET    AllocatedAmount = (
               SELECT ISNULL(SUM(AllocatedAmount), 0) / @ExchangeRate
               FROM   proj.TBL_CREDIT_NOTE_ALLOCATION
               WHERE  CnId = @CnId AND IsActive = 1
           ),
           ModifiedDate = GETDATE()
    WHERE  CnId = @CnId;

    DECLARE @JobId NVARCHAR(50) = (SELECT JobId FROM proj.TBL_INVOICE WHERE InvoiceId = @InvoiceId);
    IF NULLIF(@JobId, '') IS NOT NULL
        EXEC proj.sp_RecalcJobCredits @JobId, @ActionBy;

    SELECT @CnId AS CnId;
END
GO

