IF OBJECT_ID(N'[proj].[sp_SetCountry]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetCountry];
GO
CREATE PROCEDURE [PROJ].[sp_SetCountry]
    @CountryName NVARCHAR(100), @CountryCode NVARCHAR(10),@IsActive bit,@CreatedBy nvarchar(50),@ModifiedBy nvarchar(50),@SortOrder int=1,
    @CountryId INT
AS
BEGIN
    SET NOCOUNT ON;

    -- 1. Check for Duplicates
    -- We check if the name exists, but ignore the current ID (for updates)
    IF EXISTS (SELECT 1 FROM TBL_COUNTRY 
               WHERE( CountryName = @CountryName OR CountryCode = @CountryCode )
               AND CountryId <> @CountryId)
    BEGIN
        -- Return -1 to indicate a Duplicate Name exists
        SELECT -1;
        RETURN;
    END

    -- 2. Insert Logic
    IF @CountryId = 0
    BEGIN
        INSERT INTO TBL_COUNTRY (CountryCode,CountryName,CreatedBy,SortOrder,IsActive)
        VALUES (@CountryCode,@CountryName,@CreatedBy,@SortOrder,@IsActive);
        
        SELECT SCOPE_IDENTITY(); -- Returns the new ID
    END
    -- 3. Update Logic
    ELSE
    BEGIN
        UPDATE TBL_COUNTRY 
        SET CountryCode = @CountryCode  ,CountryName=@CountryName,ModifiedBy=@ModifiedBy,ModifiedDate=GETDATE(),SortOrder=@SortOrder,IsActive=@IsActive
        WHERE CountryId = @CountryId;
        
        SELECT @CountryId; -- Returns the existing ID to confirm success
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_SetCreditNote]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetCreditNote];
GO

CREATE PROCEDURE proj.sp_SetCreditNote
    @CnId         INT            = 0,
    @CnDate       DATE           = NULL,
    @CustomerId   INT,
    @CurrencyId   INT,
    @ExchangeRate DECIMAL(18,6)  = 1,
    @CreditAmount DECIMAL(18,4)  = 0,
    @CreditType   NVARCHAR(50)   = NULL,
    @Reason       NVARCHAR(500)  = NULL,
    @Notes        NVARCHAR(1000) = NULL,
    @CreatedBy    NVARCHAR(100)  = NULL,
    @ModifiedBy   NVARCHAR(100)  = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NULLIF(@CustomerId,  0) IS NULL  BEGIN RAISERROR('Customer is required.',                          16, 1); RETURN; END
    IF NULLIF(@CurrencyId,  0) IS NULL  BEGIN RAISERROR('Currency is required.',                          16, 1); RETURN; END
    IF ISNULL(@CreditAmount, 0) <= 0    BEGIN RAISERROR('Credit amount must be greater than zero.',       16, 1); RETURN; END
    IF NULLIF(LTRIM(RTRIM(ISNULL(@CreditType,''))), '') IS NULL
        BEGIN RAISERROR('Credit type is required.',                                                       16, 1); RETURN; END
    IF NULLIF(LTRIM(RTRIM(ISNULL(@Reason,''))), '') IS NULL
        BEGIN RAISERROR('Reason is required.',                                                             16, 1); RETURN; END

    IF @CnId IS NULL OR @CnId <= 0
    BEGIN
        IF NULLIF(@CreatedBy, '') IS NULL BEGIN RAISERROR('CreatedBy is required.', 16, 1); RETURN; END

        DECLARE @NumResult TABLE (DocNumber NVARCHAR(50), NewSeries INT);
        INSERT INTO @NumResult EXEC proj.sp_GetNextDocNumber 'CN';
        DECLARE @CnNo NVARCHAR(50); SELECT @CnNo = DocNumber FROM @NumResult;

        INSERT INTO proj.TBL_CREDIT_NOTE
            (CnNumber, CnDate, CustomerId, CurrencyId, ExchangeRate, CreditAmount,
             CreditType, Reason, Notes, Status, CreatedBy)
        VALUES
            (@CnNo, ISNULL(@CnDate, CAST(GETDATE() AS DATE)), @CustomerId, @CurrencyId,
             ISNULL(@ExchangeRate, 1), @CreditAmount,
             NULLIF(@CreditType,''), @Reason, @Notes, 'Draft', @CreatedBy);

        SELECT CAST(SCOPE_IDENTITY() AS INT) AS NewId, @CnNo AS CnNumber;
    END
    ELSE
    BEGIN
        IF EXISTS (SELECT 1 FROM proj.TBL_CREDIT_NOTE WHERE CnId = @CnId AND Status <> 'Draft')
            BEGIN RAISERROR('Only Draft credit notes can be edited.', 16, 1); RETURN; END

        -- AllocatedAmount is now BASE; convert @CreditAmount to base before comparing
        IF @CreditAmount * ISNULL(NULLIF(@ExchangeRate, 0), 1) <
           (SELECT ISNULL(SUM(AllocatedAmount),0) FROM proj.TBL_CREDIT_NOTE_ALLOCATION WHERE CnId = @CnId AND IsActive = 1)
            BEGIN RAISERROR('Credit amount cannot be less than the amount already allocated. Remove allocations first.', 16, 1); RETURN; END

        UPDATE proj.TBL_CREDIT_NOTE
        SET    CnDate        = ISNULL(@CnDate, CnDate),
               CustomerId    = @CustomerId,
               CurrencyId    = @CurrencyId,
               ExchangeRate  = ISNULL(@ExchangeRate, ExchangeRate),
               CreditAmount  = @CreditAmount,
               CreditType    = NULLIF(@CreditType,''),
               Reason        = @Reason,
               Notes         = @Notes,
               ModifiedBy    = @ModifiedBy,
               ModifiedDate  = GETDATE()
        WHERE  CnId = @CnId AND IsActive = 1;

        SELECT CAST(@CnId AS INT) AS NewId, CnNumber FROM proj.TBL_CREDIT_NOTE WHERE CnId = @CnId;
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_SetCustomer]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetCustomer];
GO
CREATE PROCEDURE [PROJ].[sp_SetCustomer]
    @CustomerId INT,
    @CustomerCode NVARCHAR(50),
    @CustomerName NVARCHAR(100),
    @CustomerRef NVARCHAR(50) = NULL,
    @CustomerShortName NVARCHAR(50) = NULL,
    @CustomerType NVARCHAR(50) = NULL,
    @CustomerCategoryId INT = NULL,
    @Phone NVARCHAR(50) = NULL,
    @Mobile NVARCHAR(50) = NULL,
    @Email NVARCHAR(50) = NULL,
    @Web NVARCHAR(50) = NULL,
    @CurrencyId INT,
    @CreditLimit DECIMAL(18, 2) = NULL,
    @CreditDays INT = NULL,
    @PaymentTermsId INT,
    @VatNumber NVARCHAR(50) = NULL,
    @TaxNumber NVARCHAR(50) = NULL,
    @SalesPerson NVARCHAR(50) = NULL,
    @Remarks NVARCHAR(100) = NULL,
    @IsActive BIT,
    @CreatedBy NVARCHAR(50),
    @ModifiedBy NVARCHAR(50) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- 1. Check if CustomerCode already exists for a DIFFERENT customer
    IF EXISTS (SELECT 1 FROM [TBL_CUSTOMER] 
               WHERE CustomerCode = @CustomerCode AND CustomerId <> @CustomerId)
    BEGIN
        SELECT '-1'; -- Return -1 to the Controller to indicate "Duplicate Code"
        RETURN;
    END

    IF @CustomerId = 0
    BEGIN
        -- INSERT NEW RECORD
        INSERT INTO [TBL_CUSTOMER] (
            CustomerCode, CustomerName, CustomerRef, CustomerShortName, CustomerType,
            CustomerCategoryId, Phone, Mobile, Email, Web, CurrencyId,
            CreditLimit, CreditDays, PaymentTermsId, VatNumber, TaxNumber,
            SalesPerson, Remarks, IsActive, CreatedBy, CreatedDate
        )
        VALUES (
            @CustomerCode, @CustomerName, @CustomerRef, @CustomerShortName, @CustomerType,
            @CustomerCategoryId, @Phone, @Mobile, @Email, @Web, @CurrencyId,
            @CreditLimit, @CreditDays, @PaymentTermsId, @VatNumber, @TaxNumber,
            @SalesPerson, @Remarks, @IsActive, @CreatedBy, GETDATE()
        );

        SELECT SCOPE_IDENTITY(); -- Return the new ID
    END
    ELSE
    BEGIN
        -- UPDATE EXISTING RECORD
        UPDATE [TBL_CUSTOMER]
        SET CustomerCode = @CustomerCode,
            CustomerName = @CustomerName,
            CustomerRef = @CustomerRef,
            CustomerShortName = @CustomerShortName,
            CustomerType = @CustomerType,
            CustomerCategoryId = @CustomerCategoryId,
            Phone = @Phone,
            Mobile = @Mobile,
            Email = @Email,
            Web = @Web,
            CurrencyId = @CurrencyId,
            CreditLimit = @CreditLimit,
            CreditDays = @CreditDays,
            PaymentTermsId = @PaymentTermsId,
            VatNumber = @VatNumber,
            TaxNumber = @TaxNumber,
            SalesPerson = @SalesPerson,
            Remarks = @Remarks,
            IsActive = @IsActive,
            ModifiedBy = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE CustomerId = @CustomerId;

        SELECT @CustomerId; -- Return the updated ID
    END
END
GO

