CREATE PROCEDURE [PROJ].[sp_SetCustomerAddress]
    @CustomerAddressId INT,
    @CustomerId INT,
    @AddressType NVARCHAR(50),
    @AddressLine1 NVARCHAR(200),
    @AddressLine2 NVARCHAR(200) = NULL,
    @City NVARCHAR(100) = NULL,
    @State NVARCHAR(100) = NULL,
    @CountryId INT,
    @PostalCode NVARCHAR(20) = NULL,
    @POBox NVARCHAR(20) = NULL,
    @IsDefault BIT,
    @CreatedBy NVARCHAR(50),
    @ModifiedBy NVARCHAR(50) = NULL,
    @IsActive BIT
AS
BEGIN
    SET NOCOUNT ON;

    -- If this address is set as default, unset others for this customer
    IF @IsDefault = 1
    BEGIN
        UPDATE [TBL_CUSTOMER_ADDRESS] SET IsDefault = 0 WHERE CustomerId = @CustomerId;
    END

    IF @CustomerAddressId = 0
    BEGIN
        INSERT INTO [TBL_CUSTOMER_ADDRESS] (
            CustomerId, AddressType, AddressLine1, AddressLine2, City, State, CountryId, 
            PostalCode, POBox, IsDefault, CreatedDate, CreatedBy, IsActive
        )
        VALUES (
            @CustomerId, @AddressType, @AddressLine1, @AddressLine2, @City, @State, @CountryId, 
            @PostalCode, @POBox, @IsDefault, GETDATE(), @CreatedBy, @IsActive
        );
        SELECT SCOPE_IDENTITY();
    END
    ELSE
    BEGIN
        UPDATE [TBL_CUSTOMER_ADDRESS]
        SET AddressType = @AddressType, AddressLine1 = @AddressLine1, AddressLine2 = @AddressLine2,
            City = @City, State = @State, CountryId = @CountryId, PostalCode = @PostalCode,
            POBox = @POBox, IsDefault = @IsDefault, ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE(),
            IsActive = @IsActive
        WHERE CustomerAddressId = @CustomerAddressId;
        SELECT @CustomerAddressId;
    END
END
GO

