CREATE PROCEDURE [PROJ].[sp_SetCustomerContact]
    @CustomerContactId INT,
    @CustomerId INT,
    @ContactTitle NVARCHAR(10) = NULL,
    @ContactName NVARCHAR(100),
    @Designation NVARCHAR(100) = NULL,
    @Phone NVARCHAR(50) = NULL,
    @Mobile NVARCHAR(50) = NULL,
    @Email NVARCHAR(150) = NULL,
    @IsPrimary BIT,
    @CreatedBy NVARCHAR(50),
    @ModifiedBy NVARCHAR(50) = NULL,
    @IsActive BIT
AS
BEGIN
    SET NOCOUNT ON;

    -- Ensure only one primary contact exists
    IF @IsPrimary = 1
    BEGIN
        UPDATE [TBL_CUSTOMER_CONTACT] SET IsPrimary = 0 WHERE CustomerId = @CustomerId;
    END

    IF @CustomerContactId = 0
    BEGIN
        INSERT INTO [TBL_CUSTOMER_CONTACT] (
            CustomerId, ContactTitle, ContactName, Designation, Phone, Mobile, Email, 
            IsPrimary, CreatedDate, CreatedBy, IsActive
        )
        VALUES (
            @CustomerId, @ContactTitle, @ContactName, @Designation, @Phone, @Mobile, @Email, 
            @IsPrimary, GETDATE(), @CreatedBy, @IsActive
        );
        SELECT SCOPE_IDENTITY();
    END
    ELSE
    BEGIN
        UPDATE [TBL_CUSTOMER_CONTACT]
        SET ContactTitle = @ContactTitle, ContactName = @ContactName, Designation = @Designation,
            Phone = @Phone, Mobile = @Mobile, Email = @Email, IsPrimary = @IsPrimary,
            ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE(), IsActive = @IsActive
        WHERE CustomerContactId = @CustomerContactId;
        SELECT @CustomerContactId;
    END
END
