CREATE   PROCEDURE proj.sp_SetCustomerCreditFlag
    @CustomerId     INT,
    @CreditFlag     NVARCHAR(10),
    @CreditFlagNote NVARCHAR(500) = NULL,
    @CreditFlagBy   NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @CreditFlag NOT IN ('GREEN','YELLOW','RED')
    BEGIN
        RAISERROR('Invalid credit flag. Allowed: GREEN, YELLOW, RED.', 16, 1);
        RETURN;
    END

    IF NOT EXISTS (SELECT 1 FROM proj.TBL_CUSTOMER WHERE CustomerId = @CustomerId)
    BEGIN
        RAISERROR('Customer not found.', 16, 1);
        RETURN;
    END

    UPDATE proj.TBL_CUSTOMER
    SET CreditFlag     = @CreditFlag,
        CreditFlagNote = @CreditFlagNote,
        CreditFlagBy   = @CreditFlagBy,
        CreditFlagDate = GETDATE(),
        ModifiedBy     = @CreditFlagBy,
        ModifiedDate   = GETDATE()
    WHERE CustomerId = @CustomerId;

    SELECT @CustomerId AS CustomerId, @CreditFlag AS CreditFlag;
END
GO

IF OBJECT_ID(N'[proj].[sp_SetCustomerCreditHold]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetCustomerCreditHold];
