CREATE   PROCEDURE [PROJ].[sp_SetCustomerCreditHold]
    @CustomerId   INT,
    @CreditHold   BIT,
    @CreditHoldBy NVARCHAR(50),
    @CreditHoldNote NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE PROJ.TBL_CUSTOMER
    SET
        CreditHold     = @CreditHold,
        CreditHoldBy   = CASE WHEN @CreditHold = 1 THEN @CreditHoldBy ELSE NULL END,
        CreditHoldDate = CASE WHEN @CreditHold = 1 THEN GETDATE()      ELSE NULL END,
        CreditHoldNote = CASE WHEN @CreditHold = 1 THEN @CreditHoldNote ELSE NULL END,
        ModifiedBy     = @CreditHoldBy,
        ModifiedDate   = GETDATE()
    WHERE CustomerId = @CustomerId;

    SELECT @CustomerId;
END
GO

IF OBJECT_ID(N'[proj].[sp_SetDebitNote]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetDebitNote];
