CREATE PROCEDURE proj.sp_SetDebitNote
    @DnId         INT            = 0,
    @DnDate       DATE           = NULL,
    @SupplierId   INT,
    @CurrencyId   INT,
    @ExchangeRate DECIMAL(18,6)  = 1,
    @DebitAmount  DECIMAL(18,4)  = 0,
    @DebitType    NVARCHAR(50)   = NULL,
    @Reason       NVARCHAR(500)  = NULL,
    @Notes        NVARCHAR(1000) = NULL,
    @CreatedBy    NVARCHAR(100)  = NULL,
    @ModifiedBy   NVARCHAR(100)  = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NULLIF(@SupplierId,  0) IS NULL  BEGIN RAISERROR('Supplier is required.',                       16, 1); RETURN; END
    IF NULLIF(@CurrencyId,  0) IS NULL  BEGIN RAISERROR('Currency is required.',                       16, 1); RETURN; END
    IF ISNULL(@DebitAmount, 0) <= 0     BEGIN RAISERROR('Debit amount must be greater than zero.',      16, 1); RETURN; END
    IF NULLIF(LTRIM(RTRIM(ISNULL(@DebitType,''))), '') IS NULL
        BEGIN RAISERROR('Debit type is required.',                                                      16, 1); RETURN; END
    IF NULLIF(LTRIM(RTRIM(ISNULL(@Reason,''))), '') IS NULL
        BEGIN RAISERROR('Reason is required.',                                                          16, 1); RETURN; END

    IF @DnId IS NULL OR @DnId <= 0
    BEGIN
        IF NULLIF(@CreatedBy, '') IS NULL BEGIN RAISERROR('CreatedBy is required.', 16, 1); RETURN; END

        DECLARE @NumResult TABLE (DocNumber NVARCHAR(50), NewSeries INT);
        INSERT INTO @NumResult EXEC proj.sp_GetNextDocNumber 'DBN';
        DECLARE @DnNo NVARCHAR(50); SELECT @DnNo = DocNumber FROM @NumResult;

        INSERT INTO proj.TBL_DEBIT_NOTE
            (DnNumber, DnDate, SupplierId, CurrencyId, ExchangeRate, DebitAmount,
             DebitType, Reason, Notes, Status, CreatedBy)
        VALUES
            (@DnNo, ISNULL(@DnDate, CAST(GETDATE() AS DATE)), @SupplierId, @CurrencyId,
             ISNULL(@ExchangeRate, 1), @DebitAmount,
             NULLIF(@DebitType,''), @Reason, @Notes, 'Draft', @CreatedBy);

        SELECT CAST(SCOPE_IDENTITY() AS INT) AS NewId, @DnNo AS DnNumber;
    END
    ELSE
    BEGIN
        IF EXISTS (SELECT 1 FROM proj.TBL_DEBIT_NOTE WHERE DnId = @DnId AND Status <> 'Draft')
            BEGIN RAISERROR('Only Draft debit notes can be edited.', 16, 1); RETURN; END

        -- AllocatedAmount is now BASE; convert @DebitAmount to base before comparing
        IF @DebitAmount * ISNULL(NULLIF(@ExchangeRate, 0), 1) <
           (SELECT ISNULL(SUM(AllocatedAmount),0) FROM proj.TBL_DEBIT_NOTE_ALLOCATION WHERE DnId = @DnId AND IsActive = 1)
            BEGIN RAISERROR('Debit amount cannot be less than the amount already allocated. Remove allocations first.', 16, 1); RETURN; END

        UPDATE proj.TBL_DEBIT_NOTE
        SET    DnDate        = ISNULL(@DnDate, DnDate),
               SupplierId    = @SupplierId,
               CurrencyId    = @CurrencyId,
               ExchangeRate  = ISNULL(@ExchangeRate, ExchangeRate),
               DebitAmount   = @DebitAmount,
               DebitType     = NULLIF(@DebitType,''),
               Reason        = @Reason,
               Notes         = @Notes,
               ModifiedBy    = @ModifiedBy,
               ModifiedDate  = GETDATE()
        WHERE  DnId = @DnId AND IsActive = 1;

        SELECT CAST(@DnId AS INT) AS NewId, DnNumber FROM proj.TBL_DEBIT_NOTE WHERE DnId = @DnId;
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_SetDelivery]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetDelivery];
GO
-- Clean version: use table variable + EXEC directly
CREATE   PROCEDURE proj.sp_SetDelivery
    @DeliveryId         INT,
    @DeliveryNo         NVARCHAR(30),
    @DeliveryDate       DATE,
    @InvoiceId          INT,
    @CustomerId         INT,
    @JobId              NVARCHAR(50),
    @DeliveryAddress    NVARCHAR(500),
    @ContactId          INT,
    @Consignee          NVARCHAR(500),
    @ConsigneeAddress   NVARCHAR(800),
    @ConsigneeLpoNo     NVARCHAR(200),
    @ConsigneeLpoDate   DATE,
    @ConsigneeTrn       NVARCHAR(200),
    @VehicleNo          NVARCHAR(200),
    @DeliveredBy        NVARCHAR(150),
    @DeliveredByDate    DATE,
    @BuyerTrnNo         NVARCHAR(200),
    @BuyerLpoNo         NVARCHAR(200),
    @BuyerLpoDate       DATE,
    @Notes              NVARCHAR(500),
    @ActionBy           NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    -- Block transactional saves on a closed job (Freezed/Completed/Cancelled).
    IF @JobId IS NOT NULL EXEC proj.sp_AssertJobOpen @JobId;


    IF @DeliveryId = 0
    BEGIN
        -- Auto-generate delivery number from document series
        DECLARE @tbl TABLE (DocNumber NVARCHAR(50), NewSeries INT);
        INSERT INTO @tbl EXEC proj.sp_GetNextDocNumber 'DN';

        DECLARE @GeneratedNo NVARCHAR(30);
        SELECT @GeneratedNo = DocNumber FROM @tbl;

        INSERT INTO proj.TBL_DELIVERY
            (DeliveryNo, DeliveryDate, InvoiceId, CustomerId, JobId, DeliveryAddress,
             ContactId, Consignee, ConsigneeAddress, ConsigneeLpoNo, ConsigneeLpoDate,
             ConsigneeTrn, VehicleNo, DeliveredBy, DeliveredByDate,
             BuyerTrnNo, BuyerLpoNo, BuyerLpoDate, Notes,
             Status, CreatedBy, CreatedDate)
        VALUES
            (@GeneratedNo, @DeliveryDate, NULLIF(@InvoiceId,0), @CustomerId, @JobId, @DeliveryAddress,
             NULLIF(@ContactId,0), @Consignee, @ConsigneeAddress, @ConsigneeLpoNo, @ConsigneeLpoDate,
             @ConsigneeTrn, @VehicleNo, @DeliveredBy, @DeliveredByDate,
             @BuyerTrnNo, @BuyerLpoNo, @BuyerLpoDate, @Notes,
             'Draft', @ActionBy, GETDATE());

        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_DELIVERY SET
            DeliveryDate      = @DeliveryDate,
            InvoiceId         = NULLIF(@InvoiceId, 0),
            CustomerId        = @CustomerId,
            JobId             = @JobId,
            DeliveryAddress   = @DeliveryAddress,
            ContactId         = NULLIF(@ContactId, 0),
            Consignee         = @Consignee,
            ConsigneeAddress  = @ConsigneeAddress,
            ConsigneeLpoNo    = @ConsigneeLpoNo,
            ConsigneeLpoDate  = @ConsigneeLpoDate,
            ConsigneeTrn      = @ConsigneeTrn,
            VehicleNo         = @VehicleNo,
            DeliveredBy       = @DeliveredBy,
            DeliveredByDate   = @DeliveredByDate,
            BuyerTrnNo        = @BuyerTrnNo,
            BuyerLpoNo        = @BuyerLpoNo,
            BuyerLpoDate      = @BuyerLpoDate,
            Notes             = @Notes,
            ModifiedBy        = @ActionBy,
            ModifiedDate      = GETDATE()
        WHERE DeliveryId = @DeliveryId
          AND Status IN ('Draft', 'Approved')
          AND IsActive = 1;

        SELECT CAST(@DeliveryId AS NVARCHAR(20));
    END
END
GO

