CREATE   PROCEDURE proj.sp_SetDeliveryLine
    @DeliveryLineId  INT,
    @DeliveryId      INT,
    @InvoiceLineId   INT,
    @LineNum         INT,
    @Description     NVARCHAR(500),
    @UomName         NVARCHAR(50),
    @Qty             DECIMAL(18,4),
    @Remarks         NVARCHAR(300),
    @ActionBy        NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    IF @DeliveryLineId = 0
    BEGIN
        INSERT INTO proj.TBL_DELIVERY_LINE
            (DeliveryId, InvoiceLineId, LineNum, Description, UomName, Qty, Remarks, CreatedBy, CreatedDate)
        VALUES
            (@DeliveryId, NULLIF(@InvoiceLineId,0), @LineNum, @Description, @UomName, @Qty, @Remarks, @ActionBy, GETDATE());
        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_DELIVERY_LINE SET
            Description   = @Description,
            UomName       = @UomName,
            Qty           = @Qty,
            Remarks       = @Remarks,
            ModifiedBy    = @ActionBy,
            ModifiedDate  = GETDATE()
        WHERE DeliveryLineId = @DeliveryLineId AND IsActive = 1;
        SELECT CAST(@DeliveryLineId AS NVARCHAR(20));
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_SetDnAllocation]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetDnAllocation];
GO

CREATE PROCEDURE proj.sp_SetDnAllocation
    @AllocationId      INT           = 0,
    @DnId              INT,
    @SupplierInvoiceId INT,
    @AllocatedAmount   DECIMAL(18,4),   -- received from frontend in invoice currency
    @CreatedBy         NVARCHAR(100) = NULL,
    @ModifiedBy        NVARCHAR(100) = NULL,
    @Reason            NVARCHAR(500) = NULL,
    @PasswordHash      NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @DnStatus     NVARCHAR(20),
            @DnSupplier   INT,
            @DebitAmount  DECIMAL(18,4),
            @ExchangeRate DECIMAL(18,6);

    SELECT @DnStatus     = Status,
           @DnSupplier   = SupplierId,
           @DebitAmount  = DebitAmount,
           @ExchangeRate = ISNULL(NULLIF(ExchangeRate, 0), 1)
    FROM   proj.TBL_DEBIT_NOTE
    WHERE  DnId = @DnId AND IsActive = 1;

    IF @DnStatus IS NULL
        BEGIN RAISERROR('Debit note not found.', 16, 1); RETURN; END
    IF @DnStatus <> 'Approved'
        BEGIN RAISERROR('The debit note must be Approved before registering it against invoices.', 16, 1); RETURN; END
    IF ISNULL(@AllocatedAmount, 0) <= 0
        BEGIN RAISERROR('Allocated amount must be greater than zero.', 16, 1); RETURN; END

    IF NULLIF(LTRIM(RTRIM(ISNULL(@Reason, ''))), '') IS NULL
        BEGIN RAISERROR('A reason is required to modify an allocation on an approved debit note.', 16, 1); RETURN; END
    IF NULLIF(@PasswordHash, '') IS NULL
        BEGIN RAISERROR('Password is required.', 16, 1); RETURN; END

    DECLARE @ActionBy NVARCHAR(100) = ISNULL(@ModifiedBy, @CreatedBy);
    IF NOT EXISTS (
        SELECT 1
        FROM   proj.TBL_USER_ROLES  ur
        JOIN   proj.TBL_ROLE_SECRET rs ON rs.RoleId  = ur.RoleId
        JOIN   proj.TBL_USERS       u  ON u.UserId   = ur.UserId
        WHERE  u.Username         = @ActionBy
          AND  rs.SecretKey       = 'PV_REVISE'
          AND  rs.SecretValueHash = @PasswordHash
    )
        BEGIN RAISERROR('Incorrect password. You do not have permission to modify allocations on this debit note.', 16, 1); RETURN; END

    DECLARE @InvSupplier     INT,
            @InvStatus       NVARCHAR(30),
            @InvTotal        DECIMAL(18,4),
            @InvExchangeRate DECIMAL(18,6);

    SELECT @InvSupplier     = SupplierId,
           @InvStatus       = Status,
           @InvTotal        = TotalAmount,
           @InvExchangeRate = ISNULL(NULLIF(ExchangeRate, 0), 1)
    FROM   proj.TBL_SUPPLIER_INVOICE
    WHERE  SupplierInvoiceId = @SupplierInvoiceId AND IsActive = 1;

    IF @InvSupplier IS NULL
        BEGIN RAISERROR('Supplier invoice not found.', 16, 1); RETURN; END
    IF @InvSupplier <> @DnSupplier
        BEGIN RAISERROR('Invoice belongs to a different supplier.', 16, 1); RETURN; END
    IF @InvStatus <> 'Approved'
        BEGIN RAISERROR('Only Approved supplier invoices can have debit applied.', 16, 1); RETURN; END

    -- Convert incoming invoice-currency amount to base for storage
    DECLARE @AllocatedAmountBase DECIMAL(18,4) = @AllocatedAmount * @InvExchangeRate;

    -- Outstanding in base: invoice total base minus approved PV allocations (base) minus other DN allocations (base)
    DECLARE @PvPaid DECIMAL(18,4);
    SELECT @PvPaid = ISNULL(SUM(a.AllocatedAmount), 0)
    FROM   proj.TBL_PAYMENT_VOUCHER_ALLOCATION a
    JOIN   proj.TBL_PAYMENT_VOUCHER pv ON pv.PvId = a.PvId
    WHERE  a.SupplierInvoiceId = @SupplierInvoiceId AND a.IsActive = 1
      AND  pv.Status = 'Approved' AND pv.IsActive = 1;

    DECLARE @DnPaidByOthers DECIMAL(18,4);
    SELECT @DnPaidByOthers = ISNULL(SUM(a.AllocatedAmount), 0)
    FROM   proj.TBL_DEBIT_NOTE_ALLOCATION a
    JOIN   proj.TBL_DEBIT_NOTE dn ON dn.DnId = a.DnId
    WHERE  a.SupplierInvoiceId = @SupplierInvoiceId AND a.IsActive = 1
      AND  dn.Status = 'Approved' AND dn.IsActive = 1 AND dn.DnId <> @DnId;

    DECLARE @Outstanding DECIMAL(18,4) = @InvTotal * @InvExchangeRate - @PvPaid - @DnPaidByOthers;
    IF @AllocatedAmountBase > @Outstanding
    BEGIN
        DECLARE @m1 NVARCHAR(400) =
            'Allocation (' + CAST(@AllocatedAmount AS NVARCHAR(30)) +
            ') exceeds the invoice outstanding balance (' +
            CAST(ROUND(@Outstanding / @InvExchangeRate, 2) AS NVARCHAR(30)) + ').';
        RAISERROR(@m1, 16, 1); RETURN;
    END

    -- DN balance: all base allocations on this DN must not exceed DebitAmount × DN rate
    DECLARE @OtherAlloc DECIMAL(18,4);
    SELECT @OtherAlloc = ISNULL(SUM(AllocatedAmount), 0)
    FROM   proj.TBL_DEBIT_NOTE_ALLOCATION
    WHERE  DnId = @DnId AND IsActive = 1 AND SupplierInvoiceId <> @SupplierInvoiceId;

    DECLARE @DnAvailable DECIMAL(18,4) = @DebitAmount * @ExchangeRate;
    IF (@OtherAlloc + @AllocatedAmountBase) > @DnAvailable
    BEGIN
        DECLARE @m2 NVARCHAR(400) =
            'Total allocations (' +
            CAST(ROUND((@OtherAlloc + @AllocatedAmountBase) / @ExchangeRate, 2) AS NVARCHAR(30)) +
            ') would exceed the DN available balance (' +
            CAST(@DebitAmount AS NVARCHAR(30)) + ').';
        RAISERROR(@m2, 16, 1); RETURN;
    END

    DECLARE @ExistingId INT;
    SELECT @ExistingId = AllocationId
    FROM   proj.TBL_DEBIT_NOTE_ALLOCATION
    WHERE  DnId = @DnId AND SupplierInvoiceId = @SupplierInvoiceId AND IsActive = 1;

    IF @ExistingId IS NOT NULL
        UPDATE proj.TBL_DEBIT_NOTE_ALLOCATION
        SET    AllocatedAmount = @AllocatedAmountBase,
               Reason         = @Reason,
               ModifiedBy     = @ActionBy,
               ModifiedDate   = GETDATE()
        WHERE  AllocationId = @ExistingId;
    ELSE
        INSERT INTO proj.TBL_DEBIT_NOTE_ALLOCATION
            (DnId, SupplierInvoiceId, AllocatedAmount, Reason, CreatedBy)
        VALUES (@DnId, @SupplierInvoiceId, @AllocatedAmountBase, @Reason, @CreatedBy);

    -- Refresh DN header: sum of base allocations ÷ DN rate = allocated in DN's own currency
    UPDATE proj.TBL_DEBIT_NOTE
    SET    AllocatedAmount = (
               SELECT ISNULL(SUM(AllocatedAmount), 0) / @ExchangeRate
               FROM   proj.TBL_DEBIT_NOTE_ALLOCATION
               WHERE  DnId = @DnId AND IsActive = 1
           ),
           ModifiedDate = GETDATE()
    WHERE  DnId = @DnId;

    SELECT @DnId AS DnId;
END
GO

IF OBJECT_ID(N'[proj].[sp_SetDocSeries]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetDocSeries];
GO

-- ── sp_SetDocSeries ───────────────────────────────────────────────────────────
CREATE   PROCEDURE proj.sp_SetDocSeries
    @DocTypeId      NVARCHAR(20),
    @DocTypeName    NVARCHAR(100),
    @Prefix         NVARCHAR(20),
    @Suffix         NVARCHAR(20)  = NULL,
    @Separator      NCHAR(1)      = '-',
    @IncludeYear    BIT           = 1,
    @YearDigits     TINYINT       = 4,
    @ResetYearly    BIT           = 1,
    @PadLength      TINYINT       = 4,
    @StartingSeries INT           = 1,
    @SortOrder      INT           = 0,
    @IsActive       BIT           = 1,
    @SavedBy        NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (SELECT 1 FROM proj.TBL_DOCUMENT_SERIES WHERE DocTypeId = @DocTypeId)
    BEGIN
        UPDATE proj.TBL_DOCUMENT_SERIES SET
            DocTypeName    = @DocTypeName,
            Prefix         = @Prefix,
            Suffix         = @Suffix,
            Separator      = ISNULL(@Separator, '-'),
            IncludeYear    = @IncludeYear,
            YearDigits     = @YearDigits,
            ResetYearly    = @ResetYearly,
            PadLength      = @PadLength,
            StartingSeries = @StartingSeries,
            SortOrder      = @SortOrder,
            IsActive       = @IsActive,
            ModifiedBy     = @SavedBy,
            ModifiedDate   = GETDATE()
        WHERE DocTypeId = @DocTypeId;
    END
    ELSE
    BEGIN
        INSERT INTO proj.TBL_DOCUMENT_SERIES
            (DocTypeId, DocTypeName, Prefix, Suffix, Separator, IncludeYear, YearDigits,
             ResetYearly, PadLength, StartingSeries, CurrentSeries, SortOrder, IsActive,
             CreatedBy, CreatedDate)
        VALUES
            (@DocTypeId, @DocTypeName, @Prefix, @Suffix, ISNULL(@Separator,'-'),
             @IncludeYear, @YearDigits, @ResetYearly, @PadLength, @StartingSeries,
             0, @SortOrder, @IsActive, @SavedBy, GETDATE());
    END

    SELECT @DocTypeId AS DocTypeId;
END;
GO

