CREATE PROCEDURE proj.sp_SetDocumentStatus
    @StatusId           INT           = 0,
    @ModuleName         NVARCHAR(30),
    @StatusCode         NVARCHAR(30),
    @StatusLabel        NVARCHAR(100),
    @BadgeBg            NVARCHAR(20)  = '#f1f5f9',
    @BadgeColor         NVARCHAR(20)  = '#475569',
    @BadgeDot           NVARCHAR(20)  = '#94a3b8',
    @SortOrder          INT           = 0,
    @CanEdit            BIT           = 0,
    @CanDelete          BIT           = 0,
    @CanUploadDocs      BIT           = 0,
    @IsInitial          BIT           = 0,
    @IsTerminal         BIT           = 0,
    @AllowedTransitions NVARCHAR(300) = NULL,
    @IsActive           BIT           = 1,
    @SavedBy            NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @StatusId = 0 OR @StatusId IS NULL
    BEGIN
        INSERT INTO proj.TBL_DOCUMENT_STATUS
            (ModuleName, StatusCode, StatusLabel, BadgeBg, BadgeColor, BadgeDot, SortOrder,
             CanEdit, CanDelete, CanUploadDocs, IsInitial, IsTerminal, AllowedTransitions,
             IsActive, CreatedBy, CreatedDate)
        VALUES
            (@ModuleName, @StatusCode, @StatusLabel, @BadgeBg, @BadgeColor, @BadgeDot, @SortOrder,
             @CanEdit, @CanDelete, @CanUploadDocs, @IsInitial, @IsTerminal, @AllowedTransitions,
             @IsActive, @SavedBy, GETDATE());
        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_DOCUMENT_STATUS SET
            ModuleName         = @ModuleName,
            StatusCode         = @StatusCode,
            StatusLabel        = @StatusLabel,
            BadgeBg            = @BadgeBg,
            BadgeColor         = @BadgeColor,
            BadgeDot           = @BadgeDot,
            SortOrder          = @SortOrder,
            CanEdit            = @CanEdit,
            CanDelete          = @CanDelete,
            CanUploadDocs      = @CanUploadDocs,
            IsInitial          = @IsInitial,
            IsTerminal         = @IsTerminal,
            AllowedTransitions = @AllowedTransitions,
            IsActive           = @IsActive,
            ModifiedBy         = @SavedBy,
            ModifiedDate       = GETDATE()
        WHERE StatusId = @StatusId;
        SELECT CAST(@StatusId AS NVARCHAR(20));
    END
END;
GO

