CREATE PROCEDURE proj.sp_SetGRN
    @GrnId            INT            = 0,
    @PoId             INT            = NULL,
    @SupplierId       INT            = NULL,
    @JobId            NVARCHAR(50)   = NULL,
    @GrnDate          DATE           = NULL,
    @ReceivedDate     DATE           = NULL,
    @DoNo             NVARCHAR(100)  = NULL,
    @ReceivedBy       NVARCHAR(100)  = NULL,
    @ReceivedFrom     NVARCHAR(200)  = NULL,
    @ShipmentBy       NVARCHAR(100)  = NULL,
    @DeliveryTerms    NVARCHAR(100)  = NULL,
    @DeliveryLocation NVARCHAR(200)  = NULL,
    @ShipmentDetails  NVARCHAR(300)  = NULL,
    @InvoiceNo        NVARCHAR(100)  = NULL,
    @InvoiceDate      DATE           = NULL,
    @CurrencyId       INT            = NULL,
    @ExchangeRate     DECIMAL(18,6)  = 1,
    @TotalAmount      DECIMAL(18,4)  = NULL,
    @BoeNo            NVARCHAR(100)  = NULL,
    @BoeDate          DATE           = NULL,
    @IsRegistered     BIT            = 0,
    @RegisteredBy     NVARCHAR(100)  = NULL,
    @RegisteredDate   DATETIME       = NULL,
    @Remarks          NVARCHAR(500)  = NULL,
    @CreatedBy        NVARCHAR(100)  = NULL,
    @ModifiedBy       NVARCHAR(100)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @JobId IS NOT NULL EXEC proj.sp_AssertJobOpen @JobId;
    IF @JobId IS NOT NULL EXEC proj.sp_AssertBudgetApproved @JobId, N'GRN';

    IF @GrnId = 0 OR @GrnId IS NULL
    BEGIN
        IF NULLIF(@CreatedBy, '') IS NULL RAISERROR('CreatedBy is required.',              16, 1);
        IF NULLIF(@PoId, 0)       IS NULL RAISERROR('Purchase Order is required for GRN.', 16, 1);
        IF NULLIF(@JobId, '')     IS NULL RAISERROR('Job is required.',                    16, 1);
        IF @@ERROR <> 0 RETURN;

        -- ── PO status guard (INSERT only) ──────────────────────────────────
        IF NULLIF(@PoId, 0) IS NOT NULL
        BEGIN
            DECLARE @PoStatus NVARCHAR(30);
            SELECT @PoStatus = Status FROM proj.TBL_PURCHASE_ORDER WHERE PoId = @PoId AND IsActive = 1;

            IF @PoStatus = 'Hold'
                RAISERROR('Cannot create a GRN — Purchase Order is currently on hold. Release the hold first.', 16, 1);

            IF @PoStatus = 'Closed'
                RAISERROR('Cannot create a GRN — Purchase Order is closed.', 16, 1);

            IF @PoStatus = 'Cancelled'
                RAISERROR('Cannot create a GRN — Purchase Order is cancelled.', 16, 1);
        END

        DECLARE @IsClosed BIT = 0, @StatusName NVARCHAR(50) = '';
        SELECT @IsClosed = js.IsClosed, @StatusName = js.StatusName
        FROM   proj.TBL_JOB j
        JOIN   proj.TBL_JOB_STATUS js ON js.JobStatusId = j.JobStatusId
        WHERE  j.JobId = @JobId;
        IF @IsClosed = 1
        BEGIN
            DECLARE @ErrMsg NVARCHAR(200) = 'Job ' + @JobId + ' is ' + @StatusName + '. Revise the job to create new transactions.';
            RAISERROR('%s', 16, 1, @ErrMsg);
            RETURN;
        END

        DECLARE @NumResult TABLE (DocNumber NVARCHAR(50), NewSeries INT);
        INSERT INTO @NumResult EXEC proj.sp_GetNextDocNumber 'GRN';
        DECLARE @GrnNumber NVARCHAR(50);
        SELECT @GrnNumber = DocNumber FROM @NumResult;

        INSERT INTO proj.TBL_GRN_HEADER (
            GrnNumber, PoId, SupplierId, JobId,
            GrnDate, ReceivedDate,
            DoNo, ReceivedBy, ReceivedFrom,
            ShipmentBy, DeliveryTerms, DeliveryLocation, ShipmentDetails,
            InvoiceNo, InvoiceDate, CurrencyId, ExchangeRate, TotalAmount,
            BoeNo, BoeDate,
            IsRegistered, RegisteredBy, RegisteredDate,
            Status, Remarks, CreatedBy, CreatedDate
        ) VALUES (
            @GrnNumber, @PoId, NULLIF(@SupplierId,0), @JobId,
            ISNULL(@GrnDate, CAST(GETDATE() AS DATE)), @ReceivedDate,
            @DoNo, @ReceivedBy, @ReceivedFrom,
            @ShipmentBy, @DeliveryTerms, @DeliveryLocation, @ShipmentDetails,
            @InvoiceNo, @InvoiceDate, NULLIF(@CurrencyId,0), ISNULL(@ExchangeRate,1), @TotalAmount,
            @BoeNo, @BoeDate,
            ISNULL(@IsRegistered,0), @RegisteredBy, @RegisteredDate,
            N'Draft', @Remarks, @CreatedBy, GETDATE()
        );

        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_GRN_HEADER SET
            PoId             = NULLIF(@PoId,0),
            SupplierId       = NULLIF(@SupplierId,0),
            JobId            = NULLIF(@JobId,''),
            GrnDate          = ISNULL(@GrnDate,          GrnDate),
            ReceivedDate     = @ReceivedDate,
            DoNo             = @DoNo,
            ReceivedBy       = @ReceivedBy,
            ReceivedFrom     = @ReceivedFrom,
            ShipmentBy       = @ShipmentBy,
            DeliveryTerms    = @DeliveryTerms,
            DeliveryLocation = @DeliveryLocation,
            ShipmentDetails  = @ShipmentDetails,
            InvoiceNo        = @InvoiceNo,
            InvoiceDate      = @InvoiceDate,
            CurrencyId       = NULLIF(@CurrencyId,0),
            ExchangeRate     = ISNULL(@ExchangeRate,     ExchangeRate),
            TotalAmount      = @TotalAmount,
            BoeNo            = @BoeNo,
            BoeDate          = @BoeDate,
            IsRegistered     = ISNULL(@IsRegistered,     IsRegistered),
            RegisteredBy     = ISNULL(@RegisteredBy,     RegisteredBy),
            RegisteredDate   = ISNULL(@RegisteredDate,   RegisteredDate),
            Remarks          = @Remarks,
            ModifiedBy       = @ModifiedBy,
            ModifiedDate     = GETDATE()
        WHERE GrnId = @GrnId AND IsActive = 1;

        SELECT CAST(@GrnId AS NVARCHAR(20));
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetGRNLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetGRNLine];
GO

CREATE PROCEDURE proj.sp_SetGRNLine
    @GrnDetailId     INT            = 0,
    @GrnId           INT,
    @PoLineId        INT            = NULL,
    @PrLineId        INT            = NULL,
    @ItemId          INT            = NULL,
    @ItemCode        NVARCHAR(50)   = NULL,
    @ItemDesc        NVARCHAR(300)  = NULL,
    @OrderedQty      DECIMAL(18,4)  = 0,
    @ReceivedQty     DECIMAL(18,4)  = 0,
    @RejectedQty     DECIMAL(18,4)  = 0,
    @UomId           INT            = NULL,
    @UomName         NVARCHAR(50)   = NULL,
    @UnitPrice       DECIMAL(18,4)  = 0,
    @TaxPct          DECIMAL(5,2)   = 0,
    @BatchNo         NVARCHAR(100)  = NULL,
    @SerialNo        NVARCHAR(100)  = NULL,
    @ExpiryDate      DATE           = NULL,
    @StorageLocation NVARCHAR(100)  = NULL,
    @BinLocation     NVARCHAR(50)   = NULL,
    @QcStatus        NVARCHAR(30)   = NULL,
    @QcRemarks       NVARCHAR(300)  = NULL,
    @Remarks         NVARCHAR(300)  = NULL,
    @CreatedBy       NVARCHAR(100)  = NULL,
    @ModifiedBy      NVARCHAR(100)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @ParentJobId NVARCHAR(50) = (SELECT JobId FROM proj.TBL_GRN_HEADER WHERE GrnId = @GrnId);
    IF @ParentJobId IS NOT NULL EXEC proj.sp_AssertJobOpen @ParentJobId;
    IF @ParentJobId IS NOT NULL EXEC proj.sp_AssertBudgetApproved @ParentJobId, N'GRN';

    IF NULLIF(@GrnId, 0) IS NULL RAISERROR('GrnId is required.', 16, 1);
    IF @@ERROR <> 0 RETURN;

    DECLARE @GrnStatus NVARCHAR(30);
    SELECT @GrnStatus = Status FROM proj.TBL_GRN_HEADER WHERE GrnId = @GrnId AND IsActive = 1;
    IF @GrnStatus IS NULL BEGIN RAISERROR('GRN not found or is inactive.', 16, 1); RETURN; END
    IF @GrnStatus <> 'Draft'
    BEGIN
        DECLARE @GsMsg NVARCHAR(200) = 'GRN lines can only be added or edited when the GRN is in Draft status. Current status: ' + @GrnStatus;
        RAISERROR(@GsMsg, 16, 1); RETURN;
    END

    IF @GrnDetailId IS NULL OR @GrnDetailId <= 0
    BEGIN
        IF NULLIF(@CreatedBy, '') IS NULL RAISERROR('CreatedBy is required.', 16, 1);
        IF @@ERROR <> 0 RETURN;
    END

    -- ── PO status guard (INSERT only) ────────────────────────────────────
    IF (@GrnDetailId IS NULL OR @GrnDetailId <= 0) AND NULLIF(@PoLineId, 0) IS NOT NULL
    BEGIN
        DECLARE @LinePoStatus NVARCHAR(30);
        SELECT @LinePoStatus = po.Status
        FROM proj.TBL_PURCHASE_ORDER_LINE pol
        JOIN proj.TBL_PURCHASE_ORDER      po ON po.PoId = pol.PoId
        WHERE pol.PoLineId = @PoLineId AND po.IsActive = 1;

        IF @LinePoStatus = 'Hold'
            RAISERROR('Cannot add a GRN line — the linked Purchase Order is currently on hold. Release the hold first.', 16, 1);

        IF @LinePoStatus = 'Closed'
            RAISERROR('Cannot add a GRN line — the linked Purchase Order is closed.', 16, 1);

        IF @LinePoStatus = 'Cancelled'
            RAISERROR('Cannot add a GRN line — the linked Purchase Order is cancelled.', 16, 1);
    END

    IF NULLIF(@PoLineId, 0) IS NOT NULL
    BEGIN
        DECLARE @PoOrderedQty    DECIMAL(18,4);
        DECLARE @AlreadyReceived DECIMAL(18,4);

        SELECT @PoOrderedQty = OrderedQty
        FROM   proj.TBL_PURCHASE_ORDER_LINE WHERE PoLineId = @PoLineId;

        SELECT @AlreadyReceived = ISNULL(SUM(d.ReceivedQty), 0)
        FROM   proj.TBL_GRN_DETAIL d
        JOIN   proj.TBL_GRN_HEADER h ON h.GrnId = d.GrnId AND h.IsActive = 1
        WHERE  d.PoLineId    = @PoLineId
          AND  d.IsActive    = 1
          AND  h.Status      <> 'Cancelled'
          AND  d.GrnDetailId <> ISNULL(NULLIF(@GrnDetailId, 0), -1);

        IF @ReceivedQty > (@PoOrderedQty - @AlreadyReceived)
        BEGIN
            DECLARE @MaxAllowed NVARCHAR(30) = CAST((@PoOrderedQty - @AlreadyReceived) AS NVARCHAR(30));
            RAISERROR(N'Received qty exceeds the remaining ordered qty for this PO line. Maximum allowed: %s', 16, 1, @MaxAllowed);
            RETURN;
        END
    END

    IF @GrnDetailId IS NULL OR @GrnDetailId <= 0
    BEGIN
        DECLARE @LineNum INT;
        SELECT @LineNum = ISNULL(MAX(LineNum), 0) + 1
        FROM   proj.TBL_GRN_DETAIL WHERE GrnId = @GrnId AND IsActive = 1;

        INSERT INTO proj.TBL_GRN_DETAIL (
            GrnId, LineNum, PoLineId, PrLineId, ItemId, ItemCode, ItemDesc,
            OrderedQty, ReceivedQty, RejectedQty, UomId, UomName,
            UnitPrice, TaxPct,
            BatchNo, SerialNo, ExpiryDate,
            StorageLocation, BinLocation,
            QcStatus, QcRemarks, Remarks, CreatedBy
        ) VALUES (
            @GrnId, @LineNum, NULLIF(@PoLineId,0), NULLIF(@PrLineId,0),
            NULLIF(@ItemId,0), @ItemCode, @ItemDesc,
            ISNULL(@OrderedQty,0), ISNULL(@ReceivedQty,0), ISNULL(@RejectedQty,0),
            NULLIF(@UomId,0), @UomName,
            ISNULL(@UnitPrice,0), ISNULL(@TaxPct,0),
            @BatchNo, @SerialNo, @ExpiryDate,
            @StorageLocation, @BinLocation,
            @QcStatus, @QcRemarks, @Remarks, @CreatedBy
        );

        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_GRN_DETAIL SET
            OrderedQty      = ISNULL(@OrderedQty,      OrderedQty),
            ReceivedQty     = ISNULL(@ReceivedQty,     ReceivedQty),
            RejectedQty     = ISNULL(@RejectedQty,     RejectedQty),
            UomId           = NULLIF(@UomId, 0),
            UomName         = @UomName,
            UnitPrice       = ISNULL(@UnitPrice,       UnitPrice),
            TaxPct          = ISNULL(@TaxPct,          TaxPct),
            BatchNo         = @BatchNo,
            SerialNo        = @SerialNo,
            ExpiryDate      = @ExpiryDate,
            StorageLocation = @StorageLocation,
            BinLocation     = @BinLocation,
            QcStatus        = @QcStatus,
            QcRemarks       = @QcRemarks,
            Remarks         = @Remarks,
            ModifiedBy      = @ModifiedBy,
            ModifiedDate    = GETDATE()
        WHERE GrnDetailId = @GrnDetailId;

        SELECT CAST(@GrnDetailId AS NVARCHAR(20));
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetInvoice]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetInvoice];
GO
CREATE   PROCEDURE PROJ.sp_SetInvoice
    @InvoiceId      INT             = 0,
    @InvoiceDate    DATE            = NULL,
    @CustomerId     INT,
    @BillingAddress NVARCHAR(1000)  = NULL,
    @CurrencyId     INT             = 2,        -- default AED
    @ExchangeRate   DECIMAL(18,6)   = NULL,      -- NULL = auto-resolve from currency master
    @DueDate        DATE            = NULL,
    @JobId          VARCHAR(30)     = NULL,
    @LpoNo          NVARCHAR(50)    = NULL,
    @LpoDate        DATE            = NULL,
    @ContactId      INT             = NULL,
    @Notes          NVARCHAR(1000)  = NULL,
    @CreatedBy      NVARCHAR(100)   = NULL,
    @ModifiedBy     NVARCHAR(100)   = NULL
AS
BEGIN
    SET NOCOUNT ON;
    -- Block transactional saves on a closed job (Freezed/Completed/Cancelled).
    IF @JobId IS NOT NULL EXEC proj.sp_AssertJobOpen @JobId;
    -- Block transactional saves on a job whose budget is not yet approved.
    IF @JobId IS NOT NULL EXEC proj.sp_AssertBudgetApproved @JobId, N'INVOICE';



    -- ── Mandatory: every invoice must be linked to a job ──────────────────
    IF NULLIF(@JobId, '') IS NULL
    BEGIN
        RAISERROR('Job is required for an invoice.', 16, 1); RETURN;
        RETURN;
    END
    IF NOT EXISTS (SELECT 1 FROM PROJ.TBL_JOB WHERE JobId = @JobId)
    BEGIN
        RAISERROR('The specified Job does not exist.', 16, 1); RETURN;
        RETURN;
    END

    -- Resolve exchange rate: base currency is always 1;
    -- if caller didn't supply a rate, pull from the master.
    DECLARE @ResolvedRate DECIMAL(18,6);
    SELECT @ResolvedRate =
        CASE WHEN IsBaseCurrency = 1 THEN 1.000000
             ELSE ISNULL(@ExchangeRate, ExchangeRate)
        END
    FROM   PROJ.TBL_CURRENCY
    WHERE  CurrencyId = @CurrencyId;

    IF @ResolvedRate IS NULL
        SET @ResolvedRate = 1.000000;   -- safety fallback

    IF @InvoiceId IS NULL OR @InvoiceId <= 0
    BEGIN
        DECLARE @NumResult TABLE (DocNumber NVARCHAR(50), NewSeries INT);
        INSERT INTO @NumResult EXEC PROJ.sp_GetNextDocNumber 'INV';
        DECLARE @InvoiceNo NVARCHAR(30);
        SELECT @InvoiceNo = DocNumber FROM @NumResult;

        INSERT INTO PROJ.TBL_INVOICE
            (InvoiceNo, InvoiceDate, CustomerId, BillingAddress, CurrencyId, ExchangeRate,
             DueDate, JobId, LpoNo, LpoDate, ContactId, Notes, CreatedBy)
        VALUES
            (@InvoiceNo, ISNULL(@InvoiceDate, CAST(GETDATE() AS DATE)),
             @CustomerId, @BillingAddress, @CurrencyId, @ResolvedRate,
             @DueDate, @JobId, @LpoNo, @LpoDate,
             NULLIF(@ContactId,0), @Notes, @CreatedBy);

        SELECT CAST(SCOPE_IDENTITY() AS INT) AS NewId, @InvoiceNo AS InvoiceNo;
    END
    ELSE
    BEGIN
        IF EXISTS (SELECT 1 FROM PROJ.TBL_INVOICE WHERE InvoiceId = @InvoiceId AND Status <> 'Draft') BEGIN RAISERROR('Cannot edit a non-Draft Invoice.', 16, 1); RETURN; END

        UPDATE PROJ.TBL_INVOICE
        SET InvoiceDate    = ISNULL(@InvoiceDate, InvoiceDate),
            CustomerId     = @CustomerId,
            BillingAddress = @BillingAddress,
            CurrencyId     = @CurrencyId,
            ExchangeRate   = @ResolvedRate,
            DueDate        = @DueDate,
            JobId          = @JobId,
            LpoNo          = @LpoNo,
            LpoDate        = @LpoDate,
            ContactId      = NULLIF(@ContactId, 0),
            Notes          = @Notes,
            ModifiedBy     = @ModifiedBy,
            ModifiedDate   = GETDATE()
        WHERE InvoiceId = @InvoiceId AND IsActive = 1;

        SELECT CAST(@InvoiceId AS INT) AS NewId, InvoiceNo
        FROM PROJ.TBL_INVOICE WHERE InvoiceId = @InvoiceId;
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetInvoiceLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetInvoiceLine];
GO
CREATE   PROCEDURE PROJ.sp_SetInvoiceLine
    @InvoiceLineId  INT             = 0,
    @InvoiceId      INT,
    @LineNum        INT             = 0,
    @Description    NVARCHAR(500),
    @UomName        NVARCHAR(30)    = NULL,
    @UnitPrice      DECIMAL(18,4)   = 0,
    @Qty            DECIMAL(18,4)   = 1,
    @VatPercent     DECIMAL(5,2)    = 0,
    @Notes          NVARCHAR(500)   = NULL,
    @CreatedBy      NVARCHAR(100)   = NULL,
    @ModifiedBy     NVARCHAR(100)   = NULL
AS
BEGIN
    SET NOCOUNT ON;
    -- Parent-lookup: same guards as the corresponding header SP.
    DECLARE @ParentJobId NVARCHAR(50) = (SELECT JobId FROM proj.TBL_INVOICE WHERE InvoiceId = @InvoiceId);
    IF @ParentJobId IS NOT NULL EXEC proj.sp_AssertJobOpen @ParentJobId;
    IF @ParentJobId IS NOT NULL EXEC proj.sp_AssertBudgetApproved @ParentJobId, N'INVOICE';

    IF EXISTS (SELECT 1 FROM PROJ.TBL_INVOICE WHERE InvoiceId = @InvoiceId AND Status <> 'Draft') BEGIN RAISERROR('Cannot edit lines of a non-Draft Invoice.', 16, 1); RETURN; END

    DECLARE @Amount    DECIMAL(18,2) = CAST(@UnitPrice * @Qty AS DECIMAL(18,2));
    DECLARE @TaxAmount DECIMAL(18,2) = CAST(@Amount * @VatPercent / 100 AS DECIMAL(18,2));

    IF @InvoiceLineId = 0 OR @InvoiceLineId IS NULL
    BEGIN
        IF @LineNum = 0
            SELECT @LineNum = ISNULL(MAX(LineNum), 0) + 1
            FROM PROJ.TBL_INVOICE_LINE WHERE InvoiceId = @InvoiceId AND IsActive = 1;

        INSERT INTO PROJ.TBL_INVOICE_LINE
            (InvoiceId, LineNum, Description, UomName, UnitPrice, Qty, Amount, VatPercent, TaxAmount, Notes, CreatedBy)
        VALUES
            (@InvoiceId, @LineNum, @Description, NULLIF(@UomName,''),
             @UnitPrice, @Qty, @Amount, @VatPercent, @TaxAmount, @Notes, @CreatedBy);

        SELECT CAST(SCOPE_IDENTITY() AS INT) AS InvoiceLineId;
    END
    ELSE
    BEGIN
        UPDATE PROJ.TBL_INVOICE_LINE
        SET Description  = @Description,
            UomName      = NULLIF(@UomName,''),
            UnitPrice    = @UnitPrice,
            Qty          = @Qty,
            Amount       = @Amount,
            VatPercent   = @VatPercent,
            TaxAmount    = @TaxAmount,
            Notes        = @Notes,
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE InvoiceLineId = @InvoiceLineId AND IsActive = 1;
        SELECT @InvoiceLineId AS InvoiceLineId;
    END

    DECLARE @Sub DECIMAL(18,2) = (SELECT ISNULL(SUM(Amount),    0) FROM PROJ.TBL_INVOICE_LINE WHERE InvoiceId = @InvoiceId AND IsActive = 1);
    DECLARE @Tax DECIMAL(18,2) = (SELECT ISNULL(SUM(TaxAmount), 0) FROM PROJ.TBL_INVOICE_LINE WHERE InvoiceId = @InvoiceId AND IsActive = 1);
    UPDATE PROJ.TBL_INVOICE
    SET SubTotal = @Sub, TaxAmount = @Tax, TotalAmount = @Sub + @Tax,
        ModifiedBy = @ModifiedBy, ModifiedDate = GETDATE()
    WHERE InvoiceId = @InvoiceId;
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetIssueReturn]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetIssueReturn];
GO
CREATE   PROCEDURE proj.sp_SetIssueReturn
    @ReturnId   INT,
    @IssueId    INT,
    @ReturnDate DATE,
    @ReturnedBy NVARCHAR(200)  = NULL,
    @Notes      NVARCHAR(1000) = NULL,
    @CreatedBy  NVARCHAR(100),
    @ModifiedBy NVARCHAR(100)  = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- Verify the referenced issue exists and is Confirmed
    IF NOT EXISTS (
        SELECT 1 FROM proj.TBL_STOCK_ISSUE
        WHERE IssueId = @IssueId AND Status = 'Confirmed' AND IsActive = 1
    ) BEGIN RAISERROR('The referenced Issue Note must be Confirmed before creating a return.', 16, 1); RETURN; END

    IF @ReturnId = 0
    BEGIN
        -- Get document number using the correct INSERT…EXEC pattern
        DECLARE @NumResult TABLE (DocNumber NVARCHAR(50), NewSeries INT);
        INSERT INTO @NumResult EXEC proj.sp_GetNextDocNumber 'IRN';

        DECLARE @ReturnNo NVARCHAR(50);
        SELECT @ReturnNo = DocNumber FROM @NumResult;

        IF @ReturnNo IS NULL BEGIN RAISERROR('Failed to generate IRN document number. Check the IRN document series.', 16, 1); RETURN; END

        INSERT INTO proj.TBL_STOCK_ISSUE_RETURN
            (ReturnNo, ReturnDate, IssueId, ReturnedBy, Notes, Status, CreatedBy)
        VALUES
            (@ReturnNo, @ReturnDate, @IssueId, @ReturnedBy, @Notes, 'Draft', @CreatedBy);

        SELECT SCOPE_IDENTITY() AS ReturnId, @ReturnNo AS ReturnNo;
    END
    ELSE
    BEGIN
        IF NOT EXISTS (
            SELECT 1 FROM proj.TBL_STOCK_ISSUE_RETURN
            WHERE ReturnId = @ReturnId AND Status = 'Draft' AND IsActive = 1
        ) BEGIN RAISERROR('Only Draft returns can be edited.', 16, 1); RETURN; END

        UPDATE proj.TBL_STOCK_ISSUE_RETURN
        SET ReturnDate   = @ReturnDate,
            ReturnedBy   = @ReturnedBy,
            Notes        = @Notes,
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = SYSDATETIME()
        WHERE ReturnId = @ReturnId;

        SELECT @ReturnId AS ReturnId, ReturnNo
        FROM proj.TBL_STOCK_ISSUE_RETURN
        WHERE ReturnId = @ReturnId;
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetIssueReturnLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetIssueReturnLine];
GO

-- ── sp_SetIssueReturnLine ─────────────────────────────────────────────────
CREATE   PROCEDURE proj.sp_SetIssueReturnLine
    @ReturnLineId INT,
    @ReturnId     INT,
    @IssueLineId  INT,
    @LineNum      INT,
    @ItemDesc     NVARCHAR(500) = NULL,
    @ReturnQty    DECIMAL(18,4),
    @UomId        INT = NULL,
    @UnitCost     DECIMAL(18,4),
    @Notes        NVARCHAR(500) = NULL,
    @CreatedBy    NVARCHAR(100),
    @ModifiedBy   NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- Return must be in Draft
    IF NOT EXISTS (SELECT 1 FROM proj.TBL_STOCK_ISSUE_RETURN WHERE ReturnId = @ReturnId AND Status = 'Draft')
        RAISERROR('Return note is not in Draft status.', 16, 1);

    -- Get original issue line qty and item
    DECLARE @OriginalQty DECIMAL(18,4);
    DECLARE @ItemId      INT;
    SELECT @OriginalQty = Qty, @ItemId = ItemId
    FROM proj.TBL_STOCK_ISSUE_LINE
    WHERE IssueLineId = @IssueLineId;

    IF @OriginalQty IS NULL
        RAISERROR('Issue line not found.', 16, 1);

    -- Already-returned qty for this issue line (excluding current line if editing)
    DECLARE @AlreadyReturned DECIMAL(18,4);
    SELECT @AlreadyReturned = ISNULL(SUM(rl.ReturnQty), 0)
    FROM proj.TBL_STOCK_ISSUE_RETURN_LINE rl
    JOIN proj.TBL_STOCK_ISSUE_RETURN r ON r.ReturnId = rl.ReturnId
    WHERE rl.IssueLineId = @IssueLineId
      AND r.Status IN ('Draft', 'Confirmed')
      AND (@ReturnLineId = 0 OR rl.ReturnLineId <> @ReturnLineId);

    DECLARE @MaxReturnQty DECIMAL(18,4) = @OriginalQty - @AlreadyReturned;

    IF @ReturnQty > @MaxReturnQty
    BEGIN
        DECLARE @Msg NVARCHAR(300) = 'Return qty exceeds available qty to return. Max: ' + CAST(@MaxReturnQty AS NVARCHAR(30));
        RAISERROR(@Msg, 16, 1);
    END

    IF @ReturnLineId = 0
    BEGIN
        DECLARE @NextLineNum INT;
        SELECT @NextLineNum = ISNULL(MAX(LineNum), 0) + 1
        FROM proj.TBL_STOCK_ISSUE_RETURN_LINE WHERE ReturnId = @ReturnId;

        INSERT INTO proj.TBL_STOCK_ISSUE_RETURN_LINE
            (ReturnId, IssueLineId, LineNum, ItemId, ItemDesc, ReturnQty, UomId, UnitCost, Notes, CreatedBy)
        VALUES
            (@ReturnId, @IssueLineId, @NextLineNum, @ItemId, @ItemDesc, @ReturnQty, @UomId, @UnitCost, @Notes, @CreatedBy);

        SELECT SCOPE_IDENTITY() AS ReturnLineId;
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_STOCK_ISSUE_RETURN_LINE
        SET ItemDesc     = @ItemDesc,
            ReturnQty    = @ReturnQty,
            UomId        = @UomId,
            UnitCost     = @UnitCost,
            Notes        = @Notes,
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = SYSDATETIME()
        WHERE ReturnLineId = @ReturnLineId AND ReturnId = @ReturnId;

        SELECT @ReturnLineId AS ReturnLineId;
    END
END;
GO

