CREATE PROCEDURE proj.sp_SetItem
    @ItemId INT=NULL, @ItemCode NVARCHAR(50)=NULL, @ItemName NVARCHAR(200),
    @ItemNameAr NVARCHAR(200)=NULL, @ShortDescription NVARCHAR(500)=NULL,
    @CategoryId INT=NULL, @ItemTypeId INT=NULL,
    @BaseUomId INT=NULL, @PurchaseUomId INT=NULL, @SalesUomId INT=NULL,
    @Barcode NVARCHAR(100)=NULL, @HSCode NVARCHAR(50)=NULL,
    @IsStockable BIT=1, @IsSaleable BIT=1, @IsPurchasable BIT=1, @IsActive BIT=1,
    @BudgetCategoryId INT=NULL,
    @CreatedBy NVARCHAR(50)=NULL, @ModifiedBy NVARCHAR(50)=NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @BudgetCategoryId IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM proj.TBL_JOB_EXPENSE_CATEGORY
        WHERE ExpenseCategoryId = @BudgetCategoryId AND UsedForBudget = 1)
    BEGIN
        RAISERROR('The selected budget header is invalid or not flagged for budgeting.', 16, 1);
        RETURN;
    END

    IF @ItemId IS NULL OR @ItemId = 0
    BEGIN
        INSERT INTO proj.TBL_ITEM
            (ItemCode,ItemName,ItemNameAr,ShortDescription,CategoryId,ItemTypeId,
             BaseUomId,PurchaseUomId,SalesUomId,Barcode,HSCode,
             IsStockable,IsSaleable,IsPurchasable,IsActive,BudgetCategoryId,CreatedBy,CreatedDate)
        VALUES
            (@ItemCode,@ItemName,@ItemNameAr,@ShortDescription,@CategoryId,@ItemTypeId,
             @BaseUomId,@PurchaseUomId,@SalesUomId,@Barcode,@HSCode,
             @IsStockable,@IsSaleable,@IsPurchasable,@IsActive,@BudgetCategoryId,@CreatedBy,GETDATE());
        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_ITEM SET
            ItemCode=@ItemCode, ItemName=@ItemName, ItemNameAr=@ItemNameAr,
            ShortDescription=@ShortDescription, CategoryId=@CategoryId,
            ItemTypeId=@ItemTypeId, BaseUomId=@BaseUomId,
            PurchaseUomId=@PurchaseUomId, SalesUomId=@SalesUomId,
            Barcode=@Barcode, HSCode=@HSCode,
            IsStockable=@IsStockable, IsSaleable=@IsSaleable,
            IsPurchasable=@IsPurchasable, IsActive=@IsActive,
            BudgetCategoryId=@BudgetCategoryId,
            ModifiedBy=@ModifiedBy, ModifiedDate=GETDATE()
        WHERE ItemId=@ItemId;
        SELECT CAST(@ItemId AS NVARCHAR(20));
    END
END;
GO

