CREATE PROCEDURE proj.sp_SetItemDetail
    @ItemDetailId      INT           = NULL,
    @ItemId            INT,
    @SKUCode           NVARCHAR(100) = NULL,
    @CountryOfOriginId INT           = NULL,
    @Brand             NVARCHAR(100) = NULL,
    @Model             NVARCHAR(100) = NULL,
    @Colour            NVARCHAR(50)  = NULL,
    @Size              NVARCHAR(50)  = NULL,
    @Grade             NVARCHAR(50)  = NULL,
    @SupplierPartNo    NVARCHAR(100) = NULL,
    @ManufacturerPartNo NVARCHAR(100)= NULL,
    @StandardCost      DECIMAL(18,4) = 0,
    @ListPrice         DECIMAL(18,4) = NULL,
    @Weight            DECIMAL(18,4) = NULL,
    @WeightUom         NVARCHAR(10)  = NULL,
    @LeadTimeDays      INT           = 0,
    @ShelfLifeDays     INT           = NULL,
    @MinStockLevel     DECIMAL(18,4) = 0,
    @MaxStockLevel     DECIMAL(18,4) = NULL,
    @ReorderLevel      DECIMAL(18,4) = 0,
    @IsDefault         BIT           = 0,
    @IsActive          BIT           = 1,
    @CreatedBy         NVARCHAR(50)  = NULL,
    @ModifiedBy        NVARCHAR(50)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @IsDefault = 1
        UPDATE proj.TBL_ITEM_DETAIL SET IsDefault = 0
        WHERE ItemId = @ItemId AND ItemDetailId != ISNULL(@ItemDetailId, 0);

    IF @ItemDetailId IS NULL OR @ItemDetailId = 0
    BEGIN
        INSERT INTO proj.TBL_ITEM_DETAIL
            (ItemId, SKUCode, CountryOfOriginId, Brand, Model, Colour, Size, Grade,
             SupplierPartNo, ManufacturerPartNo, StandardCost, ListPrice,
             Weight, WeightUom, LeadTimeDays, ShelfLifeDays,
             MinStockLevel, MaxStockLevel, ReorderLevel,
             IsDefault, IsActive, CreatedBy, CreatedDate)
        VALUES
            (@ItemId, @SKUCode, @CountryOfOriginId, @Brand, @Model, @Colour, @Size, @Grade,
             @SupplierPartNo, @ManufacturerPartNo, @StandardCost, @ListPrice,
             @Weight, @WeightUom, @LeadTimeDays, @ShelfLifeDays,
             @MinStockLevel, @MaxStockLevel, @ReorderLevel,
             @IsDefault, @IsActive, @CreatedBy, GETDATE());
        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_ITEM_DETAIL SET
            SKUCode=@SKUCode, CountryOfOriginId=@CountryOfOriginId,
            Brand=@Brand, Model=@Model, Colour=@Colour, Size=@Size, Grade=@Grade,
            SupplierPartNo=@SupplierPartNo, ManufacturerPartNo=@ManufacturerPartNo,
            StandardCost=@StandardCost, ListPrice=@ListPrice,
            Weight=@Weight, WeightUom=@WeightUom,
            LeadTimeDays=@LeadTimeDays, ShelfLifeDays=@ShelfLifeDays,
            MinStockLevel=@MinStockLevel, MaxStockLevel=@MaxStockLevel, ReorderLevel=@ReorderLevel,
            IsDefault=@IsDefault, IsActive=@IsActive,
            ModifiedBy=@ModifiedBy, ModifiedDate=GETDATE()
        WHERE ItemDetailId=@ItemDetailId;
        SELECT CAST(@ItemDetailId AS NVARCHAR(20));
    END
END;
