CREATE PROCEDURE [PROJ].[sp_SetJob]
    @JobId                      NVARCHAR(50)  = NULL,
    @ParentJobId                NVARCHAR(50)  = NULL,
    @JobTypeId                  NVARCHAR(50),
    @JobStageId                 NVARCHAR(10),
    @CustomerId                 INT,
    @JobCurrencyId              INT,
    @JobExcRate                 NUMERIC(18,6) = 1,
    @JobDescription             VARCHAR(1000) = NULL,
    @JobDate                    DATETIME      = NULL,
    @ProjectName                VARCHAR(500)  = NULL,
    @LpoDate                    DATE          = NULL,
    @ContractRef                NVARCHAR(100) = NULL,
    @LpoRef                     NVARCHAR(100) = NULL,
    @JobStatusId                INT           = 1,
    @ExternalRef                NVARCHAR(50)  = NULL,
    @CreatedBy                  NVARCHAR(50),
    @ModifiedBy                 NVARCHAR(50)  = NULL,
    @OrderValue                 DECIMAL(18,2) = 0,
    @JobAdvanceAmount           DECIMAL(18,2) = 0,
    @JobPlannedStartDate        DATE          = NULL,
    @JobExpectedCompleteDate    DATE          = NULL,
    @JobExpectedDeliveryDate    DATE          = NULL,
    @BudgetCategoryId           INT           = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @RequiresParentJob BIT = 0;
    DECLARE @IsBudgetHeaderLinked BIT = 0;
    SELECT @RequiresParentJob    = ISNULL(RequiresParentJob, 0),
           @IsBudgetHeaderLinked = ISNULL(IsBudgetHeaderLinked, 0)
    FROM PROJ.TBL_JOBTYPE
    WHERE JobTypeId = @JobTypeId;

    IF @IsBudgetHeaderLinked = 1
    BEGIN
        IF @BudgetCategoryId IS NULL
        BEGIN
            RAISERROR('A budget header (expense category) is required for jobs of this job type.', 16, 1);
            RETURN;
        END
        IF NOT EXISTS (SELECT 1 FROM proj.TBL_JOB_EXPENSE_CATEGORY
                       WHERE ExpenseCategoryId = @BudgetCategoryId AND UsedForBudget = 1)
        BEGIN
            RAISERROR('The selected budget header is invalid or not flagged for budgeting.', 16, 1);
            RETURN;
        END
        -- Only ONE open in-house job per budget header at a time.
        IF EXISTS (
            SELECT 1 FROM proj.TBL_JOB j
            JOIN proj.TBL_JOBTYPE   jt2 ON jt2.JobTypeId = j.JobTypeId AND ISNULL(jt2.IsBudgetHeaderLinked,0) = 1
            JOIN proj.TBL_JOB_STATUS js ON js.JobStatusId = j.JobStatusId
            WHERE j.BudgetCategoryId = @BudgetCategoryId
              AND ISNULL(js.IsClosed, 0) = 0
              AND j.JobId <> ISNULL(@JobId, ''))
        BEGIN
            RAISERROR('An open in-house job already exists for this budget header. Close it before opening a new one.', 16, 1);
            RETURN;
        END
    END
    ELSE IF @BudgetCategoryId IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM proj.TBL_JOB_EXPENSE_CATEGORY
            WHERE ExpenseCategoryId = @BudgetCategoryId AND UsedForBudget = 1)
    BEGIN
        RAISERROR('The selected budget header is invalid or not flagged for budgeting.', 16, 1);
        RETURN;
    END

    DECLARE @IsNew BIT = 0;
    DECLARE @GeneratedJobId NVARCHAR(100);

    IF @JobId IS NULL OR LTRIM(RTRIM(@JobId)) = ''
    BEGIN
        SET @IsNew = 1;
        EXEC proj.SP_GENERATEJOBSERIES
            @JobTypeId = @JobTypeId,
            @JobID     = @GeneratedJobId OUTPUT;
        SET @JobId = @GeneratedJobId;
    END

    IF @IsNew = 1 AND @RequiresParentJob = 1 AND (@ParentJobId IS NULL OR LTRIM(RTRIM(@ParentJobId)) = '') BEGIN RAISERROR('A Parent Job is required for this job type.', 16, 1); RETURN; END

    IF @IsNew = 1 AND @ParentJobId IS NOT NULL AND LTRIM(RTRIM(@ParentJobId)) <> ''
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM PROJ.TBL_JOB WHERE JobId = @ParentJobId) BEGIN RAISERROR('The specified Parent Job does not exist.', 16, 1); RETURN; END

        DECLARE @ParentRequiresParent BIT = 0;
        SELECT @ParentRequiresParent = ISNULL(jt.RequiresParentJob, 0)
        FROM PROJ.TBL_JOB j
        JOIN PROJ.TBL_JOBTYPE jt ON j.JobTypeId = jt.JobTypeId
        WHERE j.JobId = @ParentJobId;

        IF @ParentRequiresParent = 1 BEGIN RAISERROR('An additional job cannot be used as a parent job. Please select a main job.', 16, 1); RETURN; END
    END

    IF @IsNew = 1
    BEGIN
        INSERT INTO proj.TBL_JOB (
            JobId, ParentJobId, JobTypeId, JobStageId, CustomerId,
            JobCurrencyId, JobExcRate, JobDescription, JobDate, ProjectName,
            LpoDate, ContractRef, LpoRef, JobStatusId, ExternalRef,
            BudgetCategoryId,
            JobCreatedBy, JobCreatedDate, JobLastModifiedBy, JobLastUpdatedDate
        ) VALUES (
            @JobId, @ParentJobId, @JobTypeId, @JobStageId, @CustomerId,
            @JobCurrencyId, @JobExcRate, @JobDescription,
            ISNULL(@JobDate, GETDATE()), @ProjectName,
            @LpoDate, @ContractRef, @LpoRef, @JobStatusId, @ExternalRef,
            @BudgetCategoryId,
            @CreatedBy, GETDATE(), NULL, NULL
        );

        IF NOT EXISTS (SELECT 1 FROM proj.TBL_JOB_FINANCE WHERE JobId = @JobId)
            INSERT INTO proj.TBL_JOB_FINANCE
                (JobId, OrderValue, JobAdvanceAmount, ExchangeRate, CreatedBy, CreatedDate)
            VALUES
                (@JobId, @OrderValue, @JobAdvanceAmount, @JobExcRate, @CreatedBy, GETDATE());

        IF NOT EXISTS (SELECT 1 FROM proj.TBL_JOB_DATES WHERE JobId = @JobId)
            INSERT INTO proj.TBL_JOB_DATES
                (JobId, JobPlannedStartDate, JobExpectedCompleteDate, JobExpectedDeliveryDate, CreatedBy)
            VALUES
                (@JobId, @JobPlannedStartDate, @JobExpectedCompleteDate, @JobExpectedDeliveryDate, @CreatedBy);
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_JOB SET
            ParentJobId        = CASE WHEN @ParentJobId IS NOT NULL AND LTRIM(RTRIM(@ParentJobId)) <> ''
                                      THEN @ParentJobId ELSE ParentJobId END,
            JobTypeId          = @JobTypeId,
            JobStageId         = @JobStageId,
            CustomerId         = @CustomerId,
            JobCurrencyId      = @JobCurrencyId,
            JobExcRate         = @JobExcRate,
            JobDescription     = @JobDescription,
            JobDate            = ISNULL(@JobDate, JobDate),
            ProjectName        = @ProjectName,
            LpoDate            = @LpoDate,
            ContractRef        = @ContractRef,
            LpoRef             = @LpoRef,
            ExternalRef        = @ExternalRef,
            BudgetCategoryId   = @BudgetCategoryId,
            JobLastModifiedBy  = @ModifiedBy,
            JobLastUpdatedDate = GETDATE()
        WHERE JobId = @JobId;

        IF EXISTS (SELECT 1 FROM proj.TBL_JOB_FINANCE WHERE JobId = @JobId)
            UPDATE proj.TBL_JOB_FINANCE SET
                OrderValue       = @OrderValue,
                JobAdvanceAmount = @JobAdvanceAmount,
                ExchangeRate     = @JobExcRate,
                ModifiedBy       = @ModifiedBy,
                ModifiedDate     = GETDATE()
            WHERE JobId = @JobId;
        ELSE
            INSERT INTO proj.TBL_JOB_FINANCE
                (JobId, OrderValue, JobAdvanceAmount, ExchangeRate, CreatedBy, CreatedDate)
            VALUES
                (@JobId, @OrderValue, @JobAdvanceAmount, @JobExcRate, @ModifiedBy, GETDATE());

        IF EXISTS (SELECT 1 FROM proj.TBL_JOB_DATES WHERE JobId = @JobId)
            UPDATE proj.TBL_JOB_DATES SET
                JobPlannedStartDate      = @JobPlannedStartDate,
                JobExpectedCompleteDate  = @JobExpectedCompleteDate,
                JobExpectedDeliveryDate  = @JobExpectedDeliveryDate,
                ModifiedBy               = @ModifiedBy,
                ModifiedDate             = GETDATE()
            WHERE JobId = @JobId;
        ELSE
            INSERT INTO proj.TBL_JOB_DATES
                (JobId, JobPlannedStartDate, JobExpectedCompleteDate, JobExpectedDeliveryDate, CreatedBy)
            VALUES
                (@JobId, @JobPlannedStartDate, @JobExpectedCompleteDate, @JobExpectedDeliveryDate, @ModifiedBy);
    END

    SELECT @JobId AS JobId;
END
GO

IF OBJECT_ID(N'[proj].[sp_SetJobBudget]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetJobBudget];
GO

CREATE   PROCEDURE proj.sp_SetJobBudget
    @JobId          NVARCHAR(50),
    @CostCategoryId INT,
    @RvNo           INT           = 0,
    @BudgetedAmount DECIMAL(18,2),
    @Qty            DECIMAL(18,4) = NULL,
    @UnitPrice      DECIMAL(18,4) = NULL,
    @UomId          INT           = NULL,
    @Notes          NVARCHAR(500) = NULL,
    @CurrencyId     INT           = NULL,    -- line currency (defaults to job currency)
    @ExchangeRate   DECIMAL(18,6) = NULL,    -- rate to BASE (auto-resolved if NULL)
    @CreatedBy      NVARCHAR(100),
    @ModifiedBy     NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- Guard: refuse to write to an already-approved revision
    IF EXISTS (
        SELECT 1 FROM proj.TBL_JOB_BUDGET
        WHERE JobId = @JobId AND RvNo = @RvNo AND IsApproved = 1
    )
    BEGIN
        RAISERROR('This budget revision is approved and locked. Revise it to create a new editable version.', 16, 1);
        RETURN;
    END

    -- Job currency context
    DECLARE @JobCurrency INT, @JobRate DECIMAL(18,6);
    SELECT @JobCurrency = JobCurrencyId,
           @JobRate     = ISNULL(NULLIF(JobExcRate, 0), 1)
    FROM proj.TBL_JOB WHERE JobId = @JobId;

    -- Default the line currency to the job currency.
    IF ISNULL(@CurrencyId, 0) <= 0 SET @CurrencyId = @JobCurrency;

    -- Resolve the line's rate to base if not supplied (base currency = 1).
    IF @ExchangeRate IS NULL OR @ExchangeRate <= 0
    BEGIN
        SELECT @ExchangeRate = CASE WHEN IsBaseCurrency = 1 THEN 1 ELSE ExchangeRate END
        FROM proj.TBL_CURRENCY WHERE CurrencyId = @CurrencyId;
        IF @ExchangeRate IS NULL OR @ExchangeRate <= 0 SET @ExchangeRate = 1;
    END

    -- Validate the line currency + rate.
    DECLARE @Resolved DECIMAL(18,6);
    EXEC proj.sp_ValidateTxnCurrency @CurrencyId, @ExchangeRate, N'Budget', @Resolved OUTPUT;

    -- Base-currency amounts for the order-value comparison.
    DECLARE @OrderValue DECIMAL(18,2) =
        ISNULL((SELECT OrderValue FROM proj.TBL_JOB_FINANCE WHERE JobId = @JobId), 0);
    IF @OrderValue <= 0
    BEGIN
        RAISERROR('Set the job Order Value before adding a budget.', 16, 1);
        RETURN;
    END

    DECLARE @OrderValueBase DECIMAL(18,2) = proj.fn_ToBase(@OrderValue, @JobRate);
    DECLARE @LineBase       DECIMAL(18,2) = proj.fn_ToBase(@BudgetedAmount, @ExchangeRate);
    DECLARE @OtherBase      DECIMAL(18,2) = ISNULL((
        SELECT SUM(ISNULL(AmountInBaseCurrency, proj.fn_ToBase(BudgetedAmount, ISNULL(ExchangeRate, @JobRate))))
        FROM proj.TBL_JOB_BUDGET
        WHERE JobId = @JobId AND RvNo = @RvNo AND CostCategoryId <> @CostCategoryId
    ), 0);
    DECLARE @NewTotalBase   DECIMAL(18,2) = @OtherBase + @LineBase;

    IF @NewTotalBase > @OrderValueBase
    BEGIN
        DECLARE @BaseCode NVARCHAR(20) = ISNULL((SELECT ShortName FROM proj.TBL_CURRENCY WHERE IsBaseCurrency = 1), 'base');
        DECLARE @msg NVARCHAR(400) =
            'Total budget (' + CONVERT(NVARCHAR(30), CAST(@NewTotalBase AS DECIMAL(18,2))) + ' ' + @BaseCode + ')'
          + ' cannot exceed the job Order Value (' + CONVERT(NVARCHAR(30), CAST(@OrderValueBase AS DECIMAL(18,2))) + ' ' + @BaseCode + ').';
        RAISERROR(@msg, 16, 1);
        RETURN;
    END

    IF EXISTS (
        SELECT 1 FROM proj.TBL_JOB_BUDGET
        WHERE JobId = @JobId AND CostCategoryId = @CostCategoryId AND RvNo = @RvNo
    )
    BEGIN
        UPDATE proj.TBL_JOB_BUDGET SET
            BudgetedAmount       = @BudgetedAmount,
            Qty                  = @Qty,
            UnitPrice            = @UnitPrice,
            UomId                = @UomId,
            Notes                = @Notes,
            CurrencyId           = @CurrencyId,
            ExchangeRate         = @ExchangeRate,
            AmountInBaseCurrency = @LineBase,
            ModifiedBy           = @ModifiedBy,
            ModifiedDate         = GETDATE()
        WHERE JobId = @JobId AND CostCategoryId = @CostCategoryId AND RvNo = @RvNo;
    END
    ELSE
    BEGIN
        INSERT INTO proj.TBL_JOB_BUDGET
            (JobId, CostCategoryId, RvNo, BudgetedAmount, Qty, UnitPrice, UomId, Notes,
             CurrencyId, ExchangeRate, AmountInBaseCurrency,
             CreatedBy, CreatedDate, IsApproved, IsCurrent)
        VALUES
            (@JobId, @CostCategoryId, @RvNo, @BudgetedAmount, @Qty, @UnitPrice, @UomId, @Notes,
             @CurrencyId, @ExchangeRate, @LineBase,
             @CreatedBy, GETDATE(), 0, 1);
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_SetJobBudgetItem]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetJobBudgetItem];
GO

CREATE PROCEDURE proj.sp_SetJobBudgetItem
    @BudgetItemId   INT           = 0,
    @JobId          NVARCHAR(50),
    @RvNo           INT           = 0,
    @CostCategoryId INT,
    @ItemId         INT,
    @Qty            DECIMAL(18,4) = 0,
    @UomId          INT           = NULL,
    @UnitPrice      DECIMAL(18,4) = 0,
    @Notes          NVARCHAR(300) = NULL,
    @CreatedBy      NVARCHAR(100),
    @ModifiedBy     NVARCHAR(100) = NULL,
    @Reason         NVARCHAR(500) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    BEGIN TRY
        IF NOT EXISTS (SELECT 1 FROM proj.TBL_JOB WHERE JobId=@JobId AND ApprovalStatus='Approved')
            THROW 50702, 'The job must be approved before its budget can be edited.', 1;
        IF EXISTS (SELECT 1 FROM proj.TBL_JOB_BUDGET WHERE JobId=@JobId AND RvNo=@RvNo AND IsApproved=1)
            THROW 50700, 'This budget revision is approved and locked. Revise it to edit.', 1;
        IF ISNULL(@Qty,0) <= 0 THROW 50701, 'Qty must be greater than zero.', 1;

        -- Commitment check: only for costing-required jobs, only when editing and decreasing qty
        IF @BudgetItemId > 0
        BEGIN
            DECLARE @IsCostingRequired BIT;
            SELECT @IsCostingRequired = jt.IsCostingRequired
            FROM proj.TBL_JOB j
            JOIN proj.TBL_JOBTYPE jt ON jt.JobTypeId = j.JobTypeId
            WHERE j.JobId = @JobId;

            IF @IsCostingRequired = 1
            BEGIN
                DECLARE @OldQtyCheck DECIMAL(18,4);
                SELECT @OldQtyCheck = Qty FROM proj.TBL_JOB_BUDGET_ITEM WHERE BudgetItemId = @BudgetItemId;

                IF @Qty < @OldQtyCheck
                BEGIN
                    DECLARE @PrQty  DECIMAL(18,4),
                            @PoQty  DECIMAL(18,4),
                            @GrnQty DECIMAL(18,4),
                            @Floor  DECIMAL(18,4);

                    SELECT @PrQty = ISNULL(SUM(prl.RequiredQty), 0)
                    FROM proj.TBL_PURCHASE_REQUEST_LINE prl
                    JOIN proj.TBL_PURCHASE_REQUEST pr ON pr.PrId = prl.PrId
                    WHERE pr.JobId = @JobId
                      AND prl.ItemId = @ItemId
                      AND prl.IsActive = 1
                      AND pr.Status NOT IN ('Rejected', 'Cancelled');

                    SELECT @PoQty = ISNULL(SUM(pol.OrderedQty), 0)
                    FROM proj.TBL_PURCHASE_ORDER_LINE pol
                    JOIN proj.TBL_PURCHASE_ORDER po ON po.PoId = pol.PoId
                    WHERE po.JobId = @JobId
                      AND pol.ItemId = @ItemId
                      AND pol.IsActive = 1
                      AND po.Status NOT IN ('Rejected', 'Cancelled');

                    SELECT @GrnQty = ISNULL(SUM(d.ReceivedQty), 0)
                    FROM proj.TBL_GRN_DETAIL d
                    JOIN proj.TBL_GRN_HEADER g ON g.GrnId = d.GrnId
                    WHERE g.JobId = @JobId
                      AND d.ItemId = @ItemId
                      AND d.IsActive = 1
                      AND g.Status <> 'Cancelled';

                    SELECT @Floor = MAX(v) FROM (VALUES (@PrQty), (@PoQty), (@GrnQty)) AS t(v);

                    IF @Qty < @Floor
                    BEGIN
                        DECLARE @ErrMsg NVARCHAR(500);
                        SET @ErrMsg = 'Cannot reduce budget below committed quantity of '
                            + CAST(CAST(@Floor AS DECIMAL(18,2)) AS NVARCHAR(30))
                            + ' (PR: ' + CAST(CAST(@PrQty AS DECIMAL(18,2)) AS NVARCHAR(20))
                            + ', PO: ' + CAST(CAST(@PoQty AS DECIMAL(18,2)) AS NVARCHAR(20))
                            + ', GRN received: ' + CAST(CAST(@GrnQty AS DECIMAL(18,2)) AS NVARCHAR(20)) + ').';
                        THROW 50703, @ErrMsg, 1;
                    END
                END
            END
        END

        IF @UomId IS NULL SET @UomId = (SELECT BaseUomId FROM proj.TBL_ITEM WHERE ItemId=@ItemId);

        DECLARE @newId INT = @BudgetItemId, @oldQty DECIMAL(18,4), @oldPrice DECIMAL(18,4), @act NVARCHAR(20);
        DECLARE @who NVARCHAR(100) = ISNULL(@ModifiedBy, @CreatedBy);

        IF @BudgetItemId IS NULL OR @BudgetItemId <= 0
        BEGIN
            DECLARE @existId INT = (SELECT TOP 1 BudgetItemId FROM proj.TBL_JOB_BUDGET_ITEM
                WHERE JobId=@JobId AND RvNo=@RvNo AND CostCategoryId=@CostCategoryId AND ItemId=@ItemId AND IsActive=1);
            IF @existId IS NOT NULL
            BEGIN
                SELECT @oldQty = Qty, @oldPrice = UnitPrice FROM proj.TBL_JOB_BUDGET_ITEM WHERE BudgetItemId=@existId;
                UPDATE proj.TBL_JOB_BUDGET_ITEM
                SET Qty = Qty + @Qty,
                    UnitPrice = CASE WHEN ISNULL(@UnitPrice,0) > 0 THEN @UnitPrice ELSE UnitPrice END,
                    UomId = @UomId, ModifiedBy = @CreatedBy, ModifiedDate = GETDATE()
                WHERE BudgetItemId = @existId;
                SET @newId = @existId;
                INSERT INTO proj.TBL_JOB_BUDGET_ITEM_LOG (BudgetItemId,JobId,RvNo,CostCategoryId,ItemId,Action,OldQty,NewQty,OldUnitPrice,NewUnitPrice,ChangedBy,Reason)
                VALUES (@existId,@JobId,@RvNo,@CostCategoryId,@ItemId,'INCREASE',@oldQty,@oldQty+@Qty,@oldPrice,
                        CASE WHEN ISNULL(@UnitPrice,0)>0 THEN @UnitPrice ELSE @oldPrice END,@who,@Reason);
            END
            ELSE
            BEGIN
                INSERT INTO proj.TBL_JOB_BUDGET_ITEM (JobId, RvNo, CostCategoryId, ItemId, Qty, UomId, UnitPrice, Notes, CreatedBy)
                VALUES (@JobId, @RvNo, @CostCategoryId, @ItemId, @Qty, @UomId, @UnitPrice, @Notes, @CreatedBy);
                SET @newId = CAST(SCOPE_IDENTITY() AS INT);
                INSERT INTO proj.TBL_JOB_BUDGET_ITEM_LOG (BudgetItemId,JobId,RvNo,CostCategoryId,ItemId,Action,OldQty,NewQty,OldUnitPrice,NewUnitPrice,ChangedBy,Reason)
                VALUES (@newId,@JobId,@RvNo,@CostCategoryId,@ItemId,'ADD',NULL,@Qty,NULL,@UnitPrice,@who,@Reason);
            END
        END
        ELSE
        BEGIN
            SELECT @oldQty = Qty, @oldPrice = UnitPrice FROM proj.TBL_JOB_BUDGET_ITEM WHERE BudgetItemId=@BudgetItemId;
            UPDATE proj.TBL_JOB_BUDGET_ITEM
            SET ItemId=@ItemId, Qty=@Qty, UomId=@UomId, UnitPrice=@UnitPrice, Notes=@Notes, ModifiedBy=@ModifiedBy, ModifiedDate=GETDATE()
            WHERE BudgetItemId=@BudgetItemId;
            SET @act = CASE WHEN @Qty > @oldQty THEN 'INCREASE' WHEN @Qty < @oldQty THEN 'DECREASE' ELSE 'UPDATE' END;
            INSERT INTO proj.TBL_JOB_BUDGET_ITEM_LOG (BudgetItemId,JobId,RvNo,CostCategoryId,ItemId,Action,OldQty,NewQty,OldUnitPrice,NewUnitPrice,ChangedBy,Reason)
            VALUES (@BudgetItemId,@JobId,@RvNo,@CostCategoryId,@ItemId,@act,@oldQty,@Qty,@oldPrice,@UnitPrice,@who,@Reason);
        END

        COMMIT;
        SELECT @newId AS BudgetItemId;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        THROW;
    END CATCH
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetJobDeliveredUnit]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetJobDeliveredUnit];
GO
CREATE   PROCEDURE proj.sp_SetJobDeliveredUnit
    @JobId         NVARCHAR(50),
    @DeliveredUnit DECIMAL(18,2),
    @ModifiedBy    NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    IF @DeliveredUnit IS NULL OR @DeliveredUnit < 0
    BEGIN
        RAISERROR('Delivered units must be zero or a positive number.', 16, 1);
        RETURN;
    END

    DECLARE @Total DECIMAL(18,2);
    IF NOT EXISTS (SELECT 1 FROM proj.TBL_JOB_META WHERE JobId = @JobId)
    BEGIN
        RAISERROR('Job meta is not set up for this job. Configure job meta before recording delivered units.', 16, 1);
        RETURN;
    END

    SELECT @Total = TotalUnits FROM proj.TBL_JOB_META WHERE JobId = @JobId;
    IF @Total IS NOT NULL AND @DeliveredUnit > @Total
    BEGIN
        DECLARE @m NVARCHAR(300) =
            'Delivered units (' + CAST(@DeliveredUnit AS NVARCHAR(20)) +
            ') cannot exceed the job total units (' + CAST(@Total AS NVARCHAR(20)) + ').';
        RAISERROR(@m, 16, 1);
        RETURN;
    END

    DECLARE @Old DECIMAL(18,2);
    SELECT @Old = DeliveredUnit FROM proj.TBL_JOB_META WHERE JobId = @JobId;

    UPDATE proj.TBL_JOB_META
    SET DeliveredUnit = @DeliveredUnit,
        ModifiedBy    = @ModifiedBy,
        ModifiedDate  = GETDATE()
    WHERE JobId = @JobId;

    EXEC proj.sp_AddJobAudit
        @JobId     = @JobId,
        @Action    = 'DELIVERED_UNIT_UPDATED',
        @Section   = 'Meta',
        @OldValue  = @Old,
        @NewValue  = @DeliveredUnit,
        @CreatedBy = @ModifiedBy;

    SELECT @JobId AS JobId;
END
GO

IF OBJECT_ID(N'[proj].[sp_SetJobEngineer]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetJobEngineer];
GO

CREATE   PROCEDURE [PROJ].[sp_SetJobEngineer]
    @JobEngineerId INT           = 0,
    @JobId         NVARCHAR(50),
    @EngineerId    INT,
    @Role          NVARCHAR(50)  = NULL,
    @AssignedBy    NVARCHAR(50),
    @Completed     BIT           = 0
AS
BEGIN
    SET NOCOUNT ON;
    IF @JobEngineerId = 0 OR @JobEngineerId IS NULL
    BEGIN
        IF EXISTS (SELECT 1 FROM TBL_JOB_ENGINEER WHERE JobId=@JobId AND EngineerId=@EngineerId)
        BEGIN SELECT -1 AS JobEngineerId; RETURN; END

        INSERT INTO TBL_JOB_ENGINEER
            (JobId, EngineerId, Role, AssignedDate, AssignedBy, Completed, CreatedDate)
        VALUES
            (@JobId, @EngineerId, @Role, GETDATE(), @AssignedBy, @Completed, GETDATE());
        SELECT SCOPE_IDENTITY() AS JobEngineerId;
    END
    ELSE
    BEGIN
        UPDATE TBL_JOB_ENGINEER SET
            Role = @Role, Completed = @Completed,
            ModifiedBy = @AssignedBy, ModifiedDate = GETDATE()
        WHERE JobEngineerId = @JobEngineerId AND JobId = @JobId;
        SELECT @JobEngineerId AS JobEngineerId;
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_SetJobExpense]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetJobExpense];
GO

CREATE       PROCEDURE [PROJ].[sp_SetJobExpense]
    @ExpenseId            INT           = 0,
    @JobId                NVARCHAR(50),
    @ExpenseCategoryId    INT,
    @ExpenseDescription   NVARCHAR(500) = NULL,
    @ExpenseAmount        DECIMAL(18,2),
    @ExpenseDate          DATE,
    @CurrencyId           INT           = NULL,
    @ExchangeRate         DECIMAL(18,6) = 1,
    @AmountInBaseCurrency DECIMAL(18,2) = NULL,   -- ignored: computed server-side (kept for API compat)
    @ReferenceNo          NVARCHAR(100) = NULL,
    @Remarks              NVARCHAR(500) = NULL,
    @CreatedBy            NVARCHAR(50),
    @ModifiedBy           NVARCHAR(50)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    -- Block transactional saves on a closed job (Freezed/Completed/Cancelled).
    IF @JobId IS NOT NULL EXEC proj.sp_AssertJobOpen @JobId;
    -- Block transactional saves on a job whose budget is not yet approved.
    IF @JobId IS NOT NULL EXEC proj.sp_AssertBudgetApproved @JobId, N'EXPENSE';



    -- Default a missing currency to the configured base currency (rate 1).
    -- Base currency is data-driven (IsBaseCurrency=1) — never hardcoded.
    IF ISNULL(@CurrencyId, 0) <= 0
    BEGIN
        SELECT @CurrencyId = CurrencyId FROM proj.TBL_CURRENCY WHERE IsBaseCurrency = 1;
        SET @ExchangeRate = 1;
    END

    -- Guard: valid currency + rate before the expense can post to job costing.
    DECLARE @Resolved DECIMAL(18,6);
    EXEC proj.sp_ValidateTxnCurrency @CurrencyId, @ExchangeRate, N'Expense', @Resolved OUTPUT;

    -- Authoritative base conversion (do not trust the caller-supplied value).
    DECLARE @BaseAmt DECIMAL(18,2) = proj.fn_ToBase(@ExpenseAmount, @ExchangeRate);

    IF @ExpenseId = 0 OR @ExpenseId IS NULL
    BEGIN
        INSERT INTO proj.TBL_JOB_EXPENSE
            (JobId, ExpenseCategoryId, ExpenseDescription, ExpenseAmount, ExpenseDate,
             CurrencyId, ExchangeRate, AmountInBaseCurrency, ReferenceNo, Remarks,
             IsApproved, CreatedBy, CreatedDate)
        VALUES
            (@JobId, @ExpenseCategoryId, @ExpenseDescription, @ExpenseAmount, @ExpenseDate,
             @CurrencyId, @ExchangeRate, @BaseAmt, @ReferenceNo, @Remarks,
             0, @CreatedBy, GETDATE());
        SELECT SCOPE_IDENTITY() AS ExpenseId;
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_JOB_EXPENSE SET
            ExpenseCategoryId    = @ExpenseCategoryId,
            ExpenseDescription   = @ExpenseDescription,
            ExpenseAmount        = @ExpenseAmount,
            ExpenseDate          = @ExpenseDate,
            CurrencyId           = @CurrencyId,
            ExchangeRate         = @ExchangeRate,
            AmountInBaseCurrency = @BaseAmt,
            ReferenceNo          = @ReferenceNo,
            Remarks              = @Remarks,
            ModifiedBy           = @ModifiedBy,
            ModifiedDate         = GETDATE()
        WHERE ExpenseId = @ExpenseId AND JobId = @JobId;
        SELECT @ExpenseId AS ExpenseId;
    END

    -- Keep TotalExpenses (base currency) in sync.
    UPDATE proj.TBL_JOB_FINANCE
    SET TotalExpenses = (
        SELECT ISNULL(SUM(ISNULL(AmountInBaseCurrency, proj.fn_ToBase(ExpenseAmount, ExchangeRate))), 0)
        FROM proj.TBL_JOB_EXPENSE
        WHERE JobId = @JobId
    )
    WHERE JobId = @JobId;
END
GO

IF OBJECT_ID(N'[proj].[sp_SetJobMeta]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetJobMeta];
GO
CREATE   PROCEDURE proj.sp_SetJobMeta
    @JobId          NVARCHAR(50),
    @BayId          INT,
    @JobCategoryId  INT,
    @QualityLevelId INT,
    @TotalUnits     DECIMAL(18,2),
    @ModifiedBy     NVARCHAR(50),
    @DeliveredUnit  DECIMAL(18,2) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- ── Invariant: delivered units can never exceed total units ──────────
    DECLARE @CurDelivered DECIMAL(18,2) =
        (SELECT ISNULL(DeliveredUnit, 0) FROM proj.TBL_JOB_META WHERE JobId = @JobId);
    DECLARE @EffDelivered DECIMAL(18,2) = ISNULL(@DeliveredUnit, ISNULL(@CurDelivered, 0));

    IF @TotalUnits IS NOT NULL AND @EffDelivered > @TotalUnits
    BEGIN
        DECLARE @m NVARCHAR(300) =
            'Total units (' + CAST(@TotalUnits AS NVARCHAR(20)) +
            ') cannot be less than units already delivered (' + CAST(@EffDelivered AS NVARCHAR(20)) + ').';
        RAISERROR(@m, 16, 1);
        RETURN;
    END

    IF EXISTS (SELECT 1 FROM proj.TBL_JOB_META WHERE JobId = @JobId)
    BEGIN
        UPDATE proj.TBL_JOB_META
        SET BayId          = @BayId,
            JobCategoryId  = @JobCategoryId,
            QualityLevelId = @QualityLevelId,
            TotalUnits     = @TotalUnits,
            DeliveredUnit  = ISNULL(@DeliveredUnit, DeliveredUnit),
            ModifiedBy     = @ModifiedBy,
            ModifiedDate   = GETDATE()
        WHERE JobId = @JobId;
    END
    ELSE
    BEGIN
        INSERT INTO proj.TBL_JOB_META
            (JobId, BayId, JobCategoryId, QualityLevelId, TotalUnits, DeliveredUnit, CreatedBy, CreatedDate)
        VALUES
            (@JobId, @BayId, @JobCategoryId, @QualityLevelId, @TotalUnits, @DeliveredUnit, @ModifiedBy, GETDATE());
    END

    EXEC proj.sp_AddJobAudit
        @JobId     = @JobId,
        @Action    = 'META_UPDATED',
        @Section   = 'Meta',
        @NewValue  = 'Job meta updated',
        @CreatedBy = @ModifiedBy;

    SELECT @JobId AS JobId;
END
GO

