CREATE   PROCEDURE PROJ.sp_SetMOMTask
    @MomTaskId   INT,
    @MomId       INT,
    @JobId       VARCHAR(30),
    @Description NVARCHAR(MAX),
    @DueDate     DATE          = NULL,
    @Priority    NVARCHAR(20)  = 'Medium',
    @AssignedTo  NVARCHAR(100),
    @Remarks     NVARCHAR(MAX) = NULL,
    @CreatedBy   NVARCHAR(100),
    @ModifiedBy  NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @MomTaskId = 0
    BEGIN
        BEGIN TRY
            BEGIN TRANSACTION;

            INSERT INTO PROJ.TBL_MOM_TASK
                (MomId, JobId, Description, DueDate, Priority, AssignedTo, Status, Remarks, IsActive, CreatedBy, CreatedDate)
            VALUES
                (@MomId, @JobId, @Description, @DueDate, @Priority, @AssignedTo, 'Open', @Remarks, 1, @CreatedBy, GETDATE());

            SET @MomTaskId = CAST(SCOPE_IDENTITY() AS INT);

            INSERT INTO PROJ.TBL_MOM_TASK_LOG (MomTaskId, Action, ToUser, NewStatus, Remarks, ActionBy, ActionDate)
            VALUES (@MomTaskId, 'Assigned', @AssignedTo, 'Open', 'Task created', @CreatedBy, GETDATE());

            COMMIT;
            SELECT CAST(@MomTaskId AS NVARCHAR(20));
        END TRY
        BEGIN CATCH
            IF @@TRANCOUNT > 0 ROLLBACK;
            THROW;
        END CATCH
    END
    ELSE
    BEGIN
        UPDATE PROJ.TBL_MOM_TASK
        SET Description  = @Description,
            DueDate      = @DueDate,
            Priority     = @Priority,
            AssignedTo   = @AssignedTo,
            Remarks      = @Remarks,
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE MomTaskId = @MomTaskId;
        SELECT CAST(@MomTaskId AS NVARCHAR(20));
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_SetMOMTaskStatus]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetMOMTaskStatus];
GO
CREATE   PROCEDURE PROJ.sp_SetMOMTaskStatus
    @MomTaskId  INT,
    @NewStatus  NVARCHAR(20),
    @Remarks    NVARCHAR(MAX) = NULL,
    @ActionBy   NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @OldStatus NVARCHAR(20), @AssignedTo NVARCHAR(100), @CreatedBy NVARCHAR(100);
    SELECT @OldStatus = Status, @AssignedTo = AssignedTo, @CreatedBy = CreatedBy
    FROM PROJ.TBL_MOM_TASK WHERE MomTaskId = @MomTaskId AND IsActive = 1;

    -- Task must exist
    IF @OldStatus IS NULL
    BEGIN
        SELECT 'NOTFOUND';
        RETURN;
    END

    -- Only the assignee or the assigner may act
    IF @ActionBy <> @AssignedTo AND @ActionBy <> @CreatedBy
    BEGIN
        SELECT 'UNAUTHORIZED';
        RETURN;
    END

    -- Server-side workflow guard (mirrors the UI transition map)
    IF NOT (
            (@OldStatus = 'Open'       AND @NewStatus IN ('InProgress','Closed')) OR
            (@OldStatus = 'InProgress' AND @NewStatus IN ('Completed','Closed'))  OR
            (@OldStatus = 'Completed'  AND @NewStatus IN ('Closed'))              OR
            (@OldStatus = 'Reassigned' AND @NewStatus IN ('InProgress','Closed'))
       )
    BEGIN
        SELECT 'INVALID';
        RETURN;
    END

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE PROJ.TBL_MOM_TASK
        SET Status       = @NewStatus,
            ModifiedBy   = @ActionBy,
            ModifiedDate = GETDATE()
        WHERE MomTaskId = @MomTaskId;

        INSERT INTO PROJ.TBL_MOM_TASK_LOG (MomTaskId, Action, OldStatus, NewStatus, Remarks, ActionBy, ActionDate)
        VALUES (@MomTaskId, 'StatusChange', @OldStatus, @NewStatus, @Remarks, @ActionBy, GETDATE());

        COMMIT;
        SELECT CAST(@MomTaskId AS NVARCHAR(20));
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        THROW;
    END CATCH
END
GO

