CREATE PROCEDURE [PROJ].[sp_SetPaymentTerms]
    @PaymentTermsId INT,
    @TermCode NVARCHAR(20),
    @TermName NVARCHAR(100),
    @TermDays INT,
    @IsActive BIT,
    @CreatedBy NVARCHAR(50),
    @ModifiedBy NVARCHAR(50) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- Check for duplicate Code
    IF EXISTS (SELECT 1 FROM [TBL_PAYMENT_TERMS] 
               WHERE TermCode = @TermCode AND PaymentTermsId <> @PaymentTermsId)
    BEGIN
        SELECT '-1'; 
        RETURN;
    END

    IF @PaymentTermsId = 0
    BEGIN
        INSERT INTO [TBL_PAYMENT_TERMS] (
            TermCode, TermName, TermDays, IsActive, CreatedBy, CreatedDate
        )
        VALUES (
            @TermCode, @TermName, @TermDays, @IsActive, @CreatedBy, GETDATE()
        );
        SELECT SCOPE_IDENTITY();
    END
    ELSE
    BEGIN
        UPDATE [TBL_PAYMENT_TERMS]
        SET TermCode = @TermCode,
            TermName = @TermName,
            TermDays = @TermDays,
            IsActive = @IsActive,
            ModifiedBy = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE PaymentTermsId = @PaymentTermsId;
        
        SELECT @PaymentTermsId;
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_SetPaymentVoucher]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetPaymentVoucher];
GO

-- Fix sp_SetPaymentVoucher: convert @AmountPaid to base before comparing against base allocations
CREATE PROCEDURE proj.sp_SetPaymentVoucher
    @PvId         INT            = 0,
    @PvDate       DATE           = NULL,
    @SupplierId   INT,
    @CurrencyId   INT,
    @ExchangeRate DECIMAL(18,6)  = 1,
    @AmountPaid   DECIMAL(18,2)  = 0,
    @PaymentMode  NVARCHAR(30)   = NULL,
    @ReferenceNo  NVARCHAR(100)  = NULL,
    @ReferenceDate DATE          = NULL,
    @BankName     NVARCHAR(150)  = NULL,
    @Notes        NVARCHAR(500)  = NULL,
    @CreatedBy    NVARCHAR(100)  = NULL,
    @ModifiedBy   NVARCHAR(100)  = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NULLIF(@SupplierId, 0) IS NULL  BEGIN RAISERROR('Supplier is required.',                   16,1); RETURN; END
    IF NULLIF(@CurrencyId, 0) IS NULL  BEGIN RAISERROR('Currency is required.',                   16,1); RETURN; END
    IF ISNULL(@AmountPaid, 0) <= 0     BEGIN RAISERROR('Amount paid must be greater than zero.',  16,1); RETURN; END

    IF UPPER(LTRIM(RTRIM(ISNULL(@PaymentMode,'')))) = 'CHEQUE'
       AND NULLIF(LTRIM(RTRIM(ISNULL(@ReferenceNo,''))), '') IS NULL
        BEGIN RAISERROR('Cheque No is required when Payment Mode is Cheque.', 16,1); RETURN; END

    IF @PvId IS NULL OR @PvId <= 0
    BEGIN
        IF NULLIF(@CreatedBy,'') IS NULL BEGIN RAISERROR('CreatedBy is required.', 16,1); RETURN; END

        DECLARE @NumResult TABLE (DocNumber NVARCHAR(50), NewSeries INT);
        INSERT INTO @NumResult EXEC proj.sp_GetNextDocNumber 'PV';
        DECLARE @PvNo NVARCHAR(50); SELECT @PvNo = DocNumber FROM @NumResult;

        INSERT INTO proj.TBL_PAYMENT_VOUCHER
            (PvNumber, PvDate, SupplierId, CurrencyId, ExchangeRate, AmountPaid,
             PaymentMode, ReferenceNo, ReferenceDate, BankName, Notes, Status, CreatedBy)
        VALUES
            (@PvNo, ISNULL(@PvDate, CAST(GETDATE() AS DATE)), @SupplierId, @CurrencyId,
             ISNULL(@ExchangeRate,1), @AmountPaid,
             NULLIF(@PaymentMode,''), @ReferenceNo, @ReferenceDate,
             @BankName, @Notes, 'Draft', @CreatedBy);

        SELECT CAST(SCOPE_IDENTITY() AS INT) AS NewId, @PvNo AS PvNumber;
    END
    ELSE
    BEGIN
        IF EXISTS (SELECT 1 FROM proj.TBL_PAYMENT_VOUCHER WHERE PvId = @PvId AND Status <> 'Draft')
            BEGIN RAISERROR('Only Draft payment vouchers can be edited.', 16,1); RETURN; END

        -- AllocatedAmount is now BASE; convert @AmountPaid to base before comparing
        IF @AmountPaid * ISNULL(NULLIF(@ExchangeRate, 0), 1) <
           (SELECT ISNULL(SUM(AllocatedAmount),0) FROM proj.TBL_PAYMENT_VOUCHER_ALLOCATION WHERE PvId = @PvId AND IsActive = 1)
            BEGIN RAISERROR('Amount paid cannot be less than the amount already allocated. Remove allocations first.', 16,1); RETURN; END

        UPDATE proj.TBL_PAYMENT_VOUCHER
        SET    PvDate        = ISNULL(@PvDate, PvDate),
               SupplierId   = @SupplierId,
               CurrencyId   = @CurrencyId,
               ExchangeRate = ISNULL(@ExchangeRate, ExchangeRate),
               AmountPaid   = @AmountPaid,
               PaymentMode  = NULLIF(@PaymentMode,''),
               ReferenceNo  = @ReferenceNo,
               ReferenceDate= @ReferenceDate,
               BankName     = @BankName,
               Notes        = @Notes,
               ModifiedBy   = @ModifiedBy,
               ModifiedDate = GETDATE()
        WHERE  PvId = @PvId AND IsActive = 1;

        SELECT CAST(@PvId AS INT) AS NewId, PvNumber FROM proj.TBL_PAYMENT_VOUCHER WHERE PvId = @PvId;
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_SetPO]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetPO];
GO

CREATE PROCEDURE proj.sp_SetPO
    @PoId              INT           = 0,
    @PoDate            DATE          = NULL,
    @SupplierId        INT           = NULL,
    @SupplierContactId INT           = NULL,
    @JobId             NVARCHAR(50)  = NULL,
    @VendorName        NVARCHAR(200) = NULL,
    @VendorRef         NVARCHAR(100) = NULL,
    @VendorQuoteDate   DATE          = NULL,
    @CurrencyId        INT           = NULL,
    @ExchangeRate      DECIMAL(18,6) = 1,
    @PaymentTermsId    INT           = NULL,
    @DeliveryDate      DATE          = NULL,
    @DeliveryAddr      NVARCHAR(300) = NULL,
    @DeliveryTerms     NVARCHAR(100) = NULL,
    @Discount          DECIMAL(18,2) = NULL,
    @TaxAmount         DECIMAL(18,2) = NULL,
    @TotalAmount       DECIMAL(18,2) = NULL,
    @PaidAmount        DECIMAL(18,2) = NULL,
    @InvoiceReceived   BIT           = NULL,
    @ApprovedBy        NVARCHAR(100) = NULL,
    @ApprovedDate      DATETIME      = NULL,
    @HoldBy            NVARCHAR(100) = NULL,
    @HoldDate          DATETIME      = NULL,
    @Revision          INT           = NULL,
    @Priority          NVARCHAR(20)  = NULL,
    @Notes             NVARCHAR(500) = NULL,
    @ExpenseCategoryId INT           = NULL,
    @CreatedBy         NVARCHAR(100) = NULL,
    @ModifiedBy        NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @JobId IS NOT NULL EXEC proj.sp_AssertJobOpen @JobId;
    IF @JobId IS NOT NULL EXEC proj.sp_AssertBudgetApproved @JobId, N'PO';

    IF @PoId = 0 OR @PoId IS NULL
    BEGIN
        IF NULLIF(@CreatedBy, '')        IS NULL THROW 50500, 'CreatedBy is required.',         1;
        IF NULLIF(@SupplierId, 0)        IS NULL THROW 50501, 'Supplier is required.',          1;
        IF NULLIF(@JobId, '')            IS NULL THROW 50502, 'Job is required.',               1;
        IF NULLIF(@CurrencyId, 0)        IS NULL THROW 50503, 'Currency is required.',          1;
        IF NULLIF(@PaymentTermsId, 0)    IS NULL THROW 50504, 'Payment Terms are required.',    1;
        IF NULLIF(@ExpenseCategoryId, 0) IS NULL THROW 50506, 'Budget Category is required.',   1;

        DECLARE @IsClosed BIT = 0, @StatusName NVARCHAR(50) = '';
        SELECT @IsClosed = js.IsClosed, @StatusName = js.StatusName
        FROM   proj.TBL_JOB j
        JOIN   proj.TBL_JOB_STATUS js ON js.JobStatusId = j.JobStatusId
        WHERE  j.JobId = @JobId;
        IF @IsClosed = 1
        BEGIN
            DECLARE @ErrMsg NVARCHAR(200) = 'Job ' + @JobId + ' is ' + @StatusName + '. Revise the job to create new transactions.';
            THROW 50505, @ErrMsg, 1;
        END

        DECLARE @NumResult TABLE (DocNumber NVARCHAR(50), NewSeries INT);
        INSERT INTO @NumResult EXEC proj.sp_GetNextDocNumber 'PO';
        DECLARE @PoNumber NVARCHAR(50);
        SELECT @PoNumber = DocNumber FROM @NumResult;

        INSERT INTO PROJ.TBL_PURCHASE_ORDER (
            PoNumber, PoDate, SupplierId, SupplierContactId, JobId, VendorName, VendorRef,
            VendorQuoteDate, CurrencyId, ExchangeRate, PaymentTermsId, DeliveryDate, DeliveryAddr,
            DeliveryTerms, Discount, TaxAmount, TotalAmount, PaidAmount,
            InvoiceReceived, ApprovedBy, ApprovedDate, HoldBy, HoldDate,
            Revision, Priority, Notes, ExpenseCategoryId, CreatedBy, CreatedDate
        ) VALUES (
            @PoNumber, ISNULL(@PoDate, CAST(GETDATE() AS DATE)),
            @SupplierId, NULLIF(@SupplierContactId,0), @JobId,
            @VendorName, @VendorRef, @VendorQuoteDate,
            @CurrencyId, ISNULL(@ExchangeRate,1),
            @PaymentTermsId, @DeliveryDate, @DeliveryAddr,
            @DeliveryTerms, @Discount, @TaxAmount, @TotalAmount, @PaidAmount,
            ISNULL(@InvoiceReceived,0), @ApprovedBy, @ApprovedDate,
            @HoldBy, @HoldDate, ISNULL(@Revision,0), NULLIF(@Priority,''), @Notes,
            NULLIF(@ExpenseCategoryId,0), @CreatedBy, GETDATE()
        );

        DECLARE @NewPoId INT = SCOPE_IDENTITY();
        INSERT INTO PROJ.TBL_PURCHASE_ORDER_META (PoId, CreatedBy, CreatedDate)
        VALUES (@NewPoId, @CreatedBy, GETDATE());

        SELECT CAST(@NewPoId AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        UPDATE PROJ.TBL_PURCHASE_ORDER SET
            PoDate             = ISNULL(@PoDate,            PoDate),
            SupplierId         = NULLIF(@SupplierId,        0),
            SupplierContactId  = NULLIF(@SupplierContactId, 0),
            JobId              = NULLIF(@JobId,             ''),
            VendorName         = @VendorName,
            VendorRef          = @VendorRef,
            VendorQuoteDate    = @VendorQuoteDate,
            CurrencyId         = NULLIF(@CurrencyId,        0),
            ExchangeRate       = ISNULL(@ExchangeRate,      ExchangeRate),
            PaymentTermsId     = NULLIF(@PaymentTermsId,    0),
            DeliveryDate       = @DeliveryDate,
            DeliveryAddr       = @DeliveryAddr,
            DeliveryTerms      = @DeliveryTerms,
            Discount           = @Discount,
            Priority           = NULLIF(@Priority,          ''),
            TaxAmount          = ISNULL(@TaxAmount,         TaxAmount),
            TotalAmount        = ISNULL(@TotalAmount,       TotalAmount),
            PaidAmount         = ISNULL(@PaidAmount,        PaidAmount),
            InvoiceReceived    = ISNULL(@InvoiceReceived,   InvoiceReceived),
            ApprovedBy         = ISNULL(@ApprovedBy,        ApprovedBy),
            ApprovedDate       = ISNULL(@ApprovedDate,      ApprovedDate),
            HoldBy             = ISNULL(@HoldBy,            HoldBy),
            HoldDate           = ISNULL(@HoldDate,          HoldDate),
            Revision           = ISNULL(@Revision,          Revision),
            Notes              = @Notes,
            ExpenseCategoryId  = NULLIF(@ExpenseCategoryId, 0),
            ModifiedBy         = @ModifiedBy,
            ModifiedDate       = GETDATE()
        WHERE PoId = @PoId AND IsActive = 1;
        SELECT CAST(@PoId AS NVARCHAR(20));
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetPOAnnexure]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetPOAnnexure];
GO
-- ── Save annexure header (insert + update) ────────────────────────────
CREATE   PROCEDURE proj.sp_SetPOAnnexure
    @AnnexureId   INT           = 0,
    @PoId         INT,
    @AnnexureCode NVARCHAR(10)  = NULL,
    @Title        NVARCHAR(200) = NULL,
    @Notes        NVARCHAR(1000) = NULL,
    @SortOrder    INT           = 0,
    @CreatedBy    NVARCHAR(100) = NULL,
    @ModifiedBy   NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- Block writes on a non-Draft PO unless explicitly Revised
    DECLARE @PoStatus NVARCHAR(30);
    SELECT @PoStatus = Status FROM proj.TBL_PURCHASE_ORDER
    WHERE PoId = @PoId AND IsActive = 1;
    IF @PoStatus IS NULL                THROW 60100, 'PO not found.', 1;
    IF @PoStatus NOT IN ('Draft','Rejected') THROW 60101, 'Annexures can only be edited while the PO is in Draft.', 1;

    IF @AnnexureId IS NULL OR @AnnexureId <= 0
    BEGIN
        IF NULLIF(@CreatedBy, '') IS NULL THROW 60102, 'CreatedBy is required.', 1;

        -- Auto-assign next letter if AnnexureCode not provided
        IF NULLIF(@AnnexureCode, '') IS NULL
        BEGIN
            DECLARE @NextCode NVARCHAR(10);
            DECLARE @MaxLetter INT;
            SELECT @MaxLetter = MAX(ASCII(LEFT(AnnexureCode, 1)))
            FROM proj.TBL_PURCHASE_ORDER_ANNEXURE
            WHERE PoId = @PoId AND IsActive = 1
              AND LEN(AnnexureCode) = 1 AND AnnexureCode BETWEEN 'A' AND 'Z';
            SET @NextCode = CHAR(ISNULL(@MaxLetter, ASCII('A') - 1) + 1);
            IF ASCII(@NextCode) > ASCII('Z') SET @NextCode = 'A';   -- wrap
            SET @AnnexureCode = @NextCode;
        END

        -- Auto-set SortOrder if not provided
        IF @SortOrder = 0
            SELECT @SortOrder = ISNULL(MAX(SortOrder), 0) + 1
            FROM proj.TBL_PURCHASE_ORDER_ANNEXURE
            WHERE PoId = @PoId AND IsActive = 1;

        INSERT INTO proj.TBL_PURCHASE_ORDER_ANNEXURE
            (PoId, AnnexureCode, Title, Notes, SortOrder, CreatedBy)
        VALUES (@PoId, @AnnexureCode, @Title, @Notes, @SortOrder, @CreatedBy);

        SELECT CAST(SCOPE_IDENTITY() AS INT) AS AnnexureId, @AnnexureCode AS AnnexureCode;
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_PURCHASE_ORDER_ANNEXURE
        SET AnnexureCode = ISNULL(@AnnexureCode, AnnexureCode),
            Title        = @Title,
            Notes        = @Notes,
            SortOrder    = ISNULL(NULLIF(@SortOrder, 0), SortOrder),
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE AnnexureId = @AnnexureId AND PoId = @PoId AND IsActive = 1;

        SELECT @AnnexureId AS AnnexureId,
               (SELECT AnnexureCode FROM proj.TBL_PURCHASE_ORDER_ANNEXURE WHERE AnnexureId = @AnnexureId) AS AnnexureCode;
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetPOAnnexureDetail]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetPOAnnexureDetail];
GO
CREATE   PROCEDURE proj.sp_SetPOAnnexureDetail
    @AnnexureDetailId INT           = 0,
    @AnnexureId       INT,
    @LineNum          INT           = 0,
    @Description      NVARCHAR(MAX) = NULL,
    @Remarks          NVARCHAR(500) = NULL,
    @CreatedBy        NVARCHAR(100) = NULL,
    @ModifiedBy       NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @PoStatus NVARCHAR(30);
    SELECT @PoStatus = po.Status FROM proj.TBL_PURCHASE_ORDER po
    JOIN proj.TBL_PURCHASE_ORDER_ANNEXURE a ON a.PoId = po.PoId
    WHERE a.AnnexureId = @AnnexureId AND po.IsActive = 1 AND a.IsActive = 1;
    IF @PoStatus IS NULL                THROW 60110, 'Annexure or PO not found.', 1;
    IF @PoStatus NOT IN ('Draft','Rejected') THROW 60111, 'Annexures can only be edited while the PO is in Draft.', 1;

    IF @AnnexureDetailId IS NULL OR @AnnexureDetailId <= 0
    BEGIN
        IF NULLIF(@CreatedBy, '') IS NULL THROW 60112, 'CreatedBy is required.', 1;
        IF @LineNum = 0
            SELECT @LineNum = ISNULL(MAX(LineNum), 0) + 1
            FROM proj.TBL_PURCHASE_ORDER_ANNEXURE_DETAIL
            WHERE AnnexureId = @AnnexureId AND IsActive = 1;

        INSERT INTO proj.TBL_PURCHASE_ORDER_ANNEXURE_DETAIL
            (AnnexureId, LineNum, Description, Remarks, CreatedBy)
        VALUES (@AnnexureId, @LineNum, @Description, @Remarks, @CreatedBy);
        SELECT CAST(SCOPE_IDENTITY() AS INT) AS AnnexureDetailId, @LineNum AS LineNum;
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_PURCHASE_ORDER_ANNEXURE_DETAIL
        SET LineNum     = ISNULL(NULLIF(@LineNum, 0), LineNum),
            Description = @Description,
            Remarks     = @Remarks,
            ModifiedBy  = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE AnnexureDetailId = @AnnexureDetailId AND IsActive = 1;
        SELECT @AnnexureDetailId AS AnnexureDetailId;
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetPOAnnexureLineLinks]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetPOAnnexureLineLinks];
GO
-- Replace all line links for an annexure with the given list (delete-then-insert pattern)
CREATE   PROCEDURE proj.sp_SetPOAnnexureLineLinks
    @AnnexureId INT,
    @PoLineIds  NVARCHAR(MAX) = NULL,  -- CSV of PoLineIds; empty = clear all
    @CreatedBy  NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRAN;

        DECLARE @PoStatus NVARCHAR(30), @PoId INT;
        SELECT @PoStatus = po.Status, @PoId = po.PoId FROM proj.TBL_PURCHASE_ORDER po
        JOIN proj.TBL_PURCHASE_ORDER_ANNEXURE a ON a.PoId = po.PoId
        WHERE a.AnnexureId = @AnnexureId AND po.IsActive = 1 AND a.IsActive = 1;
        IF @PoStatus IS NULL                THROW 60140, 'Annexure or PO not found.', 1;
        IF @PoStatus NOT IN ('Draft','Rejected') THROW 60141, 'Annexure line links can only be edited while the PO is in Draft.', 1;

        DELETE FROM proj.TBL_PURCHASE_ORDER_ANNEXURE_LINE_LINK WHERE AnnexureId = @AnnexureId;

        IF NULLIF(@PoLineIds, '') IS NOT NULL
        BEGIN
            INSERT INTO proj.TBL_PURCHASE_ORDER_ANNEXURE_LINE_LINK (AnnexureId, PoLineId, CreatedBy)
            SELECT @AnnexureId, CAST(LTRIM(RTRIM(value)) AS INT), @CreatedBy
            FROM STRING_SPLIT(@PoLineIds, ',')
            WHERE TRY_CAST(LTRIM(RTRIM(value)) AS INT) IS NOT NULL
              AND EXISTS (SELECT 1 FROM proj.TBL_PURCHASE_ORDER_LINE pol
                          WHERE pol.PoLineId = TRY_CAST(LTRIM(RTRIM(value)) AS INT) AND pol.PoId = @PoId AND pol.IsActive = 1);
        END

        COMMIT;
        SELECT COUNT(*) AS LinkCount FROM proj.TBL_PURCHASE_ORDER_ANNEXURE_LINE_LINK WHERE AnnexureId = @AnnexureId;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        THROW;
    END CATCH
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetPOLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetPOLine];
GO

CREATE PROCEDURE PROJ.sp_SetPOLine
    @PoLineId    INT           = 0,
    @PoId        INT,
    @PrLineId    INT           = NULL,
    @ItemId      INT           = NULL,
    @ItemCode    NVARCHAR(50)  = NULL,
    @ItemDesc    NVARCHAR(300) = NULL,
    @OrderedQty  DECIMAL(18,4) = 1,
    @UomId       INT           = NULL,
    @UomName     NVARCHAR(50)  = NULL,
    @UnitPrice   DECIMAL(18,4) = 0,
    @TaxPct      DECIMAL(5,2)  = 0,
    @Remarks     NVARCHAR(300) = NULL,
    @CreatedBy   NVARCHAR(100) = NULL,
    @ModifiedBy  NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @ParentJobId NVARCHAR(50) = (SELECT JobId FROM proj.TBL_PURCHASE_ORDER WHERE PoId = @PoId);
    IF @ParentJobId IS NOT NULL EXEC proj.sp_AssertJobOpen @ParentJobId;
    IF @ParentJobId IS NOT NULL EXEC proj.sp_AssertBudgetApproved @ParentJobId, N'PO';

    IF NULLIF(@PoId, 0)       IS NULL RAISERROR('PoId is required.',                            16, 1);
    IF ISNULL(@OrderedQty, 0) <= 0    RAISERROR('Ordered quantity must be greater than zero.', 16, 1);
    IF ISNULL(@UnitPrice,  0)  < 0    RAISERROR('Unit price cannot be negative.',              16, 1);
    IF @@ERROR <> 0 RETURN;

    DECLARE @PoStatus NVARCHAR(30);
    SELECT @PoStatus = Status FROM PROJ.TBL_PURCHASE_ORDER WHERE PoId = @PoId AND IsActive = 1;
    IF @PoStatus IS NULL BEGIN RAISERROR('Purchase Order not found or is inactive.', 16, 1); RETURN; END
    IF @PoStatus <> 'Draft'
    BEGIN
        DECLARE @PsMsg NVARCHAR(200) = 'PO lines can only be added or edited when the PO is in Draft status. Current status: ' + @PoStatus;
        RAISERROR(@PsMsg, 16, 1); RETURN;
    END

    IF @PoLineId IS NULL OR @PoLineId <= 0
    BEGIN
        IF NULLIF(@CreatedBy, '') IS NULL RAISERROR('CreatedBy is required.',       16, 1);
        IF NULLIF(@ItemCode,  '') IS NULL RAISERROR('Item Code is required.',        16, 1);
        IF NULLIF(@UomId,      0) IS NULL RAISERROR('Unit of Measure is required.', 16, 1);
        IF @@ERROR <> 0 RETURN;
    END

    IF @PrLineId IS NOT NULL AND @PrLineId > 0
    BEGIN
        DECLARE @PrRequiredQty  DECIMAL(18,4) = 0;
        DECLARE @PrPoCreatedQty DECIMAL(18,4) = 0;
        DECLARE @OldPoQty       DECIMAL(18,4) = 0;

        SELECT @PrRequiredQty  = ISNULL(RequiredQty,  0),
               @PrPoCreatedQty = ISNULL(PoCreatedQty, 0)
        FROM PROJ.TBL_PURCHASE_REQUEST_LINE WHERE PrLineId = @PrLineId;

        IF @PoLineId IS NOT NULL AND @PoLineId > 0
            SELECT @OldPoQty = ISNULL(OrderedQty, 0)
            FROM PROJ.TBL_PURCHASE_ORDER_LINE
            WHERE PoLineId = @PoLineId AND PrLineId = @PrLineId;

        DECLARE @PrBalance DECIMAL(18,4) = @PrRequiredQty - (@PrPoCreatedQty - @OldPoQty);
        DECLARE @ErrMsg    NVARCHAR(300);
        IF @OrderedQty > @PrBalance
        BEGIN
            SET @ErrMsg = 'PO quantity (' + CAST(@OrderedQty AS NVARCHAR(30))
                        + ') exceeds PR balance (' + CAST(@PrBalance AS NVARCHAR(30)) + ').';
            RAISERROR(@ErrMsg, 16, 1); RETURN;
        END
    END

    DECLARE @LineJobId      NVARCHAR(50);
    DECLARE @LineCategoryId INT;
    SELECT @LineJobId = JobId, @LineCategoryId = ExpenseCategoryId
    FROM PROJ.TBL_PURCHASE_ORDER WHERE PoId = @PoId AND IsActive = 1;

    DECLARE @LineJobCosting BIT = 1, @IsBudgetHeaderLinked BIT = 0;
    IF @LineJobId IS NOT NULL
        SELECT @LineJobCosting      = ISNULL(jt.IsCostingRequired, 1),
               @IsBudgetHeaderLinked = ISNULL(jt.IsBudgetHeaderLinked, 0)
        FROM PROJ.TBL_JOB j JOIN PROJ.TBL_JOBTYPE jt ON jt.JobTypeId = j.JobTypeId
        WHERE j.JobId = @LineJobId;

    -- Budget attribution: a budget line must exist for the cost category — but
    -- ONLY for costed jobs. In-house / non-costed jobs (IsCostingRequired=0) are exempt.
    IF @LineJobId IS NOT NULL AND @LineCategoryId IS NOT NULL AND @LineJobCosting = 1
    BEGIN
        IF NOT EXISTS (
            SELECT 1 FROM PROJ.TBL_JOB_BUDGET
            WHERE JobId = @LineJobId AND CostCategoryId = @LineCategoryId AND IsCurrent = 1)
        BEGIN
            DECLARE @NoBudgetMsg NVARCHAR(400) = 'No approved budget line exists for the selected expense category on this job. Please create a budget line before adding PO lines.';
            RAISERROR(@NoBudgetMsg, 16, 1); RETURN;
        END
    END

    -- Budget-header-linked job: only STOCKABLE items in the PO's expense category (new lines).
    IF (@PoLineId IS NULL OR @PoLineId <= 0) AND @LineJobId IS NOT NULL AND @IsBudgetHeaderLinked = 1
    BEGIN
        IF @LineCategoryId IS NULL
        BEGIN
            RAISERROR('Select an expense category on the PO before adding items for this job type.', 16, 1); RETURN;
        END
        IF NULLIF(@ItemId, 0) IS NULL
        BEGIN
            RAISERROR('Only stockable items in the PO''s budget category can be purchased for this job type.', 16, 1); RETURN;
        END
        DECLARE @ItemStockable BIT, @ItemBudgetCat INT;
        SELECT @ItemStockable = ISNULL(IsStockable, 0), @ItemBudgetCat = BudgetCategoryId
        FROM PROJ.TBL_ITEM WHERE ItemId = @ItemId;
        IF @ItemStockable <> 1
        BEGIN
            RAISERROR('Only stockable items can be purchased under this job type.', 16, 1); RETURN;
        END
        IF ISNULL(@ItemBudgetCat, -1) <> @LineCategoryId
        BEGIN
            RAISERROR('This item does not belong to the PO''s budget category and cannot be added.', 16, 1); RETURN;
        END
    END

    IF @PoLineId IS NULL OR @PoLineId <= 0
    BEGIN
        DECLARE @LineNum INT;
        SELECT @LineNum = ISNULL(MAX(LineNum), 0) + 1
        FROM PROJ.TBL_PURCHASE_ORDER_LINE WHERE PoId = @PoId AND IsActive = 1;

        INSERT INTO PROJ.TBL_PURCHASE_ORDER_LINE
            (PoId, LineNum, PrLineId, ItemId, ItemCode, ItemDesc,
             OrderedQty, UomId, UomName, UnitPrice, TaxPct, Remarks, CreatedBy)
        VALUES
            (@PoId, @LineNum, NULLIF(@PrLineId, 0), NULLIF(@ItemId, 0),
             @ItemCode, @ItemDesc, @OrderedQty, @UomId, @UomName,
             ISNULL(@UnitPrice, 0), ISNULL(@TaxPct, 0), @Remarks, @CreatedBy);

        IF @PrLineId IS NOT NULL AND @PrLineId > 0
        BEGIN
            DECLARE @BomDetailId_I INT;
            SELECT @BomDetailId_I = BomDetailId FROM PROJ.TBL_PURCHASE_REQUEST_LINE WHERE PrLineId = @PrLineId;

            UPDATE PROJ.TBL_PURCHASE_REQUEST_LINE
            SET PoCreatedQty = ISNULL(PoCreatedQty, 0) + @OrderedQty
            WHERE PrLineId = @PrLineId;

            EXEC PROJ.sp_RecalcPrStatus @PrLineId, @CreatedBy;

            IF @BomDetailId_I IS NOT NULL
                UPDATE PROJ.TBL_BOM_DETAILS
                SET PoCreatedQty = ISNULL(PoCreatedQty, 0) + @OrderedQty,
                    BomStatus    = CASE
                        WHEN BomReceivedQty >= BomRequestedQty                                 THEN 'FullyReceived'
                        WHEN BomReceivedQty  > 0                                               THEN 'PartialReceived'
                        WHEN (ISNULL(PoCreatedQty,0) + @OrderedQty) >= BomRequestedQty        THEN 'PORaised'
                        WHEN (ISNULL(PoCreatedQty,0) + @OrderedQty)  > 0                      THEN 'POPartial'
                        WHEN PrCreatedQty >= BomRequestedQty                                   THEN 'PRRaised'
                        WHEN PrCreatedQty  > 0                                                 THEN 'PRPartial'
                        ELSE 'Pending'
                    END
                WHERE BomId = @BomDetailId_I;
        END

        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        DECLARE @OldOrderedQty DECIMAL(18,4) = 0;
        DECLARE @OldPrLineId   INT           = NULL;

        SELECT @OldOrderedQty = OrderedQty, @OldPrLineId = PrLineId
        FROM PROJ.TBL_PURCHASE_ORDER_LINE WHERE PoLineId = @PoLineId;

        UPDATE PROJ.TBL_PURCHASE_ORDER_LINE
        SET OrderedQty   = @OrderedQty,
            UomId        = NULLIF(@UomId, 0),
            UomName      = @UomName,
            UnitPrice    = ISNULL(@UnitPrice, 0),
            TaxPct       = ISNULL(@TaxPct, 0),
            Remarks      = @Remarks,
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE PoLineId = @PoLineId;

        IF @OldPrLineId IS NOT NULL AND @OldPrLineId > 0
        BEGIN
            DECLARE @BomDetailId_U INT;
            SELECT @BomDetailId_U = BomDetailId FROM PROJ.TBL_PURCHASE_REQUEST_LINE WHERE PrLineId = @OldPrLineId;

            UPDATE PROJ.TBL_PURCHASE_REQUEST_LINE
            SET PoCreatedQty = ISNULL(PoCreatedQty, 0) - @OldOrderedQty + @OrderedQty
            WHERE PrLineId = @OldPrLineId;

            EXEC PROJ.sp_RecalcPrStatus @OldPrLineId, @ModifiedBy;

            IF @BomDetailId_U IS NOT NULL
                UPDATE PROJ.TBL_BOM_DETAILS
                SET PoCreatedQty = ISNULL(PoCreatedQty, 0) - @OldOrderedQty + @OrderedQty,
                    BomStatus    = CASE
                        WHEN BomReceivedQty >= BomRequestedQty                                                   THEN 'FullyReceived'
                        WHEN BomReceivedQty  > 0                                                                 THEN 'PartialReceived'
                        WHEN (ISNULL(PoCreatedQty,0) - @OldOrderedQty + @OrderedQty) >= BomRequestedQty         THEN 'PORaised'
                        WHEN (ISNULL(PoCreatedQty,0) - @OldOrderedQty + @OrderedQty)  > 0                       THEN 'POPartial'
                        WHEN PrCreatedQty >= BomRequestedQty                                                     THEN 'PRRaised'
                        WHEN PrCreatedQty  > 0                                                                   THEN 'PRPartial'
                        ELSE 'Pending'
                    END
                WHERE BomId = @BomDetailId_U;
        END

        SELECT CAST(@PoLineId AS NVARCHAR(20));
    END

    UPDATE PROJ.TBL_PURCHASE_ORDER
    SET TotalAmount = (
        SELECT ISNULL(SUM(OrderedQty * UnitPrice), 0)
        FROM PROJ.TBL_PURCHASE_ORDER_LINE WHERE PoId = @PoId AND IsActive = 1
    )
    WHERE PoId = @PoId;
END
GO

IF OBJECT_ID(N'[proj].[sp_SetPOMeta]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetPOMeta];
GO

CREATE PROCEDURE proj.sp_SetPOMeta
    @PoId            INT,
    @IsWarranty      BIT           = 0,
    @IsPreInspection BIT           = 0,
    @IsShipping      BIT           = 0,
    @IsCOO           BIT           = 0,
    @IsDrawing       BIT           = 0,
    @IsMTC           BIT           = 0,
    @IsQtn           BIT           = 0,
    @IsOthers        BIT           = 0,
    @IsNote1         BIT           = 0,
    @IsNote2         BIT           = 0,
    @IsNote3         BIT           = 0,
    @VendorQuoteDate DATE          = NULL,
    @ModifiedBy      NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- Update main table
    UPDATE proj.TBL_PURCHASE_ORDER
    SET VendorQuoteDate = @VendorQuoteDate,
        ModifiedBy      = @ModifiedBy,
        ModifiedDate    = GETDATE()
    WHERE PoId = @PoId AND IsActive = 1;

    -- Update meta flags
    IF EXISTS (SELECT 1 FROM proj.TBL_PURCHASE_ORDER_META WHERE PoId = @PoId)
        UPDATE proj.TBL_PURCHASE_ORDER_META SET
            IsWarranty      = @IsWarranty,
            IsPreInspection = @IsPreInspection,
            IsShipping      = @IsShipping,
            IsCOO           = @IsCOO,
            IsDrawing       = @IsDrawing,
            IsMTC           = @IsMTC,
            IsQtn           = @IsQtn,
            IsOthers        = @IsOthers,
            IsNote1         = @IsNote1,
            IsNote2         = @IsNote2,
            IsNote3         = @IsNote3,
            VendorQtnDate   = @VendorQuoteDate,   -- keep in sync for backward compat
            ModifiedBy      = @ModifiedBy,
            ModifiedDate    = GETDATE()
        WHERE PoId = @PoId;
    ELSE
        INSERT INTO proj.TBL_PURCHASE_ORDER_META
            (PoId, IsWarranty, IsPreInspection, IsShipping, IsCOO, IsDrawing,
             IsMTC, IsQtn, IsOthers, IsNote1, IsNote2, IsNote3,
             VendorQtnDate, CreatedBy, CreatedDate)
        VALUES
            (@PoId, @IsWarranty, @IsPreInspection, @IsShipping, @IsCOO, @IsDrawing,
             @IsMTC, @IsQtn, @IsOthers, @IsNote1, @IsNote2, @IsNote3,
             @VendorQuoteDate, @ModifiedBy, GETDATE());

    SELECT CAST(@PoId AS NVARCHAR(20));
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetPR]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetPR];
GO

CREATE     PROCEDURE proj.sp_SetPR
    @PrId        INT           = 0,
    @PrDate      DATE          = NULL,
    @RequestedBy NVARCHAR(100) = NULL,
    @BomId       INT           = NULL,
    @JobId       NVARCHAR(50)  = NULL,
    @Priority    NVARCHAR(20)  = NULL,
    @Notes       NVARCHAR(MAX) = NULL,
    @CreatedBy   NVARCHAR(100) = NULL,
    @ModifiedBy  NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    -- Block transactional saves on a closed job (Freezed/Completed/Cancelled).
    IF @JobId IS NOT NULL EXEC proj.sp_AssertJobOpen @JobId;


    IF @PrId = 0
    BEGIN
        -- Mandatory field validation
        IF NULLIF(@CreatedBy, '') IS NULL RAISERROR('CreatedBy is required.',  16, 1);
        IF NULLIF(@JobId, '')     IS NULL RAISERROR('Job is required.',        16, 1);
        IF @@ERROR <> 0 RETURN;

        -- Job status guard (new records only)
        DECLARE @IsClosed BIT = 0, @StatusName NVARCHAR(50) = '';
        SELECT @IsClosed = js.IsClosed, @StatusName = js.StatusName
        FROM   proj.TBL_JOB j
        JOIN   proj.TBL_JOB_STATUS js ON js.JobStatusId = j.JobStatusId
        WHERE  j.JobId = @JobId;
        IF @IsClosed = 1
        BEGIN
            DECLARE @ErrMsg NVARCHAR(200) = 'Job ' + @JobId + ' is ' + @StatusName + '. Revise the job to create new transactions.';
            RAISERROR('%s', 16, 1, @ErrMsg);
            RETURN;
        END

        DECLARE @NumResult TABLE (DocNumber NVARCHAR(50), NewSeries INT);
        INSERT INTO @NumResult EXEC proj.sp_GetNextDocNumber 'PR';
        DECLARE @PrNumber NVARCHAR(50);
        SELECT @PrNumber = DocNumber FROM @NumResult;

        INSERT INTO proj.TBL_PURCHASE_REQUEST
            (PrNumber, PrDate, RequestedBy, BomId, JobId, Priority, Status, Notes, IsActive, CreatedBy, CreatedDate)
        VALUES
            (@PrNumber, ISNULL(@PrDate, CAST(GETDATE() AS DATE)), @RequestedBy, @BomId,
             @JobId, @Priority, N'Draft', @Notes, 1, @CreatedBy, GETDATE());

        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_PURCHASE_REQUEST SET
            PrDate       = ISNULL(@PrDate, PrDate),
            RequestedBy  = ISNULL(@RequestedBy, RequestedBy),
            BomId        = @BomId,
            JobId        = @JobId,
            Priority     = @Priority,
            Notes        = @Notes,
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE PrId = @PrId;
        SELECT CAST(@PrId AS NVARCHAR(20));
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetPRLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetPRLine];
GO

CREATE PROCEDURE PROJ.sp_SetPRLine
    @PrLineId     INT           = 0,
    @PrId         INT,
    @ItemId       INT           = NULL,
    @ItemCode     NVARCHAR(50)  = NULL,
    @ItemDesc     NVARCHAR(300) = NULL,
    @RequiredQty  DECIMAL(18,4) = 1,
    @UomId        INT           = NULL,
    @UomName      NVARCHAR(50)  = NULL,
    @RequiredDate DATE          = NULL,
    @EstUnitPrice DECIMAL(18,4) = NULL,
    @Remarks      NVARCHAR(300) = NULL,
    @BomDetailId  INT           = NULL,
    @CreatedBy    NVARCHAR(100) = NULL,
    @ModifiedBy   NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NULLIF(@PrId, 0)        IS NULL RAISERROR('PrId is required.',                            16, 1);
    IF ISNULL(@RequiredQty, 0) <= 0    RAISERROR('Required quantity must be greater than zero.', 16, 1);
    IF @@ERROR <> 0 RETURN;

    DECLARE @PrStatus NVARCHAR(30);
    SELECT @PrStatus = Status FROM proj.TBL_PURCHASE_REQUEST WHERE PrId = @PrId AND IsActive = 1;
    IF @PrStatus IS NULL BEGIN RAISERROR('Purchase Request not found or is inactive.', 16, 1); RETURN; END
    IF @PrStatus <> 'Draft'
    BEGIN
        DECLARE @PsMsg NVARCHAR(200) = 'PR lines can only be added or edited when the PR is in Draft status. Current status: ' + @PrStatus;
        RAISERROR(@PsMsg, 16, 1); RETURN;
    END

    IF @PrLineId IS NULL OR @PrLineId <= 0
    BEGIN
        IF NULLIF(@CreatedBy, '') IS NULL RAISERROR('CreatedBy is required.', 16, 1);
        IF @@ERROR <> 0 RETURN;
    END

    -- ── BOM balance guard ─────────────────────────────────────────────────
    IF @BomDetailId IS NOT NULL AND @BomDetailId > 0
    BEGIN
        DECLARE @BomRequestedQty DECIMAL(18,4) = 0;
        DECLARE @BomPrCreatedQty DECIMAL(18,4) = 0;
        DECLARE @OldBomQty       DECIMAL(18,4) = 0;

        SELECT @BomRequestedQty = ISNULL(BomRequestedQty, 0),
               @BomPrCreatedQty = ISNULL(PrCreatedQty,    0)
        FROM PROJ.TBL_BOM_DETAILS WHERE BomId = @BomDetailId;

        IF @PrLineId IS NOT NULL AND @PrLineId > 0
            SELECT @OldBomQty = ISNULL(RequiredQty, 0)
            FROM PROJ.TBL_PURCHASE_REQUEST_LINE
            WHERE PrLineId = @PrLineId AND BomDetailId = @BomDetailId;

        DECLARE @BomBalance DECIMAL(18,4) = @BomRequestedQty - (@BomPrCreatedQty - @OldBomQty);
        DECLARE @ErrMsg NVARCHAR(300);

        IF @RequiredQty > @BomBalance
        BEGIN
            SET @ErrMsg = 'PR quantity (' + CAST(@RequiredQty AS NVARCHAR(30))
                        + ') exceeds BOM balance (' + CAST(@BomBalance AS NVARCHAR(30)) + ').';
            RAISERROR(@ErrMsg, 16, 1); RETURN;
        END
    END

    IF @PrLineId IS NULL OR @PrLineId <= 0
    BEGIN
        -- ── INSERT ────────────────────────────────────────────────────────
        DECLARE @LineNum INT;
        SELECT @LineNum = ISNULL(MAX(LineNum), 0) + 1
        FROM PROJ.TBL_PURCHASE_REQUEST_LINE WHERE PrId=@PrId AND IsActive=1;

        INSERT INTO PROJ.TBL_PURCHASE_REQUEST_LINE
            (PrId, LineNum, ItemId, ItemCode, ItemDesc, RequiredQty, UomId, UomName,
             RequiredDate, EstUnitPrice, Remarks, BomDetailId, CreatedBy)
        VALUES
            (@PrId, @LineNum, NULLIF(@ItemId,0), @ItemCode, @ItemDesc, @RequiredQty,
             NULLIF(@UomId,0), @UomName, @RequiredDate, @EstUnitPrice, @Remarks,
             NULLIF(@BomDetailId,0), @CreatedBy);

        -- ── Update BOM detail: PrCreatedQty AND BomStatus ────────────────
        IF @BomDetailId IS NOT NULL AND @BomDetailId > 0
            UPDATE PROJ.TBL_BOM_DETAILS
            SET PrCreatedQty = ISNULL(PrCreatedQty, 0) + @RequiredQty,
                BomStatus    = CASE
                    WHEN BomReceivedQty >= BomRequestedQty                                THEN 'FullyReceived'
                    WHEN BomReceivedQty  > 0                                              THEN 'PartialReceived'
                    WHEN PoCreatedQty   >= BomRequestedQty                                THEN 'PORaised'
                    WHEN PoCreatedQty    > 0                                              THEN 'POPartial'
                    WHEN (ISNULL(PrCreatedQty,0) + @RequiredQty) >= BomRequestedQty      THEN 'PRRaised'
                    WHEN (ISNULL(PrCreatedQty,0) + @RequiredQty)  > 0                    THEN 'PRPartial'
                    ELSE 'Pending'
                END
            WHERE BomId = @BomDetailId;

        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        -- ── UPDATE ────────────────────────────────────────────────────────
        DECLARE @OldQty              DECIMAL(18,4) = 0;
        DECLARE @OldBomDetailId      INT           = NULL;
        DECLARE @CurrentPoCreatedQty DECIMAL(18,4) = 0;

        SELECT @OldQty               = RequiredQty,
               @OldBomDetailId      = BomDetailId,
               @CurrentPoCreatedQty  = ISNULL(PoCreatedQty, 0)
        FROM PROJ.TBL_PURCHASE_REQUEST_LINE
        WHERE PrLineId = @PrLineId;

        -- ── Guard: cannot reduce below what is already on PO ─────────────
        IF @RequiredQty < @CurrentPoCreatedQty
        BEGIN
            DECLARE @PoQtyMsg NVARCHAR(300) =
                'Cannot reduce quantity below the amount already ordered via Purchase Orders ('
                + CAST(@CurrentPoCreatedQty AS NVARCHAR(30)) + '). '
                + 'Close or amend the PO lines first.';
            RAISERROR(@PoQtyMsg, 16, 1); RETURN;
        END

        -- ── Update PR line (including BomDetailId in case it changed) ─────
        UPDATE PROJ.TBL_PURCHASE_REQUEST_LINE
        SET RequiredQty  = @RequiredQty,
            UomId        = NULLIF(@UomId, 0),
            UomName      = @UomName,
            RequiredDate = @RequiredDate,
            EstUnitPrice = @EstUnitPrice,
            Remarks      = @Remarks,
            BomDetailId  = NULLIF(@BomDetailId, 0),
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE PrLineId = @PrLineId;

        -- ── BOM qty / status recalc ───────────────────────────────────────
        DECLARE @NewBomDetailId INT = NULLIF(@BomDetailId, 0);

        IF @OldBomDetailId IS NOT NULL AND @OldBomDetailId > 0
           AND (@NewBomDetailId IS NULL OR @NewBomDetailId <> @OldBomDetailId)
        BEGIN
            -- BOM has changed (or cleared): subtract @OldQty from the OLD BOM
            UPDATE PROJ.TBL_BOM_DETAILS
            SET PrCreatedQty = CASE
                                   WHEN ISNULL(PrCreatedQty,0) - @OldQty < 0 THEN 0
                                   ELSE ISNULL(PrCreatedQty,0) - @OldQty
                               END,
                BomStatus    = CASE
                    WHEN BomReceivedQty >= BomRequestedQty                                                          THEN 'FullyReceived'
                    WHEN BomReceivedQty  > 0                                                                        THEN 'PartialReceived'
                    WHEN PoCreatedQty   >= BomRequestedQty                                                          THEN 'PORaised'
                    WHEN PoCreatedQty    > 0                                                                        THEN 'POPartial'
                    WHEN (CASE WHEN ISNULL(PrCreatedQty,0)-@OldQty < 0 THEN 0 ELSE ISNULL(PrCreatedQty,0)-@OldQty END) >= BomRequestedQty THEN 'PRRaised'
                    WHEN (CASE WHEN ISNULL(PrCreatedQty,0)-@OldQty < 0 THEN 0 ELSE ISNULL(PrCreatedQty,0)-@OldQty END)  > 0              THEN 'PRPartial'
                    ELSE 'Pending'
                END
            WHERE BomId = @OldBomDetailId;
        END

        IF @NewBomDetailId IS NOT NULL AND @NewBomDetailId > 0
           AND (@OldBomDetailId IS NULL OR @OldBomDetailId <> @NewBomDetailId)
        BEGIN
            -- BOM has changed: add @RequiredQty to the NEW BOM
            UPDATE PROJ.TBL_BOM_DETAILS
            SET PrCreatedQty = ISNULL(PrCreatedQty, 0) + @RequiredQty,
                BomStatus    = CASE
                    WHEN BomReceivedQty >= BomRequestedQty                                   THEN 'FullyReceived'
                    WHEN BomReceivedQty  > 0                                                 THEN 'PartialReceived'
                    WHEN PoCreatedQty   >= BomRequestedQty                                   THEN 'PORaised'
                    WHEN PoCreatedQty    > 0                                                 THEN 'POPartial'
                    WHEN (ISNULL(PrCreatedQty,0) + @RequiredQty) >= BomRequestedQty         THEN 'PRRaised'
                    WHEN (ISNULL(PrCreatedQty,0) + @RequiredQty)  > 0                       THEN 'PRPartial'
                    ELSE 'Pending'
                END
            WHERE BomId = @NewBomDetailId;
        END

        IF @OldBomDetailId IS NOT NULL AND @OldBomDetailId > 0
           AND @NewBomDetailId IS NOT NULL AND @NewBomDetailId = @OldBomDetailId
        BEGIN
            -- Same BOM: delta update
            UPDATE PROJ.TBL_BOM_DETAILS
            SET PrCreatedQty = ISNULL(PrCreatedQty, 0) - @OldQty + @RequiredQty,
                BomStatus    = CASE
                    WHEN BomReceivedQty >= BomRequestedQty                                          THEN 'FullyReceived'
                    WHEN BomReceivedQty  > 0                                                        THEN 'PartialReceived'
                    WHEN PoCreatedQty   >= BomRequestedQty                                          THEN 'PORaised'
                    WHEN PoCreatedQty    > 0                                                        THEN 'POPartial'
                    WHEN (ISNULL(PrCreatedQty,0) - @OldQty + @RequiredQty) >= BomRequestedQty      THEN 'PRRaised'
                    WHEN (ISNULL(PrCreatedQty,0) - @OldQty + @RequiredQty)  > 0                    THEN 'PRPartial'
                    ELSE 'Pending'
                END
            WHERE BomId = @OldBomDetailId;
        END

        -- ── Recalc line status now that RequiredQty may have changed ──────
        EXEC proj.sp_RecalcPrStatus @PrLineId = @PrLineId, @ChangedBy = @ModifiedBy;

        SELECT CAST(@PrLineId AS NVARCHAR(20));
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_SetPvAllocation]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetPvAllocation];
GO

CREATE PROCEDURE proj.sp_SetPvAllocation
    @AllocationId      INT           = 0,
    @PvId              INT,
    @SupplierInvoiceId INT,
    @AllocatedAmount   DECIMAL(18,2),   -- received from frontend in invoice currency
    @PoId              INT           = NULL,
    @CreatedBy         NVARCHAR(100) = NULL,
    @ModifiedBy        NVARCHAR(100) = NULL,
    @Reason            NVARCHAR(500) = NULL,
    @PasswordHash      NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @PvStatus    NVARCHAR(20), @PvSupplier INT,
            @AmountPaid  DECIMAL(18,2), @ExchangeRate DECIMAL(18,6);

    SELECT @PvStatus     = Status,        @PvSupplier   = SupplierId,
           @AmountPaid   = AmountPaid,    @ExchangeRate = ISNULL(NULLIF(ExchangeRate,0),1)
    FROM   proj.TBL_PAYMENT_VOUCHER WHERE  PvId = @PvId AND IsActive = 1;

    IF @PvStatus IS NULL                 BEGIN RAISERROR('Payment voucher not found.',16,1); RETURN; END
    IF @PvStatus <> 'Approved'           BEGIN RAISERROR('The payment voucher must be Approved before registering it against invoices.',16,1); RETURN; END
    IF ISNULL(@AllocatedAmount,0) <= 0   BEGIN RAISERROR('Allocated amount must be greater than zero.',16,1); RETURN; END
    IF NULLIF(LTRIM(RTRIM(ISNULL(@Reason,''))),'') IS NULL
                                         BEGIN RAISERROR('A reason is required to modify an allocation on an approved payment voucher.',16,1); RETURN; END
    IF NULLIF(@PasswordHash,'') IS NULL  BEGIN RAISERROR('Password is required.',16,1); RETURN; END

    DECLARE @ActionBy NVARCHAR(100) = ISNULL(@ModifiedBy, @CreatedBy);
    IF NOT EXISTS (
        SELECT 1 FROM proj.TBL_USER_ROLES ur
        JOIN proj.TBL_ROLE_SECRET rs ON rs.RoleId = ur.RoleId
        JOIN proj.TBL_USERS u  ON u.UserId   = ur.UserId
        WHERE u.Username = @ActionBy AND rs.SecretKey = 'PV_REVISE' AND rs.SecretValueHash = @PasswordHash
    )
        BEGIN RAISERROR('Incorrect password. You do not have permission to modify allocations on this payment voucher.',16,1); RETURN; END

    DECLARE @InvSupplier     INT,
            @InvStatus       NVARCHAR(30),
            @InvTotal        DECIMAL(18,2),
            @InvExchangeRate DECIMAL(18,6);

    SELECT @InvSupplier     = SupplierId,
           @InvStatus       = Status,
           @InvTotal        = TotalAmount,
           @InvExchangeRate = ISNULL(NULLIF(ExchangeRate,0),1)
    FROM   proj.TBL_SUPPLIER_INVOICE
    WHERE  SupplierInvoiceId = @SupplierInvoiceId AND IsActive = 1;

    IF @InvSupplier IS NULL              BEGIN RAISERROR('Supplier invoice not found.',16,1); RETURN; END
    IF @InvSupplier <> @PvSupplier       BEGIN RAISERROR('Invoice belongs to a different supplier.',16,1); RETURN; END
    IF @InvStatus <> 'Approved'          BEGIN RAISERROR('Only Approved supplier invoices can be paid.',16,1); RETURN; END

    IF @PoId IS NOT NULL
    BEGIN
        IF NOT EXISTS (
            SELECT 1 FROM proj.TBL_SUPPLIER_INVOICE_LINE sil
            JOIN proj.TBL_PURCHASE_ORDER_LINE pol ON pol.PoLineId = sil.PoLineId
            WHERE sil.SupplierInvoiceId = @SupplierInvoiceId AND sil.IsActive = 1
              AND pol.PoId = @PoId
        )
            BEGIN RAISERROR('Selected PO is not linked to this supplier invoice.',16,1); RETURN; END
    END

    DECLARE @ExistingId INT;
    SELECT @ExistingId = AllocationId
    FROM   proj.TBL_PAYMENT_VOUCHER_ALLOCATION
    WHERE  PvId = @PvId AND SupplierInvoiceId = @SupplierInvoiceId
      AND  ISNULL(PoId, 0) = ISNULL(@PoId, 0) AND IsActive = 1;

    -- Convert incoming invoice-currency amount to base for storage
    DECLARE @AllocatedAmountBase DECIMAL(18,4) = @AllocatedAmount * @InvExchangeRate;

    -- Outstanding in base: invoice total base minus other approved PV allocations (base) minus DN credits (base)
    DECLARE @PaidByOthers DECIMAL(18,4);
    SELECT @PaidByOthers = ISNULL(SUM(a.AllocatedAmount),0)
    FROM   proj.TBL_PAYMENT_VOUCHER_ALLOCATION a
    JOIN   proj.TBL_PAYMENT_VOUCHER pv ON pv.PvId = a.PvId
    WHERE  a.SupplierInvoiceId = @SupplierInvoiceId
      AND  a.IsActive = 1
      AND  pv.Status = 'Approved' AND pv.IsActive = 1
      AND  a.AllocationId <> ISNULL(@ExistingId, 0);

    DECLARE @DnCredits DECIMAL(18,4);
    SELECT @DnCredits = ISNULL(SUM(a.AllocatedAmount),0)
    FROM   proj.TBL_DEBIT_NOTE_ALLOCATION a
    JOIN   proj.TBL_DEBIT_NOTE dn ON dn.DnId = a.DnId
    WHERE  a.SupplierInvoiceId = @SupplierInvoiceId
      AND  a.IsActive = 1
      AND  dn.Status = 'Approved' AND dn.IsActive = 1;

    DECLARE @Outstanding DECIMAL(18,4) = @InvTotal * @InvExchangeRate - @PaidByOthers - @DnCredits;
    IF @AllocatedAmountBase > @Outstanding
    BEGIN
        DECLARE @m1 NVARCHAR(400) = 'Allocation (' + CAST(@AllocatedAmount AS NVARCHAR(30)) +
            ') exceeds invoice outstanding (' + CAST(ROUND(@Outstanding / @InvExchangeRate, 2) AS NVARCHAR(30)) + ').';
        RAISERROR(@m1,16,1); RETURN;
    END

    -- PV balance: all base allocations on this PV must not exceed AmountPaid × PV rate
    DECLARE @OtherAlloc DECIMAL(18,4);
    SELECT @OtherAlloc = ISNULL(SUM(AllocatedAmount),0)
    FROM   proj.TBL_PAYMENT_VOUCHER_ALLOCATION
    WHERE  PvId = @PvId AND IsActive = 1
      AND  AllocationId <> ISNULL(@ExistingId, 0);

    DECLARE @PvAvailable DECIMAL(18,4) = @AmountPaid * @ExchangeRate;
    IF (@OtherAlloc + @AllocatedAmountBase) > @PvAvailable
    BEGIN
        DECLARE @m2 NVARCHAR(400) = 'Total allocations (' +
            CAST(ROUND((@OtherAlloc + @AllocatedAmountBase) / @ExchangeRate, 2) AS NVARCHAR(30)) +
            ') would exceed the PV available balance (' + CAST(@AmountPaid AS NVARCHAR(30)) + ').';
        RAISERROR(@m2,16,1); RETURN;
    END

    IF @ExistingId IS NOT NULL
        UPDATE proj.TBL_PAYMENT_VOUCHER_ALLOCATION
        SET    AllocatedAmount = @AllocatedAmountBase, PoId = @PoId, Reason = @Reason,
               ModifiedBy = @ActionBy, ModifiedDate = GETDATE()
        WHERE  AllocationId = @ExistingId;
    ELSE
        INSERT INTO proj.TBL_PAYMENT_VOUCHER_ALLOCATION
            (PvId, SupplierInvoiceId, AllocatedAmount, PoId, Reason, CreatedBy)
        VALUES (@PvId, @SupplierInvoiceId, @AllocatedAmountBase, @PoId, @Reason, @CreatedBy);

    -- Refresh PV header: sum of base allocations ÷ PV rate = allocated in PV's own currency
    UPDATE proj.TBL_PAYMENT_VOUCHER
    SET    AllocatedAmount = (
               SELECT ISNULL(SUM(AllocatedAmount),0) / @ExchangeRate
               FROM   proj.TBL_PAYMENT_VOUCHER_ALLOCATION
               WHERE  PvId = @PvId AND IsActive = 1
           ),
           ModifiedDate = GETDATE()
    WHERE  PvId = @PvId;

    SELECT @PvId AS PvId;
END
GO

IF OBJECT_ID(N'[proj].[sp_SetReceiptVoucher]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetReceiptVoucher];
GO

-- Fix sp_SetReceiptVoucher: convert @AmountReceived to base before comparing against base allocations
CREATE PROCEDURE proj.sp_SetReceiptVoucher
    @RvId           INT            = 0,
    @RvDate         DATE           = NULL,
    @CustomerId     INT,
    @CurrencyId     INT,
    @ExchangeRate   DECIMAL(18,6)  = 1,
    @AmountReceived DECIMAL(18,2)  = 0,
    @PaymentMode    NVARCHAR(30)   = NULL,
    @ReferenceNo    NVARCHAR(100)  = NULL,
    @ReferenceDate  DATE           = NULL,
    @BankName       NVARCHAR(150)  = NULL,
    @Notes          NVARCHAR(500)  = NULL,
    @CreatedBy      NVARCHAR(100)  = NULL,
    @ModifiedBy     NVARCHAR(100)  = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NULLIF(@CustomerId,  0) IS NULL  BEGIN RAISERROR('Customer is required.',              16, 1); RETURN; END
    IF NULLIF(@CurrencyId,  0) IS NULL  BEGIN RAISERROR('Currency is required.',              16, 1); RETURN; END
    IF ISNULL(@AmountReceived, 0) <= 0  BEGIN RAISERROR('Amount received must be greater than zero.', 16, 1); RETURN; END

    IF UPPER(LTRIM(RTRIM(ISNULL(@PaymentMode,'')))) = 'CHEQUE'
       AND NULLIF(LTRIM(RTRIM(ISNULL(@ReferenceNo,''))), '') IS NULL
    BEGIN
        RAISERROR('Cheque No is required when Payment Mode is Cheque.', 16, 1); RETURN;
    END

    IF @RvId IS NULL OR @RvId <= 0
    BEGIN
        IF NULLIF(@CreatedBy, '') IS NULL BEGIN RAISERROR('CreatedBy is required.', 16, 1); RETURN; END

        DECLARE @NumResult TABLE (DocNumber NVARCHAR(50), NewSeries INT);
        INSERT INTO @NumResult EXEC proj.sp_GetNextDocNumber 'RV';
        DECLARE @RvNo NVARCHAR(50); SELECT @RvNo = DocNumber FROM @NumResult;

        INSERT INTO proj.TBL_RECEIPT_VOUCHER
            (RvNumber, RvDate, CustomerId, CurrencyId, ExchangeRate, AmountReceived,
             PaymentMode, ReferenceNo, ReferenceDate, BankName, Notes, Status, CreatedBy)
        VALUES
            (@RvNo, ISNULL(@RvDate, CAST(GETDATE() AS DATE)), @CustomerId, @CurrencyId,
             ISNULL(@ExchangeRate,1), @AmountReceived,
             NULLIF(@PaymentMode,''), @ReferenceNo, @ReferenceDate,
             @BankName, @Notes, 'Draft', @CreatedBy);

        SELECT CAST(SCOPE_IDENTITY() AS INT) AS NewId, @RvNo AS RvNumber;
    END
    ELSE
    BEGIN
        IF EXISTS (SELECT 1 FROM proj.TBL_RECEIPT_VOUCHER WHERE RvId = @RvId AND Status <> 'Draft')
        BEGIN RAISERROR('Only Draft receipt vouchers can be edited.', 16, 1); RETURN; END

        -- AllocatedAmount is now BASE; convert @AmountReceived to base before comparing
        IF @AmountReceived * ISNULL(NULLIF(@ExchangeRate, 0), 1) <
           (SELECT ISNULL(SUM(AllocatedAmount), 0) FROM proj.TBL_RECEIPT_VOUCHER_ALLOCATION WHERE RvId = @RvId AND IsActive = 1)
        BEGIN RAISERROR('Amount received cannot be less than the amount already allocated. Remove allocations first.', 16, 1); RETURN; END

        UPDATE proj.TBL_RECEIPT_VOUCHER
        SET    RvDate          = ISNULL(@RvDate, RvDate),
               CustomerId      = @CustomerId,
               CurrencyId      = @CurrencyId,
               ExchangeRate    = ISNULL(@ExchangeRate, ExchangeRate),
               AmountReceived  = @AmountReceived,
               PaymentMode     = NULLIF(@PaymentMode,''),
               ReferenceNo     = @ReferenceNo,
               ReferenceDate   = @ReferenceDate,
               BankName        = @BankName,
               Notes           = @Notes,
               ModifiedBy      = @ModifiedBy,
               ModifiedDate    = GETDATE()
        WHERE  RvId = @RvId AND IsActive = 1;

        SELECT CAST(@RvId AS INT) AS NewId, RvNumber FROM proj.TBL_RECEIPT_VOUCHER WHERE RvId = @RvId;
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_SetRole]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetRole];
GO

-- sp_SetRole: add @IsEngineerRole param
CREATE PROCEDURE proj.sp_SetRole
    @RoleId          INT            = 0,
    @RoleName        NVARCHAR(100),
    @RoleCode        NVARCHAR(50),
    @Description     NVARCHAR(500)  = NULL,
    @IsActive        BIT            = 1,
    @IsEngineerRole  BIT            = 0,
    @CreatedBy       NVARCHAR(50),
    @ModifiedBy      NVARCHAR(50)   = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (SELECT 1 FROM proj.TBL_ROLES WHERE RoleCode=@RoleCode AND RoleId<>@RoleId)
    BEGIN SELECT -1 AS RoleId, N'Role code already exists.' AS ErrorMessage; RETURN; END

    IF EXISTS (SELECT 1 FROM proj.TBL_ROLES WHERE RoleName=@RoleName AND RoleId<>@RoleId)
    BEGIN SELECT -2 AS RoleId, N'Role name already exists.' AS ErrorMessage; RETURN; END

    IF @RoleId = 0
    BEGIN
        INSERT INTO proj.TBL_ROLES
            (RoleName, RoleCode, Description, IsActive, IsEngineerRole, CreatedBy, CreatedDate)
        VALUES
            (@RoleName, @RoleCode, @Description, @IsActive, @IsEngineerRole, @CreatedBy, GETDATE());
        SELECT SCOPE_IDENTITY() AS RoleId, NULL AS ErrorMessage;
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_ROLES SET
            RoleName        = @RoleName,
            RoleCode        = @RoleCode,
            Description     = @Description,
            IsActive        = @IsActive,
            IsEngineerRole  = @IsEngineerRole,
            ModifiedBy      = @ModifiedBy,
            ModifiedDate    = GETDATE()
        WHERE RoleId = @RoleId;
        SELECT @RoleId AS RoleId, NULL AS ErrorMessage;
    END
END
GO

