-- Upsert one role's secret
CREATE   PROCEDURE proj.sp_SetRoleSecret
    @RoleId          INT,
    @SecretKey       NVARCHAR(100),
    @SecretValueHash NVARCHAR(500),
    @ModifiedBy      NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM proj.TBL_ROLE_SECRET WHERE RoleId = @RoleId AND SecretKey = @SecretKey)
        UPDATE proj.TBL_ROLE_SECRET
        SET SecretValueHash = @SecretValueHash,
            ModifiedBy      = @ModifiedBy,
            ModifiedDate    = GETDATE()
        WHERE RoleId = @RoleId AND SecretKey = @SecretKey;
    ELSE
        INSERT INTO proj.TBL_ROLE_SECRET (RoleId, SecretKey, SecretValueHash, ModifiedBy, ModifiedDate)
        VALUES (@RoleId, @SecretKey, @SecretValueHash, @ModifiedBy, GETDATE());
    SELECT 1 AS Success;
END
GO

IF OBJECT_ID(N'[proj].[sp_SetRTV]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetRTV];
GO
CREATE   PROCEDURE proj.sp_SetRTV
    @RtvId        INT           = 0,
    @RtvDate      DATE          = NULL,
    @GrnId        INT           = NULL,
    @SupplierId   INT           = NULL,
    @PoId         INT           = NULL,
    @JobId        NVARCHAR(50)  = NULL,
    @ReturnReason NVARCHAR(500) = NULL,
    @Remarks      NVARCHAR(500) = NULL,
    @CreatedBy    NVARCHAR(100) = NULL,
    @ModifiedBy   NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    -- Block transactional saves on a closed job (Freezed/Completed/Cancelled).
    IF @JobId IS NOT NULL EXEC proj.sp_AssertJobOpen @JobId;
    -- Block transactional saves on a job whose budget is not yet approved.
    IF @JobId IS NOT NULL EXEC proj.sp_AssertBudgetApproved @JobId, N'RTV';

    IF @RtvId IS NULL OR @RtvId <= 0
    BEGIN
        -- Guard: CreatedBy required for new records
        IF NULLIF(@CreatedBy, '') IS NULL
        BEGIN
            RAISERROR('CreatedBy is required when creating an RTV.', 16, 1);
            RETURN;
        END

        DECLARE @RtvNumber NVARCHAR(50);
        DECLARE @nr TABLE (DocNumber NVARCHAR(50), NewSeries INT);
        INSERT INTO @nr EXEC proj.sp_GetNextDocNumber 'RTV';
        SELECT @RtvNumber = DocNumber FROM @nr;

        -- If GrnId supplied on insert, auto-pull Supplier/PO from the GRN
        IF NULLIF(@GrnId, 0) IS NOT NULL
        BEGIN
            SELECT @SupplierId = ISNULL(NULLIF(@SupplierId,0), SupplierId),
                   @PoId       = ISNULL(NULLIF(@PoId,0),       PoId)
            FROM   proj.TBL_GRN_HEADER
            WHERE  GrnId = @GrnId AND IsActive = 1;
        END

        INSERT INTO proj.TBL_RETURN_TO_VENDOR
            (RtvNumber, RtvDate, GrnId, SupplierId, PoId, JobId, ReturnReason, Remarks, CreatedBy)
        VALUES
            (@RtvNumber, ISNULL(@RtvDate, CAST(GETDATE() AS DATE)), NULLIF(@GrnId,0),
             NULLIF(@SupplierId,0), NULLIF(@PoId,0), NULLIF(@JobId,''),
             @ReturnReason, @Remarks, @CreatedBy);

        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        -- When a GRN is being linked for the first time, auto-pull Supplier/PO from it
        IF NULLIF(@GrnId, 0) IS NOT NULL
        BEGIN
            SELECT @SupplierId = ISNULL(NULLIF(@SupplierId,0), SupplierId),
                   @PoId       = ISNULL(NULLIF(@PoId,0),       PoId)
            FROM   proj.TBL_GRN_HEADER
            WHERE  GrnId = @GrnId AND IsActive = 1;
        END

        UPDATE proj.TBL_RETURN_TO_VENDOR SET
            RtvDate      = ISNULL(@RtvDate, RtvDate),
            GrnId        = CASE WHEN GrnId IS NULL THEN NULLIF(@GrnId,0) ELSE GrnId END,
            SupplierId   = CASE
                               WHEN GrnId IS NULL AND NULLIF(@GrnId,0) IS NOT NULL THEN NULLIF(@SupplierId,0)
                               WHEN GrnId IS NULL THEN ISNULL(NULLIF(@SupplierId,0), SupplierId)
                               ELSE SupplierId
                           END,
            PoId         = CASE
                               WHEN GrnId IS NULL AND NULLIF(@GrnId,0) IS NOT NULL THEN NULLIF(@PoId,0)
                               WHEN GrnId IS NULL THEN ISNULL(NULLIF(@PoId,0), PoId)
                               ELSE PoId
                           END,
            ReturnReason = @ReturnReason,
            Remarks      = @Remarks,
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE RtvId = @RtvId AND Status = 'Draft' AND IsActive = 1;

        IF @@ROWCOUNT = 0
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM proj.TBL_RETURN_TO_VENDOR WHERE RtvId = @RtvId AND IsActive = 1)
            BEGIN
                RAISERROR('RTV not found.', 16, 1);
                RETURN;
            END
            ELSE
            BEGIN
                RAISERROR('RTV cannot be edited — it is not in Draft status.', 16, 1);
                RETURN;
            END
        END

        SELECT CAST(@RtvId AS NVARCHAR(20));
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetRTVLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetRTVLine];
GO

CREATE PROCEDURE proj.sp_SetRTVLine
    @RtvLineId    INT            = 0,
    @RtvId        INT,
    @GrnDetailId  INT            = NULL,
    @PoLineId     INT            = NULL,
    @PrLineId     INT            = NULL,
    @ItemId       INT            = NULL,
    @ItemCode     NVARCHAR(50)   = NULL,
    @ItemDesc     NVARCHAR(300)  = NULL,
    @ReturnQty    DECIMAL(18,4)  = 0,
    @UomId        INT            = NULL,
    @UomName      NVARCHAR(50)   = NULL,
    @UnitCost     DECIMAL(18,4)  = 0,
    @ReturnReason NVARCHAR(300)  = NULL,
    @CreatedBy    NVARCHAR(100)  = NULL,
    @ModifiedBy   NVARCHAR(100)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @ParentJobId NVARCHAR(50) = (SELECT JobId FROM proj.TBL_RETURN_TO_VENDOR WHERE RtvId = @RtvId);
    IF @ParentJobId IS NOT NULL EXEC proj.sp_AssertJobOpen @ParentJobId;
    IF @ParentJobId IS NOT NULL EXEC proj.sp_AssertBudgetApproved @ParentJobId, N'RTV';

    IF NOT EXISTS (SELECT 1 FROM proj.TBL_RETURN_TO_VENDOR WHERE RtvId = @RtvId AND Status = 'Draft' AND IsActive = 1) BEGIN RAISERROR('Lines can only be added or edited on a Draft RTV.', 16, 1); RETURN; END

    IF ISNULL(@ReturnQty, 0) <= 0 BEGIN RAISERROR('Return qty must be greater than zero.', 16, 1); RETURN; END
    IF ISNULL(@UnitCost, 0) < 0 BEGIN RAISERROR('Unit cost cannot be negative.', 16, 1); RETURN; END

    IF NULLIF(@GrnDetailId, 0) IS NOT NULL
    BEGIN
        DECLARE @AcceptedQty DECIMAL(18,4);
        SELECT @AcceptedQty = AcceptedQty FROM proj.TBL_GRN_DETAIL WHERE GrnDetailId = @GrnDetailId;
        IF @ReturnQty > ISNULL(@AcceptedQty, 0)
        BEGIN
            DECLARE @LMsg NVARCHAR(300) = 'Return qty (' + CAST(@ReturnQty AS NVARCHAR(30)) +
                ') cannot exceed accepted qty from GRN (' + CAST(ISNULL(@AcceptedQty,0) AS NVARCHAR(30)) + ').';
            RAISERROR(@LMsg, 16, 1); RETURN;
        END
    END

    DECLARE @IsNew BIT = CASE WHEN @RtvLineId IS NULL OR @RtvLineId <= 0 THEN 1 ELSE 0 END;

    IF @IsNew = 1
    BEGIN
        DECLARE @LineNum INT;
        SELECT @LineNum = ISNULL(MAX(LineNum), 0) + 1
        FROM   proj.TBL_RETURN_TO_VENDOR_LINE WHERE RtvId = @RtvId AND IsActive = 1;

        INSERT INTO proj.TBL_RETURN_TO_VENDOR_LINE
            (RtvId, LineNum, GrnDetailId, PoLineId, PrLineId, ItemId, ItemCode, ItemDesc,
             ReturnQty, UomId, UomName, UnitCost, ReturnReason, CreatedBy)
        VALUES
            (@RtvId, @LineNum, NULLIF(@GrnDetailId,0), NULLIF(@PoLineId,0), NULLIF(@PrLineId,0),
             NULLIF(@ItemId,0), @ItemCode, @ItemDesc, @ReturnQty,
             NULLIF(@UomId,0), @UomName, @UnitCost, @ReturnReason, @CreatedBy);

        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_RETURN_TO_VENDOR_LINE SET
            ReturnQty    = @ReturnQty,
            UomId        = NULLIF(@UomId,0),
            UomName      = @UomName,
            UnitCost     = @UnitCost,
            ReturnReason = @ReturnReason,
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE RtvLineId = @RtvLineId AND IsActive = 1
          AND EXISTS (SELECT 1 FROM proj.TBL_RETURN_TO_VENDOR WHERE RtvId = @RtvId AND Status = 'Draft' AND IsActive = 1);

        IF @@ROWCOUNT = 0 BEGIN RAISERROR('Line not found or RTV is no longer in Draft status.', 16, 1); RETURN; END

        SELECT CAST(@RtvLineId AS NVARCHAR(20));
    END

    UPDATE proj.TBL_RETURN_TO_VENDOR
    SET TotalAmount  = (SELECT ISNULL(SUM(LineTotal),0) FROM proj.TBL_RETURN_TO_VENDOR_LINE WHERE RtvId = @RtvId AND IsActive = 1),
        ModifiedDate = GETDATE()
    WHERE RtvId = @RtvId;
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetRvAllocation]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetRvAllocation];
GO

CREATE PROCEDURE proj.sp_SetRvAllocation
    @AllocationId    INT           = 0,
    @RvId            INT,
    @InvoiceId       INT,
    @AllocatedAmount DECIMAL(18,2),   -- received from frontend in invoice currency
    @CreatedBy       NVARCHAR(100) = NULL,
    @ModifiedBy      NVARCHAR(100) = NULL,
    @Reason          NVARCHAR(500) = NULL,
    @PasswordHash    NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @RvStatus       NVARCHAR(20),
            @RvCustomer     INT,
            @AmountReceived DECIMAL(18,2),
            @ExchangeRate   DECIMAL(18,6);

    SELECT @RvStatus       = Status,
           @RvCustomer     = CustomerId,
           @AmountReceived = AmountReceived,
           @ExchangeRate   = ISNULL(NULLIF(ExchangeRate, 0), 1)
    FROM   proj.TBL_RECEIPT_VOUCHER
    WHERE  RvId = @RvId AND IsActive = 1;

    IF @RvStatus IS NULL
        BEGIN RAISERROR('Receipt voucher not found.', 16, 1); RETURN; END
    IF @RvStatus <> 'Approved'
        BEGIN RAISERROR('The receipt voucher must be Approved before registering it against invoices.', 16, 1); RETURN; END
    IF ISNULL(@AllocatedAmount, 0) <= 0
        BEGIN RAISERROR('Allocated amount must be greater than zero.', 16, 1); RETURN; END

    IF NULLIF(LTRIM(RTRIM(ISNULL(@Reason, ''))), '') IS NULL
        BEGIN RAISERROR('A reason is required to modify an allocation on an approved receipt voucher.', 16, 1); RETURN; END
    IF NULLIF(@PasswordHash, '') IS NULL
        BEGIN RAISERROR('Password is required.', 16, 1); RETURN; END

    DECLARE @ActionBy NVARCHAR(100) = ISNULL(@ModifiedBy, @CreatedBy);
    IF NOT EXISTS (
        SELECT 1
        FROM   proj.TBL_USER_ROLES  ur
        JOIN   proj.TBL_ROLE_SECRET rs ON rs.RoleId  = ur.RoleId
        JOIN   proj.TBL_USERS       u  ON u.UserId   = ur.UserId
        WHERE  u.Username         = @ActionBy
          AND  rs.SecretKey       = 'RV_REVISE'
          AND  rs.SecretValueHash = @PasswordHash
    )
        BEGIN RAISERROR('Incorrect password. You do not have permission to modify allocations on this receipt voucher.', 16, 1); RETURN; END

    DECLARE @InvCustomer     INT,
            @InvStatus       NVARCHAR(30),
            @InvTotal        DECIMAL(18,2),
            @InvExchangeRate DECIMAL(18,6);

    SELECT @InvCustomer     = CustomerId,
           @InvStatus       = Status,
           @InvTotal        = TotalAmount,
           @InvExchangeRate = ISNULL(NULLIF(ExchangeRate, 0), 1)
    FROM   proj.TBL_INVOICE
    WHERE  InvoiceId = @InvoiceId AND IsActive = 1;

    IF @InvCustomer IS NULL
        BEGIN RAISERROR('Invoice not found.', 16, 1); RETURN; END
    IF @InvCustomer <> @RvCustomer
        BEGIN RAISERROR('Invoice belongs to a different customer.', 16, 1); RETURN; END
    IF @InvStatus <> 'Confirmed'
        BEGIN RAISERROR('Only Confirmed invoices can be paid.', 16, 1); RETURN; END

    -- Convert incoming invoice-currency amount to base for storage
    DECLARE @AllocatedAmountBase DECIMAL(18,4) = @AllocatedAmount * @InvExchangeRate;

    -- Outstanding in base: invoice total base minus other approved RV payments (base) minus CN credits (base)
    DECLARE @PaidByOthers DECIMAL(18,4);
    SELECT @PaidByOthers = ISNULL(SUM(a.AllocatedAmount), 0)
    FROM   proj.TBL_RECEIPT_VOUCHER_ALLOCATION a
    JOIN   proj.TBL_RECEIPT_VOUCHER rv ON rv.RvId = a.RvId
    WHERE  a.InvoiceId = @InvoiceId AND a.IsActive = 1
      AND  rv.Status = 'Approved' AND rv.IsActive = 1 AND rv.RvId <> @RvId;

    DECLARE @CnCredits DECIMAL(18,4);
    SELECT @CnCredits = ISNULL(SUM(a.AllocatedAmount), 0)
    FROM   proj.TBL_CREDIT_NOTE_ALLOCATION a
    JOIN   proj.TBL_CREDIT_NOTE cn ON cn.CnId = a.CnId
    WHERE  a.InvoiceId = @InvoiceId AND a.IsActive = 1
      AND  cn.Status = 'Approved' AND cn.IsActive = 1;

    DECLARE @Outstanding DECIMAL(18,4) = @InvTotal * @InvExchangeRate - @PaidByOthers - @CnCredits;
    IF @AllocatedAmountBase > @Outstanding
    BEGIN
        DECLARE @m1 NVARCHAR(400) =
            'Allocation (' + CAST(@AllocatedAmount AS NVARCHAR(30)) +
            ') exceeds the invoice outstanding balance (' +
            CAST(ROUND(@Outstanding / @InvExchangeRate, 2) AS NVARCHAR(30)) + ').';
        RAISERROR(@m1, 16, 1); RETURN;
    END

    -- RV balance: all base allocations on this RV must not exceed AmountReceived × RV rate
    DECLARE @OtherAlloc DECIMAL(18,4);
    SELECT @OtherAlloc = ISNULL(SUM(AllocatedAmount), 0)
    FROM   proj.TBL_RECEIPT_VOUCHER_ALLOCATION
    WHERE  RvId = @RvId AND IsActive = 1 AND InvoiceId <> @InvoiceId;

    DECLARE @RvAvailableBase DECIMAL(18,4) = @AmountReceived * @ExchangeRate;
    IF (@OtherAlloc + @AllocatedAmountBase) > @RvAvailableBase
    BEGIN
        DECLARE @m2 NVARCHAR(400) =
            'Total allocations (' +
            CAST(ROUND((@OtherAlloc + @AllocatedAmountBase) / @ExchangeRate, 2) AS NVARCHAR(30)) +
            ') would exceed the RV available balance (' +
            CAST(@AmountReceived AS NVARCHAR(30)) + ').';
        RAISERROR(@m2, 16, 1); RETURN;
    END

    DECLARE @ExistingId INT;
    SELECT @ExistingId = AllocationId
    FROM   proj.TBL_RECEIPT_VOUCHER_ALLOCATION
    WHERE  RvId = @RvId AND InvoiceId = @InvoiceId AND IsActive = 1;

    IF @ExistingId IS NOT NULL
        UPDATE proj.TBL_RECEIPT_VOUCHER_ALLOCATION
        SET    AllocatedAmount = @AllocatedAmountBase,
               Reason         = @Reason,
               ModifiedBy     = @ActionBy,
               ModifiedDate   = GETDATE()
        WHERE  AllocationId = @ExistingId;
    ELSE
        INSERT INTO proj.TBL_RECEIPT_VOUCHER_ALLOCATION
            (RvId, InvoiceId, AllocatedAmount, Reason, CreatedBy)
        VALUES (@RvId, @InvoiceId, @AllocatedAmountBase, @Reason, @CreatedBy);

    -- Refresh RV header: sum of base allocations ÷ RV rate = allocated in RV's own currency
    UPDATE proj.TBL_RECEIPT_VOUCHER
    SET    AllocatedAmount = (
               SELECT ISNULL(SUM(AllocatedAmount), 0) / @ExchangeRate
               FROM   proj.TBL_RECEIPT_VOUCHER_ALLOCATION
               WHERE  RvId = @RvId AND IsActive = 1
           ),
           ModifiedDate = GETDATE()
    WHERE  RvId = @RvId;

    DECLARE @JobId NVARCHAR(50) =
        (SELECT JobId FROM proj.TBL_INVOICE WHERE InvoiceId = @InvoiceId);
    IF NULLIF(@JobId, '') IS NOT NULL
        EXEC proj.sp_RecalcJobPayments @JobId, @ActionBy;

    SELECT @RvId AS RvId;
END
GO

IF OBJECT_ID(N'[proj].[sp_SetServiceReceipt]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetServiceReceipt];
GO
CREATE PROCEDURE proj.sp_SetServiceReceipt
    @SrvId        INT           = 0,
    @SrvDate      DATE          = NULL,
    @PoId         INT           = NULL,
    @JobId        NVARCHAR(50)  = NULL,
    @SupplierName NVARCHAR(200) = NULL,
    @Notes        NVARCHAR(500) = NULL,
    @CreatedBy    NVARCHAR(100) = NULL,
    @ModifiedBy   NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    -- Block transactional saves on a closed job (Freezed/Completed/Cancelled).
    IF @JobId IS NOT NULL EXEC proj.sp_AssertJobOpen @JobId;
    -- Block transactional saves on a job whose budget is not yet approved.
    IF @JobId IS NOT NULL EXEC proj.sp_AssertBudgetApproved @JobId, N'SRV';

    IF @SrvId IS NULL OR @SrvId = 0
    BEGIN
        -- Mandatory field validation
        IF NULLIF(@CreatedBy, '') IS NULL RAISERROR('CreatedBy is required.', 16, 1);
        IF @@ERROR <> 0 RETURN;

        -- PO must belong to a subcontract expense category
        IF @PoId IS NOT NULL AND @PoId > 0
        BEGIN
            IF NOT EXISTS (
                SELECT 1
                FROM   proj.TBL_PURCHASE_ORDER po
                JOIN   proj.TBL_JOB_EXPENSE_CATEGORY ec ON ec.ExpenseCategoryId = po.ExpenseCategoryId
                WHERE  po.PoId = @PoId
                AND    ISNULL(ec.IsSubcontractOrder, 0) = 1
            )
                RAISERROR('The selected PO does not belong to a subcontract expense category and cannot be used for a Service Receipt.', 16, 1);
        END

        -- Auto-fill SupplierName from PO if not passed
        IF @PoId IS NOT NULL AND @PoId > 0 AND @SupplierName IS NULL
            SELECT @SupplierName = ISNULL(s.SupplierName, po.VendorName)
            FROM   proj.TBL_PURCHASE_ORDER po
            LEFT JOIN proj.TBL_SUPPLIER s ON s.SupplierId = po.SupplierId
            WHERE  po.PoId = @PoId;

        DECLARE @PoNumber NVARCHAR(50) = NULL;
        IF @PoId IS NOT NULL
            SELECT @PoNumber = PoNumber FROM proj.TBL_PURCHASE_ORDER WHERE PoId = @PoId;

        -- Also get JobId from PO if not explicitly passed
        IF NULLIF(@JobId,'') IS NULL AND @PoId IS NOT NULL
            SELECT @JobId = JobId FROM proj.TBL_PURCHASE_ORDER WHERE PoId = @PoId;

        -- Job status guard (new records only)
        IF NULLIF(@JobId,'') IS NOT NULL
        BEGIN
            DECLARE @IsClosed BIT = 0, @StatusName NVARCHAR(50) = '';
            SELECT @IsClosed = js.IsClosed, @StatusName = js.StatusName
            FROM   proj.TBL_JOB j
            JOIN   proj.TBL_JOB_STATUS js ON js.JobStatusId = j.JobStatusId
            WHERE  j.JobId = @JobId;
            IF @IsClosed = 1
            BEGIN
                DECLARE @ErrMsg NVARCHAR(200) = 'Job ' + @JobId + ' is ' + @StatusName + '. Revise the job to create new transactions.';
                RAISERROR('%s', 16, 1, @ErrMsg);
                RETURN;
            END
        END

        DECLARE @NumResult TABLE (DocNumber NVARCHAR(50), NewSeries INT);
        INSERT INTO @NumResult EXEC proj.sp_GetNextDocNumber 'SRV';
        DECLARE @SrvNo NVARCHAR(50);
        SELECT @SrvNo = DocNumber FROM @NumResult;

        INSERT INTO proj.TBL_SRV_HEADER
            (SrvNo, SrvDate, PoId, PoNumber, JobId, SupplierName, Notes, CreatedBy)
        VALUES
            (@SrvNo, ISNULL(@SrvDate, CAST(GETDATE() AS DATE)),
             NULLIF(@PoId,0), @PoNumber, NULLIF(@JobId,''),
             @SupplierName, @Notes, @CreatedBy);

        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_SRV_HEADER SET
            SrvDate      = ISNULL(@SrvDate,      SrvDate),
            PoId         = NULLIF(@PoId,          0),
            JobId        = NULLIF(@JobId,         ''),
            SupplierName = @SupplierName,
            Notes        = @Notes,
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE SrvId = @SrvId AND IsActive = 1 AND Status = 'Draft';

        SELECT CAST(@SrvId AS NVARCHAR(20));
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetServiceReceiptLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetServiceReceiptLine];
GO

CREATE PROCEDURE proj.sp_SetServiceReceiptLine
    @SrvLineId    INT           = 0,
    @SrvId        INT,
    @LineNum      INT           = 0,
    @PoLineId     INT           = NULL,
    @ItemId       INT           = NULL,
    @ItemCode     NVARCHAR(50)  = NULL,
    @ItemDesc     NVARCHAR(300) = NULL,
    @CompletedQty DECIMAL(18,4) = 1,
    @UomId        INT           = NULL,
    @UomName      NVARCHAR(50)  = NULL,
    @UnitCost     DECIMAL(18,4) = 0,
    @Notes        NVARCHAR(300) = NULL,
    @CreatedBy    NVARCHAR(100) = NULL,
    @ModifiedBy   NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @ParentJobId NVARCHAR(50) = (SELECT JobId FROM proj.TBL_SRV_HEADER WHERE SrvId = @SrvId);
    IF @ParentJobId IS NOT NULL EXEC proj.sp_AssertJobOpen @ParentJobId;
    IF @ParentJobId IS NOT NULL EXEC proj.sp_AssertBudgetApproved @ParentJobId, N'SRV';

    IF NULLIF(@SrvId, 0)         IS NULL BEGIN RAISERROR('SrvId is required.',                             16, 1); RETURN; END
    IF NULLIF(@ItemDesc, '')      IS NULL BEGIN RAISERROR('Service description (ItemDesc) is required.',    16, 1); RETURN; END
    IF ISNULL(@CompletedQty, 0) <= 0     BEGIN RAISERROR('Completed quantity must be greater than zero.', 16, 1); RETURN; END
    IF ISNULL(@UnitCost, 0)      < 0     BEGIN RAISERROR('Unit cost cannot be negative.',                 16, 1); RETURN; END
    IF @@ERROR <> 0 RETURN;

    DECLARE @SrvStatus NVARCHAR(30);
    SELECT @SrvStatus = Status FROM proj.TBL_SRV_HEADER WHERE SrvId = @SrvId AND IsActive = 1;
    IF @SrvStatus IS NULL  BEGIN RAISERROR('Service Receipt not found or is inactive.', 16, 1); RETURN; END
    IF @SrvStatus <> 'Draft'
    BEGIN
        DECLARE @SsMsg NVARCHAR(200) = 'Service Receipt lines can only be added or edited when the receipt is in Draft status. Current status: ' + @SrvStatus;
        RAISERROR(@SsMsg, 16, 1); RETURN;
    END

    IF @SrvLineId IS NULL OR @SrvLineId = 0
    BEGIN
        IF NULLIF(@CreatedBy, '') IS NULL BEGIN RAISERROR('CreatedBy is required.', 16, 1); RETURN; END
        IF @@ERROR <> 0 RETURN;

        IF NULLIF(@PoLineId, 0) IS NOT NULL
        BEGIN
            DECLARE @SrvPoStatus NVARCHAR(30);
            SELECT @SrvPoStatus = po.Status
            FROM proj.TBL_PURCHASE_ORDER_LINE pol
            JOIN proj.TBL_PURCHASE_ORDER      po ON po.PoId = pol.PoId
            WHERE pol.PoLineId = @PoLineId AND po.IsActive = 1;

            IF @SrvPoStatus = 'Hold'
                RAISERROR('Cannot add a Service Receipt line — the linked Purchase Order is currently on hold. Release the hold first.', 16, 1);

            IF @SrvPoStatus = 'Closed'
                RAISERROR('Cannot add a Service Receipt line — the linked Purchase Order is closed.', 16, 1);

            IF @SrvPoStatus = 'Cancelled'
                RAISERROR('Cannot add a Service Receipt line — the linked Purchase Order is cancelled.', 16, 1);
        END

        IF @LineNum = 0
            SELECT @LineNum = ISNULL(MAX(LineNum), 0) + 1
            FROM   proj.TBL_SRV_LINE WHERE SrvId = @SrvId AND IsActive = 1;

        INSERT INTO proj.TBL_SRV_LINE
            (SrvId, LineNum, PoLineId, ItemId, ItemCode, ItemDesc,
             CompletedQty, UomId, UomName, UnitCost, Notes, CreatedBy)
        VALUES
            (@SrvId, @LineNum, NULLIF(@PoLineId,0), NULLIF(@ItemId,0),
             @ItemCode, @ItemDesc, @CompletedQty,
             NULLIF(@UomId,0), @UomName, ISNULL(@UnitCost,0), @Notes, @CreatedBy);

        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_SRV_LINE SET
            ItemId       = NULLIF(@ItemId, 0),
            ItemCode     = @ItemCode,
            ItemDesc     = @ItemDesc,
            CompletedQty = @CompletedQty,
            UomId        = NULLIF(@UomId, 0),
            UomName      = @UomName,
            UnitCost     = ISNULL(@UnitCost, 0),
            Notes        = @Notes,
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE SrvLineId = @SrvLineId;

        SELECT CAST(@SrvLineId AS NVARCHAR(20));
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_SetStockIssue]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetStockIssue];
GO
CREATE   PROCEDURE proj.sp_SetStockIssue
    @IssueId     INT           = 0,
    @IssueDate   DATE          = NULL,
    @JobId       NVARCHAR(50)  = NULL,
    @CostingType NVARCHAR(20)  = 'INC_COSTING',
    @IssuedTo    NVARCHAR(100) = NULL,
    @Notes       NVARCHAR(500) = NULL,
    @CreatedBy   NVARCHAR(100) = NULL,
    @ModifiedBy  NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- Job lifecycle / budget guards
    IF @JobId IS NOT NULL EXEC proj.sp_AssertJobOpen        @JobId;
    IF @JobId IS NOT NULL EXEC proj.sp_AssertBudgetApproved @JobId, N'ISSUE';

    IF @IssueId IS NULL OR @IssueId <= 0
    BEGIN
        -- ── INSERT ─────────────────────────────────────────────────────────
        IF NULLIF(@CreatedBy, '') IS NULL THROW 50500, 'CreatedBy is required.',                  1;
        IF NULLIF(@JobId, '')     IS NULL THROW 50501, 'Job is required for a Stock Issue Note.', 1;
        IF NULLIF(@IssuedTo, '')  IS NULL THROW 50502, 'Issued To is required.',                  1;

        DECLARE @IsClosed BIT = 0, @StatusName NVARCHAR(50) = '';
        SELECT @IsClosed = js.IsClosed, @StatusName = js.StatusName
        FROM   proj.TBL_JOB j
        JOIN   proj.TBL_JOB_STATUS js ON js.JobStatusId = j.JobStatusId
        WHERE  j.JobId = @JobId;

        IF @IsClosed = 1
        BEGIN
            DECLARE @ErrMsg NVARCHAR(200) = 'Job ' + @JobId + ' is ' + @StatusName +
                                            '. Revise the job to create new transactions.';
            THROW 50503, @ErrMsg, 1;
        END

        DECLARE @NumResult TABLE (DocNumber NVARCHAR(50), NewSeries INT);
        INSERT INTO @NumResult EXEC proj.sp_GetNextDocNumber 'ISN';
        DECLARE @IssueNo NVARCHAR(50);
        SELECT @IssueNo = DocNumber FROM @NumResult;

        INSERT INTO proj.TBL_STOCK_ISSUE
            (IssueNo, IssueDate, JobId, CostingType, IssuedTo, Notes, CreatedBy)
        VALUES
            (@IssueNo, ISNULL(@IssueDate, CAST(GETDATE() AS DATE)),
             @JobId, @CostingType, @IssuedTo, @Notes, @CreatedBy);

        SELECT CAST(SCOPE_IDENTITY() AS INT) AS NewId, @IssueNo AS IssueNo;
    END
    ELSE
    BEGIN
        -- ── UPDATE ─────────────────────────────────────────────────────────
        IF EXISTS (SELECT 1 FROM proj.TBL_STOCK_ISSUE WHERE IssueId = @IssueId AND Status = 'Confirmed')
            THROW 50510, 'Cannot edit a confirmed Issue Note.', 1;

        IF NULLIF(@JobId, '')    IS NULL THROW 50511, 'Job is required for a Stock Issue Note.', 1;
        IF NULLIF(@IssuedTo, '') IS NULL THROW 50512, 'Issued To is required.',                  1;

        UPDATE proj.TBL_STOCK_ISSUE
        SET IssueDate    = ISNULL(@IssueDate, IssueDate),
            JobId        = @JobId,
            CostingType  = @CostingType,
            IssuedTo     = @IssuedTo,
            Notes        = @Notes,
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE IssueId = @IssueId AND IsActive = 1;

        SELECT CAST(@IssueId AS INT) AS NewId, IssueNo
        FROM proj.TBL_STOCK_ISSUE WHERE IssueId = @IssueId;
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetStockIssueLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetStockIssueLine];
GO
CREATE   PROCEDURE proj.sp_SetStockIssueLine
    @IssueLineId INT           = 0,
    @IssueId     INT,
    @LineNum     INT           = 0,
    @ItemId      INT,
    @ItemDesc    NVARCHAR(300) = NULL,
    @Qty         DECIMAL(18,4) = 0,
    @UomId       INT           = NULL,
    @UnitCost    DECIMAL(18,4) = 0,
    @Notes       NVARCHAR(200) = NULL,
    @CreatedBy   NVARCHAR(100) = NULL,
    @ModifiedBy  NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    -- Parent-issue lookup so we can fire the same guards as the header SP.
    DECLARE @ParentJobId NVARCHAR(50) = (SELECT JobId FROM proj.TBL_STOCK_ISSUE WHERE IssueId = @IssueId);
    -- Block writes when the parent job is Freezed / Completed / Cancelled.
    IF @ParentJobId IS NOT NULL EXEC proj.sp_AssertJobOpen @ParentJobId;
    -- Block writes when the parent job's budget is not yet approved.
    IF @ParentJobId IS NOT NULL EXEC proj.sp_AssertBudgetApproved @ParentJobId, N'ISSUE';


    -- ── Parent status guard ───────────────────────────────────────────────
    IF EXISTS (SELECT 1 FROM proj.TBL_STOCK_ISSUE WHERE IssueId = @IssueId AND Status = 'Confirmed') BEGIN RAISERROR('Cannot edit lines of a confirmed Issue Note.', 16, 1); RETURN; END

    -- ── Mandatory field validation ────────────────────────────────────────
    IF NULLIF(@IssueId, 0) IS NULL BEGIN RAISERROR('IssueId is required.',                           16, 1); RETURN; END
    IF NULLIF(@ItemId,  0) IS NULL BEGIN RAISERROR('Item is required.',                               16, 1); RETURN; END
    IF ISNULL(@Qty, 0)    <= 0     BEGIN RAISERROR('Issue quantity must be greater than zero.',       16, 1); RETURN; END
    IF @@ERROR <> 0 RETURN;

    IF @IssueLineId IS NULL OR @IssueLineId = 0
    BEGIN
        IF NULLIF(@CreatedBy, '') IS NULL BEGIN RAISERROR('CreatedBy is required.', 16, 1); RETURN; END
        IF @@ERROR <> 0 RETURN;

        IF @LineNum = 0
            SELECT @LineNum = ISNULL(MAX(LineNum),0)+1
            FROM proj.TBL_STOCK_ISSUE_LINE WHERE IssueId=@IssueId AND IsActive=1;

        INSERT INTO proj.TBL_STOCK_ISSUE_LINE
            (IssueId, LineNum, ItemId, ItemDesc, Qty, UomId, UnitCost, Notes, CreatedBy)
        VALUES
            (@IssueId, @LineNum, @ItemId, @ItemDesc, @Qty, NULLIF(@UomId,0), @UnitCost, @Notes, @CreatedBy);

        SELECT CAST(SCOPE_IDENTITY() AS INT) AS IssueLineId;
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_STOCK_ISSUE_LINE
        SET ItemId       = @ItemId,
            ItemDesc     = @ItemDesc,
            Qty          = @Qty,
            UomId        = NULLIF(@UomId,0),
            UnitCost     = @UnitCost,
            Notes        = @Notes,
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE IssueLineId = @IssueLineId AND IsActive = 1;

        SELECT @IssueLineId AS IssueLineId;
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_SetStockReceipt]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetStockReceipt];
GO
CREATE PROCEDURE proj.sp_SetStockReceipt
    @ReceiptId    INT           = 0,
    @ReceiptDate  DATE          = NULL,
    @ReceiptType  NVARCHAR(10)  = 'STORE',
    @JobId        NVARCHAR(50)  = NULL,
    @PoId         INT           = NULL,
    @PoNumber     NVARCHAR(30)  = NULL,
    @SupplierId   INT           = NULL,
    @SupplierName NVARCHAR(200) = NULL,
    @SupplierRef  NVARCHAR(100) = NULL,
    @Notes        NVARCHAR(500) = NULL,
    @CreatedBy    NVARCHAR(100) = NULL,
    @ModifiedBy   NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    -- Block transactional saves on a closed job (Freezed/Completed/Cancelled).
    IF @JobId IS NOT NULL EXEC proj.sp_AssertJobOpen @JobId;
    -- Block transactional saves on a job whose budget is not yet approved.
    IF @JobId IS NOT NULL EXEC proj.sp_AssertBudgetApproved @JobId, N'STOCK_RECEIPT';

    -- Snapshot the supplier name from the master when an id is supplied
    IF @SupplierId IS NOT NULL
        SELECT @SupplierName = SupplierName FROM proj.TBL_SUPPLIER WHERE SupplierId = @SupplierId;

    IF @ReceiptId = 0 OR @ReceiptId IS NULL
    BEGIN
        DECLARE @NumResult TABLE (DocNumber NVARCHAR(50), NewSeries INT);
        INSERT INTO @NumResult EXEC proj.sp_GetNextDocNumber 'GRN';
        DECLARE @ReceiptNo NVARCHAR(50);
        SELECT @ReceiptNo = DocNumber FROM @NumResult;

        INSERT INTO proj.TBL_STOCK_RECEIPT
            (ReceiptNo, ReceiptDate, ReceiptType, JobId, PoId, PoNumber,
             SupplierId, SupplierName, SupplierRef, Notes, CreatedBy)
        VALUES
            (@ReceiptNo, ISNULL(@ReceiptDate, CAST(GETDATE() AS DATE)),
             @ReceiptType, NULLIF(@JobId,''), NULLIF(@PoId,0), NULLIF(@PoNumber,''),
             NULLIF(@SupplierId,0), @SupplierName, @SupplierRef, @Notes, @CreatedBy);

        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20)) AS NewId, @ReceiptNo AS ReceiptNo;
    END
    ELSE
    BEGIN
        IF EXISTS (SELECT 1 FROM proj.TBL_STOCK_RECEIPT WHERE ReceiptId = @ReceiptId AND Status = 'Confirmed') BEGIN RAISERROR('Cannot edit a confirmed GRN.', 16, 1); RETURN; END

        UPDATE proj.TBL_STOCK_RECEIPT
        SET ReceiptDate  = ISNULL(@ReceiptDate, ReceiptDate),
            ReceiptType  = @ReceiptType,
            JobId        = NULLIF(@JobId,''),
            PoId         = NULLIF(@PoId,0),
            PoNumber     = NULLIF(@PoNumber,''),
            SupplierId   = NULLIF(@SupplierId,0),
            SupplierName = @SupplierName,
            SupplierRef  = @SupplierRef,
            Notes        = @Notes,
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE ReceiptId = @ReceiptId AND IsActive = 1;

        SELECT CAST(@ReceiptId AS NVARCHAR(20)) AS NewId, ReceiptNo
        FROM proj.TBL_STOCK_RECEIPT WHERE ReceiptId = @ReceiptId;
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetStockReceiptLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetStockReceiptLine];
GO
CREATE   PROCEDURE proj.sp_SetStockReceiptLine
    @ReceiptLineId INT           = 0,
    @ReceiptId     INT,
    @LineNum       INT           = 0,
    @ItemId        INT,
    @ItemDesc      NVARCHAR(300) = NULL,
    @Qty           DECIMAL(18,4) = 0,
    @UomId         INT           = NULL,
    @UnitCost      DECIMAL(18,4) = 0,
    @IsJobStock    BIT           = 0,
    @JobId         NVARCHAR(50)  = NULL,
    @Notes         NVARCHAR(200) = NULL,
    @CreatedBy     NVARCHAR(100) = NULL,
    @ModifiedBy    NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    -- Block transactional saves on a closed job (Freezed/Completed/Cancelled).
    IF @JobId IS NOT NULL EXEC proj.sp_AssertJobOpen @JobId;
    -- Block transactional saves on a job whose budget is not yet approved.
    IF @JobId IS NOT NULL EXEC proj.sp_AssertBudgetApproved @JobId, N'STOCK_RECEIPT';


    -- Block if receipt confirmed
    IF EXISTS (SELECT 1 FROM proj.TBL_STOCK_RECEIPT WHERE ReceiptId=@ReceiptId AND Status='Confirmed') BEGIN RAISERROR('Cannot edit lines of a confirmed GRN.', 16, 1); RETURN; END

    IF @ReceiptLineId = 0 OR @ReceiptLineId IS NULL
    BEGIN
        IF @LineNum = 0
            SELECT @LineNum = ISNULL(MAX(LineNum),0)+1 FROM proj.TBL_STOCK_RECEIPT_LINE WHERE ReceiptId=@ReceiptId AND IsActive=1;
        INSERT INTO proj.TBL_STOCK_RECEIPT_LINE
            (ReceiptId, LineNum, ItemId, ItemDesc, Qty, UomId, UnitCost, IsJobStock, JobId, Notes, CreatedBy)
        VALUES
            (@ReceiptId, @LineNum, @ItemId, @ItemDesc, @Qty, NULLIF(@UomId,0), @UnitCost, @IsJobStock, NULLIF(@JobId,''), @Notes, @CreatedBy);
        SELECT CAST(SCOPE_IDENTITY() AS INT) AS ReceiptLineId;
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_STOCK_RECEIPT_LINE
        SET ItemId     = @ItemId,
            ItemDesc   = @ItemDesc,
            Qty        = @Qty,
            UomId      = NULLIF(@UomId,0),
            UnitCost   = @UnitCost,
            IsJobStock = @IsJobStock,
            JobId      = NULLIF(@JobId,''),
            Notes      = @Notes,
            ModifiedBy = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE ReceiptLineId = @ReceiptLineId AND IsActive = 1;
        SELECT @ReceiptLineId AS ReceiptLineId;
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_SetStockTransfer]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetStockTransfer];
GO

-- 1. Update sp_SetStockTransfer — add TransferReason, block edits past Draft
CREATE   PROCEDURE proj.sp_SetStockTransfer
    @TransferId     INT           = 0,
    @TransferDate   DATE          = NULL,
    @FromJobId      NVARCHAR(50),
    @ToJobId        NVARCHAR(50),
    @TransferReason NVARCHAR(500) = NULL,
    @Notes          NVARCHAR(500) = NULL,
    @CreatedBy      NVARCHAR(100) = NULL,
    @ModifiedBy     NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF NULLIF(@FromJobId,'') IS NULL OR NULLIF(@ToJobId,'') IS NULL
        THROW 50600, 'Both From and To jobs are required.', 1;
    IF @FromJobId = @ToJobId
        THROW 50601, 'From and To jobs must be different.', 1;
    IF NULLIF(LTRIM(RTRIM(@TransferReason)),'') IS NULL
        THROW 50604, 'Transfer reason is required.', 1;

    IF @TransferId IS NULL OR @TransferId <= 0
    BEGIN
        IF NULLIF(@CreatedBy,'') IS NULL THROW 50602, 'CreatedBy is required.', 1;

        DECLARE @Yr NVARCHAR(2) = RIGHT(CAST(YEAR(GETDATE()) AS NVARCHAR), 2);
        DECLARE @Seq INT = (
            SELECT ISNULL(MAX(TRY_CAST(RIGHT(TransferNo,5) AS INT)),0) + 1
            FROM proj.TBL_STOCK_TRANSFER
            WHERE TransferNo LIKE 'STR-' + @Yr + '-%');
        DECLARE @TransferNo NVARCHAR(30) = 'STR-' + @Yr + '-' + RIGHT('00000' + CAST(@Seq AS NVARCHAR(5)), 5);

        INSERT INTO proj.TBL_STOCK_TRANSFER
            (TransferNo, TransferDate, FromJobId, ToJobId, TransferReason, Notes, CreatedBy)
        VALUES
            (@TransferNo, ISNULL(@TransferDate, CAST(GETDATE() AS DATE)),
             @FromJobId, @ToJobId, @TransferReason, @Notes, @CreatedBy);

        SELECT CAST(SCOPE_IDENTITY() AS INT) AS NewId, @TransferNo AS TransferNo;
    END
    ELSE
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM proj.TBL_STOCK_TRANSFER WHERE TransferId=@TransferId AND Status='Draft')
            THROW 50603, 'Only Draft transfers can be edited.', 1;

        UPDATE proj.TBL_STOCK_TRANSFER
        SET TransferDate    = ISNULL(@TransferDate, TransferDate),
            FromJobId       = @FromJobId,
            ToJobId         = @ToJobId,
            TransferReason  = @TransferReason,
            Notes           = @Notes,
            ModifiedBy      = @ModifiedBy,
            ModifiedDate    = GETDATE()
        WHERE TransferId = @TransferId AND IsActive = 1;

        SELECT CAST(@TransferId AS INT) AS NewId, TransferNo
        FROM proj.TBL_STOCK_TRANSFER WHERE TransferId = @TransferId;
    END
END;
GO

IF OBJECT_ID(N'[proj].[sp_SetStockTransferLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetStockTransferLine];
GO

-- 2. Update sp_SetStockTransferLine — validate vs available qty, store snapshot
CREATE   PROCEDURE proj.sp_SetStockTransferLine
    @TransferLineId INT           = 0,
    @TransferId     INT,
    @ItemId         INT,
    @Qty            DECIMAL(18,4) = 1,
    @UomId          INT           = NULL,
    @UnitCost       DECIMAL(18,4) = 0,
    @Notes          NVARCHAR(200) = NULL,
    @CreatedBy      NVARCHAR(100) = NULL,
    @ModifiedBy     NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM proj.TBL_STOCK_TRANSFER WHERE TransferId=@TransferId AND Status='Draft')
        THROW 50610, 'Transfer lines can only be changed while the transfer is in Draft.', 1;
    IF ISNULL(@Qty,0) <= 0
        THROW 50611, 'Quantity must be greater than zero.', 1;

    -- Source job
    DECLARE @FromJobId NVARCHAR(50);
    SELECT @FromJobId = FromJobId FROM proj.TBL_STOCK_TRANSFER WHERE TransferId = @TransferId;

    -- Available stock in source job for this item
    DECLARE @AvailQty DECIMAL(18,4) = ISNULL((
        SELECT SUM(QtyIn - QtyOut)
        FROM proj.TBL_STOCK_LEDGER
        WHERE ItemId = @ItemId AND JobId = @FromJobId AND IsJobStock = 1
    ), 0);

    IF @AvailQty <= 0
    BEGIN
        DECLARE @ItemCode NVARCHAR(50) = (SELECT ItemCode FROM proj.TBL_ITEM WHERE ItemId = @ItemId);
        THROW 50613, 'Item has no available stock in the source job.', 1;
    END

    -- Qty already allocated in other lines of this same transfer (excluding current line on edit)
    DECLARE @AlreadyAlloc DECIMAL(18,4) = ISNULL((
        SELECT SUM(Qty) FROM proj.TBL_STOCK_TRANSFER_LINE
        WHERE TransferId = @TransferId AND ItemId = @ItemId AND IsActive = 1
          AND (@TransferLineId <= 0 OR TransferLineId <> @TransferLineId)
    ), 0);

    IF @Qty > (@AvailQty - @AlreadyAlloc)
    BEGIN
        DECLARE @Msg NVARCHAR(400) =
            'Transfer quantity (' + CAST(@Qty AS NVARCHAR(30)) +
            ') exceeds available stock in source job (' +
            CAST(@AvailQty - @AlreadyAlloc AS NVARCHAR(30)) + ').';
        THROW 50612, @Msg, 1;
    END

    IF @TransferLineId IS NULL OR @TransferLineId <= 0
    BEGIN
        DECLARE @LineNum INT = (
            SELECT ISNULL(MAX(LineNum),0)+1
            FROM proj.TBL_STOCK_TRANSFER_LINE
            WHERE TransferId=@TransferId AND IsActive=1);

        INSERT INTO proj.TBL_STOCK_TRANSFER_LINE
            (TransferId, LineNum, ItemId, Qty, AvailableQty, UomId, UnitCost, Notes, CreatedBy)
        VALUES
            (@TransferId, @LineNum, @ItemId, @Qty, @AvailQty, @UomId, ISNULL(@UnitCost,0), @Notes, @CreatedBy);

        SELECT CAST(SCOPE_IDENTITY() AS INT) AS NewId;
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_STOCK_TRANSFER_LINE
        SET ItemId       = @ItemId,
            Qty          = @Qty,
            AvailableQty = @AvailQty,
            UomId        = @UomId,
            UnitCost     = ISNULL(@UnitCost,0),
            Notes        = @Notes,
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE TransferLineId = @TransferLineId;

        SELECT CAST(@TransferLineId AS INT) AS NewId;
    END
END;
GO

