CREATE   PROCEDURE proj.sp_SetSupplier
    @SupplierId         INT,
    @SupplierCode       NVARCHAR(50),
    @SupplierName       NVARCHAR(100),
    @SupplierRef        NVARCHAR(50)   = NULL,
    @SupplierShortName  NVARCHAR(50)   = NULL,
    @SupplierType       NVARCHAR(50)   = NULL,
    @SupplierCategoryId INT            = NULL,
    @Phone              NVARCHAR(50)   = NULL,
    @Mobile             NVARCHAR(50)   = NULL,
    @Email              NVARCHAR(150)  = NULL,
    @Web                NVARCHAR(100)  = NULL,
    @CurrencyId         INT,
    @CreditLimit        DECIMAL(18,2)  = NULL,
    @CreditDays         INT            = NULL,
    @PaymentTermsId     INT,
    @VatNumber          NVARCHAR(50)   = NULL,
    @TaxNumber          NVARCHAR(50)   = NULL,
    @AccountManager     NVARCHAR(50)   = NULL,
    @Remarks            NVARCHAR(500)  = NULL,
    @IsActive           BIT,
    @IsApprovedVendor   BIT            = 0,
    @IsOnHold           BIT            = 0,
    @LeadTimeDays       INT            = NULL,
    @PaymentMode        NVARCHAR(50)   = NULL,
    @TradeLicenseNo     NVARCHAR(50)   = NULL,
    @TradeLicenseExpiry DATE           = NULL,
    @CountryId          INT            = NULL,
    @Rating             TINYINT        = NULL,
    @CreatedBy          NVARCHAR(50),
    @ModifiedBy         NVARCHAR(50)   = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM proj.TBL_SUPPLIER WHERE SupplierCode=@SupplierCode AND SupplierId<>@SupplierId)
    BEGIN SELECT '-1'; RETURN; END

    IF @SupplierId = 0
    BEGIN
        INSERT INTO proj.TBL_SUPPLIER
            (SupplierCode, SupplierName, SupplierRef, SupplierShortName, SupplierType,
             SupplierCategoryId, Phone, Mobile, Email, Web, CurrencyId, CreditLimit,
             CreditDays, PaymentTermsId, VatNumber, TaxNumber, AccountManager, Remarks,
             IsActive, IsApprovedVendor, IsOnHold, LeadTimeDays, PaymentMode,
             TradeLicenseNo, TradeLicenseExpiry, CountryId, Rating,
             CreatedBy, CreatedDate)
        VALUES
            (@SupplierCode, @SupplierName, @SupplierRef, @SupplierShortName, @SupplierType,
             @SupplierCategoryId, @Phone, @Mobile, @Email, @Web, @CurrencyId, @CreditLimit,
             @CreditDays, @PaymentTermsId, @VatNumber, @TaxNumber, @AccountManager, @Remarks,
             @IsActive, @IsApprovedVendor, @IsOnHold, @LeadTimeDays, @PaymentMode,
             @TradeLicenseNo, @TradeLicenseExpiry, @CountryId, @Rating,
             @CreatedBy, GETDATE());
        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_SUPPLIER SET
            SupplierCode       = @SupplierCode,
            SupplierName       = @SupplierName,
            SupplierRef        = @SupplierRef,
            SupplierShortName  = @SupplierShortName,
            SupplierType       = @SupplierType,
            SupplierCategoryId = @SupplierCategoryId,
            Phone              = @Phone,
            Mobile             = @Mobile,
            Email              = @Email,
            Web                = @Web,
            CurrencyId         = @CurrencyId,
            CreditLimit        = @CreditLimit,
            CreditDays         = @CreditDays,
            PaymentTermsId     = @PaymentTermsId,
            VatNumber          = @VatNumber,
            TaxNumber          = @TaxNumber,
            AccountManager     = @AccountManager,
            Remarks            = @Remarks,
            IsActive           = @IsActive,
            IsApprovedVendor   = @IsApprovedVendor,
            IsOnHold           = @IsOnHold,
            LeadTimeDays       = @LeadTimeDays,
            PaymentMode        = @PaymentMode,
            TradeLicenseNo     = @TradeLicenseNo,
            TradeLicenseExpiry = @TradeLicenseExpiry,
            CountryId          = @CountryId,
            Rating             = @Rating,
            ModifiedBy         = @ModifiedBy,
            ModifiedDate       = GETDATE()
        WHERE SupplierId = @SupplierId;
        SELECT CAST(@SupplierId AS NVARCHAR(20));
    END
END
GO

