CREATE   PROCEDURE proj.sp_SetSupplierBank
    @SupplierBankId INT,
    @SupplierId     INT,
    @BankName       NVARCHAR(100),
    @AccountName    NVARCHAR(100) = NULL,
    @AccountNumber  NVARCHAR(50),
    @IBAN           NVARCHAR(50)  = NULL,
    @SwiftCode      NVARCHAR(20)  = NULL,
    @BranchName     NVARCHAR(100) = NULL,
    @CurrencyId     INT           = NULL,
    @IsDefault      BIT           = 0,
    @IsActive       BIT           = 1,
    @CreatedBy      NVARCHAR(50)  = NULL,
    @ModifiedBy     NVARCHAR(50)  = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- If setting as default, clear existing defaults for this supplier
    IF @IsDefault = 1
        UPDATE proj.TBL_SUPPLIER_BANK
        SET IsDefault = 0
        WHERE SupplierId = @SupplierId AND SupplierBankId <> @SupplierBankId;

    IF @SupplierBankId = 0
    BEGIN
        INSERT INTO proj.TBL_SUPPLIER_BANK
            (SupplierId, BankName, AccountName, AccountNumber, IBAN, SwiftCode,
             BranchName, CurrencyId, IsDefault, IsActive, CreatedBy, CreatedDate)
        VALUES
            (@SupplierId, @BankName, @AccountName, @AccountNumber, @IBAN, @SwiftCode,
             @BranchName, @CurrencyId, @IsDefault, @IsActive, @CreatedBy, GETDATE());
        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_SUPPLIER_BANK SET
            BankName      = @BankName,
            AccountName   = @AccountName,
            AccountNumber = @AccountNumber,
            IBAN          = @IBAN,
            SwiftCode     = @SwiftCode,
            BranchName    = @BranchName,
            CurrencyId    = @CurrencyId,
            IsDefault     = @IsDefault,
            IsActive      = @IsActive,
            ModifiedBy    = @ModifiedBy,
            ModifiedDate  = GETDATE()
        WHERE SupplierBankId = @SupplierBankId;
        SELECT CAST(@SupplierBankId AS NVARCHAR(20));
    END
END
