CREATE PROCEDURE proj.sp_SetSupplierInvoice
    @SupplierInvoiceId  INT,
    @InvoiceNo          NVARCHAR(30),   -- ignored on INSERT; auto-generated from SINV series
    @SupplierInvRef     NVARCHAR(100),
    @InvoiceDate        DATE,
    @SupplierId         INT,
    @CurrencyId         INT,
    @ExchangeRate       DECIMAL(18,6),
    @PaymentTermsId     INT,
    @DueDate            DATE,
    @SubTotal           DECIMAL(18,4),
    @TaxAmount          DECIMAL(18,4),
    @TotalAmount        DECIMAL(18,4),
    @Notes              NVARCHAR(500),
    @ActionBy           NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    IF @SupplierInvoiceId = 0
    BEGIN
        -- Duplicate supplier-ref check for same supplier
        IF EXISTS (
            SELECT 1 FROM proj.TBL_SUPPLIER_INVOICE
            WHERE SupplierId = @SupplierId
              AND SupplierInvRef = @SupplierInvRef
              AND IsActive = 1
        )
        BEGIN
            SELECT CAST(-1 AS NVARCHAR(20)); RETURN;
        END

        -- Auto-generate document number
        DECLARE @NumResult TABLE (DocNumber NVARCHAR(50), NewSeries INT);
        INSERT INTO @NumResult EXEC proj.sp_GetNextDocNumber 'SINV';
        DECLARE @GeneratedNo NVARCHAR(30);
        SELECT @GeneratedNo = DocNumber FROM @NumResult;

        INSERT INTO proj.TBL_SUPPLIER_INVOICE
            (InvoiceNo, SupplierInvRef, InvoiceDate, SupplierId, CurrencyId, ExchangeRate,
             PaymentTermsId, DueDate, SubTotal, TaxAmount, TotalAmount, Notes,
             Status, CreatedBy, CreatedDate)
        VALUES
            (@GeneratedNo, @SupplierInvRef, @InvoiceDate, @SupplierId, @CurrencyId, @ExchangeRate,
             @PaymentTermsId, @DueDate, @SubTotal, @TaxAmount, @TotalAmount, @Notes,
             'Draft', @ActionBy, GETDATE());

        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_SUPPLIER_INVOICE SET
            SupplierInvRef  = @SupplierInvRef,
            InvoiceDate     = @InvoiceDate,
            SupplierId      = @SupplierId,
            CurrencyId      = @CurrencyId,
            ExchangeRate    = @ExchangeRate,
            PaymentTermsId  = @PaymentTermsId,
            DueDate         = @DueDate,
            SubTotal        = @SubTotal,
            TaxAmount       = @TaxAmount,
            TotalAmount     = @TotalAmount,
            Notes           = @Notes,
            ModifiedBy      = @ActionBy,
            ModifiedDate    = GETDATE()
        WHERE SupplierInvoiceId = @SupplierInvoiceId
          AND Status = 'Draft'
          AND IsActive = 1;

        SELECT CAST(@SupplierInvoiceId AS NVARCHAR(20));
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_SetSupplierInvoiceLine]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetSupplierInvoiceLine];
GO
CREATE   PROCEDURE proj.sp_SetSupplierInvoiceLine
    @SupplierInvLineId  INT,
    @SupplierInvoiceId  INT,
    @LineNum            INT,
    @GrnDetailId        INT,
    @GrnId              INT,
    @PoLineId           INT,
    @SrvId              INT           = NULL,   -- NEW
    @SrvLineId          INT           = NULL,   -- NEW
    @ItemId             INT,
    @ItemCode           NVARCHAR(50),
    @ItemDesc           NVARCHAR(300),
    @UomName            NVARCHAR(50),
    @Qty                DECIMAL(18,4),
    @UnitPrice          DECIMAL(18,4),
    @TaxPct             DECIMAL(18,4),
    @Notes              NVARCHAR(300),
    @ActionBy           NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @TaxAmount       DECIMAL(18,4) = ROUND(@Qty * @UnitPrice * @TaxPct / 100, 4);
    DECLARE @LineTotal       DECIMAL(18,4) = ROUND(@Qty * @UnitPrice, 4);
    DECLARE @LineTotalWithTax DECIMAL(18,4) = @LineTotal + @TaxAmount;

    -- If the row came from an SRV but PoLineId wasn't supplied, derive it
    IF @SrvLineId IS NOT NULL AND @PoLineId IS NULL
        SELECT @PoLineId = PoLineId FROM proj.TBL_SRV_LINE WHERE SrvLineId = @SrvLineId;

    IF @SupplierInvLineId = 0
    BEGIN
        INSERT INTO proj.TBL_SUPPLIER_INVOICE_LINE
            (SupplierInvoiceId, LineNum, GrnDetailId, GrnId, PoLineId,
             SrvId, SrvLineId,
             ItemId, ItemCode, ItemDesc, UomName,
             Qty, UnitPrice, TaxPct, TaxAmount, LineTotal, LineTotalWithTax,
             Notes, CreatedBy, CreatedDate)
        VALUES
            (@SupplierInvoiceId, @LineNum, @GrnDetailId, @GrnId, @PoLineId,
             @SrvId, @SrvLineId,
             @ItemId, @ItemCode, @ItemDesc, @UomName,
             @Qty, @UnitPrice, @TaxPct, @TaxAmount, @LineTotal, @LineTotalWithTax,
             @Notes, @ActionBy, GETDATE());

        SELECT CAST(SCOPE_IDENTITY() AS NVARCHAR(20));
    END
    ELSE
    BEGIN
        UPDATE proj.TBL_SUPPLIER_INVOICE_LINE SET
            Qty              = @Qty,
            UnitPrice        = @UnitPrice,
            TaxPct           = @TaxPct,
            TaxAmount        = @TaxAmount,
            LineTotal        = @LineTotal,
            LineTotalWithTax = @LineTotalWithTax,
            Notes            = @Notes,
            ModifiedBy       = @ActionBy,
            ModifiedDate     = GETDATE()
        WHERE SupplierInvLineId = @SupplierInvLineId AND IsActive = 1;

        SELECT CAST(@SupplierInvLineId AS NVARCHAR(20));
    END

    UPDATE proj.TBL_SUPPLIER_INVOICE SET
        SubTotal    = (SELECT ISNULL(SUM(LineTotal), 0)       FROM proj.TBL_SUPPLIER_INVOICE_LINE WHERE SupplierInvoiceId = @SupplierInvoiceId AND IsActive = 1),
        TaxAmount   = (SELECT ISNULL(SUM(TaxAmount), 0)       FROM proj.TBL_SUPPLIER_INVOICE_LINE WHERE SupplierInvoiceId = @SupplierInvoiceId AND IsActive = 1),
        TotalAmount = (SELECT ISNULL(SUM(LineTotalWithTax), 0) FROM proj.TBL_SUPPLIER_INVOICE_LINE WHERE SupplierInvoiceId = @SupplierInvoiceId AND IsActive = 1),
        ModifiedBy   = @ActionBy,
        ModifiedDate = GETDATE()
    WHERE SupplierInvoiceId = @SupplierInvoiceId;
END;
GO

