CREATE PROCEDURE proj.sp_SetUserNew
    @UserId       INT            = 0,
    @UserCode     NVARCHAR(20)   = NULL,
    @UserName     NVARCHAR(100),
    @FullName     NVARCHAR(150)  = NULL,
    @Email        NVARCHAR(100)  = NULL,
    @Mobile       NVARCHAR(150)  = NULL,
    @IsActive     BIT            = 1,
    @IsLocked     BIT            = 0,
    @PasswordHash NVARCHAR(255)  = NULL,
    @CreatedBy    NVARCHAR(50),
    @ModifiedBy   NVARCHAR(50)   = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- â”€â”€ Duplicate checks â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    IF EXISTS (SELECT 1 FROM proj.TBL_USERS WHERE UserName=@UserName AND UserId<>@UserId)
    BEGIN SELECT -1 AS UserId, N'Username already exists.' AS ErrorMessage; RETURN; END

    IF @UserCode IS NOT NULL AND EXISTS (
        SELECT 1 FROM proj.TBL_USERS WHERE UserCode=@UserCode AND UserId<>@UserId)
    BEGIN SELECT -2 AS UserId, N'User code already exists.' AS ErrorMessage; RETURN; END

    -- â”€â”€ INSERT new user â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    IF @UserId = 0
    BEGIN
        INSERT INTO proj.TBL_USERS
            (UserCode, UserName, PasswordHash, FullName, Email, Mobile,
             IsActive, IsLocked, CreatedBy, CreatedDate)
        VALUES
            (@UserCode, @UserName, ISNULL(@PasswordHash,''), @FullName, @Email, @Mobile,
             @IsActive, @IsLocked, @CreatedBy, GETDATE());

        DECLARE @NewUserId INT = SCOPE_IDENTITY();

        -- Auto-sync TBL_ENGINEER: if the user already has an engineer role assigned,
        -- create the engineer record (e.g. role assigned before user was fully saved)
        IF EXISTS (
            SELECT 1 FROM proj.TBL_USER_ROLES ur
            JOIN   proj.TBL_ROLES r ON r.RoleId=ur.RoleId
            WHERE  ur.UserId=@NewUserId AND r.IsEngineerRole=1
        )
        AND NOT EXISTS (SELECT 1 FROM proj.TBL_ENGINEER WHERE UserId=@NewUserId)
        BEGIN
            INSERT INTO proj.TBL_ENGINEER
                (EngineerName, TeamId, Email, UserId, IsActive, HourlyRate, CreatedBy, CreatedDate)
            VALUES
                (ISNULL(@FullName, @UserName), NULL, @Email, @NewUserId, @IsActive, 0, @CreatedBy, GETDATE());
        END

        SELECT @NewUserId AS UserId, NULL AS ErrorMessage;
    END

    -- â”€â”€ UPDATE existing user â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    ELSE
    BEGIN
        UPDATE proj.TBL_USERS SET
            UserCode     = @UserCode,
            UserName     = @UserName,
            FullName     = @FullName,
            Email        = @Email,
            Mobile       = @Mobile,
            IsActive     = @IsActive,
            IsLocked     = @IsLocked,
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE UserId = @UserId;

        -- Sync TBL_ENGINEER: update name + email + active status if linked
        UPDATE proj.TBL_ENGINEER SET
            EngineerName = ISNULL(@FullName, @UserName),
            Email        = @Email,
            IsActive     = @IsActive,
            ModifiedBy   = @ModifiedBy,
            ModifiedDate = GETDATE()
        WHERE UserId = @UserId;

        SELECT @UserId AS UserId, NULL AS ErrorMessage;
    END
END
GO

IF OBJECT_ID(N'[proj].[sp_SetUserRole]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetUserRole];
GO

CREATE PROCEDURE proj.sp_SetUserRole
    @UserId  INT,
    @RoleId  INT,
    @Action  NVARCHAR(10)   -- 'ASSIGN' or 'REMOVE'
AS
BEGIN
    SET NOCOUNT ON;

    IF @Action = 'ASSIGN'
    BEGIN
        -- Insert into TBL_USER_ROLES if not already assigned
        IF NOT EXISTS (SELECT 1 FROM proj.TBL_USER_ROLES WHERE UserId=@UserId AND RoleId=@RoleId)
            INSERT INTO proj.TBL_USER_ROLES (UserId, RoleId) VALUES (@UserId, @RoleId);

        -- â”€â”€ Auto-sync TBL_ENGINEER â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        -- If the assigned role is an engineer role, ensure the user has an engineer record.
        IF EXISTS (SELECT 1 FROM proj.TBL_ROLES WHERE RoleId=@RoleId AND IsEngineerRole=1)
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM proj.TBL_ENGINEER WHERE UserId=@UserId)
            BEGIN
                -- New engineer record: pull FullName + Email from TBL_USERS
                INSERT INTO proj.TBL_ENGINEER (EngineerName, TeamId, Email, UserId, IsActive, HourlyRate, CreatedBy, CreatedDate)
                SELECT FullName, NULL, Email, UserId, 1, 0, UserName, GETDATE()
                FROM proj.TBL_USERS WHERE UserId=@UserId;
            END
            ELSE
            BEGIN
                -- Re-activate if previously deactivated
                UPDATE proj.TBL_ENGINEER SET IsActive=1 WHERE UserId=@UserId AND IsActive=0;
            END
        END

        SELECT 1 AS Success, NULL AS ErrorMessage;
    END

    ELSE IF @Action = 'REMOVE'
    BEGIN
        DELETE FROM proj.TBL_USER_ROLES WHERE UserId=@UserId AND RoleId=@RoleId;

        -- â”€â”€ Auto-sync TBL_ENGINEER â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        -- If the user has no remaining engineer roles, deactivate their engineer record.
        IF EXISTS (SELECT 1 FROM proj.TBL_ROLES WHERE RoleId=@RoleId AND IsEngineerRole=1)
        BEGIN
            DECLARE @HasOtherEngineerRole BIT = 0;
            IF EXISTS (
                SELECT 1 FROM proj.TBL_USER_ROLES ur
                JOIN proj.TBL_ROLES r ON r.RoleId=ur.RoleId
                WHERE ur.UserId=@UserId AND r.IsEngineerRole=1
            )
                SET @HasOtherEngineerRole = 1;

            IF @HasOtherEngineerRole = 0
                UPDATE proj.TBL_ENGINEER SET IsActive=0 WHERE UserId=@UserId;
        END

        SELECT 1 AS Success, NULL AS ErrorMessage;
    END

    ELSE
        SELECT 0 AS Success, N'Invalid action.' AS ErrorMessage;
END
GO

IF OBJECT_ID(N'[proj].[sp_SetUserSecret]') IS NOT NULL DROP PROCEDURE [proj].[sp_SetUserSecret];
GO
CREATE   PROCEDURE proj.sp_SetUserSecret
    @UserId          INT,
    @SecretKey       NVARCHAR(50),
    @SecretValueHash NVARCHAR(500),
    @ModifiedBy      NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM proj.TBL_USER_SECRET WHERE UserId = @UserId AND SecretKey = @SecretKey)
        UPDATE proj.TBL_USER_SECRET
        SET    SecretValueHash = @SecretValueHash,
               ModifiedBy      = @ModifiedBy,
               ModifiedDate    = GETDATE()
        WHERE  UserId = @UserId AND SecretKey = @SecretKey;
    ELSE
        INSERT INTO proj.TBL_USER_SECRET (UserId, SecretKey, SecretValueHash, ModifiedBy, ModifiedDate)
        VALUES (@UserId, @SecretKey, @SecretValueHash, @ModifiedBy, GETDATE());
    SELECT 1 AS Success;
END;
GO

