-- 1. Dedicated clean soft-delete for Menu (no name corruption)
CREATE   PROCEDURE proj.sp_SoftDeleteMenu
    @MenuId INT
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE proj.TBL_MENU
       SET IsActive = 0
     WHERE MenuId = @MenuId;
    SELECT @MenuId AS MenuId;
END;
