IF OBJECT_ID(N'[proj].[sp_UpdateBomQty]') IS NOT NULL DROP PROCEDURE [proj].[sp_UpdateBomQty];
GO

-- sp_UpdateBomQty: update received/PR/PO quantities and recalculate BomStatus on a detail line
CREATE   PROCEDURE proj.sp_UpdateBomQty
    @BomId           INT,
    @BomReceivedQty  DECIMAL(18,4) = NULL,
    @PrCreatedQty    DECIMAL(18,4) = NULL,
    @PoCreatedQty    DECIMAL(18,4) = NULL,
    @ModifiedBy      NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @HeaderId       INT,
            @RequestedQty   DECIMAL(18,4),
            @ReceivedQty    DECIMAL(18,4),
            @PrQty          DECIMAL(18,4),
            @PoQty          DECIMAL(18,4),
            @NewStatus      NVARCHAR(20);

    SELECT
        @HeaderId     = BomHeaderId,
        @RequestedQty = BomRequestedQty,
        @ReceivedQty  = ISNULL(@BomReceivedQty, BomReceivedQty),
        @PrQty        = ISNULL(@PrCreatedQty,   PrCreatedQty),
        @PoQty        = ISNULL(@PoCreatedQty,   PoCreatedQty)
    FROM proj.TBL_BOM_DETAILS
    WHERE BomId = @BomId AND IsActive = 1;

    IF @HeaderId IS NULL
    BEGIN
        RAISERROR('BOM line not found.', 16, 1);
        RETURN;
    END

    -- Derive BomStatus from quantities
    SET @NewStatus =
        CASE
            WHEN @ReceivedQty >= @RequestedQty              THEN 'FullyReceived'
            WHEN @ReceivedQty > 0                           THEN 'PartialReceived'
            WHEN @PoQty       >= @RequestedQty              THEN 'PORaised'
            WHEN @PoQty       > 0                           THEN 'POPartial'
            WHEN @PrQty       >= @RequestedQty              THEN 'PRRaised'
            WHEN @PrQty       > 0                           THEN 'PRPartial'
            ELSE                                                 'Pending'
        END;

    UPDATE proj.TBL_BOM_DETAILS
    SET
        BomReceivedQty = @ReceivedQty,
        PrCreatedQty   = @PrQty,
        PoCreatedQty   = @PoQty,
        BomStatus      = @NewStatus,
        ModifiedBy     = @ModifiedBy,
        ModifiedDate   = GETDATE()
    WHERE BomId = @BomId;

    SELECT @BomId AS BomId, @NewStatus AS BomStatus;
END
GO

