IF OBJECT_ID(N'[proj].[sp_ValidateBudgetPassword]') IS NOT NULL DROP PROCEDURE [proj].[sp_ValidateBudgetPassword];
GO
CREATE PROCEDURE proj.sp_ValidateBudgetPassword
    @UserName     NVARCHAR(100),
    @PasswordHash NVARCHAR(500),
    @ActionCode   NVARCHAR(50)  = N'APPROVE',
    @MenuUrl      NVARCHAR(200) = N'/jobs'
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @UserId INT = (SELECT TOP 1 UserId FROM proj.TBL_USERS WHERE UserName = @UserName);
    IF @UserId IS NULL
    BEGIN
        SELECT CAST(0 AS BIT) AS Success, CAST(NULL AS NVARCHAR(20)) AS Source,
               N'Acting user not found.' AS Message;
        RETURN;
    END

    DECLARE @MenuId INT = (SELECT MenuId   FROM proj.TBL_MENU         WHERE MenuUrl = @MenuUrl);
    DECLARE @ActId  INT = (SELECT ActionId FROM proj.TBL_MENU_ACTIONS WHERE MenuId  = @MenuId AND ActionCode = @ActionCode);

    IF NOT EXISTS (
        SELECT 1 FROM proj.TBL_USER_ROLES ur
        JOIN proj.TBL_ROLE_MENU_ACTION rma
              ON rma.RoleId = ur.RoleId AND rma.MenuId = @MenuId
             AND rma.ActionId = @ActId AND rma.IsAllowed = 1
        WHERE ur.UserId = @UserId)
    BEGIN
        SELECT CAST(0 AS BIT) AS Success, CAST(NULL AS NVARCHAR(20)) AS Source,
               N'You do not have permission to authorise this action.' AS Message;
        RETURN;
    END

    DECLARE @HasUserSecret BIT = CASE WHEN EXISTS (
        SELECT 1 FROM proj.TBL_USER_SECRET
        WHERE UserId = @UserId AND SecretKey = N'BUDGET_PASSWORD'
    ) THEN 1 ELSE 0 END;

    IF @HasUserSecret = 1
    BEGIN
        IF EXISTS (SELECT 1 FROM proj.TBL_USER_SECRET
                   WHERE UserId = @UserId
                     AND SecretKey = N'BUDGET_PASSWORD'
                     AND SecretValueHash = @PasswordHash)
            SELECT CAST(1 AS BIT) AS Success, N'user' AS Source, CAST(NULL AS NVARCHAR(MAX)) AS Message;
        ELSE
            SELECT CAST(0 AS BIT) AS Success, CAST(NULL AS NVARCHAR(20)) AS Source,
                   N'Incorrect budget password.' AS Message;
        RETURN;
    END

    IF EXISTS (SELECT 1 FROM proj.TBL_USER_ROLES ur
               JOIN proj.TBL_ROLE_SECRET rs
                     ON rs.RoleId = ur.RoleId AND rs.SecretKey = N'BUDGET_PASSWORD'
               WHERE ur.UserId = @UserId AND rs.SecretValueHash = @PasswordHash)
        SELECT CAST(1 AS BIT) AS Success, N'role' AS Source, CAST(NULL AS NVARCHAR(MAX)) AS Message;
    ELSE
        SELECT CAST(0 AS BIT) AS Success, CAST(NULL AS NVARCHAR(20)) AS Source,
               N'Incorrect password, and your personal budget password is not set.' AS Message;
END;
GO

IF OBJECT_ID(N'[proj].[sp_ValidateJobForApproval]') IS NOT NULL DROP PROCEDURE [proj].[sp_ValidateJobForApproval];
GO

CREATE   PROCEDURE proj.sp_ValidateJobForApproval
    @JobNumId INT      = NULL,
    @JobId    NVARCHAR(50) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @JobId IS NULL AND @JobNumId IS NOT NULL
        SET @JobId = (SELECT TOP 1 JobId FROM proj.TBL_JOB WHERE JobNumId = @JobNumId);

    DECLARE @errs TABLE (Seq INT IDENTITY(1,1), Requirement NVARCHAR(40), Message NVARCHAR(300));

    IF @JobId IS NULL
    BEGIN
        INSERT INTO @errs (Requirement, Message) VALUES ('Job', 'Job not found.');
        SELECT Seq, Requirement, Message FROM @errs ORDER BY Seq; RETURN;
    END

    -- 1. Finance — Order Value must be entered (> 0)
    IF ISNULL((SELECT OrderValue FROM proj.TBL_JOB_FINANCE WHERE JobId = @JobId), 0) <= 0
        INSERT INTO @errs (Requirement, Message)
        VALUES ('Finance', 'Order Value must be entered (greater than zero) on the Finance tab.');

    -- 2. Engineers — at least one assigned
    IF NOT EXISTS (SELECT 1 FROM proj.TBL_JOB_ENGINEER WHERE JobId = @JobId)
        INSERT INTO @errs (Requirement, Message)
        VALUES ('Engineers', 'At least one engineer must be assigned on the Engineers tab.');

    -- 3. Terms & Conditions — mandatory terms must be filled
    IF NOT EXISTS (
        SELECT 1 FROM proj.TBL_JOB_TERMS
        WHERE JobId = @JobId
          AND LEN(LTRIM(RTRIM(ISNULL(JobPaymentTerms , '')))) > 0
          AND LEN(LTRIM(RTRIM(ISNULL(WarrantyTerms   , '')))) > 0
          AND LEN(LTRIM(RTRIM(ISNULL(JobDeliveryTerms, '')))) > 0)
        INSERT INTO @errs (Requirement, Message)
        VALUES ('Terms', 'Payment, Warranty and Delivery terms must all be filled on the Terms & Conditions tab.');

    -- 4. Documents — every mandatory JOB document type must be attached (e.g. LPO Copy)
    INSERT INTO @errs (Requirement, Message)
    SELECT 'Documents', CONCAT('Document "', dt.DocumentType, '" must be attached on the Documents tab.')
    FROM proj.TBL_DOCUMENT_TYPES dt
    WHERE dt.ModuleName = 'JOB' AND dt.IsMandatory = 1
      AND NOT EXISTS (
          SELECT 1 FROM proj.TBL_DOCUMENTS d
          WHERE d.ReferenceTable = 'JOB' AND d.ReferenceKey = @JobId
            AND d.DocumentType = dt.DocumentType AND ISNULL(d.IsActive, 1) = 1);

    -- 5. Meta — at least one meta entry
    IF NOT EXISTS (SELECT 1 FROM proj.TBL_JOB_META WHERE JobId = @JobId)
        INSERT INTO @errs (Requirement, Message)
        VALUES ('Meta', 'At least one entry must exist on the Meta tab.');

    SELECT Seq, Requirement, Message FROM @errs ORDER BY Seq;
END
GO

IF OBJECT_ID(N'[proj].[sp_ValidatePasswordResetToken]') IS NOT NULL DROP PROCEDURE [proj].[sp_ValidatePasswordResetToken];
GO

CREATE   PROCEDURE proj.sp_ValidatePasswordResetToken
    @TokenHash NVARCHAR(255)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT TOP 1 r.ResetId, r.UserId, u.UserName, u.Email
    FROM   proj.TBL_PASSWORD_RESET r
    JOIN   proj.TBL_USERS          u ON u.UserId = r.UserId
    WHERE  r.TokenHash = @TokenHash
      AND  r.IsUsed    = 0
      AND  r.ExpiresAt > GETDATE()
      AND  u.IsActive  = 1
      AND  u.IsLocked  = 0;
END
GO

IF OBJECT_ID(N'[proj].[sp_ValidateTxnCurrency]') IS NOT NULL DROP PROCEDURE [proj].[sp_ValidateTxnCurrency];
GO

CREATE   PROCEDURE proj.sp_ValidateTxnCurrency
    @CurrencyId    INT,
    @ExchangeRate  DECIMAL(18,6),
    @Context       NVARCHAR(50)   = N'transaction',  -- e.g. 'Invoice','PO','RV','Expense'
    @ResolvedRate  DECIMAL(18,6)  = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    -- Reusable guard for every financial posting path. RAISERROR on failure.
    -- Emits NO result set (uses OUTPUT) so it is safe to EXEC inside other SPs
    -- (e.g. approval post-hooks) without polluting their returned recordsets.
    IF ISNULL(@CurrencyId, 0) <= 0
    BEGIN
        DECLARE @m1 NVARCHAR(200) = @Context + N' currency is required.';
        RAISERROR(@m1, 16, 1); RETURN;
    END

    IF NOT EXISTS (SELECT 1 FROM proj.TBL_CURRENCY WHERE CurrencyId = @CurrencyId AND IsActive = 1)
    BEGIN
        DECLARE @m2 NVARCHAR(200) = @Context + N' currency is invalid or inactive.';
        RAISERROR(@m2, 16, 1); RETURN;
    END

    IF ISNULL(@ExchangeRate, 0) <= 0
    BEGIN
        DECLARE @m3 NVARCHAR(200) =
            @Context + N' exchange rate must be greater than zero (currency conversion would be invalid).';
        RAISERROR(@m3, 16, 1); RETURN;
    END

    SET @ResolvedRate = @ExchangeRate;
END
GO

IF OBJECT_ID(N'[proj].[sp_ValidateUser]') IS NOT NULL DROP PROCEDURE [proj].[sp_ValidateUser];
GO

CREATE PROCEDURE [PROJ].[sp_ValidateUser]
    @Username   NVARCHAR(100),
    @Password   NVARCHAR(255)
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE PROJ.TBL_USERS
    SET LastLoginDate = GETDATE()
    WHERE UserName    = @Username
      AND PasswordHash = @Password
      AND IsActive = 1
      AND IsLocked = 0;

    SELECT
        u.UserId,
        u.UserName  AS Username,
        u.FullName,
        u.Email,
        u.Theme,
        ISNULL(r.RoleName, '') AS RoleName
    FROM PROJ.TBL_USERS u
    LEFT JOIN PROJ.TBL_USER_ROLES ur ON u.UserId = ur.UserId
    LEFT JOIN PROJ.TBL_ROLES      r  ON ur.RoleId = r.RoleId
    WHERE
        u.UserName     = @Username
        AND u.PasswordHash = @Password
        AND u.IsActive = 1
        AND u.IsLocked = 0;
END
GO

IF OBJECT_ID(N'[proj].[sp_VerifyBudgetPassword]') IS NOT NULL DROP PROCEDURE [proj].[sp_VerifyBudgetPassword];
GO

CREATE   PROCEDURE proj.sp_VerifyBudgetPassword
    @UserName     NVARCHAR(100),
    @PasswordHash NVARCHAR(500)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @UserId INT = (SELECT TOP 1 UserId FROM proj.TBL_USERS WHERE UserName = @UserName);
    IF @UserId IS NULL BEGIN SELECT CAST(0 AS BIT) AS IsValid, CAST('nouser' AS NVARCHAR(20)) AS AuthSource; RETURN; END

    DECLARE @HasUserSecret BIT = CASE WHEN EXISTS (
        SELECT 1 FROM proj.TBL_USER_SECRET WHERE UserId = @UserId AND SecretKey = 'BUDGET_PASSWORD') THEN 1 ELSE 0 END;

    IF @HasUserSecret = 1
    BEGIN
        IF EXISTS (SELECT 1 FROM proj.TBL_USER_SECRET
                   WHERE UserId = @UserId AND SecretKey = 'BUDGET_PASSWORD' AND SecretValueHash = @PasswordHash)
            SELECT CAST(1 AS BIT) AS IsValid, CAST('user' AS NVARCHAR(20)) AS AuthSource;
        ELSE
            SELECT CAST(0 AS BIT) AS IsValid, CAST('user' AS NVARCHAR(20)) AS AuthSource;
        RETURN;
    END

    IF EXISTS (SELECT 1 FROM proj.TBL_USER_ROLES ur
               JOIN proj.TBL_ROLE_SECRET rs ON rs.RoleId = ur.RoleId AND rs.SecretKey = 'BUDGET_PASSWORD'
               WHERE ur.UserId = @UserId AND rs.SecretValueHash = @PasswordHash)
        SELECT CAST(1 AS BIT) AS IsValid, CAST('role' AS NVARCHAR(20)) AS AuthSource;
    ELSE
        SELECT CAST(0 AS BIT) AS IsValid, CAST('none' AS NVARCHAR(20)) AS AuthSource;
END
GO

IF OBJECT_ID(N'[proj].[sp_WriteLog]') IS NOT NULL DROP PROCEDURE [proj].[sp_WriteLog];
GO

CREATE PROCEDURE [PROJ].[sp_WriteLog]
    @LogLevel       nvarchar(20)    = 'Error',
    @Controller     nvarchar(100)   = NULL,
    @Action         nvarchar(100)   = NULL,
    @Message        nvarchar(max),
    @StackTrace     nvarchar(max)   = NULL,
    @InnerException nvarchar(max)   = NULL,
    @RequestPath    nvarchar(500)   = NULL,
    @UserId         nvarchar(100)   = NULL,
    @IpAddress      nvarchar(50)    = NULL
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO proj.TBL_APP_LOG
        (LogLevel, Controller, Action, Message, StackTrace, InnerException, RequestPath, UserId, IpAddress, LogDate)
    VALUES
        (@LogLevel, @Controller, @Action, @Message, @StackTrace, @InnerException, @RequestPath, @UserId, @IpAddress, GETDATE())
END
GO

